(window.GIM_TP=window.GIM_TP||{})["Z.LechLecha.0"]={"from":0,"a":[[[],[],[]],[["לֶךָ לְךָ מֵאַרְצְךָ וגו'. רַבִּי אַבָּא פָּתַח וְאָמַר, (ישעיהו מ״ו:י״ב) שִׁמְעוּ אֵלַי אַבִּיִרִי לֵב הָרְחוֹקִים מִצְדָקָה. שִׁמְעוּ אֵלַי אַבִּירֵי לֵב, כַּמָּה תַּקִּיפִין לִבַּיְיהוּ דְּחַיָיבַיָא, דְּחָמָאן שְׁבִילֵי ואָרְחֵי דְאוֹרַיְיתָא ולָא מִסְתַּכְּלָן בְּהוּ, ולִבַּיְיהוּ תַּקִּיפִין דְּלָא מְהַדְּרִין בִּתְיוּבְתָּא לְגַבֵּי מָרֵיהוֹן, וְאִקְרוּן אַבִּירֵי לֵב. הָרְחוֹקִים מִצְּדָקָה דְּמִתְרַחֲקֵי מֵאוֹרַיְיתָא.","רַבִּי חִזְקִיָּה אָמַר דְּמִתְרַחֲקֵי מִקוּדְשָׁא בְּרִיךְ הוּא וְאִנּוּן רְחִיקִין מִנֵּיהּ, וּבְגִין כָּךְ אִקְרוּן אַבִּירֵי לֵב. הָרְחוֹקִים מִצְּדָקָה דְּלָא בָּעָאן לְקָרְבָא לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, בְּגִין כָּךְ אִנּוּן רְחוֹקִים מִצְּדָקָה, כֵּיוָן דְּאִנּוּן רְחוֹקִים מִצְּדָקָה רְחוֹקִים אִנּוּן מִשָּׁלוֹם דְּלֵית לוֹן שָׁלוֹם. דִּכְתִיב, (ישעיהו מ״ח:כ״ב) אֵין שָׁלוֹם אָמַר יְיָ לָרְשָׁעִים. מַאי טַעְמָא בְּגִין דְּאִנּוּן רְחוֹקִים מִצְּדָקָה."],[[0,"לך לך מארצך וגו':","רבי אבא פתח, פתח טעם הכתוב, למה זכה אברהם, שיאמר לו הקב\"ה לך לך וגו' יותר מכל בני דורו. ואמר שמעו אלי אבירי לב הרחוקים מצדקה. \u0003שמעו אלי אבירי לב,\u0004 פירושו, כמה קשים הם הלבבות של הרשעים, שרואים השבילים והאורחות של התורה, היינו פנימיות וחיצוניות של התורה, שבילים פנימיות, ואורחות חיצוניות. (עי' לעיל בראשית א' דף רנ\"א אות ש\"ח) ואינם מסתכלים בהם. ולבבם קשה, שאינם חוזרים בתשובה אל רבונם, וע\"כ נקראים אבירי לב. \u0003הרחוקים מצדקה.\u0004 פירושו שמתרחקים מהתורה, וע\"כ הם רחוקים מצדקה."],[1,"רבי חזקיה אמר וכו':","ר\"ח אמר בביאור הכתוב הנזכר, שהמה מתרחקים מהקב\"ה וע\"כ הם רחוקים ממנו, ומשום זה שמתרחקים מהקב\"ה נקראים \u0003אבירי לב.\u0004 ושיעור הכתוב הוא \u0003הרחוקים מצדקה,\u0004 למה, משום שאינם רוצים להתקרב אל הקב\"ה, שהם אבירי לב, ומשום זה הם רחוקים מצדקה. וכיון שהם רחוקים מצדקה הם רחוקים משלום, שאין להם שלום. שכתוב אין שלום אמר ה' לרשעים. מה הטעם. משום שהם רחוקים מצדקה, ע\"כ אין להם שלום."],[1,"","פירוש. המלכות מבחינת הדין שבה, נקראת צדק, בלא \u0003ה'.\u0004 ובסוד הזווג הגדול דצדיק וצדק. שאז הנוקבא עולית ומלבשת לאמא, היא נקראת צדקה, כלומר שנתהפכת לרחמים, כי קבלה \u0003ה'\u0004 של אמא, להיותה מלבשת עליה. ועל ידי מ\"נ שהצדיקים מעלים להנוקבא בעת שנקראת צדק, גורמים זווג עליון וצדק מתהפך ונעשה צדקה. כלומר, שהדין מתהפך להיות רחמים. וזהו שאומר רבי אבא בביאור הכתוב שמעו אלי אבירי לב וגו'. כי להיותם \u0003אבירי לב\u0004 ואינם מעלים מ\"ן ע\"י הסתכלות בתורה וע\"י תשובה, ע\"כ הם \u0003רחוקים מצדקה\u0004 כי ע\"כ הם נמצאים בדינים דצדק. דהיינו בלי ה', שה\"ס המוחין דאמא, וז\"ש \u0003הרחוקים מצדקה, דמתרחקי מאורייתא,\u0004 משום שמתרחקים מהתורה ואינם מעלים מ\"ן לזווג עליון, ע\"כ הם רחוקים מצדקה, ונמצאים בדינים דצדק. ורבי חזקיה אינו חולק על רבי אבא, אלא שמבאר יותר ממנו, ואומר \u0003דמתרחקי מקב\"ה ואינון רחיקין מניה,\u0004 דהיינו שאין להם אהבה אל הקב\"ה, \u0003בגין כך אינון רחוקים מצדקה,\u0004 הם רחוקים מלהפך הצדק לצדקה, דהיינו את הדין לרחמים, כי אינם מעלים מ\"ן לזווג. \u0003כיון דאינון רחוקים מצדק רחוקים אינון משלום.\u0004 ומתוך שאינם מעלים מ\"ן להפך הצדק לצדקה, אין להם שלום. כלומר, שאינם גורמים זווג עליון, המכונה \u0003שלום.\u0004 וע\"כ השלום אינו מאיר עליהם."]],[[0,"","רַבִּי אַבָּא פָּתַח וְאָמַר (ישעיה מו) שִׁמְעוּ אֵלַי אַבִּירֵי לֵב הָרְחוֹקִים מִצְּדָקָה. שִׁמְעוּ אֵלַי אַבִּירֵי לֵב - כַּמָּה חֲזָקִים לִבּוֹתֵיהֶם שֶׁל הָרְשָׁעִים, שֶׁרוֹאִים אֶת שְׁבִילֵי וְדַרְכֵי הַתּוֹרָה וְלֹא מִסְתַּכְּלִים בָּהֶם, וְלִבּוֹתֵיהֶם חֲזָקִים שֶׁאֵינָם חוֹזְרִם בִּתְשׁוּבָה לְרִבּוֹנָם, וְנִקְרָאִים אַבִּירֵי לֵב. הָרְחוֹקִים מִצְּדָקָה - שֶׁמִּתְרַחֲקִים מִן הַתּוֹרָה."],[1,"","רַבִּי חִזְקִיָּה אָמַר, שֶׁמִּתְרַחֲקִים מִן הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהֵם רְחוֹקִים מִמֶּנּוּ, וּמִשּׁוּם כָּךְ נִקְרְאוּ אַבִּירֵי לֵב. הָרְחוֹקִים מִצְּדָקָה - שֶׁאֵינָם רוֹצִים לִקְרַב אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא, מִשּׁוּם כָּךְ הֵם רְחוֹקִים מִצְּדָקָה. כֵּיוָן שֶׁהֵם רְחוֹקִים מִצְּדָקָה, רְחוֹקִים הֵם מִשָּׁלוֹם, שֶׁאֵין לָהֶם שָׁלוֹם, שֶׁכָּתוּב (ישעיה מח) אֵין שָׁלוֹם אָמַר ה' לָרְשָׁעִים. מָה הַטַּעַם? מִשּׁוּם שֶׁהֵם רְחוֹקִים מִצְּדָקָה."]]],[["תָּא חֲזֵי, אַבְרָהָם בָּעֵי לְקָרְבָא לְקוּדְשָׁא בְּרִיךְ הוּא וְאִתְקָרַב. הֲדָא הוּא דִכְתִיב, (תהילים מ״ה:ח׳) אָהַבְתָּ צֶדֶק וַתִּשְׂנָא רֶשַׁע. בְּגִין דְאָהַב צֶדֶק וְשָׂנָא רֶשַׁע אִתְקָרַב לִצְדָקָה, וְעַל דָּא כְּתִיב, (ישעיהו מ״א:ח׳) אַבְרָהָם אוֹהֲבִי. מַאי טַעְמָא אוֹהֲבִי, בְּגִין דִּכְתִיב אָהַבְתָּ צֶדֶק. רְחִימוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא דְּרָחִים לֵיהּ אַבְרָהָם מִכָּל בְּנֵי דָרִיהּ דְּהֲווּ אַבִּירֵי לֵב וְאִנּוּן רְחוֹקִים מִצְּדָקָה כְּמָה דְּאִתְּמָר.","רַבִּי יוֹסֵי פָּתַח (תהילים פ״ד:ב׳) מַה יְּדִידוֹת מִשְׁכְּנוֹתֶיךָ יְיָ צְבָאוֹת. כַּמָּה אִית לוֹן לִבְנִי נָשָׁא לְאִסְתַּכָּלָא בְּפוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא. דְּהָא כָּל בְּנֵי נָשָׁא לָא יָדְעֵי וְלָא מִסְתַּכְּלֵי עַל מַה קָּאִים עָלְמָא. וְאִנּוּן עַל מַה קָּיְימִין. דְּכַד בְּרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא עֲבַד שְׁמַיָא מֵאֵשׁ וּמִמַּיִם מִתְעָרְבִין כְּחֲדָא וְלָא הֲווּ גַּלְדֵי. וּלְבָתַר אַגְלִידוּ וְקָיְימוּ בְּרוּחָא עִלָּאָה וּמִתַּמָּן שָׁתִיל עָלְמָא, לְקָיְימָא עַל סָמְכִין, וְאִנּוּן סָמְכִין לָא קָיְימִין אֶלָּא בְּהַהוּא רוּחָא, וּבְשַׁעֲתָא דְּהַהוּא רוּחָא אִסְתַּלַּק כֻּלְהוּ מְרַפְפִין וְזָעִין וְעָלְמָא אִרְתַּת הֲדָא הוּא דִכְתִיב, (איוב ט׳:ו׳) הַמַּרְגִּיז אֶרֶץ מִמְקוֹמָהּ וְעַמּוּדֶיהָ יִתְפַּלָּצוּן. וְכֹלָּא קָאִים עַל אוֹרַיְיתָא, דְּכַד יִשְׂרָאֵל מִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא מִתְקַיֵּים עָלְמָא וְאִנּוּן קָיְימִין וְסָמְכִין קָיְימִין בְּאַתְרַיְיהוּ בְּקִיּוּמָא שְׁלִים.","תָּא חֲזֵי, בְּשַׁעֲתָא דְאִתְעַר פַּלְגוּת לֵילְיָא וְקוּדְשָׁא בְּרִיךְ הוּא עָאל לְגִנְתָא דְעֵדֶן לְאִשְׁתַּעְשְׁעָא עִם צַדִּיקַיָא, כֻּלְהוּ אִילָנִין דִּבְגִנְתָא דְעֵדֶן מְזַמְּרָן וּמְשַׁבְּחָן קַמֵּיהּ. דִּכְתִיב, (דברי הימים א ט״ז:ל״ג) אָז יְרַנְּנוּ עֲצֵי הַיָּעַר מִלִּפְנֵי יְיָ וְגו'.","וְכָרוֹזָא קָרֵי בְחָיִל וְאָמַר לְכוֹן אָמְרִין קַדִּישִׁין עֶלְיוֹנִין, מָאן מִנְכוֹן דְּעָיִיל רוּחָא בְּאוּדְנוֹי לְמִשְׁמָע, וְעֵינוֹי פְּקִחִין לְמֶחֱמֵי. וְלִבֵּיהּ פָּתוּחַ לְמִנְדַע, בְּשַׁעֲתָא דְּרוּחָא דְכָל רוּחִין אָרִים בְּסִימוּ דְנִשְׁמָתָא, וּמִתַּמָּן נָפִיק קָלָא דְּקָלַיָא, חֵיְלִין אִתְבַּדַּר לְאַרְבַּע סִטְרֵי עָלְמָא.","א חַד סָלִיק לִסְטַר חָד. ב חַד נָחִית לְהַהוּא סְטַר. ג (תיקונים עג, לעיל לב ב) חַד עָיִיל בֵּין תְּרֵין. ד תְּרֵין מִתְעָרִין מִתְעַטְּרָן בִּתְלַת. ה תְּלַת עָיְילֵי בְּחַד. ו חַד אַפִּיק גְּוָונִין. ז שִׁית מִנְהוֹן לִסְטַר חָד, וְשִׁית מִנְהוֹן נָחֲתֵי לְהַהוּא סְטַר. ח שִׁית עָיְילֵי בִּתְרֵיסַר. ט תְּרֵיסַר מִתְעָרִין בְּעֶשְׂרִין וּתְרֵין. י שִׁית כְּלִילָן בַּעֲשָׂרָה. יא עֲשָׂרָה קָאִים בְּחַד."],[[0,"ת\"ח אברהם וכו':","בוא וראה, אברהם רצה לקרב עצמו להקב\"ה, ונתקרב. וז\"ש אהבת צדק ותשנא רשע, משום שאהב צדק ושנא רשע ע\"כ נתקרב לצדקה, כלומר, משום שאהב צדק וגו' העלה מ\"ן לזווג עליון, והצדק נעשה לצדקה בעדו כנ\"ל בדיבור הסמוך. ועל כן כתוב אברהם אוהבי. מהו הטעם הוא \u0003אוהבי\u0004 משום שכתוב בו \u0003אהבת צדק.\u0004 הוא אהבת הקב\"ה, שאהב אותו אברהם, יותר מכל בני דורו, שהם היו אבירי לב, והם רחוקים מצדקה. כמו שנתבאר."],[1,"רבי יוסי פתח וכו':","ר\"י פתח. מה ידידות וגו' כמה יש להם לבני אדם להסתכל בעבודת הקב\"ה. שהרי כל בני אדם אינם יודעים ואינם מסתכלים על מה העולם עומד. והם עצמם על מה עומדים. ואלו ב' דברים מתבארים בהמאמר שלפנינו. על מה קאים עלמא מתבאר עד אות ה' ועל מה בני אדם עומדים מתבאר מאות ה' עד אות י', כי כאשר ברא הקב\"ה את העולם, עשה את השמים מאש ומים ונתערבו יחד, ולא היו נקפאים. ואחר כך נקפאו ועמדו ברוח עליון."],[1,"","פירוש. כי נודע בסדר יציאת המוחין שמתחילה, יוצאים ב' הקוין ימין ושמאל. ובסוד ב' נקודות חולם ושורק, המכונים מים ואש. והם במחלוקת זה עם זה, שפירושו, שכל אחד נכנס בגבול חברו ורוצה להכניעו תחת בחינתו. כמו ב' דברים לחים המתערבים זה עם זה. עד שמתגלה קומת חסדים היוצאת על מסך דת\"ת, שה\"ס קו הג', והוא מכריע ביניהם, שכל אחד יאיר לפי דרכו ולא יתערבו עוד זה בזה. וזהו מכונה, שב' הקוין שהיו לחים ונתערבו זה בזה, נקפאו עתה ע\"י קו האמצעי שהוא ת\"ת. ולא יתערבו עוד זה בזה. (כמ\"ש כל זה באורך לעיל בראשית א' דף מ\"ז אות ל\"ד ד\"ה לפיכך. ע\"ש כל ההמשך)."],[1,"","וזה אמרו, \u0003דכד ברא קב\"ה\u0004 שהוא בינה, \u0003עלמא,\u0004 שהיא הנוקבא, \u0003עבד שמיא,\u0004 שהוא ז\"א \u0003מאש\u0004 מקו שמאל, \u0003וממים\u0004 מקו ימין \u0003מתערבין כחדא ולא הוו גלדי.\u0004 שהיו מתערבים יחד ואינם נקפאים, כלומר, שהיו במחלוקת זה עם זה וכל אחד מתערב בגבול חברו להכניעו תחתיו. כטבע הנוזלים המתערבים זה בזה. \u0003ולבתר,\u0004 אחר שיצא קו האמצעי, \u0003אגלידו וקיימו ברוחא עלאה,\u0004 נקפאו ועמדו ב' הקוין ע\"י קו אמצעי שהוא ת\"ת הנקרא רוח. דהיינו שנעשה כמו דברים מוצקים, שהאחד לא יכנוס עוד תוך הגבול של חברו."],[1,"ומתמן שתיל עלמא וכו':","ומשם מהשמים שהם ז\"א, שתל העולם שהיא הנוקבא, שיעמוד על אדנים שהם ג' קוי הנוקבא, ואלו האדנים אינם עומדים אלא באותו הרוח שהוא קו האמצעי שבהם, ובשעה שרוח ההוא מסתלק, כולם מרופפים ומזדעזעים, והעולם רותת, וז\"ש המרגיז ארץ ממקומה ועמודיה יתפלצון. כי כנ\"ל בהקוין דז\"א שאומר \u0003דאגלידו וקיימו ברוחא עלאה,\u0004 כן בהקוין דנוקבא הנמשכים מז\"א \u0003לא קיימין אלא בההוא רוחא.\u0004 כי זולת קו אמצעי אין קיום כלל להארת ב' הקוין (כנ\"ל דף ב' ד\"ה פירוש ע\"ש)."],[1,"וכלא קאים על אורייתא וכו':","והכל עומד על התורה, כי כשישראל עוסקים בתורה שמעלים מ\"ן לזו\"ן וממשיכים את קו האמצעי, כי התורה ה\"ס קו אמצעי, מתקיים העולם, ואלו העמודים והאדנים, שהם ג' קוי דז\"א הנקראים עמודים, וג' קוין דנוקבא הנקראים אדנים, נמצאים במקומם בקיום שלם. ואז נאמר על הנוקבא, מה ידידות משכנותיך וגו'. כי משכן ה\"ס הנוקבא. והנה נתבאר שהעולם עומד על רוחא דהיינו על קו האמצעי. וז\"ש \u0003דכד ישראל משתדלין באורייתא מתקיים עלמא.\u0004 ומכאן ולהלן מבאר, איך גם בני אדם עומדים ומתקיימים רק על קו אמצעי."],[2,"ת\"ח בשעתא דאתער וכו':","בוא וראה בשעה שנתעוררת חצות לילה, והקב\"ה נכנס בגן עדן להשתעשע עם הצדיקים כל האילנות שבגן עדן מזמרים ומשבחים לפניו, שנאמר אז ירננו כל עצי יער מלפני ה' כי בא וגו'. פירוש. הלילה ה\"ס הנוקבא מבחינת שליטתה עצמה, שעקרה הוא הארת קו השמאל, מסוד הארת החכמה הנמשכת מנקודת השורק שבאמא. ונודע שאין החכמה מאירה אלא מחזה ולמטה, כי מחזה ולמעלה של כל פרצוף, שולטת המנעולא ואין הארת החכמה יכולה להתגלות שם (כנ\"ל בהקדמת הזהר דף נ\"ה אות מ\"א ד\"ה וטעם ע\"ש) וז\"ס התחלקות הלילה לב' חצאים, כי נקודת החצות לילה ה\"ס נקודת החזה. וחצות לילה הראשונה ה\"ס מחזה ומעלה של הנוקבא, ומשום ששם שולטת המנעולא ע\"כ היא דינים. וחצות לילה השניה ה\"ס מחזה ולמטה של הנוקבא, ששם שולטת מלכות הממותקת בבינה, שה\"ס מפתחא, (וענין מפתחא ומנעולא עי' לעיל בהקדמה הזהר דף נ\"ה אות מ\"א ואילך) וע\"כ מתגלה שם הארת החכמה שבהנוקבא שז\"ס ותקם בעוד לילה. גם מבחינה זו נקראת הנוקבא גן עדן. כי מחזה ולמטה, שאין שם בחינת עצמה שה\"ס מלכות דמדת הדין, ע\"כ כולה נמתקת ונעשית כמו אמא הנקראת \u0003עדן.\u0004 בסוד חזרתה לחכמה. וע\"כ נקראת \u0003גן עדן.\u0004"],[2,"","וז\"ש \u0003בשעתא דאתער פלגות ליליא\u0004 דהיינו שהנוקבא נתעוררה לקבל המתקת הבינה שתאיר בהמחזה ולמטה שבה, שה\"ס גן עדן, \u0003וקב\"ה עאל לגנתא דעדן לאשתעשעא עם צדיקייא,\u0004 והקב\"ה נכנס לג\"ע להשתעשע עם הצדיקים, כלומר שהצדיקים מעלים מ\"ן וממשיכים שם הארת קו אמצעי, שה\"ס הקב\"ה המאיר בגן עדן. \u0003כלהו אילנין דבג\"ע מזמרן ומשבחן קמיה דכתיב אז ירננו עצי יער וגו':\u0004 עצי היער הם אילני סרק שאינם עושים פירות. ומטרם ביאת הקב\"ה נבחנים ספירות הנוקבא כמו עצי היער, שאין בהם פירות. ואחר שהארת הקב\"ה נכנסת שם ע\"י הצדיקים אז ירננו עצי היער מלפני הויה כי בא וגו', והם עושים פירות."],[3,"וכרוזא קרי בחיל וכו':","וכרוז יוצא וקורא בכח ואומר, לכם גבורים הקדושים, למי שבכם, שהכניס רוח באזניו לשמוע, ועיניו פקוחות לראות, ולבו פתוח לדעת. ומכח כרוז הזה מתעוררים הצדיקים לקום משנתם, ולעסוק בתורה, כמו שמסיים להלן באות ט' וממשיכים את קו האמצעי."],[3,"","פירוש. אזנים ה\"ס בינה, והאור שלהם נקרא שמיעה. עינים ה\"ס חכמה, והאור שלהם נקרא ראיה. ובלילה העינים סתומות, כי מפני הדינים אינן יכולות להאיר. ובחצות לילה כשמגיע הארת השמאל מאמא, שה\"ס הארת החכמה מנקודת השורק שבאמא, אע\"פ שכבר יש שם כח הראיה, מכל מקום עדיין אי אפשר לפקוח את העינים, כי עוד חסר אור החסדים ואין החכמה מאירה בלי חסדים. ואז הצדיקים מתעוררים לקום ולעסוק בתורה ולהעלות מ\"ן לזו\"ן, ואז עולה ז\"א גם הוא למ\"ן לב' הקוין הנמשכים שם מב' הנקודות חולם שורק שבבינה, וקומת חסדים נמשכת על מסך דז\"א המכריע בין ב' הקוין, והם נכללים זה בזה והחכמה שבשמאל מתלבשת בהחסדים שבימין ויכולה להאיר, ואז נפקחות העינים, וז\"ש \u0003מאן מנכון דעייל רוחא באודנוי,\u0004 כי רוחא ה\"ס קו אמצעי שהוא ז\"א, אשר הצדיקים בעסק התורה הם מעלים מ\"ן ומכניסים הרוח, שהוא ז\"א, אל האזנים שהם ב' קוין שבבינה, והחכמה שבשמאל מתלבשת שם על ידו בהחסדים שבימין כנ\"ל, ואז \u0003ועינוי פקחין למחמי,\u0004 כי העינים שה\"ס החכמה נפקחו לראות, כי אחר שנתלבשו בחסדים הן יכולות להאיר. וקו האמצעי נקרא דעת, ואז נעשו ג' הקוין הללו לחכמה בינה דעת בבינה, ומשם נמשכים לחב\"ד דזו\"ן, ומשם לחב\"ד דנשמות הצדיקים, שכל אלו המוחין יצאו על ידי עסק תורתם. ודעת הזה שה\"ס קו המכריע בחו\"ב של ראש, מתהפך ומאיר מלמעלה למטה אל הגוף. וז\"ש \u0003ולביה פתוח למנדע,\u0004 כי דעת שבראש מתפשט למטה וממלא את הלב וכל הגוף. וז\"ס הכרוז שמגיע בחצות לילה, דהיינו בעת התחלת הארת קו השמאל מנקודת השורק, אל הצדיקים שיעלו מ\"ן להמשכת קו אמצעי. ומ\"ש \u0003קרא בחיל,\u0004 היינו להיותו בסתימת הדינין של נקודת השורק וע\"כ נבחן אז, שיוצא בכח גדול, וקורא אל הצדיקים לתקנו. ולפנינו מבאר סדר המשכת ג' הקוין הנ\"ל, מבינה לז\"א, ומז\"א לנוקבא, ומנוקבא לנשמות הצדיקים."],[3,"בשעתא דרוחא דכל רוחין:","בשעה שרוח השורשי לכל הרוחות, מרים מתיקות הנשמה, ומשם יוצא קול השרשי לכל הקולות, הכחות מתפזרים לארבע רוחות העולם. פירוש. ז\"א העולה ומכריע בין ב' הקוין שבבינה, כנ\"ל בדיבור הסמוך, נקרא \u0003רוחא דכל רוחין,\u0004 להיותו קו אמצעי השורשי, שממנו נמשכים קוין אמצעים לכל המדרגות. נשמה היינו בינה, כי אור הבינה נקרא נשמה. ואחר שהרוח, שהוא ז\"א עלה לאודנין שה\"ס בינה והכריע בין ב' הקוין שבה, נעשה \u0003הרוח,\u0004 לבחינת \u0003קול\u0004 הנשמע, שפירושו שמקודם הכרעת הרוח לא היו נשמעים בבינה, המכונה אזנים, שום אורות, והרוח, פעל בהם השמיעה, כי על ידו נשלמו ומאירים לחוץ. וז\"ש \u0003בשעתא דרוחא דכל רוחין ארים בסימו דנשמתא,\u0004 בשעה שז\"א עלה לבינה, והרים שם המתיקות של אורות הבינה הנקראים נשמה, דהיינו שגילה שם ג' קוין חב\"ד, כנ\"ל בדיבור הסמוך, \u0003ומתמן נפיק קלא דקליא,\u0004 אחר שהרוח גילה ג' הקוין ונעשה קול כנ\"ל, הוא יוצא משם ונעשה שורש לכל הקולות, כי יוצא ומתפשט למטה. וז\"ש \u0003חילין אתבדר לארבע סטרי עלמא,\u0004 כחותיו מתפשטים ומתפזרים לד' רוחות העולם. דהיינו לז\"א ונוקבא שמתחת הבינה. כי דרום צפון מזרח ה\"ס ז\"א. ומערב ה\"ס הנוקבא."],[4,"חד סליק לסטרחד וכו': אחד עולה לצד אחד,","דהיינו לצד ימין דז\"א, שה\"ס דרום, הנמשך מנקודת החולם דבינה. \u0003אחד יורד לצד ההוא,\u0004 הב' שהוא לצד שמאל דז\"א, שה\"ס צפון, הנמשך מנקודת השורק שבבינה. \u0003אחד נכנס בין שנים.\u0004 דהיינו קו האמצעי דז\"א, שה\"ס מזרח, הנמשך מנקודת החירק שבבינה, דהיינו מז\"א, שיכריע בב' הקוין שבבינה. ואלו ג' הצדדים, דרום צפון ומזרח, ה\"ס חסד גבורה תפארת שבז\"א. ומה שבהארת הימין אומר \u0003חד סליק,\u0004 דהיינו שהארתו עולה ממטה למעלה, ובהארת השמאל אומר \u0003חד נחית,\u0004 דהיינו שהארתו יורדת ממעלה למטה. היינו משום שמדבר בסדר יציאתם, מטרם שיוצא קו האמצעי, שמתחילה יוצא קו הימין בלבדו בו\"ק בלי ראש. מסוד מ\"י. ואח\"כ קו שמאל, מסוד אל\"ה החוזרים למ\"י ונשלם השם אלקים בסתימו. ואז נמצא שהימין מאיר ממטה למעלה כטבע הארת ו\"ק. והשמאל מאיר ממעלה למטה כבחינת ג\"ר, אלא שסתומים מטעם חסרון חסדים. אבל אחר יציאת קו האמצעי ושלשתם נכללים זה בזה. אז מתהפך סדר הארתם, \u0003ודסליק נחית ודנחית סליק,\u0004 כמ\"ש לעיל (בראשית א' דף ש\"ב אות שפ\"ו ועי' בהסולם שם) שהימין מאיר ממעלה למטה והשמאל רק ממטה למעלה כמ\"ש שם. ומה שאינו חושב את החב\"ד דז\"א, הוא משום שחב\"ד דז\"א אינם חב\"ד ממש, רק חג\"ת שנעשו לחב\"ד, כנודע."],[4,"תרין מתעטרן בתלת וכו':","השנים מתעטרים ומאירים, שנעשו שלשה, חג\"ת, על ידי קו האמצעי שהכריע ביניהם, כנ\"ל ע\"כ \u0003שלושה נכנסים באחד,\u0004 כי קו האמצעי, שה\"ס ת\"ת, מקבל ומתפשט בעצמו בלבדו לג' קוין אחרים, שה\"ס נה\"י, פירוש. כי כל השיעור שהתחתון גורם בהארת העליון, זוכה בו התחתון, להיותו הגורם לזה. ולפיכך, כיון שז\"א עלה והכריע בבינה ונעשה שם לקו אמצעי, זכה ז\"א בעצמו לג' הקוין שיצאו מכחו בבינה, ונתפשט בעצמו לג' קוין חג\"ת, כנ\"ל בדיבור הסמוך. וכן ת\"ת דז\"א, שהוא קו האמצעי המכריע בין ב' הקוין שהם חסד וגבורה דז\"א, זכה בעצמו בכל ג' הקוין, ונתפשט הת\"ת לג' הקוין נצח הוד יסוד. וז\"ש \u0003תרין מתעטרן בתלת, תלת עיילי בחד,\u0004 לפי שהשנים, שהם חסד וגבורה דז\"א נעשו ג' קוין ע\"י הת\"ת, ע\"כ כל השלשה נכנסו בהאחד שהוא ת\"ת ונתפשט בעצמו לג' קוין אחרים שהם נה\"י. ויצאו בז\"א ששה ספירות חג\"ת נה\"י."],[4,"חד אפיק גוונין וכו':","האחד הנזכר, שהוא המכריע, דהיינו ת\"ת דז\"א, הוציא גוונין. דהיינו שהאציל ספירות הנוקבא הנקראות גוונים. ששה מהם, שהם חג\"ת נה\"י לצד אחד, דהיינו לימין. וששה מהם שהם חג\"ת נה\"י, לצד האחר, דהיינו לשמאל. ונמצא שהששה שהם חג\"ת נה\"י, נכנסו בשתים עשרה ספירות, כלומר, שששה ספירות של ז\"א נתפשטו ונעשו בהנוקבא י\"ב ספירות, ששה לימין שבה וששה לשמאל שבה. וכל אלו י\"ב ספירות הן מהחזה שלה ולמעלה. והטעם שהן מתכפלות, הוא כי הנוקבא מהחזה שלה ולמעלה, היא כלולה מב' יסודות הנמשכות מב' נקודות, הנקראות מפתחא ומנעולא. (עי' לעיל בהק' הזהר דף קכ\"ג אות קכ\"ב ד\"ה ב') וע\"כ יוצאים בה שם ב' קומות של חג\"ת נה\"י, אחת מבחינת מפתחא, וקומה זו מתפשטת בהארת חכמה. וקומה שניה של חג\"ת נה\"י היא מבחינת מנעולא, שקומה הזו אין בה הארת חכמה, אלא חסדים מכוסים. ולפיכך \u0003שית עיילי בתריסר,\u0004 שששה דז\"א נעשו אצלה תריסר, דהיינו ב' קומות של חג\"ת נה\"י."],[4,"תריסר מתערין בעשרין ותרין וכו':","השתי עשרה ספירות שמחזה ולמעלה מתפשטים מחזה של הנוקבא ולמטה, ונעשות עשרים ושתים ספירות כי \u0003שית\u0004 דז\"א, אינן נעשות כאן י\"ב, אלא \u0003כלילן בעשרה,\u0004 והוא מטעם כי \u0003עשרה קאים בחד.\u0004 פירוש כי מחזה ולמטה של הנוקבא אין לה זווג, מחמת שחסר שם בחינת יסוד דמנעולא, שה\"ס פני אדם, (כנ\"ל בראשית א' דף פ\"ה ד\"ה ביאור) ולפיכך נבחן שרק ב\"פ חג\"ת נ\"ה נמשכות למטה, ולא היסודות. כי היסוד דמפתחא, אע\"פ שהוא נמשך מחזה ולמטה, מ\"מ כיון שאין לו שם בחינת יסוד דמנעולא להכלל בו, אינו ראוי לזווג. וע\"כ אינו נחשב לספירה, ואין לה מחזה ולמטה רק עשרה ספירות. וז\"ש \u0003שית כלילן בעשרה.\u0004 לכן שית דז\"א כלולים מחזה ולמטה רק בעשרה ספירות, שהם ב' פעמים חג\"ת נ\"ה, ולא בי\"ב ספירות, משום כי \u0003עשרה קאים בחד.\u0004 משום שאלו עשרה ספירות עומדות רק ביסוד אחד, דהיינו דמפתחא לבד, ואינו יכול להכלל במנעולא וע\"כ אינו ראוי לזווג וכמו שאינו, הוא דומה, וע\"כ חסר כאן ב' יסודות, ויש רק ב\"פ חג\"ת נ\"ה בלבד, שהם עשרה ספירות, אמנם כל הארת החכמה מתגלה רק באלו עשרה הספירות שמחזה ולמטה, כנ\"ל בסמוך. אלא שהזווג נעשה מחזה ולמעלה וקומת הזווג נמשך בעשרה הספירות שמחזה ולמטה. ומשם מקבלות נשמות הצדיקים."]],[[0,"","בֹּא רְאֵה, אַבְרָהָם רָצָה לִקְרַב אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא וְהִתְקָרֵב. זֶהוּ שֶׁכָּתוּב (תהלים מה) אָהַבְתָּ צֶּדֶק וַתִּשְׂנָא רֶשַׁע. מִשּׁוּם שֶׁאָהַב צֶדֶק וְשָׂנָא רֶשַׁע, הִתְקָרֵב לִצְדָקָה, וְעַל זֶה כָּתוּב (ישעיה מא) אַבְרָהָם אֹהֲבִי. מָה הַטַּעַם אֹהֲבִי? מִשּׁוּם שֶׁכָּתוּב אָהַבְתָּ צֶּדֶק. הָאַהֲבָה שֶׁאָהַב אַבְרָהָם אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא מִכָּל בְּנֵי דוֹרוֹ, שֶׁהָיוּ אַבִּירֵי לֵב, וְהֵם רְחוֹקִים מִצְּדָקָה, כְּמוֹ שֶׁנִּתְבָּאֵר."],[1,"","רַבִּי יוֹסֵי פָּתַח, (תהלים פד) מַה יְּדִידוֹת מִשְׁכְּנוֹתֶיךְ ה' צְבָאוֹת. כַּמָּה יֵשׁ לִבְנֵי אָדָם לְהִסְתַּכֵּל בַּעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהֲרֵי כָּל בְּנֵי הָאָדָם לֹא יוֹדְעִים וְלֹא מִסְתַּכְּלִים עַל מָה עוֹמֵד הָעוֹלָם וְעַל מָה הֵם קַיָּמִים. שֶׁכַּאֲשֶׁר בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, עָשָׂה שָׁמַיִם מֵאֵשׁ וּמִמַּיִם מְעֹרָבִים יַחַד, וְלֹא הָיוּ קוֹפְאִים, וְאַחַר כָּךְ קָפְאוּ וְעָמְדוּ בְּרוּחַ עֶלְיוֹנָה, מִשָּׁם שָׁתַל אֶת הָעוֹלָם לַעֲמֹד עַל עמּוּדִים, וְאוֹתָם הַתּוֹמְכִים לֹא עוֹמְדִים אֶלָּא בָּרוּחַ הַהִיא. וּבְשָׁעָה שְׁאוֹתָהּ הָרוּחַ עוֹלָה, כֻּלָּם מתְרוֹפְפִים וְזָעִים וְהָעוֹלָם רוֹתֵת. הוּ שֶׁכָּתוּב (איוב ט) הַמַּרְגִּיז אֶרֶץ ממְּקוֹמָהּ וְעַמּוּדֶיהָ יִתְפַּלָּצוּן. וְהַכֹּל עוֹמֵד עַל הַתּוֹרָה. שֶׁכַּאֲשֶׁר יִשְׂרָאֵל משְׁתַּדְּלִים בַּתּוֹרָה, מִתְקַיֵּם הָעוֹלָם, אוֹתָם הָעַמּוּדִים הַתּוֹמְכִים קַיָּמִים בִּמְקוֹמָם בְּקִיּוּם שָׁלֵם."],[2,"","בֹּא רְאֵה, בְּשָׁעָה שֶׁמִּתְעוֹרֵר חֲצוֹת הַלַּיְלָה וְהַקָּדוֹשׁ בָּרוּךְ הוּא נִכְנָס לְגַן העֵדֶן לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים, כָּל האִילָנוֹת שֶׁל גַּן הָעֵדֶן מְזַמְּרִים מְשַׁבְּחִים לְפָנָיו, שֶׁכָּתוּב (דברי הימים א טז) אָז יְרַנְּנוּ עֲצֵי הַיַּעַר מִלִּפְנֵי ה' וְגוֹ'."],[3,"","הַכָּרוֹז קוֹרֵא בְחַיִל וְאוֹמֵר: לָכֶם אוֹמְרִים קְדוֹשִׁים עֶלְיוֹנִים, מִי מִכֶּם שְׁנִּכְנְסָה רוּחַ לְאָזְנָיו לִשְׁמֹעַ, וְעֵינָיו פּקוּחוֹת לִרְאוֹת, וְלִבּוֹ פָּתוּחַ לָדַעַת, בּשָׁעָה שֶׁהָרוּחַ שֶׁל כָּל הָרוּחוֹת מרִימָה אֶת הִתְבַּשְּׂמוּת הַנְּשָׁמָה, מִשָּׁם יוֹצֵא הַקּוֹל שֶׁל הַקּוֹלוֹת, הַצְּבָאוֹת הִתְפַּזְּרוּ לְאַרְבָּעָה רוּחוֹת הָעוֹלָם."],[4,"","א, אֶחָד עוֹלֶה לְצַד אֶחָד. ב. אֶחָד וֹרֵד לְאוֹתוֹ הַצַּד. ג. אֶחָד נִכְנָס בֵּין שְׁנַיִם. ד. שְׁנַיִם מִתְעוֹרְרִים (מתעטרים) בּשְׁלֹשָׁה. ה. שְׁלֹשָׁה נִכְנָסִים בְּאֶחָד: אֶחָד מוֹצִיא גְוָנִים. ז. שִׁשָּׁה מֵהֶם לצַד אֶחָד, וְשִׁשָּׁה מֵהֶם יוֹרְדִים לאוֹתוֹ הַצַּד. ח. שִׁשָּׁה נִכְנָסִים בּשְׁנֵים עָשָׂר. ט. שְׁנֵים עָשָׂר מתְעוֹרְרִים בְּעֶשְׂרִים וּשְׁנַיִם. י. שִׁשָּׁה כּלוּלִים בַּעֲשָׂרָה. יא. עֲשָׂרָה עוֹמְדִים בְּאֶחָד."]]],[["וַוי לְאִנּוּן דְּנַיְימֵי שֵׁנְתָא בְּחוֹרֵיהוֹן, לָא יָדְעֵי וְלָא מִסְתַּכְּלָאן אֵיךְ יְקוּמוּן בְּדִינָא דְּחוּשְׁבַּן אִתְפַּקַד, כַּד אִסְתָּאַב גּוּפָא, וְנִשְׁמָתָא שַׁטְיָא עַל אַנְפֵּי דְּאֲוִירָא דְּטִיהֲרָא, וְסָלְקָא וְנַחֲתָא, וְתַרְעִין לָא מִתְפַּתְּחָן, מִתְגַּלְגְּלָן כְּאַבְנִין בְּגוֹ קוּסְפִיתָא. וַוי לוֹן מַאן יִתְבַּע לוֹן, דְּלָא יְקוּמוּן בְּעִדּוּנָא דָא בְּגוֹ דוּכְתֵּי דְּעִנּוּגֵי דְצַדִּיקַיָא, אִתְפַּקְדּוּן דּוּכְתַּיְיהוּ. אִתְמַסְּרוּן בִּידָא דְדוּמָה, נַחֲתֵי וְלָא סַלְקֵי. עֲלַיְיהוּ כְּתִיב, (איוב ז׳:ט׳) כָּלָה עָנָן וַיֵּלַךְ כֵּן יוֹרֵד שְׁאוֹל לא יַעֲלֶה.","בְּהַהִיא שַׁעֲתָא אִתְעַר שַׁלְהוֹבָא חַד מִסְּטַר צָפוֹן וּבָטַשׁ בְּאַרְבַּע סִטְרֵי עָלְמָא וְנָחִית וּמָטֵי בֵּין גַּדְפֵי דְתַרְנְגוֹלָא וְאִתְעַר הַהוּא שַׁלְהוֹבָא בֵּיהּ וְקָרֵי, וְלֵית מַאן דְּאִתְעַר בַּר אִנּוּן זַכָּאֵי קְשׁוֹט דְּקָיְימֵי וְאִתְעָרוּ בְּאוֹרַיְיתָא. וּכְדֵין קוּדְשָׁא בְּרִיךְ הוּא וְכָל אִנּוּן צַדִּיקַיָיא דִּבְגוֹ גִנְתָא דְעֵדֶן צַיְיתֵי לְקָלֵיהוֹן. כְּמָא דְאַתְּ אָמֵר, (שיר השירים ח׳:י״ג) הַיּוֹשֶׁבֶת בַּגַּנִּים חֲבֵרִים מַקְשִׁיבִים לְקוֹלֵךְ הַשְּׁמִיעִנִי:","\u0003סִתְרֵי תוֹרָה\u0004 תּאנָא בְּתּוּקְפָּא דְּהֻרְמָנוּ דְמַלְכָּא, אַנְצִּיב חַד אִילָנָא רַבָּא וְתַּקִּיף גּוֹ נְטִיעָן עִלָאִין, נְטִיעַ אִילָנָא דָּא, בִּתְּרֵיסַר תְּחוּמִין אִסְתַּחַר, בְּאַרְבַּע סִטְרִין דְעָלְמָא פְּרִישָׂא רַגְלֵיהּ.","תּ\"ק פַּרְסֵי מַטְלָנוֹי, כָּל רְעוּתִּין דְּאִנּוּן פָּרְסִין בֵּיהּ תָּלְיָין, כַּד אִתְּעַר הַאי, כֻּלְהוּ מִתְּעָרִין בַּהֲדֵיהּ לֵיתּ מַאן דְּנָפִּיק מֵרְעוּתֵּיהּ לְבָתַּר, כֻּלְהוּ בִּרְעוּתָּא חָדָא בַּהֲדֵיהּ,","קָם מִלְּעֵילָא (ס\"א נחית) אִתְּנָחִיתּ בְּמַטְלָנוֹי לְגוֹ יַמָּא. מִנֵּיהּ יַמָּא (אתגלי) אִתְּמַלְיָיא. אִיהוּ מְקוֹרָא (דכל ד\"א לכל) מַיִין דְּנָבְעִין. תְּחוֹתֵּיהּ מִתְּפַּלְּגִין כָּל מֵימוֹי דִּבְרֵאשִׁיתּ, שַׁקְיוּ דְּגִנְתָּא בֵּיהּ תַּלְיָין.","כָּל נִשְׁמְתִּין דְּעָלְמָא מִנִּיהּ פָּרְחִין. נִשְׁמְתִּין אִלֵּין עָאלִין בְּגִנְתָּא לְנָחֲתָּא לְהַאי עָלְמָא. נִשְׁמָתָּא כַּד נָפְּקָא אִתְּבָּרְכָא בְּשֶׁבע בִּרְכָאן לְמֶהֱוֵי אַבָּא (ד\"א ל\"ג לרוחא ודם) לְגוּפָּא (ולמהוי) בִּסְלִיקוּ (דדיוקנא עלאה הדא הוא דכתיב ויאמר יי אל אברם הא נשמתא עלאה אבא (ד\"א ל\"ג לרוחא ודם) לגופא בסליקו) דְּדִיוּקְנא עִלָּאָה.","כַּד בַּעְיָא (נפשא) לְנָחֲתָּא לְהַאי עָלְמָא, אוֹמֵי לָהּ קוּדְשָׁא בְּרִיךָ הוּא לְמִיטַר פִּקּוּדֵי אוֹרַיְיתָּא וּלְמֶעְבַּד רְעוּתֵּיהּ. וּמָסַר לָהּ מְאָה מַפְּתְּחָאן דְּבִרְכָאן.","(ומולדתך דא גופא דאתקרי אילנא דחיי דאיהו תריסר שבטין עלאין. ומבית אביך דא שכינתא. אביך דא קודשא בריך הוא. שנאמר (משלי כ״ח:כ״ד) גוזל אביו ואמו ואומר אין פשע וגו'. ואין אביו אלא קודשא בריך הוא ואין אמו אלא כנסת ישראל. אל הארץ אשר אראך דא איהו האי עלמא), (נ\"א ומולדתך דא אילנא דחיי, ומבית אביך תריסר תחומין שבטין עלאין. אל הארץ אשר אראך דא איהו האי עלמא), (עד כאן סתרי תורה)","וַיֹּאמֶר יְיָ אֶל אַבְרָם, מַה כְּתִיב לְעֵילָא (בראשית י״א:כ״ח) וַיָּמָת הָרָן עַל פְּנֵי תֶּרַח אָבִיו וְגו'. מַאי אִירְיָא הָכָא, אֶלָּא עַד הַהוּא יוֹמָא לָא הֲוָה בַּר נָשׁ דְּמִית בְּחַיֵּי אֲבוֹי בַּר דָּא, וְכַד אִתְרְמֵי אַבְרָם לְנוּרָא אִתְקְטִיל הָרָן, וּבְגִין דָּא נָפְקוּ מִתַּמָּן מַאן קָטִיל לוֹן לְהָרָן, אֶלָּא כֵּיוָן דְּרָמוּ אַבְרָהָם לְנוּרָא דְכַּשְּׂדָאֵי, אִתְגְּלִי עֲלֵיהּ קוּדְשָׁא בְּרִיךְ הוּא וּשֵׁזָבֵיהּ, וְהֲוָה הָרָן אֲחוּי קָאֵי תַּמָּן. אָמְרוּ כַּשְּׂדָאֵי בְגִין זְכוּתֵיהּ דְהָרָן אִשְׁתְּזִיב, מִיָּד נָפַק שַׁלְהוֹבָא דְּאֶשָׁא וְאוֹקְדֵיהּ לְהָרָן, הֲדָא הוּא דִכְתִיב וַיָּמָת הָרָן עַל פְּנִי תֶּרַח אָבִיו. וְאִית דְּאָמְרֵי זַרְעָא דְתֶּרַח לֵית אֶשָׁא שָׁלְטָא בֵּיהּ, אֲבָל נְּרָמֵי לְהָרָן לְנוּרָא, וְאִי לָא אִיתּוֹקַד נֵדַע בְּוַדַּאי דְּלָא שָׁלְטָא נוּרָא בְּזַרְעֵיה, מִיָּד רָמִי לֵיהּ לְהָרָן לְנוּרָא וְאִתּוֹקְד וְהֲוָה תֶּרַח אֲבוֹי קָאִים תַּמָּן הֲדָא הוּא דִכְתִיב וַיָּמָת הָרָן עַל פְּנֵי תֶּרַח אָבִיו. בְּהַהוּא יוֹמָא יָדְעוּ כָּל אוּמַיָא וְלִישְׁנַיָא דְלָא שֵׁיזְבֵיהּ לְאַבְרָהָם אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא דְּאִיהוּ יְחִידָאִי דְעָלְמָא, וְהֲווּ מַיְיתֵין בְּנַיְיהוּ לְמִשְׁכְּנֵיהּ דְאַבְרָהָם וְאָמְרִין לֵיהּ חָמִינָן לָךְ, דְּאַתְּ רָחִיץ בְּקוּדְשָׁא בְּרִיךְ הוּא דְּאִיהוּ רִבּוֹנֵיהּ דְעָלְמָא, אוֹלִיף לְּבָנָנָא מֵאוֹרְחָךְ דְּאַתְּ יֵדַע, וְעֲלַיְיהוּ אָמַר קְרָא (תהילים מ״ז:י׳) נְדִיבֵי עַמִּים נֶאֱסָפוּ עַם אֱלֹהֵי אַבְרָהָם).","תָּא חֲזֵי, מַה כְּתִיב וַיִּקַּח תֶּרַח אֶת אַבְרָם בְּנוֹ וְאֶת לוֹט בֶּן הָרָן וְגו'. וַיֵּצְאוּ אִתָּם מֵאוּר כַּשְׂדִים. וַיֵּצְאוּ אִתָּם, אִתּוֹ מִבָּעֵי לֵיהּ. דְּהָא כְּתִיב וַיִּקַּח תֶּרַח וְגו' מַאי וַיֵּצְאוּ אִתָּם. אֶלָּא תֶּרַח וְלוֹט עִם אַבְרָהָם וְשָׂרָה נַפְקוּ דְּאִנּוּן הֲווּ עִקְּרָא לְמֵיפַּק מִגּוֹ אִנּוּן חַיָּיבַיָּא, דְּכֵיוָן דְּחָמָא תֶּרַח דְּאַבְרָהָם בְּרֵיהּ אִשְׁתְּזִיב מִגּוֹ נוּרָא, אִתְהַדַּר לְמֶעְבַּד רְעוּתֵיהּ דְּאַבְרָהָם, וּבְגִין כָּךְ וַיֵּצְאוּ אִתָּם תֶּרַח וְלוֹט.","וּבְשַׁעֲתָא דְּנַפְקוּ מַה כְּתִיב לָלֶכֶת אַרְצָה כְּנַעַן. דִּרְעוּתָא דִלְהוֹן הֲוָה לְמֵיהַךְ תַּמָּן. מִכָּאן אוֹלִיפְנָא כָּל מַאן דְּאִתְעַר לְאִתְדַּכָּאָה מְסַיְיעִין לֵיהּ. תָּא חֲזֵי, דְּהָכִי הוּא דְּכֵיוָן דִּכְתִיב לָלֶכֶת אַרְצָה כְּנַעַן מִיָּד וַיֹּאמֶר יְיָ אֶל אַבְרָם לֶךְ לְךָ, וְעַד דְּאִיהוּ אִתְעַר בְּקַדְמִיתָא לָא כְּתִיב לֶךְ לְךָ.","תָּא חֲזֵי, מִלָה דִלְעֵילָא לָא אִתְעַר עַד דְּאִתְעַר לְתַתָּא בְּקַדְמִיתָא עַל מַה דְּתִשְׁרֵי הַהִיא דִלְעֵילָא, וְרָזָא דְמִלָּה, נְהוֹרָא אוּכְמָא לָא אִתְאַחִיד בִּנְהוֹרָא חִוָּורָא עַד דְּאִיהִי אִתְעָרִית בְּקַדְמִיתָא, כֵּיוָן דְּאִיהִי אִתְעָרִית בְּקַדְמִיתָא, מִיָּד נְהוֹרָא חִוְורָא שַׁרְיָיא עֲלָהּ.","וְעַל דָּא כְּתִיב (תהילים פ״ג:ב׳) אֱלֹהִים אַל דָּמִי לָךְ אַל תֶּחֱרָשׁ וְאַל תִּשְׁקֹט אֵל. בְּגִין דְּלָא יִתְפְּסַק נְהוֹרָא חִוָּורָא מֵעָלְמָא לְעָלְמִין. וְכֵן (ישעיהו ס״ב:ו׳) הַמַּזְכִּירִים אֶת יְיָ אַל דֳּמִי לָכֶם. בְּגִין לְאַתְעָרָא לְתַתָּא בְּמָּה דְיִשְׁרֵי אִתְעֲרוּתָא דִלְעֵילָא. וְכֵן כֵּיוָן דְּאִתְעַר בַּר נָשׁ אִתְעֲרוּתָא בְּקַדְמִיתָא כְּדֵין אִתְעַר אִתְעֲרוּתָא דִלְעֵילָא. תָּא חֲזֵי, כֵּיוָן דִּכְתִיב וַיֵּצְאוּ אִתָּם מֵאוּר כַּשְׂדִים וְגו' מִיָּד וַיֹּאמֶר יְיָ אֶל אַבְרָם וְגו'.","וַיֹּאמֶר יְיָ אֶל אַבְרָם לֶךְ לְךָ, אָמַר רַבִּי אֶלְעָזָר לֶךְ לְךָ, לְגַרְמָךְ לְאַתְקָנָא גַּרְמָךְ, (לאתתקפא) לְאַתְקָנָא דַּרְגָּא דִילָךְ. לֶךְ לְךָ, לֵית אַנְתְּ (ס\"א כדאי) לְמֵיקַם הָכָא בֵּין חַיָּיבִין אִלֵּין."],[[0,"ווי לאינון דניימי וכו':","ווי לאלו המנמנמים, שהשינה בחורי עיניהם היינו אותם שאינם קמים משנתם לעסוק בתורה, ולהמשיך קו האמצעי, הרי הארת השמאל סותם מאור עיניהם והם מנמנמים. ואין להם עינים, דהיינו מוחין, אלא שהשינה בחורי עיניהם. אינם יודעים ואינם מסתכלים איך יקומו בדין, שיפקדו ליתן חשבון, כאשר הגוף יטמא, והנשמה תשוטט על פני אויר צהרים, ועולה ויורדת והשערים אינם נפתחים אליה. ומתגלגלות כאבנים בתוך כף הקלע. מי ידרוש בשבילם כאשר לא יקומו בעידון הזה, במקומות התענוג של הצדיקים יפקד ויעדר מקומם. יהיו נמסרים בידי המלאך דומה. ירדו לגיהנם ולא יעלו. עליהם כתוב כלה ענן וילך, כן יורד שאול לא יעלה."],[1,"בההיא שעתא אתער וכו':","בשעה ההיא, דהיינו בחצות, נתעוררה שלהבת מצד צפון, ומכה בארבע רוחות העולם, כי אז מתפשטת הארת השמאל בהעולם, שהוא דין כנ\"ל, ויורדת ומגעת בין כנפי התרנגול שה\"ס גבריאל (כנ\"ל בהקדמת הזהר דף קס\"ט אות קע\"א ד\"ה והנה) ואותה השלהבת נתעורר בו והוא קורא. שה\"ס הכרוז הנ\"ל שאומר \u0003וכרוזא קרא בחיל וכו'.\u0004"],[1,"","ולית מאן דאתער וכו': ואין מי שיתעורר לקול הקריאה, זולת אותם צדיקי אמת הקמים אז ועוסקים בתורה וממשיכים קו האמצעי כנ\"ל, ואז הקב\"ה וכל אלו הצדיקים שבתוך הגן עדן, מקשיבים לקולם, כמו שאתה אומר היושבת בגנים חברים מקשיבים לקולך השמיעני. והנה נתבאר בזה, איך כל קיומם של בני אדם הוא על קו האמצעי הנמשך ע\"י עסק התורה, ולולא קו אמצעי אין להם קיום כלל. אלא שנמסרים ביד דומה ויורדין לגיהנם ואינם עולים כנ\"ל."],[2,"תאנא בתוקפא דהרמנו דמלכא וכו':","תנן, בתוקפו של רצון המלך שהוא בינה נשתל אילן אחד רב ועצום, \u0003אילנא\u0004 היינו ז\"א. \u0003רבא,\u0004 בסוד המוחין דהארת החכמה. \u0003ותקיף\u0004 בסוד המוחין דחסדים. כמו שיתבאר לפנינו. והס\"ת רוצה לבאר את הכתוב לך לך מארצך וגו' שרומז, על סדר אצילות הנשמה מז\"א ונוקביה עד בואה בעולם הזה להתלבש בגוף, לפיכך מבאר מקודם איך ז\"א ונוקביה מקבלים המוחין, ומאצילים הנשמה, ואח\"כ מבאר את הכתוב."],[2,"גו נטיען עלאין וכו':","תוך נטיעות העליונות שהם ספירות הבינה, נטוע אילן הזה, שהוא ז\"א. בשנים עשרה גבולים הוא מסתובב, בארבע רוחות העולם פרושה רגלו."],[2,"","פירוש. נודע, שמכח עליית המלכות לבינה הופרסה פרסא תחת כו\"ח דכל המדרגות, ונתמעטה הבינה לו\"ק, שה\"ס מ\"י דאלקים שפירושו, אורות נפש רוח בהכלים דכתר וחכמה. וג' אותיות אל\"ה דאלקים, שפירושו בינה וז\"א ונוק' דכלים, ירדו ממנה לז\"א. ובעת גדלות אשר הבינה מורידה הפרסא למקומה, ומחזרת אתוון אל\"ה שלה אליה, עולה עמהם גם ז\"א למקום הבינה, ונעשה כמו ספירה מספירת הבינה, ומקבל שם משום זה, האורות של הבינה. (כנ\"ל בראשית א' דף ט\"ו אות ט' ד\"ה ההיא ע\"ש). וזמ\"ש, \u0003בתוקפא דהרמנו דמלכא,\u0004 בתוקפו של רצון המלך, דהיינו על ידי עלית רצון המלך שהיא מלכות, אל הבינה, משום זה נפלו אתוון אל\"ה לז\"א ונעשו בהשתוות עמו, וע\"כ בעת הגדלות שהיא מעלה אליה אתוון אל\"ה בחזרה עולה גם ז\"א עמהם, להיותו דבוק בהם, ונמצא עי\"ז \u0003גו נטיען עלאין נטיע אילנא דא\u0004 שנעשה לספירה אחת מספירות הבינה. ומקבל האורות שלה כמו ספירותיה."],[2,"","ומכח עלית המלכות והתמתקותה בהבינה. יצא סוד \u0003האלכסון.\u0004 כי ד' רוחות העולם ה\"ס חו\"ב תו\"מ כנודע. וה\"ס - מרובע. כזה וכשעלתה המלכות שה\"ס מערב אל הבינה שה\"ס צפון, הרי שב' הרוחות מערב וצפון נעדרו ממקומם ונתחברו יחד. ונעשו מהם אלכסון, כי ד' הספירות חו\"ב תו\"מ נעשו עתה משולש, כזה. ובזה תבין סוד י\"ב גבולי אלכסון. כי ד' הרוחות, שהם ד' הספירות חו\"ב תו\"מ, נכללים זה מזה, ויש בכל אחד מהם חו\"ב תו\"מ, כנודע. ולפי\"ז צריך להיות בהם ט\"ז גבולים. כי גבולים פירושו כמו רוחות. אמנם מתוך שהמלכות והבינה נכללו כאחד, אין בכל אחד מהם רק ג' רוחות, והם י\"ב רוחות דהיינו י\"ב גבולים. והיינו משום שב' הרוחות צפון מערב נתחברו ונעשו לאלכסון, באופן שהרוח מערב אין לו בחינת עצמו אלא רק אלכסון. ע\"כ נקראים \u0003י\"ב גבולי אלכסון.\u0004"],[2,"","וזה אמרו. \u0003בתריסר תחומין אסתחר,\u0004 שז\"א מסתובב בי\"ב גבולים, דהיינו בעת שמסתובב בג' דוכתי הנמשכים מכח עלית המלכות לבינה. דהיינו בסוד ג' הנקודות חולם שורק חירק, כדי לקבל הארת החכמה, (כנ\"ל בראשית א' דף י\"ט אות י\"ב) נמצאים אז ד' רוחות העולם שבו נכללים רק מי\"ב גבולים, שכל אחד מהד' יוצא רק בסוד משולש, שהם רק ב' רוחות שלמים, מזרח ודרום, אבל ב' הרוחות צפון מערב, נתמזגו ונעשה מהם אלכסון. שסודו, שהמערב שהוא מדת הדין נבלע בהצפון שהוא מדת הרחמים. וצריך שתזכור המתבאר לעיל (בראשית א' דף ז' אות ג' ד\"ה וכבר) שלולא נמתקה המלכות בהבינה לא היו זו\"ן התחתונים ראוים למוחין דהארת חכמה, עש\"ה."],[2,"","וזה אמרו \u0003בארבע סטרין דעלמא פרישא רגליה,\u0004 רגלו, היינו המלכות שלו. ואומר, שהמלכות דז\"א פרושה בד' רוחות העולם. כלומר, אע\"פ \u0003שבתריסר תחומין אסתחר,\u0004 שפירושו, שאין המלכות מפורשת בשום רוח מד' רוחות העולם דז\"א, אלא שנכללת בהאלכסון, כנ\"ל, הנה כל זה אמור בעת \u0003דאסתחר,\u0004 כלומר בו בעת שמקבל חכמה בשביל הנוקבא, אבל מבחינתו עצמו אינו כך, כי \u0003בארבע סטרין דעלמא פרישא רגליה,\u0004 שהמלכות מפורשת בו בכל רוח ורוח, ויש לו ט\"ז גבולים מבחינת עצמו. והטעם הוא כי כל תקון די\"ב גבולי אלכסון, נעשה רק לצורך קבלת המוחין דחכמה. וז\"א אינו מקבל לעצמו רק מוחין דחסדים, וע\"כ אינו מקבל אותו, התקון. ורוצה בזה לבאר את השם \u0003אברם\u0004 שהוא נוטריקון \u0003אב רם.\u0004 אשר \u0003אב\u0004 נמשך מבחי' י\"ב גבולים. ו \u0003רם\u0004 נמשך מבחי' ט\"ז גבולים כמ\"ש לפנינו."],[3,"ת\"ק פרסי מטלנוי:","חמש מאות פרסאות מסעיו. כל הרצוניות של אלו פרסאות כלומר דרכי השפעתם, תלוים בו בז\"א, כאשר זה מתעורר, כולם מתעוררים עמו. אין מי שישנה רצונו. ולאחר כך, נעשו כולם ברצון אחד עמו. פרסאות, פירושו מוחין דהארת החכמה. ומכונים כן, משום שהם יוצאים בכח עליות וירידות הפרסא שמתחת הכו\"ח של הבינה, כנ\"ל בדיבור הסמוך, שבעלות הפרסא מתחת הכו\"ח דבינה, יורדות אתוון אל\"ה לז\"א, ובעת גדלות, היא מורדת הפרסא למקומה ומחזירה אליה האתוון אל\"ה עם ז\"א הדבוק בהן, ונמצא שלולא עלית הפרסא מתחת כו\"ח דבינה, לא היה שום מציאות שז\"א יוכל לעלות לבינה. וכיון שעלה לבינה, נעשה ז\"א לעצם הבינה, כי התחתון העולה לעליון נעשה כמוהו. ומקבל שם ה' ספירות כח\"ב תו\"מ דבינה שנעשתה לחכמה, ואלו ה' ספירות דבינה, כלולה כל אחת ממאה. כי הספירות דבינה הן מאות (כנ\"ל ב\"ב דף נ\"ח אות פ\"ט ד\"ה ושית) וע\"כ הן מכונות \u0003ה' מאות פרסאות.\u0004 פרסאות נקראות על שם מקור יציאתן כי יוצאים בז\"א מכח עלית וירידת הפרסא. ה' מאות הן, להיותן מבינה."],[3,"","וז\"ש \u0003ת\"ק פרסי מטלנוי,\u0004 כי כשנוסע ועולה לבינה, מקבל שם ה' הספירות כח\"ב תו\"מ דבינה, שחזרה לחכמה, המכונים ה' מאות פרסאות. \u0003כל רעותין דאינון פרסין ביה תליין,\u0004 כל הרצוניות של אלו הפרסאות, כלומר דרכי השפעה שלהם, תלוים בז\"א, אע\"פ שהם מבינה, משום \u0003כד אתער האי, כלהו מתערין בהדיה\u0004. כי אין הספירות דבינה יכולים להאיר מטרם שז\"א עלה אליהם ומכריע בין ב' הקוין דבינה, (כנ\"ל בראשית א' דף ט\"ז אות ט' ד\"ה וזה) ונמצא שכאשר ז\"א מתעורר להכריע בין הקוין דבינה, אז כל ה' הספירות דבינה מאירים עמו, ולא זולת. וע\"כ, \u0003לית מאן דנפיק מרעותיה,\u0004 אין מי מאלו הפרסאות שיכולים לשנות רצונו. כלומר, כיון שדרך השפעתו של ז\"א הוא בבחינת ו\"ק, וע\"כ לא יוכלו גם הפרסאות להשפיע בחינת ג\"ר דחכמה, אלא שמשפיעים רק ו\"ק דחכמה כמו דרך השפעה של ז\"א והיינו כנ\"ל (בראשית א' דף קל\"ב אות קמ\"ב ד\"א וטעם) ע\"ש. ונתבאר לעיל, שכל אלו המוחין דחכמה מקבל ז\"א רק כדי להשפיע להנוקבא ולא לצורך עצמו. וז\"ש \u0003לבתר, כלהו ברעותא חדא בהדיה\u0004 ואחר כך, דהיינו אחר שמשפיע אלו המוחין של ו\"ק דחכמה אל הנוקבא, נעשו כל ת\"ק פרסאות הללו, שהם ה' הספירות שקבל מהבינה, ברצון אחד עמו, כלומר שנעשו אצלו אחר כך, לבחינת חסדים מכוסים כמוהו, כי אין ז\"א מקבל לעצמו אלא חסדים מכוסים מחכמה כנ\"ל."],[4,"קם מלעילא נחית וכו':","קם ז\"א מלמעלה מבינה, דהיינו אחר שקבל מוחין מבינה, ויורד במסעיו לתוך הים, שהיא הנוקבא, דהיינו שמשפיע אותם להנוקבא. ממנו מתמלא הים, הוא המקור לכל האורות הנובעים בהים, תחתיו מתחלקים כל מימי בראשית, השקוי של הגן, שהיא המלכות, תלוי בו בז\"א. \u0003מימי בראשית\u0004 פירושו, המוחין שז\"א מקבל מהבינה שחזרה לחכמה, הנקראת ב' ראשית, (כנ\"ל בראשית א' דף רמ\"ד אות רצ\"ח) שז\"א משפיע אותם להנוקבא, והם מתחלקים תחתיו בהנוק' לכו\"ח ובינה ותו\"מ, כמו שמתחלקים תחילה בהבינה אל \u0003מ\"י אל\"ה.\u0004 והיא בעת הקטנות. וז\"ש \u0003תחותיה מתפלגין כל מימוי דבראשית\u0004 ואח\"כ משפיע לה הגדלות, וז\"ש \u0003שקיו דגנתא ביה תליין.\u0004 (ועי' לעיל בראשית א' דף ס\"ח אות ס\"ג ד\"ה חמש מאה.)"],[5,"כל נשמתין דעלמא וכו':","כל הנשמות שבעולם יוצאים ממנו, מז\"א. נשמות האלו נכנסים בהגן, בהנוקבא, לירד משם לעולם הזה. להתלבש בגוף כאשר הנשמה יוצאת משם לעולם הזה, היא מתברכת בשבע ברכות, שתוכל להיות אב אל הגוף בעליה עליונה. וז\"ש ויאמר ה' אל אברם. שהיא נשמה העליונה הנקראת אברם, שהיא נוטריקון אב רם, להיותה אב להגוף בעליה לצורה העליונה. בחסדים הנמשכים מהעליה לאו\"א. כלומר שנוהג בה ב' מיני הארות, \u0003אב\u0004 פירושו מוחין דחכמה, ו \u0003רם\u0004 פירושו, מוחין דחסדים הנמשכים לז\"א מעליה עליונה לאו\"א, והוא מטעם היותה תולדה של ז\"א, שבו נוהג ב' מיני הארות הללו (כנ\"ל דף ח' ד\"ה בארבע סטרין ע\"ש)."],[6,"כד בעיא לנחתא וכו':","כשהנשמה באה לרדת לעולם הזה, משביע אותה הקב\"ה שתשמור מצות התורה ושתעשה רצונו. ומוסר לה מאה מפתחות של ברכות לכל יום ויום, כדי להשלים מדרגות העליונות, שהם בחשבון \u0003לך לך,\u0004 כי לך לך בגימטריא מאה. כי כולם נמסרו לה להנשמה, כדי שתתקן עמהם את הגן, שהיא הנוקבא ולעבדה ולשמרה, \u0003מארצך\u0004 זהו \u0003גן\u0004 העדן. פירוש. הקב\"ה, דהיינו ז\"א משפיע לה להנשמה המוחין דבינה, שספירותיה הן בסוד מאות (כנ\"ל בראשית א' דף שמ\"ח אות תע\"ז ד\"ה ויאמר) \u0003יום\u0004 פירושו ספירה. וז\"ש \u0003ומסר לה מאה מפתחן דברכאן בכל יומא,\u0004 שכל יום דהיינו כל ספירה שמשפיע לה, כוללת מאה מפתחות, דהיינו האפשרות להמשיך מאה ברכות, להיותם מבינה. וז\"ש \u0003לאשלמא לדרגין עלאין,\u0004 כדי שהנשמה, תקבל ותשתלם במדרגות עליונות דבינה. כי כל זמן שאינה ממשיכה בכל יום מאה ברכות, אין בהם אותה השלימות כמו שהן בבינה. ומה שמאה מפתחות הברכות מרומזים בהמלות \u0003לך לך,\u0004 הוא כי \u0003מארצך דא גנתא דעדן,\u0004 שפירושה שהנוקבא הנקראת \u0003גן,\u0004 עולית ומלבשת לבינה החוזרת לחכמה הנקראת \u0003עדן,\u0004 (כנ\"ל בראשית ב' דף ד' אות ו' ד\"ה היכלא) ונמצאת הנוקבא אז בבחינת הבינה שספירותיה בסוד מאות, וז\"ס \u0003לך לך מארצך,\u0004 אשר \u0003לך לך\u0004 ה\"ס מאה מפתחות, \u0003מארצך\u0004 ה\"ס גן עדן, כלומר כיון שהנשמה הולכת ובאה לעולם הזה מן גן העדן, ע\"כ יש לה כח להמשיך מאה ברכות בכל יום כמו הספירות שבגן עדן."],[7,"ומולדתך דא גופא:","ומולדתך, פירושו מן הגוף, שהוא ז\"א המכונה גופא, הנקרא עץ החיים, שהוא כולל י\"ב שבטים העליונים. שה\"ס תריסר תחומין הנ\"ל, ומשמיענו הכתוב, שהנשמה היא תולדה דז\"א ויוצאת ממנו. \u0003ומבית אביך,\u0004 זהו השכינה הנקראת בית. אביך פירושו הקב\"ה, הוא ז\"א, שנאמר גוזל אביו ואמו ואומר אין פשע וגו' ואין אביו אלא הקב\"ה. ואין אמו אלא כנסת ישראל שהיא הנוקבא. \u0003אל הארץ אשר אראך,\u0004 זה הוא עולם הזה. שהנשמה נשלחה שמה. וזהו שיעור הכתוב, ויאמר ה' אל אברם, \u0003אברם\u0004 פירושו הנשמה ולפי שיש לה ב' מיני מוחין כמו ז\"א, א) בחינת \u0003י\"ב תחומין,\u0004 שה\"ס אב. ב) \u0003בד' סטרין דעלמא פרישא רגליה,\u0004 שה\"ס רם, ע\"כ נקראת הנשמה \u0003אב רם. ויאמר ה',\u0004 היינו \u0003שמשביע אותה למיטר פקודי אורייתא ולמעבד רעותיה. לך לך מארצך\u0004 רומז על מסירת מאה מפתחאן דברכאן כמו שיש בהספירות דג\"ע הנקראת \u0003ארצך\u0004 כנ\"ל \u0003וממולדתך,\u0004 רומז על אצילותה מז\"א, ומבית אביך רומז על בריאתה מן הנוקבא. דהיינו כנ\"ל \u0003כל נשמתא דעלמא מיניה פרחין נשמתין אלין עאלין בגנתא, אל הארץ אשר אראך\u0004 היינו ביאת הנשמה בהגוף בעולם הזה. (ע\"כ ס\"ת)."],[8,"ויאמר ה' אל אברם וגו':","מה כתוב למעלה מזה, וימת הרן על פני תרח אביו וגו'. ומקשה, מה משמיענו כאן, שאומר \u0003על פני\u0004 תרח אביו, ואם תאמר ש \u0003על פני\u0004 משמע בחיי אביו. הכי עד היום הזה לא היה אדם שמת בחיי אביו חוץ מזה, ומכל מקום לא כתוב בו \u0003על פני,\u0004 דהיינו הבל שמת בחיי אדם אביו, חנוך שלקח אותו אלקים בחיי ירד אביו, \u0003דכד אתרמי אברם וכו':\u0004 ומתרץ, כשהשליכו את אברם לאש נהרג הרן. ומשום זה יצאו משם, מאור כשדים. ועל כן כתוב על פני תרח אביו, כלומר, שגרם לו יציאתו משם."],[9,"ת\"ח מה כתיב וכו':","בוא וראה מה כתוב ויקח תרח וגו' ויצאו אתם מאור כשדים. ושואל, כתוב \u0003ויצאו אתם,\u0004 ויצאו אתו צריך לכתוב, דהיינו עם תרח. כי כתוב ויקח תרח וגו'. למה כתוב \u0003ויצאו אתם.\u0004 ומשיב אלא תרח ולוט עם אברהם ושרה יצאו, כי הם שרצו לצאת בעיקר מתוך הרשעים, ואחר שראה תרח שאברהם בנו ניצל מתוך האש חזר לעשות רצונו של אברהם ומשום זה, ויצאו אתם תרח ולוט."],[10,"ובשעתא דנפקו וכו':","ובשעה שיצאו מה כתוב בהם, \u0003ללכת ארצה כנען\u0004 כי רצונם היה ללכת שם. מכאן למדנו שכל מי שבא לטהר עוזרים לו. בוא וראה שכך הוא, כי כיון שכתוב \u0003ללכת ארצה כנען,\u0004 מיד כתוב, \u0003ויאמר ה' אל אברהם לך לך וגו'.\u0004 ומטרם שנתעורר מעצמו מתחילה ללכת לארץ כנען, לא כתוב \u0003לך לך,\u0004 הרי שהבא ומתעורר מעצמו מלמטה, מסייעים לו מלמעלה. אבל בלי אתערותא דלתתא, אין אתערותא דלעילא."],[11,"ת\"ח מלה דלעילא וכו':","שום דבר מלמעלה אינו מתעורר, מטרם שנתעורר תחילה מלמטה על מה שעליו ישרה הדבר שלמעלה. וסוד הדבר אור שחור שבנר, שה\"ס הנוקבא אינה נאחזת באור הלבן שבנר, שה\"ס ז\"א, מטרם שהיא מתעוררת תחילה, כיון שהיא נתעוררת תחילה, מיד שורה עליה אור הלבן. כי התחתון מחויב להתעורר תחילה."],[12,"וע\"ד כתיב אלקים וגו':","וע\"כ כתוב אלקים אל דמי לך וגו' כדי שלעולם לא יפסוק אור הלבן מהעולם כי אלקים ה\"ס הנוקבא, שה\"ס נהורא אוכמא, ואם לא תחרש ולא תשקוט מלהתעורר מלמטה, יאחז בה תמיד אור הלבן למעלה, שה\"ס ז\"א. כנ\"ל."],[12,"וכן המזכירים את ה' אל דמי לכם וכו':","כדי לעורר מלמטה מה שישרה עליו ההתעוררות של מעלה. וכן כיון שעורר האדם התעוררות מלמטה תחילה, אז נתעורר עליו התעוררות של מעלה. בוא וראה, כיון שכתוב, \u0003ויצאו אתם מאור כשדים ללכת וגו':\u0004 ועשו אתערותא דלתתא, מיד \u0003ויאמר ה' אל אברם וגו',\u0004 דהיינו שסייעו אותו מלמעלה. וטעם הדברים. כי צריכים לדבר גס מלמטה שהאור יוכל להאחז בו, ודבר גס הזה תלוי לגמרי בהתחתון (כנ\"ל בראשית ב' דף קנ\"ב אות רנ\"ג ד\"ה ביאור הדברים עש\"ה) ואין להכפיל דברים."],[13,"ויאמר ה' אל אברם לך לך וגו':","א\"ר אלעזר, לך לך, לך היינו לעצמך, כלומר, לתקן את עצמך, לתקן את המדרגה שלך. \u0003לך לך,\u0004 כי אין לך להמצא כאן בין הרשעים הללו."]],[[0,"","אוֹי לְאוֹתָם שֶׁיְּשֵׁנִים וְשֵׁנָה בִּנְחִירֵיהֶם, לֹא יוֹדְעִים וְלֹא מִסְתַּכְּלִים אֵיךְ יָקוּמוּ בַּדִּין כְּשֶׁהַחֶשְׁבּוֹן נִמְנֶה, כְּשֶׁנִּטְמָא הַגּוּף, וְהַנְּשָׁמָה מְשׁוֹטֶטֶת עַל פְּנֵי הָאֲוִיר שֶׁמֵּאִיר וְעוֹלָה וְיוֹרֶדֶת, וְהַשְּׁעָרִים לֹא נִפְתָּחִים, וּמִתְגַּלְגְּלִים כַּאֲבָנִים בְּתוֹךְ הַקֶּלַע. אוֹי לָהֶם! מִי יְבַקֵּשׁ אוֹתָם שֶׁלֹּא יָקוּמוּ בַתַּעֲנוּג הַזֶּה? בְּתוֹךְ הַמְּקוֹמוֹת שֶׁל עִנּוּגֵי הַצַּדִּיקִים וְנִפְקָד מְקוֹמָם. וְנִמְסָרִים בִּידֵי דוּמָה, יוֹרְדִים וְלֹא עוֹלִים. עֲלֵיהֶם כָּתוּב (איוב ז) כָּלָה עָנָן וַיֵּלַךְ כֵּן יוֹרֵד שְׁאוֹל לֹא יַעֲלֶה."],[1,"","בְּאוֹתָהּ הַשָּׁעָה מִתְעוֹרֶרֶת שַׁלְהֶבֶת אַחַת מִצַּד הַצָּפוֹן, וּמַכָּה בְּאַרְבָּעָה רוּחוֹת הָעוֹלָם, וְיוֹרֶדֶת וּמַגִּיעָה לְבֵין כַּנְפֵי הַתַּרְנְגוֹל, וּמִתְעוֹרֶרֶת בּוֹ אוֹתָהּ הַשַּׁלְהֶבֶת וְקוֹרֵא. וְאֵין מִי שֶׁמִּתְעוֹרֵר, פְּרָט לְאוֹתָם צַדִּיקֵי הָאֱמֶת שֶׁעוֹמְדִים וּמִתְעוֹרְרִים בַּתּוֹרָה. וְאָז הַקָּדוֹשׁ בָּרוּךְ הוּא וְכָל אוֹתָם הַצַּדִּיקִים שֶׁבְּתוֹךְ גַּן הָעֵדֶן מַקְשִׁיבִים לְקוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (שיר ח) הַיּוֹשֶׁבֶת בַּגַּנִּים חֲבֵרִים מַקְשִׁיבִים לְקוֹלֵךְ הַשְׁמִיעִנִי."],[2,"","לָמַדְנוּ בְּתֹקֶף רְצוֹן הַמֶּלֶךְ נָטַע אִילָן אֶחָד גָּדוֹל וְחָזָק בְּתוֹךְ הַנְּטִיעוֹת הָעֶלְיוֹנוֹת, הַנְּטִיעָה שֶׁל הָאִילָן הַזֶּה בִּתְרֵיסַר תְּחוּמִים מְסֻבֶּבֶת. בְּאַרְבָּעָה צְדָדִים שֶׁל הָעוֹלָם פְּרוּשָׂה רַגְלוֹ."],[3,"","ת\"ק פַּרְסָאוֹת מַסְעוֹתָיו. כָּל הָרְצוֹנוֹת שֶׁל אוֹתָם פַּרְסוֹת בּוֹ תְּלוּיִים. כְּשֶׁזֶּה מִתְעוֹרֵר, כֻּלָּם מִתְעוֹרְרִים עִמּוֹ. אֵין מִי שֶׁיּוֹצֵא מֵרְצוֹנוֹ. אַחַר כָּךְ כֻּלָּם בְּרָצוֹן אֶחָד עִמּוֹ."],[4,"","קָם מִלְמַעְלָה, (יורד) יוֹרֵד בְּמַסְעוֹתָיו לְתוֹךְ הַיָּם. מִמֶּנּוּ הַיָּם (מתגלה) מִתְמַלֵּא. הוּא הַמָּקוֹר (של כל) הַמַּיִם הַנּוֹבְעִים, תַּחְתָּיו נֶחֱלָקִים כָּל מֵימֵי בְרֵאשִׁית. הַשְׁקָאוֹת הַגָּן תְּלוּיִים בּוֹ."],[5,"","כָּל הַנְּשָׁמוֹת שֶׁל הָעוֹלָמִים פּוֹרְחוֹת מִמֶּנּוּ. הַנְּשָׁמוֹת הַלָּלוּ נִכְנָסוֹת לַגָּן לָרֶדֶת לָעוֹלָם הַזֶּה. כְּשֶׁיּוֹצֵאת נְשָׁמָה, הִיא מִתְבָּרֶכֶת בְּשֶׁבַע בְּרָכוֹת לִהְיוֹת אָב (לרוח ורם) לַגּוּף (ולהיות) בַּעֲלִיָּה (של הדמות העליונה, זהו שכתוב ויאמר ה' אל אברם, הרי נשמה עליונה אבא (לרוח ורם) לגוף בעליה) שֶׁל דְּמוּת עֶלְיוֹנָה."],[6,"","כְּשֶׁרוֹצָה (הנפש) לָרֶדֶת לָעוֹלָם הַזֶּה, מַשְׁבִּיעַ אוֹתָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא לִשְׁמֹר אֶת מִצְווֹת הַתּוֹרָה וְלַעֲשׂוֹת רְצוֹנוֹ, וּמוֹסֵר לָהּ מֵאָה מַפְתְּחוֹת שֶׁל בְּרָכוֹת שֶׁל כָּל יוֹם לְהַשְׁלִים אֶת הַדְּרָגוֹת הָעֶלְיוֹנוֹת כְּחֶשְׁבּוֹן לֶ\"ךְ לְ\"ךְ. שֶׁהֲרֵי כֻּלָּם נִמְסְרוּ לָהּ כְּדֵי לְתַקֵּן בָּהֶם אֶת הַגָּן וּלְעָבְדָהּ וּלְשָׁמְרָהּ. מֵאַרְצְךְ - זֶה גַּן הָעֵדֶן."],[7,"","(ומולדתך זה הגוף, שנקרא עץ החיים, שהוא תריסר שבטים עליונים, ומבית אביך זו השכינה, אביך זה הקדוש ברוך הוא, שנאמר (משלי כח) גוזל אביו ואמו ואמר אין פשע וגו', ואין אביו אלא הקדוש ברוך הוא, ואין אמו אלא כנסת ישראל, אל הארץ אשר אראך זה הוא העולם הזה,) (ס\"א וממולדתך זה עץ החיים, ומבית אביך תריסר תחומים, שבטים עליונים, אל הארץ אשר אראך זהו העולם הזה). עד כָּאן סתרי תורָה."],[8,"","וַיֹּאמֶר ה' אֶל אַבְרָם. מַה כָּתוּב לְמַעְלָה? (בראשית יא) וַיָּמָת הָרָן עַל פְּנֵי תֶּרַח אָבִיו וְגוֹ'. מָה אוֹמֵר כָּאן? אֶלָּא עַד אוֹתוֹ הַיּוֹם לֹא הָיָה אָדָם שֶׁמֵּת בְּחַיֵּי אָבִיו פְּרָט לָזֶה, וּכְשֶׁנִּזְרַק אַבְרָהָם לָאֵשׁ, נֶהֱרַג חָרָן, וּמִשּׁוּם זֶה יָצְאוּ מִשָּׁם. (מי הרג את הרן? אלא כיון שהשליכו את אברהם לאור כשדים, התגלה עליו הקדוש ברוך הוא והצילו, והיה הרן אחיו עומד שם.) אמרו הכשדים, בשביל זכותו של הרן נצול, מיד יצאה שלהבת של אש ושרפה את הרן, זהו שכתוב וימת הרן על פני תרח אביו, ויש שאומרים שאין שולטת אש בזרעו של תרח, אבל נשליך את הרן לאש, ואם לא יבער, נדע ודאי שאין שולטת האש בזרעו, מיד השליכו את הרן לאש ונשרף, והיה תרח אביו עומד שם, זהו שכתוב וימת הרן על פני תרח אביו. באותו היום ידעו כל אמה ולשון שלא הציל את אברהם אלא הקדוש ברוך הוא שהוא יחידו של עולם, והיו מביאים את בניהם למשכנו של אברהם, ואומרים לו', ראינו אותך שאתה בוטח בקדוש ברוך הוא שהוא רבון העולם, למד את בנינו מדרכך שאתה יודע, ועליהם אמר הכתוב (תהלים מז) נדיבי עמים נאספו עם אלהי אברהם,"],[9,"","בֹּא רְאֵה מַה כָּתוּב, וַיִּקַּח תֶּרַח אֶת אַבְרָם בְּנוֹ וְאֶת לוֹט בֶּן הָרָן וְגוֹ', וַיֵּצְאוּ אִתָּם מֵאוּר כַּשְׂדִּים. וַיֵּצְאוּ אִתָּם? אִתּוֹ הָיָה צָרִיךְ לִהְיוֹת, שֶׁהֲרֵי כָּתוּב וַיִּקַּח תֶּרַח וְגוֹ'. מַה זֶּה וַיֵּצְאוּ אִתָּם? אֶלָּא תֶרַח וְלוֹט עִם אַבְרָהָם וְשָׂרָה יָצְאוּ, שֶׁהֵם הָיוּ הָעִקָּר לָצֵאת מִתּוֹךְ אוֹתָם הָרְשָׁעִים. שֶׁכֵּיוָן שֶׁרָאָה תֶרַח שֶׁאַבְרָהָם בְּנוֹ נִצַּל מִתּוֹךְ הָאֵשׁ, חָזַר לַעֲשׂוֹת אֶת רְצוֹנוֹ שֶׁל אַבְרָהָם, וּמִשּׁוּם כָּךְ וַיֵּצְאוּ אִתָּם תֶּרַח וְלוֹט."],[10,"","וּבְשָׁעָה שֶׁיָּצְאוּ מַה כָּתוּב? לָלֶכֶת אַרְצָה כְּנַעַן. שֶׁרְצוֹנָם הָיָה לָלֶכֶת לְשָׁם. מִכָּאן לָמַדְנוּ, כָּל מִי שֶׁמִּתְעוֹרֵר לְהִטַּהֵר, מְסַיְּעִים אוֹתוֹ. בֹּא רְאֵה שֶׁכָּךְ הוּא, שֶׁכֵּיוָן שֶׁכָּתוּב לָלֶכֶת אַרְצָה כְּנַעַן, מִיָּד - וַיֹּאמֶר ה' אֶל אַבְרָם לֶךְ לְךְ. וְעַד שֶׁהוּא הִתְעוֹרֵר בַּתְּחִלָּה, לֹא כָתוּב לֶךְ לְךְ."],[11,"","בֹּא רְאֵה, הַדָּבָר שֶׁלְּמַעְלָה לֹא מִתְעוֹרֵר עַד שֶׁמִּתְעוֹרֵר לְמַטָּה בָּרִאשׁוֹנָה עַל מַה שֶּׁיִּשְׁרֶה עָלָיו אוֹתוֹ שֶׁלְּמַעְלָה. וְסוֹד הַדָּבָר - הָאוֹר הַשָּׁחֹר אֵינוֹ נֶאֱחָז בָּאוֹר הַלָּבָן עַד שֶׁהִיא מִתְעוֹרֶרֶת בָּרִאשׁוֹנָה. כֵּיוָן שֶׁהִיא מִתְעוֹרֶרֶת בָּרִאשׁוֹנָה, מִיָּד שׁוֹרֶה עָלֶיהָ הָאוֹר הַלָּבָן."],[12,"","וְעַל זֶה כָּתוּב (שם פג) אֱלֹהִים אַל דֳּמִי לָךְ אַל תֶּחֱרַשׁ וְאַל תִּשְׁקֹט אֵל, כְּדֵי שֶׁלֹּא יִפָּסֵק הָאוֹר הַלָּבָן מִן הָעוֹלָם לְעוֹלָמִים. וְכֵן (ישעיה סב) הַמַּזְכִּירִים אֶת ה' אַל דֳּמִי לָכֶם, כְּדֵי לְעוֹרֵר לְמַטָּה בְּמַה שֶּׁתִּשְׁרֶה הַהִתְעוֹרְרוּת שֶׁלְּמַעְלָה. וְכֵן כֵּיוָן שֶׁמֵּעִיר אָדָם הִתְעוֹרְרוּת (טובה) בָּרִאשׁוֹנָה, אָז מִתְעוֹרֶרֶת הִתְעוֹרְרוּת שֶׁלְּמַעְלָה. בֹּא רְאֵה, כֵּיוָן שֶׁכָּתוּב וַיֵּצְאוּ אִתָּם מֵאוּר כַּשְׂדִּים וְגוֹ', מִיָּד - וַיֹּאמֶר ה' אֶל אַבְרָם וְגוֹ'."],[13,"","וַיֹּאמֶר ה' אֶל אַבְרָם לֶךְ לְךְ. אָמַר רַבִּי אֶלְעָזָר, לֶךְ לְךְ - לְעַצְמְךְ, לְתַקֵּן אֶת עַצְמְךְ, (להתחזק) לְתַקֵּן אֶת דַּרְגָּתְךְ. לֶךְ לְךְ - אֵינְךְ (ס\"א כדאי) לַעֲמֹד כָּאן בֵּין הָרְשָׁעִים הַלָּלוּ."]]],[["וְרָזָא דְמִלָּה לֶךְ לְךָ דְּהָא קוּדְשָׁא בְּרִיךְ הוּא יָהִיב לֵיהּ לְאַבְרָהָם רוּחָא דְחָכְמְתָא, וְהֲוָה יָדַע וּמְצָרֵף (צנורי) סִטְרֵי דְּיִישׁוּבֵי עָלְמָא, וְאִסְתַּכַּל בְּהוּ וְאַתְקַל בְּתִיקְלָא וְיָדַע חֵילִין דִּי מְמַנָּן עַל סִטְרֵי יִישׁוּבָא.","כַּד מָטָא לְגוֹ נְקוּדָה דְּאֶמְצָעִיתָא דְיִישׁוּבָא תָּקִיל בְּתִיקְלָא וְלָא הֲוָה סָלִיק בְּיָדֵיהּ. אַשְׁגַּח לְמִנְדַע חֵילָא דִי מְמַנָּא עֲלָהּ וְלָא יָכִיל לְאִתְדַּבְּקָא בִּרְעוּתֵיהּ,","תָּקִיל כַּמָּה זִמְנִין וְחָמָא דְּהָא מִתַּמָּן אִשְׁתִּיל כָּל עָלְמָא, אַשְׁגַּח וְצָרַף וְתָקַל לְמִנְדַע וְחָמָא דְּהָא חֵילָא עִלָּאָה דְּעֲלָהּ לֵית לֵיהּ שִׁעוּרָא עָמִיק וְסָתִים וְלָאו אִיהוּ כְּגַוְונֵי דְּסִטְרֵי דַּרְגֵּי דְיִשּׁוּבָא.","אַשְׁגַח וְתָקִיל וְיָדַע דְּהָא כְּמָּה דְּמֵהַהִיא נְקוּדָה אֶמְצָעִיתָא דְּיִשּׁוּבָא מִנֵּיהּ אִשְׁתִּיל כָּל עָלְמָא לְכָל סִטְרוֹי. הָכִי נָמֵי יָדַע דְּהָא חֵילָא דְּשָׁרֵי עֲלָהּ מִתַּמָּן נָפְקוּ כָּל שְׁאָר חֵילִין דִּמְמַנָן עַל כָּל סִטְרֵי עָלְמָא, וְכֻלְהוּ בֵּיהּ אֲחִידָן. כְּדֵין (בראשית י״א:ל״א) וַיֵּצְאוּ אִתָּם מֵאוּר כַּשְׂדִים לָלֶכֶת אַרְצָה כְּנַעַן.","עוֹד אַשְׁגַּח וְתָקִיל וְצָרִיף לְמֵיקַם עַל בְּרִירָא דְמִלָּה דְּהַהוּא אֲתַר וְלָא הֲוָה יָדַע וְלָא יָכִיל לְמֵיקַם עֲלָהּ לְאִתְדַּבְּקָא, כֵּיוָן דְּחָמָא תּוּקְפָא דְּהַאי אֲתַר וְלָא יָכִיל לְמֵיקַם עֲלֵיהּ מִיָּד וַיָּבֹאוּ עַד חָרָן וַיֵּשְׁבוּ שָׁם.","מַאי טַעְמָא דְאַבְרָהָם. אֶלָּא דְּאִיהוּ הֲוָה יָדַע וְצָרִיף בְּכָל אִנּוּן שָׁלְטָנִין מְדַבְּרֵי עָלְמָא בְּכָל סִטְרוֹ דְיִשּׁוּבָא, וְהֲוָה תָּקִיל וְצָרִיף אִנּוּן דְּשָׁלְטִין בְּסִטְרֵי דְיִשּׁוּבָא מְדַבְּרֵי כֹּכְבַיָא וּמַזָּלֵיהוֹן, מַאן אִנּוּן תַּקִּיפִין אִלֵּין עַל אִלֵּין, וְהֲוָה תָּקִיל כָּל יִשּׁוּבֵי דְעָלְמָא (ולא) וְהֲוָה סָלִיק בִּידוֹי. כַּד מָטָא לְהַאי אֲתַר חָמָא תַּקִּיפוּ דְּעֲמִיקִין וְלָא יָכִיל לְמֵיקַם בֵּיהּ.","כֵּיוָן דְּחָמָא קוּדְשָׁא בְּרִיךְ הוּא אִתְעֲרוּתָא דִילֵיהּ וְתִיאוּבְתָּא דִילֵיהּ. מִיָּד אִתְגְּלִי עֲלֵיהּ וְאָמַר לֵיהּ לֶךְ לְךָ. לְמִנְדַע לָךְ וּלְאַתְקָנָא גַּרְמָךְ.","מֵאַרְצְךָ, מֵהַהוּא סִטְרָא דְיִשּׁוּבָא דְּהֲוִית מִתְדַּבַּק בֵּיהּ. וּמִמּוֹלַדְתְּךָ, מֵהַהוּא חָכְמָה דְּאַתְּ מַשְׁגַּח וְתָקִיל תּוֹלְדָתָא דִילָךְ וְרִגְעָא וְשַׁעֲתָא וְזִמְנָא דְּאִתְיְילִידַת בֵּיהּ וּבְהַהוּא כּוֹכָבָא וּבְהַהוּא מַזָּלָא.","וּמִבֵּית אָבִיךָ, דְּלָא תַשְׁגַּח בְּבֵיתָא דְּאֲבוּךְ. וְאִי אִית לָךְ שָׁרְשָׁא לְאַצְלָחָא בְּעָלְמָא מִבֵּיתָא דְּאֲבוּךְ, בְּגִין כָּךְ לֶךְ לְךָ מֵחָכְמָה דָּא וּמֵאַשְׁגָּחוּתָא דָּא.","תָּא חֲזֵי, דְּהָכִי הוּא, דְּהָא נָפְקוּ מֵאוּר כַּשְׂדִּים וְהֲווּ בְּחָרָן, אַמַּאי יֵימָא לֵיהּ לֶךְ לְךָ מֵאַרְצְךָ וּמִמּוֹלַדְתְּךָ. אֶלָּא עִקְּרָא דְמִלְּתָא כְּמָה דְּאִתְּמָר. אֶל הָאָרֶץ אֲשֶׁר אַרְאֶךָּ. אַרְאֶךָּ מַה דְּלָא יְכִילַת לְמֵיקַם עֲלֵיהּ וְלָא יְכִילַת לְמִנְדַע חֵילָא דְּהַהִיא אַרְעָא דְּאִיהוּ עָמִיק וְסָתִים:","וְאֶעֶשְׂךָ לְגוֹי גָדוֹל וְגו' וְאֶעֶשְׂךָ, בְּגִין דִּכְתִיב לֶךְ לְךָ. וַאֲבָרַכֶךָּ, בְּגִין דִּכְתִיב מֵאַרְצְךָ. וַאֲגַדְּלָה שְׁמֶךָ, בְּגִין דִּכְתִיב וּמִמּוֹלַדְתְּךָ. וְהְיֵה בְּרָכָה, בְּגִין דִּכְתִיב וּמִבֵּית אָבִיךָ.","רַבִּי שִׁמְעוֹן אָמַר וְאֶעֶשְׂךָ לְגוֹי גָדוֹל מִסִּטְרָא דְּיָמִינָא. וַאֲבָרַכֶךָּ מִסִּטְרָא דִּשְׂמָאלָא וַאֲגַדְּלָה שְׁמֶךָ מִסִּטְרָא דְאֶמְצָעִיתָא. וְהְיֵה בְּרָכָה מִסִּטְרָא דְאַרְעָא דְיִשְׂרָאֵל. הָא הָכָא כֻּרְסְיָיא דְּאַרְבַּע סָמְכִין דְּכֻלְהוּ כְּלִילָן בֵּיהּ בְּאַבְרָהָם, מִכָּאן וּלְהָלְאָה בִּרְכָאן לְאַחֲרִינֵי דְּמִתְּזְנֵי מֵהָכָא דִּכְתִיב וַאֲבָרְכָה מְבָרַכֶיךָ וּמְקַלֶּלְךָ אָאוֹר וְנִבְרְכוּ בְךָ כֹּל מִשְׁפְּחוֹת הָאֲדָמָה."],[[0,"ורזא דמלה וכו':","וסוד הדבר בפירוש המלות \u0003לך לך,\u0004 כי הקב\"ה נתן לאברהם רוח החכמה והיה יודע ומצרף את הרוחות של ישובי העולם. והיה מסתכל בהם ושקלם במאזנים, וידע והשיג הכחות הממונים על רוחות הישוב."],[0,"","פירוש. כי הקשה לו כיון שכתוב, ויצאו מאור כשדים ויבואו עד חרן וישבו שם, א\"כ כבר יצאו מארצם ומולדתם, ולמה אמר לו הקב\"ה לך לך מארצך וממולדתך. אכן כשנדע פנימיות הדברים הללו, לא יקשה לנו כלום, וזהו שמבאר לפנינו. וצריך שתדע סוד כחו של נמרוד של אברהם להשליכו אל כבשן האש, שה\"ס אור כשדים, וכן סוד הצלתו מכבשן האש."],[0,"","והענין הוא, כי כל הדינים והקליפות נמשכים מקו שמאל מסוד הארת השורק שה\"ס חכמה בלי חסדים שהוא אש שורף, (כנ\"ל דף ב' אות ד' ד\"ה פירוש) והראש שלהם היה אז נמרוד, כמ\"ש, הוא החל להיות גבור ציד לפני ה'. ולפיכך בעת שאברהם המשיך לו את המוחין העליונים הללו, שנמשכים בג' קוין זה אחר זה, והגיע וקבל הארת קו השמאל שה\"ס הארת נקודת השורק, תכף נפל תחת שליטת נמרוד, שהשליכו לכבשן האש, הנמשך מכח גבורת הארת השורק, ואז עזרו הקב\"ה שימשיך את הארת קו האמצעי על המסך דחירק, המכריע ועושה שלום בין ב' הקוין ימין ושמאל, והחכמה שבשמאל מתלבשת ונכללת בהחסדים שבימין, שאז מאירין המוחין בכל השלימות, והדינים מתבטלים כנודע, ועל ידי זה נצל אברהם מכבשן האש, ויצא מאור כשדים, וזכה להתגלות ה'. בסו\"ה ויאמר ה' אל אברם לך לך וגו'."],[0,"","ונתבאר לעיל (בפרשת נח דף צ\"ג אות רס\"ג ד\"ה ביאור) שהמסך דחירק, שעליו יוצא קו האמצעי, נמשך ממדת הדין שבמלכות, שלא נמתק ברחמי הבינה, המכונה \u0003מנעולא.\u0004 ע\"ש. והוא מטעם, כי הימין והשמאל הם במחלוקת, להיותם בסוד ב' כתובים המכחישים זה את זה, (כנ\"ל בראשית א' דף נ\"ז אות מ\"ד ד\"ה וזה) שבהיות קו השמאל נמשך מהארת השורק, הנמשך מבינה שחזרה לראש א\"א, ע\"כ כחו רב ורוצה לבטל הארת הימין, הנמשך מנקודת החולם, דהיינו מהבינה בעת שהיתה לחוץ מראש א\"א. ובהיות קו הימין השורש אל קו השמאל, ע\"כ רוצה לבטל את תקפו של קו השמאל ולהכניעו, כיחס השורש אל הענף שלו. ולפיכך אין קו השמאל נכנע להכלל בקו הימין, זולת ע\"י ב' ענינים שפועלים בו: א' המסך דחירק. ב' קו האמצעי שה\"ס קומת החסדים היוצאת על המסך הזה. ענין הא' בא למעט את קו השמאל מבחינת ג\"ר אל בחינת ו\"ק דחכמה. ופעולה זו נעשתה ע\"י המסך דחירק. מטרם שיוצאת עליו קומת אור החסדים. ענין הב' בא לפעול, הזווג דהכאה עם אור העליון שנעשה על מסך דחירק הזה, המוציא קומת החסדים, כי אז מתוך שמצד אחד ירד קומת קו השמאל לבחינת ו\"ק דחכמה, ואין מעלתו גבוה עתה מקו הימין. ומצד הב' נתרבו החסדים מב' הצדדים של קו השמאל, (כמ\"ש בזהר אמור אות ר') אברהם מהאי סטרא ויעקב מהאי סטרא. דהיינו מקו ימין המכונה אברהם, ומקו אמצעי המכונה יעקב. ע\"כ נכנע קו השמאל המכונה יצחק, ונכלל בתוך החסדים של הימין והאמצעי. אמנם כל זמן שלא נתמעט קו השמאל מהג\"ר שלו, לא יועיל שום כח להכליל אותו בקו הימין."],[0,"","ולפיכך אין קו האמצעי יכול להכריע וליחד ב' הקוין מטרם שהמסך דחירק יוכל למעט את קו השמאל לבחינת ו\"ק דחכמה. והנה בעת שב' הקוין מאירים בהמדרגה נמצאת המלכות דנוקבא בהכרח, בסוד נקודה דאמצעיתא דישובא, שה\"ס המפתחא (כנ\"ל בהקדמת הזהר דף קכ\"ג אות קכ\"ב ד\"ה ב') שפירושה, שהמלכות נמתקת לגמרי בהבינה וקבלה צורת הבינה, בסוד \u0003אמא אוזיפת לברתא מאנהא,\u0004 (כנ\"ל בהק' הזהר דף כ' אות י\"ז) כי בלי זה אין המלכות ראויה לקבל שום אור ישר הנמשך ממעלה למטה. (כנ\"ל בראשית א' דף ז' אות ג' ד\"ה וכבר) וע\"כ כשרוצים להמשיך בה סוד המנעולא, שהוא עצמות המלכות שלא נמתקה בבינה, כדי שתמעט את הקו שמאל לו\"ק דחכמה, צריכים לד' פעולות. פעולה א' הוא להמשיך שם סוד צמצום א' שנעשה על המלכות שלא תקבל אור. ופעולה זו מבוארת כאן באות כ\"ג. פעולה ב' הוא לגלות הדינים בסוד המסך שבצמצום א'. ופעולה זו מבוארת באות כ\"ד, שעתה נשלמת בהמלכות, בחינת מדת הדין בלי מיתוק הבינה, הנקראת \u0003מנעולא.\u0004 פעולה ג' להעלות המנעולא הזאת ממקום המלכות למקום בינה. כדי למעט משם את הקו שמאל לבחינת ו\"ק דחכמה. והיא מבוארת באות כ\"ה. פעולה ד' הוא הזווג היוצא על המסך הזה, שנשלמים בו המוחין בכל השלימות והיא מבוארת באות כ\"ז."],[0,"","וזה אמרו כאן, \u0003דהא קב\"ה יהיב ליה לאברהם רוחא דחכמתא.\u0004 דהיינו שקבל רוח החכמה בסוד ב' הקוין ימין ושמאל, כי הארת השמאל הנמשכת מנקודת השורק, סופו לגלות רוח החכמה כנ\"ל. \u0003והוה ידע ומצרף סטרי דישובי עלמא\u0004 והיה יודע ומברר הצדדים של ישוב העולם, דהיינו צד הימין וצד השמאל המאירים בהמלכות בהמקום שמחזה ולמטה. שהוא המקום הנקרא \u0003ישוב העולם,\u0004 משום ששם מתגלה החכמה, שאין בני אדם נשלמים זולתה. אבל מחזה ולמעלה של המלכות אין שם מקום ישוב, כי שם לא יוכלו להאיר אורות החכמה לבני אדם. \u0003ואסתכל בהו ואתקל בתקלא וידע חילין די ממנן על סטרי ישובא,\u0004 והסתכל אברהם בב' הקוין, ושקל אותם במאזנים כלומר שהמשיך הארת החכמה שהמשכתה מכונה משקל (כנ\"ל בראשית א' דף ש\"ג אות שפ\"ז) וידע הכחות הממונים על צדדי הישוב, דהיינו שהמשיך ההארות שבצד ימין וצד שמאל וידע אותם."],[1,"כד מטא לגו נקודה דאמצעיתא דיישובא וכו':","כשהגיע אל נקודה האמצעית דישוב, שה\"ס נקודת המלכות מבחינת מפתחא (כנ\"ל בדיבור הסמוך) שקל במאזנים ולא עלה בידו כלומר שהעלה מ\"ן להמשיך שם רוח החכמה ולא נמשך לו. הסתכל לדעת את הכוח הממונה עליה, וכוונתו לא הספיקה להשיג אותה. פירוש, אחר שהמשיך ב' הקוין ימין ושמאל, מטרם שהמשיך קו האמצעי, נאחז בו נמרוד הרשע והשליכו לכבשן האש, שה\"ס אור כשדים. ולפיכך עזרו הקב\"ה להמשיך את קו האמצעי כדי להצילו מכבשן האש ולהוציאו מאור כשדים, כנ\"ל בדיבור הסמוך. ונתבאר שם שהוצרך לד' פעולות עד לגלות קו האמצעי, ופעולה הא' מבוארת כאן, וז\"ש \u0003כד מטא לגו נקודה וכו'\u0004 כלומר שהגיע להמשיך את קו האמצעי, שפעולה הא' היא שנגלה לו בחינת צמצום א' בנקודת המלכות, וע\"כ \u0003תקיל בתיקלא ולא הוה סליק בידיה,\u0004 כי אחר שרבצה כח צמצום א' על המלכות לא יכלה לקבל לתוכה שום אור ישר. וכיון שראה שאינה מקבלת אור, \u0003אשגח למנדע חילא די ממנא עלה,\u0004 הסתכל לראות ולבדוק את כח המפתחא השולט עליה, שבסגולתה ראויה לקבל האורות, אבל לא יכול להשיג עוד שם את כח הזה, והוא משום, שנמשך עליה כח צמצום א', שהיא חלק הנקודה שאינה נמתקת בהבינה, כנ\"ל. אמנם עוד לא מצא שם כח הדין, כי כח הדין אינה נגלה עוד בצמצום א' עצמו, אלא בסגולת המסך שנתקן שם, אחר הצמצום, (כנ\"ל בראשית א' דף ב' אות א' ד\"ה ומתוך ע\"ש) שמסך הזה נקרא מנעולא. וזהו שנעשה בפעולה הב', שנתבאר להלן בדבור הסמוך."],[2,"תקיל כמה זמנין וחמא דהא מתמן אשתיל כל עלמא וכו':","שקל כמה פעמים וראה שמשם נשתל ונתיסד כל העולם. פירוש, מכח ששקל הרבה פעמים ולא עלה בידו להמשיך שם אור, נגלה עי\"ז כח הדין שבה, מבחינת המסך שנעשה בהמלכות אחר צמצום א'. ואז ראה והכיר שמהמסך הזה נתיסד כל העולם. דהיינו שנתיסד בו המלכות שנקראת עולם. \u0003אשגח וצרף ותקל למנדע, וחמא דהא חילא עלאה דעלה לית ליה שיעורא עמיק וסתים,\u0004 הסתכל ובירר ושקל לדעת הענין, וראה כי כח העליון שעליה אין לו שיעור, והוא עמוק וסתום. פירוש. כי ראה בנקודת המלכות את כח העליון הנקרא מנעולא, כי עתה נגלה לו שכח הזה שולט בה, שהוא נבחן שאין לו שיעור והוא עמוק וסתום שאין לפתחו. והוא מטעם, שלא יתכן השגה ותפיסא, אלא עם התלבשות האור, ובכל מקום ששולט כח המנעולא אי אפשר להמשיך שם אור העליון. כנ\"ל. וע\"כ אין שום השגה ותפיסא שם. אמנם עודנו אינו מספיק לבחינת מסך דחירק לקו האמצעי, כי מסך הזה אינו שולט רק בהמלכות לבד ולא כלום בט' ספירות הראשונות, וע\"כ אין בכחו עוד למעט את קו השמאל, שהוא מט\"ר לבחינת ו\"ק, שזהו כל הנרצה ממסך הזה, כנ\"ל בדבור הסמוך. וזהו שמדייק, \u0003ולאו איהו כגווני דסטרי דרגי דישובא,\u0004 שהיא אינה דומה לספירות של בחינת הישוב. דהיינו לט\"ר. כי הט\"ר עודם בבחינת מפתחא, והנקודה דמלכות כבר היא בבחינת מנעולא. ובכדי שיפעול גם על ט\"ר, שבכללם הוא קו השמאל, צריכים לפעולה ג', שתתבאר לפנינו בדבור הסמוך."],[3,"אשגח ותקיל וידע דהא כמה דמההיא נקודה אמצעיתא דישובא מניה אשתיל כל עלמא לכל סטרוי:","הסתכל ושקל וידע כי כמו שנקודה האמצעית דישוב. דהיינו נקודה דמפתחא, שעלתה לבינה, שמשום זה נשתל ממנה כל העולם לכל קצותיו דהיינו שהיא שולטת על כל ספירת ז\"א וכל ספירות הנוקבא, המכונים קצוות העולם מטעם היותה למעלה מהם. \u0003הכי נמי ידע, דהא חילא דשרי עלה, מתמן נפקו כל שאר חילין דממנן על כל סטרי עלמא\u0004 כן ידע, שהכח השורה עתה על הנקודה, שהיא בחינת המנעולא, עלתה ג\"כ להבינה, ומשום זה, נמשכים ויוצאים ממנה כל שאר הכחות הממונים על כל קצוות העולם, כלומר, כיון שעלתה לבינה נמשכה משם שליטתה בכל ספירות ז\"א וכל ספירות הנוקבא, המכונים קצוות העולם. ועל ידי זה נתמעט ג\"כ הקו שמאל של הנוקבא, ונעשה לו\"ק דחכמה, שאינו נחשב לאור ישר. אע\"פ שהקו שמאל היא מט\"ס ראשונות, כי מכח עלית המנעולא למעלה לבינה, היא שולטת וממעטת את אור ישר דהיינו הג\"ר, מכל הט\"ס ראשונות. \u0003וכלהו ביה אחידן,\u0004 וכל הספירות נאחזו עתה בנקודת המנעולא, \u0003כדין ויצאו אתם מאור כשדים ללכת ארצה כנען,\u0004 אז, אחר שנתמעט קו השמאל מג\"ר, וירד לבחינת ו\"ק ואין מעלתו גבוה מקו הימין. פקע כח שליטתו, ונצל אברהם מכבשן האש ויצא מאור כשדים. כי עתה שנפל לו\"ק, הוא נכנע לקו הימין (כנ\"ל דף י\"ג אות כ\"ב ד\"ה ונתבאר ע\"ש) אמנם אינו נכנע לגמרי להתכלל בהחסדים שבימין מטרם שנעשה הזווג מאור העליון על מסך דחירק הזה, ומוציא קומת החסדים, כמ\"ש שם, ופעולה הזאת תתבאר לפנינו להלן באות כ\"ח."],[4,"עוד אשגח ותקיל וצריף למיקם על ברירא דמלה דההוא אתר:","עוד הסתכל ושקל וברר, לעמוד באופן ברור על אותו המקום, \u0003ולא הוה ידע, ולא יכיל למיקם עלה לאתדבקא,\u0004 ולא היה יודע, ולא היה יכול לעמוד עליה כדי להדבק בה. פירוש, שנתכפלו עליו הדינין, כי עד עתה היו רק בחינת הדינין מכח הארת השמאל, שלא היה יכול להתדבק בהארתו, להיותו אש שורף מכח חסרון חסדים כנ\"ל. ועתה אחר שהמנעולא עלתה לבינה ומיעטה את קו השמאל לבחינת ו\"ק, ומטרם שנעשה הזווג להמשכת חסדים, נמצא שמלבד ששלטו עוד עליו דינין הקודמים מהארת השמאל, שמשום זה, \u0003ולא יכיל למיקם עלה לאתדבקא,\u0004 נתוספו עליו עתה הדינין של ביטול הג\"ר, \u0003ולא הוה ידע.\u0004 ונמצאו עתה הדינין כפולים. \u0003כיון דחמא תוקפא דהאי אתר,\u0004 כיון שראה תוקף הדינין של מקום הזה, דהיינו ביטול הג\"ר, \u0003ולא יכיל למיקם עלה,\u0004 וגם לא יכול לעמוד עליו להדבק בו, מחמת שגם הדינין דהארת השמאל נשארו בשליטתם, שהם אש שורף, \u0003מיד, ויבואו עד חרן וישבו שם,\u0004 ופירוש, השם \u0003חרן\u0004 יורה חרון אף, על מה שנתכפלו עליו הדינין, ומשמיענו הכתוב, כי מלבד שלא בא לארץ כנען, שה\"ס ארץ מוציאה פירות, הרומז על המקום שמחזה ולמטה של הנוקבא, הוא בא למקום \u0003חרן\u0004 דהיינו לחרון אף, כי נתכפלו עליו הדינין כנ\"ל. וישבו שם."],[5,"מאי טעמא דאברהם:","שואל מהו הטעם שאברהם נתעכב בחרן ולא הלך משם תכף לארץ כנען, כי הכתוב אומר \u0003וישבו שם.\u0004 ואומר, \u0003אלא דאיהו הוה ידע וצריף בכל אינון שלטנין מדברי עלמא בכל סטרו דישובא\u0004 שאברהם היה יודע ומברר כל אלו השליטים מנהיגי העולם בכל רוחות הישוב. שהם באים מכח המנעולא, שהיא בחינת נקודה אמצעית מכללות כל העולם (כנ\"ל בהק' הזהר דף מ\"ד אות מ\"א ד\"ה ביאור) \u0003והוה תקיל וצריף אינון דשלטין בסטרי דישובא מדברי ככביא ומזליהון,\u0004 וכן היה שוקל ומברר את אלו השולטים ברוחות הישוב, שהם מנהיגי הככבים ומזלות, דהיינו הבאים מכח המפתחא, שהיא נמשכת מהבינה, בסוד אמא אוזיפת לברתא מאנהא. (כנ\"ל בהק' הזהר דף כ\"ה אות י\"ז) והארת הג\"ר דבינה מכונות \u0003ככבים,\u0004 והארת ז\"ת דבינה, מכונות \u0003מזלות.\u0004 וע\"כ השליטים הבאים ממפתחא מנהיגים אותם. \u0003מאן אינון תקיפין אלין על אלין\u0004 כמה הם חזקים אלו על אלו, כלומר שהיה שוקל כח אלו השליטים הנמשכים ממנעולא כלפי כח השליטים הבאים ממפתחא לדעת, מי מהם חזק יותר שיוכל לבטל את חברו. פירוש. כי לא יצא מאור כשדים, אלא אחר שהמנעולא עלתה לבינה, אשר אז נתגברו שליטי המנעולא על שליטי המפתחא השולטים בקצוות העולם והמעיטו אותם לבחינת ו\"ק, שבכללם נתמעט גם הקו שמאל לבחינת ו\"ק, ופקע כחו, ואז יצא מאור כשדים ובא לחרן. (כנ\"ל דף ט\"ו אות כ\"ה ד\"ה אשגח ע\"ש) ועתה כשבא לחרן, חזר על חקירתו וחזר ושקל ב' מיני השליטים מי מהם חזק יותר שיוכל לבטל את חבירו, והיה זה משום שעוד לא הרויח כלום עם צאתו מאור כשדים, אלא עוד, שנתוספו עליו דינים מביטול הג\"ר, ע\"כ ניסה, אולי יוכל עכ\"פ לחזור להשיב את הג\"ר דהארת השמאל. וע\"כ חזר ושקלם אלו כנגד אלו, והיה מקוה לראות, ששליטי המפתחא יהיו יותר חזקים משליטי המנעולא, ולא יתמעטו מג\"ר מחמתם. \u0003והוה תקיל כל ישובי דעלמא והוה סליק בידוי.\u0004 והיה שוקל כל ישובי העולם, דהיינו הט\"ס ראשונות, והיה עולה בידו. כלומר, שעלה בידו לברר כרצונו, אשר שליטי המפתחא חזקים יותר משליטי המנעולא, ואין הג\"ר שלהם מתבטלות מחמתם. \u0003כד מטא להאי אתר, חמא תקיפו דעמיקין, ולא יכיל למיקם ביה.\u0004 אבל כשהגיע למקום הזה, דהיינו לנקודת המלכות, ראה עצמת העמקים, דהיינו תוקף הדינין דמנעולא שהתחזקה על המפתחא וביטלה הג\"ר ולא יכול לעמוד בו. כלומר שלא היה יכול להתדבק בו, מכח הדינין דהארת השמאל, שעוד לא עברו, דהיינו שחזר עליו התכפלות הדינין, כנ\"ל. ולפי שעוד לא החליט בקביעת המסך דחירק, שהוא המסך דמנעולא אלא שהיה מנסה עוד לשקול הכחות של ב' מיני השליטים זה על זה. ע\"כ נתעכב בחרן, דהיינו בחרון אף, כמ\"ש \u0003וישבו שם.\u0004"],[6,"כיון דחמא קב\"ה, אתערותא דיליה ותיאובתא דיליה. מיד אתגלי עליה, ואמר ליה לך לך:","כיון שראה הקב\"ה את ההתעוררות שלו ואת התשוקה שלו, מיד נגלה עליו ואמר לו \u0003לך לך. למנדע לך ולאתקנא גרמך,\u0004 לדעת את עצמך, ולתקן את עצמך. כלומר, שיפסיק מלשקול את כחות העליונים, אלא שיעלה מ\"ן וימשיך זווג עליון על המסך הזה שנגלה לו, כנ\"ל, שבזה יזכה להמשיך דעת לעצמו, ויתקן את עצמו. וכאן נעשה פעולה הד' (הנ\"ל באות כ\"ב ד\"ה ולפיכך) שנמשכה קומת החסדים על מסך דחירק הנ\"ל, שה\"ס יציאת קו האמצעי המכריע על ב' הקוין ימין ושמאל, שכוללם יחד, שבזה נשלמו המוחין, ונגלו לו ונמשכו לו כל הברכות האמורים בכתוב הזה."],[7,"מארצך, מההוא סטרא דישובא דהוית מתדבק ביה וכו':","מארצך, היינו שאמר לו לך לך, מאותו צד של הישוב שהית דבוק בו, שהוא צד הימין בלי התכללות השמאל. \u0003וממולדתך\u0004 היינו שאמר לו לך לך, מאותו החכמה שהית מסתכל ושוקל התולדה שלך, והרגע והשעה והזמן שנולדת בו, ובאותו הכוכב ובאותו המזל. שכל זה הוא הארת השמאל בלי התכללות הימין, שהארה זו באה בכח המפתחא, שממנה באים מנהיגי הככבים ומזלות. כנ\"ל בדיבור הסמוך. ומה שהארת השמאל מכונה \u0003מולדתך,\u0004 וכן מ\"ש ששקל הרגע והזמן שנולד בו, הוא כי מוחין דהולדת נשמות, נמשכים רק מהארת השמאל, וע\"כ, המשא ומתן בו, דהיינו מה ששקל אברהם את הכחות אלו כנגד אלו (כנ\"ל בסמוך), נבחן כחוקר לדעת הרגע שנולד בו, לראות ולבדוק באיזה קומה נולד אז, אם מג\"ר אם מו\"ק, וכדומה."],[8,"ומבית אביך, דלא תשגח בביתא דאבוך וכו':","ומבית אביך, היינו שאמר לו לך לך, ולא תסתכל עוד בבית אביך, שהוא חרן, שלא תסתכל אם יש לך שורש להצליח בהעולם מבית אביך. כלומר שלא תשקול עוד ב' מיני השליטים אלו נגד אלו ולקוות להחזיר שליטת המפתחא שנעלמה, (כנ\"ל דף ט\"ז אות כ\"ו ד\"ה עוד) שפעולה זו הוא קליפת חרן, כמ\"ש שם. \u0003בגין כך לך לך מחכמה דא ומאשגחותא דא,\u0004 ועל כן לך לך מחכמה זו ומהסתכלות הזו."],[9,"תא חזי דהכי הוא וכו':","בוא וראה שכן הוא. כי כבר יצאו מאור כשדים, והיו בחרן, ולמה יאמר לו לך לך מארצך וממולדתך, הרי כבר יצא מאור כשדים שהיא ארצו ומולדתו. אלא עיקר הדבר הוא בהכרח, כמו שאמרנו, אשר מארצך פירושו מהארת הימין בלי השמאל, וממולדתך פירושו הארת השמאל בלי הימין."],[9,"אל הארץ אשר אראך:","פירושו, אראך, מה שלא יכולת לעמוד עליו, מכח הדינין דהארת השמאל, ולא יכולת לדעת הכח של ארץ ההיא, דהיינו המלכות, שהוא עמוק וסתום מכח הדינין דביטול הג\"ר כנ\"ל. ומעתה אני מבטיח אותך שיסורו ממך ב' מיני הדינין הללו. ויאירו לך המוחין בשלימות הג\"ר ובמתיקות הדביקות."],[10,"ואעשך לגוי גדול וכו':","ואעשך, הוא בזכות הכתוב לך לך. כלומר בזכות שהעלה מ\"ן וגרם זווג עליון על המסך דחירק, שהוציא קומת החסדים, שעי\"ז נשלמו המוחין העליונים כנ\"ל, בשביל זה זיכה הקב\"ה גם אותו באלו המוחין הגדולים, והיינו ההבטחה \u0003ואעשך לגוי גדול. ואברכך\u0004 הוא בזכות שכתוב מארצך. כלומר, ע\"י שפירש את עצמו מקו ימין הבלתי כלול בשמאל, זכה להארת הימין הנכלל עם הארת השמאל, שהארתו מרומזת בהכתוב ואברכך. ואגדלה שמך, הוא בזכות שכתוב וממולדתך, כלומר בזכות שפירש את עצמו מהארת השמאל הבלתי כלול בימין, זכה להבטחה המרומזת בהכתוב \u0003ואגדלה שמך,\u0004 שה\"ס הארת השמאל הכלולה בהחסדים שבימין."],[10,"והיה ברכה,","הוא בזכות שכתוב ומבית אביך. כלומר בזכות שפירש את עצמו מקליפת חרן השולטת בחרן שה\"ס בית אביך כנ\"ל, זכה להבטחה והיה ברכה, שה\"ס הארת קו האמצעי."],[11,"ר\"ש אמר וכו':","ר\"ש חולק, ואומר, \u0003ואעשך לגוי גדול\u0004 הוא הארת צד ימין. \u0003ואברכך\u0004 הוא הארת צד שמאל. ואגדלה שמך הוא הארת קו האמצעי. \u0003והיה ברכה\u0004 הוא מצד ארץ ישראל. כלומר מצד הנוקבא, המכונה ארץ ישראל. \u0003הא הכא כרסיא\u0004 וכו': הרי יש כאן, כסא של ארבע רגלים, דהיינו ג' קוין שהם חסד גבורה תפארת, שהם ג' רגלים, והנוקבא, שהיא רגל ד', שהם ארבע רגלים של כסא העליון, שהוא בינה. (להלן דף כ\"ז ד\"ה פירוש) מכאן ואילך הברכות הם לאחרים הנזונים מכאן, דהיינו שיתברכו אחרים בשבילו, שכתוב ואברכה מברכיך ומקללך אאור וגו'."]],[[0,"","וְסוֹד הַדָּבָר - לֶךְ לְךְ, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לְאַבְרָהָם רוּחַ שֶׁל חָכְמָה, וְהָיָה יוֹדֵעַ וּמְצָרֵף (צנורות) צִדְדֵי יִשּׁוּב הָעוֹלָם, וְהִסְתַּכֵּל בָּהֶם וְשָׁקַל בְּמִשְׁקָל וְיָדַע אֶת הַכֹּחוֹת הַמְמֻנִּים עַל צִדְדֵי הַיִּשּׁוּב."],[1,"","כְּשֶׁהִגִּיעַ לְתוֹךְ נְקֻדַּת אֶמְצַע הַיִּשּׁוּב, שָׁקַל בְּמִשְׁקָל וְלֹא הָיָה עוֹלֶה בְיָדוֹ. הִתְבּוֹנֵן לָדַעַת אֶת הַכֹּחַ שֶׁמְּמֻנֶּה עָלֶיהָ, וְלֹא יָכֹל לְהִתְדַּבֵּק בִּרְצוֹנוֹ."],[2,"","שָׁקַל כַּמָּה פְעָמִים, וְרָאָה שֶׁהִנֵּה מִשָּׁם נִשְׁתַּל כָּל הָעוֹלָם. הִתְבּוֹנֵן וְצֵרַף וְשָׁקַל לָדַעַת, וְרָאָה שֶׁהִנֵּה הַכֹּחַ הָעֶלְיוֹן שֶׁעָלֶיהָ אֵין לוֹ שִׁעוּר, עָמֹק וְנִסְתָּר, וְאֵינוֹ כְּמוֹ הַצְּדָדִים שֶׁל דַּרְגוֹת הַיִּשּׁוּב."],[3,"","הִתְבּוֹנֵן וְשָׁקַל וְיָדַע שֶׁהֲרֵי כְּמוֹ שֶׁמֵּהַנְּקֻדָּה הַהִיא אֶמְצָעִיתוֹ שֶׁל הַיִּשּׁוּב, מִמֶּנָּה נִשְׁתַּל כָּל הָעוֹלָם לְכָל צְדָדָיו. כָּךְ גַּם יָדַע שֶׁהֲרֵי הַכֹּחַ שֶׁשּׁוֹרֶה עָלֶיהָ, מִשָּׁם יָצְאוּ כָּל שְׁאָר הַכֹּחוֹת הַמְמֻנִּים עַל כָּל צִדְדֵי הָעוֹלָם, וְכֻלָּם אֲחוּזִים בּוֹ. אָז (בראשית יא) וַיֵּצְאוּ אִתָּם מֵאוּר כַּשְׂדִּים לָלֶכֶת אַרְצָה כְּנַעַן."],[4,"","עוֹד, הִשְׁגִּיחַ וְשָׁקַל וְצֵרַף לַעֲמֹד עַל בֵּרוּר הַדָּבָר שֶׁל אוֹתוֹ הַמָּקוֹם וְלֹא הָיָה יוֹדֵעַ, וְלֹא יָכֹל לַעֲמֹד עָלֶיהָ לְהַשִּׂיג. כֵּיוָן שֶׁרָאָה אֶת כֹּחוֹ שֶׁל הַמָּקוֹם הַזֶּה וְלֹא יָכֹל לַעֲמֹד עָלָיו, מִיָּד וַיָּבאוּ עַד חָרָן וַיֵּשְׁבוּ שָׁם."],[5,"","מָה הַטַּעַם שֶׁל אַבְרָהָם? אֶלָּא שֶׁהוּא הָיָה יוֹדֵעַ וּמְצָרֵף אֶת כָּל אוֹתָם הַשַּׁלִּיטִים מַנְהִיגֵי הָעוֹלָם בְּכָל צִדְדֵי הַיִּשּׁוּב, וְהָיָה שׁוֹקֵל וּמְצָרֵף אוֹתָם הַשּׁוֹלְטִים בִּצִדְדֵי הַיִּשּׁוּב מַנְהִיגֵי הַכּוֹכָבִים וְהַמַּזָּלוֹת שֶׁלָּהֶם מִי הֵם הַחֲזָקִים אֵלּוּ עַל אֵלּוּ. וְהָיָה שׁוֹקֵל אֶת כָּל יִשּׁוּבֵי הָעוֹלָם (ולא) וְהָיָה עוֹלֶה בְיָדוֹ. כְּשֶׁהִגִּיעַ לַמָּקוֹם הַזֶּה רָאָה אֶת חֹזֶק הָעֳמָקִים וְלֹא יָכֹל לַעֲמֹד בּוֹ."],[6,"","כֵּיוָן שֶׁרָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הִתְעוֹרְרוּתוֹ וּתְשׁוּקָתוֹ, מִיָּד הִתְגַּלָּה עָלָיו וְאָמַר לוֹ לֶךְ לְךְ, לָדַעַת אוֹתְךְ וּלְתַקֵּן עַצְמְךְ."],[7,"","מֵאַרְצְךָ - מֵאוֹתוֹ הַצַּד שֶׁל הַיִּשּׁוּב שֶׁהָיִיתָ נִדְבָּק בּוֹ. וּמִמּוֹלַדְתְּךְ - מֵאוֹתָהּ הַחָכְמָה שֶׁאַתָּה מִתְבּוֹנֵן וְשׁוֹקֵל אֶת תּוֹלַדְתְּךְ וְהָרֶגַע וְהַשָּׁעָה וְהַזְּמַן שֶׁנּוֹלַדְתָּ בּוֹ, וּבְאוֹתוֹ הַכּוֹכָב וּבְאוֹתוֹ הַמַּזָּל."],[8,"","וּמִבֵּית אָבִיךְ - שֶׁלֹּא תַשְׁגִּיחַ בְּבֵית אָבִיךְ. וְאִם יֵשׁ לְךְ שֹׁרֶשׁ לְהַצְלִיחַ בָּעוֹלָם מִבֵּית אָבִיךְ, מִשּׁוּם כָּךְ לֶךְ לְךְ מֵהַחָכְמָה הַזּוֹ וּמֵהַהַשְׁגָּחָה הַזּוֹ"],[9,"","בֹּא רְאֵה שֶׁכָּךְ הוּא, שֶׁהֲרֵי יָצְאוּ מֵאוּר כַּשְׂדִּים וְהָיוּ בְחָרָן, לָמָּה יֹאמַר לוֹ לֶךְ לְךְ מֵאַרְצְךְ וּמִמּוֹלַדְתְּךְ? אֶלָּא עִקַּר הַדָּבָר כְּמוֹ שֶׁנֶּאֱמַר. אֶל הָאָרֶץ אֲשֶׁר אַרְאֶךָּ. אַרְאֶךָּ - מַה שֶּׁלֹּא יָכֹלְתָּ לַעֲמֹד עָלָיו, וְלֹא יָכֹלְתָּ לָדַעַת אֶת כֹּחַ הָאָרֶץ הַהִיא שֶׁהוּא עָמֹק וְנִסְתָּר."],[10,"","וְאֶעָשְׂךָ לְגוֹי גָּדוֹל וְגוֹ'. וְאֶעֶשְׂךְ - מִשּׁוּם שֶׁכָּתוּב לֶךְ לְךְ. וַאֲבָרֶכְךְ - מִשּׁוּם שֶׁכָּתוּב מֵאַרְצְךְ. וַאֲגַדְּלָה שְׁמֶךְ - מִשּׁוּם שֶׁכָּתוּב מִמּוֹלַדְתְּךְ. וֶהְיֵה בְּרָכָה - מִשּׁוּם שֶׁכָּתוּב וּמִבֵּית אָבִיךְ."],[11,"","רַבִּי שִׁמְעוֹן אָמַר, וְאֶעֶשְׂךְ לְגוֹי גָּדוֹל - מִצַּד הַיָּמִין. וַאֲבָרֶכְךְ - מִצַּד הַשְּׂמֹאל. וַאֲגַדְּלָה שְׁמֶךְ - מִצַּד הָאֶמְצַע. וֶהְיֵה בְּרָכָה - מִצַּד שֶׁל אֶרֶץ יִשְׂרָאֵל. הִנֵּה כָּאן כִּסֵּא שֶׁל אַרְבָּעָה עַמּוּדִים שֶׁכֻּלָּם כְּלוּלִים בְּאַבְרָהָם. מִכָּאן וָהָלְאָה בְּרָכוֹת לָאֲחֵרִים שֶׁנִּזּוֹנִים מִכָּאן, שֶׁכָּתוּב וַאֲבָרְכָה מְבָרֲכֶיךְ. וּמְקַלֶּלְךְ אָאֹר וְנִבְרְכוּ בְךְ כֹּל מִשְׁפְּחֹת הָאֲדָמָה."]]],[["רַבִּי אֶלְעָזָר הֲוָה יָתִיב קַמֵּיהּ דְּרַבִּי שִׁמְעוֹן אֲבוֹי, וְהֲוֵי עִמֵיהּ רַבִּי יְהוּדָה וְרַבִּי יִצְחָק וְרַבִּי חִזְקִיָּה. אָמַר לֵיהּ רַבִּי אֶלְעָזָר לְרַבִּי שִׁמְעוֹן אֲבוֹי, הַאי דִכְתִיב לֶךְ לְךָ מֵאַרְצְךָ וּמִמּוֹלַדְתְּךָ, כֵּיוָן דְּכֻלְהוּ נָפְקוּ לְמֵהַךְ, אַמַּאי לָא אִתְּמָר לֵיהּ דְּכֻלְהוּ יִפְקוּן.","דְּהָא אַף עַל גַּב דְּתֶרַח הֲוָה פְּלַח לְעֲבוֹדָה זָרָה. כֵּיוָן דְּאִתְעַר בְּאִתְעֲרוּתָא טַב לְמֵיפַק בַּהֲדֵיהּ דְּאַבְרָהָם, וְחָמִינָן דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בִּתְיוּבְתָּא דְּחַיָּיבַיָא וּשְׁרָא לְמֵיפַק אַמַּאי לָא כְּתִיב לְכוּ לָכֶם, אַמַּאי לְאַבְרָהָם בִּלְחוֹדוֹי לֶךְ לְךָ.","אָמַר לֵיהּ רַבִּי שִׁמְעוֹן, אִי תֵימָא דְּתֶרַח כַּד נָפַק מֵאוּר כַּשְׂדִּים בְּגִין לְאַהֲדָרָא בִּתְשׁוּבָה הֲוָה, לָאו הָכִי. אֶלָּא כַּד נָפַק לְאִשְׁתְּזָבָא נָפַק, דְּהֲווּ כֻּלְהוּ בְּנֵי אַרְעֵיהּ בָּעָאן לְמִקְטְלֵיהּ. כֵּיוָן דְּחָזוּ דְּאִשְׁתְּזִיב אַבְרָהָם הֲווּ אָמְרֵי לֵיהּ לְתֶרַח, אַנְתְּ הוּא דְּהֲוִית מַטְעֵי לָן בְּאִלֵּין פְּסִילִין, וּמִגּוֹ דַּחֲלָא דִּלְהוֹן נָפַק תֶּרַח, כֵּיוָן דְּמָטָא לְחָרָן לָא נָפַק מִתַּמָּן לְבָתַר, דִּכְתִיב וַיֵּלֶךְ אַבְרָם כַּאֲשֶׁר דִּבֶּר אֵלָיו יְיָ וַיֵּלֶךְ אִתּוֹ לוֹט, וְאִילוּ תֶּרַח לָא כְּתִיב (ביה וילך, אלא ויצא).","פָּתַח וְאָמַר (איוב ל״ח:ט״ו) וַיִּמְנַע מֵרְשָׁעִים אוֹרָם וּזְרוֹעַ רָמָּה תְּשַׁבֵּר. הַאי קְרָא אוּקְמוּהָ, אֲבָל וַיִּמְנַע מֵרְשָׁעִים אוֹרָם, דָּא נִמְרוֹד וּבְנֵי דָּרֵיהּ דְּנָפַק אַבְרָהָם מִנַּיְיהוּ דְּהֲוָה אוֹרָם. וּזְרוֹעַ רָמָּה תְּשַׁבֵּר, דָּא נִמְרוֹד.","דָּבָר אַחֵר וַיִּמְנַע מֵרְשָׁעִים אוֹרָם, דָּא תֶּרַח וּבְנֵי בֵיתֵיהּ. אוֹרָם, דָּא אַבְרָהָם. הָאוֹר לָא כְּתִיב אֶלָּא אוֹרָם דְּהֲוָה עִמְּהוֹן. וּזְרוֹעַ רָמָּה תְּשַׁבֵּר, דָּא נִמְרוֹד דְּהֲוָה מַטְעֵי אֲבַתְרֵיהּ כָּל בְּנֵי עָלְמָא, וּבְגִין כָּךְ כְּתִיב לֶךְ לְךָ. בְּגִין לְאַנְהָרָא לָךְ וּלְכָל אִנּוּן דְּיִפְקוּן מִינָךְ מִכָּאן וּלְהָלְאָה.","תּוּ פָּתַח וְאָמַר, (איוב ל״ז:כ״א) וְעַתָּה לֹא רָאוּ אוֹר בָּהִיר הוּא בַּשְּׁחָקִים וְרוּחַ עָבְרָה וַתְּטַהֲרֵם. וְעַתָּה לא רָאוּ אוֹר, אֵימָתַי, בְּשַׁעֲתָא דְּאָמַר קוּדְשָׁא בְּרִיךְ הוּא לְאַבְרָהָם לֶךְ לְךָ מֵאַרְצְךָ וּמִמּוֹלַדְתְּךָ וּמִבֵּית אָבִיךָ. בָּהִיר הוּא בַּשְּׁחָקִים. דְּבָעָא קוּדְשָׁא בְּרִיךְ הוּא לְאַדְבָּקָא לֵיהּ לְאַבְרָהָם בְּהַהוּא אוֹר דִּלְעֵילָא וּלְאַנְהָרָא תַּמָּן.","וְרוּחַ עָבְרָה וַתְּטַהֲרֵם. דְּהָא לְבָתַר תָּבוּ בִּתְיוּבְתָּא תֶּרַח וְכָל בְּנֵי בֵיתֵיהּ (נ\"א וכל בני מאתיה). בְּנֵי בֵיתֵיהּ (נ\"א בני מאתיה) דִּכְתִיב וְאֶת הַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן. תֶּרַח, דִּכְתִיב וְאַתָּה תָבֹא אֶל אֲבוֹתֶיךָ בְּשָׁלוֹם וְגו'.","\u0003סִתְרֵי תּוֹרָה\u0004 וְאֶעֶשְׂךָ לְגוֹי גָדוֹל הַאי בִּרְכְּתָּא חָדָא, וַאֲבָרֶכְךָ תְּרֵין, וַאֲגַדְּלָה שְׁמֶךָ תְּלַתּ, וְהְיֵה בְּרָכָה אַרְבַּע. וַאֲבָרְכָה מְבָרֲכֶיךָ חָמֵשׁ, וּמְקַלֶּלְךָ אָאוֹר שִׁיתּ. וְנִבְרְכוּ בְךָ כָּל מִשְׁפְּחוֹתּ הָאֲדָמָה הא שֶׁבַע. כֵּיוָן דְּאִתְּבָּרְכוּ בְּאִלֵּין שֶׁבַע בִּרְכָאן, מַה כְּתִּיב וַיֵּלֶךָ אַבְרָם כַּאֲשֶׁר דִּבֶּר אֵלָיו יְיָ לְנָחֲתָּא לְהַאי עָלְמָא כְּמָה דְּאִתְּפָּקְדָא.","מִיָּד וַיֵּלֶךָ אִתּוֹ לוֹט. דָּא אִיהוּ נָחָשׁ דְּאִתְּלַטְיָא וְאִתְּלַטְיָא עָלְמָא בְּגִינֵיהּ דְּאִיהוּ קָאִים לְפִּתְּחָא לְאַסְטָאָה לְגוּפָּא, ולא תִּפְּעוֹל נִשְׁמָתָּא פּוּלְחָנָא דְאִתְּפַּקְדַתּ עַד דְּיַעַבְרוּן עֲלָהּ בְּהַאי עָלְמָא י\"ג שְׁנִין, דְּהָא מִתְּרֵיסַר שְׁנִין וּלְעֵילָא נִשְׁמָתָּא אִתְּעָרַתּ לְמִפְּלַח פּוּלְחָנא דְאִתְּפַּקְדַתּ הֲדָא הוּא דִכְתִּיב. וְאַבְרָם בֶּן חָמֵשׁ שָׁנִים וְשִׁבְעִים שָׁנָה. שֶׁבַע וְחָמֵשׁ תְּרֵיסַר אִנּוּן (ותרין עלאין עלייהו ארבע סרי אנון).","וּכְדֵין אִתְּחֲזִיאַתּ נִשְׁמָתָּא בְּהַאי עָלְמָא. דְּאִיהִי אַתְּיָא מֵחָמש שָׁנִים דְּאִנּוּן תּ\"ק פַּרְסֵי דְּאִילָנָא דְחַיֵּי. וְשִׁבְעִים שָׁנָה דָּא אִיהוּ הַהוּא אִילָנָא מַמָּשׁ דְּאִיהוּ שְׁבִיעָאָה לְדַרְגִּין וְשִׁבְעִין שָׁנָה אִתְּקְרֵי.","כְּדֵין נָפְּקַתּ מֵהַהוּא זוּהֲמָא דְנָחָשׁ וְעָאלַתּ בְּפּוּלְחָנָא קַדִּישָׁא הֲדָא הוּא דִכְתִּיב בְּצֵּאתּוֹ מֵחָרָן (ימי ע' שנה לא ספורות חיים מההוא ארבע סרי) מֵהַהוּא רוּגְזָא וְתּוּקְפָּא דְּהַהוּא (שטן) נָחָשׁ דְּהֲוָה אַסְטֵי לֵיהּ עַד הַשְׁתָּא לְגוּפָּא וְשָׁלְטָא עֲלוֹי.","בְּאִילָנָא שָׁלְטָא עָרְלָה תְּלַתּ שְׁנִין. בְּבַר נָשׁ תְּלַתּ סָרֵי שְׁנִין דְּאִקְרוּן שְׁנֵי עָרְלָה, כֵּיוָן דְּאַעֲבָרוּ עַל גּוּפָּא אִנּוּן שְׁנִין וְאִתְּעַבְרַתּ (ד\"א ואתערת) נִשְׁמָתָּא לְמִפְּלַח פּוּלְחָנָא קַדִּישָׁא, פְּקִידַתּ לְגוּפָּא לִרְעוּתָּא טָבָא, לִכְפּוֹף לְהַהוּא נָחָשׁ דְּהָא לָא יָכִיל לְשַׁלְטָאָה כְּמָה דְהַוִּי,"],[[0,"ר' אלעזר הוה יתיב וכו':","ר' אלעזר היה יושב לפני ר' שמעון אביו, והיה עמו ר' יהודה ור' יצחק ור' חזקיה. א\"ר אלעזר לר' שמעון אביו, מה זה שכתוב לך לך מארצך וממולדתך, כיון שכולם יצאו מאור כשדים ללכת ארץ כנען, למה לא נאמר לו שכולם ילכו."],[1,"דהא אע\"ג וכו':","כי הגם שתרח היה עובד עבודה זרה, אבל כיון שנתעורר בהתעוררות יפה לצאת עם אברהם, וראינו שהקב\"ה חפץ בתשובת הרשעים, והוא התחיל לצאת, למה לא כתוב. \u0003לכו לכם,\u0004 למה רק לאברהם לבדו נאמר \u0003לך לך.\u0004"],[2,"א\"ל ר\"ש אי תימא וכו':","אמר לו ר' שמעון, אם תחשוב, כשתרח יצא מאור כשדים, היה זה כדי לעשות תשובה, אינו כן. אלא כשיצא רק להנצל יצא, כי כל אנשי ארצו היו רוצים להורגו. כי אחר שראו שאברהם ניצל מכבשן האש, היו אומרים לתרח, אתה הוא, שהית מטעה אותנו בפסילים הללו, והיו רוצים להורגו, ומשום הפחד מפניהם יצא תרח. ולפיכך, כיון שהגיע לחרן, לא יצא עוד משם, כי כתוב, וילך אברם וגו' וילך אתו לוט, ואלו תרח לא נזכר בהכתוב."],[3,"פתח ואמר וימנע מרשעים אורם וכו':","מקרא זה כבר בארוהו. אבל וימנע רשעים אורם, זה נמרוד ובני דורו, שיצא אברהם מהם, שהוא היה אורם. וזרוע רמה תשבר, זהו נמרוד."],[4,"דבר אחר וימנע וכו':","פירוש אחר. וימנע מרשעים אורם, זהו תרח ובני ביתו. \u0003אורם\u0004 זהו אברהם. כי \u0003האור\u0004 לא כתוב אלא \u0003אורם,\u0004 שהיה עמהם. דהיינו אברהם שהיה עמהם, ויצא מהם. וזרוע רמה תשבר, זהו נמרוד שהיה מטעה אחריו כל בני העולם. ומשום זה כתוב \u0003לך לך,\u0004 כדי להאיר לך, ולכל אלו שיצאו ממך מכאן ואילך."],[5,"תו פתח ואמר, ועתה לא ראו אור:","ושואל אימתי היה זה. ואומר שזה היה, בשעה שאמר הקב\"ה לאברהם לך לך וגו'. כי לאחר שאברהם יצא מהם, לא ראו יותר אור, בהיר הוא בשחקים, סובב על אברהם שרצה הקב\"ה להדביק את אברהם באור העליון שיאיר שם."],[6,"ורוח עברה ותטהרם,","סובב על תרח ובני עירו, כי לאחר כך חזרו בתשובה, תרח וכל בני עירו. שכתוב, ואת הנפש אשר עשו בחרן, הרי שבני עירו עשו תשובה. תרח עשה תשובה, שכתוב ואתה תבא אל אבותיך בשלום. ואם תרח לא היה עושה תשובה, לא היה אומר לו הקב\"ה לאברהם, שיבא אל אבותיו בשלום."],[7,"ואעשך לגוי גדול וכו':","בכתוב הזה יש שבע ברכות. ואעשך לגוי גדול, אחת. ואברכך, שתים. ואגדלה שמך, שלש והיה ברכה, ארבע. ואברכה מברכיך, חמש. ומקללך אאור, שש. ונברכו בך כל משפחות האדמה, הרי שבע. ואחר שנתברך בשבע ברכות הללו, מה כתוב, וילך אברם כאשר דבר אליו ה', שפירושו, שהלך לירד לעולם הזה כמו שנצטוה. פירוש, כי אברהם הוא הנשמה (כמ\"ש לעיל אות י\"ג) ואחר שהנשמה נתברכה בשבע ברכות הנ\"ל, יורדת לעולם הזה להתלבש בגוף."],[8,"מיד וילך אתו לוט וכו':","זהו הנחש שנתקלל והעולם נתקלל בסבתו. כלומר, ע\"כ מכנה הכתוב להנחש בשם לוט, כי \u0003לוט,\u0004 פירושו קללה בלשון ארמית, והוא שנתקלל והביא קללה להעולם. והוא מתלוהאל הנשמה בעולם הזה. \u0003דאיהו קאים לפתחא וכו'\u0004 שהנחש עומד לפתח להשטות הגוף, כמ\"ש לפתח חטאת רובץ. וע\"כ לא תפעול הנשמה העבודה שנצטוית עד שיעברו עליה י\"ג שנים בעולם הזה. כי מי\"ב שנים ומעלה, הנשמה מתעוררת לעבוד העבודה שנצטוית, וז\"ש ואברם בן חמש שנה ושבעים שנה, שבעים במספר קטן הוא שבע, שבע וחמש הם י\"ב. ואז יוצאת הנשמה מחרן, שהוא הקליפות, ומתעוררת ללכת בעבודת השם."],[9,"וכדין אתחזיאת וכו'","ואז, אחר י\"ב שנה, תראה הנשמה בעולם הזה, שהיא באה \u0003מחמש שנים,\u0004 שהם חמש מאות פרסאות של עץ החיים, כלומר, שאז ניכרת, שהיא תולדה דז\"א הנק' עץ החיים ומהלכו ת\"ק פרסאות (כמ\"ש לעיל דף ח' ד\"ה ת\"ק ע\"ש) \u0003ושבעים שנה,\u0004 זהו אותו אילן ממש שהוא שביעי בהמדרגות, דהיינו הנוקבא שהיא ספירה שביעית מז\"ס חג\"ת נהי\"מ. ואז ניכרת הנשמה שהיא תולדה דז\"א ותולדה דנוקבא, כמ\"ש שם באורך."],[10,"כדין נפקת מההוא וכו':","אז יוצאת הנשמה מאותה הזוהמא של הנחש, ונכנסת בעבודה הקדושה, וז\"ש \u0003בצאתו מחרן,\u0004 מאותו חרון אף ומתוקפו של השטן, שעד עתה היה משטה את הגוף והיה שולט עליו."],[11,"באילנא שלטא ערלה וכו':","באילן שולט הערלה שלש שנים, שהם נקראים שני ערלה. ובבן אדם, שלש עשרה שנה נקראים בו שני ערלה. כיון שאלו השנים עוברות על הגוף, והנשמה מתעוררת לעבוד עבודה הקדושה, היא פוקדת את הגוף, ומעוררת בו רצון טוב, להכניע את הנחש הזה. ואז לא יוכל הנחש לשלוט עליו כמו שהיה מקודם לכן."]],[[0,"","רַבִּי אֶלְעָזָר הָיָה יוֹשֵׁב לִפְנֵי רַבִּי שִׁמְעוֹן אָבִיו, וְהָיָה עִמּוֹ רַבִּי יְהוּדָה וְרַבִּי יִצְחָק וְרַבִּי חִזְקִיָּה. אָמַר לוֹ רַבִּי אֶלְעָזָר לְרַבִּי שִׁמְעוֹן אָבִיו, זֶה שֶׁכָּתוּב לֶךְ לְךְ מֵאַרְצְךְ וּמִמּוֹלַדְתְּךְ, כֵּיוָן שֶׁכֻּלָּם יָצְאוּ לָלֶכֶת, לָמָּה לֹא נֶאֱמַר לוֹ שֶׁכֻּלָּם יֵצְאוּ?"],[1,"","שֶׁהֲרֵי אַף עַל גַּב שֶׁתֶּרַח הָיָה עוֹבֵד לַעֲבוֹדָה זָרָה, כֵּיוָן שֶׁהִתְעוֹרֵר בְּהִתְעוֹרְרוּת טוֹבָה לָצֵאת עִם אַבְרָהָם, וְרָאִינוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְרֻצֶּה מִתְּשׁוּבַת הָרְשָׁעִים, וְהִתְחִיל לָצֵאת, לָמָּה לֹא כָתוּב לְכוּ לָכֶם? לָמָּה לְאַבְרָהָם לְבַדּוֹ לֶךְ לְךְ?"],[2,"","אָמַר לוֹ רַבִּי שִׁמְעוֹן, אִם תֹּאמַר שֶׁתֶּרַח, כְּשֶׁיָּצָא מֵאוּר כַּשְׂדִּים, זֶה הָיָה כְּדֵי לַחֲזֹר בִּתְשׁוּבָה - לֹא כָּךְ! אֶלָּא כְּשֶׁיָּצָא, יָצָא לְהִנָּצֵל, שֶׁכָּל בְּנֵי אַרְצוֹ רָצוּ לַהֲרֹג אוֹתוֹ. כֵּיוָן שֶׁרָאוּ שֶׁנִּצַּל אַבְרָהָם, הָיוּ אוֹמְרִים לְתֶרַח: אַתָּה הוּא שֶׁהָיִיתָ מַטְעֶה אוֹתוֹ בַּפְּסִילִים הַלָּלוּ. וּמִתּוֹךְ הַהַפְחָדָה שֶׁלָּהֶם יָצָא תֶרַח. כֵּיוָן שֶׁהִגִּיעַ לְחָרָן, לֹא יָצָא מִשָּׁם אַחַר כָּךְ, שֶׁכָּתוּב וַיֵּלֶךְ אַבְרָם כַּאֲשֶׁר דִּבֶּר אֵלָיו ה' וַיֵּלֶךְ אִתּוֹ לוֹט. וְאִלּוּ תֶרַח לֹא כָתוּב (בו וילך, אלא ויצא)."],[3,"","פָּתַח וְאָמַר, (איוב לח) וְיִמָּנַע מֵרְשָׁעִים אוֹרָם וּזְרוֹעַ רָמָה תִּשָּׁבֵר. הַפָּסוּק הַזֶּה הֱקִימוּהוּ, אֲבָל וְיִמָּנַע מֵרְשָׁעִים אוֹרָם - זֶה נִמְרוֹד וּבְנֵי דוֹרוֹ שֶׁיָּצָא אַבְרָהָם מֵהֶם, שֶׁהָיָה אוֹרָם. וּזְרוֹעַ רָמָה תִּשָּׁבֵר - זֶה נִמְרוֹד."],[4,"","דָּבָר אַחֵר וְיִמָּנַע מֵרְשָׁעִים אוֹרָם - זֶה תֶרַח וּבְנֵי בֵיתוֹ. אוֹרָם - זֶה אַבְרָהָם. לֹא כָתוּב הָאוֹר אֶלָּא אוֹרָם, שֶׁהָיָה עִמָּהֶם. וּזְרוֹעַ רָמָה תִּשָּׁבֵר - זֶה נִמְרוֹד, שֶׁהָיָה מַטְעֶה אַחֲרָיו אֶת כָּל בְּנֵי הָעוֹלָם, וּמִשּׁוּם כָּךְ כָּתוּב לֶךְ לְךְ, כְּדֵי לְהָאִיר לְךְ וּלְכָל אוֹתָם שֶׁיֵּצְאוּ מִמְּךְ מִכָּאן וָהָלְאָה."],[5,"","עוֹד פָּתַח וְאָמַר, (שם לז) וְעַתָּה לֹא רָאוּ אוֹר בָּהִיר הוּא בַּשְּׁחָקִים וְרוּחַ עָבְרָה וַתְּטַהֲרֵם. וְעַתָּה לֹא רָאוּ אוֹר - מָתַי? בְּשָׁעָה שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְאַבְרָהָם לֶךְ לְךְ מֵאַרְצְךְ וּמִמּוֹלַדְתְּךְ וּמִבֵּית אָבִיךְ. בָּהִיר הוּא בַּשְּׁחָקִים - שֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַדְבִּיק אֶת אַבְרָהָם בָּאוֹר הַהוּא שֶׁלְּמַעְלָה וּלְהָאִיר שָׁם."],[6,"","וְרוּחַ עָבְרָה וַתְּטַהֲרֵם - שֶׁהֲרֵי אַחַר כָּךְ שָׁבוּ בִּתְשׁוּבָה תֶּרַח וְכָל בְּנֵי בֵיתוֹ (נ\"א: וכל בני עירו). בְּנֵי בֵיתוֹ (נ\"א: בני עירו), שֶׁכָּתוּב וְאֶת הַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן. תֶּרַח, שֶׁכָּתוּב וְאַתָּה תָבוֹא אֶל אֲבֹתֶיךְ בְּשָׁלוֹם וְגוֹ'."],[7,"","וְאֶעָשְׂךָ לְגוֹי גָּדוֹל. זּוֹ בְרָכָה אַחַת. וַאֲבָרֶכְךְ - שְׁתַּיִם. וַאֲגַדְּלָה שְׁמֶךְ - שָׁלֹשׁ. וֶהְיֵה בְּרָכָה - אַרְבַּע. וַאֲבָרְכָה מְבָרֲכֶיךְ - חָמֵשׁ. וּמְקַלֶּלְךְ אָאֹר - שֵׁשׁ. וְנִבְרְכוּ בְךְ כֹּל מִשְׁפְּחֹת הָאֲדָמָה - הִנֵּה שֶׁבַע. כֵּיוָן שֶׁהִתְבָּרֵךְ בְּשֶׁבַע הַבְּרָכוֹת הַלָּלוּ, מַה כָּתוּב? וַיֵּלֶךְ אַבְרָם כַּאֲשֶׁר דִּבֶּר אֵלָיו ה', לָרֶדֶת לָעוֹלָם הַזֶּה כְּפִי שֶׁהִצְטַוָּה."],[8,"","מִיָּד וַיֵּלֶךְ אִתּוֹ לוֹט. זֶה הַנָּחָשׁ שֶׁהִתְקַלֵּל וְהִתְקַלֵּל הָעוֹלָם בִּגְלָלוֹ, שֶׁהוּא עוֹמֵד לַפֶּתַח לְהַסְטִין לַגּוּף, וְלֹא תִפְעַל הַנְּשָׁמָה עֲבוֹדָה שֶׁהִצְטַוְּתָה עַד שֶׁיַּעַבְרוּ עָלֶיהָ בָּעוֹלָם הַזֶּה שְׁלֹשׁ עֶשְׂרֵה שָׁנִים. שֶׁהֲרֵי מִשְּׁנֵים עָשָׂר שָׁנִים וָמַעְלָה מִתְעוֹרֶרֶת הַנְּשָׁמָה לַעֲבֹד אֶת הָעֲבוֹדָה שֶׁהִצְטַוְּתָה. זֶהוּ שִּכָּתוּב, ואַברָם בִּן חָמשּ שָׁנִים וְשִׁבְעִים שָׁנָה. שֶׁבַע וְחָמֵשׁ הֵם שְׁנֵים עָשָׂר (ושני עליונים עליהם ארבעה עשר הם)."],[9,"","וְאָז נִרְאֵית הַנְּשָׁמָה בָּעוֹלָם הַזֶּה, שֶׁהִיא בָּאָה מֵחָמֵשׁ שָׁנִים שֶׁהֵם ת\"ק פַּרְסוֹת שֶׁל עֵץ הַחַיִּים. וְשִׁבְעִים שָׁנָה - זֶהוּ אוֹתוֹ אִילָן מַמָּשׁ, שֶׁהוּא שְׁבִיעִי לַדְּרָגוֹת וְנִקְרָא שִׁבְעִים שָׁנָה."],[10,"","אָז יוֹצֵאת מֵאוֹתָהּ זֻהֲמַת הַנָּחָשׁ, וְנִכְנֶסֶת לָעֲבוֹדָה הַקְּדוֹשָׁה. זֶהוּ שֶׁכָּתוּב בְּצֵאתוֹ מֵחָרָן (ימי שבעים שנה לא ספורות חיים מאותם ארבע עשרה) מֵאוֹתוֹ הָרֹגֶז וְהַתֹּקֶף שֶׁל (השטן) הַהוּא הַנָּחָשׁ שֶׁהָיָה מֵסִית אוֹתוֹ עַד עַכְשָׁו אֶת הַגּוּף וְשׁוֹלֵט עָלָיו."],[11,"","בָּאִילָן שׁוֹלֶטֶת עָרְלָה שָׁלֹשׁ שָׁנִים. בָּאָדָם שְׁלֹשׁ עֶשְׂרֵה שָׁנִים שֶׁנִּקְרָאִים שְׁנֵי עָרְלָה. כֵּיוָן שֶׁעָבְרוּ עַל הַגּוּף אוֹתָן הַשָּׁנִים וְהִתְעַבְּרָה (ד\"א והתעוררה) הַנְּשָׁמָה לַעֲבֹד אֶת עֲבוֹדַת הַקֹּדֶשׁ, הִיא מְצַוָּה אֶת הַגּוּף לְרָצוֹן טוֹב, לְהַכְנִיעַ אֶת אוֹתוֹ הַנָּחָשׁ שֶׁהִנֵּה לֹא יָכוֹל לִשְׁלֹט כְּמוֹ שֶׁהָיָה,"]]],[["דִּכְתִּיב וַיִּקַּח אַבְרָם אֶתּ שָׂרַי אִשְׁתּוֹ וְגו' (אברם דא י' את שרי דא ה'. י' דא נשמתא לנשמתא והוא זכר. ה' דא נשמתא דנוקבא). דָּא גּוּפָּא, דְּאִיהִי לְגַבֵּי נִשְׁמָתָּא כְּנוּקְבָא לְגַבֵּי דְכוּרָא. וְאֶתּ לוֹט בֶּן אָחִיו דָּא (יצר הרע) נָחָשׁ דּלא אַעֲדֵי כָּל כָּךָ מִן גּוּפָּא, בְּגִין דְּבֵקוּתָּא דְּגוּפָּא לָא אַעֲדִיוּ כָּל כָּךָ (זמנא ההוא) מִנֵּיהּ, אֲבָל אִתְּעֲרוּתָּא דְנִשְׁמָתָּא אַלְקֵי לֵיהּ תָּדִיר וְאַתְּרֵי בֵּיהּ וְאוֹכַח לֵיהּ וְכָפִּיף לֵיהּ על כָּרְחֵיהּ וְלָא יָכִיל לְשַׁלְטָאָה.","וְאֶתּ כָּל רְכוּשָׁם אֲשֶׁר רָכָשׁוּ אִלֵּין עוֹבָדִין טָבִין דְּעָבִיד בַּר נָשׁ בְּהַאי עָלְמָא בְּאִתְּעֲרוּתָּא דְנִשְׁמָתָּא. וְאֶתּ הַנְּפֶּשׁ אֲשֶׁר עשוּ בְחָרָן, הַהוּא נְפֶּשׁ דְּהֲוַתּ בִּדְבֵקוּתָּא בְּקַדְמִיתָּא בְּחַבְרוּתָּא דְהַהִיא עָרְלָה בַּהֲדֵי גוּפָּא וְאַתְּקִין לָהּ לְבָתַּר, דְּהָא לְבָתַּר דִּתְּלֵיסַר שְׁנִין וּלְעֵילָא דְּנִשְׁמָתָּא אִתְּעָרַתּ לְאַתְּקָנָא לְגוּפָּא, תַּרְוַוייהוּ מְתַּקְּנִין לְהַהוּא נְפֶּשׁ דְּמִשְׁתַּתְּפָּא בְּתּוּקְפָּא דְנָחָשׁ וּתְּאוּבְתֵּיהּ בִּישָׁא הֲדָא הוּא דִכְתִּיב וְאֶתּ הַנְּפּשׁ אֲשֶׁר עָשׂוּ בְחָרָן.","וְעִם כָּל דָּא נִשְׁמְתָּא אַתְּקֵיפַּתּ בֵּיהּ בְּהַהוּא נָחָשׁ לְתַּבְּרָא לֵיהּ בְּתּוּקְפָּא בְּשִׁעְבּוּדא דִּתְּשׁוּבָה (נ\"א בשעבודא דאורייתא, ואמשיך ליה לגבי בתי כנסיות ובתי מדרשות בגין דלא יתגבר על רוחא כדבקדמיתא) הֲדָא הוּא דִכְתִּיב ויַּעֲבוֹר (הכתוב בדף פ' אחר הגליון שורה ט\"ו) (עד כאן סתרי תורה)","וַיֵּלֶךָ אַבְרָם כַּאֲשֶׁר דִּבֶּר אֵלָיו יְיָ. אָמַר רַבִּי אֶלְעָזָר תָּא חֲזֵי, דְּהָא לָא כְּתִיב וַיֵּצֵא אַבְרָם כַּאֲשֶׁר דִּבֶּר אֵלָיו יְיָ. אֶלָּא וַיֵּלֶךְ. כְּמָא דְאַתְּ אָמֵר לֶךְ לְךָ, דְּהָא יְצִיאָה בְּקַדְמִיתָא עֲבְדוּ דִּכְתִיב וַיֵּצְאוּ אִתָּם מֵאוּר כַּשְׂדִּים לָלֶכֶת אַרְצָה כְּנָעַן, וְהַשְׁתָּא כְּתִיב וַיֵּלֶךְ וְלָא כְּתִיב וַיֵּצֵא.","כַּאֲשֶׁר דִּבֶּר אֵלָיו יְיָ, דְּאַבְטַח לֵיהּ בְּכֻלְהוּ הַבְטָחוֹת. וַיֵּלֶךְ אִתּוֹ לוֹט, דְּאִתְחַבַּר עִמֵּיהּ בְּגִין לְמֵילַף מֵעוֹבָדוֹי, וְעִם כָּל דָּא לָא אוֹלִיף כּוּלֵי הַאי. אָמַר רַבִּי אֶלְעָזָר זַכָּאִין אִנּוּן צַדִּיקַיָּיא דְּאוֹלְפֵי אָרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא בְּגִין לְמֵיהַךְ בְּהוּ וּלְדָחֲלָא מִנֵּיהּ מֵהַהוּא יוֹמָא דְדִינָא דְּזַמִּין בַּר נָשׁ לְמֵיהַב דִּינָא וְחוּשְׁבָּנָא לְקוּדְשָׁא בְּרִיךְ הוּא.","פָּתַח וְאָמַר, (איוב ל״ז:ז׳) בְּיַד כָּל אָדָם יַחְתּוֹם לָדַעַת כָּל אַנְשֵׁי מַעֲשֵׂהוּ הַאי קְרָא אוּקְמוּהָ. אֲבָל תָּא חֲזֵי בְּהַהוּא יוֹמָא דְּאַשְׁלִימוּ יוֹמוֹי דְּבַר נָשׁ לְאֲפָקָא מֵעָלְמָא, הַהוּא יוֹמָא דְּגוּפָא אִתְבַּר וְנַפְשָׁא בָּעְיָא לְאִתְפָּרְשָׁא מִנֵּיהּ, כְּדֵין אִתְיְיהִיב רְשׁוּ לְבַר נָשׁ לְמֶחֱמֵי מַה דְּלָא הֲוָה לֵיהּ רְשׁוּ לְמֶחֱמֵי בְּזִמְנָא דְּגוּפָא שָׁלְטָא וְקָאִים עַל בּוּרְיֵיהּ.","וּכְדֵין קָיְימֵי עֲלֵיהּ תְּלַת שְׁלִיחָן וְחָשְׁבֵי יוֹמוֹי וְחוֹבוֹי וְכָל מַה דְּעֲבַד בְּהַאי עָלְמָא, וְהוּא אוֹדֵי עַל כֹּלָּא בְּפוּמֵיהּ, וּלְבָתַר הוּא חָתִים עֲלֵיהּ בִּידֵיהּ, הֲדָא הוּא דִכְתִיב בְּיַד כָּל אָדָם יַחְתּוֹם,","וּבִידֵיהּ כֻּלְהוּ חֲתִימִין לְמֵידַן לֵיהּ (בההוא ד\"א בהאי) עָלְמָא עַל קַדְמָאֵי וְעַל בַּתְרָאֵי עַל חַדְתֵּי וְעַל עַתִּיקֵי לָא אִתְנְשֵׁי חַד מִנַּיְיהוּ, הֲדָא הוּא דִכְתִיב לָדַעַת כָּל אַנְשֵׁי מַעֲשֵׂהוּ. וְכָל אִנּוּן עוֹבָדִין דְּעֲבַד בְּהַאי עָלְמָא בְּגוּפָא וְרוּחָא הָכִי נָמֵי יָהִיב חוּשְׁבְּנָא בְּגוּפָּא וְרוּחָא עַד לָא יִפּוּק מֵעָלְמָא.","תָּא חֲזֵי, כַּמָה דְחַיָּיבַיָא אַקְשֵׁי קְדַל בְּהַאי עָלְמָא הָכִי נָמֵי אֲפִלּוּ בְּשַׁעְתָּא דְּבָעֵי לְנַפְקָא מֵהַאי עָלְמָא אַקְשֵׁי קְדַל. בְגִין כָּךְ זַכָּאָה הוּא בַּר נָשׁ דְּיָלִיף בְּהַאי עָלְמָא אָרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא בְּגִין לְמֵיהַךְ בְּהוּ. וְחַיָּיבָא אַף עַל גַּב דְּאִסְתַּכַּל בְּהַנֵּי (נ\"א דאשתדל בהדי) צַדִּיקַיָיא אַקְשֵׁי קְדַל וְלָא בָּעֵי לְמֵילַף.","וּבְגִין כָּךְ אִית לֵיהּ לְצַדִּיקָא לְמִתְקַף בֵּיהּ וְאַף עַל גַּב דְּחַיָּיבָא אַקְשֵׁי קְדַל הוּא לָא יִשְׁבּוֹק לֵיהּ וְאִית לֵיהּ לְאַתְקָפָא בִּידֵיהּ וְלָא יִשְׁבּוֹק לֵיהּ, דְּאִי יִשְׁבּוֹק לֵיהּ יְהַךְ וְיַחֲרִיב עָלְמָא.","תָּא חֲזֵי, מִן אֱלִישָׁע דְּדָחָה לְגֵחֲזִי. וְכֵן בְּאַבְרָהָם כָּל זִמְנָא דְּהֲוָה לוֹט בַּהֲדֵיהּ לָא אִתְחַבַּר בַּהֲדֵי רַשִּׁיעַיָּא, כֵּיוָן דְּאִתְפְּרַשׁ מִנֵּיהּ מַה כְּתִיב וַיִּבְחַר לוֹ לוֹט אֶת כָּל כִּכַּר הַיַּרְדֵּן, וּכְתִיב וַיֶאֱהַל עַד סְדוֹם. מַה כְּתִיב בַּתְרֵיהּ וְאַנְשֵׁי סְדוֹם רָעִים וְחַטָּאִים לַיְיָ מְאֹד.","אָמַר רַבִּי אַבָּא הַאי דְּאֲמַרְתְּ וַיֵּלֶךְ אַבְרָם וְלָא כְּתִיב וַיֵּצֵא אַבְרָם שַׁפִּיר הוּא. אֲבָל סוֹפָא דִקְרָא מַה כְּתִיב בְּצֵאתוֹ מֵחָרָן. אָמַר רַבִּי אֶלְעָזָר מֵחָרָן כְּתִיב וְהַהִיא יְצִיאָה מֵאֶרֶץ מוֹלַדְתּוֹ הֲוַת בְּקַדְמִיתָא:","וַיִּקַּח אַבְרָם אֶת שָׂרַי אִשְׁתּוֹ. מַהוּ וַיִּקַּח, אֶלָּא אַמְשִׁיךְ לָהּ בְּמִלֵּי מַעַלְיָיתָא, בְּגִין דְּלֵית לֵיהּ רְשׁוּ לְבַּר נָשׁ לְאֲפָקָא אִתְּתֵיהּ לְמֵיהַךְ בְּאַרְעָא אָחֳרָא בְּלָא רְעוּתָא דִילָהּ. וְכֵן הוּא אוֹמֵר (במדבר כ׳:כ״ה) קַח אֶת אַהֲרֹן (במדבר ג׳:מ״ה) קַח אֶת הַלְוִיִם. וּבְגִין כָּךְ וַיִּקַּח אַבְרָם מָשִׁיךְ לָהּ בְּמִלִּין וְאוֹדַע לָהּ אָרְחֵיהוֹן דְּאִנּוּן בְּנִי דָרָא כַּמָּה בִּישִׁין. וּבְגִין כָּךְ וַיִּקַח אַבְרָם אֶת שָׂרַי אִשְׁתּוֹ.","וְאֶת לוֹט בֶּן אָחִיו. מָה חָמָא אַבְרָהָם לְדָבְקָא עִמֵּיהּ לוֹט, אֶלָּא בְּגִין דְּצָפָה בְּרוּחַ הַקֹּדֶשׁ דְּזַמִּין לְמֵיפַּק מִנֵּיהּ דָּוִד. וְאֶת הַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן. אִלֵּין גֵּרִים וְגִיּוֹרוֹת דְּאַתְקִינוּ נַפְשַׁיְיהוּ, אַבְרָהָם מְגַיֵּיר גּוּבְרִין וְשָׂרָה מְגַיֶּירֶת נָשִׁין וּמַעֲלֶה עֲלֵיהוֹן כְּאִלּוּ עֲבְדוּ לְהוֹן.","אָמַר רַבִּי אַבָּא אִי הָכִי כַּמָּה בְּנֵי נָשָׁא הֲווּ, אִי תֵימָא דְּכֻלְהוּ אֲזְלוּ עִמֵּיהּ. אָמַר רַבִּי אֶלְעָזָר אִין. (ובגין כלהו ד\"א ובגין כך כלהו) בְּנֵי נָשָׁא דְּהֲווּ אָזְלִין עִמֵּיהּ כֻּלְהוּ אִקְרוּן עַם אֱלֹהֵי אַבְרָהָם. וְהֲוָה מַעֲבַר בְּאַרְעָא וְלָא הֲוָה דָּחִיל דִּכְתִיב וַיַּעֲבֹר אַבְרָם בָּאָרֶץ."],[[0,"דכתיב ויקח וגו':","שכתוב ויקח אברם את שרי אשתו וגו' \u0003שרי אשתו\u0004 זה הגוף, שהוא כלפי הנשמה כערך הנקבה כלפי הזכר. \u0003ואת לוט בן אחיו,\u0004 זהו הנחש, שאינו סר כל כך מן הגוף, גם לאחר י\"ג שנה, משום שגם דביקות הגוף לא תסור כל כך ממנו, אבל התעוררותה של הנשמה מכה אותו תמיד, ומתרה בו ומוכיח אותו, ומכניעו בעל כרחו, ואינו יכול למשול."],[1,"ואת כל רכושם אשר רכשו:","אלו הם מעשים הטובים שאדם עושה בעולם הזה בכח התעוררות הנשמה. \u0003ואת הנפש אשר עשו בחרן.\u0004 היינו אותה הנפש שהיתה בתחילה בדביקות ובהתחברות של הערלה עם הגוף, ואחר כך תקנה אותה הנשמה. עליה אומר הכתוב, ואת הנפש אשר עשו בחרן. והיינו נפש המתאוה, שיש לה קורבה חזקה אל תאות הגוף והקליפות. כמ\"ש להלן."],[1,"דהא לבתר דתליכר וכו':","כי לאחר כך, מי\"ג שנה ולמעלה, שהנשמה מתעוררת לתקן את הגוף, שניהם, הנשמה עם הגוף, מתקנים אותה הנפש, שנשתתפה בתוקף הדינים של הנחש ובתאותו הרעה, וזה שכתוב, ואת הנפש אשר \u0003עשו\u0004 בחרן. שאומר, \u0003עשו,\u0004 שהוא לשון רבים, משום שסובב על הנשמה ועל הגוף, ששניהם מתקנים את הנפש. הנשמה ע\"י התעוררותה שמעוררת את הגוף, והגוף על ידי מעשיו הטובים."],[2,"ועם כל דא וכו':","ועם כל זה מתקפת הנשמה על אותו הנחש לשבור אותו בתוקף השעבוד של תשובה. וזהו שכתוב, ויעבור עד מקום שכם, אשר \u0003שכם\u0004 הוא מקום משכנה של השכינה (כמ\"ש להלן באות פ') והיינו משום שכבר נשבר לגמרי תוקפו של הנחש, על ידי הנשמה. (ע\"כ ס\"ת)"],[3,"וילך אברם וגו' אר\"א ת\"ח וכו':","אמר ר' אלעזר בוא וראה. כי לא כתוב \u0003ויצא\u0004 אברם כאשר דבר אליו ה', אלא \u0003וילך\u0004 כמו שאתה אומר \u0003לך לך.\u0004 הוא, משום שהיציאה כבר עשו מקודם לכן. שכתוב, ויצאו אתם מאור כשדים ללכת ארצה כנען. וע\"כ, כתוב עתה, \u0003וילך,\u0004 ולא כתוב ויצא."],[4,"כאשר דבר אליו ה':","היינו כפי שהבטיח לו בכל ההבטחות. \u0003וילך אתו לוט,\u0004 שנתחבר עמו כדי ללמוד ממעשיו. ועם כל זה לא למד כל כך, \u0003אמר ר' אלעזר,\u0004 אשריהם הצדיקים הלומדים דרכיו של הקב\"ה, כדי ללכת בהם, וליראה ממנו, מאותו יום הדין שעתיד האדם ליתן דין וחשבון לפני הקב\"ה."],[5,"פתח ואמר, ביד כל אדם יחתום וגו':","מקרא הזה בארוהו. אבל בוא וראה. ביום ההוא שנשלמו ימיו של האדם לצאת מהעולם. ביום ההוא שהגוף נשבר והנפש צריכה לפרוש ממנו. אז ניתן רשות להאדם לראות, מה שלא היה יכול לראות בעת ששלט הגוף, ומשיג, דבר על בוריו."],[6,"וכדין קיימי עליה וכו':","ואז עומדים עליו שלשה שליחים, (שענינם מבואר ויקהל אות פ\"ז ע\"ש) וחושבים ימיו וחטאיו, וכל מה שעשה בעולם הזה. והוא מודה על הכל בפיו, ואח\"כ חותם עליו, על הדין וחשבון, בידו. וזהו שכתוב, ביד כל אדם יחתום."],[7,"ובידיה כלהו חתימין וכו':","ובידו כולם, חתומים כל מעשיו וחטאיו לדון אותו בעולם הזה, על ראשונים ועל אחרונים על חדשים ועל ישנים, אף אחד מהם אינו נשכח, וזהו שכתוב לדעת כל אנשי מעשהו. וכמו שכל אלו המעשים שעשה בעולם הזה היה בגוף ורוח יחד, כן הוא נותן חשבון עליהם כשהוא בגוף ורוח יחד, מטרם שנפטר מהעולם."],[8,"ת\"ח כמה דחייביא:","בוא וראה כמו שהרשעים הם קשי עורף בעולם הזה, כן אפילו בשעה שעומדים לצאה מעולם הזה מקשים עורף. משום זה, אשרי הוא האדם, הלומד בעולם הזה דרכיו של הקב\"ה כדי ללכת בהם. והרשע, אע\"פ שמסתכל באלו הצדיקים, הוא מקשה ערפו ואינו רוצה ללמוד מהם."],[9,"ובגין כך אית ליה וכו':","ומשום זה יש לו להצדיק לאחוז בו, ואף על פי שהרשע מקשה ערפו, לא יעזוב אותו. ויש לו להחזיק אותו בידו ולא ירפה ממנו, כי אם ירפה ממנו, ילך ויחריב העולם."],[10,"ת\"ח מן אלישע וכו'.","בוא וראה מן אלישע שדחה לגחזי, (כמ\"ש בסנהדרין קז:) וכן באברהם, כל זמן שהיה לוט עמו, לא נתחבר עם הרשעים, כיון שנפרד ממנו, מה כתוב, ויבחר לו לוט את כל ככר הירדן, וכתיב ויאהל עד סדום. ומה כתוב אחריו. ואנשי סדום רעים וחטאים לה' מאד. הרי שנתחבר עם הרשעים."],[11,"אמר ר' אבא וכו':","אר\"א, לר' אלעזר, זה שאמרת וילך אברם ולא כתוב ויצא אברם, משום שהיציאה כבר עשו מקודם לכן, (כנ\"ל באות ל\"א) יפה הוא. אבל בסוף הפסוק מה כתוב, \u0003בצאתו מחרן,\u0004 הרי שהדבור נסמך גם על היציאה, אע\"פ שכבר יצא. \u0003אמר ר' אלעזר מחרן כתיב,\u0004 אבל עיקר היציאה היא היציאה מארץ מולדתו, שזה היה מקודם לכן. מה שאין כן היציאה מחרן, באה עתה עם הדבור \u0003לך לך\u0004 וגו', ויתכן לומר כאן בצאתו מחרן."],[12,"ויקח אברם וגו':","שואל מהו ויקח שאומר הכתוב. ואומר, אלא שהמשיכה בדברים טובים. כי אין לו רשות לאדם להוציא אשתו ללכת לארץ אחר בלי רצונה. וכן הוא אומר קח את אהרן. קח את הלוים. ומשום זה, \u0003ויקח אברם,\u0004 דהיינו שהמשיכה בדברים, והודיע אותה כמה רעים הם דרכי בני הדור, וע\"כ כתוב ויקח אברם את שרי אשתו."],[13,"ואת לוט בן אחיו:","שואל מה ראה אברהם, להדביק את לוט אליו. ואומר. אלא משום שצפה ברוח הקדש שדוד עתיד לצאת ממנו. \u0003ואת הנפש אשר עשו בחרן,\u0004 אלו הם גרים וגיורות שתקנו את נפשותם. אברהם היה מגייר את האנשים ושרה היתה מגיירת את הנשים, וע\"כ מעלה עליהם הכתוב כאלו עשו אותם."],[14,"א\"ר אבא וכו':","אר\"א, אם כן. הרבה אנשים היו אלו הגרים, איך אפשר לומר שכולם הלכו עמו. א\"ר אלעזר כן. ומשום זה כל האנשים שהלכו עמו, נקראו, עם אלהי אברהם, והיה עובר בארץ ולא היה מתירא. שכתוב ויעבור אברם בארץ."]],[[0,"","שֶׁכָּתוּב וַיִּקַּח אַבְרָם אֶת שָׂרַי אִשְׁתּוֹ וְגוֹ' (אברם זו י', את שרי זו ה', י' זו הנשמה לנשמה, והוא זכר, ה' זו הנשמה של הנקבה). זֶה הַגּוּף, שֶׁהוּא אֵצֶל הַנְּשָׁמָה כְּמוֹ נְקֵבָה אֵצֶל הַזָּכָר. וְאֶת לוֹט בֶּן אָחִיו - זֶה (יצר הרע) הַנָּחָשׁ שֶׁלֹּא זָז כָּל כָּךְ מִן הַגּוּף, מִשּׁוּם הַדְּבֵקוּת שֶׁל הַגּוּף לֹא כָּל כָּךְ זָזִים (הזמן ההוא) מִמֶּנּוּ. אֲבָל הִתְעוֹרְרוּת הַנְּשָׁמָה תָּמִיד מַלְקָה אוֹתוֹ וּמַתְרָה בּוֹ וּמוֹכִיחָה אוֹתוֹ וּמַכְנִיעָה אוֹתוֹ בְּעַל כָּרְחוֹ, וְלֹא יָכוֹל לִשְׁלֹט."],[1,"","וְאֶת כָּל רְכוּשָׁם אֲשֶׁר רָכָשׁוּ - אֵלּוּ הַמַּעֲשִׂים הַטּוֹבִים שֶׁעוֹשֶׂה אָדָם בָּעוֹלָם הַזֶּה בַּהִתְעוֹרְרוּת שֶׁל הַנְּשָׁמָה. וְאֶת הַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן - אוֹתָהּ הַנֶּפֶשׁ שֶׁהָיְתָה בָּרִאשׁוֹנָה בַּדְּבֵקוּת בַּחֲבֵרוּת שֶׁל הָעָרְלָה הַהִיא עִם הַגּוּף וְתִקֵּן אוֹתָהּ לְאַחַר מִכֵּן, שֶׁהֲרֵי אַחַר שְׁלֹשׁ עֶשְׂרֵה שָׁנִים וָמַעְלָה, כְּשֶׁהַנְּשָׁמָה מִתְעוֹרֶרֶת לְתַקֵּן אֶת הַגּוּף, שְׁנֵיהֶם מְתַקְּנִים אֶת אוֹתָהּ הַנֶּפֶשׁ שֶׁמִּשְׁתַּתֶּפֶת עִם חֹזֶק הַנָּחָשׁ וּתְשׁוּקָתוֹ הָרָעָה. זֶהוּ שֶׁכָּתוּב וְאֶת הַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן."],[2,"","וְעִם כָּל זֶה הַנְּשָׁמָה מִתְגַּבֶּרֶת בְּאוֹתוֹ הַנָּחָשׁ לִשְׁבֹּר אוֹתוֹ בְּחֹזֶק בְּשִׁעְבּוּד שֶׁל תְּשׁוּבָה (נ\"א: בשעבוד של תורה, ומושך אותו לבתי כנסיות ובתי מדרשות כדי שלא יתגבר על הרוח כבראשונה). זֶהוּ שֶׁכָּתוּב וַיַּעֲבֹר. (ע\"כ סתרי תורה)."],[3,"","וַיֵּלֶךָ אַבְרָם כַּאֲשֶׁר דִּבֶּר אֵלָיו ה'. אָמַר רַבִּי אֶלְעָזָר, בֹּא רְאֵה, שֶׁהֲרֵי לֹא כָתוּב וַיֵּצֵא אַבְרָם כַּאֲשֶׁר דִּבֶּר אֵלָיו ה', אֶלָּא וַיֵּלֶךְ, כְּמוֹ שֶׁנֶּאֱמַר לֶךְ לְךְ, שֶׁהֲרֵי בָּרִאשׁוֹנָה עָשׂוּ יְצִיאָה, שֶׁכָּתוּב וַיֵּצְאוּ אִתָּם מֵאוּר כַּשְׂדִּים לָלֶכֶת אַרְצָה כְּנַעַן. וְעַכְשָׁו כָּתוּב וַיֵּלֶךְ, וְלֹא כָתוּב וַיֵּצֵא."],[4,"","כַּאֲשֶׁר דִּבֶּר אֵלָיו ה' - שֶׁהִבְטִיחַ לוֹ אֶת כָּל הַהַבְטָחוֹת. וַיֵּלֶךְ אִתּוֹ לוֹט - שֶׁהִתְחַבֵּר עִמּוֹ כְּדֵי לִלְמֹד מִמַּעֲשָׂיו, וְעִם כָּל זֶה לֹא לָמַד כָּל זֶה. אָמַר רַבִּי אֶלְעָזָר, אַשְׁרֵי הַצַּדִּיקִים שֶׁלּוֹמְדִים דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּדֵי לָלֶכֶת בָּהֶם וְלִירָא מִמֶּנּוּ מֵאוֹתוֹ יוֹם הַדִּין שֶׁעָתִיד אָדָם לָתֵת דִּין וְחֶשְׁבּוֹן לַקָּדוֹשׁ- בָּרוּךְ-הוּא."],[5,"","פָּתַח וְאָמַר, (איוב לז) בְּיַד כָּל אָדָם יַחְתּוֹם לָדַעַת כָּל אַנְשֵׁי מַעֲשֵׂהוּ. הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ. אֲבָל בֹּא רְאֵה, בַּיּוֹם הַהוּא שֶׁנִּשְׁלָמִים יְמֵי הָאִישׁ לָצֵאת מִן הָעוֹלָם, הַיּוֹם הַהוּא שֶׁהַגּוּף נִשְׁבָּר וְהַנֶּפֶשׁ רוֹצָה לְהִפָּרֵד מִמֶּנּוּ, אָז נִתֶּנֶת רְשׁוּת לָאָדָם לִרְאוֹת מַה שֶּׁלֹּא הָיְתָה לוֹ רְשׁוּת לִרְאוֹת בִּזְמַן שֶׁהַגּוּף שָׁלַט וְעָמַד עַל בֻּרְיוֹ."],[6,"","וְאָז עוֹמְדִים עָלָיו שְׁלֹשָׁה שְׁלִיחִים וּמְחַשְּׁבִים יָמָיו וַחֲטָאָיו וְכָל מַה שֶּׁעָשָׂה בָּעוֹלָם הַזֶּה, וְהוּא מוֹדֶה עַל הַכֹּל בְּפִיו, וְאַחַר כָּךְ הוּא חוֹתֵם עָלָיו בְּיָדוֹ. זֶהוּ שֶׁכָּתוּב בְּיַד כָּל אָדָם יַחְתּוֹם."],[7,"","וּבְיָדוֹ כֻּלָּם חֲתוּמִים לָדוּן אוֹתוֹ (באותו ד\"א בזה) הָעוֹלָם עַל הָרִאשׁוֹנִים וְעַל הָאַחֲרוֹנִים, עַל חֲדָשִׁים וְעַל יְשָׁנִים, לֹא נִשְׁכָּח אֶחָד מֵהֶם. זֶהוּ שֶׁכָּתוּב לָדַעַת כָּל אַנְשֵׁי מַעֲשֵׂהוּ. וְכָל אוֹתָם הַמַּעֲשִׂים שֶׁעָשָׂה בָּעוֹלָם הַזֶּה בְּגוּף וְרוּחַ, כָּךְ גַּם נוֹתֵן חֶשְׁבּוֹן בְּגוּף וְרוּחַ בְּטֶרֶם יָצָא מִן הָעוֹלָם"],[8,"","בֹּא רְאֵה כַּמָּה הָרְשָׁעִים קְשֵׁי עֹרֶף בָּעוֹלָם הַזֶּה, כָּךְ גַּם אֲפִלּוּ בְּשָׁעָה שֶׁרוֹצִים לָצֵאת מִן הָעוֹלָם הַזֶּה הֵם קְשֵׁי עֹרֶף. מִשּׁוּם כָּךְ אַשְׁרֵי הָאִישׁ שֶׁלּוֹמֵד בָּעוֹלָם הַזֶּה אֶת דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּדֵי לָלֶכֶת בָּהֶם. וְהָרָשָׁע, אַף עַל פִּי שֶׁמִּסְתַּכֵּל בְּאֵלּוּ (נ\"א: שמשתדל עם) הַצַּדִּיקִים, מַקְשֶׁה עֹרֶף וְלֹא רוֹצֶה לִלְמֹד."],[9,"","וּמִשּׁוּם כָּךְ יֵשׁ לַצַּדִּיק לְהַחֲזִיק בּוֹ. וְאַף עַל גַּב שֶׁהָרָשָׁע מַקְשֶׁה עֹרֶף הוּא, לֹא יַעֲזֹב אוֹתוֹ, וְיֵשׁ לוֹ לְהַחֲזִיק בְּיָדוֹ וְלֹא יַעֲזב אוֹתוֹ. כִּי אִם יַעֲזב אוֹתוֹ, יֵלֶךְ וְיַחֲרִיב אֶת הָעוֹלָם."],[10,"","בֹּא רְאֵה מֵאֱלִישָׁע שֶׁדָּחָה אֶת גֵיחֲזִי. וְכֵן בְּאַבְרָהָם - כָּל פַּעַם שֶׁלּוֹט הָיָה עִמּוֹ, לֹא הִתְחַבֵּר עִם הָרְשָׁעִים. כֵּיוָן שֶׁנִּפְרַד מִמֶּנּוּ, מַה כָּתוּב? וַיִּבְחַר לוֹ לוֹט אֵת כָּל כִּכַּר הַיַּרְדֵּן. וְכָתוּב וַיֶּאֱהַל עַד סְדוֹם. מַה כָּתוּב אַחַר כָּךְ? וְאַנְשֵׁי סְדֹם רָעִים וְחַטָּאִים לַה' מְאֹד."],[11,"","אָמַר רַבִּי אַבָּא, זֶה שֶׁאָמַרְתָּ וַיֵּלֶךְ אַבְרָם וְלֹא כָתוּב וַיֵּצֵא אַבְרָם - זֶה יָפֶה. אֲבָל בְּסוֹף הַפָּסוּק מַה כָּתוּב? בְּצֵאתוֹ מֵחָרָן. אָמַר רַבִּי אֶלְעָזָר, כָּתוּב מֵחָרָן, וְהַיְצִיאָה הַהִיא מֵאֶרֶץ מוֹלַדְתּוֹ הָיְתָה בָּרִאשׁוֹנָה."],[12,"","וַיִּקַּח אַבְרָם אֶת שָׂרַי אִשְׁתּוֹ. מַה זֶּה וַיִּקַּח? אֶלָּא מָשַׁךְ אוֹתָהּ בִּדְבָרִים נְעִימִים, מִשּׁוּם שֶׁאֵין רְשׁוּת לְאָדָם לְהוֹצִיא אֶת אִשְׁתּוֹ לָלֶכֶת לְאֶרֶץ אַחֶרֶת לְלֹא רְצוֹנָהּ. וְכֵן הוּא אוֹמֵר (במדבר כ) קַח אֶת אַהֲרֹן, (שם ג) קַח אֶת הַלְוִיִּם. וּמִשּׁוּם כָּךְ וַיִּקַּח אַבְרָם. מָשַׁךְ אוֹתָהּ בִּדְבָרִים וְהוֹדִיעַ לָהּ אֶת דַּרְכֵי בְּנֵי הַדּוֹר כַּמָּה הֵם רָעִים. וּמִשּׁוּם כָּךְ וַיִּקַּח אַבְרָם אֶת שָׂרַי אִשְׁתּוֹ."],[13,"","וְאֶת לוֹט בֶּן אָחִיו. מָה רָאָה אַבְרָם לְהַדְבִּיק עִמּוֹ אֶת לוֹט? אֶלָּא מִשּׁוּם שֶׁצָּפָה בְּרוּחַ הַקֹּדֶשׁ שֶׁעָתִיד לָצֵאת מִמֶּנּוּ דָּוִד. וְאֶת הַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן - אֵלּוּ הַגֵּרִים וְהַגֵּרוֹת שֶׁתִּקְּנוּ אֶת נַפְשׁוֹתָם. אַבְרָהָם מְגַיֵּר אֲנָשִׁים, וְשָׂרָה מְגַיֶּרֶת נָשִׁים, וּמַעֲלֶה עֲלֵיהֶם כְּאִלּוּ עָשׂוּ אוֹתָם."],[14,"","אָמַר רַבִּי אַבָּא, אִם כָּךְ, כַּמָּה בְּנֵי אָדָם הָיוּ, אִם תֹּאמַר שֶׁכֻּלָּם הָלְכוּ עִמּוֹ? אָמַר רַבִּי אֶלְעָזָר, כֵּן, (ומשום שכלם ד\"א ומשום כך כלם) הָאֲנָשִׁים שֶׁהָיוּ הוֹלְכִים עִמּוֹ, כֻּלָּם נִקְרְאוּ עַם אֱלֹהֵי אַבְרָהָם. וְהָיָה עוֹבֵר בָּאָרֶץ וְלֹא הָיָה פוֹחֵד, שֶׁכָּתוּב וַיַּעֲבֹר אַבְרָם בָּאָרֶץ."]]],[["אָמַר לֵיהּ רַבִּי אַבָּא אִי הֲוָה כְּתִיב וְהַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן הֲוָה אֲמִינָא הָכִי, אֶלָּא וְאֶת הַנֶּפֶשׁ כְּתִיב, אֶת לְאַסְגָּאָה זְכוּתָא דְּכֻלְהוּ נַפְשָׁאן דְּהֲווּ אָזְלֵי עִמֵּיהּ, דְּכָל מַאן דִּמְזַכֶּה לְאָחֳרָא הַהוּא זְכוּתָא תַּלְיָא בֵּיהּ וְלָא אַעֲדֵי מִנֵּיהּ, מְנָלָן דִּכְתִיב וְאֶת הַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן, זְכוּתָא דְּאִנּוּן נַפְשָׁן הֲוָה אָזִיל עִמֵּיהּ דְּאַבְרָהָם. לֶךְ לְךָ.","אָמַר רַבִּי שִׁמְעוֹן מַאי טַעְמָא דְּגִלּוּיָא קַדְמָאָה דְּאִתְגְּלֵי קוּדְשָׁא בְּרִיךְ הוּא עֲלֵיהּ דְּאַבְרָהָם פָּתַח בְּלֶךְ לְךָ, דְּהָא עַד הָכָא לָא מַלִּיל עִמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, מַאי טַעְמָא פָּתַח לֶךְ לְךָ. אֶלָּא הָא קָאֲמְרוּ דְּרָמַז בְּחוּשְׁבְּנִיהּ מְאָה דְּהָא לְמֵאָה שְׁנִין אִתְיְילִיד לֵיהּ בַּר.","אֲבָל תָּא חֲזֵי, כָּל מַה דְּעָבִיד קוּדְשָׁא בְּרִיךְ הוּא בְּאַרְעָא כֹּלָּא רָזָא דְחָכְמְתָא אִיהוּ, בְּגִין דְּאַבְרָהָם לָא הֲוָה דָּבִיק בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא כְּדֵין כְּדְקָא חָזֵי, אָמַר לֵיהּ לֶךְ לְךָ, וְדָא רֶמֶז לְהַהוּא אֲתַר דְּבָעֵי לְאִתְקְרָבָא בַּהֲדֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, וְאִיהוּ דַּרְגָּא קַדְמָאָה לְאָעֳלָא לְקוּדְשָׁא בְּרִיךְ הוּא, בְּגִין כָּךְ לֶךְ לְךָ.","וְהַאי דַרְגָא לָא יָכִיל אַבְרָהָם לְאִתְאַחֲדָא בֵּיהּ עַד דְּיֵיעוּל לְאַרְעָא דְּתַמָּן יְקַבֵל לֵיהּ לְהַהוּא דַרְגָא, כְּגַוְונָא דָא כְּתִיב, (שמואל ב ב׳:א׳) וַיִּשְׁאַל דָּוִד בַּיְיָ לֵאמֹר הַאֶעֱלֶה בְּאַחַת מֵעָרֵי יְהוּדָה וַיֹּאמֶר יְיָ עֲלֵה וַיֹּאמֶר אָנָה אֶעֱלֶה וַיֹּאמֶר חֶבְרוֹנָה. וְכִי כֵּיוָן דְּמִית שָׁאוּל וּמַלְכוּתָא אִתְחֲזֵי לְדָוִד אַמַּאי לָא קַבִּיל מַלְכוּתָא מִיָּד עַל כָּל יִשְׂרָאֵל.","אֶלָּא כֹּלָּא רָזָא דְחָכְמְתָא אִיהוּ, בְּגִין דְּדָוִד לֵית לֵיהּ לְקַבְּלָא מַלְכוּתָא אֶלָּא עַד דְּיִתְחַבַּר בַּאֲבָהָן דְּאִנּוּן בְּחֶבְרוֹן וּכְדֵין בְּהוּ יְקַבֵּל מַלְכוּתָא. וְעַל דָּא אִתְעַכַּב תַּמָּן שְׁבַע שְׁנִין בְּגִין דִּיקַבֵּל מַלְכוּתָא כְּדְקָא יְאוּת וְכֹלָּא בְּרָזָא דְּחָכְמְתָא וּבְגִין דִּיתַקֵּן מַלְכוּתֵיהּ. כְּגַוְונָא דָא אַבְרָהָם לָא עָאל בְּקִיּוּמָא דְּקוּדְשָׁא בְּרִיךְ הוּא עַד דְּעָאל לְאַרְעָא.","חָמֵי מַה כְּתִיב וַיַּעֲבֹר אַבְרָם בָּאָרֶץ. וַיַּעֲבֹר וַיֵּלֶךְ מִבָּעֵי לֵיהּ, אֶלָא הָכָא הוּא רֶמֶז שְׁמָא קַדִּישָׁא דְּאִתְחַתִּים בֵּיהּ עָלְמָא בְּע\"ב אַתְוָון גְּלִיפָן דְּכֻלְהוּ בִּשְׁמָא דָא. כְּתִיב הָכָא וַיַּעֲבֹר וּכְתִיב הָתָם (שמות לה) וַיַּעֲבֹר יְיָ עַל פָּנָיו וַיִּקְרָא:","בְּסִפְרָא דְּרַבִּי יֵיסָא סָבָא כְּתִיב הָכָא וַיַּעֲבֹר אַבְרָם בָּאָרֶץ וּכְתִיב הָתָם (שמות ל״ג:י״ט) אֲנִי אַעֲבִיר כָּל טוּבִי. וְהוּא רֶמֶז לִקְדוּשָׁה דְאַרְעָא דְּאָתֵי מֵאֲתַר עִלָּאָה כְּדְקָא חָזֵי.","עַד מְקוֹם שְׁכֶם עַד אֵלוֹן מוֹרֶה. מִסִּטְרָא דָא (ד\"א ל\"ג דלתתא). לְסִטְרָא דָא כְּדְקָא חָזֵי. וְהַכְּנַעֲנִי אָז בָּאָרֶץ. הָא אִתְּמָר דְּעַד כְּדֵין שָׁלְטָא חִוְיָא בִּישָׁא דְּאִתְלַטְיָא וְאַיְיתֵי לְוָוטִין עַל עָלְמָא דִּכְתִיב, (בראשית ט׳:כ״ה) אָרוּר כְּנַעַן עֶבֶד עֲבָדִים יִהְיֶה לְאֶחָיו וּכְתִיב, (בראשית נ) אָרוּר אַתָּה מִכָּל הַבְּהֵמָה וְגו'. וְתַמָּן אִתְקְרִיב אַבְרָהָם לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא. מַה כְּתִיב וַיֵּרָא יְיָ אֶל אַבְרָם הָכָא אִתְגְּלִי לֵיהּ מַה דְּלָא הֲוָה יָדַע הַהוּא חֵילָא עֲמִיקָא לְשָׁלְטָא עַל אַרְעָא. וּבְגִין כָּךְ וַיֵּרָא מַה דְּהֲוָה מִתְכַּסֵּי מִנֵּיהּ."],[[0,"אמר ליה ר' אבא וכו':","א\"ל ר\"א, אם היה כתוב והנפש אשר עשו בחרן, היתי אומר כן, שמפאת הרבוי שלהם לא היה מתירא לעבור בארץ. אלא, \u0003ואת הנפש\u0004 כתוב, המלה \u0003את\u0004 באה לרבות, זכותן של כל אלו הנפשות שהיו הולכות עמו. וע\"כ עבר אברהם בארץ בלי פחד. כי כל המזכה את האחר, אותה הזכות עומדת לו ואינה סרה ממנו. מאין לנו זה, כי כתוב, ואת הנפש אשר עשו בחרן, הזכות של אלו הנפשות. היתה הולכת עם אברהם."],[1,"לך לך:","א\"ר שמעון מה הטעם, שגילוי הראשון, שנגלה הקב\"ה על אברהם, פתח \u0003בלך לך,\u0004 שהרי עד כאן עוד לא דיבר הקב\"ה עם אברהם, מה הטעם שפתח \u0003בלך לך.\u0004 אלא שאמרו, שרמז לו בהחשבון של \u0003לך לך,\u0004 שהוא בגמטריא מאה, כי יולד לו בן למאה שנים."],[2,"אבל תא חזי:","אבל בוא וראה, כל מה שעושה הקב\"ה בארץ, הכל הוא בסוד החכמה. משום. שאברהם עוד לא היה דבוק אז בהקב\"ה כראוי, אמר לו לך לך. וזהו רומז לאותו המקום שהיה צריך להתקרב להקב\"ה והוא מדרגה ראשונה לבוא להקב\"ה, משום זה כתוב לך לך."],[3,"והאי דרגא לא יכיל וכו':","ומדרגה הזו לא יכול אברהם להתאחז בה מטרם שיכנס לארץ ישראל, כי שם מקבלים מדרגה הזו. כעין זה כתוב, וישאל דוד בה' וגו' ושואל וכי מאחר ששאול מת, ודוד היה ראוי לקבל המלכות, למה לא קבל מיד את המלכות על ישראל, אלא שנצרך למלוך מקודם ז' שנים בחברון."],[4,"אלא כלא רזא וכו':","אלא הכל סוד החכמה הוא. כי דוד, לא היה לו לקבל המלכות, אלא עד שיתחבר מקודם באבות שהם בחברון, ואז יקבל המלכות בהם. וע\"כ נתעכב שם בחברון שבע שנים כדי שיקבל המלכות כראוי, והכל בסוד החכמה, ומשום שיתוקן מלכותו. כעין זה גם אברהם לא בא בקיום שלם להקב\"ה עד שנכנס לארץ."],[4,"","פירוש, מתחילה נבנית המלכות, שה\"ס הנוקבא דז\"א, בסוד ב' מאורות הגדולים, דהיינו שקומתה שוה לגמרי כמו ז\"א, ושניהם משתמשים בכתר אחד, שפירושו שמקבלים שניהם הארתם ממקור אחד, שהיא בינה שבחינת הימין שבה דהיינו החסדים, מקבל ז\"א. ובחינת השמאל שבה, דהיינו הארת חכמה בסוד השורק, מקבלת הנוקבא. ואז נבחנים שניהם לד' רגלי כסא העליון, שהוא בינה. ז\"א שה\"ס חג\"ת, נבחן לג' רגלי הכסא. הנוקבא, שהיא ספירת המלכות, נבחנת לרגל רביעי של הכסא. ומשם אין הנוקבא יכולה להשפיע מוחין לעולם, כי אין זה מקומה, וע\"כ הם מכונים מוחין דאחורים. וה\"ס \u0003חברון,\u0004 מטעם היותה מחוברת עם האבות, שה\"ס חג\"ת, בקומה שוה. ואח\"כ יורדת משם, ונבנית מבחי' מחזה ולמטה דז\"א בסוד המאור הקטן, ואז מקבלת ב' מיני מוחין: אחורים, ופנים, על ידי ז\"א, והיא נשלמת במוחין דגדלות השלמים, ומשפעת להעולם. ואז נבחנת לבחינת ארץ ישראל. שאין הארת החכמה מושפעת אלא רק ממנה, כנודע."],[4,"","והנה דוד הוא מרכבה אל המלכות, שהיא הנוקבא דז\"א. ולפיכך לא יכול לקבל מלכות על כל ישראל ולהעשות מרכבה אל המלכות, הנקראת ארץ ישראל. מטרם שמלך בחברון ונעשה מרכבה שם אל המלכות הנקראת חברון שמשם מוחין הראשונים של המלכות. המקבלת מבינה שחזרה להיות חכמה, וכיון שדוד קבל בחינת המוחין דחברון היה יכול לקבל אח\"כ המוחין השלמים מבחינת ארץ ישראל. וקבל המלכות על כל ישראל. ולולא קבל המוחין דחברון, לא היה יכול לקבל המוחין דארץ ישראל, כי היה חסר לו המוחין דהארת השמאל של הבינה, שאינם מקובלים אלא בחברון כנ\"ל."],[4,"","וז\"ש \u0003דדוד לית ליה לקבלא מלכותא, אלא עד דיתחבר באבהן דאינון בחברון.\u0004 כמבואר."],[4,"","ואברהם היה מרכבה לבחינת חג\"ת דז\"א, ועקרו בחסד דז\"א. ונודע שז\"א הוא תמיד בחסדים מכוסים. זולת בעת שמשפיע אל הנוקבא. שאז מקבל מוחין דהארת חכמה בשביל הנוקבא ונכלל גם הוא מהם."],[4,"","וז\"ש \u0003בגין דאברהם לא הוה דביק ביה בקב\"ה כדין כדקא חזי אמר ליה לך לך,\u0004 כי מטרם שהשפיע המוחין בשביל הנוקבא, לא היה לו אלא חסדים מכוסים מחכמה, וכיון שהיה חסר לו הארת החכמה, לא היה אז דבוק בו בהקב\"ה כראוי. כי לא גרם זווג קב\"ה ושכינתיה. וע\"כ אמר לו לך לך, \u0003ודא רמז לההוא אתר\u0004 דהיינו השכינה, \u0003דבעי לאתקרבא בהדיה דקב\"ה,\u0004 כלומר שרמז לו שילך ויקרב השכינה אל הקב\"ה, \u0003ואיהו דרגא קדמאה לאעלא לקב\"ה,\u0004 שהוא מדרגה הראשונה לבא ולהעשות מרכבה לקב\"ה, כי מטרם שיגרום זווג קב\"ה ושכינתיה, לא יוכל להדבק בהקב\"ה. \u0003והאי דרגא לא יכיל אברהם לאתאחדא ביה עד דייעול לארעא,\u0004 ומדרגה זו לזכות בהמוחין דהארת חכמה ע\"י שגורם זווג קוב\"ה ושכינתיה כנ\"ל, לא יוכל להמשיך אלא כשהוא בארץ ישראל. כי שם הנוקבא מתוקנת במוחין דפב\"פ עם הקב\"ה, ויכולה להשפיע לעולם, כנ\"ל. וזהו שמשוה ביאת אברהם לארץ ישראל למלכות דוד בחברון, כי כמו שדוד המלך, שהוא מרכבה להנוקבא, לא יכול לקבל מלכות השלמה שה\"ס ארץ ישראל, מטרם שקבל הארת חכמה מבינה, בסוד רגל רביעי לכסא עלאה שה\"ס מלכות חברון. כן אברהם שהוא מרכבה לז\"א, לא היה ראוי לדביקות שלם בז\"א מטרם שבא לא\"י וגרם זווג קב\"ה ושכינתיה, שמשם נכלל גם הוא בהארת החכמה. וז\"ש \u0003כגוונא דא אברהם לא עאל בקיומא דקב\"ה עד דעאל לארעא.\u0004 כמו שדוד לא היה ראוי להדבק במלכות השלמה שה\"ס א\"י מסבת חסרון המוחין דהארת חכמה, שאינם נמשכים לו רק בחברון. כן אברהם לא היה ראוי להדבק בהקב\"ה, מסבת חסרון מוחין הללו דהארת חכמה, שאינם נמשכים לו רק בארץ ישראל."],[5,"חמי מה כתיב וכו'","ראה מה שכתוב ויעבור אברם בארץ, שואל, הכתוב אומר \u0003ויעבור\u0004 וילך צריך לומר, אלא שהוא רומז כאן השם הקדוש שנחתם בו העולם בע\"ב אותיות חקוקות, שכולם הן בשם הזה, כלומר, ויעבור הוא נוטריקון ע\"ב רי\"ו, הרומז על ע\"ב שמות ורי\"ו אותיות כתוב כאן ויעבור. וכתוב שם ויעבור ה' על פניו ויקרא, מה שם המדובר הוא בהשם ע\"ב הקדוש, אף \u0003ויעבור\u0004 שבכאן המדובר הוא בהשם ע\"ב הקדוש. (ואלו ע\"ב שמות שבהם רי\"ו אותיות מובאים בזהר בפרשת בשלח דף מ\"ט אות קע\"ב. וביאורו תמצא לעיל בהקדמת הזהר דף קי\"ז אות קט\"ז"],[6,"בספרא דר' ייסא סבא וכו':","בספרו של ר' ייסא סבא, אומר, כתוב כאן ויעבור אברם בארץ, וכתוב שם אני אעביר כל טובי, מה שם המדובר הוא בכל טובו במקום עליון דהיינו בינה אף כאן הוא רומז לקדושת הארץ הבאה ממקום עליון בכל טובו כראוי. דהיינו המלכות המלבשת את הבינה כראוי ומקבלת אורותיה."],[7,"עד מקום שכם עד אלון מורה:","היינו מצד זה לצד זה כראוי. \u0003מקום שכם\u0004 פירושו \u0003סטרא דשמאלא\u0004 מקום הארת השורק, שנקרא עתה שכם, מטעם שנתמעט מג\"ר דג\"ר, ואינו מושג אלא משכמו ולמטה ולא משכמו ולמעלה. \u0003אלון מורה\u0004 ה\"ס סטרא דמזרח, כי אלון לשון תוקף, שזה רומז על המנעולא הנ\"ל, שצד מזרח שה\"ס קו האמצעי קבל אותו, להמשיך קומת חסדים על המסך שלו, כנ\"ל בסמוך. ואחר שנעשה זווג על המסך הזה כמ\"ש לעיל בביאור הכתוב \u0003לך לך,\u0004 ונמשכה קומת חסדים ונכללו כל ג' הקוין זה בזה, אז המשיך אברהם אותם אל הנוקבא שנקראת ארץ."],[7,"","וזה שיעור הכתוב, \u0003ויעבור אברם\u0004 פירושו, שאברהם המשיך השפע מן מקום עליון שהיא הבינה, על דרך הכתוב אני אעביר כל טובי על פניך, אל הנוקבא, שז\"ס ויעבור אברם בארץ. והמשכה זו נקראת \u0003ויעבור,\u0004 משום שעוברת בג' דוכתי, דהיינו ג' קוין, ומפרש הכתוב, \u0003עד מקום שכם,\u0004 דהיינו ממדרגתו עצמו שהוא קו ימין, ששם היה נכלל כל טובו של הקב\"ה, המשיך אל מקום שכם שהוא קו שמאל, ואז נכללו ב' הקוין ימין ושמאל זה בזה. \u0003עד אלון מורה,\u0004 היינו שהמשיך שני הקוין אל קו האמצעי, שהוא הנושא אל המסך דמנעולא, ונכללו כל ג' הקוין בקו האמצעי, ואומר הטעם, שהוא משום \u0003והכנעני אז בארץ,\u0004 כי מטרם שנעשה הזווג על המסך דמנעולא שבקו האמצעי היה הכנעני שה\"ס הקללה של הנחש שולטת על הארץ, שהיה מחלוקת בין הקוין, והארת השמאל היתה כאש שורף, וניתן עי\"ז כח לקליפת כנען לשלוט על הארץ, אבל עתה אחר ביאת הזווג על המסך שבקו אמצעי, סרה קליפה הארורה הזו מהארץ, והאירו בה ב' הקוין ימין ושמאל כנ\"ל, וכיון שקו האמצעי היה הגורם לכל זה, זכה בהם גם הוא, כי כל שיעור אור שהתחתון גורם להעליון זוכה בו גם התחתון. שז\"ס \u0003תלת נפקי מחד חד בתלת קיימא\u0004 (כנ\"ל בראשית א' דף רפ\"ז ד\"ה תלת)."],[7,"","וזה אמרו \u0003ותמן אתקריב אברהם לגבי קב\"ה,\u0004 דהיינו על ידי קו האמצעי, שה\"ס אלון מורה, נגלה עליו הקב\"ה בכל טובו המפורש בהכתוב לך לך וגו', כנ\"ל, \u0003מה כתיב וירא ה' אל אברם הכא אתגלי ליה מה דלא הוה ידע ההוא חילא עמיקא דשלטא על ארעא,\u0004 מה כתוב עתה, \u0003וירא ה'\u0004 וגו' שנתגלה לו מה שלא הוה ידע מחמת אותו הכח העמוק, דהיינו המנעולא, ששלט על הארץ. פירוש. כי מובא לעיל (דף ט\"ז ד\"ה עוד) שאחר הופעת המנעולא ומטרם שנמשך הזווג עליה, נכפלו עליו הדינין בסוד \u0003חרן,\u0004 שמלבד שלא הרפו ממנו הדינין דשמאל. \u0003ולא יכיל למיקם עליה\u0004 נתחדשו עליו דינין דביטול הג\"ר, דהיינו \u0003ולא הוה ידע,\u0004 עש\"ה. ועל זה אומר כאן, כי עתה אחר הזווג הנעשה על המסך דמנעולא, \u0003אתגלי ליה מה דלא הוה ידע\u0004 כי עתה נכללו חקוין זה בזה ונשלמה הארת השמאל על ידי הימין והימין על ידי השמאל, והאירו בכל השלימות האפשרי, \u0003ובגין כך וירא מה דהוה מתכסי מניה,\u0004 כי סרו ממנו כל דינין שבשמאל שלא היה \u0003יכול למיקם עלייהו,\u0004 ועתה \u0003יכול למיקם עלייהו,\u0004 ואינם מתכסים ממנו יותר."]],[[0,"","אָמַר לוֹ רַבִּי אַבָּא, אִם הָיָה כָּתוּב וְהַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן - הָיִיתִי אוֹמֵר כָּךְ. אֶלָּא כָתוּב וְאֶת הַנֶּפֶשׁ. אֶת - לְרַבּוֹת אֶת הַזְּכוּת שֶׁל כָּל הַנְּפָשׁוֹת שֶׁהָיוּ הוֹלְכוֹת עִמּוֹ. שֶׁכָּל מִי שֶׁמְּזַכֶּה אֶת הָאַחֵר, אוֹתָהּ הַזְּכוּת תְּלוּיָה בּוֹ וְלֹא זָזָה מִמֶּנּוּ. מִנַּיִן לָנוּ? שֶׁכָּתוּב וְאֶת הַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן. הַזְּכוּת שֶׁל אוֹתָן הַנְּפָשׁוֹת הָיְתָה הוֹלֶכֶת עִם אַבְרָהָם. לֶךָ לְךְ."],[1,"","אָמַר רַבִּי שִׁמְעוֹן, מָה הַטַּעַם שֶׁהַהִתְגַּלּוּת הָרִאשׁוֹנָה שֶׁהִתְגַּלָּה הַקָּדוֹשׁ בָּרוּךְ הוּא עַל אַבְרָהָם פּוֹתַחַת בְּלֶךְ לְךְ, שֶׁהֲרֵי עַד כָּאן לֹא דִבֵּר עִמּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא. מָה הַטַּעַם פָּתַח בְּלֶךְ לְךְ? אֶלָּא זֶה אָמְרוּ שֶׁרָמַז בְּחֶשְׁבּוֹנוֹ מֵאָה, שֶׁהֲרֵי לְמֵאָה שָׁנִים נוֹלַד לוֹ בֵּן."],[2,"","אֲבָל בֹּא תִרְאֶה, כָּל מַה שֶּׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בָּאָרֶץ, הַכֹּל הוּא סוֹד שֶׁל חָכְמָה. מִשּׁוּם שֶׁאַבְרָהָם לֹא הָיָה דָבוּק בַּקָּדוֹשׁ- בָּרוּךְ-הוּא אָז כָּרָאוּי, אָמַר לוֹ לֶךְ לְךְ. וְזֶה רֶמֶז לַמָּקוֹם הַהוּא שֶׁצָּרִיךְ לְהִתְקָרֵב עִם הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהִיא הַדַּרְגָּה הָרִאשׁוֹנָה לְהִכָּנֵס לַקָּדוֹשׁ-בָּרוּךְ- הוּא, מִשּׁוּם כָּךְ לֶךְ לְךְ."],[3,"","וּבַדַּרְגָּה הַזּוֹ לֹא יָכוֹל אַבְרָהָם לְהֵאָחֵז בָּהּ עַד שֶׁיִּכָּנֵס לָאָרֶץ, שֶׁשָּׁם יְקַבֵּל אֶת הַדַּרְגָּה הַהִיא. כְּמוֹ כֵן כָּתוּב (שמואל ב ב) וַיִּשְׁאַל דָּוִד בַּה' לֵאמֹר הַאֶעֱלֶה בְּאַחַת מֵעָרֵי יְהוּדָה וַיֹּאמֶר ה' עֲלֵה וַיֹּאמֶר דָּוִד אָנָה אֶעֱלֶה וַיֹּאמֶר חֶבְרוֹנָה. וְכִי כֵּיוָן שֶׁמֵּת שָׁאוּל וְהַמַּלְכוּת רְאוּיָה לְדָוִד, לָמָּה לֹא קִבֵּל אֶת הַמַּלְכוּת מִיָּד עַל כָּל יִשְׂרָאֵל?"],[4,"","אֶלָּא הַכֹּל הוּא סוֹד שֶׁל חָכְמָה, מִשּׁוּם שֶׁדָּוִד אֵין לוֹ לְקַבֵּל מַלְכוּת אֶלָּא עַד שֶׁיִּתְחַבֵּר עִם הָאָבוֹת שֶׁהֵם בְּחֶבְרוֹן, וְאָז יְקַבֵּל בָּהֶם מַלְכוּת. וְעַל כֵּן הִתְעַכֵּב שָׁם שֶׁבַע שָׁנִים, כְּדֵי שֶׁיְּקַבֵּל מַלְכוּת כָּרָאוּי, וְהַכֹּל בְּסוֹד הַחָכְמָה וּכְדֵי שֶׁיְּתַקֵּן אֶת מַלְכוּתוֹ. כְּמוֹ כֵן אַבְרָהָם לֹא נִכְנַס לִבְרִיתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא עַד שֶׁנִּכְנַס לָאָרֶץ."],[5,"","רְאֵה מַה כָּתוּב, וַיַּעֲבֹר אַבְרָם בָּאָרֶץ. וַיַּעֲבר? וַיֵּלֶךְ הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא כָּאן הוּא רֶמֶז הַשֵּׁם הַקָּדוֹשׁ שֶׁנֶּחְתָּם בּוֹ הָעוֹלָם בְּשִׁבְעִים וּשְׁתַּיִם אוֹתִיּוֹת חֲקוּקוֹת שֶׁכֻּלָּן בַּשֵּׁם הַזֶּה. כָּתוּב כָּאן וַיַּעֲבֹר, וְכָתוּב שָׁם (שמות לד) וַיַּעֲבֹר ה' עַל פָּנָיו וַיִּקְרָא."],[6,"","בְּסִפְרוֹ שֶׁל רַבִּי יֵיסָא הַזָּקֵן כָּתוּב, וַיַּעֲבֹר אַבְרָם בָּאָרֶץ, וְכָתוּב שָׁם (שם לג) אֲנִי אַעֲבִיר כָּל טוּבִי. וְהוּא רֶמֶז לִקְדֻשַּׁת הָאָרֶץ שֶׁבָּאָה מִמָּקוֹם עֶלְיוֹן כָּרָאוּי."],[7,"","עַד מְקוֹם שְׁכֶם עַד אֵלוֹן מוֹרֶה, מִצַּד זֶה (ד\"א ל\"ג שלמטה) לְצַד זֶה כָּרָאוּי. וְהַכְּנַעֲנִי אָז בָּאָרֶץ, הֲרֵי נִתְבָּאֵר שֶׁעַד כָּעֵת שׁוֹלֵט הַנָּחָשׁ הָרָע שֶׁהִתְקַלֵּל וְהֵבִיא קְלָלוֹת עַל הָעוֹלָם, שֶׁכָּתוּב (בראשית ט) אָרוּר כְּנָעַן עֶבֶד עֲבָדִים יִהְיֶה לְאֶחָיו, וְכָתוּב (שם ג) אָרוּר אַתָּה מִכָּל הַבְּהֵמָה וְגוֹ'. וְשָׁם הִתְקָרֵב אַבְרָהָם לַקָּדוֹשׁ- בָּרוּךְ-הוּא. מַה כָּתוּב? וַיֵּרָא ה' אֶל אַבְרָם. כָּאן הִתְגַּלָּה לוֹ מַה שֶּׁלֹּא הָיָה יוֹדֵעַ אוֹתוֹ הַכֹּחַ הֶעָמֹק שֶׁשּׁוֹלֵט עַל הָאָרֶץ. וּמִשּׁוּם כָּךְ וַיֵּרָא, מַה שֶּׁהָיָה מְכֻסֶּה מִמֶּנּוּ."]]],[["וּכְדֵין וַיִּבֶן שָׁם מִזְבֵּחַ לַיְיָ הַנִּרְאֶה אֵלָיו, כֵּיוָן דְּאָמַר לַיְיָ מַהוּ הַנִּרְאֶה אֵלָיו. אֶלָּא הָכָא אִתְגְּלִי לֵיהּ הַהוּא דַרְגָא דְּשָׁלְטָא עַל אַרְעָא וְעָאל בֵּיהּ וְאִתְקְיַּים בֵּיהּ:","וַיַּעְתֵּק מִשָּׁם הָהָרָה. מִתַּמָּן יָדַע הַר יְיָ. וְכֻלְהוּ דַּרְגִּין דִּנְטִיעִין בְּהַאי אֲתַר. וַיֵּט אָהֳלה בְּהֵ\"א כְּתִיב. פָּרִישׂ פְּרִישׂוּ וְקַבִּיל מַלְכוּ שְׁמַיָא בְּכֻלְהוּ דַּרְגִּין דְּאֲחִידָן בֵּיהּ. וּכְדֵין יָדַע דְּקוּדְשָׁא בְּרִיךְ הוּא שַׁלִּיט עַל כֹּלָּא. וּכְדֵין בָּנָה מִזְבֵּחַ.","וּתְרֵין מַדְבְּחָן הֲווּ, בְּגִין דְּהָכָא אִתְגְּלִי לֵיהּ דְּהָא קוּדְשָׁא בְּרִיךְ הוּא שַׁלִּיט עַל כֹּלָּא וְיָדַע חָכְמָה עִלָּאָה, מַה דְּלָא הֲוָה יָדַע מִקַּדְמַת דְּנָא. וּבָנָה תְּרִין מַדְּבְּחָן חַד לְדַרְגָּא דְּאִתְגַּלְיָא וְחַד לְדַרְגָּא דְּאִתְכַּסְיָא. תָּא חֲזֵי, דְּהָכִי הֲוָה בְּקַדְמִיתָא כְּתִיב וַיִּבֶן שָׁם מִזְבֵּחַ לַיְיָ הַנִּרְאֶה אֵלָיו וְגו'. וּלְבָתַר כְּתִיב וַיִּבֶן שָׁם מִזְבֵּחַ לַיְיָ סְתָם וְלָא כְּתִיב הַנִּרְאֶה אֵלָיו. וְכֹלָּא רָזָא דְחָכְמְתָא אִיהוּ.","וּכְדֵין אִתְעַטַּר אַבְרָהָם מִדַּרְגָּא לְדַרְגָּא עַד דְּסָלִיק לְדַרְגֵּיהּ הֲדָא הוּא דִכְתִיב וַיִּסַּע אַבְרָם הָלוֹךְ וְנָסוֹעַ הַנֶּגְבָּה. דָּא דָרוֹם דְּהוּא חוּלָקֵיהּ דְּאַבְרָהָם. הָלוֹךְ וְנָסוֹעַ דַּרְגָּא בָּתַר דַּרְגָּא עַד דְּסָלִיק לְדָרוֹם וְתַמָּן אִתְקַשַּׁר כְּדְקָא יְאוּת וְסָלִיק לְדַרְגֵּיהּ דְדָרוֹם.","כֵּיוָן דְּאִתְעַטַּר אַבְרָהָם בְּדַרְגּוֹי בְּאַרְעָא קַדִּישָׁא וְעָאל (בארעא) בְּדַרְגָּא קַדִּישָׁא, כְּדֵין מַה כְּתִיב וַיְהִי רָעָב בָּאָרֶץ. דְּלָא הֲווּ יָדְעֵי יְדִיעָה לְקָרְבָא לְגַבֵּי דְקוּדְשָׁא בְּרִיךְ הוּא:","וַיְהִי רָעָב בָּאָרְץ, דְּעַד כְּעָן לָא הֲוָה חֵילָא דְּעַל אַרְעָא יָהִיב תּוּקְפָא וּמְזוֹנָא עַל אַרְעָא, בְּגִין דְּעַד לָא אִתְקַדְּשַׁת (נ\"א אתתקנת) וְלָא קָיְימָא בְּקִיּוּמָא. כֵּיוָן דְּחָמָא אַבְרָהָם דְּהָא הַהוּא חֵילָא דִּמְמַנָּא עַל אַרְעָא לָא יָהִיב תּוּקְפָא וְחֵילָא קַדִּישָׁא כִּדְקָחָזֵי, כְּדֵין וַיֵּרֶד אַבְרָם מִצְרַיְמָה לָגוּר שָׁם.","מְנָא יָדַע אַבְרָהָם, דִּכְתִיב לְזַרְעֲךָ נָתַתִּי אֶת הָאָרֶץ הַזֹּאת. כְּדֵין יָדַע אַבְרָהָם דְּהָא אַרְעָא לָא אִתְתַּקְנָא בְּתִקּוּנָא קַדִּישָׁא אֶלָּא בְּדַרְגִּין (ידיען) קַדִּישִׁין דְּיִפְקוּן מִנֵּיהּ, וּכְדֵין יָדַע אַבְרָהָם רָזָא דְחָכְמְתָא דְּאַרְעָא לָא תִתַּקַּן בִּקְדוּשָׁה אֶלָּא כִּדְאֲמָרָן:","\u0003סִתְרֵי תּוֹרָה\u0004 (מקב\"ה עד ויעבור הוא גליון) קוּדְשָׁא בְּרִיךָ הוּא רָמִיז חָכְמְתָּא עִלָּאָה בְּאַבְרָהָם וּבְיִצְּחָק, אַבְרָהָם דָּא נִשְׁמָתָּא לְנִשְׁמָתָּא וְאִיהִי (ס\"א אב ורם), נְשָׁמָ\"ה דא הִיא שָׂרָה. לוֹט דָּא הוּא נָחָ\"שׁ וּבַתּ זוּגֵיהּ דְּהַהוּא סמאל. רוּ\"חַ קַדִּישָׁא דָּא יִצְּחָק. נְפֶּ\"שׁ קַדִּישָׁא דָּא רִבְקָה. יֵצֶּ\"ר הָרָע דָּא רוּחַ הַבְּהֵמָה, ועל דָּא אָמַר שְׁלֹמֹה בְּחָכְמָתֵּיהּ (קהלת ג׳:כ״א) מִי יוֹדֵעַ רוּחַ בְּנֵי הָאָדָם הָעוֹלָה הִיא וְגו' נְפֶּשׁ הַבַּהֲמִיתּ דָּא נְפֶּשׁ מִסִּטְרָא דְּיֵצֶּר הָרָע.","וְעַל דָּא אָמְרוּ (נ\"א דההוא) דְּאִיהִי נִשְׁמָתָּא לְנִשְׁמָתָּא אִתְּעֲרָא לְגַבְרָא בְּיִרְאָ\"ה וּבְחָכְמְ\"תָּא, נִשְׁמָתָּא אִתְּעֲרָא לְאִינִישׁ בְּבִינָה, הֲדָא הוּא דִכְתִּיב, (איוב כ״ח:כ״ח) וַיֹּאמֶר לָאָדָם הֵן יִרְאַתּ יְיָ הִיא חָכְמָה וְגו'. נִשְׁמָ\"תָּא אִתְּעֳרֵי בִּתְּשׁוּבָ\"ה דְּאִתְּקְרֵי בִּינָה וְאִקְרֵי שָׂרָ\"ה. וְרוּ\"חַ הוּא הַקּוֹ\"ל וְאִתְּקְרֵי דַעַתּ וְאִתְּעֳרֵי לְאִינִישׁ דִּי סָלִיק קָלֵיהּ בְּאוֹרַיְיתָּא, וְאִתְּקְרֵי תּוֹרָה שֶׁבִּכְתָּב, וְנְפֶּשׁ הַשִׂכְלִיתּ אִתְּעָר מִנֵּיהּ עוֹבָדִין טָבִין.","וּבְדוּגְמָא דָא בָּרָא גוּפָּא מֵאַרְבַּע יְסוֹדוֹתּ אֵשׁ וְרוּחַ וְעָפָּר וּמַיִם כְּגַוְונָא דְהוּא נִשְׁמָתָּא לְנִשְׁמָתָּא נְשָׁמָה וְרוּחַ וְנֶפֶּשׁ. מַיִם דָּא דְּכַר ודא הוּא מַיִם מְתִּיקֵי דִקְדוּשָׁה, וְאִיתּ מַיִם הַמְאָרְרִים דְּאִנּוּן יֵצֶּר הָרָע. אִיתּ אֶשָׁא קַדִּישָׁא נוּקְבָא וְאִיתּ אֶשָׁא נוּכְרָאָה אש זָרָה, וְעַל דָּא כְּתִּיב וְאַל יָבֹא בְּכָל עֵתּ אֶל הַקֹּדֶשׁ, דְּאִיהִי נוּקְבְתָּא מִן יֵצֶּר הָרָע. רוּחַ קַדִּישָׁא אִיהוּ דְּכַר. אִיתּ רוּחַ מְסָאֳבָא דָּא יֵצֶּר הָרָע שֶׁנֶּאֱמַר (ישעיהו י״ד:כ״ט) כִּי מִשֹׁרֶשׁ נָחָשׁ יִצֻּא צֶּפַּע. אִיתּ עָפָּר קַדִּישָׁא ואִיתּ עָפָּר מְסָאֳבָא.","וְעַל דּא נִשְׁמָתָּא דְּאִיהִי תְּשׁוּבָ\"ה אַתְּקִיפַּתּ בֵּיהּ בְּהַהוּא נָחָשׁ לְתַּבְרָא לֵיהּ בְּשִׁעְבּוּדָא דִּתְּשׁוּבָה ואַמְשִׁיךָ לֵיהּ לְבָתֵּי כְנֵסִיּוֹתּ וּלְבָתֵּי מִדְרָשׁוֹתּ, וְאִנּוּן אַרְבַּע יְסוֹדֵי מִתְּפַּשְׁטִין לְכ\"ב אַתְּוָון אחה\"ע בומ\"ף גיכ\"ק דטלנ\"תּ זסשר\"ץ. (עד כאן גליון):","וַיַּעֲבֹר אַבְרָם בָּאָרֶץ עַד מְקוֹם שְׁכֶם. דָּא בֵּי כְּנִישְׁתָּא אֲתַּר דְּדִיּוּרָא דִּשְׁכִינְתָּא תַּמָּן כְּמָא דְאַתְּ אָמֵר, (בראשית מ״ח:כ״ב) ואֲנִ\"י נָתַּתִּי לְךָ שְׁ'כֶ'ם' אֶחָד, דָּא שְׁכִינְתָּא דְּאִתְּחֲזֵי לֵיהּ הוֹאִיל וְאִתְּקְרֵי צַּדִּיק, דְּהָא צֶּדֶק לָאו דִּיּוּרָהּ אֶלָּא בַּהֲדֵי צַּדִּיק, וְדָא הוּא עַד מְקוֹם שְׁכֶם. עַד אֵלוֹן מוֹרֶה אֵלּוּ בָּתֵּי מִדְרָשׁוֹתּ דְּאוֹלְפִּין וּמוֹרִים תַּמָּן תּוֹרָה בָּרַבִּים.","וְהַכְּנַעֲנִי אָז בָּאָרֶץ. כְּדֵין אִתְּבַּסַּם וְאִתְּתַּקַּן יֵצֶּר הָרָע בְּגוּפָּא בְּעַל כָּרְחֵיהּ. דְּסַגִּיאִין שְׁמָהָן אִיתּ לֵיהּ, וּבְגִינֵי כָךָ (אתהדר) אִדְכַּר בִּשְׁמָהָן סַגִּיאִין. אָז בָּאָרֶץ ודּאי וְאִתְּכַּפְּיָא בְּהַאי, בְּגִין דִּכְדֵין אִיהוּ גוּפָּא בְּזִמְנָא דְּלָא אִתְּעֲבַר מִנִּיהּ הַהוּא נָחָשׁ כָּל כָּךָ, בְּגִין דְּבֵקוּתָּא דְּגוּפָּא כְּדֵין הַכְּנַעֲנִי אָז בָּאָרֶץ, אַמַּאי אִקְרֵי כְּנַעֲנִי, דְּאַסְחַר גּוּפָּא לְדִינִין בִּישִׁין.","וְנִשְׁמָתָּא קָיְימָא בְּהַאי עָלְמָא (לאתתקנא אורחוי דגופא) כְּדְקָא יְאוּתּ בְּגִין לְמִזְכֵּי בָּהּ, לְבָתַּר כַּד נָפְּקַתּ מֵהַאי עָלְמָא אִי זָכָאתּ סָלְקָא לְאַתְּרָהּ דְּנָפְּקַתּ מִתַּמָּן דִּכְתִּיב אֶל מְקוֹם הַמִּזְבֵּחַ אשר עָשָׂה שָׁם בָּרִאשׁוֹנָה וּכְתִּיב אֶל הַמָּקוֹם אֲשֶׁר הָיָה שָׁם אָהֳלה בַּתְּחִלָּה. אָהֳלה בְּהֵ\"א.","וְהַשְׁתָּא אִיהִי קָיְימָא בֵּין לְסָלְקָא לְעֵילָא וּבֵין לְנָחֲתָּא לְתַּתָּא. (דכתיב) בֵּין בֵּיתּ אל וּבֵין הָעָי. אִי זָכָאתּ סָלְקָא אל מְקוֹם הַמִּזְבֵּחַ, אֲשֶׁר עָשָׂה שָׁם וְגו'. מַאן עשה וּמַאן מִזְבֵּחַ. אֶלָּא אֲשֶׁר עָשָׂה שָׁם, דָא קוּדְשָׁא בְּרִיךָ הוּא. דְּאִיהוּ עָבַד תַּמָּן הַאי מִזְבֵּחַ וְאַתְּקִין לָהּ על תְּרֵיסַר אַבְנִין לְמִסְפַּר שִׁבְטֵי בְּנֵי יַעֲקֹב אשר הָיָה דְּבַר יְיָ אֵלָיו לֵאמֹר יִשְׂרָאֵל יִהְיְה שְׁמֶךָ ודַּאי.","וּמִזְבֵּחַ דָּא עָשָׂה שָׁם בָּרִאשׁוֹנָה כַּד אִתְּבְּרֵי עָלְמָא עִלָּאָה (עלאה) טְמִירָא לְכָל עָלְמִין, וּמִיכָאֵ\"ל כַּהֲנָא רַבָּא קָאִים וּמַקְרִיב עֲלָהּ קָרְבָּנִין דְּנִשְׁמָתִּין, כֵּיוָן דְּנִשְׁמָתָּא סָלְקָא תַּמָּן מַה כְּתִּיב וַיִּקְרָא שָׁם אַבְרָם בּשם יְיָ, נִשְׁמָתָּא קָארֵי תַּמָּן וְאִצְּרִירָא בִּצְּרוֹרָא דְחַיֵּי."],[[0,"וכדין ויבן שם מזבח לה' הנראה אליו","ושואל, כיון דאמר \u0003לה'\u0004 למה צריך לומר עוד, \u0003הנראה אליו,\u0004 ואומר, אלא כאן נגלה לו אותה המדרגה השולטת על הארץ, ונכנס בה ונתקיים בה, דהיינו שנגלה לו סוד שליטת המנעולא על הארץ, \u0003ועאל ביה,\u0004 דהיינו שקבל קומת הזווג שיצאה עליה. \u0003ואתקיים ביה,\u0004 שנתקיים, לקבל כל המוחין, על ידה, ולולא שליטתה היה נשאר בחשך ולא היה יכול להתקיים, כנ\"ל."],[1,"ויעתק משם ההרה:","משם ידע הר ה', וכל המדרגות הנטועות באותו מקום. פירוש שעלה ממדרגת הנוקבא שבמקום נה\"י שמחזה ולמטה דז\"א להנוקבא שבמקום חג\"ת, שמחזה ולמעלה דז\"א, כי חג\"ת נקראים הרים והנוקבא אשר שם נקראת \u0003הר ה',\u0004 והשיג שם כל המדרגות הנטועות במקום חג\"ת. \u0003ויט אהלה בה' כתיב,\u0004 הרומז על הנוקבא ולא כתוב אהלו עם ו' כי פרש מסך וקבל מלכות שמים, בכל המדרגות התליות בה. ואז ידע, שהקב\"ה מושל על הכל, ואז בנה מזבח. פירוש, ויט אהלה, עם \u0003ה'\u0004 רומז על תקון המסך שפרש אברהם, במקום החזה דהיינו שעשה גבול להבדיל בין המדרגות שמחזה ולמעלה לבין המדרגות שמחזה ולמטה, שלא להמשיך ממעלה למטה. שבזה קבל הארת המלכות שמים שמחזה ולמעלה, המכונית לאה, בכל המדרגות שבה. והיא מרומזת בסוד \u0003ה\u0004 של אהל \u0003ה. ואהל\u0004 פירושו מסך ופרסא שפרש מתחתיה."],[2,"ותרין מדבחן","וכו': ושני מזבחות היו משום דכאן נגלה לו שהקב\"ה שולט על הכל. שהיא בחינת מחזה ולמעלה. גם ידע חכמה עליונה מה שלא השיג מקודם לכן. שהוא בחינת מחזה ולמטה. וע\"כ \u0003ובנה תרין מדבחן\u0004 ב' מזבחות בנה. מזבח אחד להמדרגה שנגלה, דהיינו להנוקבא שמחזה ולמטה דז\"א המכונה רחל. שה\"ס \u0003עלמא דאתגליא,\u0004 שפירושו, שהארותיה מגולות בחכמה. ומזבח אחד למדרגה המכוסה, דהיינו להנוקבא שמחזה ולמעלה דז\"א, המכונה לאה, שה\"ס \u0003עלמא דאתכסיא.\u0004 שפירושו שמאירה בחסדים מכוסים מחכמה. בוא וראה שכן הוא, כי מתחילה כתוב ויבן מזבח \u0003לה' הנראה\u0004 אליו ואחר כך כתוב, ויבן שם מזבח \u0003לה',\u0004 סתם, ולא כתוב, \u0003הנראה אליו,\u0004 וכל זה הוא בסוד החכמה, פירוש: כי מזבח הראשון בנה במדרגת הנוקבא שמחזה ולמטה, שה\"ס עלמא דאתגליא, וע\"כ כתוב לה' הנראה אליו. ומזבח הב' בנה במדרגת הנוקבא שמחזה ולמעלה שה\"ס עלמא דאתכסיא, ע\"כ לא כתוב בה לה' הנראה אליו, אלא לה' סתם, ומשמיענו הכתוב, כי אחר שגילה והמשיך המוחין בסוד החסדים המגולים בחכמה, במדרגת הנוקבא שמחזה ולמטה, בסוד, ויבן שם מזבח לה' הנראה אליו. לא נשאר בהמוחין ההם. אלא עלה למעלה מחזה והמשיך המוחין בבחינת חסדים מכוסים מחכמה, כמדרגת הנוקבא שמחזה ולמעלה דז\"א, וטעם הדבר, כי אברהם היה מרכבה לז\"א, וז\"א אינו מקבל חכמה לעצמו אלא בשעה שהוא משפיע להנוקבא. (כנ\"ל דף ט' ד\"ה וז\"ש ע\"ש). וע\"כ בחר גם אברהם בחסדים מכוסים."],[3,"וכדין אתעטר אברהם","וכו': ואז נתעטר אברהם ממדרגה למדרגה, עד שעלה למדרגתו. וז\"ש ויסע אברהם הלוך ונסוע הנגבה, זהו דרום דהיינו שרצה לזכות במדרגת חסד דז\"א המכונה דרום, שהוא חלקו של אברהם, כלומר שהוא היה עתיד להיות מרכבה לספירת החסד דז\"א, וע\"כ היה \u0003הלוך ונסוע,\u0004 מדרגה אחר מדרגה עד שעלה לדרום, ונתקשר שם כראוי דהיינו שתקן את עצמו, שיוכל להחזיק במדרגת החסד בקביעות. ואז ועלה למדרגתו של הדרום. דהיינו שזכה להיות מרכבה לחסד דז\"א הנקרא דרום."],[4,"וכיון דאתעטר אברהם","וכו': אחר שנתעטר אברהם במדרגותיו בארץ הקודש, שה\"ס המוחין מעלמא דאתגליא, רחל, הנקראת ארץ הקודש. ונכנס בהמדרגה הקדושה דהיינו מדרגת החסד ובבחינת עלמא דאחכסיא, לאה, כנ\"ל בדבור הסמוך, מה כתוב אז, \u0003ויהי רעב בארץ,\u0004 שפירושו שלא היו יודעים הידיעה איך להתקרב אל הקב\"ה. דהיינו בסו\"ה, (עמוס ח' י\"א) לא רעב ללחם לא צמא למים כי אם לשמוע את דברי ה'. והטעם, מביא הזהר לפנינו בסמוך."],[5,"ויהי רעב בארץ","וכו': כי עד עתה עוד לא היה הכח השולט על הארץ, שהוא המסך דמנעולא, נותן גבורה ומזונות על הארץ, משום שעוד לא נתקנה הנוקבא לגמרי, ולא היתה בקיומה כראוי, פירוש, כי כל התקונים שנמשכו עד עתה להנוקבא, היו מבחינת המפתחא, שה\"ס הכלים דאמא (כנ\"ל דף י\"ג ד\"ה ולפיכך) אבל מבחינת מנעולא שה\"ס בחינתה עצמה של המלכות, עוד לא המשיך התקונים המיוחדים לה, וע\"כ מבחינה זו היה רעב בארץ. שלא היה יודע ומשיג איך להתקרב עמה להקב\"ה, כנ\"ל בדבור הסמוך."],[5,"כיון דחמא אברהם וכו':","כיון שראה אברהם כי אותו הכח הממונה על הארץ, דהיינו המנעולא אינו נותן גבורה וכח קדוש כראוי. אז וירד אברם מצרימה לגור שם."],[6,"מנא ידע אברהם וכו':","ושואל, מאין ידע אברהם, שהארץ, שהיא הנוקבא, עוד חסרת תקונים. ומשיב, דכתיב, לזרעך אתן את הארץ הזאת. ואינו אומר, לך ולזרעך אתן את הארץ הזאת אז ידע אברהם, שהארץ לא תתקן בתקון הקדוש אלא ע\"י המדרגות הקדושות שיולדו ממנו, שעליהם נאמר לזרעך אתן את הארץ הזאת, ולא לו. ואז ידע אברהם סוד החכמה מפני מה הארץ לא תתקן בקדושה אלא רק כמו שאמרנו. וע\"כ ירד מצרימה, כדי לתקן משם את החסרון."],[7,"קב\"ה רמיז חכמתא עלאה באברהם","וכו': הקב\"ה רמז חכמה העליונה באברהם ויצחק. אברהם הוא נשמה לנשמה דהיינו אור החיה. נשמה זו שרה. לוט זהו נחש שהוא בת זוגו של אותו סמאל. רוח הקדוש, זה יצחק. נפש הקדושה זו רבקה. יצר הרע זהו רוח הבהמה. ועליו אמר שלמה בחכמתו, מי יודע רוח בני האדם העולה היא למעלה, ורוח הבהמה היורדת היא למטה לארץ. נפש הבהמית זו היא נפש מצד היצר הרע."],[8,"ועל דא אמרו וכו':","ועל זה אמרו, כי אותה \u0003נשמה לנשמה,\u0004 באה לאדם, \u0003ביראה בחכמה,\u0004 כלומר שמקובלת מספירת החכמה, ביראה וחכמה. \u0003הנשמה\u0004 באה לאדם, \u0003בבינה.\u0004 וז\"ש הן יראת ה' היא חכמה. וע\"כ אין נשמה לנשמה באה אלא על ידי יראה וחכמה. אבל הנשמה באה לאדם על ידי \u0003תשובה,\u0004 הנקראת בינה, ונקראת שרה. \u0003ורוח\u0004 הוא שנקרא קול, ונקרא \u0003דעת,\u0004 והוא נמשך לאדם המגביר קולו בתורה. והרוח גם נקרא תורה שבכתב. \u0003ונפש\u0004 השכלית, נמשך ממנה מעש\"ט. פירוש. חכמה בינה דעת, נמשכים מהם נשמה לנשמה, ונשמה, ורוח ונפש: הנשמה לנשמה ה\"ס אברהם. ונמשך מספירת החכמה. הנשמה ה\"ס שרה, ונמשכת מספירת הבינה. הרוח ה\"ס יצחק ונמשך מספירת הדעת. וכן הנפש שה\"ס רבקה, נמשכת מדעת. הרוח ה\"ס הימין של הדעת. והנפש ה\"ס שמאל של הדעת."],[9,"ובדוגמא דא ברא גופא","וכו': וכעין זה, ברא הקב\"ה את הגוף מארבעה יסודות, שהם אש, רוח, עפר, ומים. בדומה אל הנשמה לנשמה, נשמה, רוח ונפש. הנשמה לנשמה ה\"ס מים. הנשמה ה\"ס אש. הרוח, ה\"ס רוח. הנפש ה\"ס עפר. מים, זהו בחי' זכר דהיינו בדומה לנשמה לנשמה, הבאה מחכמה, וזהו מים מתוקים דקדושה. ויש לעומתם מים המאררים שהם יצר הרע. שה\"ס סמאל. יש אש קדוש, שהיא בחינת נקבה, דהיינו בדומה לנשמה הבאה מבינה, ויש לעומתה, אש זרה, שעליה כתוב ואל יבוא בכל עת אל הקודש, שהיא הנוקבא מצד היצר הרע. דהיינו הנחש שהוא הנוקבא של סמאל. רוח קדוש הוא זכר. דהיינו בדמיון הרוח הבא מספירת הדעת. ויש לעומתו רוח טמא, הוא היצר הרע, שעליו נאמר משרש נחש יצא צפע. דהיינו רוח הבהמה הנק' צפע, והוא תולדה של הנחש דטומאה, דהיינו מבינה דטומאה. וע\"כ אומר הכתוב משורש נחש יצא צפע. ויש עפר קדוש, דהיינו בדומה לנפש הבאה משמאל הדעת. ויש לעומתה עפר טמא דהיינו הנפש הבהמי שהיא מצד היצר הרע."],[10,"ועל דא נשמתא וכו':","ועל כן הנשמה, שהיא תשובה, דהיינו בינה, מתקפת בו באותו הנחש לשבר אותו בכח השעבוד של התשובה, ומושך אותו לבתי כנסיות ולבתי מדרשות. ואלו ארבעה יסודות שהם ד' בחינות חכמה, בינה, ת\"ת ומלכות. מתפשטים לכ\"ב אותיות היוצאים מה' מוצאות הפה, \u0003אחה\"ע\u0004 מגרון. \u0003בומ\"ף\u0004 משפתים. \u0003גיכ\"ק\u0004 מחיך. \u0003דטלנ\"ת,\u0004 מלשון. \u0003זסשר\"ץ\u0004 משנים. כי אלו ה' מוצאות הם כנגד כתר, חו\"ב ותו\"מ, שהם ארבע היסודות מים אש רוח עפר כנ\"ל. וע\"כ אומר, שהד' יסודות, שהם סוד ה' מוצאות הפה הללו, מתפשטים בהם כ\"ב אותיות (ע\"כ גליון)."],[11,"ויעבור וגו' עד מקום שכם:","זהו בית הכנסת, המקום שמדורת השכינה שמה. כמו שאתה אומר ואני נתתי לך שכם אחד, שכם זה השכינה. שהיא ראויה לו ליוסף, הואיל שנקרא צדיק. כי צדק, שהיא השכינה, אין מדורה אלא עם הצדיק, שהוא יוסף. וזה הוא \u0003עד מקום שכם,\u0004 שפירושו, עד מקום השכינה, דהיינו בית הכנסת. \u0003עד אלון מורה,\u0004 הוא בתי מדרשות, שמאלפים ומורים שם תורה ברבים."],[12,") והכנעני אז בארץ:","אז נתמתק היצר הרע ונתתקן בעל כרחו בהגוף שנקרא ארץ. ואל תתמה מה שהיצר הרע נקרא כנעני, כי הרבה שמות יש לו ליצר הרע, והוא נזכר משום זה בהרבה שמות. \u0003אז בארץ,\u0004 ודאי שהוא נכפה בזה, שהוא בגוף, בעת שמאיר בו הנשמה, שה\"ס אברם. כי אז נמצא הגוף, במצב שהנחש עוד לא נעבר ממנו כל כך. ומשום דבקות הגוף שיש עוד להנחש נמצא \u0003הכנעני אז בארץ.\u0004 למה נקרא היצר הרע כנעני, משום שמקיף את הגוף עם דינים רעים כי כנעני פירושו סוחר, שהוא לשון מקיף כמ\"ש צנה וסוחרה אמתו (תהלים צ\"א)."],[13,"ונשמתא קיימא וכו':","והנשמה עומדת בעולם הזה כראוי, כדי לזכות בה אחר שתצא מעולם הזה. ואם היא זכאית היא חוזרת למקום שיצאה משם, שכתוב, אל מקום המזבח אשר עשה שם בראשונה. וכתיב אל המקום אשר היה שם אהלה בתחלה, \u0003אהלה\u0004 כתוב עם \u0003ה'\u0004 שהיא השכינה (כנ\"ל באות ע')."],[14,"והשתא איהי וכו':","ועתה בעולם הזה, היא נמצאת בינתים, בין לעלות למעלה, למקום שיצאה משם, ובין לרדת למטה, למקום העונשים, דהיינו \u0003בין בית אל,\u0004 שהוא למעלה, \u0003ובין העי\u0004 שהוא למטה, במקום העונשים. ודורש \u0003עי\u0004 מלשון \u0003עי\u0004 מפלה."],[14,"אי זכאת סלקא וכו':","שואל, אם היא זוכה עולה אל מקום המזבח אשר עשה וגו', לפי\"ז, מי הוא \u0003אשר עשה\u0004 ומה הוא \u0003מזבח.\u0004 ומשיב. אלא \u0003אשר עשה שם\u0004 זהו הקב\"ה, שהוא עשה שם \u0003מזבח\u0004 הזה, דהיינו השכינה ותקן אותה על י\"ב אבנים למספר שבטי בני יעקב, אשר היה דבר ה' אליו לאמור, ישראל יהיה שמך, בודאי. פירוש. העשר ספירות כשמתוקנים להאיר בהארת חכמה מתחלקות לי\"ב. (כנ\"ל בהקדמת הזהר דף ז' ד\"ה ועם זה) וה\"ס בנין השכינה בשלמות ע\"י ז\"א בעלה, שאז נקרא ז\"א בשם \u0003ישראל.\u0004 שהוא נוטריקון \u0003לי ראש\u0004 וזסו\"ה, \u0003ישראל יהיה שמך,\u0004 דהיינו שמקבלת ראש וג\"ר מישראל בעלה."],[15,"ומזבח דא עשה וכו':","ומזבח זה, שהוא השכינה, עשה שם בראשונה, כאשר נברא עולם העליון הנסתר מכל העולמות, ומיכאל, המלאך, כהן הגדול, עומד ומקריב עליו קרבנות מנשמות הצדיקים, כיון שהנשמה עולה שמה לקרבן מה כתוב עליה, ויקרא שם אברם בשם ה', הנשמה קוראת שם בשם ה', ונקשרת בקשר החיים. פירוש. הבינה. נקראת עולם העליון, הנסתר מכל העולמות היינו בינה דא\"א. ומשמיענו שבנין המזבח על י\"ב אבנים, הוא נבנה תחלה בעולם העליון הנסתר מכל העולמות, דהיינו הבינה דא\"א שיצאה לחוץ מראש א\"א, ונבנית שם בסוד י\"ג תקוני דיקנא. (כמ\"ש בתע\"ס שיעור י\"ג) ועליה רומז הכתוב, \u0003אשר עשה שם בראשונה,\u0004 ומשם מקבל \u0003המזבח,\u0004 שהוא השכינה, את המוחין הגדולים השלימים מהארת החכמה. \u0003ומיכאל המלאך\u0004 ה\"ס אור החסד, שהוא המקרב את הנשמה ומעלה אותה מבי\"ע אל המזבח דאצילות. כלומר שבכח אור החסדים שהנשמה מקבלת יכולה לעלות ולהתדבק בשכינה. ומקבלת ממנה, השלימות הגדול דהארת החכמה, מסוד י\"ג תקוני דיקנא. וזהו שאומר, \u0003נשמתא קארי תמן, ואצרירא בצרורא דחיי,\u0004 שהנשמה קוראת שם בשם ה' ונקשרת בקשר החיים. כי המוחין דחכמה, נקראים אור החיים."]],[[0,"","וְאָז וַיִּבֶן שָׁם מִזְבֵּחַ לַה' הַנִּרְאֶה אֵלָיו. כֵּיוָן שֶׁאָמַר לַה', מַה זֶּה הַנִּרְאֶה אֵלָיו? אֶלָּא כָּאן הִתְגַּלְּתָה לוֹ אוֹתָהּ הַדַּרְגָּה שֶׁשּׁוֹלֶטֶת עַל הָאָרֶץ, וְנִכְנַס בָּהּ וְהִתְקַיֵּם בָּהּ."],[1,"","וַיַּעִִתֵּק מִשָּׁם הָהָרָה. מִשָּׁם יָדַע הַר ה' וְכָל הַדְּרָגוֹת הַנְּטוּעוֹת בַּמָּקוֹם הַזֶּה. וַיֵּט אָהֳלֹה, כָּתוּב בְּהֵ\"א. פָּרַשׂ פְּרִישָׂה וְקִבֵּל מַלְכוּת שָׁמַיִם בְּכָל הַדְּרָגוֹת שֶׁאֲחוּזוֹת בּוֹ, וְאָז יָדַע שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹלֵט עַל הַכֹּל, וְאָז בָּנָה מִזְבֵּחַ."],[2,"","וּשְׁנֵי מִזְבְּחוֹת הָיוּ, מִשּׁוּם שֶׁכָּאן הִתְגַּלָּה לוֹ שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹלֵט עַל הַכֹּל, וְיָדַע הַחָכְמָה הָעֶלְיוֹנָה מַה שֶּׁלֹּא הָיָה יוֹדֵעַ מִלִּפְנֵי כֵן. וּבָנָה שְׁנֵי מִזְבְּחוֹת - אֶחָד לַדַּרְגָּה הַגְּלוּיָה, וְאֶחָד לַדַּרְגָּה הַנִּסְתֶּרֶת. בֹּא רְאֵה שֶׁכָּךְ הָיָה בָּרִאשׁוֹנָה. כָּתוּב וַיִּבֶן שָׁם מִזְבֵּחַ לַה' הַנִּרְאֶה אֵלָיו וְגוֹ', וְאַחַר כָּךְ כָּתוּב וַיִּבֶן שָׁם מִזְבֵּחַ לַה' סְתָם, וְלֹא כָתוּב הַנִּרְאֶה אֵלָיו, וְהַכֹּל הוּא סוֹד שֶׁל חָכְמָה."],[3,"","וְאָז הִתְעַטֵּר אַבְרָהָם מִדַּרְגָּה לְדַרְגָּה עַד שֶׁעָלָה לְדַרְגָּתוֹ. זֶהוּ שֶׁכָּתוּב וַיִּסַּע אַבְרָם הָלוֹךְ וְנָסוֹעַ הַנֶּגְבָּה. זֶה הַדָּרוֹם, שֶׁהוּא חֶלְקוֹ שֶׁל אַבְרָהָם, הָלוֹךְ וְנָסוֹעַ דַּרְגָּה אַחַר דַּרְגָּה עַד שֶׁעָלָה לַדָּרוֹם וְשָׁם נִקְשַׁר כָּרָאוּי, וְעָלָה לְדַרְגָּתוֹ שֶׁל הַדָּרוֹם."],[4,"","כֵּיוָן שֶׁאַבְרָהָם הִתְעַטֵּר בְּדַרְגָּתוֹ בָּאָרֶץ הַקְּדוֹשָׁה וְנִכְנַס (בארץ) לַדַּרְגָּה הַקְּדוֹשָׁה, אָז מַה כָּתוּב? וַיְהִי רָעָב בָּאָרֶץ, שֶׁלֹּא הָיוּ יוֹדְעִים יְדִיעָה לְהִתְקָרֵב אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא."],[5,"","וַיְהִי רָעָב בָּאָרֶץ, שֶׁעַד כָּעֵת לֹא הָיָה הַכֹּחַ שֶׁעַל הָאָרֶץ נוֹתֵן חֹזֶק וּמָזוֹן עַל הָאָרֶץ, מִשּׁוּם שֶׁטֶּרֶם הִתְקַדְּשָׁה (נ\"א: נתקנה) וְלֹא עָמְדָה בְקִיּוּם. כֵּיוָן שֶׁאַבְרָהָם רָאָה אֶת אוֹתוֹ הַכֹּחַ הַמְמֻנֶּה עַל הָאָרֶץ, לֹא נָתַן חֹזֶק וְכֹחַ קָדוֹשׁ כָּרָאוּי, אָז וַיֵּרֶד אַבְרָם מִצְרַיִם לָגוּר שָׁם."],[6,"","מִנַּיִן יָדַע אַבְרָהָם? שֶׁכָּתוּב לְזַרְעֲךְ נָתַתִּי אֶת הָאָרֶץ הַ את. אָז יָדַע אַבְרָהָם שֶׁהִנֵּה הָאָרֶץ לֹא נִתְקְנָה בְּתִקּוּן קָדוֹשׁ, אֶלָּא בִּדְרָגוֹת (ידועות) קְדוֹשׁוֹת שֶׁיֵּצְאוּ מִמֶּנּוּ. וְאָז יָדַע אַבְרָהָם אֶת סוֹד הַחָכְמָה, שֶׁהָאָרֶץ לֹא תִתַּקֵּן בִּקְדֻשָּׁה, אֶלָּא כְּפִי שֶׁאָמַרְנוּ."],[7,"","הַקָּדוֹשׁ בָּרוּךָ הוּא רוֹמֵז חָכְמָה עֶלְיוֹנָה בְּאַבְרָהָם וּבְיִצְחָק. אַבְרָהָם זוֹ הַנְּשָׁמָה לִנְשָׁמָה וְהִיא (ס\"א אב ורם), וְהַנְּשָׁמָה הַזּוֹ הִיא שָׂרָה. לוֹט זֶה הוּא הַנָּחָ\"שׁ וּבַת זוּגוֹ שֶׁל הַסמא\"ל הַהוּא. רוּ\"חַ הַקְּדוֹשָׁה זֶה יִצְחָק. נֶפֶ\"שׁ הַקְּדוֹשָׁה זוֹ רִבְקָה. יֵצֶ\"ר הָרָע זוֹ רוּחַ הַבְּהֵמָה, וְעַל זֶה אָמַר שְׁלֹמֹה בְּחָכְמָתוֹ (קהלת ג) מִי יוֹדֵעַ רוּחַ בְּנֵי הָאָדָם הָעֹלָה הִיא וְגוֹ'. נֶפֶשׁ הַבַּהֲמִית זוֹ הַנֶּפֶשׁ מִצַּד הַיֵּצֶר הָרָע."],[8,"","וְעַל זֶה אָמְרוּ (שההוא) שֶׁהַנְּשָׁמָה לִנְשָׁמָה הַזּוֹ מְעוֹרֶרֶת אֶת הָאִישׁ בְּיִרְאָ\"ה וּבְחָכְמָ\"ה. הַנְּשָׁמָה מְעוֹרֶרֶת אֶת הָאִישׁ בְּבִינָה. זֶהוּ שֶׁכָּתוּב (איוב כח) וַיֹּאמֶר לָאָדָם הֵן יִרְאַת ה' הִיא חָכְמָה וְגוֹ'. הַנְּשָׁמָ\"ה מְעוֹרֶרֶת בִּתְשׁוּבָ\"ה שֶׁנִּקְרֵאת בִּינָה וְנִקְרֵאת שָׂרָ\"ה. וְרוּ\"חַ הוּא הַקּוֹ\"ל, וְנִקְרָא דַעַת, וּמְעוֹרְרִים אֶת הָאִישׁ שֶׁקּוֹלוֹ עוֹלֶה בַתּוֹרָה, וְנִקְרָא תוֹרָה שֶׁבִּכְתָב, וְהַנֶּפֶשׁ הַשִּׂכְלִית מִתְעוֹרְרִים מִמֶּנָּהּ מַעֲשִׂים טוֹבִים."],[9,"","וּבַדֻּגְמָה הַזּוֹ בָּרָא אֶת הַגּוּף מֵאַרְבָּעָה יְסוֹדוֹת - אֵשׁ וְרוּחַ וְעָפָר וּמַיִם, כְּמוֹ שֶׁהוּא נְשָׁמָה לִנְשָׁמָה, נְשָׁמָה וְרוּחַ וְנֶפֶשׁ. מַיִם זֶה זָכָר, וְזֶהוּ הַמַּיִם הַמְּתוּקִים שֶׁל קְדֻשָּׁה. וְיֵשׁ מַיִם הַמְאָרְרִים שֶׁהֵם יֵצֶר הָרָע. יֵשׁ אֵשׁ קְדוֹשָׁה נְקֵבָה, וְיֵשׁ אֵשׁ נָכְרִיָּה, אֵשׁ זָרָה. וְעַל זֶה כָּתוּב וְאַל יָבא בְכָל עֵת אֶל הַקֹּדֶשׁ, שֶׁהִיא נְקֵבָה מִיֵּצֶר הָרָע. רוּחַ קְדוֹשָׁה הִיא זָכָר. יֵשׁ רוּחַ טֻמְאָה, זֶה יֵצֶר הָרָע, שֶׁנֶּאֱמַר (ישעיה יד) כִּי מִשֹּׁרֶשׁ נָחָשׁ יֵצֵא צֶפַע. יֵשׁ עָפָר קָדוֹשׁ וְיֵשׁ עָפָר טָמֵא."],[10,"","וְעַל זֶה, הַנְּשָׁמָה שֶׁהִיא תְשׁוּבָ\"ה, מִתְגַּבֶּרֶת בְּאוֹתוֹ הַנָּחָשׁ לִשְׁבֹּר אוֹתוֹ בְּשִׁעְבּוּד שֶׁל תְּשׁוּבָה, וּמוֹשֵׁךְ אוֹתוֹ לְבָתֵּי כְּנֵסִיּוֹת וּבָתֵּי מִדְרָשׁוֹת, וְאוֹתָם אַרְבַּעַת הַיְסוֹדוֹת מִתְפַּשְּׁטִים לְכ\"ב אוֹתִיּוֹת, אחה\"ע בומ\"ף גיכ\"ק דטלנ\"ת זסשר\"ץ."],[11,"","וַיַּעָבֹר אַבְרָם בָּאָרֶץ עַד מְקוֹם שְׁכֶם - זֶה בֵּית הַכְּנֶסֶת, מְקוֹם דִּיּוּר הַשְּׁכִינָה שָׁם, כְּמוֹ שֶׁנֶּאֱמַר (בראשית מח) וַאֲנִ\"י נָתַתִּי לְךְ שְׁ'כֶ'ם אַחַד. זוֹ שְׁכִינָה שֶׁרְאוּיָה לוֹ, הוֹאִיל וְנִקְרָא צַדִּיק, שֶׁהֲרֵי הַצֶּדֶק אֵין דִּיּוּרָהּ אֶלָּא עִם צַדִּיק, וְזֶהוּ עַד מְקוֹם שְׁכֶם. עַד אֵלוֹן מוֹרֶה - אֵלּוּ בָּתֵּי מִדְרָשׁוֹת שֶׁלּוֹמְדִים וּמוֹרִים שָׁם תּוֹרָה בָּרַבִּים."],[12,"","וְהַכְּנַעָנִי אָז בָּאָרֶץ - אָז נִמְתַּק וְנִתְקַן יֵצֶר הָרָע בַּגּוּף בְּעַל כָּרְחוֹ. שֶׁשֵּׁמוֹת רַבִּים יֵשׁ לוֹ, וּמִשּׁוּם כָּךְ (חזר) נִזְכָּר בְּשֵׁמוֹת רַבִּים. אָז בָּאָרֶץ, וַדַּאי, וְנִכְנָע בָּזֶה, מִשּׁוּם שֶׁאָז הַגּוּף בִּזְמַן שֶׁלֹּא בָּטַל מִמֶּנּוּ אוֹתוֹ הַנָּחָשׁ כָּל כָּךְ, מִשּׁוּם דְּבֵקוּת הַגּוּף אָז הַכְּנַעֲנִי אָז בָּאָרֶץ. לָמָּה נִקְרָא כְּנַעֲנִי? שֶׁמְּסוֹבֵב אֶת הַגּוּף לְדִינִים רָעִים."],[13,"","וְהַנְּשָׁמָה עוֹמֶדֶת בָּעוֹלָם הַזֶּה כָּרָאוּי כְּדֵי לִזְכּוֹת בָּהּ, אַחַר כָּךְ יוֹצֵאת מִן הָעוֹלָם הַזֶּה. אִם זוֹכָה - עוֹלָה לִמְקוֹמָהּ שֶׁמִּשָּׁם יָצְאָה, שֶׁכָּתוּב אֶל מְקוֹם הַמִּזְבֵּחַ אֲשֶׁר עָשָׂה שָׁם בָּרִאשּנָה. וְכָתוּב עַד הַמָּקוֹם אֲשֶׁר הָיָה שָׁם אָהֳלֹה בַּתְּחִלָּה. אָהֳלֹ\"ה בְּהֵ\"א."],[14,"","וְכָעֵת הִיא עוֹמֶדֶת בֵּין לַעֲלוֹת לְמַעְלָה וּבֵין לָרֶדֶת לְמַטָּה, (שכתוב) בֵּין בֵּית אֵל וּבֵין הָעָי. אִם זוֹכָה - עוֹלָה אֶל מְקוֹם הַמִּזְבֵּחַ אֲשֶׁר עָשָׂה שָׁם וְגוֹ'. מִי עָשָׂה וְאֵיזֶה מִזְבֵּחַ? אֶלָּא אֲשֶׁר עָשָׂה שָׁם זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁעָשָׂה שָׁם אֶת הַמִּזְבֵּחַ הַזֶּה וְתִקֵּן אוֹתוֹ עַל שְׁתֵּים עֶשְׂרֵה אֲבָנִים לְמִסְפַּר שִׁבְטֵי בְּנֵי יַעֲקֹב אֲשֶׁר הָיָה דְּבַר ה' אֵלָיו לֵאמֹר יִשְׂרָאֵל יִהְיֶה שְׁמֶךְ וַדַּאי."],[15,"","וְהַמִּזְבֵּחַ הַזֶּה עָשָׂה שָׁם בָּרִאשׁוֹנָה כַּאֲשֶׁר נִבְרָא הָעוֹלָם הָעֶלְיוֹן, (עליון) הַטָּמִיר שֶׁל כָּל הָעוֹלָמוֹת, וּמִיכָאֵל הַכֹּהֵן הַגָּדוֹל עוֹמֵד וּמַקְרִיב עָלָיו קָרְבָּנוֹת שֶׁל נְשָׁמוֹת. כֵּיוָן שֶׁעוֹלָה לְשָׁם נְשָׁמָה מַה כָּתוּב? וַיִּקְרָא שָׁם אַבְרָם בְּשֵׁם ה'. הַנְּשָׁמָה קוֹרֵאת שָׁם וְנִצְרֶרֶת בִּצְרוֹר הַחַיִּים."]]],[["וְכָל דָּא, אִי זַכָּאָה בְּהַאי עָלְמָא לְאַתְּקָנָא גּוּפָּא כְּדְקָא יָאוֹתּ וּלְאִכַּפְּיָא (ולאספיא) תּוּקְפָּא דְּהַהוּא לָטְיָיא, עַד דְּאִתְּפָּרְשָׁא מִנֵּיהּ מַה כְּתִּיב, וַיְהִי רִיב בֵּין רוֹעֵי מִקְנֵה אַבְרָם וּבֵין רוֹעֵי מִקְנֵה לוֹט (דא יצר הרע), דְּבְּכָל יוֹמָא וְיוֹמָא בְּהַאי עָלְמָא, אִנּוּן סִיעָן וּמַנְהִיגִי דְּנִשְׁמָתָּא, וְאִנּוּן סִיעָן וּמַנְהִיגִין דְּיֵצֶּר הָרָע, אִנּוּן בְּקִטְרוּגָא מְקַטְרְגִין אִלֵּין בְּאִלֵּין, וְכָל שָׁיְיפִּין דְּגוּפָּא בְּצַּעֲרָא בֵּינַיְיהוּ בֵּין נִשְׁמָתָּא וְהַהוּא נָחָשׁ דְּקָא מַגִּיחִין קְרָבָא בְּכָל יוֹמָא.","מַה כְּתִּיב וַיֹּאמֶר אַבְרָם אל לוֹט. נִשְׁמָתָּא אֲהַדְּרָא לְגַבֵּי יֵצֶּר הָרָע וְאָמַר לֵיהּ, אַל נא תְּהִי מְרִיבָה בֵּינִי וּבֵינְיךָ וּבֵין רוֹעַי וּבֵין רוֹעֶיךָ, סִטְרִין דִּילִי וְסִטְרִין דִּילָךָ. כִּי אֲנָשִׁים אַחִים אֲנַחְנוּ, יִצֶּר טוֹב וְיֵצֶּר הָרָע קְרֵיבִין דָּא בְּדָא, דָּא לִימִינָא וְדָא לִשְׂמָאלָא.","הֲלא כָל הָאָרֶץ לְפָּנְיךָ הִפָּרֶד נָא מֵעָלַי. סַגִּיאִין חַיָּיבַיָא אִנּוּן בְּעָלְמָא, זִיל וְשׁוּט אֲבַּתְּרַיְיהוּ וְאִתְּפְּרַשׁ מֵעִמִּי. אִם הַשְׂמֹאל וְאֵימִינָה וְגו'. וְאוֹכַח לֵיהּ וְאָעִיק לֵיהּ בְּכַמָּה קְרָבִין דְּעָבִיד בַּהֲדֵיהּ בְּכָל יוֹמָא, עד דִּכְתִּיב וַיִּפָּרְדוּ אִישׁ מֵעַל אָחִיו.","כֵּיוָן דְּמִתְּפָּרְשִׁין דָּא מִן דָּא מַה כְּתִּיב, אַבְרָם ישב בְּאֶרֶץ כְּנָעַן. אִתְּיַשְׁבַתּ נִשׁמתָּא בְּאִנּוּן צַּדִּיקַיָא בְּיִשׁוּבָא טַב בִּשְׁלָם. וְלוֹט יָשַׁב בְּעָרֵי הַכִּכָּר, הַהוּא לָטְיָא מְקַטְרְגָא אָזִיל לְקַטְרְגָא וּלְאִתְּחַבְּרָא בְּאֲתַּר דְּחַיָּיבַיָא תַּמָּן דִּכְתִּיב וַיֶּאֱהַל עַד סְדוֹם. מַה כְּתִּיב בַּתְּרֵיהּ וְאַנְשֵׁי סְדוֹם רָעִים וְחַטָאִים לַיְיָ מְאֹד. תַּמָּן שַׁרְיָא וְשָׁוִי דִּיּוּרֵיהּ בֵּינַיְיהוּ לְאִתְּחַבְּרָא בְּהוּ לְאַסְטָאָה לוֹן וּלְאוֹבָדָא לוֹן. (ואברהם בעובדין טבין בתשובה באורייתא) (חסר) (ס\"א) בְּעוֹבָדִין בִּישִׁין.","כֵּיוָן דְּאִשְׁתְּאָרַתּ נִשְׁמָתָּא בְּלָא מְקַטְרְגָא וְאִתְּדְּכֵי גוּפָּא מֵהַהוּא זוּהֲמָא, מִיָּד קוּדְשָׁא בְּרִיךָ הוּא אַשְׁרֵי דִיּוּרֵיהּ בַּהֲדֵיהּ וְיָרִיתּ אַחְסַנְתָּא עִלָּאָה וְתַּתָּאָה, וְאִיתּ לֵיהּ נַיְיחָא בֵּין צַּדִּיקַיָא, והַהוּא לָטְיָא בֵּין אִנּוּן רַשִׁיעַיָיא חָטָאן בַּהֲדֵיהּ, עַד דְּלָא הֲוָה פּוּרְקָנָא לְחוֹבַיְיהוּ.","מַה כְּתִּיב וַיִּשְׁמַע אַבְרָם כִּי נִשְׁבָּה אָחִיו. וַיִּשְׁמַע אַבְרָם דָּא נִשְׁמָתָּא דְּאִשְׁתְּאָרַתּ בְּדַכְיוּ בְּגוּפָּא. כִּי נִשְׁבָּה אָחִיו, דָּא יֵצֶּר הָרָע דְּנִשְׁבָּה בֵּין אִנּוּן חַיָּיבַיָא בְּחוֹבִין סַגִּיאִין. וַיָּרֶק אֶתּ חֲנִיכָיו יְלִידֵי בֵיתּוֹ, אִלֵּין אִנּוּן צַּדִּיקַיָיא דְּלָעָאן בְּאוֹרַיְיתָּא דְּאִנּוּן שַׁיְיפֵּי דְגוּפָּא זְרִיזִין לְמֵיהַךָ בַּהֲדֵיהּ י\"ח וּשֹלשׁ מֵאוֹתּ, אִלֵּין רמ\"ח שַׁיְיפִּין דְּגוּפָּא, ושִׁבְעִין, דְּרָזָא דְּנִשְׁמָתָּא דְּנָפְּקָא מִתַּמָּן (ע\"כ). בְּכלָּא אִזְדְּרָז לְמֵהַךָ תַּמָּן לְגַבֵּי אִנּוּן חַיָּיבַיָא לְאֲתָּבָא לוֹן (מחובוי) מֵחוֹבֵיהוֹן.","מַה כְּתִּיב ויִּרְדֹּף עַד דָּן. רָדִיף אֲבַּתְּרַיְיהוּ וְאוֹדַע לוֹן דִּינא דְּהַהוּא עָלְמָא וְעוֹנְשָׁא דְּגֵיהִנֹּם, וְלָא יָהִיב דְּמִיכוּ לְעֵינֵיהּ בִּימָמָא וּבְלֵילְיָא עד דְּאוֹכַח לוֹן לְאִנּוּן חַיָּיבִין וְאָתִּיב לוֹן בִּתְּיוּבְתָּא לְגַבֵּי קוּדְשָׁא בְּרִיךָ הוּא. מַה כְּתִּיב וַיָּשֶׁב אֶתּ כָּל הָרְכוּשׁ, אָתִּיב לוֹן בִּתְּיוּבְתָּא שְׁלֵימָא כְּדְקָא יְאוּתּ.","וְגַם אֶתּ לוֹט אָחִיו וְגו'. אֲפִּלּוּ לְהַהוּא יֵצֶּר הָרָע אַתְּקִיף בַּהֲדֵיהּ עַד דְּאַכְפְּיֵיה בְּעַל כָּרְחֵיהּ (ולא) וְאַמְתִּיק לֵיהּ כְּדְקָא חָזֵי. כּלָּא אָתִּיב בִּתְּיוּבְתָּא שְׁלֵימָתָּא כְּדְקָא יְאוּתּ, בְּגִין דְּלָא אִשְׁתְּכַח יְמָמָא וְלֵילְיָא עַד דְּאוֹכַח לוֹן וּרְדַף לוֹן עַל הַהוּא חוֹבָא דְּחָאבוּ עַד דְּתָּאבוּ בִּתְּיוּבְתָּא שְׁלֵימָתָּא כִּדְקָחָזוּ.","אַהֲדַרְנָא לְמִילֵּי קַדְמָאֵי דְּפָּרְשָׁתָּא. כְּתִיב (שיר השירים ג׳:ג׳) מְצָּאוּנִי הַשׁוֹמְרִים הַסּוֹבְבִים בָּעִיר וגו'. (תנן כדוגמת דרמיז באברהם ויצחק ושרה ורבקה ידו\"ד, כדוגמא דא רמיז בהאי קרא (רות א׳:ב׳) ושם האיש אלימלך ושם אשתו נעמי ושם שני בניו מחלון וכליון אפרתים. אלימל\"ך דא נשמתא לנשמתא.) נָעְמִ\"י דָּא נְשָׁמָה, וְאַמַּאי אִתְּקְרֵי נָעְמִי, מִשׁוּם (תהילים צ׳:י״ז) וִיהִי נֹעַם יְיָ אֱלֹהֵינוּ. מַחְלוֹן דָּא רוּחָא קַדִּישָׁא, וְלָמָּה אִתְקְרֵי מַחְלוֹן דְּמָחַל לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא. רוּ\"ת דָּא נֶפֶשׁ קַדִּישָׁא, וְלָמָּה אִתְקְרֵי רוּ\"ת עַל שֵׁם תּוֹ\"ר. כִלְיוֹ\"ן דָּא רוּחָ\"א דְבְּעִירָ\"א, ועַל דָּא אָמַר שְלמֹה עָלָיו הַשָׁלוֹם (קהלת ג׳:כ״א) רוּחַ הַבּהמה דָּא יֵצֶ\"ר הָרָ\"ע. עָרְפָּ\"ה דָּא נַפְשָׁא דִּשְׂמָאלָא בַת זוּגֵיהּ שֶׁל יֵצֶר הָרָע. וְלָמָּה אִתְקְרֵי עָרְפָּה מִשׁוּם כִּי עַם קשה עֹרֶף הוּא. אִי זָכָה בַּר נָשׁ סָלְקָא נִשְׁמָתָּא עִלָּאָה, וְאִי לָאו מִסְתַּלְּקֵי אִנּוּן דוֹבְרֵי נִשְׁמָתָּא וְרוּחָא וְאִשְׁתָּאַר נִשְׁמָתָּא עִלָּאָה וְנְפֶּשׁ הַשִׂכְלִיתּ, מַה כְּתִּיב, (רות א׳:ז׳) וַתֵּצֵּא מִן הַמָּקוֹם אֲשֶׁר הָיתָּה שָׁמָּה וּשְׁתֵּי כַלוֹתֶּיהָ עִמָּהּ וַתֹּאמֶר נָעֳמִי לִכַלוֹתֶּיהָ שֹׁבְנָה בְנֹתַּי וְגו'. וַתֹּאמֶר רוּתּ אַל תִּפְּגְּעִי בִי וְגו' וְעָרְפָּה שָׁבָה לְעַמָּהּ וּלְאֱלהֶיהָ. תְּנַן עָבַד קוּדְשָׁא בְּרִיךָ הוּא יְרוּשְׁלֵם לְעֵילָא כְּגַוְונָא דִּיְרוּשָׁלַםִ דִּלְתַּתָּא, בְּשׁוּרִין וּמִגְדָּלִין וּפִּתְּחִין פְּתִּיחִין, וְאִנּוּן חוֹמוֹתּ דְּתַּמָּן אִיתּ עֲלַיְיהוּ נָטְרִין דְּנָטְרֵי תַּרְעֵי דְּאִנּוּן חוֹמוֹתּ דִּכְתִּיב, (ישעיהו ס״ב:ו׳) עַל חוֹמוֹתַּיִךָ יְרוּשָׁלַיִם הִפְּקַדְתִּי שׁוֹמְרִים וְגו'. וּמִיכָאֵל כַּהֲנָא רַבָּא עִלָּאָה מִכֻּלְהוּ נָטְרֵי תַּרְעֵי דְּאִנּוּן חוֹמוֹתּ."],[[0,"וכל דא אי זכאה וכו':","וכל זה אם הנשמה זכתה בעולם הזה לתקן את הגוף, ולכפות תוקפו של אותו הארור, דהיינו יצר הרע הנקרא \u0003לוט,\u0004 עד שנפרד ממנו. מה כתוב, ויהי ריב בין רועי מקנה אברם, שהוא הנשמה, ובין רועי מקנה לוט, שהוא היצר הרע. כי בעולם הזה, בכל יום ויום, אלו המחנות והמנהיגים שמצד הנשמה, הם במריבה עם אלו המחנות והמנהיגים שמצד הגוף, והם מריבים אלו עם אלו וכל אברי הגוף נמצאים בצער ביניהם: בין הנשמה ובין אותו הנחש, שהוא היצר הרע. הנלחמים בכל יום ויום."],[1,"מה כתיב, ויאמר אברם אל לוט:","הנשמה השיבה ליצר הרע, ואמרה לו, אל נא תהי מריבה ביני וביניך. ובין רועי ובין רועיך, דהיינו בין המחנות שלי והמחנות שלך. כי אנשים אחים אנחנו, שהיצר הרע והיצר טוב קרובים זה לזה, זה לימינו של אדם וזה לשמאלו. דהיינו יצה\"ר לשמאלו ויצה\"ט לימינו."],[2,"הלא כל הארץ לפניך הפרד נא מעלי וכו':","הרבה רשעים הם בעולם, לך ושוט אחריהם והפרד מעמי, אם השמאל ואימינה וגו'. ומוכיח אותו ומציק אותו בכמה מלחמות שעושה עמו בכל יום, עד שכתוב ויפרדו איש מעל אחיו."],[3,"כיון דמתפרשין דא מן דא וכו':","כיון שנפרדו זה מזה, מה כתוב, \u0003אברם ישב בארץ כנען,\u0004 שפירושו שהנשמה נתישבה בין הצדיקים בישוב טוב בשלום. \u0003ולוט ישב בערי הככר,\u0004 שפירושו, שאותו ארור המקטרג, הלך לקטרג ולהתחבר במקום שהרשעים שם, שכתוב, \u0003ויאהל עד סדום.\u0004 מה כתוב לאחר זה, ואנשי סדום רעים וחטאים לה' מאד. שם שכן, ושם משכנו ביניהם, להתחבר בהם להשטות אותם ולהאביד אותם במעשים רעים."],[4,"כיון דאשתארת וכו':","כיון שנשארה הנשמה בלי מקטרג, והגוף נטהר מאותה הזוהמא, מיד הקב\"ה משרה משכנו עמו, והוא יורש נחלה העליונה והתחתונה. ויש לו נחת בין הצדיקים. ואותו הארור, דהיינו לוט, הוא בין הרשעים והם חוטאים עמו עד שאין להם עוד גאולה לחטאתם."],[5,"מה כתיב וישמע אברם כי נשבה אחיו וכו':","וישמע אברם, זוהי הנשמה שנשארה בגוף בטהרה. כי \u0003נשבה אחיו,\u0004 זהו היצר הרע, שנשבה בין הרשעים בהרבה עונות. \u0003וירק את חניכיו ילידי ביתו,\u0004 אלו הם הצדיקים העוסקים בתורה, שהם אברי הגוף. כלומר, אברי הגוף מדומים לצדיקים העוסקים בתורה, המזוינים ללכת עמו, במספר שלש מאות ושמונה עשרה, שהם רמ\"ח אברי הגוף, וע' של סוד הנשמה, שהם כנגד ז' ספירות דז\"א, שכל אחת במספר עשר, שהיא יוצאת משם, מז\"ס דז\"א. ורמ\"ח עם ע' הם במספר שי\"ח. בכולם נזדיין ללכת שם אל אלו הרשעים, להחזיר אותם בתשובה על עונותיהם."],[6,"מה כתיב וירדוף עד דן וכו':","רדף אחריהם והודיעם הדין שבעולם האמת, ועונש הגיהנם, ולא נתן שינה בעיניו ביום ובלילה, עד שהוכיחם והחזיר אותם הרשעים בתשובה אל הקב\"ה. מה כתוב, \u0003וישב את כל הרכוש,\u0004 כי החזיר אותם בתשובה כראוי."],[7,"וגם את לוט אחיו וכו':","אפילו אותו יצר הרע, הנקרא לוט, התקיף אותו עד שכפה אותו בעל כרחו והמתיקו כראוי. כולם השיב בתשובה שלמה כראוי. כי לא שקט יומם ולילה מלהוכיח אותם, ורדף אחריהם על כל עון ועון שחטאו, עד ששבו בתשובה שלמה כראוי."],[8,"אהדרנא למלי קדמאי דפרשתא וכו':","נחזור לדברים הראשונים שבפרשה. כתוב, מצאוני השומרים הסובבים בעיר וגו'. תנן עשה הקב\"ה את ירושלים של מעלה, דהיינו בינה כעין ירושלם של מטה, שהיא מלכות, בחומות ומגדלים ופתחים פתוחים. \u0003מגדלים,\u0004 ה\"ס גדלות המלכות, דהיינו ג\"ר. \u0003חומות,\u0004 ה\"ס ו\"ק שלה. פתחים, ה\"ס מלכות שלה. וה\"ס ראש תוך סוף. ונפש רוח נשמה. ואומר שירושלם של מעלה שהיא בינה, נכללה מהמלכות, שהיא ירושלם של מטה. באופן, שכל הנוהג בהמלכות נוהג בהבינה."],[8,"ואינון חומות דתמן וכו':","ואלו החומות אשר שם. בהבינה ובהמלכות, יש עליהם שומרים. שכתוב על חומותיך ירושלים הפקדתי שומרים וגו'. ומיכאל כהן גדול הוא עליון על כל שומרי השערים."]],[[0,"","וְכָל זֶה אִם צַדִּיק בָּעוֹלָם הַזֶּה לְתַקֵּן הַגּוּף כָּרָאוּי וּלְהַכְנִיעַ (ולאסף) הַחֹזֶק שֶׁל אוֹתוֹ הַמְקֻלָּל. עַד שֶׁנִּפְרַד מִמֶּנּוּ מַה כָּתוּב? וַיְהִי רִיב בֵּין רֹעֵי מִקְנֵה אַבְרָם וּבֵין רֹעֵי מִקְנֵה לוֹט (זה יצר הרע), שֶׁבְּכָל יוֹם וָיוֹם בָּעוֹלָם הַזֶּה הֵם מְסַיְּעִים וּמַנְהִיגִים אֶת הַנְּשָׁמָה, וְהֵם מְסַיְּעִים וּמַנְהִיגִים אֶת הַיֵּצֶר הָרָע, הֵם מְקַטְרְגִים בְּקִטְרוּג אֵלּוּ עִם אֵלּוּ, וְכָל הָאֵיבָרִים שֶׁל הַגּוּף בְּצַעַר בֵּינֵיהֶם, בֵּין הַנְּשָׁמָה לְאוֹתוֹ הַנָּחָשׁ שֶׁנִּלְחָמִים בִּקְרָב בְּכָל יוֹם."],[1,"","מַה כָּתוּב? וַיֹּאמֶר אַבְרָם אֶל לוֹט. הַנְּשָׁמָה חוֹזֶרֶת לַיֵּצֶר הָרָע וְאוֹמֶרֶת לוֹ, אַל נָא תְהִי מְרִיבָה בֵּינִי וּבֵינֶךְ וּבֵין רֹעַי וּבֵין רוֹעֶיךְ, הַצְּדָדִים שֶׁלִּי וְהַצְּדָדִים שֶׁלְּךְ, כִּי אֲנָשִׁים אַחִים אֲנָחְנוּ. יֵצֶר הַטּוֹב וְיֵצֶר הָרָע קְרוֹבִים זֶה עִם זֶה. זֶה לְיָמִין וְזֶה לִשְׂמֹאל."],[2,"","הֲלֹא כָל הָאָרֶץ לְפָנֶיךְ הִפָּרֶד נָא מֵעָלָי. רַבִּים הָרְשָׁעִים בָּעוֹלָם, לֵךְ וְשׁוֹטֵט אַחֲרֵיהֶם וְהִפָּרֵד מֵעִמִּי. אִם הַשְּׂמֹאל וְאֵימִנָה וְגוֹ'. וּמוֹכִיחַ אוֹתוֹ וּמֵצִיק לוֹ בְּכַמָּה קְרָבוֹת שֶׁעוֹשֶׂה עִמּוֹ בְּכָל יוֹם, עַד שֶׁכָּתוּב וַיִּפָּרְדוּ אִישׁ מֵעַל אָחִיו."],[3,"","כֵּיוָן שֶׁנִּפְרָדִים זֶה מִזֶּה מַה כָּתוּב? אַבְרָם יָשַׁב בְּאֶרֶץ כְּנָעַן. מִתְיַשֶּׁבֶת הַנְּשָׁמָה עִם אוֹתָם הַצַּדִּיקִים בְּיִשּׁוּב טוֹב בְּשָׁלוֹם. וְלוֹט יָשַׁב בְּעָרֵי הַכִּכָּר. אוֹתוֹ הַמְקֻלָּל הַמְקַטְרֵג הוֹלֵךְ לְקַטְרֵג וּלְהִתְחַבֵּר בְּמָקוֹם שֶׁהָרְשָׁעִים שָׁם, שֶׁכָּתוּב וַיֶּאֱהַל עַד סְדם. מַה כָּתוּב אַחֲרָיו? וְאַנְשֵׁי סְדם רָעִים וְחַטָּאִים לַה' מְאֹד. שָׁם שָׁרוּי וְשָׂם דִּיּוּרוֹ בֵּינֵיהֶם לְהִתְחַבֵּר עִמָּהֶם לְהָסִיט אוֹתָם וּלְאַבֵּד אוֹתָם. (ואברהם במעשים טובים, בתשובה, ובתורה) (חסר) (במעשים רעים)."],[4,"","(כיון שנשארת הנשמה בלי מקטרג ונטהר הגוף מאותה הזהמה, מיד הקדוש ברוך הוא משרה את דיורו עמו ויורש נחלה עליונה ותחתונה, ויש לו נחת בין הצדיקים, והמקלל ההוא בין אותם הרשעים חוטאים עמו, עד שאין פדות לחטאיהם,)"],[5,"","(מה כתוב? וישמע אברם, זו הנשמה שנשארה בטהר הגוף, כי נשבה אחיו זה יצר הרע שנשבה בין אותם הרשעים בחטאים רבים, וירק את חניכיו ילידי ביתו אלו הם הצדיקים שעוסקים בתורה, שהם האיברים של הגוף הזריזים ללכת עמו, שמנה עשר ושלש מאות אלו רמ\"ח איברי הגוף, ושבעים של סוד הנשמה שיוצאת משם,) בַּכֹּל מִזְדָּרֵז לָלֶכֶת לְשָׁם לְאוֹתָם הָרְשָׁעִים לְהָשִׁיב אוֹתָם (מחטאם) מֵחֲטָאֵיהֶם."],[6,"","מַה כָּתוּב? וַיִּרְדֹּף עַד דָּן. רוֹדֵף אַחֲרֵיהֶם וּמוֹדִיעַ לָהֶם אֶת דִּין הָעוֹלָם הַהוּא וְעֹנֶשׁ הַגֵּיהִנֹּם, וְלֹא נוֹתֵן שֵׁנָה לְעֵינוֹ בַּיּוֹם וּבַלַּיְלָה עַד שֶׁמּוֹכִיחַ אוֹתָם אֶת אוֹתָם הָרְשָׁעִים, וּמֵשִׁיב אוֹתָם בִּתְשׁוּבָה לַקָּדוֹשׁ-בָּרוּךְ-הוּא. מַה כָּתוּב? וַיָּשֶׁב אֵת כָּל הָרְכֻשׁ. הֵשִׁיב אוֹתָם בִּתְשׁוּבָה שְׁלֵמָה כָּרָאוּי."],[7,"","וְגַם אֶת לוֹט אָחִיו וְגוֹ' - אֲפִלּוּ אֶת אוֹתוֹ יֵצֶר הָרָע מַחֲזִיק עִמּוֹ, עַד שֶׁמַּכְנִיעוֹ בְּעַל כָּרְחוֹ (ולא) וּמַמְתִּיק אוֹתוֹ כָּרָאוּי. וְהַכֹּל מֵשִׁיב בִּתְשׁוּבָה שְׁלֵמָה כָּרָאוּי, מִכֵּיוָן שֶׁלֹּא יִשְׁקֹט יוֹמָם וָלַיְלָה, עַד שֶׁמּוֹכִיחַ אוֹתָם וְרוֹדֵף אוֹתָם עַל אוֹתוֹ הַחֵטְא שֶׁחָטְאוּ עַד שֶׁשָּׁבִים בִּתְשׁוּבָה שְׁלֵמָה כָּרָאוּי."],[8,"","חָזַרְנוּ לַדְּבָרִים הָרִאשׁוֹנִים שֶׁל הַפָּרָשָׁה. כָּתוּב (שיר ג) מְצָאוּנִי הַשּּׁמְרִים הַ בְבִים בָּעִיר וְגוֹ'. (שנינו, כדגמה שרמוז באברהם ויצחק ושרה ורבקה יהו\"ה, כדגמה הזו רמוז בפסוק הזה (רות א) ושם האיש אלימלך ושם אשתו נעמי ושם שני בניו מחלון וכליון אפרתים, אלימל\"ך זו הנשמה לנשמה, נעמ\"י זו הנשמה, ולמה נקראת נעמי? משום (תהלים צ) ויהי נעם ה' אלהינו, מחלון זו רוח הקדש, ולמה נקרא מחלון? שמחל לו הקדוש ברוך הוא, רו\"ת זו הנפש הקדושה, ולמה נקראת רו\"ת? על שם תו\"ר, כליו\"ן זו רוח הבהמ\"ה, ועל זה אמר שלמה עליו השלום (קהלת ג) רוח הבהמה, זה יצ\"ר הר\"ע, ערפ\"ה זו נפש השמאל, בת זוגו של היצר הרע, ולמה נקראת ערפה? משום כי עם קשה ערף הוא. אם זכה אדם עולה הנשמה העליונה, ואם לא מסתלקים אותם דוברי הנשמה והרוח, ונשארת הנשמה העליונה והנפש השכלית, מה כתוב? (רות א) ותצא מן המקום אשר היתה שמה ושתי כלתיה עמה, ותאמר נעמי לכלתיה שבנה בנתי וגו', ותאמר רות אל תפגעי בי וגו', וערפה שבה לעמה ולאלהיה). שנינו, עשה הקדוש ברוך הוא ירושלים של מעלה כמו ירושלים של מטה, בחומות ומגדלים ופתחים פתוחים, ואותן החומות ששם יש עליהם שומרים ששומרים את השערים של אותן החומות, שכתוב, (ישעיה סב) עַל חוֹמֹתַיִךְ יְרוּשָׁלַיִם הִפְקַדְתִּי שֹׁמְרִים וְגוֹ'. וּמִיכָאֵל כֹּהֵן גָּדוֹל עֶלְיוֹן מִכֻּלָּם, שׁוֹמֵר פְּתָחִים שֶׁל אֵלּוּ הַחוֹמוֹת."]]],[["נְשָׁמָ\"ה (דאתקרי נעמ\"י) כַּד נָפְּקַתּ מֵהַאי עָלְמָא, אִי זָכָאתּ עָאלַתּ בְּגִנְתָּא דְעֵדֶן דְּאַרְעָא דְּנָטַע קוּדְשָׁא בְּרִיךָ הוּא לְרוּחֵיהוֹן דְּצַּדִּיקַיָיא כְּגַוְונָא דְהַהוּא גִּנְתָּא דְּעֵדֶן דִּלְעֵילָא. וְתַּמָּן כָּל צַּדִּיקַיָיא דְּעָלְמָא.","וְכַד נִשְׁמָתָּא נָפְּקַתּ מֵהַאי עָלְמָא, עָאלַתּ בִּמְעַרְתָּא דְּכָפֶּלְתָּא דְּתַּמָּן אִיהִי פִּתְּחָא דְּגַּן עֵדֶן. פָּגְעַתּ בְּאָדָם הָרִאשׁוֹן וּבְאִנּוּן אֲבָהָן דְּתַּמָּן, אִי זָכָאתּ אִיהִי, חָדָאן בָּהּ וּפָּתְּחִין לָהּ פִּתְּחִין וְעָאלַתּ. ואִי לָא דַּחְיָין לָהּ לְבַר. (ומה היא אמרה כד דחיין לה לבר (שיר השירים ג׳:ג׳) מצאוני השומרים וגו' אזלת. לבתר דאזלת תמן מקמי דאתיא לעלמא דא ויהיבת נר על רישיה שנאמר (איוב כ״ט:ג׳) בהלו נרו עלי ראשי כל מאן דחזון לה מזדעזעין ואמרי הזאת נעמי. אתיבת היא ואמרה (רות א׳:כ׳) אל תקראנה לי נזעמי קראן לי מרה וגו'. אני מלאה הלכתי בההוא אתר וריקם השיבני יי בלא תורה ובלא מעשים טובים דאעיל לי בגופא בישא למה תקראנה לי נעמי ויי ענה בי). ואִי ז זָכָאתּ עָיְילַתּ לְגִנְתָּא דְעֵדֶן, כֵּיוָן דְּעָיְילַתּ יָתְּבָא תַּמָּן בְּגִנְתָּא (אזדווגת באלימלך דא מחלון דדא רוח אזדווג ברות דדא נפש השכלית) וְאִתְּלַבְּשׁוּ (ד\"א ואתלבשת) תַּמָּן בִּלְבוּשָׁא דְּדִיוּקְנָא דְּהַאי עָלְמָא וְאִתְּעַדְּנַתּ תַּמָּן.","סִתְּרָא דְסִתְּרִין לַחֲכִימֵי לִבָּא אִתְּמָסַר. (ארבע) תְּלַתּ דַּרְגִּין אִנּוּן דְּאֲחִידָן דָּא בְּדָא, ואִלֵּין אִנּוּן נֶפֶּשׁ (נשמתא לנשמתא נשמתא עלאה דאתקרי יו\"ד) רוּ\"חַ וּנְשָׁמָה. (נפ\"ש) נְפֶּשׁ אִיהוּ חֵילָא דְּגוּפָּא אִתְּבְּנֵי מִנֵּיהּ. דְּכַד בַּר נָשׁ אִתְּעַר בְּהַאי עָלְמָא לְאִזְדַּוְוגָא בְּנוּקְבֵיהּ כָּל שַׁיִיפֵּי מִסְתַּכְּמֵי (נ\"א מתכנשי) ֹ וּמִתְּתַּקְנֵי לְאִתְּהַנָּאָה (לנשמה) תַּמָּן, וְהַהוּא נְפֶּשׁ וּרְעוּתָּא דִילֵיהּ אִסְתַּכַּם בֵּיהּ בְּהַהוּא עוֹבָדָא (ממש) וּמָשִׁיךָ לֵיהּ לְהַהוּא נְפֶּשׁ וְאָעִיל לֵיהּ תַּמָּן בְּהַהוּא זַרְעָא דְּאוֹשִׁיד.","וּמִגּוֹ רְעוּתָּא וּמְשִׁיכוּ דְנַפְּשָׁא דְּמָשִׁיךָ תַּמָּן, אִתְּמְשַׁךָ חֵילָא אוֹחֲרָא תַּמָּן מֵאִנּוּן דַּרְגִּין דְּאִתְּקְרוּן אִישִׁי\"ם, וְעָאל כּלָּא בִּמְשִׁיכוּ דְּהַהוּא זַרְעָא, וְאִתְּבְּנֵי מִנֵּיהּ גּוּפָּא. וְדָא אִיהוּ חֵילָא קַדְמָאָה תַּתָּאָה דְּאִנּוּן (ארבע) תְּלַתּ.","וּבְגִין דְּהַאי (נשמתא לנשמתא) נְפֶּשׁ אַקְרִיב בִּדְבֵקוּתָּא וִיסוֹדָא דְגוּפָּא, קָרְבָּנָא דְּאִתְּקְרִיב לְכַפָּרָא עַל נִשְׁמָתָּא אִתְּיְהִיבַתּ חוּלָקָא לְאִנּוּן דַּרְגִּין דְּאִישִׁי\"ם (דאתקרון רוח ונפש השכלית) בְגִין דִּמְשִׁיכוּ דְּחוּלְקָא דְּהַהוּא (נשמה) נְפֶּשׁ אָתֵּי מִנַּיְיהוּ. וְהַיְינוּ דִכְתִּיב אֶתּ קָרְבָּנִי לַחְמִי לְאִשַׁי (מהו לחמי לאשי דיהיב מזונא לאשי ודא הוא שפע מאור דאנון מתהנן מזיו השכינה) בְּגִין דְּהוּא כַּפָּרָה דְּנְפֶּשׁ נָטְלֵי חוּלָקֵיהוֹן. וְכַד מִיתּ בַּר נָשׁ בְּהַאי עָלְמָא, הַהִיא נְפֶּשׁ לָא אִתְּעֲדֵי מִן קִבְרָא לְעָלְמִין, וּבְחֵילָא דָא יָדְעֵי מֵתַּיָיא וּמִשְׁתָּעוּ דָּא עִם דָּא.","רוּחַ אִיהוּ דִּמְקַיֵּים לַנְּפֶּשׁ בְּהַאי עָלְמָא. וְאִיהוּ מְשִׁיכוּ דְאִתְּעֲרוּתָּא דְּנוּקְבָא לְגַבֵּי דְכוּרָא כַּד אִנּוּן בְּתִּיאוּבְתָּא חָדָא. וּכְדֵין אִתְּעָרַתּ לְגַבֵּי דְכוּרָא בְּתִּיאוּבְתָּא דִילָהּ, לְהַאי רוּחַ כְּגַוְונָא דְּנוּקְבָא לְגַבֵּי דִּלְתַּתָּא אַשְׁדִיאַתּ זַרְעָא בְּתִּיאוּבְתָּא לְגַבֵּי דְכוּרָא. וְסִתְּרָא דָא (כד אשדיאת שפע בתיאובתא לגבי נוקבא והכא רזא) (קהלת י״ב:ז׳) וְהָרוּחַ תָּשׁוּב אל הָאֱלהִים אֲשֶׁר נְתָּנָהּ.","וְהַאי רוּ\"חַ (ונפ\"ש ונשמ\"ה ונשמת\"א לנשמתא כד) נָפְּקָא מֵהַאי עָלְמָא (ואתפרשת מנפש) (אתפרשן י\"ה אסתלק לגנתא דעדן בשמיא עלאה ומתלבש בדיוקנא עלאה מרקמא בכל גוונין) עָאל לְגִנְתָּא דְעֵדֶן דִּבְהַאי עָלְמָא (תתאה), וְאִתְּלַבַּשׁ תַּמָּן גּוֹ אֲוירָא דְגִנְתָּא כְּמָה דְּמִתְּלַבְּשֵׁי מַלְאֲכֵי עִלָּאֵי כַּד נָחֲתִּין לְהַאי עָלְמָא. בְּגִין דְּאִנּוּן מֵהַהוּא רוּחַ הֲווּ דִּכְתִּיב, (תהילים ק״ד:ד׳) עוֹשֶׂה מַלְאָכָיו רוּחוֹתּ וגו'.","אוּף הָכִי רוּחא מִתְּלַבָּשׁ בְּגַּן עֵדֶן דְאַרְעָא בְּדִיוּקְנָא דְהַאי עָלְמָא וְתַּמָּן אִתְּעַדְּנַתּ בְּכָל עִדּוּנִין, בְּגַּן עֵדֶן דָּא אִיתּ צִּיּוּרִין וְדִּיוּקְנִין דְהַאי עָלְמָא. וְאִיתּ צִּיּוּרִין וְדִּיוּקְנִין דְעָלְמָא עִלָּאָה, וְתַּמָּן כָּל אִנּוּן צַּדִּיקַיָּיא אָזְלִין וּמִתְּעַדְּנִין תַּמָּן, וּבְרֵישׁ יַרְחֵי וְשַׁבַּתֵּי אִנּוּן בָּעָאָן לְסָלְקָא לְעֵילָא. (דיוקנא דא מרו\"ח וא\"ש דבהאי עלמא ובדיוקנא דא אתעדנו בכל עדונין ובכל זמנ\"י וירח\"י ושבת\"י אסתלקו רו\"ח ונפ\"ש ומתפשטי מהאי גופא ומתלבשי בדיוקנא עלאה בגן עדן דלעילא מרקמא בכל גוונין. באן אתר הוא י\"ה בלבושא דיליה ואזדווגו כחדא ידו\"ד ואנון נהנין מאור השכינה) וּבִמְצִּיעוּתּ גִּנְתָּא אִיתּ עַמּוּדָא חָדָא מֵרֻקָּמָא בְּכָל גְּוָונִין. וְהַהוּא רוּחַ כַּד בָּעָא לְסָלְקָא, אִתְּפַּשַׁט תַּמָּן מֵהַהוּא לְבוּשָׁא (ונפשא אשתארת תמן בגופא) וְעָאל גּוֹ הַהוּא עַמּוּדָא (וסלקת) וְסָלִיק לְעֵילָא גּוֹ הַהוּא אֲתַּר דְּנָפְּקַתּ מִנֵּיהּ, כְּדִכְתִּיב וְהָרוּחַ תָּשׁוּב וְגו'.","וְנָטִיל לָהּ מִיכָאֵל כַּהֲנָא רַבָּא וּמַקְרִיב לָהּ קָרְבַּן בּוּסְמִין קַמֵּי קוּדְשָׁא בְּרִיךָ הוּא, (ואתת) וְיָתְּבָא תַּמָּן וּמִתְּעַדְּנָא בְּהַהוּא צְּרוֹרָא דְחַיֵּי (ישעיהו ס״ד:ג׳) דְּעַיִן לֹא רָאָתָּה אֱלהִים זוּלָתְּךָ וְגו'. לְבָתַּר נָחֲתָּא לְגוֹ גִנְתָּא דְאַרְעָא וּמִתְּעַדְּנָא בְּכָל עִדּוּנִין, וְאִתְּלַבְּשַׁתּ בְּהַהוּא לְבוּשָׁא (ואזדווגא בנפש דידיה) וְיָתְּבָא תַּמָּן בְּטוּרָא עַל חַד תְּרֵין מִכַּמָּה דְּהֲוַתּ בְּקַדְמִיתָּא. (ודא הוא בחול ואסתלקא בישיבות דגן עדן ומתעסק באורייתא ובכל רישי ירחי וזמני ושבתי נחתא אזדווגת בנפש)."],[[0,"נשמה כד נפקת וכו':","הנשמה, בעת שיוצאת מעולם הזה, דהיינו בפטירתו של אדם, אם האדם זוכה, היא נכנסת בגן עדן הארץ, שנטע הקב\"ה בשביל רוחות הצדיקים בהארץ שהיא מלכות. כעין גן עדן העליון, שהיא בינה, ושם עומדים כל צדיקי עולם."],[1,"וכד נשמתא נפקת וכו':","וכשהנשמה יוצאת מעולם הזה, היא נכנסת תחילה, במערת המכפלה ששם הוא פתח גן עדן. ופוגעת באדם הראשון ובאבות אשר שם. אם זוכה הם שמחים בה ופותחים לה הפתחים ונכנסת, ואם לא הם דוחים אותה לחוץ. ואם זוכה נכנסה בגן עדן ויושבת שם, ומתלבשת בלבוש מצורת עולם הזה. ומתעדנת שם. וביאור הדברים תמצא להלן בדף מ\"ב ד\"ה ביאור המאמר."],[2,"סתרא דסתרין לחכימי וכו':","סתר הסתרים לחכמי לב נמסר, שלשה מדרגות הן הנאחזות זו בזו, ואלו הן: נפש, רוח, נשמה. נפש, היא בחינת כח שהגוף נבנה ממנו. כי כשהאדם מתעורר בעולם הזה להזדווג בנוקביה, כל האברים מוסכמים ומתתקנים להנות מזה, והנפש והרצון של האדם, נכנס אז בהסכמה באותה הפעולה, ומושך את הנפש ומכניסה בהזרע שהיציא."],[3,"ומגו רעותא וכו':","ומתוך הרצון ועם המשכת הנפש שהמשיך שמה נמשך שם כח אחר, מאלו המדרגות המלאכים הנקראים \u0003אישים,\u0004 והכל נכנס בהמשכה של הזרע, והגוף נבנה מהם. זה הוא כח הראשון התחתון מאלו שלשה מדרגות הנ\"ל, שהוא הנפש."],[3,"","פירוש. כי האדם הוא תולדה דזו\"ן דאצילות. (כנ\"ל דף ז' ד\"ה תאנא) וע\"כ משורשו אין לו אלא בחינת נפש. כי אור הנמשך מהמלכות שה\"ס הנוקבא דז\"א, מכונה נפש. אמנם מתוך המיתוק, שהמלכות עלתה ונתמתקה בהבינה, נאחז האדם גם בבינה, ונמצא משום זה, שהאדם כולל ג' מדרגות, שהם בינה ת\"ת ומלכות, שאור הבינה נקרא נשמה, ואור הת\"ת נקרא רוח, ואור המלכות נקרא נפש. וז\"ש \u0003תלת דרגין אינון דאחידן דא בדא,\u0004 שהם: נפש, רוח, נשמה. כמו שהולך ומבאר. ואלו ג' מדרגות, נמשכים מג' עולמות: בריאה, יצירה, ועשיה. ואם זכה יותר הם נמשכים מבינה ות\"ת ומלכות מעולם האצילות."],[3,"","והמשכה הראשונה היא אור הנפש. ומבאר כאן, שהיא כח שהגוף נבנה ממנו. והוא נמשך בכח אור הנפש של המולידים, כי בכח גודל תשוקת המולידים, שהיא בחינת הסכמה חזקה מאור הנפש שלהם, הם ממשיכים \u0003מעולם העשיה הרוחני\u0004 את אור הנפש של הולד, והוא מתלבש בהזרע שלהם שמוציאים, ומאור הזה הרוחני הולך ונבנה גופו של הולד. אמנם לא יצויר כלל מציאות של הארת אור הנפש בלי הארה מאור הרוח. כי אין לך דבר שלא יהיה בו בחינת זכר ונקבה. והרוח הוא זכר. והנפש היא נקבה. כנודע. וע\"כ יחד עם אור הנפש נמשך לו אור הרוח מעולם המלאכים שהוא \u0003עולם היצירה.\u0004 אבל בתחילת התהוותו של הולד אינו נמשך לו אז רוח ממש, אלא בחינת מלכות דרוח, דהיינו מהמלכות של עולם המלאכים. כי גם הם נחלקים לעשר ספירות, כח\"ב חג\"ת נהי\"מ, ונקראים: \u0003מלאכים, אראלים, שרפים, חיות, אופנים, חשמלים אלים, אלהים, בני אלהים, אישים,\u0004 (כמ\"ש בזהר בא אות רכ\"ח) הרי שמדרגה אחרונה שלהם הוא, \u0003אישים\u0004 דהיינו בחינת מלכות של המלאכים, שערכו הוא כמו נפש דרוח, והוא מתלבש באור הנפש של הולד, ונבחן בזה שיש לו ב' אורות, רוח ונפש שבנפש, אשר נפש דנפש הוא מעולם העשיה, ורוח שבנפש, הוא מעולם המלאכים, מבחינת הנפש שבהם, הנקראים \u0003אישים.\u0004 כמבואר."],[4,"ובגין דהאי נפש וכו':","ומשום שנפש הזה מקרבת קרבן בדביקות יחד עם יסוד הגוף, שהוא נקרב כדי לכפר על הנשמה, ניתן חלק ממנו, לאלו המדרגות דבחינת \u0003אישים,\u0004 משום שחלק מהנפש, שהוא הרוח שבנפש כנ\"ל, נמשך מהם. והיינו שכתב את קרבני לחמי \u0003לאשי,\u0004 שפירושו \u0003לאישים\u0004 הנ\"ל. כי משום שהוא כפרה הבאה בכח הנפש, לוקחים גם הם חלקם. דהיינו לפי שיעור מדת חלקם המלובש בנפש ההיא המקרבת את הקרבן."],[4,"וכד מית ב\"נ וכו':","וכאשר האדם נפטר מעולם הזה, אותה הנפש לא תסור מן הקבר לעולם. ובכח הזה, של הנפש הנשארת בקבר, יודעים המתים, ומדברים זה עם זה."],[5,"רוח, איהו דמקיים וכו', רוח:","הוא המקיים את הנפש בעולם הזה, שהוא ממשיך שפע החיים ומשפיע להנפש. והוא מדרגה האמצעית מג' מדרגות דנ\"ל. והוא המשכה הבאה בהתעוררות הנוקבא דאצילות להדכר דאצילות, בעת שהם בתשוקה אחת, דהיינו בעת הזווג כי אז מתעוררת להדכר מחמת תשוקתה לקבל ממנו אור הרוח, כעין הנוקבא דעולם הזה, המזרעת זרע בכח תשוקתה לקבל מהזכר. וזה סוד, והרוח תשוב אל האלקים אשר נתנה. דהיינו ששב אל הנוקבא הנקראת בשם אלקים. ואע\"פ שהרוח נמשך מז\"א שנקרא הוי\"ה, מכל מקום, כיון שבא עם התעוררות הנוקבא היא נחשבת לו לשורש, שלאחר הפטירה מהגוף הוא שב אליה."],[6,"והאי רוח נפקא וכו':","ורוח הזה, לאחר פטירת האדם, יוצא מעולם הזה ונפרד מהנפש, הנשארת חופפת על הקבר, והוא נכנס לגן עדן שבעולם הזה. ומתלבש שם בהאויר של גן עדן, כמו מלאכים העליונים היורדים לעולם הזה. שמתלבשים באויר הזה כאשר יורדים לעולם הזה. משום שהם נתהוו מאותו הרוח, שכתוב עושה מלאכיו רוחות וגו'."],[7,"ובמציעות גנתא וכו':","ובאמצע הגן, יש עמוד אחד מרוקם בכל הצבעים. ורוח ההוא, כשרוצה לעלות לעולם אצילות. מתפשט שם מאותו הלבוש, דאוירא דג\"ע ונכנס תוך העמוד, ועולה למעלה, אל המקום שיצא משם, דהיינו אל הנוקבא דאצילות (כנ\"ל בסמוך) כמו שכתוב, והרוח תשוב אל האלקים אשר נתנה."],[8,"ונטיל לה מיכאל וכו':","ואז, מיכאל כהן הגדול לוקח אותו, את הרוח. ומקריב אותו קרבן ריח ניחוח לפני הקב\"ה היינו ז\"א, והוא יושב שם, בז\"א דאצילות, ומתעדן באותו צרור החיים, אשר עליו רומז הכתוב, עין לא ראתה אלקים זולתך. ואחר כך, חוזר ויורד משם לגן עדן הארץ, ומתעדן בכל עדנים, ומתלבש שוב באותו הלבוש, דאוירא דגן עדן, ויושב שם עתה בעטרה, הגדולה בכפלים ממה שהיה לו מטרם עליתו לזו\"ן דאצילות."]],[[0,"","הַנְּשָׁמָ\"ה (שנקראת נעמ\"י), כְּשֶׁיּוֹצֵאת מִן הָעוֹלָם הַזֶּה, אִם זוֹכָה - נִכְנֶסֶת לְגַן הָעֵדֶן שֶׁל הָאָרֶץ שֶׁנָּטַע הַקָּדוֹשׁ בָּרוּךְ הוּא לְרוּחוֹת הַצַּדִּיקִים כְּמוֹ אוֹתוֹ גַּן עֵדֶן שֶׁלְּמַעְלָה, וְשָׁם כָּל הַצַּדִּיקִים שֶׁל הָעוֹלָם."],[1,"","וּכְשֶׁהַנְּשָׁמָה יוֹצֵאת מִן הָעוֹלָם הַזֶּה, נִכְנֶסֶת לִמְעָרַת הַמַּכְפֵּלָה שֶׁשָּׁם הוּא פֶּתַח גַּן הָעֵדֶן. פּוֹגֶשֶׁת בְּאָדָם הָרִאשׁוֹן וּבְאוֹתָם הָאָבוֹת שֶׁשָּׁם. אִם הִיא זוֹכָה - שְׂמֵחִים בָּהּ וּפוֹתְחִים לָהּ פְּתָחִים וְנִכְנֶסֶת, וְאִם לֹא - דּוֹחִים אוֹתָהּ הַחוּצָה (ומה היא אומרת כשדוחים אותה החוצה? (שיר ג) מצאוני השומרים וגו', והולכת, אחר שהולכת שם מלפני שבאה לעולם הזה ונתון נר על ראשו, שנאמר (איוב כט) בהלו נרו עלי ראשי, כל מי שרואים אותה מזדעזעים ואומרים הזאת נעמי?) (היא משיבה ואומרת, (רות א) אל תקראנה לי נעמי קראן לי מרא וגו', אני מלאה הלכתי באותו מקום, וריקם השיבני ה' בלי תורה ובלי מעשים טובים, שהכניס אותי לגוף רע, למה תקראנה לי נעמי וה' ענה בי). ואם זוכה, נכנסת לגן עדן. כיון שנכנסת, יושבת שם בגן (מזדוגת עם אלימלך, זה מחלון, שזה הרוח מזדוג עם רות, שזו הנפש השכלית) והתלבשו (ד\"א ומתלבשת) שם בלבוש של הדמות של העולם הזה ושם מתעדנת."],[2,"","סֵתֶר הַסְּתָרִים נִמְסָר לְחַכְמֵי הַלֵּב. (ארבע) שָׁלֹשׁ דְּרָגוֹת הֵן שֶׁאֲחוּזוֹת זוֹ בְּזוֹ, וְאֵלּוּ הֵן נֶפֶשׁ (נשמה לנשמה, הנשמה העליונה שנקראת יו\"ד) רוּ\"חַ וּנְשָׁמָה. (נפ\"ש) הַנֶּפֶשׁ הִיא הַכֹּחַ שֶׁהַגּוּף נִבְנֶה מִמֶּנּוּ. שֶׁכַּאֲשֶׁר הָאָדָם מִתְעוֹרֵר בָּעוֹלָם הַזֶּה לְהִזְדַּוֵּג עִם נְקֵבָתוֹ, כָּל אֵיבָרָיו מַסְכִּימִים (נ\"א: מתכנסים) וְנִתְקָנִים לֵהָנוֹת (לנשמה) שָׁם, וְאוֹתָהּ הַנֶּפֶשׁ וְהָרָצוֹן שֶׁלּוֹ מַסְכִּים עִם אוֹתוֹ הַמַּעֲשֶׂה (ממש), וּמוֹשֵׁךְ אֶת אוֹתָהּ הַנֶּפֶשׁ וּמַכְנִיס אוֹתָהּ שָׁם בְּאוֹתוֹ הַזֶּרַע שֶׁשּׁוֹפֵךְ."],[3,"","וּמִתּוֹךָ רָצוֹן וְהַמְשָׁכַת הַנֶּפֶשׁ שֶׁמּוֹשֵׁךְ לְשָׁם, נִמְשָׁךְ כֹּחַ אַחֵר לְשָׁם מֵאוֹתָן הַדְּרָגוֹת שֶׁנִּקְרָאוֹת אִישִׁי\"ם, וְהַכֹּל נִכְנָס בִּמְשִׁיכַת הַזֶּרַע הַהוּא וְנִבְנֶה מִמֶּנּוּ הַגּוּף. וְזֶהוּ הַכֹּחַ הָרִאשׁוֹן הַתַּחְתּוֹן שֶׁל אוֹתָם (ארבע) שָׁלֹשׁ."],[4,"","וּמִשּׁוּם שֶׁ את (נשמה לנשמה) הַנֶּפֶשׁ נִקְרֶבֶת בִּדְבֵקוּת וְהַיְסוֹד שֶׁל הַגּוּף, הַקָּרְבָּן שֶׁנִּקְרָב לְכַפֵּר עַל הַנְּשָׁמָה נִתָּן חֵלֶק לְאוֹתָם הַדְּרָגוֹת שֶׁל אִישִׁי\"ם (שנקראו רוח ונפש השכלית), מִשּׁוּם שֶׁמְּשִׁיכַת הַחֵלֶק שֶׁל אוֹתָהּ (נשמה) הַנֶּפֶשׁ בָּאָה מֵהֶם. וְהַיְנוּ שֶׁכָּתוּב אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי (מהו לחמי לאשי? שנותן מזון לאשי, וזהו שפע מאור שהם נהנים מזיו השכינה), מִשּׁוּם שֶׁהוּאא כַּפָּרַת הַנֶּפֶשׁ נוֹטְלִים חֶלְקָם. וּכְשֶׁמֵּת אָדָם בָּעוֹלָם הַזֶּה, אוֹתָהּ הַנֶּפֶשׁ לֹא זָזָה מִן הַקֶּבֶר לְעוֹלָמִים, וּבַכֹּחַ הַזֶּה יוֹדְעִים הַמֵּתִים וּמְסַפְּרִים זֶה עִם זֶה."],[5,"","הָרוּחַ הִיא שֶׁמְּקַיֶּמֶת אֶת הַנֶּפֶשׁ בָּעוֹלָם הַזֶּה, וְהִיא מְשִׁיכַת הִתְעוֹרְרוּת הַנְּקֵבָה לַזָּכָר כְּשֶׁהֵם בִּתְשׁוּקָה אַחַת. וְאָז מִתְעוֹרֶרֶת לַזָּכָר בִּתְשׁוּקָתָהּ לָרוּחַ הַזּוֹ כְּמוֹ שֶׁהַנְּקֵבָה כְּלַפֵּי מַטָּה שׁוֹפֶכֶת זֶרַע בִּתְשׁוּקָה אֶל הַזָּכָר. וְהַסֵּתֶר הַזֶּה (כשנשפך שפע בתשוקה לנקבה, וכאן סוד) (קהלת יב) וְהָרוּחַ תָּשׁוּב אֶל הָאֱלֹהִים אֲשֶׁר נְתָנָהּ."],[6,"","וְהָרוּ\"חַ הַזּוֹ (ונפ\"ש ונשמ\"ה ונשמ\"ה לנשמה כאשר), כְּשֶׁיּוֹצֵאת מִן הָעוֹלָם הַזֶּה וְנִפְרֶדֶת מִן הַנֶּפֶשׁ (נפרדים י\"ה מסתלק לגן עדן בשמים העליונים, ומתלבש בדמות עליונה מרקמת מכל הגונים) נִכְנָס לְגַן הָעֵדֶן שֶׁבָּעוֹלָם הַזֶּה (התחתון), וּמִתְלַבֵּשׁ שָׁם בְּתוֹךְ הָאֲוִיר שֶׁל הַגָּן כְּמוֹ שֶׁמִּתְלַבְּשִׁים הַמַּלְאָכִים הָעֶלְיוֹנִים כְּשֶׁיּוֹרְדִים לָעוֹלָם הַזֶּה, מִשּׁוּם שֶׁהֵם מֵאוֹתָהּ הָרוּחַ הָיוּ, שֶׁכָּתוּב (תהלים קד) עֹשֶׂה מַלְאָכָיו רוּחוֹת וְגוֹ'."],[7,"","אַף כָּךְ הָרוּחַ מִתְלַבֶּשֶׁת בְּגַן הָעֵדֶן שֶׁל הָאָרֶץ בִּדְמוּת הָעוֹלָם הַזֶּה, וְשָׁם מִתְעַדֶּנֶת בְּכָל הָעִדּוּנִים. בְּגַן הָעֵדֶן הַזֶּה יֵשׁ צִיּוּרִים וּדְמֻיּוֹת שֶׁל הָעוֹלָם הַזֶּה, וְיֵשׁ צִיּוּרִים וּדְמֻיּוֹת שֶׁל הָעוֹלָם הָעֶלְיוֹן, וְשָׁם כָּל אוֹתָם הַצַּדִּיקִים הוֹלְכִים וּמִתְעַדְּנִים שָׁם. וּבְרָאשֵׁי חֳדָשִׁים וְשַׁבָּתוֹת הֵם רוֹצִים לַעֲלוֹת לְמַעְלָה (הדמות הזו מרו\"ח וא\"ש של העולם הזה, ובדמות הזו מתעדנים בכל העדונים, ובכל המועדי\"ם והחדשי\"ם והשבתו\"ת מסתלקים הרו\"ח והנפ\"ש ומתפשטים מהגוף הזה ומתלבשים בדמות עליונה בגן העדן שלמעלה מרקם בכל הגונים, באיזה מקום הוא י\"ה? בלבושו, ומזדוגים יחד יהו\"ה, והם נהנים מאור השכינה). וּבְאֶמְצַע הַגָּן יֵשׁ עַמּוּד אֶחָד מְרֻקָּם בְּכָל הַגְּוָנִים, וּכְשֶׁאוֹתָהּ הָרוּחַ כַּאֲשֶׁר רוֹצָה לַעֲלוֹת, מִתְפַּשֶּׁטֶת שָׁם מֵהַלְּבוּשׁ הַהוּא (והנפש נשארת שם בגוף) וְנִכְנֶסֶת לְתוֹךְ אוֹתוֹ הָעַמּוּד (ועולה) וְעוֹלֶה לְמַעְלָה לְתוֹךְ אוֹתוֹ הַמָּקוֹם שֶׁיָּצְאָה מִמֶּנּוּ, כַּכָּתוּב וְהָרוּחַ תָּשׁוּב וְגוֹ'."],[8,"","וְנוֹטֵל אוֹתָהּ מִיכָאֵל הַכֹּהֵן הַגָּדוֹל, וּמַקְרִיב אוֹתָהּ קָרְבַּן בְּשָׂמִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, (ובאה) וְיוֹשֶׁבֶת שָׁם, וּמִתְעַדֶּנֶת בְּאוֹתוֹ צְרוֹר הַחַיִּים, (ישעיה סד) שֶׁעַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ וְגוֹ'. אַחַר כָּךְ יוֹרֶדֶת לְתוֹךְ הַגָּן שֶׁל הָאָרֶץ וּמִתְעַדֶּנֶת בְּכָל הָעִדּוּנִים, וּמִתְלַבֶּשֶׁת בַּלְּבוּשׁ הַהוּא (ומזדוגת עם נפשו), וְיוֹשֶׁבֶת שָׁם בְּעִטּוּר שֶׁל אֶחָד פִּי שְׁנַיִם מִכַּמָּה שֶׁהָיְתָה בָּרִאשׁוֹנָה. (וזהו בחל, ועולה לישיבות של גן העדן ומתעסקת בתורה, ובכל ראשי חדשים ומועדים ושבתות יורדת להזדוג עם הנפש)."]]],[["נְשָׁמָה הִיא חֵילָא עִלָּאָה על כָּל אִלֵּין, וְאִיהִי מֵחֵילָא דִדְכוּרָא רָזָא דְאִילָנָא דְחַיֵּי. וְדָא סָלְקָא לְעֵילָא מִיָּד. וְכָל הַנֵּי (ד\"א אנון) תְּלַתּ דַּרְגִּין מִתְּקַשְׁרִין כְּחֲדָא דָּא בְּדָא. וְכַד מִתְּפָּרְשָׁן כֻּלְהוּ סָלְקִין ותָּבִין לְהַהוּא אֲתַּר דְּנַפְּקוּ מִנֵּיהּ.","כַּד הַאי רוּחָא נָפְּקַתּ מֵהַאי עָלְמָא וְעָאלַתּ בְּגוֹ מְעַרְתָּא דְּאָדָם וְאֲבָהָן תַּמָּן, אִנּוּן יָהֲבִין לָהּ פִּנְקָס סִימָנָא וְעָאלַתּ לְגַבֵּי גִנְתָּא דְעֵדֶן, קְרִיבַתּ תַּמָּן וְאַשְׁכָּחַתּ כְּרוּבִים וְהַהוּא לַהַט הַחֶרֶב הַמִּתְּהַפֶּכֶתּ. אִי זָכָאתּ חָמָאן פִּנְקָס סִימָנָא וּפָּתְּחִין לָהּ פִּתְּחָא וְעָאלַתּ. וְאִי לָא דַּחְיָין לָהּ לְבַר.","וְיָתְּבָא תַּמָּן, כָּל הַהוּא זִמְנָא דְּיָתְּבָא מִתְּלַבְּשָׁא תַּמָּן בְּדִיוּקְנָא דְהַאי עָלְמָא. וּבְרֵישׁ יַרְחֵי וְשַׁבַּתֵּי כַּד בָּעָאתּ לְסַלְקָא. צַּדִּיקַיָּיא דִּבְגִנְתָּא דְעֵדֶן יַהֲבִין לָהּ פִּנְקָס סִימָנָא, וְסָלְקַתּ בְּהַהוּא עַמּוּדָא וּפָּגְעַתּ בְּאִנּוּן נָטְרֵי חוֹמוֹתּ יְרוּשְׁלֵם, אִי זָכְאָה פָּתְּחִין לָהּ פִּתְּחָא וְעָאלַתּ. וְאִי לָא נָטְלִין מִינָהּ הַהוּא פִּנְקָס וְדַחְיָין לָהּ לְבַר. תָּבַתּ לְגִנְתָּא ואָמְרָה (שיר השירים ג׳:ג׳) מְצָּאוּנִי הַשׁוֹמְרִים הַסּוֹבְבִים בָּעִיר וְגו' נָשְׂאוּ אֶתּ רְדִידַי מֵעָלַי, דָּא אִיהוּ פִּנְקָס סִימָנָא דְּנָטְלֵי מִנֵּיהּ (ד\"א מינה). שׁוֹמְרֵי הַחוֹמוֹתּ אִלֵּין אִנּוּן נָטְרֵי חוֹמוֹתּ יְרוּשָׁלַיִם. (כדוגמא דא נשמתא לנשמתא אתפשט מההוא לבושא דלעילא ומסתלק לעילא לעילא ואתהני מאור השכינה. ונשמה (ס\"א ונפשא) אשתארת בגופא (שמות קמא ב) ובכל רישי ירחי וזמני ושבתי נחתא נשמה לנשמה ומזדווגא לנשמה דאשתארת בגופא ומזדווגא בנשמה ודיוקנא דגנתא דעדן דלתתא הוא אש ומים שנאמר שמים. עד הכא רוחא דשמאלא היורדת למטה אזלת לדרגא דיליה ונפש דיליה אשתארא בגופא דארעא דכתיב, (איוב י״ד:כ״ב) אך בשרו עליו יכאב וגו'. ועל דא אמרו דמתיא ידעי בעלמא דאתי מיקרא דצדיקייא ומעלמא תתאה ומשתעיין דא עם דא) (עד כאן סתרי תורה):","וַיֵּרֶד אַבְרָם מִצְרַיְמָה לָגוּר שָׁם. מַאי טַעְמָא לְמִצְרַיִם. אֶלָּא בְּגִין דְּשָׁקִיל לְגַן יְיָ. דִּכְתִיב כְּגַן יְיָ כְּאֶרֶץ מִצְרַיִם. דְּתַמָּן שָׁקִיל וְנָחִית חַד נַהֲרָא דְּאִיהוּ לְיָמִינָא דִּכְתִיב, (בראשית ב׳:י״א) שֵׁם הָאֶחָד פִּישׁוֹן הוּא הַסּוֹבֵב אֶת כָּל אֶרֶץ הַחֲוִילָה אֲשֶׁר שָׁם הַזָּהָב.","וְאַבְרָהָם כֵּיוָן דְּיָדַע וְעָאל בְּהֵימְנוּתָא שְׁלֵימָתָא. בָּעָא לְמִנְדַע כָּל אִנּוּן דַּרְגִּין דְּאִתְאַחֲדָן לְתַתָּא. וּמִצְרַיִם הֲוָה נָטִיל מִיָּמִינָא (ד\"א לימינא) וּבְגִין כָּךְ נָחַת לְמִצְרַיִם. וְתָּא חֲזֵי, כַּפְנָא לָא אִשְׁתְּכַח בְּאַרְעָא אֶלָּא כַּד מִסְתַּלְּקֵי רַחֲמֵי מִן דִּינָא:","וַיְהִי כַּאֲשֶׁר הִקְרִיב לָבֹא מִצְרָיְמָה. אָמַר רַבִּי אֶלְעָזָר כַּאֲשֶׁר הִקְרִיב, כַּאֲשֶׁר קָרַב מִבָּעֵי לֵיהּ. מַאי כַּאֲשֶׁר הִקְרִיב, אֶלָּא כְּדִכְתִיב, (שמות י״ד:י׳) וּפַרְעֹה הִקְרִיב דְּאִיהוּ אַקְרִיב לְהוּ לְיִשְׂרָאֵל לְתִיוּבְתָּא. אוּף הָכָא הִקְרִיב, דְּאַקְרִיב גַּרְמֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא כְּדְקָא יְאוּת. לָבֹא מִצְרָיְמָה לְאַשְׁגָּחָא בְּאִנּוּן דַּרְגִּין וּלְאִתְרַחֲקָא מִנַּיְיהוּ וּלְאִתְרַחֲקָא מֵעוֹבְדֵי מִצְרַיִם.","אָמַר רַבִּי יְהוּדָה תָּא חֲזֵי, כֵיוָן (ס\"א בגין) דְּנָחַת אַבְרָהָם לְמִצְרַיִם בְּלָא רְשׁוּ, אִשְׁתַּעְבִּידוּ בְּנוֹי בְּמִצְרַיִם אַרְבַּע מְאָה שְׁנִין, דְּהָא כְּתִיב וַיֵּרֶד אַבְרָם מִצְרָיְמָה. וְלָא כְּתִיב רֵד מִצְרָיִם, וְאִצְטָעַר כָּל הַהוּא לֵילְיָא בְּגִינָהּ דְּשָׂרָה.","וַיֹּאמֶר אֶל שָׂרָה אִשְׁתּוֹ הִנֵּה נָא יָדַעְתִּי כִּי אִשָּׁה יְפַת מַרְאֶה אָתְּ. וְכִי עַד הַהִיא שַׁעֲתָא לָא הֲוָה יָדַע אַבְרָהָם דְּאִשָּׁה יְפַת מַרְאֶה הֲוַת. אֶלָּא הָא אוּקְמוּהָ דְּעַד הַהִיא שַׁעֲתָא לָא אִסְתַּכַּל בְּדִיוּקְנָא דְשָׂרָה בִּסְגִיאוּת צְנִיעוּתָא דְּהֲוַת בֵּינֵיהוֹן, וְכַד קָרִיב לְמִצְרַיִם אִתְגַלְיָיא אִיהִי וְחָמָא בָּהּ.","דָּבָר אַחֵר בְּמָּה יָדַע, אֶלָּא עַל יְדָא דְּטוֹרַח אוֹרְחָא בַּר נָשׁ מִתְבַּזֶּה וְהִיא קָיְימָא בְּשַׁפִּירוּ דִילָהּ וְלָא אִשְׁתַּנִּי. דָּבָר אַחֵר הִנִּה נָא יָדַעְתִּי דְּחָמָא עִמָּהּ שְׁכִינְתָּא. וּבְגִין כָּךְ אִתְרְחַץ אַבְרָהָם וְאָמַר אֲחוֹתִי הִיא.","וּמִלָּה דָא אִסְתָּלַּק לִתְרֵי גְּוָונִין. חַד כְּמַשְׁמָעוֹ. וְחַד כְּדִכְתִיב, (משלי ז׳:ד׳) אֱמוֹר לַחָכְמָה אֲחוֹתִי אָתְּ. וּכְתִיב אִמְרִי נָא אֲחוֹתִי אָתְּ. וּכְתִיב, (דברים ה׳:כ״ד) וְאַתְּ תְּדַבֵּר אֵלֵינוּ. לְמַעַן יִיטַב לִי בַּעֲבוּרֵךְ, כְּלַפֵּי שְׁכִינָה אָמַר בַּעֲבוּרֵךְ יִיטַב לִי קוּדְשָׁא בְּרִיךְ הוּא. וְחָיְתָה נַפְשִׁי בִּגְלָלֵךְ. בְּגִין דִּבְדָא יִסְתַּלַּק בַּר נָשׁ וְיִזְכֶּה לְאִסְתַּלְּקָא לְאָרְחָא דְחַיֵּי.","אִמְרִי נָא אֲחוֹתִי וְגו'. רַבִּי יֵיסָא אָמַר יָדַע הֲוָה אַבְרָהָם דְּכֻלְהוּ מִצְרָאֵי שְׁטִיפִין אִנּוּן בְּזִמָּה, וְכֵיוָן דְּכָל הַאי יָדַע אַמַּאי לָא דָחִיל עַל אִתְּתֵיהּ דְּלָא אַהֲדַר מֵאָרְחָא וְלָא יֵיעוּל לְתַמָּן. אֶלָּא בְּגִין דְּחָמָא שְׁכִינְתָּא עִמָּהּ:"],[[0,"נשמה, היא חילא עלאה וכו':","הנשמה: היא כח עליון על כל אלו, היינו על הנפש והרוח, והוא מכח הזכר, שהוא עץ החיים. כלומר שז\"א הנק' עץ החיים מושך אותה מבינה דאצילות. ומשום שז\"א מושך אותה הוא נבחן לשורשה. כמו הרוח, שהנוקבא נחשבת לשורשו, משום שממשכת אותו מז\"א. אמנם אור ז\"א נקרא רוח. ואור הבינה נקרא נשמה. \u0003ודא סלקא לעילא מיד.\u0004 והנשמה, אחר פטירתו של אדם, והיא עולה למעלה מיד. כלומר, שאינה באה מתחילה לגן עדן הארץ שבעוה\"ז כמו הרוח, אלא שעולית לשורשה מיד, דהיינו לז\"א, שהוא שורשה מבחינת ההמשכה, כמבואר."],[0,"וכל הני תלת דרגין וכו':","וכל שלש מדרגות הללו, שהן נפש רוח נשמה, מתקשרות זו בזו. וכאשר נפרדים מהגוף, כולם עולים וחוזרים אל המקום שיצאו משם. כמ\"ש לעיל."],[1,") כד האי רוחא וכו':","כאשר הרוח יוצא מעולם הזה, ונכנס בתוך המערה של אדם הראשון והאבות, הם נותנים לו שם מכתב לסימן, והולך אל גן העדן, כשהוא קרב שם פוגש הכרובים ואותה להט החרב המתהפכת. אם זוכה, הם רואים את מכתב הסימן, ופותחים לו הפתח ונכנס. ואם לא, הם דוחים אותו לחוץ."],[2,"ויתבא תמן וכו':","ויושבת שם כל הזמן שיושבת ומתלבשת שם בצורה של עולם הזה. (כנ\"ל בהק' הזהר דף קי\"ג אות ק\"ט ע\"ש בהסולם) ובראש חודש ושבת כשהיא רוצה לעלות לג\"ע העליון, הצדיקים שבגן עדן נותנים לה מכתב סימן. והיא עולה דרך אותו עמוד שבאמצע גן עדן התחתון. (כמ\"ש באורך לעיל בראשית ב' דף י\"ד ד\"ה ביאור ע\"ש.) והיא פוגשת את שומרי חומות ירושלם. אם היא זוכה, פותחים לה הפתח ונכנסת. ואם לא, לוקחים ממנה את מכתב הסימן, ודוחים אותה לחוץ. והיא אומרת מצאוני השומרים הסובבים בעיר וגו', נשאו את רדידי מעלי וגו'. רדידי, זהו מכתב הסימן שלקחו ממנה אותם שומרי החומות, שהם שומרי חומות ירושלם."],[2,"","ביאור המאמר. כי המיתה באה לעולם מכח חטא עצה\"ד, שגילה הנקודה דמדת הדין של המלכות, (כנ\"ל בפרשת נח דף ק\"ח ד\"ה פירוש) שאין לה תקון בשתא אלפי שני, וע\"כ אין צדיק בארץ שלא יחטא. ואפילו זכה האדם להמשיך נפש רוח נשמה במעשיו הטובים, מ\"מ יש כח למלאך המות לגלות הנקודה דמדת הדין הגנוזה בשורשו ואז הוא מת. כי בכל מקום שנגלתה נקודה זו מסתלקים אורות החיים משם. ואחר שתא אלפי שני, כשתתוקן נקודה הזו, אז נאמר ובלע המות לנצח."],[2,"","אמנם מדת הדין הזה שה\"ס צמצום א' אינו שולט רק על המלכות לבדה ולא כלום על ט\"ר. ולפיכך הוא שורה רק על הגוף הנמשך ממלכות הזו, וכן על הנפש שה\"ס אור המלכות שממנו נבנה הגוף, (כנ\"ל באות צ\"ו) אבל לא על רוח ונשמה שה\"ס ט\"ר, כי הרוח ה\"ס ז\"א הכולל חג\"ת נה\"י, והנשמה, ה\"ס אור הבינה הכולל ג\"ר, כי הם אינם נפגמים כלום, אלא פורחים מהגוף ומסתלקים לשורשם, ומכל מקום יש הפרש מרוח לנשמה, כי \u0003רוח,\u0004 ה\"ס אור ז\"א. שהוא מקיים את הנפש (כנ\"ל באות צ\"ט) וע\"כ יש לו התכללות מן המלכות הזו דמדת הדין. וע\"כ אינו יכול לעלות תכף לשורשו אלא שצריך למיתוק מחדש מן הבינה. אבל הנשמה שהיא אור הג\"ר אין לה שום מגע עם מלכות הזו דמדת הדין וע\"כ אינה צריכה שום מיתוק, וע\"כ בעת מיתת הגוף היא עולה תכף לשרשה. באופן שיש ג' הבחנות ביניהם, א) הנפש והגוף, שעליהם רובץ כח מדת הדין בזה, שנגלה עם המיתה, המכונה קבר. ב) הרוח, שיש לו תקון לחזור לשורשו על ידי שמקבל מיתוק מהבינה. ג) הנשמה שבלי שום מיתוק, היא עולה תכף לשורשה."],[2,"","וזה אמרו, \u0003וכד מית בר נש בהאי עלמא, ההיא נפש לא אתעדי מן קברא לעלמין.\u0004 כי \u0003קברא\u0004 ה\"ס כח מדת הדין שבמלכות שממנו מת האדם, ושם הוא נעול עד תחה\"מ בסו\"ה בפתחי את קברותיכם וגו'. והוא רובץ בעיקר על הגוף שה\"ס מלכות הזו, ועל הנפש שה\"ס אור המלכות המקיים את הגוף. וע\"כ הם בקברא. וז\"ש \u0003כד האי רוחא נפקת מהאי עלמא, ועאלת בנו מערתא דאדם ואבהן תמן אינון יהבין לה פנקס סימנא:\u0004 כי אותו הקליפה הקשה שה\"ס קבר אינו שולטת על הרוח אלא שצריך מיתוק מחדש מבינה, כנ\"ל, וע\"כ הוא נכנס \u0003במערת המכפלה,\u0004 שה\"ס מקום המיתוק של ב' ההין יחדיו, שהם מלכות ובינה. ומיתוק זה מכונה בשם \u0003פנקס.\u0004 שפירושו אגרת מקופלה, על דרך שאמרו בעובר במעי אמו, שמקופל כפנקס ראשו על ברכיו. (נדה ל' ע\"ב) וזה יורה על עלית נה\"י לחג\"ת ג' גו ג'. (כמ\"ש בתע\"ס חלק י' דף תתפ\"ד אות ל\"ו ע\"ש) וכשהרוח מקבל פנקס זה מאדם והאבות סימן הוא שנתמתק בהבינה, די צרכו, ואז \u0003ועאלת לגבי גנתא דעדן וכו' המאן פנקס סימנא ופתחין לה.\u0004 והיינו גן עדן התחתון. כי \u0003גן\u0004 ה\"ס מלכות. וכשהוא מתוקנת להיות לגמרי באורות הבינה, הנקראת \u0003עדן,\u0004 נקראת המלכות גן עדן. ואז נבחן בה ב' כלליות, א) כללות הבינה במלכות, שה\"ס גן עדן תחתון. ב) כללות המלכות בבינה שה\"ס גן עדן עליון. (כמ\"ש לעיל בראשית ב' דף ה' ד\"ה היכלא) ושם מדבר בדרך כללות מרוח ונשמה יחדיו וכאן מדבר בפרטות. וע\"כ אומר שרק הרוח עולה לג\"ע התחתון."],[2,"","וז\"ש \u0003ובריש ירחא ושבתא וכו' יהבין לה פנקס סימנא.\u0004 כי בר\"ח ושבת הרוח עולה לג\"ע העליון, וע\"כ צריך מיתוק ב' בהבינה, וה\"ס \u0003פנקס סימנא דיהבין לה צדיקייא די בגנתא דעדן.\u0004 וכ\"ז אמור רק בהרוח, שצריך לאלו המתוקים בבינה אבל הנשמה אומר (באות ק\"ג) \u0003ודא סלקא לעילא מיד,\u0004 כי אינה צריכה למיתוקים כמבואר."],[3,"וירד אברם מצרימה וכו':","שואל מה הטעם שירד למצרים. ואומר, אלא משום שהיא נדמה לגן ה' דהיינו גן עדן שכתוב, כגן ה' כארץ מצרים. כי שם שקול ויורד נהר אחד שהוא לימין. שכתוב שם האחד פישון וגו'. פירוש. כמו שהזהר מבאר להלן (בפ' חיי שרה אות קמ\"ג במדרש הנעלם) שמטפות שהעדן, שה\"ס חכמה, מנטף לגן, שה\"ס מלכות נעשה נהר גדול המתחלק לד' ראשים, שה\"ס חו\"ב תו\"מ, אשר האחד המיוחד מכולם הוא פישון, שה\"ס חכמה, והוא הנופל בארץ מצרים. ולפיכך היתה חכמת מצרים יותר מכל העולם. וזהו הנהר שראה יחזקאל בנבואתו, וע\"כ אמר הכתוב, כי מלאה הארץ דעה את ה' שאותם מים מגדלים תמיד הידיעה בעולם. ע\"כ לשונו בקיצור."],[3,"","וזהו אמרו כאן, \u0003דתמן שקיל ונחית חד נהרא דאיהו לימינא.\u0004 דהיינו חכמה שהוא בקו ימין. כי ג' קוין הם: חח\"ן בימין. בג\"ה בשמאל. דת\"י באמצע. הרי שהחכמה היא בראש קו הימין. והוא לאפוקי מבחינת החכמה שהוא בקו שמאל, דהיינו בינה החוזרת לחכמה, שכל הארת חכמה שבזו\"ן ממנה באים שהיא מכונה זהב. אבל נהר פישון הוא בחינת החכמה שבימין. שכתוב שם האחד פישון הוא הסובב את כל ארץ החוילה אשר שם הזהב. הרי שנהר פישון הוא החכמה שבימין, וע\"כ סובב ומשפיע לארץ החוילה, שה\"ס בינה, אשר שם הזהב, דהיינו הארת החכמה שבשמאל."],[4,"ואברהם, כיון דידע ועאל בהימנותא שלימתא.","ואברהם אחר שידע ונכנס באמונה שלמה, דהיינו הנוקבא דז\"א הנקראת אמונה, ואחר שנשלמה בהארת החכמה, מצד הבינה שחזרה לחכמה, היא נקראת אמונה שלמה, דהיינו הארת חכמה מסוד השמאל, שה\"ס הזהב כנ\"ל, \u0003בעא למנדע כל אינון דרגין דאתאחדן לתתא, ומצרים הוה נטיל מימינא,\u0004 היה רוצה עתה לדעת כל המדרגות הנאחזות למטה, דהיינו היכולים להשפיע מלמעלה למטה, שה\"ס החכמה שבקו ימין כמ\"ש להלן. ומצרים היתה נוסעת מימין, כלומר שהיא מבחינת נהר פישון, שה\"ס החכמה שבקו ימין. \u0003ובגין כך נחית למצרים,\u0004 ומשום זה ירד למצרים. כדי להוציא משם כל ניצוצים הקדושים שמבחינת החכמה ההיא שמצד ימין, ואח\"ז חזר לארץ ישראל, ונשלם בזה עם המוחין דחכמה הללו. \u0003ות\"ח כפנא לא אשתכח בארעא אלא כד מסתלקי רחמי מן דינא.\u0004 ובוא וראה. הרעב אינו בארץ אלא בעת שמסתלקים הרחמים מן הדין. כלומר, שז\"א שה\"ס רחמים נסתלק מהנוקבא שה\"ס דין. כי נפרד זווג זו\"ן, ונעשה רעב בהנוקבא, הנקראת ארץ. והטעם הוא. כי כן הדרך בכל פעם שזו\"ן משפיעים מדרגה חדשה להתחתונים, חוזרים, לקטנותם ונפסק זווגם, כנודע. ואל תתמה איך אפשר שנהר פישון שה\"ס החכמה השלמה יאיר בארץ מצרים מקום הקליפות וערות הארץ. הענין הוא בסו\"ה אמלאה החרבה, שאין הקליפות נבנות אלא מחורבנה של הקדושה, וכן להיפך, שאין הקדושה נבנית אלא מחורבנם של הקליפות. ולפיכך מסבת החטא דעצה\"ד נפלו אלו ניצוצות דחכמה מצד ימין בארץ מצרים וע\"ז רומז הכתוב, כגן ה' כארץ מצרים. וע\"כ לא יכול אברהם להבנות במוחין הגדולים, דחכמה דימין, אלא אחר שליקט אותם הניצוצין ממצרים. כמ\"ש לפנינו."],[5,"ויהי כאשר הקריב לבא מצרימה וכו':","אמר ר' אלעזר, הכתוב אומר, כאשר הקריב, היה צריך לומר כאשר קרב, ולמה אומר כאשר הקריב, אלא כמו שכתוב, ופרעה הקריב, שביארו, שהוא הקריב את ישראל לעשות תשובה. אף כאן \u0003הקריב,\u0004 יורה שהקריב את עצמו להקב\"ה כראוי. \u0003לבא מצרימה,\u0004 פירושו, להסתכל באלו המדרגות, שבמצרים, ולהתרחק מהן, ולהתרחק מעובדי מצרים."],[5,"","ביאור הדברים. כי יש כאן ב' בחינות. א) הוא קריבה למצרים. ב) מעשה מצרים ממש. וההפרש ביניהם, כי מעשה מצרים, הוא המשכת אור החכמה ממעלה למטה, כמו החטא דעצה\"ד. כי הכלים והניצוצין מבחינת החכמה, שפגם אדם בחטאו בעצה\"ד, נפלו לחלקם של המצרים כנ\"ל, וע\"כ הם ממשיכים בחטא הזה. אמנם יש מדרגה קרובה למעשה מצרים, ואינה מעשה מצרים ממש. והוא, כי הוא ממשיך הארת החכמה ממעלה למטה פעם אחת, כדי לחזק ולגדל את החסדים המכוסים מחכמה. שמצד אחד הוא כמו מעשה מצרים, כי הוא ממשיך ממעלה למטה כמוהם. ומצד הב' הוא הפכי למעשה מצרים, כי הוא רק מחזק וקובע הארת החסדים המכוסים מחכמה, ולפיכך נבחנת מדרגה זאת שהוא, קרובה למצרים, ולא ארץ מצרים ממש."],[5,"","וזה אמרו \u0003מאי כאשר הקריב אלא כדכתיב ופרעה וגו' אוף הכא דקריב, דאקריב גרמיה לקב\"ה כדקא יאות,\u0004 כי הקריב פירושו שהקריב עצמו להקב\"ה כראוי דהיינו למדרגת חג\"ת דז\"א שהיא חסדים מכוסים. \u0003לבא מצרימה\u0004 פירושו, \u0003לאשגחא באינון דרגין\u0004 דהיינו להמשיך הארת החכמה ממעלה למטה כמו מדרגות המצרים, אבל \u0003לאתרחקא מנייהו,\u0004 דהיינו להתרחק מהמשכת החכמה, \u0003ולהתרחקא מעובדי מצרים,\u0004 אלא לחזק ולקבוע הארת חחסדים המכוסים מחכמה, שהוא רחוק מקצה אל הקצה ממעשה מצרים. ושיעור הכתוב הוא, שהקריב עצמו להקב\"ה וע\"כ הקריב לבא מצרימה, לעשות כמעשיהם, אבל להתרחק מהם ולהתקרב להקב\"ה, עשה מעשה זו. ע\"כ נבחנת המעשה, שהקריב לבא מצרימה ועוד לא בא למצרים."],[6,"אר\"י ת\"ח וכו':","א\"ר יהודה בוא וראה, משום שירד למצרים בלי רשות, נשתעבדו בניו במצרים ארבע מאות שנים. שהרי כתוב וירד אברם מצרימה ולא כתוב שאמר לו הקב\"ה, רד מצרים. וע\"כ, נצטער כל אותו הלילה בשביל שרה. וביאור הדברים הללו, תמצא להלן בדף מ\"ח ד\"ה ואין ע\"ש."],[7,"ויאמר אל שרי וגו' יפת מראה את:","ושואל וכי עד אז, עוד לא ידע אברהם שהיא אשה יפת מראה. ומשיב, אלא שבארוה, דעד אז לא היה מסתכל בצורתה של שרה, מרוב הצניעות שהיתה ביניהם. וכאשר \u0003קרב למצרים\u0004 היא נתגלתה, וראה אותה. פירוש, כמ\"ש לעיל בסמוך, בסו\"ה, ויהי כאשר הקריב לבא מצרימה, שפירושו, שהקריב את עצמו ועשה מעשה קרובה למעשה מצרים, דהיינו שהמשיך הארת חכמה ממעלה למטה, והוא השפיע אותם אל שרה, ואלו המוחין מכונים אצלה \u0003יפת מראה,\u0004 כי מראה וראיה רומזים על מוחין דחכמה, וזש\"ה אחר שהקריב לבא מצרים, הנה נא ידעתי כי אשה יפת מראה את. דהיינו אחר שקבלה ממנו המוחין בסוד הקרבה למצרים. וזה אמרו, \u0003דעד ההיא שעתא לא אסתכל בדיוקנא דשרה בסגיאות צניעותא וכו',\u0004 כי אברהם ושרה היו מרכבה לדכר ונוקבא שמחזה ולמעלה דז\"א, ששם החסדים מכוסים מחכמה, המכונה ראיה והסתכלות, וע\"כ לא נסתכל בה. \u0003אלא כד קריב למצרים,\u0004 דהיינו שהמשיך המוחין דחכמה ע\"י קרבת מצרים כנ\"ל, והשפיע אליה. אז \u0003אתגליא איהי וחמא בה,\u0004 אז נתגלו החסדים שלה בהארת החכמה, המכונה ראיה, וע\"כ ראה בה."],[8,"ד\"א במה ידע וכו':","פירוש אחר לפרש מאין ידע עתה שהיא יפת מראה יותר מתמיד, עד שאמר הנה נא ידעתי. כי על ידי טורח הדרך האדם מתבזה, ועם זה, היא עמדה ביפיה ולא נשתנתה. ע\"כ ידע אז יותר מתמיד שהיא יפת מראה. פירוש. כי עוברי דרכים, כלומר, ההולכים בדרך ה' מטרם באים למטרתם, הם בקטנות המוחין והם מתבזים, ושרה היתה גם היא בדרך, ולא עוד אלא דרך ירידה כמש\"ה וירד אברם מצרימה, ומכ\"ש שמעשה המשכת המוחין היתה קרובה למעשה מצרים כנ\"ל, ומ\"מ האירו בה המוחין בכל שלמותם, ע\"כ אמר אז הנה נא ידעתי, כי ידע אז יותר מתמיד. \u0003ד\"א הנה נא ידעתי וכו':\u0004 פירוש אחר על מה שאמר הנה נא ידעתי. כי ראה עמה את השכינה. כלומר שזכה לגילוי שכינה, וע\"כ בטח אברהם ואמר אחותי היא."],[9,"ומלה דא אסתלק וכו':","ומלה זו \u0003אחותי היא,\u0004 מתבארת בב' פנים, אחד כמשמעו, דהיינו אחותי. ואחד כמו שכתוב, אמור לחכמה אחותי את. וכתוב כאן אמרי נא אחותי את, והמלה \u0003את\u0004 פירושו השכינה. וכן כתוב ואת תדבר אלנו, שגם שם פירושו השכינה. \u0003למען ייטב לי בעבורך\u0004 אמר כלפי השכינה, כלומר בעבור השכינה, וכן \u0003וחיתה נפשי בגללך,\u0004 משום שבזה דהיינו במוחין הללו דחכמה, מתעלה האדם בדרך החיים. כי אור החכמה נקרא אור החיה כנודע."],[10,"אמרי נא אחותי את וכו':","ר' ייסא אמר, יודע היה אברהם שהמצרים כולם שטופי זמה הם, ושואל וכיון שידע כל זה למה לא פחד על אשתו, ולא חזר מדרכי זה, שלא יכנוס שמה. ומשיב, אלא משום שראה עמה השכינה, וע\"כ בטח בה ולא היה מפחד."]],[[0,"","הַנְּשָׁמָה הִיא כֹּחַ עֶלְיוֹן עַל כָּל אֵלּוּ, וְהִיא מִכֹּחַ הַזָּכָר, הַסּוֹד שֶׁל עֵץ הַחַיִּים. וְזוֹ עוֹלָה לְמַעְלָה מִיָּד, וְכָל אֵלּוּ (אותן) שְׁלֹשׁ הַדְּרָגוֹת נִקְשָׁרוֹת יַחַד זֶה עִם זֶה. וּכְשֶׁנִּפְרָדוֹת, כֻּלָּן עוֹלוֹת וְשָׁבוֹת לְאוֹתוֹ מָקוֹם שֶׁיָּצְאוּ מִמֶּנּוּ."],[1,"","כְּשֶׁהָרוּחַ הַזּוֹ יוֹצֵאת מִן הָעוֹלָם הַזֶּה וְנִכְנֶסֶת לַמְּעָרָה שֶׁשָּׁם אָדָם וְהָאָבוֹת, הֵם נוֹתְנִים לָהּ פִּנְקָס סִימָן, וְנִכְנֶסֶת לְגַן הָעֵדֶן. קְרֵבָה לְשָׁם, וּמוֹצֵאת הַכְּרוּבִים וְאוֹתָהּ לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת. אִם זוֹכָה - רוֹאִים פִּנְקָס הַסִּימָן, וּפוֹתְחִים לָהּ פֶּתַח וְנִכְנֶסֶת. וְאִם לֹא - דּוֹחִים אוֹתָהּ הַחוּצָה."],[2,"","וְיוֹשֶׁבֶת שָׁם. כָּל אוֹתוֹ הַזְּמַן שֶׁיּוֹשֶׁבֶת, מִתְלַבֶּשֶׁת שָׁם בִּדְמוּת שֶׁל הָעוֹלָם הַזֶּה. וּבְרָאשֵׁי חֳדָשִׁים וְשַׁבָּתוֹת כְּשֶׁרוֹצָה לַעֲלוֹת, הַצַּדִּיקִים שֶׁבְּגַן עֵדֶן נוֹתְנִים לָהּ פִּנְקָס סִימָן וְעוֹלָה בָּעַמּוּד הַהוּא, וּפוֹגֶשֶׁת אֶת אוֹתָם שׁוֹמְרֵי חוֹמוֹת יְרוּשָׁלַיִם. אִם זוֹכָה - פּוֹתְחִים לָהּ פֶּתַח וְנִכְנֶסֶת, וְאִם לֹא - נוֹטְלִים מִמֶּנָּה אוֹתוֹ הַפִּנְקָס וְדוֹחִים אוֹתָהּ הַחוּצָה. הִיא שָׁבָה לַגָּן וְאוֹמֶרֶת, (שיר ג) מְצָאוּנִי הַשֹּׁמְרִים הַסֹּבְבִים בָּעִיר וְגוֹ', נָשְׂאוּ אֶת רְדִידִי מֵעָלַי. זֶהוּ פִּנְקָס הַסִּימָן שֶׁנָּטְלוּ מִמֶּנּוּ (ממנה). שׁוֹמְרֵי הַחוֹמוֹת, אֵלּוּ אוֹתָם שׁוֹמְרֵי חוֹמוֹת יְרוּשָׁלַיִם. (כדגמה הזו, הנשמה לנשמה מתפשטת מאותו הלבוש שלמעלה ומסתלקת למעלה למעלה ונהנית מאור השכינה, והנשמה (והנפש) נשארת בגוף, ובכל ראשי החדשים והמועדים והשבתות יורדת נשמה לנשמה ומזדוגת עם הנשמה שנשארה בגוף ומזדוגת עם הנשמה, והדמות של גן העדן שלמעלה היתה מן הרוח והעפר שנכר לגבי מעלה, וסוד חשוב הוא, ובלבוש זה מתלבש י\"ה לבוש של גן עדן שלמטה, הוא אש ומים, שנאמר שמים, עד כאן הרוח של השמאל היורדת למטה, יורדת לדרגתה, ונפשה נשארת בגוף של הארץ, שכתוב (איוב יד) אך בשרו עליו יכאב וגו', ועל זה אמרו שהמתים יודעים בעולם הבא מכבוד הצדיקים ומהעולם התחתון ומספרים זה עם זה), עד כָּאן סתרי תורָה,"],[3,"","וַיֵּרֶד אַבְרָם מִצְרַיְמָה לָגוּר שָׁם. מָה הַטַּעַם לְמִצְרַיִם? אֶלָּא מִשּׁוּם שֶׁשָּׁקוּל לְגַן ה', שֶׁכָּתוּב כְּגַן ה' כְּאֶרֶץ מִצְרַיִם. שֶׁשָּׁם שָׁקַל וְיָרַד נָהָר אֶחָד שֶׁהוּא לְיָמִין, שֶׁכָּתוּב (בראשית ב) שֵׁם הָאֶחָד פִּישׁוֹן הוּא הַסֹּבֵב אֵת כָּל אֶרֶץ הַחֲוִילָה אֲשֶׁר שָׁם הַזָּהָב."],[4,"","וְאַבְרָהָם כֵּיוָן שֶׁיָּדַע וְנִכְנַס בָּאֱמוּנָה הַשְּׁלֵמָה, רָצָה לָדַעַת כָּל אוֹתָן הַדְּרָגוֹת שֶׁנֶּאֶחְזוּ לְמַטָּה. וּמִצְרַיִם הָיָה נוֹסֵעַ מִיָּמִין (ד\"א לימין), וּמִשּׁוּם כָּךְ יָרַד לְמִצְרַיִם. וּבֹא וּרְאֵה, הָרָעָב לֹא נִמְצָא בָאָרֶץ אֶלָּא כַּאֲשֶׁר מִסְתַּלְּקִים רַחֲמִים מִן הַדִּין."],[5,"","וַיְהִי כַּאֲשֶׁר הִקְרִיב לָבא מִצְרָיְמָה. אָמַר רַבִּי אֶלְעָזָר, כַּאֲשֶׁר הִקְרִיב? כַּאֲשֶׁר קָרַב הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה כַּאֲשֶׁר הִקְרִיב? אֶלָּא כַּכָּתוּב (שמות יד) וּפַרְעֹה הִקְרִיב, שֶׁהוּא קֵרַב אֶת יִשְׂרָאֵל לִתְשׁוּבָה. אַף כָּאן הִקְרִיב, שֶׁהִקְרִיב אֶת עַצְמוֹ לַקָּדוֹשׁ-בָּרוּךְ-הוּא כָּרָאוּי. לָבֹא מִצְרָיְמָה, לְהִתְבּוֹנֵן בְּאוֹתָן הַדְּרָגוֹת וּלְהִתְרַחֵק מֵהֶן וּלְהִתְרַחֵק מִמַּעֲשֵׂי מִצְרַיִם."],[6,"","אָמַר רַבִּי יְהוּדָה, בֹּא רְאֵה, כֵּיוָן (ס\"א משום) שֶׁיָּרַד אַבְרָהָם לְמִצְרַיִם בְּלִי רְשׁוּת, הִשְׁתַּעְבְּדוּ בָנָיו בְּמִצְרַיִם אַרְבַּע מֵאוֹת שָׁנָה, שֶׁהֲרֵי כָּתוּב וַיֵּרֶד אַבְרָהָם מִצְרָיְמָה, וְלֹא כָתוּב רֵד מִצְרַיִם, וְהִצְטַעֵר כָּל הַלַּיְלָה הַהוּא בִּשְׁבִיל שָׂרָה."],[7,"","וַיֹּאמֶר אֶל שָׂרַי אִשְׁתּוֹ הִנֵּה נָא יָדַעְתִּי כִּי אִשָּׁה יְפַת מַרְאֶה אָתְּ. וְכִי עַד הַשָּׁעָה הַהִיא לֹא הָיָה יוֹדֵעַ אַבְרָהָם שֶׁהָיְתָה אִשָּׁה יְפַת מַרְאֶה? אֶלָּא זֶה פֵּרְשׁוּהָ, שֶׁעַד הַשָּׁעָה הַהִיא לֹא הִסְתַּכֵּל בִּדְמוּת שָׂרָה מֵרֹב הַצְּנִיעוּת שֶׁהָיְתָה בֵינֵיהֶם. וּכְשֶׁקָּרַב לְמִצְרַיִם, הִיא הִתְגַּלְּתָה וְרָאָה אוֹתָהּ."],[8,"","דָּבָר אַחֵר, בַּמֶּה יָדַע? אֶלָּא עַל יְדֵי טֹרַח הַדֶּרֶךְ אָדָם מִתְבַּזֶּה, וְהִיא עָמְדָה בְּיָפְיָהּ וְלֹא הִשְׁתַּנְּתָה. דָּבָר אַחֵר הִנֵּה נָא יָדַעְתִּי, שֶׁרָאָה עִמָּהּ אֶת הַשְּׁכִינָה, וּמִשּׁוּם כָּךְ בָּטַח אַבְרָהָם וְאָמַר אֲחֹתִי אָתְּ."],[9,"","וְזֶה הַדָּבָר עוֹלֶה לִשְׁנֵי גְוָנִים - אֶחָד כְּמַשְׁמָעוֹ, וְאֶחָד כַּכָּתוּב (משלי ז) אֱמֹר לַחָכְמָה אֲחֹתִי אָתְּ, וְכָתוּב (דברים ה) וְאַתְּ תְּדַבֵּר אֵלֵינוּ. לְמַעַן יִיטַב לִי בַּעֲבוּרֵךְ - כְּלַפֵּי שְׁכִינָה אָמַר, בַּעֲבוּרֵךְ יֵיטִיב לִי הַקָּדוֹשׁ בָּרוּךְ הוּא. וְחָיְתָה נַפְשִׁי בִּגְלָלֵךְ, מִשּׁוּם שֶׁבָּזֶה יִתְעַלֶּה אָדָם וְיִזְכֶּה לְהִתְעַלּוֹת לְדֶרֶךְ הַחַיִּים."],[10,"","אִמְרִי נָא אֲחֹתִי וְגוֹ'. רַבִּי יֵיסָא אָמַר, יוֹדֵעַ הָיָה אַבְרָהָם שֶׁכָּל הַמִּצְרִים שְׁטוּפִים הֵם בְּזִמָּה, וְכֵיוָן שֶׁכָּל זֶה יָדַע, לָמָּה לֹא פָחַד עַל אִשְׁתּוֹ שֶׁלֹּא חָזַר מִן הַדֶּרֶךְ וְלֹא יִכָּנֵס לְשָׁם? אֶלָּא מִשּׁוּם שֶׁרָאָה עִמָּהּ שְׁכִינָה."]]],[["וַיְהִי כְּבֹא אַבְרָם מִצְרָיְמָה וַיִּרְאוּ הַמִּצְרִים אֶת הָאִשָּׁה כִּי יָפָה הִיא מְאֹד. אָמַר רַבִּי יְהוּדָה בְּתֵיבָה אָעִיל לָהּ, וּפְתָחוּ לָהּ לְמֵיסַב מִנָּה קוּסְטוּנָא. כֵּיוָן דְּאִתְפַּתַּח הֲוָה נְהוֹרָא כִּנְהוֹרָא דְּשִׁמְשָׁא הֲדָא הוּא דִכְתִיב כִּי יָפָה הִיא מְאֹד.","מַאי מְאֹד, אֶלָּא דְּחָמוּ בַּתֵּיבָה דִיוּקְנָא (נ\"א נהורא) אָחֳרָא. אַפִּיקוּ לָהּ וְחָמוּ לָהּ כְּמִלְקַדְמִין הֲדָא הוּא דִכְתִיב וַיִּרְאוּ אוֹתָהּ שָׂרֵי פַרְעֹה. כֵּיוָן דִּכְתִיב וַיִּרְאוּ הַמִּצְרִים אֶת הָאִשָּׁה מַאי וַיִּרְאוּ אוֹתָהּ שָׂרֵי פַרְעֹה, אֶלָּא דְּאֲפִיקוּ לָהּ וְחָמוּ לָהּ כְּמִלְקַדְּמִין וּכְדֵין וַיְהַלְּלוּ אוֹתָהּ אֶל פַּרְעֹה וְגו'. (כאן שייך מה שבז\"ח דף לח ע\"ב)","אָמַר רַבִּי יִצְחָק. וַוי לְאִנּוּן חַיָּיבַיָא דְעָלְמָא דְּלָא יָדְעִין וְלָא מַשְׁגִּיחִין בַּעֲבִידְתֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, וְאִנּוּן לָא מִסְתַּכְּלֵי (בכלא) דְּכָל מַה דְּהֲוֵי בְּעָלְמָא מֵעִם קוּדְשָׁא בְּרִיךְ הוּא אִיהוּ, דְּאִיהוּ יָדַע בְּקַדְמִיתָא מַה דִּלְהוֵי בְּסוֹפָא דִּכְתִיב, (ישעיהו מ״ו:י׳) מַגִּיד מֵרִאשִׁית אַחֲרִית. וְאִיהוּ אִסְתָּכֵי וְעֲבִיד עֲבִידָן בְּקַדְמִיתָא בְּגִין לְסָלְקָא לוֹן לְבָתַר יוֹמִין.","תָּא חֲזֵי אִלְמָלֵא דְּאִנְסִיבַת שָׂרַי לְגַבֵּי פַּרְעֹה, לָא אַלְקֵי הוּא, וְאַלְקָאוּתָא דָּא גָּרִים אַלְקָאוּתָא לְבָתַר כֵּן דְּיִלְקוּן מִצְרַיִם בִּנְגָעִים גְּדוֹלִים, כְּתִיב הָכָא נְגָעִים גְּדוֹלִים וּכְתִיב הָתָם (דברים ו׳:כ״ב) וַיִּתֵּן יְיָ אוֹתוֹת וּמוֹפְתִים גְּדוֹלִים וְרָעִים בְּמִצְרַיִם. מַה לְּהַלָּן עֶשֶׂר מַכּוֹת אַף כָּאן עֶשֶׂר מַכּוֹת. כְּמָה דְּעֲבִיד קוּדְשָׁא בְּרִיךְ הוּא נִסִּין וּגְבוּרָן לְיִשְׂרָאֵל לֵילְיָא, אוּף הָכָא עֲבַד לָהּ קוּדְשָׁא בְּרִיךְ הוּא לְשָׂרָה נִסִּין וּגְבוּרָאן לֵילְיָא.","רַבִּי יוֹסֵי פָּתַח וְאָמַר (תהילים ג׳:ד׳) וְאַתָּה יְיָ מָגֵן בַּעֲדִי כְּבוֹדִי וּמֵרִים רֹאשִׁי. אָמַר דָּוִד אַף עַל גַּב דְּכָל בְּנֵי עָלְמָא יֵיתוּן לַאֲגָחָא בִּי קְרָבָא, וְאַתָּה יְיָ מָגֵן בַּעֲדִי. תָּא חֲזֵי, כְּתִיב מָגֵן בַּעֲדִי. אָמַר דָּוִד לְקוּדְשָׁא בְּרִיךְ הוּא, רִבּוֹנוֹ שֶׁל עוֹלָם מִפְּנֵי מָה לָא עַבְדֵי בִּי חֲתִימָה דִבְרָכָה כְּמָה דְּחָתְמֵי בְּרָכָה בְּאַבְרָהָם דִּכְתִיב אָנֹכִי מָגֵן לָךְ. וְאָמְרֵי מָגֵן אַבְרָהָם.","אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְדָוִד, אַבְרָהָם כְּבָר בְּחַנְתִּיו וּצְרַפְתִּיו וְקָאִים קַמָּאי בְּקִיּוּמָא שְׁלִים. אָמַר לֵיהּ דָּוִד אִי הָכִי (תהילים כ״ו:ב׳) בְּחָנֵנִי יְיָ וְנַסֵּנִי צָרְפָה כִלְיוֹתַי וְלִבִּי. כֵּיוָן דְּעֲבַד הַהִיא מִלָּה דְּבַת שֶׁבַע אִדְכַּר דָּוִד קַמֵּיהּ עַל מַה דְּאָמַר. אָמַר (תהילים י״ז:ג׳) בָּחַנְתָּ לִבִּי פָּקַדְתָּ לַיְלָה צְרַפְתַּנִּי בַּל תִּמְצָא זַמּוֹתִי בַּל יַעֲבָר פִּי.","אָמַר אֲנָא אֲמִינָא בְּחָנִנִי יְיָ וְנַסֵּנִי וְאַנְתְּ בָּחַנְתָּ לִבִּי. אֲנָא אֲמִינָא צָרְפָה כִלְיוֹתַי וְאַתְּ צְרַפְתַּנִּי בַּל תִּמְצָא לָא אַשְׁכַּחְתְּ לִי כְּדְקָא יְאוּת. זַמּוֹתִי בַּל יַעֲבָר פִּי. מַאן יִתֵּן וְהַאי מִלָּה דַּחֲשָׁבִית דְּלָא יַעֲבָר לִי פּוּמָאי,","וְעִם כָּל דָּא חָתְמִין בֵּיהּ בְּרָכָה דְּקָאֲמָרָן מָגֵן דָּוִד, וּבְגִין כָּךְ אָמַר דָּוִד וְאַתָּה יְיָ מָגֵן בַּעֲדִי, כְּבוֹד וּמֵרִים רֹאשִׁי. (ד\"א ל\"ג והאי) וַדַּאי דַּרְגָּא דָּא יְקָרָא דִילִי דְּאֲנָא מִתְעַטַּרְנָא בֵּיהּ:","וַיְצַו עָלָיו פַּרְעֹה אֲנָשִׁים וַיְשַׁלְּחוּ אוֹתוֹ. תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא אִיהוּ מָגֵן לְצַדִּיקַיָּיא דְּלָא יִשְׁלְטוּן בְּהוּ בְּנֵי נָשָׁא, וְקוּדְשָׁא בְּרִיךְ הוּא אָגִין עַל אַבְרָהָם דְּלָא יִשְׁלְטוּן בֵּיהּ וּבְאִתְּתֵיהּ.","תָּא חֲזֵי, שְׁכִינְתָּא לָא אִתְעֲדֵי מִנָּהּ דְּשָׂרָה כָּל הַהוּא לֵילְיָא, אֲתָא פַּרְעֹה לְמִקְרַב בַּהֲדָהּ, אֲתָא מַלְאַךְ וְאַלְקֵי לֵיהּ, כָּל אֵימַת דְּאֲמְרָה שָׂרָה אַלְקֵי הוּא מַלְקֵי, וְאַבְרָהָם הֲוָה מַתְקִיף בְּמָארֵיהּ דְּהָא שָׂרָה לָא יָכְלִין לְשַׁלְטָאָה עֲלָהּ הֲדָא הוּא דִכְתִיב, (משלי כ״ח:א׳) וְצַדִּיקִים כִּכְפִיר יִבְטָח, וְהָכָא נִסְיוֹנָא הוּא דְּלָא הִרְהֵר אֲבַתְרֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא.","אָמַר רַבִּי יִצְחָק תָּא חֲזֵי, דִּבְגִין כָּךְ לָא פַקֵּיד קוּדְשָׁא בְּרִיךְ הוּא לְנַחֲתָא לְמִצְרַיִם אֶלָּא הוּא עַצְמוֹ מִגַרְמֵיהּ נָחַת, בְּגִין דְּלָא יְהֵא פִּתְחוֹן פֶּה לִבְנֵי עָלְמָא דְּאָמַר לֵיהּ כֵּן וּלְבָתַר אִצְטַעֵר עַל אִתְּתֵיהּ.","רַבִּי יִצְחָק פָּתַח וְאָמַר (תהילים צ״ב:י״ג) צַדִּיק כַּתָּמָר יִפְרָח כְּאֶרֶז בַּלְּבָנוֹן יִשְׂגֶּא. צַדִּיק כַּתָּמָר יִפְרָח. מִפְּנֵי מָה אַקִּישׁ צַדִּיק לְתָמָר. מַה תָּמָר כֵּיוָן דְּגָזְרִין לֵיהּ לָא סָלִיק עַד זְמַן סַגְיָא, אוּף הָכִי צַדִּיק כֵּיוָן דְּאִתְאֲבִיד מֵעָלְמָא לָא סָלִיק אַחֵר תְּחוֹתוֹי עַד זְמַן סַגְיָא. כְּאֶרֶז בַּלְּבָנוֹן יִשְׂגֶא אוּף הָכִי נָמֵי.","כַּתָּמָר יִפְרָח מַה תָּמָר לָא סָלִיק אֶלָּא דְּכַר וְנוּקְבָא. אוּף הָכִי צַדִּיק לָא סָלִיק אֶלָּא דְּכַר וְנוּקְבָא, דְּכַר צַדִּיק וְנוּקְבָא צַדֶּקֶת, כְּגַוְונָא דְּאַבְרָהָם וְשָׂרָה.","כְּאֶרֶז בַּלְּבָנוֹן יִשְׂגֶא מָה אֶרֶז בַּלְּבָנוֹן עִלָּאָה עַל כֹּלָּא וְכֹלָּא יַתְבֵי תְּחוֹתוֹי, אוּף הָכִי צַדִּיק הוּא עִלָּאָה עַל כֹּלָּא וְכֹלָּא יַתְבֵי תְּחוֹתוֹי. וְעָלְמָא לָא קָיְימָא אֶלָּא עַל צַדִּיק חַד דִּכְתִיב, (משלי י׳:כ״ה) וְצַדִּיק יְסוֹד עוֹלָם. וְעֲלֵיהּ קָאִים עָלְמָא, וּבְגִינֵיהּ אִסְתְּמִיךְ, וְעֲלֵיהּ אִשְׁתִּיל.","רַבִּי יְהוּדָה אָמַר וְהָא תָּנִינָן דְּעַל שִׁבְעָה סָמְכִין עָלְמָא קָיְימָא דִּכְתִיב, (משלי ט׳:א׳) חָצְבָה עַמּוּדֶיהָ שִׁבְעָה. אָמַר לֵיהּ רַבִּי יוֹסֵי הָכִי הוּא וַדַּאי, אֲבָל (הכא) כֻּלְהוּ אָחֳרָנִין בִּשְׁבִיעָאָה קָיְימֵי דְּאִיהוּ סָמְכָא דְעָלְמָא, וְאִיהוּ צַדִּיק וְדָא אַשְׁקֵי (לעלמא) וְרָוִי עָלְמָא (ס\"א מן כלא) וְזָן כֹּלָּא. וְעֲלֵיהּ כְּתִיב (ישעיהו ג׳:י׳) אִמְרוּ צַדִּיק כִּי טוֹב כִּי פְּרִי מַעַלְלֵיהֶם יאכֵלוּ. וּכְתִיב, (תהילים קמ״ה:ט׳) טוֹב יְיָ לַכֹּל וְרַחֲמָיו עַל כָּל מַעֲשָׂיו."],[[0,"ויהי כבא אברם מצרימה וגו':","א\"ר יהודה בתיבה הכניס אותה למצרים. והמצרים פתחו התיבה לקבל ממנה מכס. כלומר שאחר שהמשיך לשרה המוחין דחכמה חזר והעלה המוחין למחזה ולמעלה דזו\"ן ששם החסדים מכוסים מחכמה, שתהיה משומרת מהמצרים, ומטעם זה מכונה שם \u0003תיבה,\u0004 שאותיותיה למפרע ממלה \u0003הבית,\u0004 (כנ\"ל נח דף ס\"ד ד\"ה פירוש ע\"ש) אמנם המצרים פתחו התיבה להחזירה לבחינת הבית, דהיינו בית פרעה. כדי לקבל מכס. כלומר, שפתחו כדי להמשיך הארת החכמה שבה ממעלה למטה, שרשות בידם לקבל זה בתורת מסים להיותה בארצם, \u0003כיון דאתפתח וכו':\u0004 כיון שנפתחה התיבה. היה האור כאור השמש. כלומר שהיה אורה של שרה, שה\"ס אור הלבנה גדול כאור החמה, בסוד ב' מאורות הגדולים. וזהו שכתוב כי יפה היא מאד."],[1,"מאי מאד וכו':","ושואל מה רומז הכתוב בהמלה \u0003מאד.\u0004 ומשיב, אלא שהמצרים ראו בתיבה אור אחר, דהיינו אור חסדים המכוסים, כנ\"ל. הוציאו אותה מהתיבה והמשיכו האור ממעלה למטה בבחינת בית וראו אותה יפה כבתחילה, דהיינו כמו שהיתה בהתיבה. כלומר שמעשה מצרים לא פגמו אותה, ונשאר ובה יפיה כמו שהיתה בהתיבה."],[1,"הה\"ד ויראו אותה שרי פרעה:","ושואל כיון שכתוב ויראו המצרים את האשה, למה לי ויראו אותה שרי פרעה, הרי גם הם היו מצרים. ומשיב, אלא שהוציאו אותה מהתיבה, דהיינו שאור החכמה שהיה טמון בה המשיכו ממעלה למטה, בבחינת \u0003בית\u0004 וראו אותה עומדת ביפיה כבתחילה, כעוד שהיתה בהתיבה. ואז ויהללו אותה אל פרעה ותקח האשה \u0003בית\u0004 פרעה. פירוש. כי המצרים פתחו את התבה, וראו את שרה בעודה בהתבה שהיה אורה כאור השמש. ושרי פרעה הם שהוציאוה מן התיבה, וראו אותה עומדת ביפיה כמלפנים בעודה בתיבה. וע\"כ יש כאן ב' ראיות: של המצרים ושל שרי פרעה."],[2,"א\"ר יצחק ווי לאינון וכו':","אר\"י, ווי לרשעי עולם הללו, שאינם יודעים, ואינם מסתכלים כדי להבין, שכל מה שיש בעולם מהקב\"ה הוא. כלומר, שהוא לבדו ית', עשה ועושה ויעשה את כל המעשים כולם שבעולם. שהוא ידע מראש מה שיהיה בסוף. שכתוב מגיד מראשית אחרית. והוא צופה ועושה מעשים מראשית, כדי לחזור עליהם ולעשותם בשלמות לאחר זמן."],[3,"ת\"ח אלמלא דאנסיבת וכו':","בוא וראה אלמלא לוקחה שרי אל פרעה לא היה פרעה מוכה, והכאה זו גרם הכאה לאחר מכאן, שיוכו המצרים בנגעים גדולים, ביציאת ישראל ממצרים, כי כאן כתוב נגעים גדולים, ושם, ביציאת ישראל ממצרים, כתוב, ויתן ה' אותות ומופתים גדולים וגו'. ויליף גזירה שוה, גדולים גדולים, מה שם הם עשר מכות, אף כאן, הוכה פרעה עשר מכות. וכמו שעשה הקב\"ה לישראל נסים וגבורות בלילה, אף כאן, עשה הקב\"ה נסים וגבורות בלילה. הרי, שבשעה שעשה המכות לפרעה, בשביל שרה, היה צופה ומביט לחזור עליהם ולעשותם בגמר שלימותם לאחר זמן, בעת יציאת ישראל ממצרים."],[3,"","ויש כאן עמקות מאד נפלא, ומוכרחני להאריך בו, להיותו הקוטב של כל המאמר שלפנינו. והנה כבר נתבאר לעיל (דף מ\"ד ד\"ה ביאור) שסוד הכלים והניצוצין של מוח החכמה דאדם הראשון, שנשרו ממנו בסבת החטא דעץ הדעת ונמסרו לקליפות, המה נמסרו למצרים, שה\"ס חכמת מצרים, שבשעה שישראל יבררו כל הכלים הללו מהם ויחזירו אותם לקדושה, נאמר אז, והאבדתי את חכמת מצרים. אמנם אין הבירור הזה יוכל להעשות אלא על ידי המצרים עצמם, ולא ע\"י עובדי השם, כי אי אפשר לבררם לצורך הקדושה, זולת אם ימשיך לתוכם אור העליון ממעלה למטה, כי כמו שנפגמו על ידי המשכת האור ממעלה למטה, שה\"ס איסור עץ הדעת (כנ\"ל בראשית ב' דף ק\"ע ד\"ה ועל ע\"ש) כן צריך להיות טהרתם מהקליפות ע\"י המשכת האור אליהם מלמעלה למטה. שזסו\"ה, כל דבר אשר יבא באש תעבירו באש וטהר וגו'. (במדבר ל\"א). כי הכלים לא יפלטו מתוכם בליעת הטומאה, שה\"ס זוהמא דחויא, שנבלע בהם בחטא עצה\"ד, זולת שיכשירו אותם באותו הדרך שבלעו האיסור, דהיינו על ידי המשכת האור ממעלה למטה שהוא החטא דעצה\"ד. ולפיכך אי אפשר שיעשה זה אלא על ידי המצרים עצמם, שחטא דעץ הדעת וזוהמתו דבוקה בהם, והמה מבררים הכלים ונותנים אותם לישראל. בסו\"ה יכין רשע וצדיק ילבש. ובכדי שימסרו הכלים לישראל צריכים לזה ב' פעולות. א) היא בדרך כפיה, דהיינו שהקב\"ה מכריחם על ידי מכות ויסורים, עד שימסרו אותם לישראל. ב) שהמסירה עצמה צריכה להיות מדעתם ומרצונם הטוב, שהסו\"ה, וה' נתן את חן העם בעיני מצרים וישאילום וינצלו את מצרים (שמות י\"ב) הרי שלא יכלו ישראל לנצל את מצרים זולת על ידי מציאת חן שמצאו בעיני מצרים. וכן ז\"ס שהקב\"ה לא הוציא ישראל ממצרים בעל כרחו של פרעה אלא שצוה אליו, שלח את עמי ויעבדוני, דהיינו דוקא בהסכמתו, וכן היה באמת אחר מכת בכורות, שנאמר, ויקם פרעה לילה וגו' ויאמר קומו צאו מתוך עמי וגו' ולכו עבדו את ה' כדברכם. כי הוא מטעם הנ\"ל שאין הכלים והניצוצין האלו נמסרין מהמצרים לישראל אלא מדעתם ורצונם, וע\"כ היה צריך פרעה לקום לילה ולומר לישראל מדעתו ורצונו, קומו צאו מתוך עמי וגו', שבדבורים הללו מסר להם הכלים מדעתו ורצונו."],[3,"","ואין המוחין הללו נגמרים שהם מדרגת אור החיה, אלא בג' פעמים, שהם ג' בחינות מוחין. א) בדרך נסיון, כמו אברהם, שלא צוהו הקב\"ה לרדת מצרימה, אלא ששלח רעב בארץ, והכריחו בזה לרדת מצרימה מדעתו עצמו, ואחר שלוקחה שרה בית פרעה ונצטער כל אותו הלילה, השב שהענישהו הקב\"ה על החטא שירד למצרים ונתחבר ברשעים הללו. ואחר שעמד בנסיון ולא הרהר אחר מדותיו ית', זכה לקבל מפרעה את הכלים והניצוצין למוחין הגדולים, שנפלו לרשותו בעת החטא דעץ הדעת כנ\"ל, בסו\"ה ולאברם היטיב בעבורה וגו', וכן ויצו עליו פרעה אנשים וישלחו אותו, כדוגמת הכתוב ביציאת מצרים, ויהי בשלח פרעה את העם וגו'. שבזה מסר לו פרעה את הכלים מדעתו ורצונו הטוב כנ\"ל. ובחינה זו נבחנת לבירורי הכלים, למוחין דו\"ק של המדרגה דאור החיה, והוא מטעם שלא השיג אותה על ידי דבר ה', זולת ע\"י חטא ונסיון."],[3,"","ב) הוא על ידי מאמר ה', שהקב\"ה אמר לו לרדת למצרים. וזהו מבואר בדבר ה', בהכתוב, ידע תדע כי גר יהיה זרעך בארץ לא להם וגו' ואחרי כן יצאו ברכוש גדול. שה\"ס מוחין דחיה ממש. וכן אמר ליעקב אנכי ארד עמך מצרימה ואנכי אעלך גם עלה וגו'. ולפי שהירידה היה ברשות הקב\"ה, ע\"כ הכלים שהוציאו משם חשובים ביותר, וזכו בהם למוחין הגדולים דחיה. שה\"ס המוחין דליל פסח."],[3,"","ג) בסוד המעמד הקדוש, שזכו לשמוע מפי הגבורה אנכי ה' אלקיך אשר הוציאך מארץ מצרים וגו' שז\"ס ההמשך של גילוי המוחין דיציאת מצרים, וה\"ס המוחין דיחידה, שה\"ס חרות ממלאך המות כנודע. והנה נתבאר שאין המוחין הללו נשלמים אלא בג' פעמים. ואטעם, שבפעם הא'. המה מחויבים לבא בדרך חטא ונסיון, הוא, משום שתחילת הבירור נעשה באיסור על ידי המצרים כנ\"ל, ואם היה הקב\"ה מצוהו לרדת מצרים, היה מתדבק בהם, ובמעשיהם הללו, ולא היה פורש מהם לעולם, וע\"כ היה מוכרח לבא מעצמו בדרך חטא, כדי שימהר להסתלק מהם."],[3,"","וזה אמרו (באות קט\"ז) \u0003ווי לאינון חייביא וכו' ואינון לא מסתכלי דכל מה דהוי בעלמא, מעם קב\"ה איהו.\u0004 חייביא דעלמא, פירושו אותם שהתחילו לקבל מדרגות קדושות, ונתעכבו בתחילתם ואינם משיגים יותר, וזה עון פלילי, שהזהר מכנה אותם \u0003דעיילי ולא נפקי,\u0004 ועיקר עכובם יקרה להם, בעת השגת מוחין דחיה בפעם הא' הנ\"ל, מפאת שחושבים שמוחין הללו השיגו ע\"י מעשיהם הם ולא על ידי הקב\"ה, ואם היו חותרים לדעת ולהבין כמו אברהם, \u0003דכל מה דהוי בעלמא מעם קב\"ה איהו,\u0004 אז היו זוכים לבחינה הב' שהקב\"ה יצוה אותם לרדת למצרים, שה\"ס השגת מדרגה הגדולה מוחין דחיה, כמו שזכו ישראל ביציאת מצרים בליל פסח, כנ\"ל. וז\"ש \u0003ואנון לא מסתכלי,\u0004 דהיינו שאינם מסתכלים להבין ולדעת כמו אברהם וז\"ש \u0003דאיהו ידע בקדמותא מה דלהוי בסופא וכו' ואלקאותא דא גרים אלקאותא לבתר כן וכו'.\u0004 שצריכים להסתכל עד ושיזכו וישיגו שאלו המכות שקבל פרעה בפעם הא' באברהם, היה תכף על ידי הקב\"ה עצמו, שהיה אז צופה ומביט בראשית מה שיהיה באחרית, ביציאת מצרים, דהיינו שהם רשימה והכנה לבירורי המוחין, שישיגו בשעה שיתן להם רשות לרדת מצרים, כמו שנתן רשות לישראל, שאמר לו אנכי ארד עמך מצרים וכו' כי הזוכה לזה ישיג אז המוחין הגדולים דאור החיה, כנ\"ל. וזהו שמשוה הנסים של שרה, לנסים של יציאת מצרים. כי כל המעשים דבחינה א' דמוחין דו\"ק דחיה הם רשימה והכנה להמוחין דבחינה ב', שהם מוחין דחיה. וגם אברהם עצמו זכה בידיעה זו, כמ\"ש, ידע תדע כי גר יהיה זרעך בארץ לא להם וגו' שבידיעה זו השיג גם הוא אותם המוחין דיציאת מצרים."],[4,"ר' יוסי פתח וכו'","ר\"י פתח ואמר, ואתה ה' מגן בעדי כבודי ומרים ראשי. אמר דוד, אפילו בני העולם יבואו ויעשו עמי מלחמה. לא יוכלו לי, כי ואתה ה' מגן בעדי. בוא וראה, כתוב מגן בעדי. אמר דוד להקב\"ה רבונו של עולם, מפני מה אין חותמים בי ברכה, כמו שחותמים ברכה באברהם, שכתוב אנכי מגן לך. ואומרים \u0003מגן אברהם.\u0004 ולמה אין חותמים בי \u0003מגן דוד.\u0004"],[5,"א\"ל קב\"ה לדוד וכו':","והשיב הקב\"ה לדוד. אברהם, כבר בחנתיו וצרפתיו, ועמד בנסיון לפני בקיום שלם. אמר לו דוד, אם כן, בחנני ה' ונסני צרפה כליותי ולבי. כיון שעשה אותו מעשה דבת שבע, נזכר דוד מה שאמר לפני הקב\"ה. אמר, בחנת לבי וגו'."],[6,"אמר, אנא אמינאו כו'",": אמר, אני אמרתי בחנני ה' ונסני, ואתה בחנת לבי בנסיון עם בת שבע. אני אמרתי צרפה כליותי, ואתה צרפתני בל תמצא. זמותי בל יעבר פי, מי יתן שאותו דבר שחשבתי לא היה עבר אל פי, ולא אמרתי אז בחנני ה' ונסני וגו'."],[6,"","ביאור הדברים. כי סוד הכתוב ואתה ה' מגן בעדי. וכן אנכי מגן לך. סובב על המוחין הנ\"ל. הנבררים על ידי המצרים. ומכונים מגן מב' טעמים. א) משום שאין מי שישיגם אלא בדרך מגן והצלה. כמו שפרעה הוכה להגן על שרה ולהוציאה משם. וכן להגן על ישראל ולהוציאם ממצרים ב) משום שהזוכה בהם אין לו עוד פחד משום דבר. ונבחנים ע\"כ כמו שהם מגן בעדו. וזה אמרו \u0003אמר דוד, אע\"נ דכל בני עלמא ייתון לאגחא בי קרבא, ואתה ה' מגן בעדי.\u0004 דהיינו כמבואר שהזוכה בהם אינו מפחד עוד משום דבר."],[6,"","וזה אמרו, \u0003מפני מה לא עבדי בי חתימה דברכה כמה דחתמי באברהם, דכתיב אנכי מגן לך ואמרי מגן אברהם.\u0004 כלומר שבקש על המוחין \u0003דמגן\u0004 הנ\"ל. כי בכל ברכה ממשיכים בה תחילה בחינת ו\"ק ממדרגה המיוחדת לה. ובחתימת הברכה, ממשיכים הג\"ר שבה. ובחתימה \u0003דמגן\u0004 נמשכים בחינת הג\"ר הגדולים, שהכלים נבררים ע\"י המצרים. כנ\"ל. ולפי שאברהם זכה בהם ע\"כ כתוב בו אנכי מגן לך. וע\"כ חותמים בו, מגן אברהם. ובקש דוד מהקב\"ה שיזכהו ג\"כ במוחין הגדולים הללו כמו לאברהם. וז\"ש, \u0003א\"ל קב\"ה לדוד אברהם, כבר בחנתיו וצרפתיו, וקאים קמא בקיומא שלים,\u0004 כלומר שבפעם הא', אי אפשר להשיג מוחין הללו, אלא על ידי נסיון (כנ\"ל דף מ\"ח ד\"ה ואין ע\"ש) כמו אברהם שלא זכה בהם, אלא ע\"י שבחנתיו בהנסיון של חטיפת שרה וכו', ואם אתה מוכן לבא בנסיון כמוהו, תוכל גם עתה לזכות בהם. וז\"ש א\"ל דוד אי הכי בחנני ה' ונסני וגו'. כלומר שאמר, כי גם הוא מוכן לכך כמו אברהם."],[6,"","וז\"ש, \u0003כיון דעבד האי מלה דבת שבע אדכר דוד וכו'.\u0004 כי באמת היתה בת זוגו של דוד מיום שנברא העולם, (כנ\"ל בהקדמת הזהר דף ק\"ז אות קל\"ב. ובנח דף קי\"א אות שי\"ט) אלא דוד לא היה יכול להשפיע לבת שבע אותם המוחין, כמו אברהם שלא היה יכול לברר אותם. וכמו שבררו המצרים אותם בשביל אברהם, (כנ\"ל דף מ\"ח ד\"ה ויש) ואברהם קבל אותם מהמצרים בדרך חטא ונסיון כנ\"ל, כן אוריה החתי נשא את בת שבע תחילה, והוא השפיע לה אותם המוחין, ואח\"כ קבל דוד את המוחין הללו באמצעית בת שבע על ידי חטא ונסיון, בדומה לאברהם. ואז זכה באלו המוחין \u0003דמגן\u0004 כמו אברהם. אלא שנדמה לו תחילה שלא עמד בנסיון כראוי, משום שהרג לאוריה בחרב בני עמון, וע\"כ אמר \u0003בחנת לבי\u0004 וגו' אבל לבסוף מחל לו הקב\"ה וזכה בהמוחין הללו."],[7,"","וז\"ש \u0003ועם כל דא חתמין ביה ברכה דקאמרן מגן דוד,\u0004 דהיינו שזכה בהמוחין \u0003דמגן,\u0004 כמו אברהם. \u0003ובגין כך אמר דוד, ואתה ה' מגן בעדי,\u0004 ואחר שזכה בהם אמר דוד, ואתה ה' מגן בעדי. \u0003כבודי ומרים ראשי ודאי דרגא דא יקרא דילי, דאנא מתעטרנא ביה.\u0004 כבודי ומרים ראשי, פירושו, שאמר, מדרגה זו \u0003דמגן\u0004 הוא כבודי ודאי, שאני מתעטר בה."],[8,"ויצו עליו פרעה אנשים וישלחו אותו וכו':","בוא וראה הקב\"ה הוא מגן לצדיקים, שלא ישלטו בהם אנשים. והקב\"ה הגן על אברהם שלא ישלטו בו ובאשתו. פירוש, כי כאן בסוד ויצו עליו פרעה אנשים וישלחו אותו, מסר לו גמר הכלים דמוחין דמגן הנ\"ל. שזהו כמו סו\"ה ויקם פרעה לילה וגו' ויאמר קומו צאו מתוך עמי. וכן ויהי בשלח פרעה את העם. ואז נמשכו לאברהם המוחין דמגן באותם הכלים. וז\"ש \u0003קב\"ה איהו מגן לצדיקיא, וכו' דלא ישלטון ביה ובאתתיה.\u0004 כלומר, כי עתה זכה במוחין דמגן. שהזוכה בהם אינו מפחד עוד משום איש. (כנ\"ל דף נ' ד\"ה ביאור ע\"ש)."],[9,"ת\"ח שכינתא","וכו': בוא וראה, השכינה, לא היתה מסתלקת משרה כל אותה הלילה. בא פרעה לקרב אליה, בא המלאך והכה אותו. בכל עת שאמרה שרה הך, הוא הכה. ואברהם היה מפציר בתפלה ברבונו, על שרה, שלא יוכלו לשלוט עליה. וז\"ש וצדיקים ככפיר יבטח. וכאן היה נסיון, שנסה ה' את אברהם, ולא הרהר אחר הקב\"ה."],[10,"אר\"י ת\"ח דבגין כך וכו':","א\"ר יצחק, בוא וראה, משום זה לא צוהו הקב\"ה לירד למצרים, אלא הוא ירד מעצמו, כדי שלא יהיה פתחון פה לבני העולם, על הקב\"ה, כי אמר לו לירד למצרים, ואחר כך נצטער על אשתו."],[11,"ר' יצחק פתח וכו':","ר\"י פתח ואמר, צדיק כתמר יפרח כארז בלבנון ישגא. ושואל צדיק כתמר יפרח, מפני מה משוה את הצדיק לתמר. ואומר, מה תמר כיון שקצצו אותו לא יחזור ויעלה עד זמן רב, דהיינו לע' שנים, אף הצדיק כן, כיון שנאבד מהעולם, לא יבא אחר תחתיו, עד זמן רב, דהיינו עד ע' שנים, שהם ז\"ס חג\"ת נהי\"מ שכל אחת כלולה מעשר. והטעם הוא, מפני שאין לו שלמות זולת בהנוקבא שהיא המלכות, ספירה השביעית, וע\"כ נצרך לכל ע' שנים."],[12,"כתמר יפרח וכו':","הוא להורות, מה תמר אינו עולה אלא זכר ונקבה, אף הצדיק כן, שאינו עולה אלא זכר ונקבה. הזכר הוא צדיק והנקבה היא צדקת, כמו אברהם ושרה. וע\"כ אינו נשלם אלא בע' שנה שלמים כנ\"ל."],[13,"כארז בלבנון ישגא.","מה ארז בלבנון הוא עליון על כל האילנות, אף הצדיק, הוא עליון על כל, והכל יושבים תחתיו. כלומר שמתקימים בזכותו. פירוש כי הצדיק, שה\"ס יסוד דז\"א שורשו הוא בבינה, שהוא נכלל שם בסוד קו המכריע בין ב' הקוין ימין ושמאל אשר שם. (כנ\"ל ב\"א דף נ\"ג ד\"ה יסודא) וע\"כ הוא נבחן \u0003לעליון על כל\u0004 ז\"ס חג\"ת נהי\"מ. וכן \u0003וכלא יתבי תחותוי,\u0004 כי הוא הממשיך המוחין מבינה ומשפיע אותם להנוקבא, וממנה לכל העולמות. וז\"ש \u0003ועלמא לא קיימא אלא על צדיק חד,\u0004 והעולם, שה\"ס הנוקבא, אינה עומדת אלא על צדיק אחד, כמו שכתוב, וצדיק יסוד עולם. \u0003ועליה קאים עלמא, ובגיניה אסתמיך, ועליה אשתיל.\u0004 ועליו עומד העולם שהיא הנוקבא. ובשבילו הוא נסמך, ועליו הוא נשתל. כלומר שמשפיע לה מג' קוין שלו. \u0003קאים\u0004 ה\"ס קו ימין \u0003אסתמיך\u0004 ה\"ס קו שמאל. \u0003אשתיל\u0004 ה\"ס קו אמצעי."],[14,"ר' יהודה אמר וכו':","רי\"א, והרי למדנו, שעל שבעה עמודים העולם עומד, שהם חג\"ת נהי\"מ, ולא על צדיק אחד בלבדו, כמ\"ש ר' יצחק. א\"ל ר' יוסי, כן הוא ודאי, אבל כל עמודים האחרים עומדים בכח עמוד השביעי שהוא הסומך של העולם, והוא הנקרא צדיק, דהיינו יסוד רז\"א, והוא משקה ומרוה את העולם, שהיא הנוקבא. וזן כל העולמות. ועליו כתוב אמרו צדיק וגו'. וכתוב טוב ה' וגו'. פירוש, בעת שיסוד דז\"א נוסע מהבינה, כנ\"ל בדיבור הסמוך, נבחן היסוד לשביעי, כלומר לשביעי מבינה. וז\"ש \u0003כלהו אחרנין בשביעאה קיימי,\u0004 דהיינו בהיסוד שהוא ספירה שביעית מהבינה. ועליו לבדו העולם עומד כדברי ר' יצחק."]],[[0,"","וַיְהִי כְּבוֹא אַבְרָם מִצְרָיְמָה וַיִּרְאוּ הַמִּצְרִים אֶת הָאִשָּׁה כִּי יָפָה הִוא מְאֹד. אָמַר רַבִּי יְהוּדָה, הִכְנִיס אוֹתָהּ בְּתֵבָה, וּפָתְחוּ אוֹתָהּ לָקַחַת מִמֶּנָּה מֶכֶס. כֵּיוָן שֶׁנִּפְתַּח, הָיָה אוֹר כְּאוֹר הַשֶּׁמֶשׁ. זֶהוּ שֶׁכָּתוּב כִּי יָפָה הִוא מְאֹד."],[1,"","מַה זֶּה מְאֹד? אֶלָּא שֶׁרָאוּ בַּתֵּבָה דְּמוּת (נ\"א: אור) אַחֶרֶת. הוֹצִיאוּ אוֹתָהּ וְרָאוּ אוֹתָהּ כְּבַתְּחִלָּה. זֶהוּ שֶׁכָּתוּב וַיִּרְאוּ אֹתָהּ שָׂרֵי פַרְעֹה. כֵּיוָן שֶׁכָּתוּב וַיִּרְאוּ הַמִּצְרִים אֶת הָאִשָּׁה, מַה זֶּה וַיִּרְאוּ אֹתָהּ שָׂרֵי פַרְעֹה? אֶלָּא שֶׁהוֹצִיאוּ אוֹתָהּ וְרָאוּ אוֹתָהּ כְּבַתְּחִלָּה, וְאָז וַיְהַלֲלוּ אֹתָהּ אֶל פַּרְעֹה וְגוֹ'."],[2,"","אָמַר רַבִּי יִצְחָק, אוֹי לְאוֹתָם רִשְׁעֵי הָעוֹלָם שֶׁלֹּא יוֹדְעִים וְלֹא מַשְׁגִּיחִים בְּמַעֲשֵׂי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהֵם לֹא מִסְתַּכְּלִים (בכל) שֶׁכָּל מַה שֶּׁיֵּשׁ בָּעוֹלָם הוּא מֵעִם הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא יוֹדֵעַ בַּתְּחִלָּה מַה שֶּׁיִּהְיֶה בַּסּוֹף, שֶׁכָּתוּב (ישעיה מו) מַגִּיד מֵרֵאשִׁית אַחֲרִית. וְהוּא צוֹפֶה וְעוֹשֶׂה מַעֲשִׂים בָּרִאשׁוֹנָה כְּדֵי לְהַעֲלוֹתָם לְאַחַר יָמִים."],[3,"","בֹּא רְאֵה, אִלְמָלֵא שֶׁנִּטְּלָה שָׂרַי לְפַרְעֹה, הוּא לֹא הָיָה מֻלְקֶה. וְהַהַלְקָאָה הַזּוֹ גָּרְמָה הַלְקָאָה לְאַחַר מִכֵּן שֶׁיִּלְקוּ מִצְרַיִם בִּנְגָעִים גְּדוֹלִים. כָּתוּב כָּאן נְגָעִים גְּדלִים, וְכָתוּב שָׁם (דברים ו) וַיִּתֵּן ה' אוֹתֹת וּמֹפְתִים גְּדלִים וְרָעִים בְּמִצְרַיִם. מַה לְּהַלָּן עֶשֶׂר מַכּוֹת - אַף כָּאן עֶשֶׂר מַכּוֹת. כְּמוֹ שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא נִסִּים וּגְבוּרוֹת לְיִשְׂרָאֵל בַּלַּיְלָה - אַף כָּאן עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְשָׂרָה נִסִּים וּגְבוּרוֹת בַּלַּיְלָה."],[4,"","רַבִּי יוֹסֵי פָּתַח וְאָמַר, (תהלים ג) וְאַתָּה ה' מָגֵן בַּעֲדִי כְּבוֹדִי וּמֵרִים רֹאשִׁי. אָמַר דָּוִד, אַף עַל גַּב שֶׁכָּל בְּנֵי הָעוֹלָם יָבוֹאוּ לַעֲרֹךְ עִמִּי קְרָב - וְאַתָּה ה' מָגֵן בַּעֲדִי. בּא רְאֵה, כָּתוּב מָגֵן בַּעֲדִי. אָמַר דָּוִד לַקָּדוֹשׁ-בָּרוּךְ-הוּא: רִבּוֹנוֹ שֶׁל עוֹלָם, מִפְּנֵי מָה לֹא עוֹשִׂים בִּי חֲתִימָה שֶׁל בְּרָכָה כְּמוֹ שֶׁחוֹתְמִים בְּרָכָה בְּאַבְרָהָם, שֶׁכָּתוּב אָנֹכִי מָגֵן לָךְ, וְאוֹמְרִים מָגֵן אַבְרָהָם?"],[5,"","אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְדָוִד: אַבְרָהָם כְּבָר בְּחַנְתִּיו וּצְרַפְתִּיו, וְעוֹמֵד לְפָנַי בְּקִיּוּם שָׁלֵם. אָמַר לוֹ דָּוִד: אִם כָּךְ, (שם כו) בְּחָנֵנִי ה' וְנַסֵּנִי צָרְפָה כִלְיוֹתַי וְלִבִּי. כֵּיוָן שֶׁעָשָׂה אוֹתוֹ הַדָּבָר שֶׁל בַּת שֶׁבַע, נִזְכַּר דָּוִד לְפָנָיו עַל מַה שֶּׁאָמַר. אָמַר (שם יז) בָּחַנְתָּ לִבִּי פָּקַדְתָּ לַּיְלָה צְרַפְתַּנִי בַל תִּמְצָא זַמֹּתִי בַּל יַעֲבָר פִּי."],[6,"","אָמַר, אֲנִי אָמַרְתִּי בְּחָנֵנִי ה' וְנַסֵּנִי, וְאַתָּה בָּחַנְתָּ לִבִּי. אֲנִי אָמַרְתִּי צָרְפָה כִלְיוֹתַי, וְאַתָּה צְרַפְתַּנִי בַל תִּמְצָא, לֹא מָצָאתָ אוֹתִי כָּרָאוּי. זַמֹּתִי בַּל יַעֲבָר פִּי - מִי יִתֵּן וְהַדָּבָר הַזֶּה שֶׁחָשַׁבְתִּי, שֶׁלֹּא יַעֲבֹר אֶת פִּי."],[7,"","וְעִם כָּל זֶה חוֹתְמִים בּוֹ הַבְּרָכָה, שֶׁאָנוּ אוֹמְרִים מָגֵן דָּוִד. וּמִשּׁוּם כָּךְ אָמַר דָּוִד, וְאַתָּה ה' מָגֵן בַּעֲדִי כְּבוֹדִי וּמֵרִים רֹאשִׁי. (וזה) וַדַּאי דַּרְגָּה זוֹ הַכָּבוֹד שֶׁלִּי שֶׁאֲנִי מִתְעַטֵּר בּוֹ."],[8,"","וַיְצַו עָלָיו פַּרְעֹה אֲנָשִׁים וַיְשַׁלְּחוּ אֹתוֹ. בֹּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא מָגֵן לַצַּדִּיקִים שֶׁלֹּא יִשְׁלְטוּ בָהֶם בְּנֵי אָדָם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הֵגֵן עַל אַבְרָהָם שֶׁלֹּא יִשְׁלְטוּ בוֹ וּבְאִשְׁתּוֹ."],[9,"","בֹּא רְאֵה, הַשְּׁכִינָה לֹא זָזָה מִשָּׂרָה כָּל הַלַּיְלָה הַהוּא. בָּא פַּרְעֹה לִקְרַב אֵלֶיהָ - בָּא הַמַּלְאָךְ וְהִלְקָה אוֹתוֹ. כָּל פַּעַם שֶׁאָמְרָה שָׂרָה הַלְקֵה - הָיָה מַלְקֶה. וְאַבְרָהָם הָיָה מַחֲזִיק בְּרִבּוֹנוֹ, שֶׁהֲרֵי עַל שָׂרָה לֹא יָכְלוּ לִשְׁלֹט עָלֶיהָ. זֶהוּ שֶׁכָּתוּב (משלי כח) וְצַדִּיקִים כִּכְפִיר יִבְטָח. וְכָאן הַנִּסָּיוֹן שֶׁלֹּא הִרְהֵר אַחַר הַקָּדוֹשׁ בָּרוּךְ הוּא."],[10,"","אָמַר רַבִּי יִצְחָק, בֹּא רְאֵה שֶׁמִּשּׁוּם כָּךְ לֹא צִוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא לָרֶדֶת לְמִצְרַיִם, אֶלָּא הוּא עַצְמוֹ מֵעַצְמוֹ יָרַד, כְּדֵי שֶׁלֹּא יִהְיֶה פִּתְחוֹן פֶּה לִבְנֵי הָעוֹלָם שֶׁאָמַר לוֹ כֵּן, וְאַחַר כָּךְ הִצְטַעֵר עַל אִשְׁתּוֹ."],[11,"","רַבִּי יִצְחָק פָּתַח וְאָמַר, (תהלים צב) צַדִּיק כַּתָּמָר יִפְרָח כְּאֶרֶז בַּלְּבָנוֹן יִשְׂגֶּה. צַדִּיק כַּתָּמָר יִפְרָח, מִפְּנֵי מָה הִקִּישׁ צַדִּיק לְתָמָר? מַה תָּמָר כֵּיוָן שֶׁגּוֹזְרִים אוֹתוֹ לֹא עוֹלֶה עַד זְמַן רַב - אַף כָּךְ צַדִּיק, כֵּיוָן שֶׁאָבַד מִן הָעוֹלָם, לֹא עוֹלֶה אַחֵר תַּחְתָּיו עַד זְמַן רַב. כְּאֶרֶז בַּלְּבָנוֹן יִשְׂגֶּה - אַף כָּךְ גַּם."],[12,"","כַּתָּמָר יִפְרָח - מַה תָּמָר לֹא עוֹלֶה אֶלָּא זָכָר וּנְקֵבָה, אַף כָּךְ הַצַּדִּיק לֹא עוֹלֶה אֶלָּא זָכָר וּנְקֵבָה. הַזָּכָר צַדִּיק וְהַנְּקֵבָה צַדֶּקֶת, כְּמוֹ שֶׁאַבְרָהָם וְשָׂרָה."],[13,"","כְּאֶרֶז בַּלְּבָנוֹן יִשְׂגֶּה - מָה הָאֶרֶז בַּלְּבָנוֹן עֶלְיוֹן עַל הַכֹּל וְהַכֹּל יוֹשְׁבִים תַּחְתָּיו - אַף כָּךְ הַצַּדִּיק הוּא עֶלְיוֹן עַל הַכֹּל וְהַכֹּל יוֹשְׁבִים תַּחְתָּיו. וְהָעוֹלָם אֵינוֹ עוֹמֵד אֶלָּא עַל צַדִּיק אֶחָד, שֶׁכָּתוּב (משלי י) וְצַדִּיק יְסוֹד עוֹלָם. וְעָלָיו הָעוֹלָם עוֹמֵד, וּבִגְלָלוֹ נִסְמָךְ, וְעָלָיו נִשְׁתָּל."],[14,"","רַבִּי יְהוּדָה אָמַר, וַהֲרֵי שָׁנִינוּ שֶׁעַל שִׁבְעָה עַמּוּדִים הָעוֹלָם עוֹמֵד, כַּכָּתוּב (שם ט) חָצְבָה עַמּוּדֶיהָ שִׁבְעָה. אָמַר לוֹ רַבִּי יוֹסֵי, כָּךְ הוּא וַדַּאי, אֲבָל (כאן) כָּל הָאֲחֵרִים בַּשְּׁבִיעִי הֵם עוֹמְדִים, שֶׁהוּא סֶמֶךְ שֶׁל הָעוֹלָם, וְהוּא צַדִּיק, וְזֶה מַשְׁקֶה (את העולם) וּמַרְוֶה אֶת הָעוֹלָם (מן הכל) וְזָן לַכֹּל, וְעָלָיו כָּתוּב (ישעיה ג) אִמְרוּ צַדִּיק כִּי טוֹב כִּי פְרִי מַעַלְלֵיהֶם יֹאכֵלוּ, וְכָתוּב (תהלים קמה) טוֹב ה' לַכֹּל וְרַחֲמָיו עַל כָּל מַעֲשָׂיו."]]],[["אָמַר רַבִּי יִצְחָק, הָא כְּתִיב, (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן. דָּא הוּא סָמְכָא דְעָלְמָא קָאִים עֲלֵיהּ, וְאִיהוּ אַשְׁקֵי לְגִנְתָא (דעדן) וְגִנְתָא אִשְׁתַּקֵּי מִנֵּיהּ וּמִנֵּיהּ עֲבִידָא פֵּירִין. וְכֻלְהוּ פֵּירִין פָּרְחִין בְּעָלְמָא וְאִנּוּן קִיּוּמָא דְעָלְמָא קִיּוּמָא דְאוֹרַיְיתָא, וּמַאן נִינְהוּ, נִשְׁמַתְהוֹן דְּצַדִּיקַיָיא דְּאִנּוּן פְּרִי עוֹבָדוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא. וּבְגִין כָּךְ בְּכָל לֵילְיָא וְלֵילְיָא נִשְׁמַתְהוֹן דְּצַדִּיקַיָיא סָלְקָן.","וְכַד אִתְפְּלַג לֵילְיָא קוּדְשָׁא בְּרִיךְ הוּא אָתֵי לְגִנְתָא דְעֵדֶן לְאִשְׁתַּעְשְׁעָא בְּהוּ. בְּמַאן. אָמַר רַבִּי יוֹסֵי בְּכֻלְהוּ, בֵּין אִנּוּן דִּמְדוֹרֵיהוֹן בְּהַהוּא עָלְמָא, בֵּין אִנּוּן דְּיָתְבֵי בִּמְדוֹרֵיהוֹן בְּהַאי עָלְמָא, בְּכֻלְהוּ מִשְׁתַּעֲשַׁע בְּהוּ קוּדְשָׁא בְּרִיךְ הוּא בְּפַלְגּוּת לֵילְיָא.","תָּא חֲזֵי, עָלְמָא דִלְעֵילָא אִצְטְרִיךְ לְאִתְעֲרוּתָא דְעָלְמָא תַּתָּאָה, וְכַד נִשְׁמַתְהוֹן דְּצַדִּיקַיָיא נָפְקֵי מֵהַאי עָלְמָא וְסָלְקֵי לְעֵילָא כֻּלְהוּ מִתְלַבְּשֵׁי בִּנְהוֹרָא דִלְעֵילָא בְּדִיוּקְנָא יְקָר, וּבְהוּ קוּדְשָׁא בְּרִיךְ הוּא מִשְׁתַּעֲשַׁע וְתָאִיב לוֹן דְּאִינְהוּ פְּרִי עוֹבָדוֹי, וְעַל דָּא אִקְרוּן יִשְׂרָאֵל דְּאִית לוֹן נִשְׁמָתִין קַדִּישִׁין בְּנִין לְקוּדְשָׁא בְּרִיךְ הוּא, כְּמָא דְאַתְּ אָמֵר (דברים י״ד:א׳) בָּנִים אַתֶּם לַיְיָ אֱלֹהֵיכֶם, בָּנִים וַדַּאי אִיבָּא דְּעוֹבָדוֹי.","אָמַר רַבִּי יֵיסָא וְאֲפִילּוּ אִנּוּן דִּבְהַאי עָלְמָא (דארעא), הֵיאַךְ. אָמַר לֵיהּ בְּגִין דִּי בְּפַלְגוּת לֵילְיָא כָּל אִנּוּן זַכָּאֵי קְשׁוֹט כֻּלְהוּ מִתְעָרֵי לְמִקְרֵי בְּאוֹרַיְיתָא וּלְמִשְׁמַע תּוּשְׁבְּחָן דְּאוֹרַיְיתָא, וְהָא אִתְּמָר דְּקוּדְשָׁא בְּרִיךְ הוּא וְכָל אִנּוּן צַדִּיקַיָא דִּבְגוֹ גִנְתָא דְעֵדֶן כֻּלְהוּ צַיְיתִין לְקָלֵיהוֹן, וְחוּטָא דְחֶסֶד אִתְמְשַׁךְ עֲלַיְיהוּ בִּימָמָא דִּכְתִיב, (תהילים מ״ב:ט׳) יוֹמָם יְצַוֶּה יְיָ חַסְדּוֹ וּבַלַּיְלָה שִׁירֹה עִמִּי.","וְעַל דָּא תּוּשְׁבְּחָן דְּסָלְקִין בְּלֵילְיָא קַמֵּיהּ דָּא תּוּשְׁבַּחְתָּא שְׁלִים. תָּא חֲזֵי, בְּשַׁעֲתָא דְיִשְׂרָאֵל הֲווּ סְגִירִין בְּבָתֵּיהוֹן כַּד קָטַל קוּדְשָׁא בְּרִיךְ הוּא בְּכוֹרֵיהוֹן דְּמִצְרָאֵי, הֲווּ אֲמָרֵי הֲלֵילָא וְתֻשְׁבְּחָן קַמֵּיהּ.","תָּא חֲזֵי, דְּדָוִד מַלְכָּא הֲוָה קָם בְּפַלְגוּת לֵילְיָא, דְּאִי תֵימָא דְּהֲוָה יָתִיב אוֹ שָׁכִיב בְּעַרְסֵיהּ וְהֲוָה אָמַר שִׁירִין וְתוּשְׁבְּחָן, לָא, אֶלָּא כְּמָה דִכְתִיב (תהילים קי״ט:ס״ב) חֲצוֹת לַיְלָה אָקוּם לְהוֹדוֹת לְךָ. אָקוּם וַדַּאי בַּעֲמִידָה לְאִתְעַסְּקָא בְּשִׁירִין וְתוּשְׁבְּחָן דְּאוֹרַיְיתָא.","וּבְגִין כָּךְ דָּוִד מַלְכָּא חַי לְעָלְמִין, וְאֲפִילּוּ בְּיוֹמֵי מַלְכָּא מְשִׁיחָא אִיהוּ מַלְכָּא. דְּהָא תְּנַן מַלְכָּא מְשִׁיחָא אִי מִן חַיָּיא הוּא דָּוִד שְׁמֵיהּ וְאִי מִן מֵתַיָיא הוּא דָּוִד שְׁמֵיהּ, וְאִיהוּ הֲוָה אִתְעַר בְּצַפְרָא עַד לָא יֵיתֵי דִּכְתִיב, (תהילים נ״ז:ט׳) עוּרָה כְבוֹדִי עוּרָה הַנֵּבֶל וְכִנּוֹר אָעִירָה שָׁחַר.","תָּא חֲזֵי, כָּל הַהוּא לֵילְיָא דְּשָׂרָה הֲוַת לְגַבֵּיהּ דְּפַרְעֹה אָתוּ מַלְאֲכֵי עִלָּאֵי לְזַמְרָא לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא בְּשִׁירִין וְתוּשְׁבְּחָן, אָמַר לְהוּ קוּדְשָׁא בְּרִיךְ הוּא כֻּלְּכוּ זִילוּ וְעֲבִידוּ מַכְתְּשִׁין רַבְרְבִין בְּמִצְרַיִם, רְשִׁימוּ לְמַאן דְּאֲנָא זַמִּין לְמֶעְבַּד לְבָתַר, (דא) מַה כְּתִיב וַיְנַגַּע יְיָ אֶת פַּרְעֹה נְגָעִים גְּדוֹלִים וְגו'.","תָּא חֲזֵי, מַה כְּתִיב וַיִּקְרָא פַּרְעֹה לְאַבְרָם וְגו'. מְנָא הֲוָה יָדַע, דְּהָא לָא כְּתִיב הָכָא כְּמָה דְּאִתְּמָר בַּאֲבִימֶלֶךְ דִּכְתִיב וְעַתָּה הָשֵׁב אֵשֶׁת הָאִישׁ כִּי נָבִיא הוּא וְגו', וְהָכָא לָא אָמַר לֵיהּ מִדִּי.","אָמַר רַבִּי יִצְחָק הָא כְּתִיב עַל דְּבַר שָׂרַי אֵשֶׁת אַבְרָם. דְּהָכִי הֲווּ אָמְרֵי לֵיהּ, עַל דְּבַר שָׂרַי אֵשֶׁת אַבְרָם. דְּהָא לָא הֲוָה מְמַלֵּיל עִמֵּיהּ כְּמָה דִּמְמַלֵּיל בַּאֲבִימֶלֶךְ, אֶלָּא בְּמִלָּה דָא אִתְּמָר וְלָא יַתִּיר, מַכְתְּשָׁא דָא עַל דְּבַר שָׂרַי אֵשֶׁת אַבְרָם אִיהִי, וְלָא הֲוָה מַלִּיל (דא) עִמֵּיהּ, כְּדֵין יָדַע (הוא) דְּהָא אִתְּתֵיהּ דְּאַבְרָהָם אִיהִי, מִיָּד וַיִּקְרָא פַּרְעֹה לְאַבְרָם וַיֹּאמֶר וְגו'.","וַיְצַו עָלָיו פַּרְעֹה אֲנָשִׁים. לָמָּה בְּגִין דְּלָא יִקְרַב בַּר נַשׁ בְּהוּ לְאַבְאָשָׁא לוֹן. וַיְשַׁלְּחוּ אוֹתוֹ, לְוָיָיה עֲבָדוּ לֵיהּ בְּכָל אַרְעָא דְמִצְרַיִם. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא הָכִי אַנְתְּ זַמִּין לְמֶעְבַּד לִבְנוֹי אַתְּ תּוֹזִיף לוֹן מֵאַרְעָךְ דִּכְתִיב, (שמות י״ג:י״ז) וַיְהִי בְּשַׁלַּח פַּרְעֹה אֶת הָעָם דְּאוֹזִיף לוֹן מִכָּל אַרְעֵיהּ.","אָמַר רַבִּי אַבָּא כָּל כָּךְ לָמָּה אִזְדַּמֵּן לֵיהּ לְאַבְרָהָם וּלְמַאי אִיצְטְרִיךְ, אֶלָּא בְּגִין לְגַדְּלָא שְׁמֵיהּ דְּאַבְרָהָם וְשָׂרָה בְּעָלְמָא, דְּאָפִילּוּ בְּמִצְרַיִם דְּאִנּוּן חֳרָשֵׁי עָלְמָא וְלָא הֲוָה יָכִיל בַּר נָשׁ לְאִשְׁתְּזִיב מִנַּיְיהוּ. אִתְגַּדַּל אַבְרָהָם וְאִסְתַּלִּיק לְעֵילָא הֲדָא הוּא דִכְתִיב וַיַּעַל אַבְרָם מִמִּצְרַיִם, לְאָן אֲתַר הַנֶּגְבָּה. (ומאי הוא ואשתו וכל אשר לו, אלא לאודעא דלא גזלו מניה מדעם מאנון מתנן דיהבו ליה בדיל שרה דתהא למלכא)"],[[0,"אמר ר' יצחק וכו':","אר\"י, הרי כתוב ונהר יוצא מעדן להשקות את הגן, שהוא יסוד דז\"א היוצא מבינה שחזרה לחכמה, הנקראת עדן. וזה הוא העמוד שהעולם עומד עליו, והוא המשקה להגן, שהיא הנוקבא, והגן מושקה ממנו, ועושה ממנו פירות, שהם נשמות בני אדם. וכל הפירות פורחים בעולם, שהיא הנוקבא, והן קיום העולם וקיום התורה. ושואל, מי המה פירות האלו. ואומר, הם נשמות הצדיקים, שהן פרי מעשיו של הקב\"ה."],[1,"ובגין כך בכל ליליא וכו':","ומשום זה, משום שהנשמות הן תולדות הקב\"ה, בכל לילה ולילה עולות נשמות הצדיקים לגן עדן, וכשנחלק הלילה הקב\"ה בא לגן עדן להשתעשע בהן. ושואל, במי. במי הוא בא להשתעשע, אם בנשמות החיים אם בנשמות הנפטרים. אמר רבי יוסי בכולן, הן באלו שמשכנן בעולם האמת, הן באלו שמשכנן בעולם הזה, בכולן, הקב\"ה משתעשע בהם בחצות לילה בגן עדן. פירוש. לא לבד נשמות הנפטרים עולות בכל לילה למ\"ן, אלא אפילו נשמות החיים עולות ג\"כ למ\"ן ולשעשועים בכל לילה. כמו שמבאר לפנינו להלן."],[2,"ת\"ח עלמא דלעילא וכו':","בוא וראה, עולם העליון, נצרך להתעוררות מעולם התחתון. וכאשר נשמות הצדיקים יוצאות מעולם הזה, ועולות למעלה לגן עדן, מתלבשות כולן באור העליון בצורה יקרה. ובהן הקב\"ה משתעשע ומשתוקק אליהן, כי הן פרי מעשיו. ועל כן נקראים ישראל בנים להקב\"ה, משום שיש להם נשמות קדושות, כמו שאתה אומר, בנים אתם לה' אלקיכם, כי הנשמות הן בנים ודאי, פרי מעשיו של הקב\"ה."],[2,"","פירוש. \u0003עולם העליון,\u0004 היינו הנוקבא, הנקראת \u0003לילה\u0004 אשר שלמותה מצד קו השמאל, נגלית מחצות לילה ואילך שה\"ס מחזה ולמטה של הנוקבא. בסו\"ה ותקם בעוד לילה. אמנם להיות הארת השמאל בחינת חכמה בלי חסדים, הוא עוד לילה, כי אור החכמה אינו יכול להאיר בלי לבוש של חסדים. וז\"ש, \u0003עלמא דלעילא אצטריך לאתערותא דעלמא תתאה,\u0004 שעולם העליון שהיא הנוקבא, שהוא בבחינת חכמה בלי חסדים ואינו יכול להאיר הוא נצרך להתעוררות, דהיינו להעלאת מ\"ן, מעולם התחתון. דהיינו מעולם הזה, מהנשמות, שיעלו מ\"ן אליה, שעל מ\"ן הללו יוצאת קומת חסדים, ומגלה את קו האמצעי, שה\"ס הקב\"ה המכריע ומלביש החכמה באור החסדים. (כנ\"ל דף ג' ד\"ה ת\"ח ע\"ש). וז\"ש, \u0003וכד נשמתהון דצדיקיא נפקי מהאי עלמא וסלקי לעילא,\u0004 כשהנשמות יוצאות מעוה\"ז ועולות למעלה להנוקבא, הן מעלות מ\"ן ומגלים בה את קו האמצעי, שה\"ס הקב\"ה, המכריע ומלביש החכמה בחסדים, שלבוש הזה דחסדים מכונה \u0003לבוש יקר,\u0004 (כנ\"ל בהק' הזהר דף כ\"ג ד\"ה וז\"ש בעא ע\"ש). וז\"ש \u0003כלהו מתלבשי בנהורא דלעילא בדיוקנא יקר,\u0004 כי שיעור האור שהתחתון גרם בעליון, זוכה בו גם התחתון, וע\"כ כיון שהנשמות גרמו \u0003לבוש יקר\u0004 דחסדים להנוקבא, זוכות בו גם הן, ומתלבשות \u0003בדיוקנא יקר\u0004 הזה. וז\"ש \u0003ובהו הקב\"ה משתעשע ותאיב לון\u0004 כי הקב\"ה ה\"ס קו אמצעי, שעל ידי העלאת מ\"ן של הנשמות הוא בא להנוקבא, שה\"ס גן עדן, ומשלים אותה בקו האמצעי, כנ\"ל. וע\"כ משתעשע עם הנשמות ההם, ומשתוקק אליהם. \u0003דאינון פרי עובדוי,\u0004 שהן תולדות הקב\"ה. (כנ\"ל דף ט' אות י\"ג). וע\"כ נקראים ישראל בנים כמ\"ש בנים אתם לה' אלקיכם."],[3,"אמר ר' ייסא וכו':","אר\"י ואפילו באלו הנשמות שבעוה\"ז אתה אומר הוא משתעשע, איך הוא זה. אמר לו. משום, שבחצות לילה, כל אלו צדיקי אמת מתעוררים כולם לקרות בתורה ולהשמיע תשבחות של התורה. ולמדנו, שהקב\"ה וכל אלו הצדיקים שבתוך גן העדן, כולם מקשיבים לקולותיהם, וחוט של חסד נמשך עליהם ביום. כלומר שע\"י המ\"ן שהם מעלים על ידי התורה והתשבחות, נמשך קו האמצעי אל הנוקבא, שה\"ס אור החסדים, כנ\"ל בסמוך. ולפי שהם גרמו לאור הזה, זוכים בו גם הם. וז\"ש \u0003וחוטא דחסד אתמשך עלייהו ביממא.\u0004 דהיינו אותו השיעור שגרמו להנוקבא. וזסו\"ה יומם יצוה ה' חסדו ובלילה שירה עמי. שבשביל השירה שבלילה זוכים לחסדו ביום."],[4,"ועל דא תושבחן וכו':","ועל כן, התשבחות העולות לפני הקב\"ה בלילה, הן תשבחות שלמות. בוא וראה בשעה שישראל היו סגורים בבתיהם, כשהקב\"ה הרג את בכורי מצרים, היו אומרים לפני הקב\"ה הלל ותשבחות."],[5,"ת\"ח דדוד מלכא וכו':","בוא וראה, דוד המלך היה קם בחצות לילה. ואם תאמר שהיה יושב או שוכב במטה, ואומר שירות ותשבחות. לא. אלא כמ\"ש, חצות לילה אקום להודות לך. אקום ודאי, בעמידה, היה עוסק בשירות ותשבחות של התורה. פירוש. מוחין דנה\"י באור הנפש, מכונים \u0003שכיבה,\u0004 שאין להשוכב שום קומה. מוחין דו\"ק מכונים \u0003ישיבה,\u0004 כי היושב, נמצאים נה\"י שלו מקופלים תחתיו, והוא חסר אז נה\"י דכלים וג\"ר דאורות. מוחין דג\"ר מכונים \u0003עמידה,\u0004 כי אז כל ג' חלקי קומת האדם זקופים שהם: ראש, תוך, וסוף. וז\"ש \u0003דאי תימא דהוה יתיב,\u0004 דהיינו ששיבח להקב\"ה במוחין דו\"ק הנבחנים \u0003לישיבה. או שכיב בערסיה,\u0004 או ששיבח במוחין דנה\"י, הנבחנים \u0003לשכיבה, אלא כמה דכתיב וכו',\u0004 אקום \u0003ודאי בעמידה לאתעסקא בשירין וכו'.\u0004 דהיינו במוחין דג\"ר הנבחנים \u0003לעמידה.\u0004 ובמוחין האלו היה עוסק בשירות ותשבחות לפני הקב\"ה, ששיעור קומתו גדלה בכל הגדלות."],[6,"ובגין כך דוד מלכא וכו':","ומשום זה, משום שעסק בשירות ותשבחות במוחין דג\"ר שה\"ס עמידה, וה\"ס אור החיה, דוד המלך חי לעולם. ואפילו בימות המלך המשיח, הוא המלך. כי למדנו, אשר מלך המשיח, אם הוא יהיה מבין החיים. דוד שמו. ואם הוא יהיה מנשמות הנפטרים שיעמדו לתחיה, דוד שמו. והוא היה מעורר השחר מטרם שיבא, שכתוב עורה כבודי עורה הנבל וכנור אעירה שחר. שהיה קם לעסוק בתורה תמיד, מטרם שיאיר השחר."],[7,"ת\"ח כל ההוא ליליא וכו':","בוא וראה, כל אותו הלילה, ששרה היתה אצל פרעה, באו מלאכים העליונים לזמר לפני הקב\"ה בשירות ותשבחות. אמר להם הקב\"ה: לכו כלכם ונגעו נגעים גדולים במצרים, לרשימה וסימן, למה שאני עתיד לעשות לאחר כך. מה כתוב. וינגע ה' את פרעה נגעים גדולים וגו'."],[8,"ת\"ח מה כתיב וכו':","בוא וראה מה כתוב. ויקרא פרעה לאברם. ושואל מאין ידע ששרה אשת אברם היא, שהרי לא כתוב כאן כמו שנאמר באבימלך, שכתוב, ועתה השב אשת האיש וגו', וכאן לא אמר הקב\"ה לפרעה כלום."],[9,"אמר רבי יצחק.","הרי כתוב, על דבר שרי אשת אברם. כי כן היו המלאכים אומרים, \u0003על דבר שרי אשת אברם.\u0004 כי לא דבר עמו הקב\"ה כמו שדבר עם אבימלך, אלא מלות אלו נאמרו לו ולא יותר: \u0003נגע זה על דבר שרי אשת אברם.\u0004 וגם זה לא דבר עמו הקב\"ה, אלא המלאכים המכים אמרו זה, אז ידע כי היא אשת אברם. מיד ויקרא פרעה לאברם וגו'."],[10,"ויצו עליו פרעה אנשים וכו':","ושואל. למה עשה זה. ואומר כדי שלא יקרב אדם להרע להם. \u0003וישלחו אותו,\u0004 לוייה עשו לו, דהיינו שליוו אותו, בכל ארץ מצרים אמר לו הקב\"ה, לפרעה, כן אתה עתיד לעשות לבניו, אתה תלוה אותם מארצך, שכתוב, ויהי בשלח פרעה את העם: שליווה אותם מכל ארצו."],[11,"א\"ר אבא וכו':","אר\"א למה נזדמן לו לאברהם כל כך, ולמה נצרך כל זה. ואומר, אלא שהוא כדי להגדיל שמו של אברהם ושרה בעולם. שאפילו במצרים, שהמה מכשפי העולם שאיש לא יכול להציל עצמו מהם, גם שם נתגדל אברהם ונתעלה למעלה. וזהו שכתוב ויעל אברם ממצרים, לאיזה מקום, \u0003הנגבה,\u0004 דהיינו למדרגתו שהיה בה בתחילה."]],[[0,"","אָמַר רַבִּי יִצְחָק, הֲרֵי כָּתוּב (בראשית ב) וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן. זֶה הוּא הָעַמּוּד שֶׁהָעוֹלָם עוֹמֵד עָלָיו וְהוּא מַשְׁקֶה לַגָּן (העדן), וְהַגָּן נִשְׁקֶה מִמֶּנּוּ, וּמִמֶּנּוּ עוֹשֶׂה פֵרוֹת. וְכָל הַפֵּרוֹת פּוֹרְחִים בָּעוֹלָם וְהֵם הַקִּיּוּם שֶׁל הָעוֹלָם, הַקִּיּוּם שֶׁל הַתּוֹרָה. וּמִי הֵם? נִשְׁמוֹת הַצַּדִּיקִים שֶׁהֵם פְּרִי מַעֲשָׂיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וּמִשּׁוּם כָּךְ בְּכָל לַיְלָה וְלַיְלָה נִשְׁמוֹת הַצַּדִּיקִים עוֹלוֹת."],[1,"","וּכְשֶׁנֶּחֱלָק הַלַּיְלָה, הַקָּדוֹשׁ בָּרוּךְ הוּא בָּא לְגַן הָעֵדֶן לְהִשְׁתַּעֲשֵׁעַ בָּהֶם. בְּמִי? אָמַר רַבִּי יוֹסֵי, בְּכֻלָּם. בֵּין אוֹתָם שֶׁמְּדוֹרָם בָּעוֹלָם הַהוּא, וּבֵין אוֹתָם שֶׁיּוֹשְׁבִים בִּמְדוֹרָם בָּעוֹלָם הַזֶּה, בְּכֻלָּם מִשְׁתַּעֲשֵׁעַ הַקָּדוֹשׁ בָּרוּךְ הוּא בַּחֲצוֹת הַלַּיְלָה."],[2,"","בֹּא רְאֵה, הָעוֹלָם שֶׁלְּמַעְלָה צָרִיךְ אֶת הִתְעוֹרְרוּתוֹ שֶׁל הָעוֹלָם הַתַּחְתּוֹן. וּכְשֶׁנִּשְׁמוֹת הַצַּדִּיקִים יוֹצְאוֹת מִן הָעוֹלָם הַזֶּה וְעוֹלוֹת לְמַעְלָה, כֻּלָּן מִתְלַבְּשׁוֹת בָּאוֹר שֶׁלְּמַעְלָה בִּדְמוּת נִכְבָּדָה, וּבָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּעֲשֵׁעַ וְתָאֵב לָהֶם, שֶׁהֵם פְּרִי מַעֲשָׂיו, וְעַל זֶה נִקְרְאוּ יִשְׂרָאֵל שֶׁיֵּשׁ לָהֶם נְשָׁמוֹת קְדוֹשׁוֹת בָּנִים לַקָּדוֹשׁ- בָּרוּךְ-הוּא, כְּמוֹ שֶׁנֶּאֱמַר (דברים יד) בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם. בָּנִים וַדַּאי, פְּרִי מַעֲשָׂיו."],[3,"","אָמַר רַבִּי יֵיסָא, אֲפִלּוּ אוֹתָם שֶׁבָּעוֹלָם הַזֶּה (של הארץ). אֵיךְ? אָמַר לוֹ, מִשּׁוּם שֶׁבַּחֲצוֹת הַלַּיְלָה כָּל אוֹתָם צַדִּיקֵי אֱמֶת, כֻּלָּם מִתְעוֹרְרִים לִקְרֹא בַתּוֹרָה וְלִשְׁמֹעַ אֶת תִּשְׁבְּחוֹת הַתּוֹרָה. וַהֲרֵי נִתְבָּאֵר שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא וְכָל אוֹתָם הַצַּדִּיקִים שֶׁבְּתוֹךְ גַּן הָעֵדֶן כֻּלָּם מַקְשִׁיבִים לְקוֹלָם, וְחוּט שֶׁל חֶסֶד נִמְשָׁךְ עֲלֵיהֶם בַּיּוֹם, שֶׁכָּתוּב (תהלים מב) יוֹמָם יְצַוֶּה ה' חַסְדּוֹ וּבַלַּיְלָה שִׁירֹה עִמִּי."],[4,"","וְעַל כֵּן הַתִּשְׁבָּחוֹת שֶׁעוֹלוֹת בַּלַּיְלָה לְפָנָיו, זוֹ תִשְׁבַּחַת שְׁלֵמָה. בּא רְאֵה, בְּשָׁעָה שֶׁיִּשְׂרָאֵל הָיוּ סְגוּרִים בְּבָתֵּיהֶם כְּשֶׁהָרַג הַקָּדוֹשׁ בָּרוּךְ הוּא בִּבְכוֹרֵי מִצְרַיִם, הָיוּ אוֹמְרִים הַלֵּל וְתִשְׁבָּחוֹת לְפָנָיו."],[5,"","בֹּא רְאֵה שֶׁדָּוִד הַמֶּלֶךְ הָיָה קָם בַּחֲצוֹת הַלַּיְלָה, שֶׁאִם תֹּאמַר שֶׁהָיָה יוֹשֵׁב אוֹ שׁוֹכֵב בְּמִטָּתוֹ וְהָיָה אוֹמֵר שִׁירוֹת וְתִשְׁבָּחוֹת - לֹא, אֶלָּא כְּמוֹ שֶׁכָּתוּב (שם קיט) חֲצוֹת לַיְלָה אָקוּם לְהוֹדוֹת לָךְ. אָקוּם וַדַּאי בַּעֲמִידָה לְהִתְעַסֵּק בְּשִׁירוֹת וְתִשְׁבָּחוֹת שֶׁל הַתּוֹרָה."],[6,"","וּמִשּׁוּם כָּךְ דָּוִד הַמֶּלֶךְ חַי לְעוֹלָמִים, וַאֲפִלּוּ בִּימֵי מֶלֶךְ הַמָּשִׁיחַ הוּא מֶלֶךְ. שֶׁהֲרֵי שָׁנִינוּ, מֶלֶךְ הַמָּשִׁיחַ, אִם מִן הַחַיִּים הוּא - דָּוִד שְׁמוֹ, וְאִם מִן הַמֵּתִים הוּא - דָּוִד שְׁמוֹ. וְהוּא הָיָה מִתְעוֹרֵר"],[7,"","בַּבֹּקֶר בְּטֶרֶם יָבא, שֶׁכָּתוּב (שם נז) עוּרָה כְבוֹדִי עוּרָה הַנֵּבֶל וְכִנּוֹר אָעִירָה שָּׁחַר. בֹּא רְאֵה, כָּל אוֹתוֹ הַלַּיְלָה שֶׁשָּׂרָה הָיְתָה אֵצֶל פַּרְעֹה, בָּאוּ הַמַּלְאָכִים הָעֶלְיוֹנִים לְזַמֵּר לַקָּדוֹשׁ-בָּרוּךְ- הוּא בְּשִׁירוֹת וְתִשְׁבָּחוֹת. אָמַר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא: כֻּלְּכֶם לְכוּ וַעֲשׂוּ מַכּוֹת גְּדוֹלוֹת בְּמִצְרַיִם, סִימָן לְמִי שֶׁאֲנִי עָתִיד לַעֲשׂוֹת אַחַר כָּךְ. זֶה מַה שֶּׁכָּתוּב וַיְנַגַּע ה' אֶת פַּרְעֹה נְגָעִים גְּדֹלִים וְגוֹ'"],[8,"","בֹּא רְאֵה מַה כָּתוּב, וַיִּקְרָא פַרְעֹה לְאַבְרָם וְגוֹ'. מִנַּיִן הָיָה יוֹדֵעַ, שֶׁהֲרֵי לֹא כָתוּב כָּאן כְּמוֹ שֶׁנֶּאֱמַר בַּאֲבִימֶלֶךְ, שֶׁכָּתוּב וְעַתָּה הָשֵׁב אֵשֶׁת הָאִישׁ כִּי נָבִיא הוּא וְגוֹ', וְכָאן לֹא אָמַר לוֹ דָּבָר?"],[9,"","אָמַר רַבִּי יִצְחָק, הֲרֵי כָּתוּב עַל דְּבַר שָׂרַי אֵשֶׁת אַבְרָם. שֶׁכָּךְ הָיוּ אוֹמְרִים לוֹ: עַל דְּבַר שָׂרַי אֵשֶׁת אַבְרָם. שֶׁהֲרֵי לֹא הָיָה מְדַבֵּר עִמּוֹ כְּמוֹ שֶׁמְּדַבֵּר עִם אֲבִימֶלֶךְ, אֶלָּא בְּדָבָר זֶה נִתְבָּאֵר וְלֹא יוֹתֵר: הַמַּכָּה הַזּוֹ הִיא עַל דְּבַר שָׂרַי אֵשֶׁת אַבְרָם. וְלֹא הָיָה מְדַבֵּר (זה) עִמּוֹ. אָז (הוא) יָדַע שֶׁזּוֹ אִשְׁתּוֹ שֶׁל אַבְרָהָם הִיא. מִיָּד - וַיִּקְרָא פַרְעֹה לְאַבְרָם וַיֹּאמֶר וְגוֹ'."],[10,"","וַיְצַו עָלָיו פַּרְעֹה אֲנָשִׁים, לָמָּה? כְּדֵי שֶׁלֹּא יִקְרַב אָדָם לָהֶם לְהָרַע לָהֶם. וַיְשַׁלְּחוּ אֹתוֹ, לְוָיָה עָשׂוּ לוֹ בְּכָל אֶרֶץ מִצְרַיִם. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: כָּךְ אַתָּה עָתִיד לַעֲשׂוֹת לְבָנָיו, אַתָּה תְלַוֶּה אוֹתָם מֵאַרְצְךְ, שֶׁכָּתוּב (שמות יג) וַיְהִי בְשַׁלַּח פַּרְעֹה אֶת הָעָם, שֶׁלִּוָּה אוֹתָם מִכָּל אַרְצוֹ."],[11,"","אָמַר רַבִּי אַבָּא, כָּל כָּךְ לָמָּה הִזְדַּמֵּן לְאַבְרָהָם וּלְמַה הִצְטָרֵךְ? אֶלָּא כְּדֵי לְגַדֵּל אֶת שְׁמָם שֶׁל אַבְרָהָם וְשָׂרָה בָּעוֹלָם, שֶׁאֲפִלּוּ בְּמִצְרַיִם שֶׁהֵם מְכַשְּׁפֵי הָעוֹלָם, וְלֹא יָכוֹל הָיָה אָדָם לְהִנָּצֵל מֵהֶם, הִתְגַּדֵּל אַבְרָהָם וְהִתְעַלָּה לְמַעְלָה. זֶהוּ שֶׁכָּתוּב וַיַּעַל אַבְרָם מִמִּצְרַיִם. לְאֵיזֶה מָקוֹם? הַנֶּגְבָּה (ומה זה הוא ואשתו וכל אשר לו? אלא להודיע שלא גזלו ממנו דבר מאותן מתנות שנתנו לו בשביל שרה שתהיה למלך)."]]],[["אָמַר רַבִּי שִׁמְעוֹן תָּא חֲזֵי, כֹּלָּא רָזָא דְחָכְמְתָא אִיהוּ, וְקָא רָמַז הָכָא בְּחָכְמְתָא וְדַרְגִּין דִּלְתַתָּא דְּקָא נָחִית אַבְרָהָם לְעוּמְקַיָּיא דִלְהוֹן וְיָדַע לוֹן, וְלָא אִתְדַּבָּק בְּהוּ, וְתָב לְקַמֵּי מָרֵיהּ.","וְלָא אִתְפַּתָּא בְּהוּ כְּאָדָם דְּכַד מָטָא לְהַהוּא דַרְגָא אִתְפַּתָּא בְּנָחָשׁ וְגָרִים מוֹתָא לְעָלְמָא. וְלָא אִתְפַּתָּא כְּנֹחַ דְּכַד נָחַת וּמָטָא לְהַהוּא דַרְגָּא מַה כְּתִיב, (בראשית ט׳:כ״א) וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגָּל בְּתוֹךְ אָהֳלֹה. אָהֳלֹה כְּתִיב בְּה\"א.","אֲבָל בְּאַבְרָהָם מַה כְּתִיב וַיַּעַל אַבְרָם מִמִּצְרַיִם. דְּסָלִיק וְלָא נָחִית, וְתָב לְאַתְרֵיהּ לְדַרְגָא עִלָּאָה דְּאִתְדַּבָּק בֵּיהּ בְּקַדְמִיתָא. וְעוֹבָדָא דָא הֲוָה, בְּגִין לְאַחֲזָאָה חָכְמָתָא דְּאִתְקַיָּים בְּקִיּוּמָא שְׁלִים כְּדְקָא חָזֵי לֵיהּ וְלָא אִתְפַּתָּא וְקָם בְּקִיּוּמָא וְתָב לְאַתְרֵיהּ. הַנֶּגְבָּה, דָּא דָרוֹם דַּרְגָּא עִלָּאָה דְּאִתְאֲחִיד בֵּיהּ בְּקַדְמִיתָא דִּכְתִיב הָלוֹךְ וְנָסוֹעַ הַנֶּגְבָּה. אוּף הָכָא הַנֶּגְבָּה, אֲתַר דְּאִתְדַבַּק בֵּיהּ בְּקַדְמִיתָא.","תָּא חֲזֵי, רָזָא דְמִלָּה, אִי אַבְרָם לָא יֵיחוּת לְמִצְרַיִם וְלָא יִצְטָרֵף תַּמָּן בְּקַדְמִיתָא. לָא יְהֵא חוּלַק עַדְבֵיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא. כְּגַוונָא דָא לִבְנוֹי כַּד בָּעָא קוּדְשָׁא בְּרִיךְ הוּא לְמֶעבַּד לֵיהּ (ד\"א לון) עַמָּא חָדָא עַמָּא שְׁלִים וּלְקָרְבָא לוֹן לְגַבֵּיהּ, אִי לָא נָחֲתוּ בְּקַדְמִיתָא לְמִצְרַיִם וְלָא יִצְטַרְפוּן תַּמָּן, לא הֲווּ עַמָּא יְחִידָא דִילֵיהּ.","(סא א) כְּגַוְונָא דָא אִי לָא אִתְיְיהִיבַת אַרְעָא קַדִּישָׁא לִכְנַעַן בְּקַדְמיתָא וְיִשְׁלוֹט בָּהּ לָא הֲות אַרְעָא חוּלְקֵיהּ וְעַדְבֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא. וכֹלָּא רָזָא חָדָא.","רַבִּי שִׁמְעוֹן הֲוָה אָזִיל בְּאָרְחָא, וְהֲוָה עִמֵּיהּ רַבִּי אֶלְעָזָר בְּרֵיהּ וְרַבִּי אַבָּא וְרַבִּי יְהוּדָה. עַד דְּהֲווּ אָזְלֵי, אָמַר רַבִּי שִׁמְעוֹן תָּוַוהְנָא הֵיךְ בְּנֵי עָלְמָא לָא מַשְׁגִּיחִין לְמִנְדַע מִלֵּי דְאוֹרַיְיתָא ועָל מָה קָיְימֵי. פָּתַח וְאָמַר, (ישעיהו כ״ו:ט׳) נַפְשִׁי אִוִּיתִיךָ בַּלַּיְלָה אַף רוּחִי בְּקִרְבִּי אֲשַׁחֲרֶךָּ, הַאי קְרָא אוּקְמוּהָ וְאוֹקִימְנָא לֵיהּ, אֲבָל תָּא חֲזִי, נַפְשָׁא דְּבַּר נָשׁ, כָּד (איהו) סָלִיק לְעַרְסֵיהּ, נָפְקַת מִנֵּיהּ וְסָלְקָא לְעֵילָא. וְאִי תֵימָא דְּכֻלְהוּ סָלְקָאן. לָאו כָּל חַד וְחַד חָמֵי אַפֵּי מַלְכָּא, אֶלָּא נַפְשָׁא סָלְקָא וְלָא אִשְׁתָּאַר בָּהּ בַּהֲדֵי גוּפָא בַּר חַד רְשִׁימוּ (נשימו) דְּקֻיסְטָא דְּחַיּוּתָא דְּלִבָּא.","וְנַפְשָׁא אָזְלָא וּבָעְיָא לְסָלְקָא. וְכַמָּה דַּרְגִּין לְדַרְגִּין לְסָלְקָא, שָׁטָאת וְהִיא אִתְעָרְעַת בְּהַנֵּי קוּמְרִין טְהִירִין דִּמְסָאֲבוּתָא. אִי הִיא דְּכִיאַת דְּלָא אִסְתָּאָבַת בִּימָמָא סָלְקָא לְעֵילָא. וְאִי לָאו דְּכִיאַת, אִסְתָּאֳבַת בֵּינַיְיהוּ וְאִתְדַּבְּקַת בְּהוּ וְלָא סָלְקָא יַתִּיר.","וְתַמָּן מוֹדָעֵי לָהּ מִלִּין וְאִיהוּ אִתְדַּבְּקַת מֵאִנּוּן מִלִּין דִּזְמַן קָרִיב. וּלְזִמְנִין דְּחַיְיכִין בָּהּ וּמוֹדָעִין לָהּ מִלִּין כְּדִיבִין. וּכְדֵין אָזְלָא כְּהַאי גַּוְונָא כָּל לֵילְיָא עַד דְּיִתְעַר בַּר נָשׁ וְתָאבַת לְאַתְרָהּ. זַכָּאִין אִנּוּן צַדִּיקַיָיא דְּגָלֵי לוֹן קוּדְשָׁא בְּרִיךְ הוּא רָזִין דִּילֵיהּ בְּחֶלְמָא בְּגִין דְּיִסְתַּמְּרוּן מִן דִּינָא. וַוי לְאִנּוּן חַיָיבֵי עָלְמָא דִּמְסָאֲבִין גַּרְמַיְיהוּ וְנַפְשַׁיְיהוּ.","תָּא חֲזֵי, אִנּוּן דְּלָא אִסְתָּאֲבוּ, כַּד סָלְקֵי בְּעַרְסַיְיהוּ, נַפְשָׁא סָלְקָא וְעָאלַת בֵּין כָּל הַנֵּי דַרְגִּין בְּקַדְמִיתָא וְסָלְקָא וְלָא אִתְדַּבְּקַת בְּהוּ. וּלְבָתַר אָזְלָא וְשָׁטָאת וְסָלְקָא כְּפוּם אוֹרְחָהּ.","הַהִיא נַפְשָׁא דְזָכָת לְסָלְקָא אִתְחֲזִיאַת קַמֵּיהּ דִּסְבַר אַפֵּי יוֹמִין וְאִתְדַּבְּקַת בִּרְעוּתָא לְאִתְחַזָּאָה בְּתִיאוּבְתָּא עִלָּאָה לְמֶחֱמֵי בְּנוֹעַם מַלְכָּא וּלְבַקְּרָא בְּהֵיכָלֵיהּ. וְדָא הוּא בַּר נָשׁ דְּאִית לֵיהּ חוּלָקָא תָּדִיר בְּעָלְמָא דְּאָתֵי.","וְדָא הִיא נַפְשָׁא דִּכְסִיפָא דִילָהּ כַּד סָלְקָא בְּקוּדְשָׁא בְּרִיךְ הוּא (תדיר), וְלָא אִתְדַבְּקַת בְּהַנֵּי זִינִין טְהִירִין אַחֲרָנִין, וְהִיא אָזְלַת בָּתַר זִינָא קַדִּישָׁא בְּאַתְרָא (ד\"א בתר אתרא) דְּנָפְקַת מִתַּמָּן. וּבְגִין כָּךְ כְּתִיב נַפְשִׁי אִוִּיתִיךָ בַּלָּיְלָה. בְּגִין לְמִרְדַּף בַּתְרָךְ וְלָא לְאִתְפַּתָּאָה בָּתַר זִינָא אָחֳרָא נוּכְרָאָה.","תָּא חֲזֵי, נַפְשִׁי דָּא נֶפֶשׁ דְּאִיהִי שָׁלְטָא בַּלַּיְלָה וּלְמִרְדַּף בָּתַר דַּרְגָּא. רוּחַ בַּיּוֹם, דִּכְתִיב נַפְשִׁי אִוִּיתִיךָ בַּלַּיְלָה, דָּא נֶפֶשׁ דְּאִיהִי שָׁלְטָא בַּלַּיְלָה. אַף רוּחִי בְּקִרְבִּי אֲשַׁחֲרֶךָּ. דָּא רוּחַ דְּאִיהוּ שָׁלְטָא בִּימָמָא."],[[0,"אמר ר' שמעון ת\"ח וכו':","אר\"ש בוא וראה. הכל סוד החכמה הוא. והכתוב מרמז כאן בבחינת החכמה ומדרגות שלמטה, דהיינו מדרגות המצרים שממשיכים החכמה מלמעלה למטה. (כנ\"ל דף מ\"ח ד\"ה ויש) אשר אברהם ירד לעמוקות שלהם, וידע אותן, ולא נתדבק בהם, אלא חזר אל רבונו."],[1,"ולא אתפתא בהו וכו':","ולא נתפתה מהם, כמו אדם, כאשר הגיע לאותה מדרגה, נתפתה על ידי הנחש, וגרם מות לכל העולם. ולא נתפתה כנח, כאשר ירד לאותה המדרגה, מה כתוב, וישת מן היין וישכר ויתגל בתוך אהלה. אהלה כתיב ב \u0003ה'\u0004 שה\"ס אשה זרה, (כנ\"ל בפרשת נח דף ק\"ח אות ש\"ח ע\"ש)."],[2,"אבל באברהם מה כתיב וכו':","אבל באברהם מה כתיב בו, ויעל אברם ממצרים, שעלה ולא ירד, וחזר למקומו, למדרגה העליונה, שנתדבק בה בתחילה. ומעשה זו היתה כדי להורות חכמה, שנתקיים בקיום שלם כראוי לו, ולא נתפתה אחר המצרים, ועמד בקיומו וחזר למקומו, הנגבה, זהו רוח דרום, חסד דז\"א, הוא מדרגה העליונה שאחז בה בתחילה, שכתוב הלוך ונסוע \u0003הנגבה.\u0004 אף עתה \u0003הנגבה,\u0004 דהיינו המקום שנתדבק בו בתחילה."],[3,"ת\"ח רזא דמלה וכו':","בוא וראה סוד הדבר. אם לא ירד אברם למצרים, ולא נצרף שם בתחילה, לא היה חלק גורלו בהקב\"ה. כעין זה היה לבניו, כאשר רצה הקב\"ה לעשותם עם אחד, עם שלם, ולקרבם אליו. אם לא ירדו מתחילה למצרים, ולא נצרפו שם, לא היו עם אחד שלו."],[4,"כגוונא דא וכו':","כעין זה, אם לא ניתנה ארץ הקדש מתחילה לכנען, והיו מושלים בה, לא היתה הארץ חלקו וגורלו של הקב\"ה והכל סוד אחד. וכבר נתבאר כל זה. (ענין אברהם ומצרים נתבאר לעיל דף מ\"ח ד\"ה ואין ע\"ש. וענין ישראל ומצרים נתבאר לעיל דף מ\"ח ד\"ה ב') וג') ע\"ש. וענין כנען וארץ הקדש נתבאר לעיל פרשת נח דף קי\"ב ד\"ה והסוד הוא ע\"ש)."],[5,"ר\"ש הוה אזיל וכו':","ר' שמעון היה הולך בדרך, והיה עמו ר' אלעזר בנו, ורבי אבא, ורבי יהודה, בעוד שהיו הולכים, אמר ר' שמעון, תמיהני איך בני העולם אינם מסתכלים להבין דברי תורה. ולדעת על מה הם עומדים בעולם. פתח ואמר, נפשי אויתיך בלילה וגו', מקרא זה בארוהו וגם אנו בארנו אותו. אבל בוא וראה. נפש האדם, בעת שעולה לישן על מטתו, יוצאת ממנו ועולה למעלה. ואם תאמר שכולם עולים דהיינו שגם שאר המדרגות: רוח ונשמה עולים עמה למעלה, אינו כך, כי לאו כל אחד ואחד רואה פני המלך, אלא הנפש עולה, אל המלך, (וטעם הדבר הוא להלן דף נ\"ט ד\"ה ת\"ח) ולא נשאר אז עם הגוף, רק רשימה אחת שהיא מדת החיים של הלב."],[6,"ונפשא אזלא וכו':","והנפש הולכת, מן הגוף, ומבקשת לעלות. וכמה מדרגות על מדרגות הם, לעלות. היא משוטטת ופוגשת בקליפות של אורות הטומאה. אם היא טהורה, שלא נטמאת עם הגוף ביום, היא עולית למעלה. ואם אינה טהורה, היא נטמאת בין הקליפות הללו ומתדבקת בהן, ולא תעלה עוד."],[7,"ותמן מודעי וכו':","ושם, בין הקליפות, מודיעים לה דברים מאלו דברים העתידים לבא בזמן קרוב, והנפש מתדבקת בהם. ולפעמים, שמצחקים בה, ומודיעים לה דברי שקר. וכך הולכת באותו אופן כל הלילה עד שיעור האדם משנתו, ואז חוזרת הנפש למקומה, להגוף."],[7,"זכאין אינון:","אשריהם הצדיקים, שהקב\"ה מגלה להם בחלום את הסודות שלו, כדי שישמרו עצמם מן הדין. ווי לאותם הרשעים המטמאים עצמם ונפשם."],[8,"ת\"ח אינון וכו':","בוא וראה. אלו שלא נטמאו ביום, כשעולים למטתם לישן, עולה הנפש ונכנסת מתחילה בין כל אלו מדרגות הקליפות הנ\"ל, ועולה מהן, ואינה מתדבקת בהן. ואחר כך הולכת ומשוטטת ועולה למעלה לפי מדרגתה."],[9,"ההיא נפשא וכו':","אותה הנפש שזכתה לעלות. היא מתראית אל פני המלך, ומתדבקת בהרצון להראות, בתשוקה עליונה, לראות בנועם המלך ולבקר בהיכלו. וזה הוא אדם שיש לו חלק תמיד, בעולם הבא."],[10,"ודא הוא נפשא וכו':","וזו היא נפש, אשר בעת שהשתוקקות שלה עולה, היא להקב\"ה, ואינה מתדבקת במיני אורות אחרים, והיא הולכת אחר מינה הקדוש, במקום שיצאה משם. שה\"ס הנוקבא, שהיא יוצאת ונמשכת ממנה. ומשום זה כתוב, נפשי אויתיך בלילה, כדי לרדוף אחריך להדבק בך, ולא להתפתות אחר מין אחר זר."],[11,"ת\"ח נפשי וכו':","בוא וראה, נפשי, זו היא השולטת בלילה, ולרדוף אחר המדרגה שלה, שהיא הנוקבא דז\"א, להדבק בה. רוח, שולט ביום. שכתוב \u0003נפשי אויתיך בלילה,\u0004 זו היא הנפש השולטת בלילה. דהיינו כנ\"ל, שאז עולית ומתראית אל פני המלך וכו'. \u0003אף רוחי בקרבי אשחרך,\u0004 זה הוא רוח, השולט ביום. פירוש. נפש רוח נמשכים מזו\"ן, הרוח מז\"א, שה\"ס חסדים. והנפש מהנוקבא. וכמו שז\"א שולט ביום כן הרוח שולט ביום. וכמו שהנוקבא שולטת בלילה, בסו\"ה ותקם בעוד לילה, כן הנפש שולטת בלילה, ומטעם זה אומר לעיל באות קמ\"ו \u0003לאו כל חד וחד חמי אפי מלכא אלא נפשא סלקא,\u0004 להיותה דומה אל הנוקבא, שבה נוהג ראיה, (כנ\"ל בראשית א', דף ע\"ד ד\"ה ועלמא. ודף רע\"ו ד\"ה ועוד) אבל שאר המדרגות, רוח ונשמה הנמשכים מז\"א ובינה, אינם עולים להראות לפני המלך, כי בהם אינה נוהגת ראיה כמ\"ש שם."]],[[0,"","אָמַר רַבִּי שִׁמְעוֹן, בּא רְאֵה, הַכֹּל הוּא סוֹד שֶׁל חָכְמָה, וְרָמַז כָּאן בַּחָכְמָה וְהַדְּרָגוֹת שֶׁלְּמַטָּה שֶׁאַבְרָהָם יָרַד לְעָמְקָם וְיָדַע אוֹתָם, וְלֹא נִדְבַּק בָּהֶם, וְשָׁב לִפְנֵי רִבּוֹנוֹ,"],[1,"","וְלֹא הִתְפַּתָּה בָהֶם כְּאָדָם שֶׁכַּאֲשֶׁר הִגִּיעַ לַדַּרְגָּה הַהִיא הִתְפַּתָּה בַּנָּחָשׁ וְגָרַם מָוֶת לָעוֹלָם. וְלֹא הִתְפַּתָּה כְּמוֹ נֹחַ, שֶׁכַּאֲשֶׁר יָרַד וְהִגִּיעַ לַדַּרְגָּה הַהִיא מַה כָּתוּב? (בראשית ט) וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגַּל בְּתוֹךְ אָהֳלֹה. אָהֳלֹה כָּתוּב בְּהֵ\"א."],[2,"","אֲבָל בְּאַבְרָהָם מַה כָּתוּב? וַיַּעַל אַבְרָם מִמִּצְרַיִם. שֶׁעָלָה וְלֹא יָרַד, וְשָׁב לִמְקוֹמוֹ לְדַרְגָּה עֶלְיוֹנָה שֶׁנִּדְבַּק בָּהּ כְּבָרִאשׁוֹנָה. וְהַמַּעֲשֶׂה הַזֶּה הָיָה כְּדֵי לְהַרְאוֹת הַחָכְמָה שֶׁהִתְקַיֵּם בְּקִיּוּם שָׁלֵם כָּרָאוּי לוֹ וְלֹא הִתְפַּתָּה, וְעָמַד בְּקִיּוּם וְשָׁב לִמְקוֹמוֹ. הַנֶּגְבָּה - זֶה הַדָּרוֹם, הַדַּרְגָּה הָעֶלְיוֹנָה שֶׁנֶּאֱחַז בָּהּ כְּבָרִאשׁוֹנָה, שֶׁכָּתוּב הָלוֹךְ וְנָסוֹעַ הַנֶּגְבָּה. אַף כָּאן הַנֶּגְבָּה - מָקוֹם שֶׁנִּדְבַּק בּוֹ בָּרִאשׁוֹנָה."],[3,"","בֹּא רְאֵה סוֹד הַדָּבָר, אִם אַבְרָם לֹא יֵרֵד לְמִצְרַיִם וְלֹא יִצְטָרֵף שָׁם בָּרִאשׁוֹנָה, לֹא יִהְיֶה חֵלֶק גּוֹרָלוֹ בַּקָּדוֹשׁ-בָּרוּךְ-הוּא. כְּמוֹ זֶה לְבָנָיו, כְּשֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת לוֹ (ד\"א להם) עַם אֶחָד, עַם שָׁלֵם, וּלְקָרְבָם אֵלָיו, אִם לֹא יֵרְדוּ בָּרִאשׁוֹנָה לְמִצְרַיִם וְלֹא יִזְדַּכְּכוּ שָׁם, לֹא הָיוּ הָעָם הַיְחִידִי שֶׁלּוֹ."],[4,"","כְּמוֹ כֵן אִם לֹא נִתְּנָה הָאָרֶץ הַקְּדוֹשָׁה לִכְנַעַן בָּרִאשׁוֹנָה וְיִשְׁלֹט בָּהּ, לֹא הָיְתָה הָאָרֶץ חֶלְקוֹ וְגוֹרָלוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהַכֹּל סוֹד אֶחָד."],[5,"","רַבִּי שִׁמְעוֹן הָיָה הוֹלֵךְ בַּדֶּרֶךְ, וְהָיָה עִמּוֹ רַבִּי אֶלְעָזָר בְּנוֹ, וְרַבִּי אַבָּא וְרַבִּי יְהוּדָה. בְּעוֹדָם הוֹלְכִים, אָמַר רַבִּי שִׁמְעוֹן, תְּמֵהַנִי אֵיךְ בְּנֵי הָעוֹלָם לֹא מַשְׁגִּיחִים לָדַעַת דִּבְרֵי תוֹרָה וְעַל מָה עוֹמְדִים. פָּתַח וְאָמַר, (ישעיה כו) נַפְשִׁי אִוִּיתִךְ בַּלַּיְלָה אַף רוּחִי בְקִרְבִּי אֲשַׁחֲרֶךָּ. הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ וּבֵאַרְנוּ אוֹתוֹ. אֲבָל בּא רְאֵה, נֶפֶשׁ הָאָדָם, כְּשֶׁהוּא עוֹלֶה לְמִטָּתוֹ, יוֹצֵאת מִמֶּנּוּ וְעוֹלָה לְמַעְלָה. וְאִם תֹּאמַר שֶׁכֻּלָּן עוֹלוֹת - אֵין כָּל אֶחָד וְאֶחָד רוֹאֶה אֶת פְּנֵי הַמֶּלֶךְ, אֶלָּא הַנֶּפֶשׁ עוֹלָה וְלֹא נִשְׁאָר בָּהּ עִם הַגּוּף, רַק רֹשֶׁם (נשימה) שֶׁל הַמִּדָּה שֶׁל חַיּוּת הַלֵּב."],[6,"","וְהַנֶּפֶשׁ הוֹלֶכֶת וְרוֹצָה לַעֲלוֹת. וְכַמָּה דְרָגוֹת לִדְרָגוֹת לַעֲלוֹת, הִיא מְשׁוֹטֶטֶת וּפוֹגֶשֶׁת בַּקְּלִפּוֹת שֶׁל אוֹרוֹת הַטֻּמְאָה. אִם הִיא טְהוֹרָה, שֶׁלֹּא נִטְמְאָה בַיּוֹם, עוֹלָה לְמַעְלָה. וְאִם לֹא טְהוֹרָה, נִטְמֵאת בֵּינֵיהֶם וְנִדְבֶּקֶת בָּהֶם וְלֹא עוֹלָה יוֹתֵר."],[7,"","וְשָׁם מוֹדִיעִים לָהּ דְּבָרִים, וְנִדְבֶּקֶת מֵאוֹתָם דְּבָרִים שֶׁל זְמַן קָרוֹב. וְלִפְעָמִים שֶׁצּוֹחֲקִים עָלֶיהָ וּמוֹדִיעִים לָהּ דְּבָרִים כּוֹזְבִים. וְאָז הוֹלֶכֶת כְּמוֹ זֶה כָּל הַלַּיְלָה עַד שֶׁיִּתְעוֹרֵר הָאִישׁ, וְשָׁבָה לִמְקוֹמָהּ. אַשְׁרֵי הַצַּדִּיקִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְגַלֶּה לָהֶם סוֹדוֹתָיו בַּחֲלוֹם כְּדֵי שֶׁיִּשָּׁמְרוּ מִן הַדִּין. אוֹי לְאוֹתָם רִשְׁעֵי הָעוֹלָם שֶׁמְּטַמְּאִים עַצְמָם וְנַפְשָׁם."],[8,"","בֹּא רְאֵה, אוֹתָם שֶׁלֹּא נִטְמְאוּ, כְּשֶׁעוֹלִים לְמִטָּתָם, הַנֶּפֶשׁ עוֹלָה וְנִכְנֶסֶת בֵּין כָּל אוֹתָן הַדְּרָגוֹת בָּרִאשׁוֹנָה, וְעוֹלָה וְלֹא נִדְבֶּקֶת בָּהֶן. אַחַר כָּךְ הוֹלֶכֶת וּמְשׁוֹטֶטֶת וְעוֹלָה כְּפִי דַרְכָּהּ."],[9,"","אוֹתָהּ הַנֶּפֶשׁ שֶׁזּוֹכָה לַעֲלוֹת, נִרְאֵית לִפְנֵי סֵבֶר פְּנֵי הַיָּמִים, וְנִדְבֶּקֶת בְּרָצוֹן לְהֵרָאוֹת בִּתְשׁוּקָה עֶלְיוֹנָה לִרְאוֹת בְּנֹעַם הַמֶּלֶךְ וּלְבַקֵּר בְּהֵיכָלוֹ. וְזֶה הוּא הָאִישׁ שֶׁיֵּשׁ לוֹ חֵלֶק תָּמִיד בָּעוֹלָם הַבָּא."],[10,"","וְזוֹ הִיא הַנֶּפֶשׁ שֶׁהַכִּסּוּף שֶׁלָּהּ כְּשֶׁעוֹלָה בַּקָּדוֹשׁ-בָּרוּךְ-הוּא (תמיד) וְלֹא נִדְבֶּקֶת בַּמִּינִים הַלָּלוּ אוֹרוֹת הָאֲחֵרִים, וְהִיא הוֹלֶכֶת אַחַר מִין קָדוֹשׁ בְּמָקוֹם (אחר מקום) שֶׁיּוֹצֵאת מִשָּׁם. וּמִשּׁוּם כָּךְ כָּתוּב נַפְשִׁי אִוִּיתִךְ בַּלַּיְלָה, כְּדֵי לִרְדֹּף אַחֲרֶיךְ וְלֹא לְהִתְפַּתּוֹת אַחַר מִין אַחֵר נָכְרִי."],[11,"","בֹּא רְאֵה, נַפְשִׁי - זוֹ הַנֶּפֶשׁ שֶׁשּׁוֹלֶטֶת בַּלַּיְלָה לִרְדֹּף אַחַר הַדַּרְגָּה שֶׁלָּהּ. הָרוּחַ בַּיּוֹם, שֶׁכָּתוּב נַפְשִׁי אִוִּיתִךְ בַּלַּיְלָה, זוֹ הַנֶּפֶשׁ שֶׁשּׁוֹלֶטֶת בַּלַּיְלָה. אַף רוּחִי בְקִרְבִּי אֲשַׁחֲרֶךָּ - זוֹ הָרוּחַ שֶׁשּׁוֹלֶטֶת בַּיּוֹם."]]],[["וְאִי תֵימָא דִּתְרֵין דַּרְגִּין אִנּוּן בִּפְרוּדָא, לָאו הָכִי, דְּהָא דַּרְגָּא חַד אִנּוּן, וְאִנּוּן תְּרֵין בְּחִבּוּרָא חַד. וְחַד עִלָּאָה דְּשָׁלְטָא עֲלַיְיהוּ וְאִתְדַּבָּק בְּהוּ וְאִנּוּן בֵּיהּ (ואקרון) וְאִתְקְרִיאַת נְשָׁמָה,","וְכֻלְהוּ דַּרְגִּין סָלְקָאן בְּרָזָא דְּחָכְמְתָא, דְּכַד מִסְתַּכְּלָן אִלֵּין דַּרְגִּין יִסְתַּכֵּל בַּר נָשׁ בְּחָכְמָה עִלָּאָה, וְהַאי נְשָׁמָה עָיִיל בְּהוּ וּמִתְדַּבְּקָן בָּהּ, וְכַד הַאי שָׁלְטָא כְּדֵין הַהוּא בַּר נָשׁ אִקְרֵי קָדוֹשׁ שְׁלִים מִכֹּלָּא. רְעוּתָא חָדָא לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא.","נֶפֶ\"שׁ אִיהוּ אִתְעֲרוּתָא תַּתָּאָה וְדָא סְמִיכָא בְּגוּפָא וְזָנַת לֵיהּ, וְגוּפָא אָחִיד בָּהּ וְהִיא אִתְאַחֲדַת בְּגוּפָא. לְבָתַר אִתְתַּקְנַת וְאִתְעֲבִידַת כֻּרְסְיָיא לְאַשְׁרָאָה עֲלָהּ רוּחַ בְּאִתְעֲרוּתָא דְּהַאי נֶפֶשׁ דְּאִתְאֲחִידַת בְּגוּפָא, כְּמָה דִכְתִיב, (ישעיה לב) עַד יֵעָרֶה עָלֵינוּ רוּחַ מִמָּרוֹם.","לְבָתַר דִּמְתַקְּנִי תַּרְוַויְיהוּ, זְמִינִין לְקַבְּלָא נְשָׁמָה. דְּהָא רוּחַ אִתְעֲבִיד כֻּרְסְיָיא לְגַבֵּי נְשָׁמָה לְאַשְׁרָאָה עֲלֵיהּ, וְהַאי נְשָׁמָה אִיהִי סְתִימָא עִלָּאָה עַל כֹּלָּא טְמִירָא דְכָל טְמִירִין.","אִשְׁתְּכַח דְּאִית (לה) כֻּרְסְיָיא לְכֻּרְסְיָיא וְכֻּרְסְיָיא לְגַבֵּי עִלָּאָה עֲלַיְיהוּ. וְכַד תִּסְתַּכַּל בְּדַרְגִּין תִּשְׁכַּח רָזָא דְחָכְמְתָא בְּהַאי מִלָּה. וְכֹלָּא הוּא חָכְמְתָא לְאִתְדַּבְּקָא בְּהַאי גַוְונָא מִלִּין סְתִימִין.","תָּא חֲזֵי (לעיל עז ב) נֶפֶשׁ אִיהִי אִתְעֲרוּתָא תַּתָּאָה דְּאִתְדַּבְּקָא בֵּיהּ בְּגוּפָא. כְּגַוְונָא דִנְהוֹרָא דְּבוּצִינָא. דִּנְהוֹרָא תַּתָּאָה דְּאִיהִי אוּכְמָא אִתְדַּבְּקַת בִּפְתִילָה וְלָא אִתְפְּרַשׁ מִנָּהּ וְלָא אִתְתַּקְנַת אֶלָּא בָּהּ. וְכַד אִתְתַּקְנַת בַּפְּתִילָה אִתְעֲבִידַת כֻּרְסְיָיא לִנְהוֹרָא עִלָּאָה חִוָּורָא דְּשַׁרְיָיא עַל הַהוּא נְהוֹרָא אוּכְמָא.","לְבָתַר כַּד מִתְתַּקְנָן תַּרְוַויְיהוּ אִתְעֲבִידַת הַהוּא נְהוֹרָא חִוָּורָא כֻּרְסְיָיא לִנְהוֹרָא סְתִימָאָה דְּלָא אִתְחֲזֵי וְלָא אִתְיְידַע מַה דְּשָׁרָא עַל הַהוּא נְהוֹרָא חִוָּורָא. וּכְדֵין נְהוֹרָא שְׁלִים. וְכָךְ הוּא בַּר נָשׁ דְּאִיהוּ שְׁלִים בְּכֹלָּא. וּכְדֵין אִקְרֵי קָדוֹשׁ, כְּמָא דְאַתְּ אָמֵר, (תהילים ט״ז:ג׳) לִקְדוֹשִׁים אֲשֶׁר בָּאָרֶץ הֵמָּה וְגו'. כְּגַוְונָא דָא בְּרָזָא עִלָּאָה.","תָּא חֲזֵי, בְּשַׁעֲתָא דְּעָאל אַבְרָהָם לְאַרְעָא, אִתְחֲזִיִ לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא כְּמָה דְּאִתְּמָר דִּכְתִיב לַיְיָ הַנִּרְאֶה אֵלָיו, וְקַבִּיל תַּמָּן נֶפֶשׁ וּבָנָה מִזְבֵּחַ לְהַהוּא דַרְגָא. לְבָתַר הָלוֹךְ וְנָסוֹעַ הַנֶּגְבָּה דְּקַבִּיל רוּחַ. לְבָתַר (עד) דְּסָלִיק לְאִתְדַּבְּקָא גּוֹ נְשָׁמָה כְּדֵין וַיִּבֶן שָׁם מִזְבֵּחַ לַיְיָ סְתָם, דָּא הִיא נְשָׁמָה דְּאִיהִי סְתִימָא דְכָל סְתִימִין.","לְבָתַר יָדַע דְּבָעֵי לְאִצְטְרָפָא וּלְאִתְעַטְּרָא בְּדַרְגִּין, מִיָּד וַיֵּרֶד אַבְרָם מִצְרָיְמָה, וְאִשְׁתְּזִיב מִתַּמָּן. וְלָא אִתְפַּתָּא גּוֹ אִנּוּן טְהִירִין, וְאִתְצָרִיף וְתָב לְאַתְרֵיהּ. כֵּיוָן דְּנָחַת וְאִתְצָרִיף, מִיָּד וַיַּעַל אַבְרָם מִמִּצְרַיִם, סָלִיק וַדַּאי וְתָב לְאַתְרֵיהּ וְאִתְדָּבַּק בִּמְהֵימְנוּתָא עִלָּאָה דִּכְתִיב הַנֶּגְבָּה.","מִכָּאן וּלְהָלְאָה יָדַע אַבְרָהָם חָכְמְתָא עִלָּאָה וְאִתְדָּבַּק בְּקוּדְשָׁא בְּרִיךְ הוּא וְאִתְעֲבִיד יָמִינָא דְעָלְמָא. כְּדֵין וְאַבְרָם כָּבֵד מְאֹד בַּמִּקְנְה בַּכֶּסֶף וּבַזָּהָב. כָּבֵד מְאֹד בְּסִטְרָא דְמִזְרָח. בַּמִּקְנֶה בְּסִטְרָא דְמַעֲרָב. בַּכֶּסֶף מִסִּטְרָא דְּדָרוֹם. בַּזָּהָב מִסִּטְרָא דְצָפוֹן.","אָתוּ רַבִּי אֶלְעָזָר וְרַבִּי אַבָּא וְכֻלְהוּ חַבְרַיָא וּנְשָׁקוּ יְדוֹי. בְּכָה רַבִּי אַבָּא וְאָמַר וַוי וַוי כַּד תִּסְתַּלַּק מִן עָלְמָא מַאן יַנְהִיר נְהוֹרָא דְאוֹרַיְיתָא. זַכָּאָה חוּלַקְהוֹן דְּחַבְרַיָיא דְּשָׁמְעִין מִלִּין דְּאוֹרַיְיתָא אִלֵּין מִפּוּמָךְ.","אָמַר רַבִּי שִׁמְעוֹן תָּא חֲזֵי, מַה כְּתִיב וַיֵּלֶךָ לְמַסָּעָיו, לְמִפְקַד אַתְרֵיהּ וְדַרְגּוֹי. לְמַסָּעָיו לְמַסָּעוֹ כְּתִיב, מַאן מַסָּעוֹ. דָּא דַרְגָּא קַדְמָאָה דְּאִתְחֲזֵי לֵיהּ בְּקַדְמִיתָא, כְּתִיב הָכָא מַסָּעוֹ וּכְתִיב הָתָם (מלכים א ו׳:ז׳) אֶבֶן שְׁלֵמָה מַסַּע נִבְנֶה. וְהָא אוֹקִימְנָא אֶבֶן שְׁלֵמָה וַדַּאי. מַסַּע כְּמָה דְאִתְּמָר.","וַיֵּלֶךָ לְמַסָּעָיו. (עיין פי' בס' הגלגולים דף ו' ע\"ג סוף פ' ו) כָּל אִנּוּן דַּרְגִּין דַּרְגָּא בָּתַר דַּרְגָּא כְּמָה דְאִתְּמָר. מִנֶּגֶב וְעַד בֵּית אֵל לְאַתְקָנָא אַתְרֵיהּ וּלְחַבְּרָא לוֹן בְּיִחוּדָא שְׁלִים. דְּהָא מִנֶּגֶב וְעַד בֵּית אֵל אִשְׁתְּכַח רָזָא דְחָכְמְתָא כְּדְקָא יְאוּת."],[[0,"ואי תימא דתרין וכו':","ואם תאמר, שנפש רוח הם ב' מדרגות נפרדות זו מזו. אינו כך, כי מדרגה אחת הם, והם שנים בחיבור יחד. ואחת עליונה השולטת עליהם ומתדבקת בהם, והם בה, ונקראת \u0003נשמה.\u0004"],[1,"וכלהו דרגין וכו':","וכל המדרגות עולות בסוד החכמה. כי כשהמדרגות מסתכלות זו בזו, מסתכל אז האדם בחכמה העליונה, ונשמה הזו נכנסת בהם, בהנפש ורוח, והם מתדבקים בה. וכאשר זו שולטת, דהיינו הנשמה, נקרא אז האדם, קדוש, שלם מכל, והוא ברצון אחד אל הקב\"ה."],[2,"נפש איהו וכו': נפש","היא התעוררות תחתונה, כלומר, היא התחתונה מהאורות נר\"ן. וזו סמוכה להגוף, ומזינה אותו, והגוף אוחז בה, והיא נאחזת בהגוף. לאחר כך, הנפש מתתקנת ע\"י מעשים טובים שעושה האדם, ונעשית כסא, שישרה עליה \u0003הרוח,\u0004 בכח התעוררות של הנפש הנאחזת בהגוף, כמו שכתוב עד יערה עלינו רוח ממרום."],[3,"לבתר דמתקני וכו':","לאחר שכבר נתקנו שניהם, הנפש והרוח, הם עתידים לקבל \u0003נשמה,\u0004 כי הרוח נעשה כסא אל הנשמה שתשרה עליו. ונשמה זו היא עליונה על כולם וסתומה, בלתי מושגת, נסתרת מכן נסתר."],[4,"אשתכח דאית וכו':","נמצא, שיש כסא לכסא, כי הנפש היא כסא להרוח שהוא ג\"כ כסא, וכסא אל העליון עליהם, כי הרוח הוא כסא אל הנשמה שהיא עליונה עליהם. וכשתסתכל במדרגות תמצא בדבר זה סוד החכמה. כלומר איך אור החכמה נמשך על ידי נפש רוח נשמה הללו. והכל הוא חכמה להשיג בדרך הזה דברים סתומים."],[5,"ת\"ח נפש איהי וכו':","בוא וראה, נפש היא התעוררות תחתונה הנדבקת בהגוף. כעין אור הנר, שאור התחתון שבו שהוא שחור, מתדבק בפתילה, ואינו נפרד ממנו ואינו מתתקן אלא בו. וכשאור השחור מתתקן ונאחז בפתילה, הוא נעשה כסא לאור הלבן העליון שעליו, כי הוא שורה על אור השחור. ואור הלבן הזה הוא כנגד אור הרוח."],[6,"לבתר כד מתתקנן וכו':","לאחר ששניהם מתתקנים, אור השחור ואור הלבן שעליו, נעשה אור הלבן כסא, לאור סתום שאינו נראה ולא נודע, מה ששורה על אור הלבן והוא כנגד אור הנשמה ואז הוא אור שלם. באופן שיש באור הנר ג' אורות זה על זה. א) אור שחור הדבק בפתילה, שהוא למטה מכולם. ב) אור הלבן השורה על אור השחור. ג) אור סתום לא נודע, השורה על אור הלבן. \u0003וכך היא ב- נש דאיהו שלים בכלא,\u0004 וכן הוא האדם השלם בכל. שיש לו ג\"כ ג' אורות זה על זה, כנ\"ל באור הנר, שהם נפש רוח נשמה. \u0003וכדין אקרי קדוש, כד\"א לקדושים וגו'.\u0004 ואז נקרא האדם בשם קדוש. כמו שאתה אומר, לקדושים אשר בארץ המה וגו'."],[7,"כגוונא דא ברזא עלאה, ת\"ח וכו':","כעין זה בסוד עליון הוא בהכתובים שלפנינו. בוא וראה. בשעה שאברהם בא לארץ נראה לו הקב\"ה. כמו שאמרנו, שכתוב לה' הנראה אליו. והשיג שם אור הנפש. ובנה מזבח למדרגה זו. לאחר זה כתוב, הלוך ונסוע הנגבה, שהשיג בזה אור הרוח. ואחר כך, שעלה להתדבק תוך אור הנשמה שה\"ס בינה הנק' עלמא דאתכסיא. כתוב אז \u0003ויבן שם מזבח,\u0004 סתם. שלא כתוב לה' הנראה אליו. אשר זה הוא נשמה, שהיא סתומה מכל סתום. וע\"כ לא כתוב בה לה' הנראה אליו, כמו שכתוב באור הנפש."],[8,"לבתר ידע דבעי וכו':","לאחר כך, ידע אברהם שהוא צריך להצרף, ולהתעטר עוד במדרגות, מיד, וירד אברם מצרימה, ונצל משם ולא נתפתה תוך אותם האורות שלהם, ונצרף ושב למקומו. כיון שירד למצרים ונצרף שם, מיד ויעל אברם ממצרים, עלה ודאי. כלומר שהיה לו עליה במדרגה. כי זכה לאור החיה שה\"ס חכמה דצד ימין (כנ\"ל דף נ\"ו ד\"ה אמר) ושב למקומו לארץ ישראל. ונתדבק באמונה העליונה, שכתוב הנגבה, שפירושו חכמה דצד ימין: דהיינו חסד שעולה לעת גדלות ונעשה חכמה. אמנם יש גם במדרגה זו ה' מדרגות נרנח\"י ועתה זכה למדרגות הראשונות שבה כמ\"ש להלן."],[9,"מכאן ולהלאה וכו':","מכאן ואילך, ידע אברהם חכמה עליונה ונתדבק בהקב\"ה, ונעשה ימינו של העולם, אז נאמר ואברם כבד מאד במקנה בכסף וזהב. \u0003כבד מאד,\u0004 מצד מזרח, שהוא ת\"ת. \u0003במקנה,\u0004 מצד מערב, שהוא מלכות. \u0003בכסף,\u0004 מצד דרום, שהוא חכמה. \u0003בזהב,\u0004 מצד צפון, שהוא בינה."],[10,"אתו ר' אלעזר וכו':","באו ר' אלעזר ור' אבא וכל החברים ונשקו ידיו של ר\"ש. בכה ר' אבא ואמר, ווי ווי כאשר תסתלק מהעולם מי יאיר אור התורה. אשרי חלקם של החברים ששמעו דברי תורה הללו מפיך."],[11,"אר\"ש וכו' וילך למסעיו וכו':","וילך למסעיו פירושו, שהלך לפקוד את מקומו ומדרגתו. \u0003למסעו,\u0004 למסעו כתוב, בלי \u0003י',\u0004 שהוא לשון יחיד. ושואל, איזה מסע, ואומר, זו היא מדרגה הראשונה שנראה לו בתחילה. כתוב כאן מסעו, וכתוב שם אבן שלמה מסע נבנה, ובארנו לעיל (פרשת נח קי\"ד אות שכ\"ו) אבן שלמה ודאי, דהיינו אבן שהוא מלכות, של המלך שהשלום שלו. כי שלמה רומז על המלך שהשלום שלו שהוא ז\"א (כנ\"ל ב\"א דף רמ\"א אות רצ\"ג.) ואבן שלמה היא הנוקבא דז\"א. ויליף גזירה שוה שאף כאן, היא הנוקבא דז\"א. \u0003מסע, כמה דאתמר.\u0004 מסע פירושו, כמו שנתבאר שם (בפרשת נח דף קי\"ד אות שכ\"ו.) ע\"ש."],[12,"וילך למסעיו וכו':","למסעיו, פירושו, שהלך בכל אלו המדרגות מדרגה אחר מדרגה. כמו שנתבאר לעיל (באות קס\"א) \u0003מנגב ועד בית אל,\u0004 הוא כדי לתקן את מקומו שהוא חסד הנקרא \u0003נגב,\u0004 ולחבר אותו עם \u0003בית אל\u0004 שהיא הנוקבא, ביחוד שלם. כי מנגב עד בית אל נמצא סוד החכמה כראוי. פירוש. כי הנוקבא הנקראת בית אל, היא מאירה באור החכמה, כי נקראת חכמה תתאה. אמנם אין החכמה יכולה להאיר בה בלי חסדים. וע\"כ אומר. \u0003דהא מנגב,\u0004 שהוא חסד, \u0003עד בית אל אשתכח רזא דחכמתא כדקא יאות.\u0004 כי כשמחבר את הנגב שהוא חסדים, עם החכמה, שבבית אל יכולה החכמה להאיר כראוי. אבל מטרם שנתחברה בנגב אין החכמה שבבית אל יכולה להאיר. (כנ\"ל דף ס\"א ד\"ה לבתר)."]],[[0,"","וְאִם תֹּאמַר שֶׁשְּׁתֵּי דְרָגוֹת הֵן בְּפֵרוּד - לֹא כָּךְ, שֶׁהֲרֵי הֵן דַּרְגָּה אַחַת, וְהֵן שְׁתַּיִם בְּחִבּוּר אֶחָד, וְאַחַת עֶלְיוֹנָה שֶׁשּׁוֹלֶטֶת עֲלֵיהֶן וְנִדְבֶּקֶת בָּהֶן וְהֵן בָּהּ (ונקראים) וְנִקְרֵאת נְשָׁמָה."],[1,"","וְכָל הַדְּרָגוֹת עוֹלוֹת בְּסוֹד הַחָכְמָה. שֶׁכְּשֶׁמִּסְתַּכְּלִים עַל אֵלּוּ הַדְּרָגוֹת, יִסְתַּכֵּל הָאָדָם בַּחָכְמָה הָעֶלְיוֹנָה, וְהַנְּשָׁמָה הַזּוֹ נִכְנֶסֶת בָּהֶם וְנִדְבָּקִים בָּהּ. וּכְשֶׁזֶּה שׁוֹלֵט, אָז אוֹתוֹ הָאִישׁ נִקְרָא קָדוֹשׁ, שָׁלֵם מִן הַכֹּל. רָצוֹן אֶחָד לַקָּדוֹשׁ-בָּרוּךְ-הוּא."],[2,"","הַנֶּפֶ\"שׁ הִיא הִתְעוֹרְרוּת תַּחְתּוֹנָה, וְזוֹ סְמוּכָה בַּגּוּף וְזָנָה אוֹתוֹ, וְהַגּוּף אוֹחֵז בָּהּ וְהִיא אֲחוּזָה בַּגּוּף. אַחַר כָּךְ נִתְקֶנֶת וְנַעֲשֵׂית כִּסֵּא לְהַשְׁרוֹת עָלֶיהָ רוּחַ בְּהִתְעוֹרְרוּת הַנֶּפֶשׁ הַזֹּאת שֶׁנֶּאֱחֶזֶת בַּגּוּף, כַּכָּתוּב (ישעיה לב) עַד יֵעָרֶה עָלֵינוּ רוּחַ מִמָּרוֹם."],[3,"","לְאַחַר שֶׁמְּתַקְנִים אֶת שְׁנֵיהֶם, עֲתִידִים לְקַבֵּל נְשָׁמָה, שֶׁהֲרֵי הָרוּחַ נַעֲשֵׂית כִּסֵּא לַנְּשָׁמָה לְהַשְׁרוֹת עָלֶיהָ, וְהַנְּשָׁמָה הַזּוֹ הִיא נִסְתֶּרֶת עֶלְיוֹנָה עַל הַכֹּל טְמוּנַת כָּל הַטְּמוּנִים."],[4,"","נִמְצָא שֶׁיֵּשׁ (לה) כִּסֵּא לַכִּסֵּא, וְכִסֵּא לָעֶלְיוֹן עֲלֵיהֶם. וּכְשֶׁתִּסְתַּכֵּל בַּדְּרָגוֹת, תִּמְצָא סוֹד הַחָכְמָה בַּדָּבָר הַזֶּה, וְהַכֹּל הִיא חָכְמָה לְהַדְבִּיק בַּגָּוֶן הַזֶּה דְּבָרִים נִסְתָּרִים."],[5,"","בֹּא רְאֵה, הַנֶּפֶשׁ הִיא הִתְעוֹרְרוּת תַּחְתּוֹנָה שֶׁנִּדְבֶּקֶת בַּגּוּף, כְּמוֹ הָאוֹר שֶׁל הַמָּאוֹר, שֶׁהָאוֹר הַתַּחְתּוֹן שֶׁהוּא שָׁחֹר, נִדְבָּק בַּפְּתִילָה וְלֹא נִפְרָד מִמֶּנָּה וְלֹא נִתְקָן אֶלָּא בָּהּ. וּכְשֶׁנִּתְקָן בַּפְּתִילָה, נַעֲשֶׂה כִסֵּא לָאוֹר הָעֶלְיוֹן הַלָּבָן שֶׁשּׁוֹרֶה עַל אוֹתוֹ הָאוֹר הַשָּׁחֹר."],[6,"","אַחַר כָּךְ כְּשֶׁשְּׁנֵיהֶם נִתְקָנִים, נַעֲשֶׂה אוֹתוֹ אוֹר לָבָן כִּסֵּא לָאוֹר הַנִּסְתָּר שֶׁאֵינוֹ נִרְאֶה וְאֵינוֹ נוֹדָע מַה שֶּׁשָּׁרָה עַל אוֹתוֹ הָאוֹר הַלָּבָן, וְאָז הָאוֹר שָׁלֵם. וְכָךְ הָאָדָם שֶׁהוּא שָׁלֵם בַּכֹּל, וְאָז נִקְרָא קָדוֹשׁ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים טז) לִקְדוֹשִׁים אֲשֶׁר בָּאָרֶץ הֵמָּה וְגוֹ'. כְּמוֹ כֵן בְּסוֹד עֶלְיוֹן."],[7,"","בֹּא רְאֵה, בְּשָׁעָה שֶׁאַבְרָהָם נִכְנַס לָאָרֶץ, נִרְאָה לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנֶּאֱמַר לַה' הַנִּרְאֶה אֵלָיו, וְקִבֵּל שָׁם נֶפֶשׁ וּבָנָה מִזְבֵּחַ לַדַּרְגָּה הַהִיא. אַחַר כָּךְ הָלוֹךְ וְנָסוֹעַ הַנֶּגְבָּה, שֶׁקִּבֵּל רוּחַ. אַחַר כָּךְ (עד) שֶׁעָלָה לְהִתְדַּבֵּק תּוֹךְ הַנְּשָׁמָה, אָז וַיִּבֶן שָׁם מִזְבֵּחַ לַה', סְתָם. זוֹ הִיא הַנְּשָׁמָה שֶׁהִיא נִסְתֶּרֶת כָּל הַנִּסְתָּרִים."],[8,"","אַחַר כָּךְ יָדַע שֶׁצָּרִיךְ לְהִצָּרֵף וּלְהִתְעַטֵּר בַּדְּרָגוֹת, מִיָּד - וַיֵּרֶד אַבְרָם מִצְרָיְמָה, וְנִצַּל מִשָּׁם, וְלֹא הִתְפַּתָּה תּוֹךְ אוֹתָם הָאוֹרוֹת, וְנִצְרַף וְשָׁב לִמְקוֹמוֹ. כֵּיוָן שֶׁיָּרַד וְנִצְרַף, מִיָּד - וַיַּעַל אַבְרָם מִמִּצְרַיִם. עָלָה וַדַּאי וְשָׁב לִמְקוֹמוֹ וְנִדְבַּק בָּאֱמוּנָה הָעֶלְיוֹנָה, שֶׁכָּתוּב הַנֶּגְבָּה."],[9,"","מִכָּאן וָהָלְאָה יָדַע אַבְרָהָם הַחָכְמָה הָעֶלְיוֹנָה וְנִדְבַּק בַּקָּדוֹשׁ- בָּרוּךְ-הוּא, וְנַעֲשָׂה הַיָּמִין שֶׁל הָעוֹלָם. אָז, וְאַבְרָם כָּבֵד מְאֹד בַּמִּקְנֶה בַּכֶּסֶף וּבַזָּהָב. כָּבֵד מְאֹד - בְּצַד הַמִּזְרָח. בַּמִּקְנֶה - בְּצַד הַמַּעֲרָב. בַּכֶּסֶף - מִצַּד הַדָּרוֹם. בַּזָּהָב - מִצַּד הַצָּפוֹן."],[10,"","בָּאוּ רַבִּי אֶלְעָזָר וְרַבִּי אַבָּא וְכָל הַחֲבֵרִים וְנִשְּׁקוּ אֶת יָדוֹ. בָּכָה רַבִּי אַבָּא וְאָמַר, וַי וַי, כְּשֶׁתִּסְתַּלֵּק מִן הָעוֹלָם, מִי יָאִיר אֶת אוֹר הַתּוֹרָה? אַשְׁרֵי חֶלְקָם שֶׁל הַחֲבֵרִים שֶׁשּׁוֹמְעִים דִּבְרֵי תוֹרָה הַלָּלוּ מִפִּיךְ."],[11,"","אָמַר רַבִּי שִׁמְעוֹן, בֹּא רְאֵה מַה כָּתוּב. וַיֵּלֶךְ לְמַסָּעָיו, לִפְקֹד אֶת מְקוֹמוֹ וְדַרְגָּתוֹ. לְמַסָּעָיו - לְמַסָּעוֹ כָּתוּב, מִי הַמַּסָּעוֹ? זוֹ הַדַּרְגָּה הָרִאשׁוֹנָה שֶׁרְאוּיָה לוֹ בָּרִאשׁוֹנָה. כָּתוּב כָּאן מַסָּעוֹ, וְכָתוּב שָׁם (מלכים א ו) אֶבֶן שְׁלֵמָה מַסָּע נִבְנָה. וַהֲרֵי בֵּאַרְנוּ אֶבֶן שְׁלֵמָה וַדַּאי. מַסָּע, כְּמוֹ שֶׁנִּתְבָּאֵר."],[12,"","וַיֵּלֶךָ לְמַסָּעָיו, כָּל אוֹתָן הַדְּרָגוֹת, דַּרְגָּה אַחַר דַּרְגָּה, כְּמוֹ שֶׁנֶּאֱמַר. מִנֶּגֶב וְעַד בֵּית אֵל, לְתַקֵּן אֶת מְקוֹמוֹ וּלְחַבְּרָם בְּיִחוּד שָׁלֵם, שֶׁהֲרֵי מִנֶּגֶב וְעַד בֵּית אֵל נִמְצָא סוֹד הַחָכְמָה כָּרָאוּי."]]],[["אֶל הַמָּקוֹם אֲשֶׁר הָיָה שָׁם אָהֳלֹה בַּתְּחִלָּה, אָהֳלה בְּהֵ\"א, מַאן אָהֳלה, דָּא בֵּית אֵל. אֶבֶן שְׁלֵמָה כִּדְאֲמָרָן. תוּ רְשִׁים וְאָמַר אֶל מְקוֹם הַמִּזְבֵּחַ אֲשֶׁר עָשָׂה שָׁם בָּרִאשׁוֹנָה דִּכְתִיב לַיְיָ הַנִּרְאֶה אֵלָיו. וּכְדֵין וַיִּקְרָא שָׁם אַבְרָם בְּשֵׁם יְיָ. כְּדֵין אִתְדָּבַּק בִּמְהֵימְנוּתָא שְׁלֵימָתָא.","תָּא חֲזֵי, בְּקַדְמִיתָא סָלִיק מִתַּתָּא לְעֵילָא דִּכְתִיב וַיֵּרָא יְיָ אֶל אַבְרָם. וּכְתִיב לַיְיָ הַנִּרְאֶה אֵלָיו. וְדָא הוּא דַּרְגָּא קַדְמָאָה כִּדְאֲמָרָן אֶבֶן שְׁלֵמָה (מסע נבנה וכתיב למסעו). וּלְבָתַר הָלוֹךְ וְנָסוֹעַ הַנֶּגְבָּה. דַּרְגָּא בָּתַר דַּרְגָּא עַד דְּאִתְעַטַּר בַּדָּרוֹם חוּלָקֵיהּ וְעַדְבֵיהּ. לְבָתַר סָתִים מִלָּה כַּד סָלִיק וְאָמַר לַיְיָ סְתָם, דָּא עָלְמָא עִלָּאָה. וּמִתַּמָּן נָטִיל בְּדַרְגִּין וְנָחִית מֵעֵילָא לְתַתָּא וְאִתְדָּבַּק כֹּלָּא בְּאַתְרֵיהּ כְּדְקָא יְאוּת.","וְהָכָא כַּד תִּסְתַּכֵּל בְּדַרְגִּין תִּשְׁכַּח רָזָא דְחָכְמְתָא עִלָּאָה. מַה כְּתִיב וַיֵלֶךְ לְמַסָּעָו מִנֶּגֶב מִסִּטְרָא דְּיָמִינָא שֵׁירוּתָא דְּעָלְמָא עִלָּאָה סְתִימָא עֲמִיקָא לְעֵילָא עַד אֵין סוֹף, וְנָחִית דַּרְגָּא בָּתַר דַּרְגָּא (עד) מִנֶּגֶב וְעַד בֵּית אֵל מֵעֵילָא לְתַתָּא.","וּכְתִיב וַיִּקְרָא שָׁם אַבְרָם בְּשֵׁם יְיָ אַדְבַּק יִחוּדָא בְּאַתְרֵיהּ כְּדְקָא יְאוּת דִּכְתִיב אֶל מְקוֹם הַמִּזְבֵּחַ אֲשֶׁר עָשָׂה שָׁם בָּרִאשׁוֹנָה. מַאי אֲשֶׁר עָשָׂה שָׁם, דְּסָלִיק לָהּ מִתַּתָּא לְעֵילָא. וְהַשְׁתָּא נָחִית בְּדַרְגִּין מֵעֵילָא לְתַתָּא, בְּגִין דְּהִיא לָא תַעֲדֵי מֵאִנּוּן דַּרְגִּין עִלָּאִין, וְאִנּוּן לָא יַעֲדוּן מִנָּהּ, וְיִתְיַחֵד כֹּלָּא בְּיִחוּדָא חָדָא כְּדְקָא יָאוֹת.","כְּדֵין אִתְעַטַּר אַבְרָהָם וְהֲוָה חוּלַק עַדְבֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא וַדַּאי. זַכָּאִין אִנּוּן צַדִּיקַיָּיא דְּמִתְעַטְּרֵי בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא וְהוּא מִתְעַטֵּר בְּהוֹן. זַכָּאִין אִנּוּן בְּעָלְמָא דֵין וְזַכָּאִין אִנּוּן בְּעָלְמָא דְאָתֵי. עֲלַיְיהוּ כְּתִיב, (ישעיהו ס׳:כ״א) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִרְשׁוּ אָרֶץ. וּכְתִיב, (משלי ד׳:י״ח) וְאוֹרַח צַדִּיקִים כְּאוֹר נוֹגַהּ הוֹלֵךְ וְאוֹר עַד נְכוֹן הַיּוֹם.","אֲזְלוּ, כַּד מָטוּ בְּחַד בֵּי חֲקַל יָתְבוּ. פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר (תהילים כ״ה:ט״ז) פְּנֵה אֵלַי וְחָנִנִי וְגו'. הַאי קְרָא אִית לְאִסְתַּכָּלָא בֵּיהּ, וְהָא אוֹקִימְנָא לֵיהּ בְּכַמָּה אֲתַר. אֲבָל בְּהַאי קְרָא מִלִּין סְתִימִין אִית בֵּיהּ. פְּנֵה אֵלַי. וְכִי דָוִד אָמַר פְּנֵה אֵלַי וְחָנִנִי.","אֶלָּא בְּגִין דַּרְגָּא דִילֵיהּ דְּאִיהוּ אִתְעַטַּר בֵּיהּ קָאֲמַר. תְּנָה עֻזְךָ לְעַבְדֶּךָ, תְּנָה עֻזְךָ דָּא עֹז עִלָּאָה כְּדִכְתִיב, (שמואל א ב׳:י׳) וְיִתֵּן עֹז לְמַלְכּוֹ. מַאן מַלְכּוֹ דָּא מֶלֶךְ סְתָם מַלְכָּא מְשִׁיחָא. אוּף הָכָא לְעַבְדֶּךָ דָּא מַלְכָּא מְשִׁיחָא כִּדְאֲמָרָן מֶלֶךְ סְתָם.","וְהוֹשִׁיעָה לְבֶן אֲמָתֶךָ, וְכִי לָא הֲוָה בְּרֵיהּ דְּיִשַׁי אִיהוּ עַד דְּאִיהוּ אָמַר בִּשְׁמָא דְאִמֵּיהּ וְלָא בִּשְׁמָא דְּאֲבוֹי. אֶלָא הָא אוֹקִימְנָא דְּכַד יֵיתֵי בַּר נָשׁ לְקַבֵּל מִלָּה עִלָּאָה לְאִדְכָּרָא, בָּעֵי לְמֵהַךְ בְּמִלָּה דְּאִיהוּ וַדַּאי. וְעַל דָּא אַדְכַּר לְאִמֵּיהּ וְלָא לְאֲבוֹי. וְתוּ הָא תָּנִינָן (ד\"א ל\"ג דהא) דְּדָא מֶלֶךְ כִּדְקָאֲמָרָן.","אָמַר רַבִּי שִׁמְעוֹן תָּא חֲזֵי, מַה כְּתִיב וַיְהִי רִיב בֵּין רֹעֵי מִקְנֵה אַבְרָם, רִב כְּתִיב חָסֵר יוד, דְּבָעָא לוֹט לְמֶהדַר לְפוּלְחָנָא נוּכְרָאָה דְּפַלְחֵי יָתְבֵי אַרְעָא, וְסוֹפֵיהּ דִּקְרָא אוֹכַח דִּכְתִיב וְהַכְּנַעֲנִי וְהַפְּרִיזִי אָז יוֹשֵׁב בָּאָרֶץ.","וּמְנָלָן דְּלוֹט אַהֲדַר לְסָרְחָנֵיהּ לְפוּלְחָנָא נוּכְרָאָה, דִּכְתִיב וַיִּסַּע לוֹט מִקֶּדֶם. מַאי (לעיל עד ב) מִקֶּדֶם, מִקַּדְמוֹנוֹ שֶׁל עוֹלָם. כְּתִיב הָכָא וַיִּסַּע לוֹט מִקֶּדֶם וּכְתִיב וַיְהִי בְּנָסְעָם מִקֶּדֶם מַה לְּהַלָּן נְטִילוּ מִקַּדְמוֹנוֹ שֶׁל עוֹלָם אוּף הָכָא כֵּן.","כֵּיוָן דְּיָדַע אַבְרָהָם דְּלוֹט לְהָכִי נָטֵי לִבֵּיהּ. מִיָּד וַיֹּאמֶר אַבְרָם אֶל לוֹט וְגו' הִפָּרֶד נָא מֵעָלַי. לֵית אַנְתְּ כְּדַאי לְאִתְחַבְּרָא בַּהֲדָאי. כְּדֵין אִתְפְּרַשׁ אַבְרָהָם מִנֵּיהּ וְלָא בָּעָא לְמֵיהַךְ וּלְאִתְחַבָּרָא עִמֵּיהּ, דְּכָל מַאן דְּיִתְחַבַּר לְחַיָּיבָא סוֹפֵיהּ לְמֵיהַךְ אֲבַתְרֵיהּ וּלְאִתְעַנַּשׁ בְּגִינֵיהּ."],[[0,"אל מקום אשר היה שם אהלה בתחילה:","אהל\"ה כתיב עם \u0003ה'\u0004 ולא עם \u0003ו'.\u0004 זהו יורה אשר אהל\"ה הוא בית אל, הנקראת אבן שלמה, כמו שאמרנו (באות ע') דהיינו הנוקבא דז\"א. עוד מציין שכוונתו על הנוקבא, ואומר, אל מקום המזבח אשר עשה שם בראשונה, שכתוב בו לה' הנראה אליו, שה\"ס הנוקבא כנ\"ל (באות ק\"ס) ואז, ויקרא שם אברם בשם ה'. כי אז נתדבק באמונה שלמה. דהיינו בהנוקבא בשלמותה, שנקראת אמונה שלמה."],[1,"ת\"ח בקדמיתא וכו':","בוא וראה, מתחילה עלה במדרגות ממטה למעלה. שכתוב וירא ה' אל אברם. וכתוב לה' הנראה אליו. וזה הוא מדרגה הראשונה, כמו שאמרנו, שה\"ס אבן שלמה, דהיינו מדרגת הנוקבא, (כנ\"ל באות ע') שבה נוהג ראיה. ומכאן השיג נפש. ואחר כך כתוב, הלוך ונסוע הנגבה, דהיינו שהלך מדרגה אחר מדרגה עד שנתעטר בדרום שהוא חסד דז\"א. שהוא חלקו וגורלו, ומכאן השיג רוח. אחר כך, כשעלה יותר למעלה סותם הדבר, ואומר ויבן שם מזבח לה' סתם, ואינו אומר לה' הנראה אליו. (כנ\"ל באות ק\"ס) זה הוא עולם העליון. דהיינו בינה, ומכאן זכה בנשמה, (כנ\"ל באות ק\"ס) ומשם נסע עוד במדרגות. דהיינו שירד למצרים ועלה משם, שבזה השיג מדרגת חכמה שמצד ימין שחסד נעשה לחכמה, כנ\"ל. ואח\"כ ירד ממעלה למטה, כמ\"ש כאן בהכתוב וילך למסעיו כנ\"ל. ונתדבק הכל במקומו כראוי ולהיות."],[2,"והכא כד תסתכל וכו':","וכאן כאשר תסתכל במדרגות שבהכתוב, תמצא כאן סוד חכמה העליונה, דהיינו החכמה שמצד ימין. מה כתוב, \u0003וילך למסעיו מנגב,\u0004 שפירושו מצד ימין, שהוא דרום, והוא התחלה של העליון, דהיינו בינה, הסתום ועמוק למעלה עד אין סוף. פירוש \u0003הנגב,\u0004 שאומר כאן פירושו חכמה שבראש קו ימין, שהוא התחלה ושורש אל הבינה העומדת בראש קו שמאל. שחכמה זו סתומה ועמוקה עד א\"ס. ומשם ירד מדרגה אחר מדרגה ממעלה למטה, מנגב עד בית אל שהיא הנוקבא."],[3,"וכתיב ויקרא וכו':","וכתוב ויקרא שם אברם בשם ה'. דהיינו שהדביק היחוד במקומו כראוי. שכתוב אל מקום המזבח אשר עשה שם בראשונה. מה פירושו של \u0003אשר עשה שם,\u0004 הוא, כי מתחילה העלה את הנוקבא ממטה למעלה, כנ\"ל, ועתה הוריד אותה בהמדרגות, ממעלה למטה כדי שלא תעבור מאלו מדרגות העליונות והן לא תעבורנה ממנה. ויתיחד הכל ביחוד אחד כראוי."],[4,"כדין אתעטר וכו':","אז נתעטר אברהם, ונעשה חלק גורלו ודאי בה'. אשריהם הצדיקים שמתעטרים בהקב\"ה, והוא מתעטר בהם. אשריהם בעולם הזה ואשריהם בעולם הבא עליהם כתוב ועמך כולם צדיקים לעולם ירשו ארץ. וכתוב, ואורח צדיקים כאור נוגה הולך ואור עד נכון היום."],[5,"אזלו כד מטי וכו':","הלכו, כשהגיעו לשדה אחד ישבו. פתח ר\"ש ואמר, פנה אלי וחנני וגו'. מקרא הזה יש להסתכל בו. והרי בארנוהו בכמה מקומות. אבל דברים סתומים יש במקרא הזה. \u0003פנה אלי,\u0004 שואל, וכי דוד שהיה עניו, יאמר פנה אלי וחנני."],[6,"אלא וכו:","ומשיב אלא שאמר זה, בשביל מדרגה שלו שהוא מתעטר בה. דהיינו שהתפלל בשביל הנוקבא דז\"א, \u0003תנה עוזך לעבדך וכו':\u0004 תנה עוזך, זה הוא עז העליון, שהוא חכמה, שכתוב ויתן עז למלכו. מי הוא מלכו, זה הוא מלך סתם שהוא מלך המשיח. דהיינו המלכות שהיא נוקבא דז\"א, (כנ\"ל בראשית א' דף רמ\"א אות רצ\"ג) אף כאן \u0003לעבדך\u0004 הוא מלך המשיח, כמו שאמרנו מלך סתם. דהיינו הנוקבא."],[7,"והושיעה לבן אמתך:","שואל, וכי לא היה בנו של ישי, עד שהיה צריך לומר בשמו של אמו, ולא בשמו של אביו. ומשיב, אלא בארנוהו. כאשר יבא האדם להזכיר עצמו לקבל דבר עליון, הוא צריך לבא בדבר שהוא ברור. וע\"כ הזכיר את אמו, שאמר \u0003לבן אמתך\u0004 ולא לאביו. ועוד הרי למדנו שזהו מלך סתם כמו שאמרנו. כלומר, שלא התפלל בשביל עצמו אלא בשביל הנוקבא הנקראת מלך סתם, וע\"כ הזכיר לאמו, שה\"ס הנוקבא ולא הזכיר לאביו."],[8,"אמר ר\"ש ת\"ח וכו':","אמר ר\"ש בוא וראה מה כתוב, ויהי ריב בין רעי מקנה אברם. \u0003רב\u0004 כתוב חסר \u0003י'.\u0004 יורה, שלוט רצה לחזור לעבודה זרה, שיושבי הארץ עבדו. וסוף הכתוב מוכיח זה. שכתוב והכנעני והפריזי אז יושב בארץ. שזה מלמד שלוט היה רוצה לעבוד ע\"ז כמותם. ומה שאומר \u0003רב\u0004 חסר \u0003י'\u0004 מורה על עבודה זרה. וה\"ס הכתוב \u0003ורב\u0004 יעבוד צעיר. וכן עשו אמר ליעקב יש לי \u0003רב.\u0004 ויעקב אמר לו יש לי כל. וכן ה\"ס וערב \u0003רב\u0004 עלה אתם."],[9,"ומנלן דלוט וכו':","ומאין נשמע שלוט חזר לסורו לעבודה זרה. שכתוב, ויסע לוט מקדם, מהו מקדם. מקדמונו של עולם. כתוב כאן ויסע לוט מקדם, וכתיב ויהי בהנסעם מקדם, מה שם נסעו מקדמונו של עולם, אף כאן כן."],[10,"כיון דידע וכו':","כיון שידע אברהם אשר לוט נטה לבו אחר ע\"ז, מיד ויאמר אברם אל לוט הפרד נא מעלי. אין אתה כדאי להתחבר עמי אז נפרד אברהם ממנו. ולא רצה עוד ללכת להתחבר עמו. כי כל מי שמתחבר לרשע סופו ללכת אחריו ולהענש בשבילו."]],[[0,"","אֶל הַמָּקוֹם אֲשֶׁר הָיָה שָׁם אָהֳלֹה בַּתְּחִלָּה, אָהֳלֹה בְּהֵ\"א. מִי אָהֳלֹה? זֶה בֵּית אֵל. אֶבֶן שְׁלֵמָה, כְּמוֹ שֶׁאָמַרְנוּ. עוֹד רָשַׁם וְאָמַר, אֶל מְקוֹם הַמִּזְבֵּחַ אֲשֶׁר עָשָׂה שָׁם בָּרִאשֹׁנָה, שֶׁכָּתוּב לַה' הַנִּרְאֶה אֵלָיו. וְאָז וַיִּקְרָא שָׁם אַבְרָם בְּשֵׁם ה', אָז נִדְבַּק בָּאֱמוּנָה הַשְּׁלֵמָה."],[1,"","בֹּא רְאֵה, בָּרִאשׁוֹנָה עָלָה מִמַּטָּה לְמַעְלָה, שֶׁכָּתוּב וַיֵּרָא ה' אֶל אַבְרָם, וְכָתוּב לַה' הַנִּרְאֶה אֵלָיו, וְזוֹ הַדַּרְגָּה הָרִאשׁוֹנָה כְּמוֹ שֶׁאָמַרְנוּ אֶבֶן שְׁלֵמָה (מסע נבנה, וכתוב למסעו), וְאַחַר כָּךְ הָלוֹךְ וְנָסוֹעַ הַנֶּגְבָּה, דַּרְגָּה אַחַר דַּרְגָּה, עַד שֶׁהִתְעַטֵּר בַּדָּרוֹם, חֶלְקוֹ וְגוֹרָלוֹ. אַחַר כָּךְ סָתַם הַדָּבָר כְּשֶׁעָלָה וְאָמַר לַה' סְתָם, זֶה הָעוֹלָם הָעֶלְיוֹן, וּמִשָּׁם נָסַע בַּדְּרָגוֹת וְיָרַד מִמַּעְלָה לְמַטָּה, וְהַכֹּל נִדְבַּק בִּמְקוֹמוֹ כָּרָאוּי."],[2,"","וְכָאן כְּשֶׁתִּסְתַּכֵּל בַּדְּרָגוֹת, תִּמְצָא אֶת סוֹד הַחָכְמָה הָעֶלְיוֹנָה. מַה כָּתוּב? וַיֵּלֶךְ לְמַסָּעָיו מִנֶּגֶב. מִצַּד הַיָּמִין, רֵאשִׁית הָעוֹלָם הָעֶלְיוֹן הַנִּסְתָּר הֶעָמֹק לְמַעְלָה עַד אֵין סוֹף. וְיָרַד דַּרְגָּה אַחַר דַּרְגָּה (עד) מִנֶּגֶב וְעַד בֵּית אֵל, מִמַּעְלָה לְמַטָּה."],[3,"","וְכָתוּב וַיִּקְרָא שָׁם אַבְרָם בְּשֵׁם ה'. נִדְבַּק הַיִּחוּד בִּמְקוֹמוֹ כָּרָאוּי, שֶׁכָּתוּב אֶל מְקוֹם הַמִּזְבֵּחַ אֲשֶׁר עָשָׂה שָׁם בָּרִאשֹׁנָה. מַה זֶּה אֲשֶׁר עָשָׂה שָׁם? שֶׁהֶעֱלָה אוֹתָהּ מִמַּטָּה לְמַעְלָה, וְעַכְשָׁו יָרַד בַּדְּרָגוֹת מִמַּעְלָה לְמַטָּה כְּדֵי שֶׁלֹּא תָזוּז מֵאוֹתָן הַדְּרָגוֹת הָעֶלְיוֹנוֹת וְהֵם לֹא יָזוּזוּ מִמֶּנָּה, וְיִתְיַחֵד הַכֹּל בְּיִחוּד אֶחָד כָּרָאוּי."],[4,"","אָז הִתְעַטֵּר אַבְרָהָם וְהָיָה לְחֵלֶק גּוֹרָלוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וַדַּאי. אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁמִּתְעַטְּרִים בַּקָּדוֹשׁ בָּרוּךְ הוּא וְהוּא מִתְעַטֵּר בָּהֶם. אַשְׁרֵיהֶם בָּעוֹלָם הַזֶּה וְאַשְׁרֵיהֶם בָּעוֹלָם הַבָּא. עֲלֵיהֶם כָּתוּב (ישעיה ס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ, וְכָתוּב (משלי ד) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ הוֹלֵךְ וָאוֹר עַד נְכוֹן הַיּוֹם."],[5,"","הָלְכוּ, כְּשֶׁהִגִּיעוּ לְשָׂדֶה אֶחָד יָשְׁבוּ. פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (תהלים כה) פְּנֵה אֵלַי וְחָנֵּנִי. בַּפָּסוּק הַזֶּה יֵשׁ לְהִסְתַּכֵּל בּוֹ, וַהֲרֵי בֵּאַרְנוּ אוֹתוֹ בְּכַמָּה מְקוֹמוֹת. אֲבָל בַּפָּסוּק הַזֶּה דְּבָרִים נִסְתָּרִים יֵשׁ בּוֹ. פְּנֵה אֵלַי - וְכִי דָוִד אָמַר פְּנֵה אֵלַי וְחָנֵּנִי?"],[6,"","אֶלָּא בַּעֲבוּר דַּרְגָּתוֹ שֶׁהוּא מִתְעַטֵּר בָּהּ הוּא אָמַר. (שם פו) תְּנָה עֻזְּךְ לְעַבְדֶּךְ - תְּנָה עֻזְּךְ זֶה הָעֹז הָעֶלְיוֹן, כַּכָּתוּב (שמואל א ב) וְיִתֵּן עֹז לְמַלְכּוֹ. מִי מַלְכּוֹ? זֶה מֶלֶךְ סְתָם, מֶלֶךְ הַמָּשִׁיחַ. אַף כָּאן לְעַבְדֶּךְ זֶה מֶלֶךְ הַמָּשִׁיחַ, כְּמוֹ שֵׁאָמַרְנוּ מֶלֶךְ סְתָם."],[7,"","וְהוֹשִׁיעָֹה לְבֶן אֲמָתֶךְ - וְכִי לֹא הָיָה בֶן יִשַׁי הוּא, עַד שֶׁאָמַר בַּשֵּׁם שֶׁל אִמּוֹ וְלֹא בַּשֵּׁם שֶׁל אָבִיו? אֶלָּא הִנֵּה הֵקַמְנוּ, שֶׁכַּאֲשֶׁר יָבֹא אָדָם לְקַבֵּל דָּבָר עֶלְיוֹן לְהַזְכִּיר, צָרִיךְ לָלֶכֶת בְּדָבָר שֶׁהוּא וַדַּאי, וְעַל כֵּן הִזְכִּיר אֶת אִמּוֹ וְלֹא אֶת אָבִיו. וְעוֹד, הִנֵּה שָׁנִינוּ (שהרי) שֶׁזֶּה מֶלֶךְ כְּפִי שֶׁאָמַרְנוּ."],[8,"","אָמַר רַבִּי שִׁמְעוֹן, בּא רְאֵה מַה כָּתוּב. וַיְהִי רִיב בֵּין רֹעֵי מִקְנֵה אַבְרָם, רִב כָּתוּב חָסֵר יוֹ\"ד. שֶׁרָצָה לוֹט לַחֲזֹר לַעֲבוֹדָה הַזָּרָה שֶׁעוֹבְדִים יוֹשְׁבֵי הָאָרֶץ, וְסוֹף הַכָּתוּב מוֹכִיחַ, שֶׁכָּתוּב וְהַכְּנַעֲנִי וְהַפְּרִזִּי אָז יֹשֵׁב בָּאָרֶץ."],[9,"","וּמִנַּיִן לָנוּ שֶׁלּוֹט חָזַר לְסוּרוֹ הָרָע לַעֲבוֹדָה זָרָה? שֶׁכָּתוּב וַיִּסַּע לוֹט מִקֶּדֶם. מַהוּ מִקֶּדֶם? מִקַּדְמוֹנוֹ שֶׁל עוֹלָם. כָּתוּב כָּאן וַיִּסַּע לוֹט מִקֶּדֶם, וְכָתוּב וַיְהִי בְּנָסְעָם מִקֶּדֶם. מַה לְּהַלָּן נְסִיעָה מִקַּדְמוֹנוֹ שֶׁל עוֹלָם - אַף כָּאן כֵּן."],[10,"","כֵּיוָן שֶׁיָּדַע אַבְרָהָם שֶׁלְּכָךְ נָטָה לִבּוֹ שֶׁל לוֹט, מִיָּד - וַיֹּאמֶר אַבְרָם אֶל לוֹט וְגוֹ' הִפָּרֶד נָא מֵעָלָי. אֵינְךְ כְּדַאי לְהִתְחַבֵּר עִמִּי. אָז נִפְרַד מִמֶּנּוּ אַבְרָהָם וְלֹא רָצָה לָלֶכֶת וּלְהִתְחַבֵּר עִמּוֹ, שֶׁכָּל מִי שֶׁמִּתְחַבֵּר לָרָשָׁע, סוֹפוֹ לָלֶכֶת אַחֲרָיו וּלְהֵעָנֵשׁ בִּגְלָלוֹ."]]],[["מְנָלָן מִיהוֹשָׁפָט דְּאִתְחַבַּר עִם אַחְאָב וְאִלְמָלֵא זְכוּ דְּאֲבָהָן אִתְעַנַּשׁ תַּמָּן דִּכְתִיב, (דברי הימים ב י״ח:ל״א) וַיִּזְעַק יְהוֹשָׁפָט. וּכְדֵין אִשְׁתְּזִיב דִּכְתִיב וַיְסִיתֵם אֱלהִים מִמֶּנּוּ.","וְעַל דָּא לָא בָּעָא אַבְרָם לְמֵיהַךְ בַּהֲדֵיהּ דְּלוֹט. וְעִם כָּל דָּא לָא בָּעָא לוֹט לְמֶהדַר מִסּוּרְחָנֵיהּ אֶלָּא וַיִּבְחַר לוֹ לוֹט אֶת כָּל כִּכַּר הַיַּרְדֵּן. וַיִּסַּע לוֹט מִקֶּדֶם אִתְנְטִיל מִן קַדְמָאָה דְעָלְמָא וְלָא בָּעָא לְאִתְדַּבְּקָא בִּמְהֵימְנוּתָא שְׁלֵימָתָא כְּאַבְרָהָם.","אַבְרָם יָשַׁב בְּאֶרֶץ כְּנָעַן. לְאִתְדַּבְּקָא בְּאַתְרָא דִּמְהֵימְנוּתָא וּלְמִנְדַע חָכְמְתָא לְאִתְדַּבְּקָא בְּמָארֵיהּ. וְלוֹט יָשַׁב בְּעָרֵי הַכִּכָּר וַיֶּאֱהַל עַד סְדוֹם. עִם אִנּוּן חַיָּיבִין דְּעָלְמָא דְּנַפְקוּ מִגּוֹ מְהֵימְנוּתָא דִּכְתִיב וְאַנְשֵׁי סְדוֹם רָעִים וְחַטָּאִים לַיְיָ מְאֹד. כָּל חַד אִתְפְּרַשׁ לְאָרְחֵיהּ כְּדְקָא יְאוּת. בְגִין כָּךְ זַכָּאִין אִנּוּן חַבְרַיָיא דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא יְמָמָא וְלֵילְיָא, וְחַבְרוּתָא דִלְהוֹן בְּקוּדְשָׁא בְּרִיךְ הוּא. וְעֲלַיְיהוּ כְּתִיב, (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּיְיָ אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם:","וַיְיָ אָמַר אֶל אַבְרָם אַחֲרֵי הִפָּרֶד לוֹט מֵעִמּוֹ וְגו'. רַבִּי אַבָּא פָּתַח (יונה א׳:ג׳) וַיָּקָם יוֹנָה לִבְרוֹחַ תַּרְשִׁישָׁה מִלִּפְנִי יְיָ וְגו'. וַוי לְמַאן דְּאִסְתַּתַּר מִקַּמֵּי קוּדְשָׁא בְּרִיךְ הוּא דִּכְתִיב בֵּיהּ (ירמיהכג) הֲלא אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ אֲנִי מָלֵא נְאֻם יְיָ וְהוּא אָתֵי לְמֶעֱרַק מִקַּמֵּיהּ.","אֶלָּא כְּתִיב, (שיר השירים ב׳:י״ד) יוֹנָתִי בְּחַגְוֵי הַסֶּלַע בְּסֵתֶר הַמַּדְרֵגָה. יוֹנָתִי דָּא כְּנֶסֶת יִשְׂרָאֵל. בְּחַגְוֵי הַסֶּלַע דָּא יְרוּשְׁלֵם דְּאִיהִי סָלְקָא עַל כָּל עָלְמָא. מַה סֶּלַע אִיהִי עִלָּאָה וְתַקִּיפָא עַל כֻּלָּא אוּף יְרוּשְׁלֵם אִיהִי עִלָּאָה וְתַקִּיפָא עַל כֹּלָּא. בְּסֵתֶר הַמַּדְרֵגָה דָּא (בית המקדש) אֲתַר דְּאִקְרֵי בֵּית קֹדֶשׁ הַקֳּדָשִׁים לִבָּא דְּכָל עָלְמָא.","וּבְגִין כָּךְ כְּתִיב בְּסֵתֶר הַמַּדְרֵגָה בְּגִין דְּתַמָּן הֲוַת שְׁכִינְתָּא מִסְתַּתְּרָא כְּאִתְּתָא דְּאִיהִי צְנוּעָה לְבַעֲלָהּ וְלָא נָפְקָא מִבֵּיתָא לְבַר. כְּמָה דְאַתְּ אָמַר (תהילים קכ״ח:ג׳) אֶשְׁתְּךָ כְּגֶפֶן פּוֹרִיָה בְּיַרְכְּתֵי בֵיתֶךָ וְגו'. כָּךְ כְּנֶסֶת יִשְׂרָאֵל לָא שָׁרְיָיא לְבַר מֵאַתְרָהָא בִּסְתִירוּ דְּדַרְגָּא אֶלָּא בְּזִמְנָא דְגָלוּתָא דְּאִיהוּ בְּגוֹ גָּלוּתָא, וּבְגִין דְּאִיהִי בְּגָלוּתָא, שְׁאָר עַמִּין אִית לוֹן טִיבוּ וְשַׁלְוָה יַתִּיר.","תָּא חֲזֵי בְּזִמְנָא דְיִשְׂרָאֵל שַׁרְיָין עַל אַרְעָא קַדִּישָׁא כֹּלָּא הֲוָה מִתְתַּקַּן כְּדְקָא יְאוּת, וְכֻּרְסְיָיא שְׁלִים עֲלַיְיהוּ, וְעַבְדֵּי פּוּלְחָנָא וּבָקַע אֲוִירִין דְּעָלְמָא וְסָלִיק הַהוּא פּוּלְחָנָא לְעֵילָא לְאַתְרֵיהּ, בְּגִין דְּאַרְעָא לָא אִתְתַּקְנַת לְפוּלְחָנָא אֶלָּא לְיִשְׂרָאֵל בִּלְחוֹדַיְיהוּ. וּבְגִין כָּךְ שְׁאָר עַמִין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת הֲווּ מִתְרַחֲקֵי דְּלָא הֲווּ שָׁלְטִין בָּהּ כִּדְהַשְׁתָּא בְּגִין דְּלָא אִתְזָנוּ אֶלָּא מִתַּמְצִית.","וְאִי תֵימָא הָא חָמֵינָן כַּמָּה מַלְכִין הֲווּ דְּשַׁלִּיטִין בְּזִמְנָא דְּבֵית הַמִּקְדָּשׁ קַיָּים עַל עָלְמָא. תָּא חֲזֵי, בְּבַיִת רִאשׁוֹן עַד לָא סְאִיבוּ יִשְׂרָאֵל אַרְעָא, לָא הֲווּ שָׁלְטִין שְׁאָר עַמִין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת אֶלָּא אִתְזָנוּ מִתַּמְצִית וּבָהּ הֲווּ שָׁלְטִין וְלָאו כָּל כָּךְ. כֵּיוָן דְּחָבוּ יִשְׂרָאֵל וְסָאִיבוּ אַרְעָא כְּדֵין כִּבְיָכוֹל דָּחוּ לָהּ לִשְׁכִינְתָּא מֵאַתְרָהּ וְאִתְקָרְבַת לְדוּכְתָּא אָחֳרָא, וּכְדֵין שָׁלְטִין שְׁאָר עַמִין וְאִתְיְיהִיב לוֹן רְשׁוּ לְשַׁלְטָאָה.","תָּא חֲזֵי, אַרְעָא דְיִשְׂרָאֵל לָא שַׁלִּיט עֲלָהּ מְמַנָּא אָחֳרָא בַּר קוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי. וּבְשַׁעֲתָא דְּחָאבוּ יִשְׂרָאֵל וְהֲווּ מְקַטְרִין לְטַעֲוָון אָחֳרָנִין בְּגוֹ אַרְעָא, כִּבְיָכוֹל אִדַּחְיָיא שְׁכִינְתָא מֵאַתְרָהּ וּמָשְׁכֵי וּמְקַטְרֵי לְאִתְקַשְׁרָא טַעֲוָון אָחֳרָן גּוֹ שְׁכִינְתָּא, וּכְדֵין אִתְיְיהִיב לוֹן שָׁלְטָנוּתָא, בְּגִין דִּקְטֹרֶת קִטְרָא הוּא לְאִתְקַטָּרָא. וּכְדֵין שָׁלְטוּ שְׁאָר עַמִּין, וּבָטְלוּ נְבִיאִים, וְכָל אִנּוּן דַּרְגִּין עִלָּאִין לָא שָׁלְטוּ בְּאַרְעָא.","וְלָא אַעֲדִיוּ שָׁלְטָנוּתָא דִּשְׁאָר עַמִּין בְּגִין דְּאִנּוּן מָשְׁכוּ לִשְׁכִינְתָּא לְגַבַּיְיהוּ. וְעַל דָּא בְּבֵית שֵׁנִי הָא שׁוּלְטָנוּתָא מִשְׁאָר עַמִין לָא אַעֲדִיוּ וְכָל שֶׁכֵּן בְּגָלוּתָא דִּשְׁכִינְתָּא בִּשְׁאָר עַמִּין אֲתַר דִּשְׁאָר מְמַנָּן שָׁלְטִין וּבְגִין כָּךְ כֻּלְהוּ יַנְקִין מִן שְׁכִינְתָּא דְּאִתְקְרִיבַת גַּבַּיְהוּ."],[[0,"מנלן מיהושפט וכו':","מאין לנו זה, מיהושפט שנתחבר עם אחאב. ואלמלא זכות אבות שהיה לו, היה נענש בשבילו, שכתוב ויצעק יהושפט וגו' ואז נצל שכתוב ויסיתם אלקים ממנו."],[1,"ועל דא לא בעא אברם וכו':","וע\"כ לא רצה אברהם ללכת עם לוט. ועם כל זה לא רצה לוט לחזור מחטאו, אלא ויבחר לו לוט וגו' ויסע לוט מקדם, שפירושו, שנסע מקדמונו של עולם, ולא רצה להדבק באמונה השלימה כמו אברהם."],[2,"אברם ישב בארץ כנען:","ארץ כנען ה\"ס הנוקבא, והכתוב אברם ישב בארץ כנען, פירושו, כדי להתדבק במקום האמונה שה\"ס הנוקבא, ולדעת חכמת רבונו. ולוט ישב בערי הככר ויאהל עד סדום, דהיינו שנתחבר עם רשעי עולם האלו שיצאו מן האמונה, שכתוב עליהם, ואנשי סדום רעים וחטאים לה' מאד, כל אחד נפרד לדרכו כראוי לו, אברהם לקדושה ולוט לרשעי עולם, בשביל זה אשריהם החברים. שעוסקים בתורה יום ולילה והתחברותם הוא בהקב\"ה, דהיינו שעושים כמעשה אברהם ולא כמעשה לוט. ועליהם כתוב, ואתם הדבקים בה' אלקיכם חיים כלכם היום."],[3,"וה' אמר אל אברם אחרי הפרד לוט","וגו': ר' אבא פתח, ויקם יונה לברוח תרשישה מלפני ה' וגו' ווי למי שמסתיר עצמו מלפני הקב\"ה, שכתוב בו, הלא את השמים ואת הארץ אני מלא נאם ה'. ומתמה, ויונה בא לברוח מלפני הקב\"ה."],[4,"אלא כתיב יונתי וכו':","ומשיב אלא כתוב יונתי בחגוי הסלע בסתר המדרגה. \u0003יונתי,\u0004 היא כנסת ישראל, דהיינו השכינה. \u0003בחגוי הסלע\u0004 היא ירושלים, שהוא גבוה מכל העולם. מה סלע הוא גבוה וחזק מכל, אף ירושלים היא גבוה וחזקה מכל. בסתר המדרגה זהו המקום שנקרא בית קדש הקדשים שהוא הלב של כל העולם."],[5,"ובג\"כ כתיב וכו':","ועל כן כתוב, בסתר המדרגה, על הקדש קדשים, משום שהשכינה היתה מסתרת עצמה שם, כאשה שהיא צנועה לבעלה, ואינה יוצאת מביתה לחוץ. כמו שאתה אומר, אשתך כגפן פוריה בירכתי ביתך, כך כנסת ישראל אינה שורה מחוץ למקומה, שהוא בסתר המדרגה, אלא בזמן הגלות, שהיא בתוך הגלות. ומשום שהיא בתוך הגלות, ע\"כ שאר האומות יש להם טובה ושלוה יותר מישראל. פירוש, בית המקדש ה\"ס הנוקבא. וכתוב, והבדילה הפרכת לכם בין הקדש ובין קדש הקדשים. כי הפרכת ה\"ס הפרסא שבמקום החזה המבדילה בין מחזה ולמטה, ששם החסדים מגולים בהארת חכמה, שה\"ס הקדש, ובין מחזה ולמעלה, ששם החסדים מכוסים ונעלמים מהארת חכמה, שה\"ס קדש הקדשים, וע\"כ נקרא קדש הקדשים בשם סתר המדרגה, כי החכמה מסתתרת שם ואינה מתגלית. אמנם מקום הזווג אינה אלא בבחינת מחזה ולמעלה, (כנ\"ל בראשית א' דף פ\"ו ד\"ה וזה אמרו) דהיינו במקום קדש הקדשים. וז\"ש \u0003דתמן הות שכינתא מסתתרא כאתתא דאיהי צנועה לבעלה, ולא נפקא מביתא לבר,\u0004 כי אין פני אדם אלא שם, כנ\"ל ע\"ש."],[6,"ת\"ח בזמנא","וכו': בא וראה, בשעה שישראל שרוים בארץ הקדושה הכל היה מתוקן כראוי, והכסא שהוא הנוקבא היה שלם עליהם, כלומר, שהיתה כסא שלם לישראל העליון ועבדו עבודת השם, דהיינו שהעלו מ\"ן, ובקעו אוירים של העולם, והעבודה עלתה למעלה למקומה לזו\"ן, וגרמו להם זווג. כי הארץ אינה מתוקנת לעבודה רק לישראל בלבדם. ועל כן שאר האומות היו מתרחקים מהארץ, שלא היו שולטים בה כמו עתה, כי לא היו נזונים אלא מתמצית, כלומר השפע שהמשיכו ישראל ע\"י עבודתם, השלים גם את אומות העולם, אבל עיקר השפע הגיע לישראל, והאומות קבלו רק תמצית מהשפע, לפיכך היתה הממשלה לישראל."],[7,"ואי תימא הא וכו':","ואם תאמר הרי אנו רואים כמה מלכי האומות היו שולטים גם בזמן שהיה בית המקדש קים בעולם. בא וראה, בבית ראשון, טרם שטמאו ישראל את הארץ, לא היו שולטים שאר האומות כל כך, אלא שניזונו מתמצית, ומתמצית הזה היתה שליטתם אז, וע\"כ לא היתה שליטתם חזקה כל כך, כיון שחטאו ישראל וטימאו את הארץ, אז, כביכול, דחו את השכינה ממקומה, ונתקרבת למקום אחר, ואז שלטו שאר האומות, כי ניתן להם רשות לשלוט."],[8,"ת\"ח ארעא דישראל","וכו': בוא וראה ארץ ישראל, ממונה אחר אינו שולט עליה חוץ מהקב\"ה בלבדו. ובשעה שחטאו ישראל, והיו מקטרים בתוך הארץ לאלהים אחרים, נדחה כביכול השכינה ממקומה, כי היו מושכים ומקטרים לאלהים אחרים שיתקשרו בהשכינה, ואז ניתן להם השליטה. הקטרת עושה קשר להתקשר וע\"כ ינקו מהשכינה וקבלו ממנה השליטה, ואז שלטו שאר האומות, ונתבטלו הנביאים. וכל אלו מדרגות העליונות לא שלטו בהארץ."],[9,"ולא אעריו וכו':","ולא הוסרה השליטה משאר האומות, משום שמשכו אצלם את שפע השכינה. ועל כן בבית שני לא הוסרה השליטה משאר האומות, ומכל שכן בזמן הגלות, ששפע השכינה היא בשאר האומות במקום ששאר הממונים שולטים, וע\"כ יונקים כולם מהשכינה שנתקרבה אליהם."]],[[0,"","מִנַּיִן לָנוּ? מִיהוֹשָׁפָט שֶׁהִתְחַבֵּר עִם אַחְאָב, וְאִלְמָלֵא זְכוּת אָבוֹת נֶעֱנַשׁ שָׁם, שֶׁכָּתוּב (דברי הימים ב יח) וַיִּזְעַק יְהוֹשָׁפָט. וְאָז נִצַּל, שֶׁכָּתוּב וַיְסִיתֵם אֱלֹהִים מִמֶּנּוּ,"],[1,"","וְעַל כֵּן לֹא רָצָה אַבְרָם לָלֶכֶת עִם לוֹט. וְעִם כָּל זֶה לֹא רָצָה לוֹט לַחֲזֹר מִסּוּרוֹ הָרָע, אֶלָּא וַיִּבְחַר לוֹ לוֹט אֵת כָּל כִּכַּר הַיַּרְדֵּן וַיִּסַּע לוֹט מִקֶּדֶם. נָסַע מִקַּדְמוֹנוֹ שֶׁל הָעוֹלָם, וְלֹא רָצָה לִדְבֹּק בָּאֱמוּנָה הַשְּׁלֵמָה כְּמוֹ אַבְרָהָם."],[2,"","אַבְרָם יָשַׁב בְּאֶרֶץ כְּנָעַן, לְהִדָּבֵק בִּמְקוֹם הָאֱמוּנָה וְלָדַעַת הַחָכְמָה לְהִדָּבֵק בְּרִבּוֹנוֹ. וְלוֹט יָשַׁב בְּעָרֵי הַכִּכָּר וַיֶּאֱהַל עַד סְדם, עִם אוֹתָם הָרְשָׁעִים שֶׁל הָעוֹלָם שֶׁיָּצְאוּ מִתּוֹךְ הָאֱמוּנָה, שֶׁכָּתוּב וְאַנְשֵׁי סְדם רָעִים וְחַטָּאִים לַה' מְאֹד. כָּל אֶחָד נִפְרַד לְדַרְכּוֹ כָּרָאוּי. מִשּׁוּם כָּךְ אַשְׁרֵיהֶם הַחֲבֵרִים שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה יוֹמָם וָלַיְלָה, וְהַחֲבֵרוּת שֶׁלָּהֶם עִם הַקָּדוֹשׁ בָּרוּךְ הוּא, וַעֲלֵיהֶם כָּתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם."],[3,"","וַה' אָמַר אֶל אַבְרָם אַחֲרֵי הִפָּרֶד לוֹט מֵעִמּוֹ וְגוֹ'. רַבִּי אַבָּא פָּתַח, (יונה א) וַיָּקָם יוֹנָה לִבְרֹחַ תַּרְשִׁישָׁה מִלִּפְנֵי ה' וְגוֹ'. אוֹי לְמִי שֶׁמִּסְתַּתֵּר מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב בּוֹ (ירמיה כג) הֲלוֹא אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ אֲנִי מָלֵא נְאֻם ה', וְהוּא בָּא לִבְרֹחַ מִלְּפָנָיו?!"],[4,"","אֶלָּא כָּתוּב (שיר ג) יוֹנָתִי בְּחַגְוֵי הַסֶּלַע בְּסֵתֶר הַמַּדְרֵגָה. יוֹנָתִי - זוֹ כְּנֶסֶת יִשְׂרָאֵל. בְּחַגְוֵי הַסֶּלַע - זוֹ יְרוּשָׁלַיִם שֶׁהִיא עוֹלָה עַל כָּל הָעוֹלָם. מָה הַסֶּלַע הוּא עֶלְיוֹן וְחָזָק עַל הַכֹּל, אַף יְרוּשָׁלַיִם הִיא עֶלְיוֹנָה וַחֲזָקָה עַל הַכֹּל. בְּסֵתֶר הַמַּדְרֵגָה - זֶה (בית המקדש) הַמָּקוֹם שֶׁנִּקְרָא בֵּית קָדְשֵׁי הַקְּדָשִׁים, הַלֵּב שֶׁל כָּל הָעוֹלָם."],[5,"","וּמִשּׁוּם כָּךְ כָּתוּב בְּסֵתֶר הַמַּדְרֵגָה, מִשּׁוּם שֶׁשָּׁם הָיְתָה הַשְּׁכִינָה נִסְתֶּרֶת, כְּמוֹ אִשָּׁה שֶׁהִיא צְנוּעָה לְבַעְלָהּ וְאֵין יוֹצֵאת מִבֵּיתָהּ הַחוּצָה, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קכח) אֶשְׁתְּךְ כְּגֶפֶן פּוֹרִיָּה בְּיַרְכְּתֵי בֵיתֶךְ וְגוֹ'. כָּךְ כְּנֶסֶת יִשְׂרָאֵל אֵינָהּ שׁוֹרָה מִחוּץ לִמְקוֹמָהּ בְּסֵתֶר הַמַּדְרֵגָה אֶלָּא בִּזְמַן שֶׁל הַגָּלוּת שֶׁהִיא בְּתוֹךְ הַגָּלוּת. וּמִשּׁוּם שֶׁהִיא בַּגָּלוּת, לִשְׁאָר הָעַמִּים יֵשׁ טוֹבָה וְשַׁלְוָה יוֹתֵר."],[6,"","בֹּא רְאֵה, בִּזְמַן שֶׁיִּשְׂרָאֵל שׁוֹרִים בָּאָרֶץ הַקְּדוֹשָׁה, הַכֹּל הָיָה מְתֻקָּן כָּרָאוּי, וְהַכִּסֵּא שָׁלֵם עֲלֵיהֶם, וְעוֹשִׂים אֶת הָעֲבוֹדָה, וּבוֹקֵעַ הָאֲוִירִים שֶׁל הָעוֹלָם. וְאוֹתָהּ הָעֲבוֹדָה עוֹלָה לְמַעְלָה בִּמְקוֹמָהּ, מִשּׁוּם שֶׁהָאָרֶץ לֹא הִתְתַּקְּנָה לָעֲבוֹדָה אֶלָּא לְיִשְׂרָאֵל לְבַדָּם. וּמִשּׁוּם כָּךְ שְׁאָר הָעַמִּים עוֹבְדֵי עַכּוּ\"ם הָיוּ מִתְרַחֲקִים, שֶׁלֹּא הָיוּ שׁוֹלְטִים בָּהּ כְּמוֹ עַכְשָׁו, מִשּׁוּם שֶׁלֹּא נִזּוֹנוּ אֶלָּא מֵהַתַּמְצִית."],[7,"","וְאִם תֹּאמַר, הֲרֵי רָאִינוּ כַּמָּה מְלָכִים הָיוּ שֶׁשָּׁלְטוּ בִּזְמַן שֶׁבֵּית הַמִּקְדָּשׁ קַיָּם עַל הָעוֹלָם - בֹּא רְאֵה, בְּבַיִת רִאשׁוֹן, כְּשֶׁטֶּרֶם טִמְּאוּ יִשְׂרָאֵל אֶת הָאָרֶץ, לֹא הָיוּ שׁוֹלְטִים שְׁאָר הָעַמִּים עוֹבְדֵי עַכּוּ\"ם, אֶלָּא נִזּוֹנוּ מִן הַתַּמְצִית, וּבָהּ הָיוּ שׁוֹלְטִים וְלֹא כָּל כָּךְ. כֵּיוָן שֶׁחָטְאוּ יִשְׂרָאֵל וְטִמְּאוּ אֶת הָאָרֶץ, אָז כִּבְיָכוֹל דָּחוּ אֶת הַשְּׁכִינָה מִמְּקוֹמָהּ, וְהִתְקָרְבָה לַמָּקוֹם הָאַחֵר, וְאָז שָׁלְטוּ שְׁאָר הָעַמִּים וְנִתְּנָה לָהֶם הָרְשׁוּת לִשְׁלֹט."],[8,"","בֹּא רְאֵה, עַל אֶרֶץ יִשְׂרָאֵל לֹא שׁוֹלֵט מְמֻנֶּה אַחֵר פְּרָט לַקָּדוֹשׁ- בָּרוּךְ-הוּא לְבַדּוֹ. וּבְשָׁעָה שֶׁחָטְאוּ יִשְׂרָאֵל וְהָיוּ מְקַטְּרִים לָעֲבוֹדָה הַזָּרָה שֶׁבְּתוֹךְ הָאָרֶץ, כִּבְיָכוֹל נִדְחֲתָה הַשְּׁכִינָה מִמְּקוֹמָהּ, וּמוֹשְׁכִים וּמְקַטְּרִים לִקְשֹׁר עֲבוֹדָה זָרָה לְתוֹךְ הַשְּׁכִינָה, וְאָז נִתְּנָה לָהֶם הַשְּׁלִיטָה, מִשּׁוּם שֶׁקְּטֹרֶת הִיא קֶשֶׁר לְהִתְקַשֵּׁר, וְאָז שָׁלְטוּ שְׁאָר הָעַמִּים וּבָטְלוּ נְבִיאִים, וְכָל אוֹתָן הַדְּרָגוֹת הָעֶלְיוֹנוֹת לֹא שָׁלְטוּ בָאָרֶץ."],[9,"","וְלֹא הֵסִירוּ אֶת שְׁלִיטַת שְׁאָר הָעַמִּים, מִשּׁוּם שֶׁהֵם מָשְׁכוּ אֶת הַשְּׁכִינָה אֲלֵיהֶם. וְעַל זֶה הִנֵּה בְּבַיִת שֵׁנִי לֹא סָרָה הַשְּׁלִיטָה מִשְּׁאָר הָעַמִּים, וְכָל שֶׁכֵּן בַּגָּלוּת שֶׁשְּׁכִינָה בִּשְׁאָר הָעַמִּים, הַמָּקוֹם שֶׁשָּׁם שׁוֹלְטִים שְׁאָר הַמְמֻנִּים. וּמִשּׁוּם כָּךְ כֻּלָּם יוֹנְקִים מִן הַשְּׁכִינָה שֶׁנִּקְרֶבֶת אֲלֵיהֶם."]]],[["וְעַל דָּא בְּזִמְנָא דְּיִשְׂרָאֵל הֲווּ שָׁרָאן עַל אַרְעָא וּפָלְחֵי פּוּלְחָנָא דְקוּדְשָׁא בְּרִיךְ הוּא, שְׁכִינְתָּא הֲוַת צְנוּעָה בֵּינַיְיהוּ וְלָא נָפְקַת מִגּוֹ בֵּיתָא לְבַר בְּאִתְגַּלְיָיא. וּבְגִין כָּךְ כָּל אִנּוּן נְבִיאִים דְּהֲווּ בְּהַהוּא זִמְנָא לָא נָטְלוּ נְבוּאָה אֶלָּא בְּאַתְרָהּ כִּדְקָאֲמָרָן. וּבְגִין כָּךְ יוֹנָה הֲוָה עָרַק לְבַר מֵאַרְעָא קַדִּישָׁא, דְּלָא יִתְגְּלֵי עֲלֵיהּ נְבוּאָה וְלָא יְהַךְ בִּשְׁלִיחוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא.","וְאִי תֵימָא הָא חָמִינָן דְּאִתְגַּלְּיָיא שְׁכִינְתָּא בְּבָבֶל דְּאִיהוּ לְבַר. הָא אוֹקִימְנָא דִּכְתִיב, (יחזקאל א) הָיֹה הָיָה, דְּהֲוָה מַה דְּלָא הֲוָה מִן קַדְמַת דְּנָא מִיּוֹמָא דְאִתְבְּנִי בֵּי מַקְדְּשָׁא, וְהַהִיא נְבוּאָה לְשַׁעֲתָא הֲוַת","וּכְתִיב עַל נְהַר כְּבָר, נָהָר דִּכְבָר הֲוָה מִיּוֹמָא דְאִתְבְּרֵי עָלְמָא, וּשְׁכִינְתָּא אִתְגַּלְּיָיא תָּדִיר עֲלֵיהּ דִּכְתִיב, (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן וּמִשָּׁם יִפָּרֶד וְגו'. (שם האחד וגו) וְדָא אִיהוּ חַד מִינַיְיהוּ.","וְתַמָּן אִתְגַּלְּיָיא שְׁכִינְתָּא לְפוּם שַׁעֲתָא דְּאִצְטְרִיכוּ לָהּ יִשְׂרָאֵל לְפוּם צַעֲרַיְיהוּ. אֲבָל בְּזִמְנָא אָחֳרָא לָא אִתְגַּלְּיָיא. וּבְגִין כָּךְ יוֹנָה בְּגִין דְּלָא תִשְׁרֵי עֲלוֹי שְׁכִינְתָּא וְלָא תִתְגְּלֵי עֲלֵיהּ, אָזַל מֵאַרְעָא קַדִּישָׁא וְעֲרַק. הֲדָא הוּא דִכְתִיב (יונה א׳:י׳) מִלִּפְנֵי יְיָ. וּכְתִיב כִּי יָדְעוּ הָאֲנָשִׁים כִּי מִלִּפְנִי יְיָ הוּא בּוֹרֵחַ.","תָּא חֲזֵי, כְּמָּה דִּשְׁכִינְתָּא לָא אִתְגַּלְּיָא אֶלָּא בְּאַתְרָא דְּאִתְחֲזֵי לָהּ, אוּף הָכִי לָא אִתְחֲזֵי וְלָא אִתְגַּלְּיָא אֶלָּא בְּבַּר נָשׁ דְּאִתְחֲזֵי לָהּ. דְּהָא מִן יוֹמָא דְּסָלִיק עַל רְעוּתֵיהּ דְּלוֹט לְאִתְהַפְּכָא בְּסֻרְחָנֵיהּ, אִסְתַּלְקַת רוּחָא קַדִּישָׁא מֵאַבְרָהָם. וְכַד אִסְתַּלַּק לוֹט מִנֵּיהּ, מִיָּד שָׁרָא רוּחַ קוּדְשָׁא בְּדוּכְתֵּיהּ הֲדָא הוּא דִכְתִיב וַיְיָ אָמַר אֶל אַבְרָם אַחֲרֵי הִפָּרְד לוֹט מֵעִמּוֹ וְגו'.","תָּא חֲזֵי, כֵּיוָן דְּחָמָא אַבְרָהָם דְּלוֹט הֲוָה תָּב לְסֻרְחָנֵיהּ, הֲוָה דָּחִיל אַבְרָהָם. אָמַר דִּילְמָא חַס וְשָׁלוֹם בְּגִין חַבְרוּתָא דְדָא אֲבִידְנָא בְּגִינֵיהּ חוּלָקָא קַדִּישָׁא דְּאַעֲטַר לִי קוּדְשָׁא בְּרִיךְ הוּא. כֵּיוָן דְּאִתְפְּרַשׁ מִנֵּיהּ אָמַר לֵיהּ שָׂא נָא עֵינֶיךָ וּרְאֵה מִן הַמָּקוֹם אֲשֶׁר אַתָה שָׁם.","מַאי מִן הַמָּקוֹם אֲשֶׁר אַתָּה שָׁם דְּאִתְדַּבְּקַת בֵּיהּ בְּקַדְמִיתָא וְאִתְעַטְּרַת בְּהֵימְנוּתָא שְׁלֵימָתָא. צָפוֹנָה וָנֶגְבָּה וָקֵדְמָה וְיָמָה. אִלֵּין אִנּוּן מַסָּעָיו דְּהֲווּ בְּקַדְמִיתָא דִּכְתִיב וַיֵּלֶךְ לְמַסָּעָיו. וּכְתִיב הָלוֹךְ וְנָסוֹעַ הַנֶּגְבָּה. אִלֵּין דַּרְגִּין עִלָּאִין דְּאִתְעַטַּר בִּמְהֵימְנוּתָא שְׁלֵימָתָא בְּקַדְמִיתָא.","וּכְדֵין אִתְבַּשַּׂר דְּלָא יַעֲדֵי מִנֵּיהּ וּמִן בְּנוֹי לְעָלְמִין דִּכְתִיב כִּי אֶת כָּל הָאָרֶץ אֲשֶׁר אַתָּה רוֹאֶה. מַאי אֲשֶׁר אַתָּה רוֹאֶה. דָּא דַּרְגָּא קַדְמָאָה דְּאִתְגַּלְּיָא לֵיהּ כְּמָא דְאַתְּ אָמֵר לַיְיָ הַנִּרְאֶה אֵלָיו. וּבְגִין כָּךְ אֲשֶׁר אַתָּה רוֹאֶה בְּגִין דְּדַרְגָא דָּא קַדְמָאָה אִתְכְּלִיל מִכֻּלְהוּ דַּרְגִּין וְכֻלְהוּ אִתְחֲזוּן בֵּיהּ, וּבְגִין כָּךְ כִּי אֶת כָּל הָאָרֶץ אֲשֶׁר אַתָּה רוֹאֶה וְגו'.","רַבִּי אֶלְעָזָר אִעֲרַא בְּבֵי אוּשְׁפִּיזָא בְּלוּד, וְהֲוָה עִמֵּיהּ רַבִּי חִזְקִיָּה. קָם בְּלֵילְיָא לְמִלְעֵי בְּאוֹרַיְיתָא, קָם רַבִּי חִזְקִיָּה גַּבֵּיהּ. אָמַר לֵיהּ רַבִּי אֶלְעָזָר בְּקִיסְטְרָא דְּקוּסְטָא חַבְרַיְיא שְׁכִיחֵי.","פָּתַח רַבִּי אֶלְעָזָר וְאָמַר (שיר השירים ב׳:ג׳) כְּתַפּוּחַ בַּעֲצֵי הַיַּעַר וְגו'. כְּתַפּוּחַ, דָּא קוּדְשָׁא בְּרִיךְ הוּא, דְּאִיהוּ חָמִיד וּמִתְעַטַּר בִּגְוָונוֹי מִכָּל שְׁאָר אִילָנִין דְּלָא אִית דְּדָמֵי לֵיהּ. רָשִׁים אִיהוּ מִכֹּלָּא, רָשִׁים הוּא דְּלֵית אָחֳרָא כַּוָּתֵיהּ.","בְּגִינִי כָּךְ בְּצִלּוֹ חִמַדְתִּי. בְּצִלּוֹ וְלָא בְּצִלָּא אָחֳרָא. בְּצִלוֹ וְלָא בְצִלָּא דִּשְׁאָר מְמַנָּן. חִמַּדְתִּי, אֵימָתַי, מִן יוֹמָא דְּהֲוָה אַבְרָהָם בְּעָלְמָא דְּאִיהוּ חָמִיד וְרָחִים לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא בְּאַהֲבָה כְּמָא דְאַתְּ אָמֵר, (ישעיהו מ״א:ח׳) אַבְרָהָם אוֹהֲבִי. וּפִרְיוֹ מָתוֹק לְחִכִּי, דָּא הוּא יִצְחָק דְּאִיהוּ אִיבָּא קַדִּישָׁא.","דָּבָר אַחֵר בְּצִלּוֹ חִמַדְתִּי וְיָשַׁבְתִּי, דָּא יַעֲקֹב. וּפִרְיוֹ מָתוֹק לְחִכִּי, דָּא יוֹסֵף הַצַּדִּיק דְּעֲבַד פֵּירִין קַדִּישִׁין בְּעָלְמָא. וְעַל דָּא כְּתִיב (בראשית ל״ז:ב׳) אֵלֶּה תּוֹלְדוֹת יַעֲקֹב יוֹסֵף. דְּכָל אִנּוּן תּוֹלְדוֹת דְּיַעֲקֹב (יוסף דאיהו דעביד תולדות) (נ\"א ביוסף הצדיק קיימי, דעביד תולדות כעין כלהו) (ד\"א ל\"ג שבטים), וּבְגִין כָּךְ אִקְרוּן יִשְׂרָאֵל עַל שְׁמָא דְאֶפְרַיִם דִּכְתִיב, (ירמיהו ל״א:כ׳) הֲבֵן יַקִּיר לִי אֶפְרַיִם וְגו'.","דָּבָר אַחֵר כְּתַפּוּחַ בַּעֲצֵי הַיַּעַר. דָּא אַבְרָהָם. דְּדָמֵי לֵיהּ לְתַפּוּחַ דְּסָלִיק רֵיחִין וְאִתְרְשִׁים בִּמְהֵימְנוּתָא שְׁלֵימָתָא עַל כָּל בְּנֵי דָרֵיהּ, וְאִתְרְשִׁים חַד לְעֵילָא, וְאִתְרְשִׁים חַד לְתַתָּא דִּכְתִיב (יחזקאל ל\"ג כ\"ד) אֶחָד הָיָה אַבְרָהָם."],[[0,"ועל דא בזמנא","וכו': ועל כן, בשעה שישראל היו שרוים בארץ, ועבדו עבודת הקב\"ה, השכינה היתה צנועה ביניהם ולא יצאה מן הבית לחוץ בגלוי. ומשום זה כל הנביאים שהיו אז באותו זמן, דהיינו בזמן שביהמ\"ק היה קים, לא קבלו נבואה מחוץ למקומה, דהיינו מחוץ לארץ ישראל, כמו שאמרנו. ומשום זה ברח יונה לחוץ מארץ הקדושה, כדי שהנבואה לא תתגלה עליו, ולא יהיה מחויב ללכת בשליחותו של הקב\"ה."],[1,"ואי תימא הא","וכו': ואם תאמר, הרי אנו רואים שנגלה השכינה בבבל, ליחזקאל, שהוא חו\"ל. הנה ביארנו, שכתוב, \u0003היה היה,\u0004 שהיה אז, מה שלא היה מקודם לכן, מיום שנבנה בית המקדש, ואותה הנבואה לשעה היתה. כדי לנחם את ישראל כמ\"ש להלן."],[2,"","וכתוב \u0003על נהר כבר,\u0004 שפירושו, נהר שכבר היה מיום שנברא העולם והשכינה היתה נגלה עליו תמיד, היינו מטרם שנבנה ביהמ\"ק, שכתוב, ונהר יוצא מעדן להשקות את הגן ומשם יפרד והיה לארבעה ראשים וגו', ונהר זה \u0003כבר,\u0004 הוא אחד מד' נהרות הללו. פירוש, הגן, ה\"ס השכינה, (כנ\"ל ב\"א דף רי\"א ד\"ה ומיד) שממנה נמשך הנהר היוצא מעדן, שה\"ס חכמה, ונעשה לד' נהרות, ע\"כ היתה נגלה על ד' נהרות הללו מטרם שנבנה בית המקדש."],[3,"ותמן אתגלייא שכינתא וכו',","ושם נגלה השכינה לצורך השעה, שהיו ישראל צריכים אותה, כדי לנחמם מצער של חורבן בית המקדש, אבל בזמן אחר לא נגלה השכינה בחוץ לארץ. ומשום זה, ברח יונה, כדי שלא תשרה עליו השכינה, ולא תתגלה עליו, וע\"כ הלך מארץ הקדושה וברח. וזהו שכתוב, מלפני ה', וכתוב כי ידעו האנשים כי מלפני ה' הוא בורח."],[4,"תא חזי כמה וכו':","בוא וראה, כמו שהשכינה אינה מתגלה אלא במקום הראוי לה, כן אינה נראית ואינה מתגלה אלא לאיש הראוי לה, שהרי מיום שעלה ברצונו של לוט להתהפך בחטאו. נסתלק רוח הקדש מאברהם, וכשלוט נפרד ממנו, מיד שרה רוח הקדש במקומו, דהיינו על אברהם, וזהו שכתוב, וה' אמר אל אברם אחרי הפרד לוט מעמו וגו'."],[4,"","ביאור המאמר, כי ידעת שכל מדרגה נחלקת לפנימיות וחצוניות, ששורשו של התחלקות הזה, ה\"ס עלית ה\"ת לעינים, ונעשה סיום חדש בסיום גלגלתא ועינים שה\"ס פרסא. ואח\"פ יצאו לחוץ מהמדרגה. (עי' בפתיחה לחה\"ק אות ע\"ז) ולפיכך הכלים שלמעלה מפרסא שנשארו בהמדרגה נקראים פנימיות, והכלים שיצאו למטה מפרסא נקראים חיצוניות, או אחורים, עש\"ה, ואע\"פ שבעת גדלות מוחזרים הכלים החצונים שלמטה מפרסא אל המדרגה, עם כל זה. כיון שז\"ת דאצילות, שהם זו\"ן, אינם נשלמים רק בדרך עליה להמקום שלמעלה מחזה, שה\"ס השלמת התחתון בעליון, ואינם נשלמים במקומם עצמם, בהמקום שמחזה ולמטה, כמו שנתבאר באורך בפתיחה לחכמת הקבלה, מאות קל\"ד עד אות קמ\"ד, עש\"ה, ע\"כ נחנים תמיד הכלים בינה ותו\"מ שמחזה ולמטה לבחינת חצוניות, כי לא יוכלו להתברר ולהשתלם מטרם גמר התקון, כי אז יקבלו הזו\"ן השלמה דמין הב' כמ\"ש באות קל\"ג."],[4,"","וזהו ההפרש מנשמת ישראל לאומות העולם, כי ישראל נמשכים מבחינת כלים דפנים, והם ראוים לקבל אורות שלמים גם מטרם גמר התקון. אבל אומות העולם נמשכים מבחינת כלים החצונים, וע\"כ לא יוכלו לקבל שום שלמות מטרם גמר התקון, ועד\"ז נחלקו העולמות לפנימיות וחיצוניות. וארץ ישראל, ה\"ס כלים דפנים מבחינת העולם. וחוץ לארץ הם כלים דחיצוניות. וע\"כ אין שלמות בחוץ לארץ מטרם גמר התקון, כי אז נאמר והיה ה' למלך על כל הארץ וגו'. וכן ומלאה הארץ דעה וגו'. אבל מטרם גמר התקון. אין שלמות רק בהכלים דפנים מהעולם בלבדם, שהם סוד ארץ ישראל."],[4,"","וזה אמרו, \u0003ארעא דישראל לא שליט עלה ממנא אחרא בר קב\"ה בלחודוי.\u0004 כי ארץ ישראל להיותה מבחינות כלים דפנים, קבלה תקון גם בזמן הזה, בסו\"ה ארץ אשר עיני ה' אלקיך בה וגו' והשכינה מתגלית בה. מה שאין כן בחוץ לארץ, כי נתנה לשליטת ע' שרים, שגם הם בחינת חיצוניות מהקדושה, דהיינו שנמשכים מכלים החצונים שאין להם שום שלמות מטרם גמר התקון, ולפיכך עוד לא נתקים, והיה ה' למלך על כל הארץ, אלא בארץ ישראל לבד."],[4,"","וז\"ש \u0003כמה דשכינתא לא אתגליא אלא באתרא דאתחזי לה,\u0004 דהיינו בארץ ישראל. \u0003אוף הכי וכו' בבר נש דאתחזי לה וכו',\u0004 דהיינו שיהיה נשמר מלעורר הזווג בחיצוניות הנוקבא, שהיא בהמקום שלמטה מחזה, כי אז הוא מפריד הנוקבא מז\"א, והשפע הולכת לחוץ לארץ, אל ע' שרים של אומות העולם שהם בעלי הכלים החיצונים המתאוים לאותו השפע. וז\"ש (באות קפ\"ה) \u0003ובשעתא דחאבו והוו מקטרן לטעוון אחרנין וכו',\u0004 דהיינו שעוררו זווג בכלים החצונים של הנוקבא והמשיכו השפע ממעלה למטה, שאז הולכת השפע לאלהים אחרים כנ\"ל. \u0003. וכדין שלטו שאר עמין וכו',\u0004 כי השפע הגיע לע' שרים שלהם. \u0003ובג\"כ כלהו ינקין מן שכינתא דאתקריבת גבייהו,\u0004 כי הכלים החצונים של השכינה, קרובים לאומות העולם, כי רק הם מקבלים מהם כנ\"ל. ובדרך הזה תבין כל המאמר."],[5,"תא חזי כיון וכו':","בוא וראה, כיון שראה אברהם שלוט חזר לסורו, היה מפחד, אמר, אולי ח\"ו. משום התחברותי עם זה, אבדתי בשבילו, חלק הקדוש שהקב\"ה העטיר אותי. כיון שלוט נפרד ממנו, א\"ל הקב\"ה, שא נא עיניך וגו',"],[6,"ושואל מהו מן המקום אשר אתה שם,","ואומר שפירושו, המקום שנתדבקת בו בתחילה ונתעטרת באמונה שלמה, דהיינו צפונה ונגבה קדמה וימה, אלו הם המסעות שנסע בתחילה, שכתוב וילך למסעיו, כמו שנתבאר (באות קס\"ה) שה\"ס נפש רוח נשמה וחיה ע\"ש. צפונה ה\"ס בינה ונשמה. נגבה, ה\"ס חכמה וחיה. קדמה ה\"ס ת\"ת, ורוח. ימה, ה\"ס מלכות, ונפש. \u0003וכתיב הלוך ונסוע הנגבה וכו':\u0004 אלו הן מדרגות העליונות שנתעטר בהם באמונה שלמה בתחילה."],[7,"וכדין אתבשר וכו':","ואז נתבשר, שלא יסורו ממנו ומן בניו לעולם. שכתוב, כי את כל הארץ אשר אתה רואה לך אתננה ולזרעך. ושואל מהו \u0003אשר אתה רואה\u0004 ואומר, זה הוא מדרגה הראשונה שנתגלה לו שהיא מדרגת הנפש, כמו שאתה אומר, לה' הנראה אליו (כנ\"ל באות קס\"ז) ומשום זה נאמר אשר אתה רואה, משום שמדרגה זו הראשונה, שהיא הנוקבא, נכללת מכל המדרגות, וכל המדרגות נראות בה, ומשום זה נאמר, כי את כל הארץ אשר אתה רואה וגו'."],[8,"ר' אלעזר אערע וכו':","ר' אלעזר אירע במלון בלוד. והיה עמו שם ר' חזקיה, קם ר' אלעזר בלילה ללמוד תורה. עמד אצלו ר' חזקיה, בסמוך לו, כי היה צר להם המקום. אמר לו ר' אלעזר, בארמון צר החברים מצוים. כלומר מתוך שהם מרבים בתורה וממעטים במלאכה, לכן פוגשים אותם תמיד בבית מלונות צרים וקטנים. כי אין להם כסף לשכור בתים מרווחים. \u0003קיסטרא,\u0004 פירושו ארמון, לפי הענין. \u0003קוסטא,\u0004 פירושו מקום צר ודחוק. כמ\"ש (תענית כד.) דיירנא בקוסטא דחיקא."],[9,"פתח ר' אלעזר וכו':","פתח ר\"א ואמר. כתפוח בעצי היער וגו'. \u0003כתפוח,\u0004 זהו הקב\"ה, שהוא נחמד ומתעטר בגווניו שה\"ס ג' קוין חג\"ת, הנבחנים לג' גוונין, לבן אדום וירוק. שאין דומה לו, בכל שאר אילנות, שהם ע' שרים המתדמים לקדושה כקוף בפני אדם. מצוין הוא מכל, מצוין הוא שאין אחר כמותו. פירוש. כי מחמת חטא דעצה\"ד, נמשכה השכינה לצד ע' שרים, שהם בחינת חיצוניות דז\"א, כמ\"ש לעיל (בהסולם באות קצ\"א ע\"ש) וע\"כ אחר שנתקנה וחזרה ונתדבקה בז\"א, הנקרא הקב\"ה, אמרה השכינה כתפוח בעצי היער וכו' שאין דומה לו בע' שרים שנתדבקה מקודם, וניכר יתרונו ית' עליהם עתה, כיתרון האור על החשך."],[10,"בגיני כך בצלו חמדתי בצלו ולא בצלא אחרא וכו':","כי מטרם תקונה היתה השכינה בצל אחר, דהיינו בצל דעלי תאנה (כנ\"ל בראשית ב' דף קפ\"א ד\"ה ויתפרו ע\"ש) \u0003בצלו ולא בצלא דשאר ממנן,\u0004 דהיינו בצל של ע' שרים. כנ\"ל. \u0003חמדתי אימתי,\u0004 שואל, בצלו חמדתי מאימתי חמדה, כי אי אפשר לומר שחמדה תמיד, שהרי מסבת החטא נטתה לע' שרים כנ\"ל בדבור הסמוך, ואומר, שהוא מיום שבא אברהם לעולם, ואהב את הקב\"ה באהבה, כמו שאתה אומר \u0003אברהם אוהבי.\u0004 אז תקן את השכינה, וחזרה ונתיחדה בז\"א, \u0003ופריו מתוק לחכי,\u0004 זהו יצחק, שהוא פרי קדוש של אברהם. פירוש. כי בעוד שנטתה לע' שרים, שה\"ס הארת השמאל, היתה ריקנית הן מחכמה והן מחסדים כנ\"ל (דף י\"ג ד\"ה והענין) ואחר שאברהם תקנה לזווג עם ז\"א, וקבלה ממנו קו ימין שה\"ס חסדים המכוסים הנבחנים \u0003לצל,\u0004 חזר להאיר בה גם קו השמאל, שה\"ס הארת החכמה המתלבשת בחסדים דימין. (כנ\"ל דף י\"ז ד\"ה כיון) ונמצא הארת החכמה בבחינת פרי ותולדה דקו ימין. כי לא יכלה להאיר מקודם לכן. וז\"ס אברהם הוליד את יצחק."],[11,"ד\"א בצלו וכו':","פירוש אחר. \u0003בצלו חמדתי וישבתי,\u0004 זה יעקב, שה\"ס קו אמצעי, שלהיותו מכריע בבחינת מסך דחירק, הממעט הקומה, (כנ\"ל דף י\"ז ד\"ה וכיון) ע\"כ נבחן \u0003לצל,\u0004 ולבחינת \u0003ישיבה. ופריו מתוק לחכי,\u0004 זה יוסף שה\"ס יסוד שהוא עשה פירות קדושים בעולם דהיינו נשמות וע\"כ כתוב אלה תולדות יעקב יוסף, שכל אלו תולדות דיעקב ביוסף הצדיק עומדים, שהוא בחינת יסוד של יעקב, ומשום זה נקראים ישראל על שם אפרים, שכתוב הבן יקיר לי אפרים וגו'."],[12,"ד\"א כתפוח בעצי היער וכו':","זהו אברהם שהוא דומה לתפוח המעלה ריח. והוא נצטיין באמונה שלמה יותר מכל בני דורו. ונצטיין לבחינת אחד למעלה ובבחינת אחד למטה, שכתוב, אחד היה אברהם."]],[[0,"","וְעַל זֶה, בִּזְמַן שֶׁיִּשְׂרָאֵל הָיוּ שְׁרוּיִים עַל הָאָרֶץ וְעוֹבְדִים אֶת עֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא, הַשְּׁכִינָה הָיְתָה צְנוּעָה בֵּינֵיהֶם, וְלֹא יָצְאָה מִתּוֹךְ בֵּיתָהּ הַחוּצָה בַּגָּלוּי. וּמִשּׁוּם כָּךְ, כָּל אוֹתָם הַנְּבִיאִים שֶׁהָיוּ בְּאוֹתוֹ הַזְּמַן, לֹא נָטְלוּ נְבוּאָה אֶלָּא בִּמְקוֹמָהּ, כְּפִי שֶׁאָמַרְנוּ. וּמִשּׁוּם כָּךְ יוֹנָה הָיָה בּוֹרֵחַ מִחוּץ לְאֶרֶץ הַקֹּדֶשׁ, כְּדֵי שֶׁלֹּא תִתְגַּלֶּה עָלָיו הַנְּבוּאָה, וְלֹא יֵלֵךְ בַּשְּׁלִיחוּת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא."],[1,"","וְאִם תֹּאמַר, הֲרֵי רָאִינוּ שֶׁהִתְגַּלְּתָה הַשְּׁכִינָה בְּבָבֶל, שֶׁהִיא בַּחוּץ - הִנֵּה פֵּרַשְׁנוּ שֶׁכָּתוּב (יחזקאל א) הָיֹה הָיָה, שֶׁהָיָה מַה שֶּׁלֹּא הָיָה מִלִּפְנֵי כֵן מִיּוֹם שֶׁנִּבְנָה בֵּית הַמִּקְדָּשׁ, וְהַנְּבוּאָה הַהִיא הָיְתָה לְשַׁעְתָּהּ."],[2,"","וְכָתוּב עַל נְהַר כְּבָר, הַנָּהָר שֶׁכְּבָר הָיָה מִן הַיּוֹם שֶׁנִּבְרָא הָעוֹלָם, וְהַשְּׁכִינָה תָּמִיד הִתְגַּלְּתָה עָלָיו, שֶׁכָּתוּב (בראשית ב) וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן וּמִשָּׁם יִפָּרֵד וְגוֹ' (שם האחד וגו'), וְזֶה הוּא אֶחָד מֵהֶם."],[3,"","וְשָׁם נִגְלְתָה הַשְּׁכִינָה לְפִי שָׁעָה שֶׁהִצְטָרְכוּ אוֹתָהּ יִשְׂרָאֵל לְפִי צַעֲרָם, אֲבָל בִּזְמַן אַחֵר לֹא הִתְגַּלְּתָה. וּמִשּׁוּם כָּךְ יוֹנָה, כְּדֵי שֶׁלֹּא תִשְׁרֶה עָלָיו הַשְּׁכִינָה וְלֹא תִתְגַּלֶּה עָלָיו, הָלַךְ מֵאֶרֶץ הַקֹּדֶשׁ וּבָרַח. זֶהוּ שֶׁכָּתוּב (יונה א) מִלִּפְנֵי ה'. וְכָתוּב כִּי יָדְעוּ הָאֲנָשִׁים כִּי מִלִּפְנֵי ה' הוּא בֹרֵחַ"],[4,"","בֹּא רְאֵה, כְּמוֹ שֶׁהַשְּׁכִינָה לֹא מִתְגַּלָּה אֶלָּא בְּמָקוֹם הָרָאוּי לָהּ, אַף כָּךְ לֹא רְאוּיָה וְלֹא מִתְגַּלָּה אֶלָּא בְּאָדָם שֶׁרָאוּי לָהּ. שֶׁהֲרֵי מִיּוֹם שֶׁעָלָה עַל רְצוֹנוֹ שֶׁל לוֹט לְהִתְהַפֵּךְ לְסוּרוֹ הָרָע, הִסְתַּלְּקָה רוּחַ הַקֹּדֶשׁ מֵאַבְרָהָם. וּכְשֶׁהִסְתַּלֵּק מִמֶּנּוּ לוֹט, מִיָּד שָׁרְתָה רוּחַ הַקֹּדֶשׁ בִּמְקוֹמָהּ. זֶהוּ שֶׁכָּתוּב וַה' אָמַר אֶל אַבְרָם אַחֲרֵי הִפָּרֶד לוֹט מֵעִמּוֹ וְגוֹ'."],[5,"","בֹּא רְאֵה, כֵּיוָן שֶׁרָאָה אַבְרָהָם שֶׁלּוֹט הָיָה שָׁב לְסוּרוֹ הָרָע, הָיָה פּוֹחֵד אַבְרָהָם. אָמַר, אוּלַי חַס וְשָׁלוֹם מִשּׁוּם הַחֲבֵרוּת עִם זֶה אִבַּדְתִּי בִּגְלָלוֹ אֶת הַחֵלֶק הַקָּדוֹשׁ שֶׁעִטֵּר אוֹתִי הַקָּדוֹשׁ בָּרוּךְ הוּא. כֵּיוָן שֶׁנִּפְרַד מִמֶּנּוּ, אָמַר לוֹ, שָׂא נָא עֵינֶיךְ וּרְאֵה מִן הַמָּקוֹם אֲשֶׁר אַתָּה שָׁם."],[6,"","כְּמוֹ מַה זֶּה מִן הַמָּקוֹם אֲשֶׁר אַתָּה שָׁם? שֶׁנִּדְבַּקְתָּ בּוֹ בַּתְּחִלָּה וְהִתְעַטַּרְתָּ בָּאֱמוּנָה הַשְּׁלֵמָה. צָפֹנָה וָנֶגְבָּה וָקֵדְמָה וָיָמָּה - אֵלּוּ הֵם מַסָּעָיו שֶׁהָיוּ בַתְּחִלָּה, שֶׁכָּתוּב וַיֵּלֶךְ לְמַסָּעָיו. וְכָתוּב הָלוֹךְ וְנָסוֹעַ הַנֶּגְבָּה - אֵלּוּ הַדְּרָגוֹת הָעֶלְיוֹנוֹת שֶׁהִתְעַטֵּר בָּאֱמוּנָה הַשְּׁלֵמָה בַּתְּחִלָּה."],[7,"","וְאָז הִתְבַּשֵּׂר שֶׁלֹּא תָזוּז מִמֶּנּוּ וּמִבָּנָיו לְעוֹלָמִים, שֶׁכָּתוּב כִּי אֶת כָּל הָאָרֶץ אֲשֶׁר אַתָּה רֹאֶה. מַה זֶּה אֲשֶׁר אַתָּה רֹאֶה? זוֹ הַדַּרְגָּה הָרִאשׁוֹנָה שֶׁהִתְגַּלְּתָה לוֹ, כְּמוֹ שֶׁנֶּאֱמַר לַה' הַנִּרְאֶה אֵלָיו. וּמִשּׁוּם כָּךְ אֲשֶׁר אַתָּה רֹאֶה, מִשּׁוּם שֶׁהַדַּרְגָּה הָרִאשׁוֹנָה הַזּוֹ נִכְלֶלֶת מִכָּל הַדְּרָגוֹת וְכֻלָּן נִרְאוֹת בָּהּ. וּמִשּׁוּם כָּךְ כִּי אֶת כָּל הָאָרֶץ אֲשֶׁר אַתָּה רֹאֶה וְגוֹ'."],[8,"","רַבִּי אֶלְעָזָר נִקְלַע לְבֵית אַכְסַנְיָה בְּלוֹד, וְהָיָה עִמּוֹ רַבִּי חִזְקִיָּה. קָם בַּלַּיְלָה לַעֲסֹק בַּתּוֹרָה. קָם רַבִּי חִזְקִיָּה אֵלָיו. אָמַר לוֹ רַבִּי אֶלְעָזָר, הַחֲבֵרִים נִמְצָאִים בְּאַרְמוֹן צַר."],[9,"","פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (שיר ב) כְּתַפּוּחַ בַּעֲצֵי הַיַּעַר וְגוֹ'. כְּתַפּוּחַ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא נֶחְמָד וּמִתְעַטֵּר בִּגְוָנָיו מִכָּל שְׁאָר הָאִילָנוֹת שֶׁאֵין מִי שֶׁדּוֹמֶה לוֹ. רָשׁוּם הוּא מִן הַכֹּל, רָשׁוּם הוּא שֶׁאֵין אַחֵר כְּמוֹתוֹ."],[10,"","מִשּׁוּם כָּךְ בְּצִלּוֹ חִמַּדְתִּי. בְּצִלּוֹ וְלֹא בְצֵל שֶׁל אַחֵר. בְּצִלּוֹ וְלֹא בְצֵל שֶׁל שְׁאָר הַמְמֻנִּים. חִמַּדְתִּי - מָתַי? מִן הַיּוֹם שֶׁהָיָה אַבְרָהָם בָּעוֹלָם, שֶׁהוּא נֶחְמָד וְאָהַב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאַהֲבָה, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה מא) אַבְרָהָם אֹהֲבִי. וּפִרְיוֹ מָתוֹק לְחִכִּי - זֶה הוּא יִצְחָק, שֶׁהוּא פְּרִי קָדוֹשׁ."],[11,"","דָּבָר אַחֵר בְּצִלּוֹ חִמַּדְתִּי וְיָשַׁבְתִּי - זֶה יַעֲקֹב. וּפִרְיוֹ מָתוֹק לְחִכִּי - זֶה יוֹסֵף הַצַּדִּיק שֶׁעָשָׂה פֵרוֹת קְדוֹשִׁים בָּעוֹלָם, וְעַל זֶה כָּתוּב (בראשית לז) אֵלֶּה תֹּלְדוֹת יַעֲקֹב יוֹסֵף. שֶׁכָּל אוֹתָם הַתּוֹלָדוֹת שֶׁל יַעֲקֹב (יוסף שהוא שעושה תולדות) (נ\"א: ביוסף הצדיק הם עומדים, שעושה תולדות כעין כלם) (ד\"א שבטים), וּמִשּׁוּם כָּךְ נִקְרְאוּ יִשְׂרָאֵל עַל שֵׁם אֶפְרַיִם, שֶׁכָּתוּב (ירמיה לא) הֲבֵן יַקִּיר לִי אֶפְרַיִם וְגוֹ'."],[12,"","דָּבָר אַחֵר כְּתַפּוּחַ בַּעֲצֵי הַיַּעַר - זֶה אַבְרָהָם, שֶׁדּוֹמֶה לְתַפּוּחַ שֶׁמַּעֲלֶה רֵיחוֹת, וְנִצְטַיֵּן בֶּאֱמוּנָה שְׁלֵמָה עַל כָּל בְּנֵי דוֹרוֹ, וְנִרְשַׁם אֶחָד לְמַעְלָה וְנִרְשַׁם אֶחָד לְמַטָּה, שֶׁכָּתוּב אֶחָד הָיָה אַבְרָהָם."]]],[["מַאי טַעְמָא הֲוָה אֶחָד. דְּלָא הֲוָה אָחֳרָא בְּעָלְמָא דִי סָלִיק לִמְהֵימְנוּתָא דְקוּדְשָׁא בְּרִיךְ הוּא בַּר אִיהוּ. אָמַר לֵיהּ רַבִּי חִזְקִיָּה וְהָא כְּתִיב וְאֶת הַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן. אָמַר לֵיהּ עַד כְּעָן אִנּוּן לָא הֲווּ בְּדַרְגִּין עִלָאִין דְּאִתְעַטַּר בְּהוּ אַבְרָהָם.","לְבָתַר אָמַר לֵיהּ תוּ שְׁמַעְנָא דְּלָא אִקְרֵי אַבְרָהָם אֶחָד עַד דְּאִסְתַּלַּק בְּיִצְחָק וְיַעֲקֹב. כֵּיוָן דְּאִסְתַּלַּק בְּיִצְחָק וְיַעֲקֹב (נ\"א והא) וְהֲווּ כֻּלְהוּ תְּלָתְהוֹן אֲבָהָן דְּעָלְמָא כְּדֵין אִקְרֵי אַבְרָהָם אֶחָד. וּכְדֵין הוּא תַּפּוּחַ בְּעָלְמָא רָשִׁים מִכָּל בְּנֵי עָלְמָא. אָמַר לֵיהּ שַׁפִּיר קָא אֲמַרְתְּ.","דָּבָר אַחֵר כְּתַפּוּחַ בַּעֲצֵי הַיַּעַר דָּא קוּדְשָׁא בְּרִיךְ הוּא. כֵּן דּוֹדִי דָּא קוּדְשָׁא בְּרִיךְ הוּא. בְּצִלּוֹ דָּא קוּדְשָׁא בְּרִיךְ הוּא. חִמַדְתִּי וְיָשַׁבְתִּי, בְּיוֹמָא דְאִתְגְּלֵי קוּדְשָׁא בְּרִיךְ הוּא עַל טוּרָא דְסִינַי וְקַבִּילוּ יִשְׂרָאֵל אוֹרַיְיתָא וְאָמְרוּ (שמות כ״ד:ז׳) נַעֲשֶׂה וְנִשְׁמַע.","וּפִרְיוֹ מָתוֹק לְחִכִּי. אִלֵּין מִלִּין דְּאוֹרַיְיתָא דִּכְתִיב בְּהוּ (תהילים י״ט:י״א) וּמְתוּקִים מִדְּבַשׁ וְנוֹפֶת צוּפִים. דָּבָר אַחֵר וּפִרְיוֹ מָתוֹק לְחִכִּי, אִלֵּין נִשְׁמַתְהוֹן דְּצַדִּיקַיָא דְּכֻלְהוּ אִיבָּא דְּעוֹבָדוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא וְקָיְימֵי עִמֵּיהּ לְעֵילָא.","תָּא חֲזֵי, כָּל נִשְׁמָתִין דְּעָלְמָא דְּאִנּוּן אִיבָּא דְּעוֹבָדוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא כֻּלְהוּ חַד בְּרָזָא חַד, וְכַד נָחֲתֵי לְעָלְמָא כֻּלְהוּ מִתְפָּרְשִׁין בִּגְוָונִין דְּכַר וְנוּקְבָא, וְאִנּוּן דְּכַר וְנוּקְבָא מְחֻבָּרִין כְּחֲדָא.","וְתָּא חֲזֵי, תִּיאוּבְתָּא דְנוּקְבָא לְגַבֵּי דְכוּרָא עָבִיד נֶפֶשׁ. וּרְעוּתָא דְּתִיאוּבְתָּא דִּדְכוּרָא לְגַבֵּי נוּקְבָא וְאִתְדַּבְּקוּתָא דִילֵיהּ בָּהּ, אַפִּיק נֶפֶשׁ וְכָלִיל תִּיאוּבְתָּא (נ\"א תיאובתיה) דְנוּקְבָא וְנָטִיל לָהּ. וְאִתְכְּלִיל) תִּיאוּבְתָּא תַּתָּאָה בְּתִיאוּבְתָּא דִּלְעֵילָא וְאִתְעֲבִידוּ רְעוּתָא חָדָא בְּלָא פִּירוּדָא.","וּכְדֵין (נטיל) כָּלִיל כֹּלָא נוּקְבָא וְאִתְעַבְּרַת מִן דְּכוּרָא וְתִיאוּבְתִּין דְּתַרְוַויְיהוּ מִתְדַּבְּקָן כְּחֲדָא, וְעַל דָּא כֹּלָּא כָּלִיל דָּא בְּדָא. וְכַד נִשְׁמָתִין נָפְקִין דְּכַר וְנוּקְבָא כְּחֲדָא נָפְקִין.","לְבָתַר כֵּיוָן דְּנָחֲתֵי מִתְפָּרְשָׁן דָּא לְסִטְרָא דָא וְדָא לְסִטְרָא דָא, וְקוּדְשָׁא בְּרִיךְ הוּא מְזַוִּוג לוֹן לְבָתַר. וְלָא אִתְיְיהִיב זִוּוּגָא לְאָחֳרָא אֶלָּא לְקוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי, דְּאִיהוּ יָדַע זִוּוּגָא דִּלְהוֹן לְחַבְּרָא לוֹן כְּדְקָא יָאוֹת.","זַכָּאָה הוּא בַּר נָשׁ דְּזָכֵי בְּעוֹבָדוֹי וְאָזִיל בְּאוֹרַח קְשׁוֹט בְּגִין דְּאִתְחַבַּר נֶפֶשׁ בְּנֶפֶשׁ כְּמָה דְּהֲוָה מֵעִיקָרָא, דְּהָא אִי זָכֵי בְּעוֹבָדוֹי דָּא הוּא בַּר נָשׁ שְׁלִים כְּדְקָא יְאוּת. וּבְגִין כָּךְ כְּתִיב וּפִרְיוֹ מָתוֹק לְחִכִּי. דְּהוּא בְּתִקּוּנָא מְבֹרָךְ לְאִתְבָּרְכָא מִנֵּיהּ עָלְמָא, בְּגִין דְּכֹלָּא בְּעוֹבָדִין דְּבַר נָשׁ תַּלְיָא אִי זָכֵי אִי לָא זָכֵי.","אָמַר רַבִּי חִזְקִיָּה הָכִי שָׁמַעְנָא דִּכְתִיב, (הושע י״ד:ט׳) מִמֶּנִּי פֶּרְיְךָ נִמְצָא. קוּדְשָׁא בְּרִיךְ הוּא אָמַר לֵיהּ לִכְנְסֶת יִשְׂרָאֵל מִמֶּנִּי וַדַּאי פֶּרְיְךָ נִמְצָא. פֶּרְיִי נִמְצָא לָא כְּתִיב אֶלָּא פֶּרְיְךָ. הַהוּא תִּיאוּבְתָּא דְּנוּקְבָא דְּעֲבִיד נֶפֶשׁ וְאִתְכְּלִיל בְּתוּקְפָא דִדְּכוּרָא וְאִתְכְּלִיל נֶפֶשׁ בְּנֶפֶשׁ וְאִתְעֲבִידוּ חָד כָּלִיל דָּא בְּדָא כִּדְאֲמָרָן. לְבָתַר אִשְׁתַּכָּחוּ תַּרְוַויְיהוּ בְּעָלְמָא, וְדָא בְּחֵילָא דִּדְכוּרָא אִשְׁתְּכַח אִיבָּא דְנוּקְבָא.","דָּבָר אַחֵר בְּתִיאוּבְתָּא דְּנוּקְבָא אִשְׁתְּכַח אִיבָּא דִדְכוּרָא. דְּאִי לָאו תִּיאוּבְתָּא דְּנוּקְבָא לְגַבֵּי דְכוּרָא לָא אִתְעֲבִידוּ פֵּירִין לְעָלְמִין הֲדָא הוּא דִכְתִיב מִמֶּנִּי פֶּרְיְךָ נִמְצָא:","וַיְהִי בִּימֵי אַמְרָפֶל מֶלֶךְ שִׁנְעָר וְגו'. רַבִּי יוֹסֵי פָּתַח (ישעיהו מ״א:ב׳) מִי הֵעִיר מִמִּזְרָח צֶדֶק יִקְרָאֵהוּ לְרַגְלוֹ וְגו'. הַאי קְרָא אוּקְמוּהָ חַבְרַיָיא. אֲבָל הַאי קְרָא בְּרָזָא דְחָכְמְתָא אִיהוּ. דְּהָא תָּנִינָן שִׁבְעָה רְקִיעִין עֲבַד קוּדְשָׁא בְּרִיךְ הוּא לְעֵילָא, וְכֻלְהוּ לְאִשְׁתְּמוֹדַע יְקָרָא דְקוּדְשָׁא בְּרִיךְ הוּא, וְכֻלְהוּ קָיְימִין לְאוֹדָעָא רָזָא דִמְהֵימְנוּתָא עִלָּאָה.","תָּא חֲזֵי, אִית רְקִיעָא עִלָּאָה סָתִים לְעֵילָא מִנַּיְיהוּ דְּאִנּוּן שִׁבְעָה, וְדָא הוּא רְקִיעָא דְּדַבָּר לוֹן וְנָהִיר לוֹן לְכֻלְהוּ, וְדָא לָא אִתְיְידַע, וְקָיְימָא בִּשְׁאֶלְתָּא דְּלָא יְדִיעָא, בְּגִין דְּאִיהוּ סָתִים וְעָמִיק, וְכֹלָּא תְּוָוהִין עֲלֵיהּ, וּבְגִין כָּךְ אִקְרֵי מִ\"י, כְּמָה דְאוּקְמוּהָ דִּכְתִיב, (איוב ל״ח:כ״ט) מִבֶּטֶן מִי יָצָא הַקָּרַח וְאִתְּמָר, וְהַאי הוּא רְקִיעָא עִלָּאָה דְּקָיְימָא עַל כָּל אִנּוּן שִׁבְעָה."],[[0,"מאי טעמא וכו':","שואל, מהו דטעם שהיה אחד. ואומר, שלא היה אז אחר בעולם, שיתעלה באמונת הקב\"ה חוץ ממנו. אמר לו רבי חזקיה. והרי כתוב ואת הנפש אשר עשו בחרן, שפירושו, שאברהם היה מגייר את האנשים ושרה את הנשים. הרי שהיו בעלי אמונת הקב\"ה חוץ ממנו. אמר לו, ובכל זאת, עוד לא היו באותן מדרגות העליונות שאברהם נתעטר בהן."],[1,"לבתר א\"ל וכו':","אחר כך אמר לו, עוד שמעתי. שלא נקרא אברהם אחד, עד שנכלל ביצחק ויעקב. כיון שנכלל ביצחק ויעקב, וכל השלשה יחד היו לאבות העולם, אז נקרא אברהם אחד. כלומר, אחר שנכלל כאחד בכל ג' הקוין נקרא \u0003אחד,\u0004 ולא מקודם לכן, ואז הוא נקרא תפוח בעולם כלומר שיש לו ג' גוונין לבן אדום ירוק כמו תפוח, שהם רומזין לג' הקוין, והוא נצטיין מכל בני דורו. אמר לו, יפה אמרת."],[2,"ד\"א כתפוח וכו':","פירוש אחר, \u0003כתפוח בעצי היער\u0004 זהו הקב\"ה, דהיינו קו ימין. \u0003כן דודי,\u0004 זהו הקב\"ה, היינו קו שמאל. \u0003בצלו\u0004 זהו הקב\"ה, היינו קו אמצעי. \u0003חמדתי וישבתי,\u0004 הוא ביום שנגלה הקב\"ה על הר סיני וישראל קבלו את התורה, ואמרו נעשה ונשמע. אז אמרה השכינה \u0003חמדתי וישבתי.\u0004"],[3,"ופריו מתוק לחכי:","אלו הם דברי התורה, שכתוב בהם ומתוקים מדבש ונופת צופים. פירוש אחר. \u0003ופריו מתוק לחכי\u0004 אלו הן נשמות הצדיקים, שכולן הן פרי מעשיו של הקב\"ה, ועומדים עמו למעלה."],[4,"ת\"ח כל נשמתין וכו':","כל נשמות העולם, שהן פרי מעשיו של הקב\"ה, כולן הן אחד בסוד אחד, כלומר שלמעלה עוד לא ניכר בהן שהן זכר ונקבה, אלא כשיורדת לעולם כל הנשמות בבחינות זכר ונקבה, וכל נשמה היא זכר ונקבה מחוברים כאחד."],[5,"ות\"ח תיאובתא וכו':","ובוא וראה השתוקקותה של הנקבה להזכר עושה נפש. וכן רצון השתוקקותו של הזכר להנקבה, ודבקותו בה, מוציא נפש, והיא כוללת את הנפש מהשתוקקות הנקבה, ולוקחת אותה. ונכלל השתוקקות של התחתון הנקבה בהשתוקקות של העליון הזכר. ונעשו ב' הנפשות רצון אחד בלי פירוד."],[6,"וכדין כליל וכו':","ואז הנקבה כוללת הכל. שלוקחת ב' הנפשות, ומתעברת מן הזכר, בהן. והשתוקקותם של שניהם מתדבקים ונעשו אחד, ועל כן, כלול הכל זה בזה. וכאשר הנשמות יוצאות, זכר ונקבה כלולים בהן כאחד."],[7,"לבתר כיון וכו':","אח\"כ, כיון שיורדים לעולם הם נפרדות זה מזה, הזכר מהנקבה, זה פונה לעברו וזה פונה לעברו. והקב\"ה מזווג אותם לאחר כך. ולא ניתן מפתח הזווג לאחר אלא להקב\"ה בלבדו, שרק הוא יודע זווגם לחבר אותם כראוי. דהיינו, שיהיו זכר ונקבה מנשמה אחת."],[8,"זכאה וכו':","אשרי האיש הזוכה במעשיו, והולך בדרך האמת. כדי שיתחברו לו נפש בנפש, זכר בנקבה, כמו שהיו מקודם שירדו לעולם. אבל אם אינו זוכה לא יתנו לו בת זוגו. וע\"כ כתוב עליו ופריו מתוק לחכי. כי איש הזה נתברך בתקון זכר ונקבה כראוי, שיתברך ממנו העולם בפירות מתוקים, דהיינו תולדות נאות, משום שהכל תלוי במעשיו של האדם אם זכה או לא."],[9,"א\"ר חזקיה הכי וכו':","אר\"ח, כך שמעתי. שכתוב ממני פריך נמצא. הקב\"ה אמר לכנסת ישראל, שהיא השכינה, ממני ודאי פריך נמצא. ולא כתוב פריי נמצא אלא פריך, להורות על אותה השתוקקות של הנקבה העושה בחינת הנקבה של הנפש, שנכללת בתוקפו של הזכר ונכללו נפש הנקבה בנפש הזכר, ונעשו אחד כלולים זה בזה כמו שאמרנו. ואח\"כ נמצאים שניהם נפרדים בעולם. ודאי שבכחו של הזכר, נמצא הפרי של הנוקבא, בעולם, פירוש. המלה \u0003פריך,\u0004 קאי על פירות הנקבה, דהיינו על הנפש הנמשך בהשתוקקותה, ומשמיענו הכתוב, שאפילו נפש הנקבה אינה מבחינתה עצמה, אלא מכח התכללותה בנפש הזכר. וע\"כ אומר ממני פריך נמצא."],[10,"ד\"א בתיאובתא וכו':","פירוש אחר. על הכתוב ממני פריך נמצא. כי בהשתוקקות הנקבה עצמה שמשם באה בחי' הנקבה של הנפש, נמצא פריו של הזכר. כי לולא השתוקקות הנקבה אל הזכר, לא היו נעשים פירות בעולם, כלומר שלא היו שום תולדות. וז\"ש ממני פריך נמצא."],[11,"ויהי בימי אמרפל וגו':","ר' יוסי פתח, מי העיר ממזרח צדק יקראהו לרגלו וגו' מקרא זה בארוהו החברים, אבל מקרא זה בסוד החכמה הוא. כי למדנו, ז' רקיעים עשה הקב\"ה למעלה שהם ז\"ת דאצילות, חג\"ת נהי\"מ. וכולם הם כדי להכיר כבוד הקב\"ה. וכולם עומדים להודיע סוד האמונה העליונה."],[12,"ת\"ח אית רקיעא וכו':","בוא וראה, יש רקיע עליון סתום, למעלה מאלו שבעה רקיעים, שה\"ס בינה דאצילות, וזה הוא הרקיע המנהיג אותם ומאיר אל כולם. והוא לא אתידע, והיינו ג\"ר שלו, שה\"ס או\"א. ועומד בשאלה, שהיא לא ידוע, היינו ז\"ת שלו, שה\"ס ישסו\"ת, משום שהוא סתום ועמוק והכל תמהים בו. ומשום זה נקרא \u0003מ\"י,\u0004 היינו הז\"ת שלו, כמו שבארוהו, שכתוב מבטן \u0003מי\u0004 יצא הקרח. וזה נתבאר (לעיל בראשית א' דף רנ\"ו אות שי\"ג). וזהו רקיע העליון, העומד על כל שבעה הרקיעים."]],[[0,"","מָה הַטַּעַם הָיָה אֶחָד? שֶׁלֹּא הָיָה אַחֵר בָּעוֹלָם שֶׁעָלָה לֶאֱמוּנַת הַקָּדוֹשׁ בָּרוּךְ הוּא פְּרָט לוֹ. אָמַר לוֹ רַבִּי חִזְקִיָּה, וַהֲרֵי כָּתוּב וְאֶת הַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן? אָמַר לוֹ, עַד כָּעֵת הֵם לֹא הָיוּ בִּדְרָגוֹת עֶלְיוֹנוֹת שֶׁהִתְעַטֵּר בָּהֶם אַבְרָהָם."],[1,"","אַחַר כָּךְ אָמַר לוֹ, עוֹד שָׁמַעְתִּי, שֶׁלֹּא נִקְרָא אַבְרָהָם אֶחָד עַד שֶׁהִתְעַלָּה בְּיִצְחָק וְיַעֲקֹב. כֵּיוָן שֶׁהִתְעַלָּה בְּיִצְחָק וְיַעֲקֹב וְהָיוּ שְׁלָשְׁתָּם אֲבוֹת הָעוֹלָם, אָז נִקְרָא אַבְרָהָם אֶחָד. וְאָז הוּא תַּפּוּחַ בָּעוֹלָם, מְצֻיָּן מִכָּל בְּנֵי הָעוֹלָם. אָמַר לוֹ, יָפֶה אָמַרְתָּ."],[2,"","דָּבָר אַחֵר, כְּתַפּוּחַ בַּעֲצֵי הַיַּעַר - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. כֵּן דּוֹדִי - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. בְּצִלּוֹ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. חִמַּדְתִּי וְיָשַׁבְתִּי - בַּיּוֹם שֶׁנִּגְלָה הַקָּדוֹשׁ בָּרוּךְ הוּא עַל הַר סִינַי וְקִבְּלוּ יִשְׂרָאֵל תּוֹרָה וְאָמְרוּ נַעֲשֶׂה וְנִשְׁמָע (שמות כד)."],[3,"","וּפִרְיוֹ מָתוֹק לְחִכִּי - אֵלּוּ דִּבְרֵי הַתּוֹרָה שֶׁכָּתוּב בָּהֶם (תהלים יט) וּמְתוּקִים מִדְּבַשׁ וְנֹפֶת צוּפִים. דָּבָר אַחֵר וּפִרְיוֹ מָתוֹק לְחִכִּי - אֵלּוּ נִשְׁמוֹת הַצַּדִּיקִים שֶׁכֻּלָּן פְּרִי מַעֲשָׂיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וְעוֹמְדוֹת עִמּוֹ לְמַעְלָה."],[4,"","בֹּא רְאֵה, כָּל נִשְׁמוֹת הָעוֹלָם שֶׁהֵן פְּרִי מַעֲשָׂיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, כֻּלָּן אֶחָד בְּסוֹד אֶחָד. וּכְשֶׁיּוֹרְדוֹת לָעוֹלָם, כֻּלָּן נִפְרָדוֹת בִּגְוָנִים זָכָר וּנְקֵבָה, וְהֵן זָכָר וּנְקֵבָה מְחֻבָּרוֹת יַחַד."],[5,"","וּבֹא וּרְאֵה, תְּשׁוּקַת הַנְּקֵבָה לַזָּכָר עוֹשָׂה נֶפֶשׁ, וּתְשׁוּקַת הַזָּכָר לַנְּקֵבָה עוֹשָׂה נֶפֶשׁ. וְהָרָצוֹן שֶׁל תְּשׁוּקַת הַזָּכָר לַנְּקֵבָה וְהִתְדַּבְּקוּתוֹ בָּהּ מוֹצִיאָה נֶפֶשׁ, וְכוֹלֵל תְּשׁוּקַת (תשוקתו) הַנְּקֵבָה וְנוֹטֵל אוֹתָהּ. וְנִכְלֶלֶת הַתְּשׁוּקָה הַתַּחְתּוֹנָה בַּתְּשׁוּקָה שֶׁלְּמַעְלָה, וְנַעֲשֵׂית רָצוֹן אֶחָד בְּלִי פֵרוּד."],[6,"","וְאָז (נוטל) כּוֹלֵל הַכֹּל נְקֵבָה, וּמִתְעַבֶּרֶת מִן הַזָּכָר, וְהַתְּשׁוּקוֹת שֶׁל שְׁנֵיהֶם נִדְבָּקוֹת יַחַד, וְעַל כֵּן הַכֹּל כָּלוּל זֶה עִם זֶה. וּכְשֶׁהַנְּשָׁמוֹת יוֹצְאוֹת, הֵן יוֹצְאוֹת יַחַד זָכָר וּנְקֵבָה."],[7,"","אַחַר כָּךְ, כֵּיוָן שֶׁיּוֹרְדוֹת, נִפְרָדוֹת זוֹ לְצַד זֶה וְזוֹ לְצַד זֶה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְזַוֵּג אוֹתָן אַחַר כָּךְ. וְהַזִּוּוּג לֹא נִתָּן לְאַחֵר, אֶלָּא לַקָּדוֹשׁ-בָּרוּךְ-הוּא לְבַדּוֹ, שֶׁהוּא יוֹדֵעַ אֶת זִוּוּגָם לְחַבֵּר אוֹתָם כָּרָאוּי."],[8,"","אַשְׁרֵי הָאִישׁ שֶׁזּוֹכֶה בְמַעֲשָׂיו וְהוֹלֵךְ בְּדֶרֶךְ הָאֱמֶת כְּדֵי שֶׁתִּתְחַבֵּר נֶפֶשׁ בְּנֶפֶשׁ כְּמוֹ שֶׁהָיָה בַּתְּחִלָּה. שֶׁהֲרֵי אִם הוּא זוֹכֶה בְמַעֲשָׂיו, זֶהוּ אָדָם שָׁלֵם כָּרָאוּי. וּמִשּׁוּם כָּךְ כָּתוּב וּפִרְיוֹ מָתוֹק לְחִכִּי, שֶׁהוּא בְּתִקּוּן מְבֹרָךְ שֶׁיִּתְבָּרֵךְ מִמֶּנּוּ הָעוֹלָם, מִשּׁוּם שֶׁהַכֹּל תָּלוּי בְּמַעֲשֵׂי הָאָדָם אִם זוֹכֶה וְאִם לֹא זוֹכֶה."],[9,"","אָמַר רַבִּי חִזְקִיָּה, כָּךְ שָׁמַעְתִּי, שֶׁכָּתוּב (הושע יד) מִמֶּנִּי פֶּרְיְךְ נִמְצָא. הַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר לִכְנֶסֶת יִשְׂרָאֵל, וַדַּאי מִמֶּנִּי פֶּרְיְךְ נִמְצָא. לֹא כָתוּב פִּרְיִי נִמְצָא, אֶלָּא פֶּרְיְךְ. אוֹתָהּ תְּשׁוּקַת הַנְּקֵבָה שֶׁעוֹשָׂה נֶפֶשׁ וְנִכְלֶלֶת בְּכֹחַ הַזָּכָר, וְנִכְלֶלֶת נֶפֶשׁ בְּנֶפֶשׁ, וְנַעֲשׂוֹת אַחַת כּוֹלֶלֶת זוֹ בָּזֶה, כְּפי שֶׁאָמַרְנוּ. לְאַחַר מִכֵּן נִמְצָאִים שְׁנֵיהֶם בָּעוֹלָם, וַדַּאי בְּכֹחַ הַזָּכָר נִמְצָא פְּרִי הַנְּקֵבָה."],[10,"","דָּבָר אַחֵר, בִּתְשׁוּקַת הַנְּקֵבָה נִמְצָא פְּרִי הַזָּכָר, שֶׁאִם לֹא תְשׁוּקַת הַנְּקֵבָה לַזָּכָר, לֹא נַעֲשׂוּ פֵרוֹת לְעוֹלָמִים. זֶהוּ שֶׁכָּתוּב מִמֶּנִּי פֶּרְיְךְ נִמְצָא."],[11,"","וַיְהִי בִּימֵי אַמְרָפֶל מֶלֶךְ שִׁנְעָר וְגוֹ'. רַבִּי יוֹסֵי פָּתַח, (ישעיה מא) מִי הֵעִיר מִמִּזְרָח צֶדֶק יִקְרָאֵהוּ לְרַגְלוֹ וְגוֹ'. אֶת הַפָּסוּק הַזֶּה בֵּאֲרוּ הַחֲבֵרִים. אֲבָל הַפָּסוּק הַזֶּה הוּא בַּסּוֹד שֶׁל הַחָכְמָה, שֶׁהֲרֵי שָׁנִינוּ, שִׁבְעָה רְקִיעִים עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה, וְכֻלָּם לְהוֹדִיעַ אֶת כְּבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכֻלָּם עוֹמְדִים לְהוֹדִיעַ אֶת סוֹד הָאֱמוּנָה הָעֶלְיוֹנָה."],[12,"","בֹּא רְאֵה, יֵשׁ רָקִיעַ עֶלְיוֹן נִסְתָּר לְמַעְלָה מֵאוֹתָם הַשִּׁבְעָה, וְזֶה הוּא הָרָקִיעַ שֶׁמַּנְהִיגָם וּמֵאִיר לְכֻלָּם, וְזֶה אֵינוֹ נוֹדָע, וְעוֹמֵד בִּשְׁאֵלָה שֶׁלֹּא יְדוּעָה, מִשּׁוּם שֶׁהוּא נִסְתָּר וְעָמֹק, וְכֻלָּם תְּמֵהִים עָלָיו. וּמִשּׁוּם כָּךְ נִקְרָא מִ\"י, כְּמוֹ שֶׁפֵּרְשׁוּהָ שֶׁכָּתוּב (איוב לח) מִבֶּטֶן מִי יָצָא הַקָּרַח, וְנֶאֱמַר. וְזֶה הוּא הָרָקִיעַ הָעֶלְיוֹן שֶׁעוֹמֵד עַל כָּל אוֹתָם הַשִּׁבְעָה."]]],[["וְאִית לְתַתָּא רְקִיעָא דְּאִיהוּ תַּתָּאָה מִכֻּלְהוּ וְלָא נָהִיר, וּבְגִין דְּאִיהוּ תַּתָּאָה דְּלָא נָהִיר, הַהוּא רְקִיעָא דְּעֲלַיְיהוּ אִתְחַבַּר בֵּיהּ, וְאִלֵּין תְּרֵין אַתְוָון כָּלִיל לוֹן בְּגַוֵּיהּ וְאִקְרֵי יָם, דְּהַהוּא רְקִיעָא עִלָּאָה דְּאִקְרֵי מִ\"י.","בְּגִין דְּכָל אִנּוּן רְקִיעִין אָחֳרָנִין אִתְעֲבִידוּ נַחֲלִין וְעָאלִין לְגַבֵּיהּ, וּכְדֵין אִיהוּ יַם עִלָּאָה וְעֲבַד אִיבִּין וְנוּנִין לִזְנַיְיהוּ, וְעַל דָּא אָמַר דָּוִד (תהילים ק״ד:כ״ה) זֶה הַיָּם גָּדוֹל וּרְחַב יָדַיִם שָׁם רֶמֶשׂ וְאֵין מִסְפָּר חַיּוֹת קְטַנּוֹת עִם גְּדוֹלוֹת.","וְעַל דָּא כְּתִיב, (ישעיהו מ״א:ב׳) מִי הֵעִיר מִמִּזְרָח צֶדֶק יִקְרָאֵהוּ לְרַגְלוֹ. מִי הֵעִיר מִמִּזְרָח. דָּא אַבְרָהָם. צֶדֶק יִקְרָאֵהוּ לְרַגְלוֹ. (נ\"א דא שרה, ד\"א צדק יקראהו לרגלו וגו') דָּא הוּא רְקִיעָא תַּתָּאָה דְּכֻלְהוּ רְקִיעִין דְּאִתְעֲבִיד יָם. יִתֵּן לְפָנָיו גּוֹיִם. מַאן הַאי, הוּא רְקִיעָא תַּתָּאָה דְּאֲמָרָן דְּעֲבִיד נוּקְמִין וְאַפִּיל שָׂנְאִין. וּבְהַאי אִשְׁתַּבַּח דָּוִד וְאָמַר (תהילים י״ח:מ״א) וְאֹיבַי נָתַתָּה לִּי עֹרֶף וּמְשַׂנְאַי אַצְמִיתֵם.","(ישעיהו מ״א:ב׳) יִתֵּן לְפָנָיו גּוֹיִם. אִלֵּין אִנּוּן עַמִּין דְּהֲוָה רָדִיף עֲלֵיהוֹן אַבְרָהָם וְקוּדְשָׁא בְּרִיךְ הוּא הֲוָה קָטִיל לוֹן. (ומלכים ירד. (מאי ירד אלא) אלין מלכים דממנן לעילא עלייהו. יתן לפניו גוים, אלין עמין דלתתא) וּמְלָכִים יַרְדְּ אִלֵּין מְמַנָּן רַבְרְבָן דִּלְעֵילָא. דְּכַד עֲבִיד קוּדְשָׁא בְּרִיךְ הוּא דִּינָא בְּעָלְמָא (ד\"א בעמא) בְּכֹלָּא עֲבִיד דִּינָא בְּעֵילָא וְתַתָּא.","יִרְדְּפֵם יַעֲבוֹר שָׁלוֹם אֹרַח בְּרַגְלָיו לֹא יָבוֹא. יִרְדְּפֵם דָּא אַבְרָהָם. דְּאַבְרָהָם הֲוָה רָדִיף לוֹן, וְקוּדְשָׁא בְּרִיךְ הוּא הֲוָה עָבַר קַמֵּיהּ וְקָטִיל לוֹן. דִּכְתִיב יַעֲבוֹר שָׁלוֹם דָּא קוּדְשָׁא בְּרִיךְ הוּא דְּאִקְרֵי שָׁלוֹם.","אֹרַח בְּרַגְלָיו לא יָבוֹא. וְכִי סַלְקָא דַעְתָּךְ דְּהֲוָה אַבְרָהָם אָזִיל בְּגוֹ עֲנָנֵי אוֹ בְּגוֹ סוּסְוָון וּרְתִיכִין. אֶלָּא אֹרַח בְּרַגְלָיו לֹא יָבוֹא, דְּלָא הֲוָה אָזִיל קַמֵּיהּ דְּאַבְרָהָם לָא מַלְאָכָא וְלָא שְׁלִיחָא אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי דִּכְתִיב אֹרַח בְּרַגְלָיו. מַאן רַגְלָיו אִלֵּין מַלְאָכִין דְּאִנּוּן תְּחוֹתוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא כְּמָא דְאַתְּ אָמֵר, (זכריה י״ד:ד׳) וְעָמְדוּ רַגְלָיו בַּיּוֹם הַהוּא וְגו'.","דָּבָר אַחֵר מִי הֵעִיר מִמִּזְרָח. תָּא חֲזֵי, בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְעָר עָלְמָא לְאַיְיתָאָה לְאַבְרָהָם וּלְקָרְבָא לֵיהּ לְגַבֵּיהּ, הַאי אִתְעֲרוּתָא בְּגִין דְּזַמִּין יַעֲקֹב לְמֵיפַּק מִנֵּיהּ וּלְקָיְימָא תְּרֵיסַר שִׁבְטִין כֻּלְהוּ זַכָּאִין קַמֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא.","צֶדֶק יִקְרָאֵהוּ לְרַגְלוֹ. דְּקוּדְשָׁא בְּרִיךְ הוּא הֲוָה קָרֵי לֵיהּ תָּדִיר מִן יוֹמָא דְּאִתְבְּרֵי עָלְמָא כְּמָא דְאַתְּ אָמֵר, (ישעיהו מ״א:ד׳) קוֹרֵא הַדּוֹרוֹת מֵרֹאשׁ, וּבְגִין כָּךְ צֶדֶק יִקְרָאֵהוּ וַדַּאי. לְרַגְלוֹ, לְאִתְחַבְּרָא בֵּיהּ בְּפוּלְחָנֵיהּ וּלְקָרְבָא לֵיהּ לְגַבֵּיהּ. כְּמָא דְאַתְּ אָמֵר, (שמות י״א:ח׳) הָעָם אֲשֶׁר בְּרַגְלֶיךָ.","דָּבָר אַחֵר מִי הֵעִיר מִמִּזְרָח. דְּמִתַּמָּן שֵׁרוּתָא דִּנְהוֹרָא לְאַנְהָרָא. בְּגִין דְּדָרוֹם הַהוּא תּוּקְפָא דִילֵיהּ מִגּוֹ מִזְרָח אִיהוּ. וְעַל דָּא מִי הֵעִיר הַהוּא נְהוֹרָא דְּדָרוֹם. מִמִּזְרָח, בְּגִין דְּאִיהוּ נָטִיל וְאִתְּזָן בְּקַדְמִיתָא, וְתִיאוּבְתָּא דְּהַהוּא רְקִיעָא עִלָּאָה לְמֵיהַב לֵיהּ לְמִזְרָח.","צֶדֶק יִקְרָאֵהוּ לְרַגְלוֹ. דָּא מַעֲרָב, דְּאִיהוּ קָרֵי לֵיהּ תָּדִיר וְלָא שָׁכִיךְ כְּמָא דְאַתְּ אָמֵר (תהילים פ״ג:ב׳) אֱלֹהִים אַל דֳּמִי לָךְ אַל תֶּחרָשׁ וְאַל תִּשְׁקוֹט אֵל. בְּגִין דְּמַעֲרָב אִתְעַר תָּדִיר לְגַבֵּיהּ. יִתֵּן לְפָנָיו גּוֹיִם וּמְלָכִים יַרְדְּ. דְּהָא מִנֵּיהּ קַבִּיל תּוּקְפָא לְאַכְנָעָא כָּל אִנּוּן עַמִּין דְּעָלְמָא.","רַבִּי יְהוּדָה אָמַר (ישעיהו מ״א:ב׳) מִי הֵעִיר מִמִּזְרָח, דָּא אַבְרָהָם דְּלָא נָטִיל אִתְעֲרוּתָא לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא אֶלָּא מִמִּזְרָח, בְּגִין דְּחָמָא שִׁמְשָׁא דְּנָפִיק בְּצַפְרָא מִסִּטְרָא דְמִזְרָח, נָטִיל אִתְעֲרוּתָא לְנַפְשֵׁיהּ דְּאִיהוּ קוּדְשָׁא בְּרִיךְ הוּא. אָמַר דָּא הוּא מַלְכָּא דְּבָרָא יָתִי. פְּלַח לֵיהּ כָּל הַהוּא יוֹמָא, לְרַמְשָׁא חָמָא שִׁמְשָׁא דְּאִתְכְּנִישׁ (וירחא נפקת) וְסִיהֲרָא נָהֲרָא. אָמַר דָּא הוּא וַדַּאי דְּשַׁלִּיט עַל הַהוּא פּוּלְחָנָא דְּפָלָחִית כָּל הַאי יוֹמָא, דְּהָא אִתְחֲשַׁךְ קַמֵּיהּ וְלָא נָהִיר. פָּלַח לֵיהּ כָּל הַהוּא לֵילְיָא.","לְצַפְרָא חָמָא דְּאָזְלָא חֲשׁוֹכָא וְאִתְנְהִיר סִטְרָא דְמִזְרָח. אָמַר וַדַּאי כָּל אִלֵּין מַלְכָּא אִית עֲלַיְיהוּ וְשַׁלִּיט דְּאַנְהִיג לוֹן. כֵּיוָן דְּחָמָא קוּדְשָׁא בְּרִיךְ הוּא תִּיאוּבְתָּא דְּאַבְרָהָם לְגַבֵּיהּ, כְּדֵין אִתְגָּלֵי עֲלוֹי וּמַלִּיל עִמֵּיהּ, דִּכְתִיב צֶדֶק יִקְרָאֵהוּ לְרַגְלוֹ. דְּמַלִּיל עִמֵּיהּ וְאִתְגְלֵי עֲלֵיהּ."],[[0,"ואית לתתא וכו':","ויש למטה רקיע, דהיינו המלכות, שהוא התחתון מכולם, ואינו מאיר. ומשום שהוא תחתון שאינו מאיר, אותו רקיע העליון שעליהם שהיא בינה הנקראת מ\"י, מתחבר בו. כלומר שרקיע העליון, שה\"ס \u0003מ\"י,\u0004 אינו מאיר החכמה לשום רקיע מהז\"ת אלא להתחתון שבהם, שהיא מלכות (כנ\"ל ב\"א רע\"ז אות שמ\"ד). ואלו ב' האותיות \u0003מ' י',\u0004 של רקיע העליון הנקרא \u0003מ\"י,\u0004 הוא כולל אותם בתוכו, ונקרא \u0003ים\u0004 שהם אותיות \u0003מ\"י.\u0004"],[1,"בגין דכל אינון וכו':","משום שכל אלו רקיעים האחרים שלמעלה מרקיע התחתון, שהם חג\"ת נה\"י. נעשו נחלים ונכנסים לתוכו ואז הוא נעשה ים עליון ועושה פירות ודגים למינם, שהם המוחין שמשפיע לבי\"ע. ועליו אמר דוד, זה הים גדול ורחב ידים שם רמש ואין מספר חיות קטנות עם גדולות."],[2,"ועל דא כתיב וכו':","ועל זה כתוב, מי העיר ממזרח צדק יקראהו לרגלו, מי העיר ממזרח, זה אברהם. כלומר, אברהם העיר את רקיע העליון הנקרא \u0003מ\"י,\u0004 שישפיע החכמה לרקיע התחתון הנקרא \u0003י\"ם. צדק יקראהו לרגלו,\u0004 זה הוא רקיע התחתון מכל ז' הרקיעים, שנעשה \u0003י\"ם. יתן לפניו גוים,\u0004 שואל מי הוא לפניו. ואומר, הוא רקיע התחתון שאמרנו, שהוא העושה נקמות ומפיל השונאים. ובו משתבח דוד ואמר, ואויבי נתת לי עורף משנאי אצמיתם. פירוש כי הארת החכמה משמידה כל החצונים והקליפות, ולפי שרק רקיע התחתון מקבל הארת החכמה, ולא ששה העליונים ממנו, ע\"כ אומר, שהוא עושה נקמות ומפיל האויבים, וכן יתן לפניו גוים."],[3,"יתן לפניו גוים:","אלו הם העמים שאברהם היה רודף אחריהם, והקב\"ה הורגם. \u0003ומלכים ירד,\u0004 אלו הם המלאכים הממונים עליהם למעלה. כי כשהקב\"ה עושה דין בעולם, בכולם הוא עושה הדין, למעלה ולמטה, דהיינו בהעמים שלמטה ובשרים שלהם שלמעלה בשמים."],[4,"ירדפם יעבור שלום וגו': ירדפם,","זהו אברהם. כי אברהם היה רודף אותם, והקב\"ה היה עובר לפניו והורגם. שכתוב, \u0003יעבור שלום,\u0004 זהו הקב\"ה שנקרא שלום."],[5,"אורח ברגליו לא יבא:","שואל וכי יעלה על דעתך, שהיה אברהם הולך בתוך העננים, או על סוסים ומרכבות. כי נאמר אורח ברגליו לא יבא. ומשיב, אלא, אורח ברגליו לא יבא, פירושו, שלא מלאך ולא שליח הלך לפני אברהם, אלא הקב\"ה בלבדו, שכתוב \u0003אורח ברגליו,\u0004 ושואל מי המה רגליו, ומשיב, אלו הם המלאכים שהם מתחת הקב\"ה. כמו שאתה אומר, ועמדו רגליו ביום ההוא וגו', שהוא המלאכים הנקראים רגליו. ושיעור הכתוב הוא, \u0003רגליו,\u0004 שהם המלאכים, \u0003לא יבאו\u0004 אז \u0003באורח\u0004 אברהם. אלא הקב\"ה לבדו היה בדרכו."],[6,"ד\"א, מי העיר ממזרח:","בוא וראה, בשעה שהעיר הקב\"ה את העולם שהוא מלכות, להביא את אברהם ולקרבהו אצלו, היה התעוררות הזה, בשביל יעקב, שה\"ס מזרח, בשביל שיעקב עתיד לצאת ממנו, ולהעמיד ממנו י\"ב שבטים, שהיו כולם צדיקים לפני הקב\"ה. ושיעור הכתוב, \u0003מ\"י\u0004 שהוא בינה, \u0003העיר\u0004 את העולם להביא את אברהם, \u0003ממזרח\u0004 בשביל \u0003מזרח\u0004 שהוא יעקב. כי אברהם יצחק יעקב, מכונים, דרום צפון, מזרח."],[7,"צדק יקראהו לרגלו:","הקב\"ה היה קורא אותו את יעקב, תמיד, מיום שנברא העולם. כמש\"א, קורא הדורות מראש. ומשום זה \u0003צדק,\u0004 שהיא המלכות, \u0003יקראהו\u0004 ודאי. \u0003לרגלו,\u0004 פירושו, להתחבר בו בעבודתו ולקרבהו אליו. כמו שאתה אומר העם אשר ברגליך, שפירושו העם המחובר בך. אף \u0003לרגלו,\u0004 שבכאן פירושו להתחבר עמו."],[8,"ד\"א מי העיר ממזרח:","כי משם האור מתחיל להאיר. משום שדרום, שהוא חסד, כל תוקף האור שבו הוא ממזרח, שהוא ת\"ת, וע\"כ אוה\"כ \u0003מי העיר\u0004 את אור הדרום שהוא חסד, \u0003ממזרח,\u0004 המזרח שהוא ת\"ת העיר אותו, כי הוא, דהיינו הת\"ת, לוקח וניזון תחילה, ואח\"כ הוא נותן לשש קצוות הכלולים בת\"ת, שבתוכם הוא הדרום, שהוא חסד. וחשקו של רקיע העליון, דהיינו בינה, הוא להשפיע למזרח, שהוא ת\"ת. כלומר שהמקבל מבינה הוא ת\"ת, שהוא העיקר מהשש קצוות, ואח\"כ הוא משפיע להקצוות. שאור החסד בתוכם, ונמצא הדרום אינו מקבל מבינה, אלא ממזרח. וע\"כ אומר הכתוב מי העיר ממזרח."],[9,"צדק יקראהו לרגלו:","זהו מערב, שהוא מלכות, שהוא קורא למזרח תמיד, שהוא ת\"ת. ואינו שוקט. כמש\"א אלקים אל דמי לך וגו', משום שהמערב שהוא המלכות הנק' אלקים, מתעוררת אליו תמיד. יתן לפניו גוים ומלכים ירד, כי ממנו, מן המזרח, מקבל כח להכניע כל עמי העולם."],[10,"ר' יהודה אומר וכו':","רי\"א מי העיר ממזרח זהו אברהם, שלא לקח התעוררות אל הקב\"ה אלא ממזרח. כי כשראה את השמש יוצא בבקר מצד מזרח, לקח לעצמו התעוררות, שהוא הקב\"ה, אמר על השמש, זהו המלך שברא אותי. ועבד אל השמש כל היום, לערב ראה ששקעה השמש והלבנה האירה, אמר על הלבנה, זהו ודאי, השולט על עבודה ההיא שעבד כל אותו היום, אל השמש, שהרי השמש נחשך מפני הלבנה ואינו מאיר, עבד אל הלבנה כל אותה הלילה."],[11,"לצפרא חמא וכו':","בבוקר ראה שהלבנה הולכת לה חשוכה, והאיר צד המזרח, אמר, בודאי, שיש מלך ושליט על כל אלו שמנהיג אותם. כיון שראה הקב\"ה חשקו של אברהם אליו. אז נגלה אליו ודיבר עמו. שכתוב \u0003צדק יקראהו לרגלו.\u0004 צדק זה הקב\"ה שקרא אותו, ודבר עמו ונגלה עליו."]],[[0,"","וְיִשִׁ לְמַטָּה רָקִיעַ שֶׁהוּא תַּחְתּוֹן מִכֻּלָּם וְלֹא מֵאִיר. וּמִשּׁוּם שֶׁהוּא תַּחְתּוֹן שֶׁלֹּא מֵאִיר, אוֹתוֹ הָרָקִיעַ שֶׁעֲלֵיהֶם מִתְחַבֵּר עִמּוֹ, וּשְׁתֵּי הָאוֹתִיּוֹת הַלָּלוּ הוּא כּוֹלְלָם בְּתוֹכוֹ, וְנִקְרָא יָם, שֶׁאוֹתוֹ הָרָקִיעַ הָעֶלְיוֹן שֶׁנִּקְרָא מִ\"י."],[1,"","מִשּׁוּם שֶׁכָּל אוֹתָם הָרְקִיעִים הָאֲחֵרִים נַעֲשִׂים נְחָלִים וְנִכְנָסִים אֵלָיו, וְאָז הוּא הַיָּם הָעֶלְיוֹן, וְעוֹשֶׂה פֵרוֹת וְדָגִים לְמִינֵיהֶם. וְעַל זֶה אָמַר דָּוִד (תהלים קד) זֶה הַיָּם גָּדוֹל וּרְחַב יָדָיִם שָׁם רֶמֶשׂ וְאֵין מִסְפָּר חַיּוֹת קְטַנּוֹת עִם גְּדֹלוֹת."],[2,"","וְעַל זֶה כָּתוּב (ישעיה מא) מִי הֵעִיר מִמִּזְרָח צֶדֶק יִקְרָאֵהוּ לְרַגְלוֹ. מִי הֵעִיר מִמִּזְרָח - זֶה אַבְרָהָם. צֶדֶק יִקְרָאֵהוּ לְרַגְלוֹ - (נ\"א: זו שרה, ד\"א צדק יקראהו לרגלו וגו') זֶה הוּא הָרָקִיעַ הַתַּחְתּוֹן שֶׁל כָּל הָרְקִיעִים שֶׁנַּעֲשָׂה יָם. יִתֵּן לְפָנָיו גּוֹיִם, מִי זֶה? הוּא הָרָקִיעַ הַתַּחְתּוֹן שֶׁאָמַרְנוּ, שֶׁעוֹשֶׂה נְקָמוֹת וּמַפִּיל שׂוֹנְאִים. וּבָזֶה הִשְׁתַּבַּח דָּוִד וְאָמַר (תהלים יח) וְאֹיְבַי נָתַתָּה לִּי עֹרֶף וּמְשַׂנְאַי אַצְמִיתֵם."],[3,"","(ישעיה מא) יִתֵּן לְפָנָיו גּוֹיִם - אֵלּוּ הֵם הָעַמִּים שֶׁהָיָה אַבְרָהָם רוֹדֵף אַחֲרֵיהֶם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה הוֹרֵג אוֹתָם. (ומלכים ירד, (מה זה ירד, ' אלא) אלו המלכים שממנים למעלה עליהם, יתן לפניו גוים אלו העמים שלמטה) וּמְלָכִים יַרְדְּ - אֵלּוּ הַמְמֻנִּים הַגְּדוֹלִים שֶׁלְּמַעְלָה. שֶׁכַּאֲשֶׁר הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה דִין בָּעוֹלָם (ד\"א בעם), הוּא עוֹשֶׂה דִין בַּכֹּל, בְּמַעְלָה וּבְמַטָּה."],[4,"","(ישעיה מא ג) יִרְדְּפֵם יַעֲבוֹר שָׁלוֹם אֹרַח בְּרַגְלָיו לֹא יָבוֹא, (ישעיה מא ג). יִרְדְּפֵם - זֶה אַבְרָהָם, שֶׁאַבְרָהָם הָיָה רוֹדֵף אוֹתָם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה עוֹבֵר לְפָנָיו וְהוֹרֵג אוֹתָם, שֶׁכָּתוּב יַעֲבוֹר שָׁלוֹם. זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁנִּקְרָא שָׁלוֹם."],[5,"","אֹרַח בְּרַגְלָיו לֹא יָבוֹא, וְכִי עוֹלֶה עַל דַּעְתְּךְ שֶׁאַבְרָהָם הָיָה הוֹלֵךְ בְּתוֹךְ הָעֲנָנִים אוֹ בְּתוֹךְ סוּסִים וּמֶרְכָּבוֹת? אֶלָּא אֹרַח בְּרַגְלָיו לֹא יָבוֹא, שֶׁלֹּא הָיָה הוֹלֵךְ לִפְנֵי אַבְרָהָם לֹא מַלְאָךְ וְלֹא שָׁלִיחַ, אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ, שֶׁכָּתוּב אֹרַח בְּרַגְלָיו. מִי זֶה רַגְלָיו? אֵלּוּ הַמַּלְאָכִים שֶׁתַּחְתָּיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנֶּאֱמַר (זכריה יד) וְעָמְדוּ רַגְלָיו בַּיּוֹם הַהוּא וְגוֹ'."],[6,"","דָּבָר אַחֵר מִי הֵעִיר מִמִּזְרָח - בֹּא רְאֵה, בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הֵעִיר אֶת הָעוֹלָם לְהָבִיא אֶת אַבְרָהָם וּלְקָרֵב אוֹתוֹ אֵלָיו, הַהִתְעוֹרְרוּת הַזּוֹ מִשּׁוּם שֶׁעָתִיד הָיָה לָצֵאת מִמֶּנּוּ יַעֲקֹב וּלְהַעֲמִיד שְׁנֵים עָשָׂר שְׁבָטִים כֻּלָּם צַדִּיקִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא."],[7,"","צֶדֶק יִקְרָאֵהוּ לְרַגְלוֹ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה תָמִיד קוֹרֵא לוֹ מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה מא) קֹרֵא הַדֹּרוֹת מֵרֹאשׁ. וּמִשּׁוּם כָּךְ, צֶדֶק יִקְרָאֵהוּ וַדַּאי. לְרַגְלוֹ - לְהִתְחַבֵּר בּוֹ בַּעֲבוֹדָתוֹ וּלְקָרֵב אוֹתוֹ אֵלָיו, כְּמוֹ שֶׁנֶּאֱמַר (שמות יא) הָעָם אֲשֶׁר בְּרַגְלֶיךְ."],[8,"","דָּבָר אַחֵר מִי הֵעִיר מִמִּזְרָח - שֶׁמִּשָּׁם רֵאשִׁית הָאוֹר לְהָאִיר. מִשּׁוּם שֶׁהַדָּרוֹם, אוֹתוֹ הַחֹזֶק שֶׁל הָאוֹר שֶׁלּוֹ הוּא מִן הַמִּזְרָח. וְעַל כֵּן, מִי הֵעִיר - אוֹתוֹ הָאוֹר שֶׁל הַדָּרוֹם. מִמִּזְרָח - מִשּׁוּם שֶׁהוּא נוֹסֵעַ וְנִזּוֹן בָּרִאשׁוֹנָה, וּתְשׁוּקָתוֹ שֶׁל אוֹתוֹ הָרָקִיעַ הָעֶלְיוֹן לָתֵת לַמִּזְרָח."],[9,"","צֶדֶק יִקְרָאֵהוּ לְרַגְלוֹ - זֶה הַמַּעֲרָב, שֶׁהוּא תָמִיד קוֹרֵא לוֹ וְלֹא שׁוֹקֵט, כְּמוֹ שֶׁנֶּאֱמַר (תהלים פג) אֱלֹהִים אַל דֳּמִי לָךְ אַל תֶּחֱרַשׁ וְאַל תִּשְׁקֹט אֵל, מִשּׁוּם שֶׁהַמַּעֲרָב תָּמִיד מִתְעוֹרֵר אֵלָיו. יִתֵּן לְפָנָיו גּוֹיִם וּמְלָכִים יַרְדְּ, שֶׁהֲרֵי מִמֶּנּוּ מְקַבֵּל אֶת הַחֹזֶק לְהַכְנִיעַ אֶת כָּל אוֹתָם הָעַמִּים שֶׁל הָעוֹלָם."],[10,"","רַבִּי יְהוּדָה אָמַר, (ישעיה מא) מִי הֵעִיר מִמִּזְרָח - זֶה אַבְרָהָם, שֶׁלֹּא נָטַל הִתְעוֹרְרוּת אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶלָּא מִמִּזְרָח. מִשּׁוּם שֶׁרָאָה אֶת הַשֶּׁמֶשׁ שֶׁיּוֹצֵאת בַּבֹּקֶר מִצַּד הַמִּזְרָח, נָטַל הִתְעוֹרְרוּת לְנַפְשׁוֹ שֶׁהוּא הַקָּדוֹשׁ בָּרוּךְ הוּא. אָמַר, זֶה הוּא הַמֶּלֶךְ שֶׁבָּרָא אוֹתִי. עָבַד לוֹ כָּל הַיּוֹם הַהוּא. לָעֶרֶב רָאָה הַשֶּׁמֶשׁ שֶׁנֶּאֱסַף (והלבנה יוצאת) וְהַלְּבָנָה מְאִירָה. אָמַר, זֶה הוּא וַדַּאי שֶׁשּׁוֹלֵט עַל אוֹתָהּ הָעֲבוֹדָה שֶׁעָבַדְתִּי כָּל הַיּוֹם הַזֶּה, שֶׁהִנֵּה נֶחְשַׁךְ לְפָנָיו וְלֹא מֵאִיר. עָבַד לוֹ כָּל הַלַּיְלָה הַהוּא."],[11,"","לַבֹּקֶר רָאָה שֶׁהָלְכָה הַחֲשֵׁכָה וְהֵאִיר צַד הַמִּזְרָח. אָמַר, וַדַּאי כָּל אֵלּוּ יֵשׁ עֲלֵיהֶם מֶלֶךְ וְשַׁלִּיט שֶׁמַּנְהִיג אוֹתָם. כֵּיוָן שֶׁרָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת תְּשׁוּקָתוֹ שֶׁל אַבְרָהָם אֵלָיו, אֲזַי הִתְגַּלָּה אֵלָיו וְדִבֵּר עִמּוֹ, שֶׁכָּתוּב צֶדֶק יִקְרָאֵהוּ לְרַגְלוֹ, שֶׁדִּבֵּר עִמּוֹ וְהִתְגַּלָּה עָלָיו."]]],[["רַבִּי יִצְחָק פָּתַח (ישעיהו מ״ה:י״ט) דּוֹבֵר צֶדֶק מַגִּיד מֵישָׁרִים. קוּדְשָׁא בְּרִיךְ הוּא כָּל מִלּוֹי אִנּוּן בְּקוּשְׁטָא, וְעֲבִיד מֵישָׁרִים, בְּמָּה עֲבִיד מֵישָׁרִים. בְּגִין דְּכַד בְּרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא, לָא הֲוָה קָאִים וְהֲוָה מִתְמוֹטֵט לְהָכָא וּלְהָכָא. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְעָלְמָא, מַה לָּךְ דְּאַתְּ מִתְמוֹטֵט. אָמַר לֵיהּ, רִבּוֹנוֹ שֶׁל עוֹלָם לָא יָכִילְנָא לְמֵיקַם דְּלֵית בִּי יְסוֹדָא עַל מַה דְּאִתְקַיָּים.","אָמַר לֵיהּ הָא אֲנָא זַמִּין לְמֵיקַם בָּךְ חַד צַדִּיק דְּאִיהוּ אַבְרָהָם דִּי יַרְחִים לִי. מִיָּד קָאִים עָלְמָא בְּקִיּוּמֵיהּ הֲדָא הוּא דִכְתִיב, (בראשית ב) אֵלֶּה תּוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם אַל תִּקְרָא בְּהִבָּרְאָם אֶלָּא בְּאַבְרָהָם. בְּאַבְרָהָם מִתְקַיֵּים עָלְמָא.","אָמַר רַבִּי חִיָּיא (ישעיהו מ״ה:י״ט) מַגִּיד מֵישָׁרִים. דְּהָא אָתִיב לֵיהּ עָלְמָא לְקוּדְשָׁא בְּרִיךְ הוּא הַהוּא אַבְרָהָם זַמִּין הוּא דְּיִפְקוּן מִנֵּיהּ בְּנִין דְּיַחֲרִיבוּ מַקְדְּשָׁא וְיוֹקִידוּ אוֹרַיְיתָא. (נ\"א לנפקא מניה ישמעאל, אמר ליה הא יצחק, אמר ליה זמין למיפק מניה עשו חייבא דיחרב בי מקדשא ויוקיד אורייתא), אָמַר לֵיהּ זַמִּין חַד בַּר נָשׁ לְמֵיפַּק מִנֵּיהּ דְּאִיהוּ יַעֲקֹב וְיִפְקוּן מִנֵּיהּ תְּרֵיסַר שִׁבְטִין כֻּלְהוּ זַכָּאִין. מִיָּד אִתְקְיַּים עָלְמָא בְּגִינֵיהּ הֲדָא הוּא דִכְתִיב מַגִּיד מֵישָׁרִים.","רַבִּי אֶלְעָזָר אָמַר הָא אַתְעַרְנָא וַיְדַבֵּר וַיַּגֵּד וַיֹּאמֶר כֻּלְהוּ לְטַעֲמַיְיהוּ מִתְפָּרְשָׁן. וַיְדַבֵּר אִיהוּ בְּאִתְגַּלְיָא דַּרְגָּא לְבַר, דְּלָא אִיהוּ דַּרְגָּא פְּנִימָאָה כְּאִנּוּן דַּרְגִּין עִלָּאִין, וְדָא אִיהוּ (ישעיה מה) דּוֹבֵר צֶדֶק.","וַיַּגֵּד אִיהוּ רֶמֶז לְדַרְגָּא פְּנִימָאָה עִלָּאָה דְּשַׁלְטָאָה עַל דִּבּוּר, וְדָא הוּא מַגִּיד מֵישָׁרִים. מַאן מֵישָׁרִים דָּא דַרְגָּא עִלָּאָה דְיַעֲקֹב שַׁרְיָיא בֵּיהּ הֲדָא הוּא דִכְתִיב, (תהילים צ״ט:ד׳) אַתָּה כּוֹנַנְתָּ מֵישָׁרִים. וּבְגִין כָּךְ מַגִּיד כְּתִיב, וְלָא כְּתִיב דּוֹבֵר.","אָמַר רַבִּי יִצְחָק וְהָא כְּתִיב, (דברים ד׳:י״ג) וַיַּגֵּד לָכֶם אֶת בְּרִיתוֹ. אָמַר לֵיהּ הָכִי הוּא וַדַּאי אִיהוּ דַרְגָּא דְּשָׁלְטָא עַל תַּתָּאָה דְּאִיהוּ דּוֹבֵר צֶדֶק. וְכֹלָּא (בה) אִיהוּ (נ\"א לאשתלא איבא) לְאִסְתַּכָּלָא (איכא) הָכָא. (נ\"א אתיא) תָּא חֲזֵי, דְאַף עַל גַּב דְּדִּבּוּר אִיהוּ תַּתָּאָה, לָא תֵימָא דְּלָא עִלָּאָה אִיהוּ, אֶלָּא וַדַּאי דִּבּוּר מַלְיָיא אִיהוּ מִכֹּלָּא וְדַרְגָּא עִלָּאָה אִיהוּ. וְסִימָנִיךְ (דברים לכ) כִּי לא דָּבָר רֵק הוּא מִכֶּם.","רַבִּי אֶלְעָזָר הֲוָה אָזִיל לְבֵי חֲמוֹי, וְהֲווּ עִמֵּיהּ רַבִּי חִיָּיא וְרַבִּי יוֹסֵי וְרַבִּי חִזְקִיָּה. אָמַר רַבִּי אֶלְעָזָר הָא חָמֵינָא דְּאִתְעֲרוּתָא דִלְעֵילָא לָאו אִיהוּ אֶלָּא כַּד אִתְעַר לְתַתָּא, דְּהָא אִתְעֲרוּתָא דִלְעֵילָא בְּתִיאוּבְתָּא דִלְתַתָּא תַּלְיָיא (מלתא).","פָּתַח וְאָמַר, (תהילים פ״ג:ב׳) אֱלהִים עַל דֳּמִי לָךְ אַל תֶּחרָשׁ וְאַל תִּשְׁקוֹט אֵל. דָּא הוּא אִתְעֲרוּתָא דִלְתַתָּא בְּגִין לְשַׁלְטָאָה. אָמַר דָּוִד, אֱלֹהִים אַל דֳּמִי לָךְ, לְאַתְעָרָא לְגַבֵּי עִלָּאָה וּלְאִתְחַבְּרָא גַּבֵּי יָמִינָא.","מַאי טַעְמָא בְּגִין (תהילים פ״ג:ו׳) כִּי הִנֵּה אוֹיְבֶיךָ יֶהֱמָיוּן וְגו' (וכתיב) כִּי נוֹעֲצוּ לֵב יַחְדָּיו עָלֶיךָ בְּרִית יִכְרוֹתוּ, וּבְגִין כָּךְ אֱלהִים אַל דֳּמִי לָךְ לְאַתְעָרָא לְגַבֵּי עֵילָא, דְּהָא כְּדֵין אִתְעָרַת יָמִינָא וּקְטִירַת לָהּ בַּהֲדָהּ. וְכַד אִתְקַשְׁרַת בְּיָמִינָא כְּדֵין אִתְבַּר שָׂנְאִין דִּכְתִיב (שמות ט״ו:ו׳) יְמִינְךָ יְיָ נֶאְדָּרִי בַּכֹּחַ יְמִינְךָ יְיָ תִּרְעַץ אוֹיֵב.","וְתָא חֲזֵי בְּשַׁעֲתָא דְּאִתְחַבָּרוּ כָּל אִנּוּן מַלְכִין לְאַגָּחָא קְרָבָא עֲלֵיהּ דְּאַבְרָהָם, אִתְיָיעֲטוּ לְאַעֲבָרָא לֵיהּ מִן עָלְמָא, וְכֵיוָן דְּשָׁלְטוּ בְּלוֹט בַּר אַחוּהָ דְּאַבְרָהָם מִיָּד אֲזְלוּ, דִּכְתִיב וַיִּקְחוּ אֶת לוֹט וְאֶת רְכוּשׁוֹ בֶּן אֲחִי אַבְרָם וַיֵּלֵכוּ. מַאי טַעְמָא, בְּגִין דְּדִיוּקְנֵיהּ דְּלוֹט הֲוָה דָמֵי לְאַבְרָהָם, וּבְגִין כָּךְ וַיֵּלֵכוּ, דְּכָל הַהוּא קְרָבָא בְּגִינֵיהּ הֲוָה.","מַאי טַעְמָא. בְּגִין דְּהֲוָה אַבְרָהָם אַפִּיק בְּנֵי עָלְמָא מִפּוּלְחָנָא נוּכְרָאָה וְאָעִיל לוֹן בְּפוּלָחָנָא דְקוּדְשָׁא בְּרִיךְ הוּא. וְתוּ קוּדְשָׁא בְּרִיךְ הוּא אַתְעַר לוֹן בְּעָלְמָא בְּגִין לְגַדְּלָא שְׁמָא דְאַבְרָהָם בְּעָלְמָא וּלְקָרְבָא לֵיהּ לְפוּלְחָנֵיהּ.","וְרָזָא דְמִלָּה כֵּיוָן דְּאַבְרָהָם אִתְעַר לְמִרְדַּף אֲבַּתְרַיְיהוּ כְּדֵין אֱלֹהִים אַל דֳּמִי לָךְ עַד דְּאִתְקַשַּׁר כֹּלָּא בְּאַבְרָהָם, וְכַד אִתְקַשַּׁר כֹּלָּא בְּאַבְרָהָם כְּדֵין אִתְבָּרוּ כֻּלְהוּ מַלְכִין מִקַּמֵּיהּ כְּדְקָא אֲמָרָן דִּכְתִיב יְמִינְךָ יְיָ תִּרְעַץ אוֹיֵב וְגו':","וּמַלְכִּי צֶדֶק מֶלֶךְ שָׁלֵם הוֹצִיא לֶחֶם וָיָיִן. רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר (תהילים ע״ו:ג׳) וַיְהִי בְּשָׁלֵם סֻכּוֹ וְגו'. תָּא חֲזֵי כַּד סָלִיק בִּרְעוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא לְמִבְרֵי עָלְמָא חַד שַׁלְהוֹבָא דְּבוּצִינָא דְּקַרְדִינוּתָא. וּנְשַׁף זִיקָא בְּזִיקָא חָשְׁכַאת וְאוֹקִידַת. וְאַפִּיק מִגּוֹ סִטְרֵי תְּהוֹמָא חַד טִיף וְחִבֵּר לוֹן כְּחַד וּבָרָא בְּהוּ עָלְמָא."],[[0,"ר' יצחק פתח וכו':","ר\"י פתח. דובר צדק מגיד מישרים, הקב\"ה, כל דבריו אמת, ועושה מישרים, ושואל, במה עושה מישרים. ואומר, כי כאשר ברא אלקים את העולם לא היה העולם עומד, אלא היה מתמוטט לכאן ולכאן, אמר לו הקב\"ה אל העולם: מה לך שאתה מתמוטט, א\"ל רבונו של עולם איני יכול לעמוד. כי אין בי יסוד שעליו אעמוד."],[1,"א\"ל הא אנא וכו':","א\"ל הקב\"ה, הרי אני עתיד להעמיד בתוכך צדיק אחד, שהוא אברהם, שהוא יאהב אותי. מיד עמד העולם על קיומו. הה\"ד אלה תולדות השמים וארץ בהבראם. אל תקרי בהבראם אלא באברהם, כי באברהם נתקיים העולם, (ועי' לעיל בהקדמת הזהר דף ס\"א והלאה, שנתבאר זה באורך)."],[2,"אמר ר' חייא וכו':","אר\"ח. מגיד מישרים פירושו כי העולם השיב להקב\"ה, אותו אברהם. עתיד שיצאו ממנו בנים שיחריבו את בית המקדש וישרפו התורה. אמר לו הקב\"ה אדם אחד עתיד לצאת ממנו, שהוא יעקב, ויצאו ממנו י\"ב שבטים כולם צדיקים. מיד נתקיים העולם בשבילו. וזה שכתוב מגיד מישרים. כי מישרים ה\"ס יעקב שהוא ת\"ת."],[3,"ר' אלעזר וכו':","ר\"א אמר, הנה הערנו, וידבר, ויגד, ויאמר, יש לכל אחד טעם מיוחד. וידבר, פירושו בגלוי, שה\"ס מלכות שנק' עלמא דאתגליא. והיא מדרגה חיצוניות לכולן, ואינה מדרגה פנימיות כאלו מדרגות העליונות ממנה. וזה היא \u0003דובר צדק.\u0004 דהיינו המלכות שהיא בחינת דיבור, כמבואר."],[4,"ויגד,","רומז למדרגה פנימיות עליונה ממלכות, שהיא שולטת על הדיבור שהיא מלכות. וזה הוא \u0003מגיד משרים,\u0004 מי הוא \u0003מישרים\u0004 זה הוא מדרגה עליונה, אשר יעקב שורה בה, דהיינו ת\"ת. וז\"ש אתה כוננת מישרים ועל כן כתוב כאן \u0003מגיד\u0004 ואינו כתוב \u0003דובר,\u0004 להורות שהכונה הוא כאן על ת\"ת, ולא על המלכות. ור' אלעזר מביא בדבריו אלו, ראיה לדברי ר' חייא."],[5,"אמר ר' יצחק וכו':","אר\"י, והרי כתוב ויגד לכם את בריתו. וא\"כ כמו שכתוב הגדה אצל ברית יכול לומר ג\"כ אצל צדק. אמר לו כן הוא ודאי, שהגדה הוא גם בחינת ברית, דהיינו יסוד, כי ת\"ת וברית חד הוא. אבל יסוד הוא מדרגה השולטת על התחתונה, שהוא דובר צדק. וע\"כ יתכן לומר גם בה לשון הגדה. והכל הוא להסתכל כאן. בוא וראה, אע\"פ, שאמרנו \u0003שדבור\u0004 הוא תחתון מכולן, אל תאמר בשביל זה, שהוא אינו מדרגה עליונה וחשובה אלא ודאי \u0003דבור,\u0004 יורה שהוא מלא מכל המדרגות, ומדרגה עליונה היא. והסימן שלך שכתוב כי לא \u0003דבר\u0004 רק הוא מכם. פירוש. כי הגם שדבור היא מדרגה החיצונה מכולם, דהיינו מלכות, אמנם אין המלכות נקראת בשם דבור, אלא בשעה שהיא נבנית ונעשית פרצוף פנימי עליון בשוה עם ז\"א פנים בפנים, שאז נקרא ז\"א \u0003קול\u0004 והנוקבא \u0003דבור.\u0004 הרי שמצד אחד, \u0003דבור\u0004 פירושו מלכות, שהיא חיצונה ותחתונה מכולן. ומצד הב' יורה על בנינה השלם פב\"פ עם ז\"א, שאז היא מדרגה עליונה."],[6,"רבי אליעזר וכו':","ר\"א היה הולך אל חמיו, והיה עמו ר' חייא ור' יוסי ור' חזקיה. אמר ר' אלעזר, אני רואה, שהתעוררות העליון אינה, אלא על ידי התעוררות התחתון, כי התעוררות העליון בתשוקתו של התחתון תלוי."],[7,"פתח ואמר אלקים אל דמי לך וגו':","זה הוא התעוררות מלמטה, מצד הנוקבא, כדי לשלוט. אמר דוד, אלקים אל דמי לך, מלהתעורר אל העליון, לז\"א ולהתחבר בימין. בחסד שלו."],[8,"מאי טעמא וכו':","מה הטעם. משום כי הנה אויביך יהמיון וגו' כי נועצו לב יחדיו עליך ברית יכרותו. כי הנוקבא היא בחי' שמאל, שה\"ס חכמה בלי חסדים, ואין החכמה יכולה להאיר בלי חסדים. וע\"כ, כל הקליפות ואויבי הקדושה מרימים ראש. ומשום זה אלקים אל דמי לך מלהתעורר למעלה, לז\"א, כי אז מתעורר הימין דז\"א וקושר אותה עמו. וכשמתקשרת בימין, דהייני שהחכמה שבה מתלבשת בחסדים שבימין, אז נשברו השונאים כי הארת החכמה משמדת כל אויבי הקדושה. שכתוב ימינך ה' נאדרי בכח ימינך ה' תרעץ אויב."],[9,"ות\"ח.","בשעה שנתחברו כל אלו המלכים לעשות מלחמה עם אברהם, נתיעצו להעבירו מן העולם. וכיון ששלטו בלוט בן אחי אברהם. מיד הלכו. שכתוב ויקחו את לוט ואת רכושו בן אחי אברם וילכו. מה הטעם, משום שצורתו של לוט היתה דומה לאברהם, ומשום זה, \u0003וילכו.\u0004 כי כל מלחמה הזו בשבילו היתה. וחשבו שכבר נפל בידיהם."],[10,"מאי טעמא וכו':","ושואל, מה הטעם שרצו להרוג את אברהם. ואומר, שהוא משום שאברהם הוציא את בני העולם מלעבוד עבודה זרה, והביאם לעבודת הקב\"ה, וע\"כ רצו להורגו. ועוד. כי הקב\"ה עורר אותם בעולם, להלחם באברהם, כדי לגדל שמו של אברהם בעולם, ולקרבהו לעבודתו."],[11,"ורזא דמלה וכו':","וסוד הדבר. כיון שנתעורר אברהם לרדוף אחריהם, אז נאמר אלקים אל דמי לך וגו', שהנוקבא נתעוררה לז\"א, והעלתה מ\"ן אליו להמשיך חסד שה\"ס ימין. עד שהכל נקשר באברהם, שה\"ס חסד דז\"א, דהיינו שהחכמה שבה נתלבשה בחסדים ונשלמה הארתה וכשנקשר הכל באברהם אז נשברו לפניו כל המלכים. כמו שאמרנו לעיל (באות הסמוך) שכתוב אז, ימינך ה' תרעץ אויב."],[12,"ומלכי צדק מלך שלם וגו':","ר' שמעון פתח ואמר, ויהי בשלם סכו וגו', בוא וראה. כשעלה ברצונו של הקב\"ה, שה\"ס בינה, לברוא העולם, שהוא ז\"א הנקרא עולם, הוציא להבה אחת של בוצינא דקרדנותא, ונשב רוח ברוח, ונחשכה הלהבה, וגם שורפת. והוציא מתוך צדדי התהום טפה אחת, וחבר אותם כאחד, דהיינו הטפה עם הלהבה, וברא בהם את העולם, שהוא ז\"א. פירוש. כדי לבאר הכתוב ומלכי צדק וגו', וסוד הברכה אשר ברכו, הוצרך לבאר היטב בדיוק סדר עלית זו\"ן אל הבינה בסוד מ\"ן, כדי להשלים הארתה. שבזה מתבאר ברכה הראשונה, ברוך אברם לאל עליון קונה שמים וארץ. ואח\"כ הוצרך לבאר סדר קבלת ז\"א ונוקביה את המוחין מבינה אחר עליתם שם. שבזה מתבאר ברכה הב', וברוך אל עליון אשר מגן צריך בידיך וגו'."],[12,"","ונודע, שבעת שהבינה משפעת בחינת ו\"ק לזו\"ן, היא צריכה אז להתמעט בעצמה לבחינת ו\"ק. שאז מורידה ג' אתוון אל\"ה דאלקים, אל זו\"ן, והיא עצמה נשארה בב' אותיות מ\"י דאלקים, שהם בחינת ו\"ק בלי ראש, ואז משפעת ו\"ק לזו\"ן. (כנ\"ל דף ז' ד\"ה פירוש ע\"ש) וכשרוצה להשפיע ג\"ר לזו\"ן. היא מעלית ג' אתוון אל\"ה מזו\"ן ומחזרת אותם למדרגתה, והזו\"ן עולים עמהם, ואז יוצא קו שמאל בהבינה. ונעשו ה' אתוון אלקים סתימא בשמא, מטעם חסרון חסדים. ונעשו מחלוקת בין ב' הקוין ימין ושמאל דבינה, ואז נעשה ז\"א בחינת מ\"ן אליה עם סוד המסך דחירק, שמצד אחד ממעט כחו של קו שמאל, ומצד הב' הוא מרבה חסדים ואז מכריע ביניהם ומיחד אותם זה בזה. (כנ\"ל דף י\"ג ד\"ה ונתבאר ע\"ש) ואחר שז\"א השלים ג' הקוין בבינה, זוכה גם הוא באותם ג' הקוין. כי כל השיעור שתחתון גורם בעליון זוכה בו התחתון. וכבר נתבאר זה בכ\"מ. וכאן בא הזהר לבאר רק השפעת מוחין דג\"ר אל הזו\"ן. שהוא מבחינת ג\"ר של עצמה. דהיינו שכבר החזירה לעצמה ג' אתוון \u0003אל\"ה,\u0004 והאירה בה הארת השורק, דהיינו קו השמאל שבה, שהאורות נסתמים בה אז, וצריכה לעלית ז\"א עם המסך שלו, שתזדווג עליו ותוציא על ידו קו האמצעי המכריע ומשלים ב' הקוין שלה."],[12,"","וזה אמרו, \u0003כד סליק ברעותא דקב\"ה,\u0004 שהוא בינה, \u0003למברי עלמא,\u0004 דהיינו להשפיע מוחין דג\"ר אל העולם, שהוא זו\"ן. \u0003אפיק חד שלהובא דבוצינא דקרדינותא,\u0004 דהיינו שגילתה את כח הדין של קו השמאל, שהוא כאש שורף מחוסר חסדים. ואז \u0003ונשף זיקא בזיקא,\u0004 שרוח התחתון שהוא ז\"א, נשב ברוח העליון שהוא ז\"ת דבינה. כלומר, שז\"א עלה אז למ\"ן עם המסך שלו אל ז\"ת דבינה, ונעשה לה בחינת רוח. שזה נבחן כנשיבת הרוח ברוח. ואז \u0003חשכאת ואוקידת,\u0004 כלומר שנכפלו הדינים בז\"ת דבינה, כי מטרם שנעשה זווג על המסך דז\"א, לא לבד שלא נתקן האש דקו שמאל אלא עוד שקו השמאל נתמעט ונחשך לבחינת ו\"ק, (כנ\"ל דף ט\"ז ד\"ה עוד) שה\"ס חרן, ע\"ש. ונמצא \u0003דחשכאת\u0004 מטעם המסך דז\"א שעלה, וגם \u0003אוקידת,\u0004 כי עוד לא יצא הזווג על המסך שימשיך קומת החסדים."],[12,"","ואחר זה נעשה הזווג מאור העליון על המסך דז\"א ויצאה עליו קומת חסדים. וז\"ש \u0003ואפיק מגו סטרי תהומא חד טיף,\u0004 המסך דצמצום ב' מכונה תהום (כנ\"ל בראשית א' דף ל\"ח ד\"ה אבנין ע\"ש) וקומת החסדים שה\"ס קו אמצעי מכונה \u0003חד טיף,\u0004 טפה אחת, כי ג' הקוין מכונים ג' טפות, (כנ\"ל בראשית א' דף רס\"ד אות שכ\"א) ואומר שהוציא בסוד הזווג על המסך, המכונה סטרי תהומא, טפה אחת דהיינו קומת החסדים, \u0003וחבר לון כחד,\u0004 שקומת החסדים חיבר ב' הקוין, ימין ושמאל דבינה להיות כמו קו אחד. דהיינו שעשה שלום ביניהם, ונתלבשו זב\"ז החכמה שבשמאל בהחסדים שבימין וכן החסדים שבימין בהחכמה שבשמאל. \u0003וברא בהו עלמא,\u0004 ובאלו המוחין ברא את העולם, שהוא ז\"א. כי מתוך שז\"א גרם הארת המוחין הללו בבינה, זכה בהם גם הוא. כנ\"ל."]],[[0,"","רַבִּי יִצְחָק פָּתַח, (שם מה) דֹּבֵר צֶדֶק מַגִּיד מֵישָׁרִים. כָּל דִּבְרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא הֵם אֱמֶת וְעוֹשֶׂה מֵישָׁרִים. בַּמָּה הוּא עוֹשֶׂה מֵישָׁרִים? מִשּׁוּם שֶׁכַּאֲשֶׁר בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, לֹא הָיָה עוֹמֵד, וְהָיָה מִתְמוֹטֵט לְכָאן וּלְכָאן. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לָעוֹלָם: מַה לְּךְ שֶׁאַתָּה מִתְמוֹטֵט? אָמַר לוֹ: רִבּוֹנוֹ שֶׁל עוֹלָם, אֵינִי יָכוֹל לַעֲמֹד, שֶׁאֵין בִּי יְסוֹד עַל מַה שֶּׁאֶתְקַיֵּם."],[1,"","אָמַר לוֹ: הֲרֵי אֲנִי עָתִיד לְהַעֲמִיד בְּךְ צַדִּיק אֶחָד שֶׁהוּא אַבְרָהָם שֶׁיֹּאהַב אוֹתִי. מִיָּד עָמַד הָעוֹלָם בְּקִיּוּמוֹ. זֶהוּ שֶׁכָּתוּב (בראשית ב) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם. אַל תִּקְרֵי בְּהִבָּרְאָם אֶלָּא בְּאַבְרָהָם. בְּאַבְרָהָם מִתְקַיֵּם הָעוֹלָם."],[2,"","אָמַר רַבִּי חִיָּיא, (ישעיה מה) מַגִּיד מֵישָׁרִים, שֶׁהִנֵּה הֵשִׁיב הָעוֹלָם לַקָּדוֹשׁ-בָּרוּךְ-הוּא: אוֹתוֹ אַבְרָהָם עָתִיד הוּא שֶׁיֵּצְאוּ מִמֶּנִּי בָּנִים שֶׁיַּחֲרִיבוּ אֶת הַמִּקְדָּשׁ וְיִשְׂרְפוּ אֶת הַתּוֹרָה. (נ\"א: לצאת ממנו ישמעאל, אמר לו', הנה יצחק, אמר לו, ' עתיד לצאת ממנו עשו הרשע שיחריב את בית המקדש וישרף התורה,) אָמַר לוֹ: עָתִיד אָדָם אֶחָד לָצֵאת מִמֶּנּוּ שֶׁהוּא יַעֲקֹב, וְיֵצְאוּ מִמֶּנּוּ שְׁנֵים עָשָׂר שְׁבָטִים כֻּלָּם צַדִּיקִים. מִיָּד הִתְקַיֵּם הָעוֹלָם בִּשְׁבִילוֹ. זֶהוּ שֶׁכָּתוּב מַגִּיד מֵישָׁרִים."],[3,"","רַבִּי אֶלְעָזָר אוֹמֵר, הֲרֵי הֵעַרְנוּ, וַיְדַבֵּר, וַיַּגֵּד, וַיֹּאמֶר - כֻּלָּם לְטַעֲמָם מִתְפָּרְשִׁים. וַיְדַבֵּר הוּא בְּגָלוּי, דַּרְגָּה חִיצוֹנָה, שֶׁאֵינָהּ דַּרְגָּה פְּנִימִית כְּמוֹ אוֹתָן הַדְּרָגוֹת הָעֶלְיוֹנוֹת. וְזֶהוּ דֹּבֵר צֶדֶק."],[4,"","וַיַּגֵּד, הוּא רֶמֶז לְדַרְגָּה פְּנִימִית עֶלְיוֹנָה שֶׁשּׁוֹלֶטֶת עַל הַדִּבּוּר, וְזֶהוּ מַגִּיד מֵישָׁרִים. מִי הַמֵּישָׁרִים? זוֹ הַדַּרְגָּה הָעֶלְיוֹנָה שֶׁיַּעֲקֹב שָׁרוּי בָּהּ. זֶהוּ שֶׁכָּתוּב (תהלים צט) אַתָּה כּוֹנַנְתָּ מֵישָׁרִים. וּמִשּׁוּם כָּךְ כָּתוּב מַגִּיד וְלֹא כָתוּב דּוֹבֵר."],[5,"","אָמַר רַבִּי יִצְחָק, וַהֲרֵי כָּתוּב (דברים ד) וַיַּגֵּד לָכֶם אֶת בְּרִיתוֹ? אָמַר לוֹ, כָּךְ הוּא וַדַּאי, הִיא הַדַּרְגָּה שֶׁשּׁוֹלֶטֶת עַל הַתַּחְתּוֹנָה שֶׁהִיא דּבֵר צֶדֶק, וְהַכֹּל (בה) הוּא (נ\"א: לשתל הפרי) לְהִתְבּוֹנֵן (יש) כָּאן. בּא רְאֵה, שֶׁאַף עַל גַּב שֶׁהַדִּבּוּר הוּא תַּחְתּוֹן, אַל תֹּאמַר שֶׁאֵינוֹ עֶלְיוֹן, אֶלָּא וַדַּאי הַדִּבּוּר הוּא מָלֵא מִן הַכֹּל וְהוּא דַּרְגָּה עֶלְיוֹנָה, וְסִימָן לַדָּבָר - (שם לב) כִּי לֹא דָבָר רֵק הוּא מִכֶּם."],[6,"","רַבִּי אֶלְעָזָר הָיָה הוֹלֵךְ לְבֵית חָמִיו, וְהָיוּ עִמּוֹ רַבִּי חִיָּיא וְרַבִּי יוֹסֵי וְרַבִּי חִזְקִיָּה. אָמַר רַבִּי אֶלְעָזָר, הִנֵּה רָאִיתִי שֶׁהִתְעוֹרְרוּת שֶׁל מַעְלָה אֵינָהּ אֶלָּא כְּשֶׁמִּתְעוֹרֵר לְמַטָּה, שֶׁהֲרֵי הַהִתְעוֹרְרוּת שֶׁל מַעְלָה תְּלוּיָה בַּתְּשׁוּקָה שֶׁל מַטָּה (הדבר)."],[7,"","פָּתַח וְאָמַר, (תהלים פג) אֱלֹהִים אַל דֳּמִי לָךְ אַל תֶּחֱרַשׁ וְאַל תִּשְׁקֹט אֵל. זוֹ הִיא הַהִתְעוֹרְרוּת שֶׁל מַטָּה כְּדֵי לִשְׁלֹט. אָמַר דָּוִד, אֱלֹהִים אַל דֳּמִי לָךְ, לְהָעִיר אֶל הָעֶלְיוֹן וּלְהִתְחַבֵּר אֶל הַיָּמִין."],[8,"","מָה הַטַּעַם? מִשּׁוּם (שם) כִּי הִנֵּה אוֹיְבֶיךְ יֶהֱמָיוּן וְגוֹ'. (וכתוב) כִּי נוֹעֲצוּ לֵב יַחְדָּו עָלֶיךְ בְּרִית יִכְרֹתוּ. וּמִשּׁוּם כָּךְ, אֱלֹהִים אַל דֳּמִי לָךְ לְהָעִיר כְּלַפֵּי מַעְלָה, שֶׁהֲרֵי אָז מִתְעוֹרֵר הַיָּמִין וְקוֹשֵׁר אוֹתָהּ עִמָּהּ. וְכַאֲשֶׁר נִקְשֶׁרֶת בַּיָּמִין, אָז נִשְׁבָּרִים הַשּׂוֹנְאִים, שֶׁכָּתוּב (שמות טו) יְמִינְךְ ה' נֶאְדָּרִי בַּכֹּחַ יְמִינְךְ ה' תִּרְעַץ אוֹיֵב."],[9,"","וּבֹא וּרְאֵה, בְּשָׁעָה שֶׁהִתְחַבְּרוּ כָּל אוֹתָם הַמְּלָכִים לְהִלָּחֵם בַּקְּרָב עַל אַבְרָהָם, הִתְיָעֲצוּ לְהַעֲבִירוֹ מִן הָעוֹלָם, וְכֵיוָן שֶׁשָּׁלְטוּ בְּלוֹט בֶּן אָחִיו שֶׁל אַבְרָהָם, מִיָּד הָלְכוּ, שֶׁכָּתוּב וַיִּקְחוּ אֶת לוֹט וְאֶת רְכֻשׁוֹ בֶּן אֲחִי אַבְרָם וַיֵּלֵכוּ. מָה הַטַּעַם? מִשּׁוּם שֶׁדְּמוּתוֹ שֶׁל לוֹט הָיְתָה דוֹמָה לְאַבְרָהָם, וּמִשּׁוּם כָּךְ וַיֵּלֵכוּ, שֶׁכָּל אוֹתוֹ הַקְּרָב הָיָה בִּשְׁבִילוֹ."],[10,"","מָה הַטַּעַם? מִשּׁוּם שֶׁאַבְרָהָם הָיָה מוֹצִיא אֶת בְּנֵי הָעוֹלָם מֵעֲבוֹדָה זָרָה וּמַכְנִיס אוֹתָם לַעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא. וְעוֹד, הַקָּדוֹשׁ בָּרוּךְ הוּא הֵעִיר אוֹתָם בָּעוֹלָם כְּדֵי לְגַדֵּל אֶת שְׁמוֹ שֶׁל אַבְרָהָם בָּעוֹלָם וּלְקָרֵב אוֹתוֹ לַעֲבוֹדָתוֹ."],[11,"","וְסוֹד הַדָּבָר - כֵּיוָן שֶׁאַבְרָהָם הִתְעוֹרֵר לִרְדֹּף אַחֲרֵיהֶם, אָז אֱלֹהִים אַל דֳּמִי לָךְ, עַד שֶׁהַכֹּל נִקְשַׁר לְאַבְרָהָם. וּכְשֶׁהַכֹּל נִקְשַׁר לְאַבְרָהָם, אָז נִשְׁבְּרוּ כָּל הַמְּלָכִים מִלְּפָנָיו, כְּמוֹ שֶׁאָמַרְנוּ, שֶׁכָּתוּב יְמִינְךְ ה' תִּרְעַץ אוֹיֵב וְגוֹ'."],[12,"","וּמַלְכִּי צֶדֶק מֶלֶךְ שָׁלֵם הוֹצִיא לֶחֶם וָיָיִן. רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (תהלים עו) וַיְהִי בְשָׁלֵם סוּכּוֹ וְגוֹ'. בֹּא רְאֵה, כְּשֶׁעָלָה בִּרְצוֹן הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְרֹא אֶת הָעוֹלָם, הוֹצִיא שַׁלְהֶבֶת אַחַת שֶׁל הַמָּאוֹר שֶׁל הַנִּיצוֹץ הַקָּשֶׁה, וְנָשַׁף רוּחַ בְּרוּחַ חֲשׁוּכָה וְשׂוֹרֶפֶת. וְהוֹצִיא מִתּוֹךְ צִדְדֵי הַתְּהוֹם טִפָּה אַחַת, וְחִבֵּר אוֹתָם יַחַד, וּבָרָא בָהֶם אֶת הָעוֹלָם."]]],[["הַהוּא שַׁלְהוֹבָא סָלִיק וְאִתְעַטְּרָא בִּשְּׂמָאלָא, וְהַהוּא טִיף סָלִיק וְאִתְעַטַּר בְּיָמִינָא, סָלְקוּ חַד בְּחַד אִחְלָפוּ דּוּכְתֵּי דָּא לְסִטְרָא דָא וְדָא לְסִטְרָא דָא, דְּנָחִית סָלִיק וּדְסָלִיק נָחִית.","אִתְקַטְּרוּ דָּא בְּדָא, נָפִיק מִבֵּינַיְיהוּ רוּחַ שְׁלִים. כְּדֵין אִנּוּן תְּרֵין סִטְרִין אִתְעֲבִידוּ חַד וְאִתְיְיהִיב בֵּינַיְיהוּ וְאִתְעַטְּרוּ חַד בְּחַד. כְּדֵין אִשְׁתְּכַח שְׁלָם לְעֵילָא וּשְׁלָם לְתַתָּא, וְדַרְגָּא אִתְקַיָּים.","אִתְעַטְּרַת ה\"א בְּוא\"ו וָא\"ו בְּה\"א, כְּדֵין סַלְקָא ה\"א וְאִתְקַשְּׁרָא בְּקִשּׁוּרָא שְׁלִים. כְּדֵין וּמַלְכִּי צֶדֶק מֶלֶךְ שָׁלֵם. מֶלֶךְ שָׁלֵם וַדַּאי מֶלֶךְ אִיהוּ דְּשַׁלִּיט בִּשְׁלִימוּ, אֵימָתַי אִיהוּ מֶלֶךְ שָׁלֵם בְּיוֹמָא דְכִפּוּרֵי דְּכָל אַנְפִּין נְהִירִין. (דבר אחר מלכי צדק מלך שלם, אמר רבי שמעון בעא קודשא בריך הוא למיפק כהונתא משם כמא דאת אמר ברוך אברם לאל עליון, כיון דאקדים ברכתא דאברהם לברכתא דמריה, אמרז ליה אברהם וכי מקדימין ברכתא דעבדא לברכתא דמריה, מיד אתיהיבת כהונתא לאברהם דכתיב, (תהילים ק״י:א׳) נאם יי לאדני שב לימיני. וכתיב בתריה נשבע יי ולא ינחם אתה כהן לעולם על דברתי מלכי צדק, דכתיב והוא כהן לאל עליון, ואין זרעו כהן)","דָּבָר אַחֵר וּמַלְכִּי צֶדֶק. דָּא עָלְמָא בַּתְרָאָה. מֶלֶךְ שָׁלֵם, דָּא עָלְמָא עִלָּאָה. דְּאִתְעַטַּר חַד בְּחַד בְּלָא פִּירוּדָא תְּרֵין עָלְמִין כְּחֲדָא, וְאֲפִילּוּ עָלְמָא תַּתָּאָה כֹּלָּא הוּא. וְחַד מִלָּה אִיהוּ. הוֹצִיא לֶחֶם וָיָיִן דִּתְרֵי אִלֵּין בֵּיהּ. וְהוּא כֹהֵן לְאֵל עֶלְיוֹן מְשַׁמֵּשׁ עָלְמָא לָקֳבֵל עָלְמָא. וְהוּא כֹהֵן דָּא יָמִינָא. לְאֵל עֶלְיוֹן עָלְמָא עִלָּאָה. וּבְגִין כָּךְ בָּעֵי כַּהֲנָא לְבָרְכָא עָלְמָא.","תָּא חֲזֵי, בִּרְכָאן (ד\"א ל\"ג כד) נָטִיל הַאי עָלְמָא תַּתָּאָה כַּד אִתְחַבַּר בְּכַהֲנָא רַבָּא כְּדֵין וַיְבָרַכֵהוּ וַיֹּאמַר בָּרוּךְ אַבְרָם (וגו) לְאֵל עֶלְיוֹן הָכִי הוּא וַדַּאי. כְּגַוְונָא דָא בָּעֵי כַּהֲנָא לְתַתָּא לְקָשְׁרָא קִשְׁרִין וּלְבָרְכָא הַאי דוּכְתָּא בְּגִין דְּיִתְקַשַּׁר בְּיָמִינָא לְאִתְקַשְּׁרָא תְּרֵין עָלְמִין כְּחַד. בָּרוּךְ אַבְרָם רָזָא דְמִלָּה תִּקּוּנָא דְּבִרְכָאן אִיהוּ.","בָּרוּךָ אַבְרָם כְּמָה דְּאַמְרִינָן בָּרוּךְ אַתָּה. לְאֵל עֶלְיוֹן. יְיָ אֱלהֵינוּ. קוֹנֵה שָׁמַיִם וָאָרֶץ. מֶלֶךְ הָעוֹלָם. וְהַאי קְרָא רָזָא דְּבִרְכָאן אִיהוּ. (ובגין כך) וַיְבָרַכֵהוּ מִתַּתָּא לְעֵילָא. וּבָרוּךְ אֵל עֶלְיוֹן (אשר מגן צריך בידך). מֵעֵילָא לְתַתָּא. וַיִּתֶּן לוֹ מַעֲשֵׂר מִכֹּל לְאִתְדַּבְּקָא בְּאֲתַר דְּקִשּׁוּרָא אִתְקַּשַּׁר לְתַתָּא.","עַד דְּהֲווּ אָזְלֵי, אִעֲרַע בְּהוּ רַבִּי יֵיסָא וְחַד יוּדָאי בַּהֲדֵיהּ. וְהֲוָה אָמַר הַהוּא יוּדָאי (תהילים כ״ה:א׳) לְדָוִד אֵלֶיךָ יְיָ נַפְשִׁי אֶשָּׂא. לְדָוִד. וְכִי אַמַּאי לָא כְּתִיב מִזְמוֹר לְדָוִד אוֹ לְדָוִד מִזְמוֹר.","אֶלָא בְּגִין דַרְגֵּיהּ קָאֲמַר לְדָוִד תּוּשְׁבַּחְתָּא דְּאָמַר בְּגִינֵיהּ אֵלֶיךָ יְיָ נַפְשִׁי אֶשָּׂא. אֵלֶיךָ יְיָ לְעֵילָא. נַפְשִׁי, מַאן נַפְשִׁי, (אשא) דָּא דָּוִד (הוא) דַּרְגָּא קַדְמָאָה דְּקָאֲמָרָן. אֶשָּׂא, אֲסַלֵּק. כְּמָא דְאַתְּ אָמֵר, (תהילים קכ״א:א׳) אֶשָּׂא עֵינַי אֶל הֶהָרִים. בְּגִין דְּכָל יוֹמוֹי דְדָוִד הֲוָה מִשְׁתַּדֵּל לְסַלְקָא דַרְגֵּיהּ לְאִתְעַטְּרָא לְעֵילָא וּלְאִתְקַשְּׁרָא תַּמָּן בְּקִשּׁוּרָא שְׁלִים כְּדְקָא יְאוּת.","כְּגַוְונָא דָא (תהילים ק״ג:א׳) לְדָוִד בָּרְכִי נַפְשִׁי אֶת יְיָ בְּגִין דַּרְגֵּיהּ קָּאֲמַר, וּמַאי אָמַר בָּרְכִי נַפְשִׁי אֶת יְיָ. אֶת לְאִתְקַשְּׁרָא בְּקִשּׁוּרָא לְעֵילָא. וְכָל קְרָבַי, מַאן קְרָבַי. אִלֵּין שְׁאָר חֵיוָן בְּרָא. דְּאִקְרוּן קְרָבַיִם כְּמָא דְאַתְּ אָמֵר, (שיר השירים ה׳:ד׳) וּמֵעַי הָמוּ עָלָיו. דָּבָר אַחֵר בָּרְכִי נַפְשִׁי, בְּגִינֵיהּ קָאֲמַר. אֶת יְיָ דָּא שְׁלִימוּ דְכֹלָּא, אֶת יְיָ כְּלָלָא דְּכֹלָּא.","אָמַר לֵיהּ רַבִּי אֶלְעָזָר לְרַבִּי יֵיסָא חָמִינָא לָךְ דְּהָא עִם שְׁכִינְתָּא קָאֲתִית וְאִתְחַבָּרַת. אָמַר לֵיהּ הָכִי הוּא וַדַּאי, וּתְלַת פַּרְסֵי הוּא דְּאָזִילְנָא בַּהֲדֵיהּ וְאָמַר לִי כַּמָּה מִלֵי מַעַלְיָיתָא וְאֲנָא אֲגִירְנָא לֵיהּ לְיוֹמָא דָא וְלָא יְדַעְנָא דְּאִיהוּ בּוֹצִינָא דְּנָהִיר כִּדְחָמִינָא הַשְׁתָּא.","אָמַר לֵיהּ רַבִּי אֶלְעָזָר לְהַהוּא יוּדָאי מַה שְּׁמָךְ, אָמַר לֵיהּ יוֹעֶזְרִ. אָמַר לֵיהּ יוֹעֶזֶר וְאֶלְעָזָר (מלה חדא) יְתִיבָן כְּחֲדָא, יָתְבוּ גַּבֵּי חַד טִנָּרָא בְּהַהוּא חֲקַל. פָּתַח הַהוּא יוּדַאי וְאָמַר (ישעיהו מ״ג:כ״ה) אָנֹכִי אָנֹכִי הוּא מוֹחֶה פְשָׁעֶיךָ לְמַעֲנִי וְחַטֹּאתֶיךָ לֹא אֶזְכּוֹר. מַאי טַעְמָא תְּרֵי זִמְנֵי אָנֹכִי אָנֹכִי."],[[0,"ההוא שלהובא וכו':","אחר שביאר בדרך כלל, ענין יציאת המוחין בבינה, והמשכתם לז\"א, בא עתה לבאר זה בפרטיות. ואומר, שלהבת ההיא עלתה ונתעטרה בקו שמאל דבינה, וטפה ההיא שהיא קו אמצעי, עלתה ונתעטרה בקו ימין דבינה. ואז \u0003סלקו חד בחד,\u0004 נכללו ב' הקוין זה בזה. \u0003אחלפו דוכתי דא לסטרא דא ודא לסטרא דא,\u0004 החליפו מקומותיהם הימין והשמאל, החסדים שבצד ימין נמשכו ובאו לצד שמאל, והארת החכמה שהיה שם בשמאל, כשלהבת שורפת, נתלבשת בהחסדים וחזרה לבחינת הארת חכמה המתוקה והארת החכמה שבשמאל נמשכה ובאה לצד ימין. והחסדים שהיו שם בימין בבחינת ו\"ק קבלו עתה מהארת השמאל בחינת ג\"ר. \u0003דנחית סליק ודסליק נחית,\u0004 כלומר, דנחית מי שירד מקודם לכן, דהיינו הארת השמאל שהאירה מקודם לכן ממעלה למטה, נמצא עתה \u0003סליק.\u0004 שעולה הארתו להאיר רק ממטה למעלה. \u0003ודסליק,\u0004 מי שעלה הארתו מקודם לכן, דהיינו הארת הימין, שהאירה מקודם לכן רק ממטה למעלה, נמצא עתה, אחר שנכללה בהארת השמאל, שהיא \u0003נחית,\u0004 שמאירה ממעלה למטה. וטעם השינוי, הזה נתבאר לעיל (בראשית א' דף ש\"ג ד\"ה ונודע) ע\"ש ואין להכפיל דברים."],[1,"אתקטרו דא בדא וכו':","נתקשרו ב' הקוין, ימין ושמאל דבינה, זה בזה, ויצא מהם רוח שלם. דהיינו שז\"א הנקרא \u0003רוח\u0004 נאצל מזווגם. כמ\"ש (לעיל בראשית א' דף רפ\"ז אות שס\"ג) \u0003תלת נפקי מחד, חד בתלת קיימא\u0004 כיון שז\"א גרם בעלייתו לבינה, שיצא ג' קוין בבינה, לכן זכה גם ז\"א באותם ג' קוין, וז\"ש כאן, \u0003נפיק מבינייהו רוח שלים,\u0004 דהיינו שז\"א נאצל מהם בג' קוין. ומבאר, \u0003אינון תרין סטרין,\u0004 ימין ושמאל דבינה, \u0003אתעבידו חד,\u0004 נכללו זה בזה ונעשו בז\"א לאחד. \u0003ואתיהיב בינייהו,\u0004 והרוח עצמו, ניתן ביניהם בבחינת קו אמצעי, וע\"כ יצא בו ג' קוין. \u0003ואתעטרו חד בחד,\u0004 וכל ג' הקוין דז\"א נתעטרו זה בזה, דהיינו כמו שנתבאר לעיל בג' הקוין דבינה אשר השמאל נתעטר בחסדים דימין ונשלם החכמה שבו, והימין נתעטר בחכמה שבשמאל ונשלם בג\"ר גם הוא. וקו האמצעי נתעטר בהחסדים דימין, והשיג גם הוא ג\"ר מהימין. \u0003כדין אשתכח שלם לעילא ושלם לתתא,\u0004 אז נמצא שלימות למעלה בבינה ושלימות למטה בז\"א, \u0003ודרגא\u0004 אתקיים. והמדרגה של המוחין דז\"א נשלמה."],[2,"אתעטרת ה\"א בוא\"ו וכו':","ונמצא שנתעטרה \u0003ה\u0004 ראשונה דהויה, שהיא \u0003בינה,\u0004 עם ה \u0003ו'\u0004 דהויה שהוא ז\"א. כי ע\"י עלית ז\"א לבינה נתגלו המוחין שבה, בסוד \u0003תלת נפקי מחד. וא\"ו בה\"א,\u0004 ה \u0003ו'\u0004 דהויה, שהוא ז\"א נתעטר במוחין ע\"י ה \u0003ה'\u0004 דהויה. שהיא בינה, בסוד \u0003חד בתלת קיימא,\u0004 כנ\"ל, \u0003כדין סלקא ה\"א ואתקשרא בקשורא שלים.\u0004 אז עלתה \u0003ה'\u0004 אחרונה דהויה, שהיא הנוקבא דז\"א, אל ה \u0003ו'\u0004 דהויה. שהוא ז\"א, ונקשרה בו בקשר שלם, שקבלה ממנו המוחין דבינה. \u0003כדין ומלכי צדק מלך שלם מלך שלם ודאי,\u0004 ואז נאמר על ה' אחרונה הנקראת מלכי צדק, הכתוב ומלכי צדק מלך שלם. כי היא עתה מלך שלם בודאי. שפירושו, \u0003מלך איהו דשליט בשלימו,\u0004 היא עתה מלך השולט בשלמות, \u0003אימתי איהו מלך שלם,\u0004 ושואל, אימתי נבחנת הנוקבא דז\"א שהיא מלך שלם. ואומר \u0003ביומא דכפורי, דכל אנפין נהירין\u0004 ביום כפור, שאז עלתה המלכות ומלבשת את הבינה, וכל פנים מאירים, דהיינו שגם הפנים של הנוקבא מאירה כמו הפנים של הבינה."],[3,"ומלכי צדק דא עלמא בתראה:","ומרחיב לבאר את הכתוב, ואומר \u0003ומלכי צדק,\u0004 זהו עולם האחרון, דהיינו הנוקבא דז\"א. \u0003מלך שלם דא עלמא עלאה דאתעטר חד בחד בלא פרודא, תרין עלמין כחדא,\u0004 מלך שלם, פירושו עולם העליון, בינה. בעת שנתעטר אחד באחד, דהיינו עולם התחתון נתעטר בעולם העליון, בלי פירוד. ושני העולמות הם כמו אחד. \u0003ואפילו עלמא תתאה, בלא חד מלה איהו,\u0004 ואפילו עולם התחתון הוא כולו דבר אחד עם עולם העליון. והטעם הוא, כי בעת ההוא, עולה הנוקבא דז\"א ומלבשת הבינה, וכל תחתון העולה לעליון נעשה לגמרי כמוהו. וע\"כ נעשו אז ב' העולמות שהם הנוקבא עם הבינה, כמו דבר אחד. \u0003הוציא לחם ויין דחרין אלין ביה,\u0004 כי \u0003לחם\u0004 פירושו אור החסדים שבימין. יין פירושו הארת החכמה שבשמאל. וע\"כ אומר הכתוב \u0003הוציא לחם ויין,\u0004 להשמיענו ששני הארות הללו נמצאות עתה במלכי צדק. שה\"ס הנוקבא בעת שמלבשת לבינה, כנ\"ל. \u0003והוא כהן לאל עליון, משמש עלמא לקבל עלמא. והוא כהן, דא ימינא, לאל עליון עלמא עלאה.\u0004 והוא כהן לאל עליון, פירושו שעולם התחתון משמש בחסדים כנגד עולם העליון, כי \u0003והוא כהן\u0004 זהו ימין, כלומר אור החסדים שבנוקבא. \u0003לאל עליון,\u0004 הוא עולם העליון, דהיינו בינה. ושיעור הכתוב הוא, \u0003והוא כהן,\u0004 שהנוקבא משמשת באור החסדים הנק' כהן, \u0003לאל עליון,\u0004 בשביל הבינה. כי הכרעת קו אמצעי בבינה, שיצאה ע\"י הזווג על המסך דחירק, נמצאת הנוקבא דז\"א לנושאת את המסך הזה, וע\"כ הנוקבא משמשת לבחינת \u0003כהן\u0004 דהיינו להאיר את החסדים, \u0003לאל עליון,\u0004 אל הבינה. (כנ\"ל ב\"א דף כ\"ה ד\"ה יזהירו) וע\"כ מתברכת גם הנוקבא בחסדים."],[4,"ת\"ח ברכאן נטיל האי עלמא תתאה כד אתחבר בכהנא רבא:","עולם התחתון, שהיא הנוקבא, מקבלת ברכות. בעת שמתחבר בכהן גדול, דהיינו בקו ימין שבבינה הנק' כהן גדול, \u0003כדין ויברכהי,\u0004 אז, אחר שהנוקבא קבלה הברכות מכהן גדול, היא ברכה את אברהם, כמ\"ש, ויאמר ברוך אברם לאל עליון. כי כן הוא ודאי. כעין זה הכהן למטה בעולם הזה, צריך לקשור קשרים, דהיינו ליחד יחודים, כמ\"ש לפנינו, ולברך את המקום הזה, דהיינו הנוקבא דז\"א, כדי שתתקשר בהחסדים שבימין הבינה, שבזה נמצאים מתקשרים ב' העולמות, הנוקבא והבינה, ונעשים אחד."],[5,"ברוך אברם. רזא דמלה תקונא דברכאן איהו.","סוד הדבר, שברכה זו ברוך אברם וגו', מסודר בה תיקון הכונה שצריכים לכוון בכל הברכות שאנו מברכים. כי \u0003ברוך אברם, כמה דאמרינן ברוך אתה:\u0004 ברוך אברם, דומה למה שאנו אומרים בכל ברכה \u0003ברוך אתה. לאל עליון ה' אלקנו.\u0004 לאל עליון שבכאן, דומה למה שאנו אומרים בכל ברכה \u0003ה' אלקנו. קונה שמים וארץ,\u0004 דומה למה שאנו אומרים בכל ברכה \u0003מלך העולם. והאי קרא רזא דברכאן איהו,\u0004 פסוק הזה ה\"ס הברכה. \u0003ויברכהו, מתתא לעילא,\u0004 ויברכהו ויאמר ברוך אברם וגו', הוא סדר הכוונה ממטה למעלה. \u0003וברוך אל עליון, מעילא לתתא,\u0004 וברוך אל עליון אשר מגן צריך בידיך, הוא סדר הכוונה ממעלה למטה."],[5,"","ביאור הדברים. כי כונת הברכה בכל מקום, הוא, שמתחילה מורידים שפע מבינה לזו\"ן כדי שיוכלו לעלות אל הבינה ולהוציא בה את המוחין. וזה נבחן לבחינת ממטה למעלה, כלומר שמעלים זו\"ן ממקומם למעלה אל הבינה להשלים אותה. וסדר זה הוא בחצי ברכה הראשונה עד מלך העולם. ולבסוף ממשיכים השפע ממעלה למטה, דהיינו מהבינה אל זו\"ן ואל התחתונים. שזהו בסיום הברכה אחר מלך העולם. והביאור הוא, כיון שכל זכותם של הזו\"ן לקבל את המוחין מבינה, הוא משום שעלו והשלימו את המוחין דבינה עם קו אמצעי היוצא על המסך שלהם, בסוד \u0003תלת נפקי מחד,\u0004 אשר אז זוכים גם הזו\"ן אותו השיעור שהאיר מכחם בהבינה, בסוד \u0003חד בתלת קיימא,\u0004 כנ\"ל א\"כ אם אנו רוצים להמשיך איזה מדרגה מבינה אל זו\"ן, צריכים מקודם להעלות הזו\"ן אל הבינה, שיגרמו בה תוספת מוחין. שאח\"כ יקבלו גם הם אותה התוספת שגרמו בבינה, וסוד עליות זו\"ן אל הבינה הוא ע\"י אתון אל\"ה דאלקים, שבעת מיעוטה של הבינה יורדות לזו\"ן, ובעת גדלותה שמחזרת אליה אתוו\"ן אל\"ה עולים אליה עמהם גם הזו\"ן, (וכנ\"ל דף פ\"ג ד\"ה ונודע ע\"ש). ולפיכך מסודר נוסח חצי הברכה הראשונה, בבחינת ממטה למעלה, שפירושו להעלות זו\"ן למעלה להשלים הבינה. והמלה \u0003ברוך,\u0004 פירושה, להמשיך מבחינת קטנות הבינה שה\"ס בריכה עליונה, ג' אתוון אל\"ה, ולהורידם אל חג\"ת דז\"א, שהם ג' המלות אתה ה' אלקינו. \u0003אתה\u0004 זה חסד. \u0003ה'.\u0004 זה ת\"ת. \u0003אלקינו,\u0004 זה גבורה. יאחר שנמשכו אתוון אל\"ה בחג\"ת דז\"א, אנו מכוונים שהבינה מחזרת אתוו\"ן אל\"ה שלה למדרגתה, אשר אז עולים עמהן גם זו\"ן, ומשלימים בה המוחין בסוד קו האמצעי כנ\"ל, ואז נקראת הבינה, \u0003מלך העולם,\u0004 מאחר שנשלמו בה המוחין ואח\"ז בחצי ברכה השניה, אנו ממשיכים המוחין ממעלה למטה דהיינו מבינה אל זו\"ן ואל התחתונים, כי אותו השיעור שגרמו זו\"ן בבינה זוכים בה גם הם כנ\"ל."],[5,"","וז\"ש כאן, \u0003ברוך אברם. רזא דמלה, תקונא דברכאן איהו,\u0004 שסוד הדבר, שמסודר כאן תקון נוסח של כל הברכות. \u0003ברוך אברם כמה דאמרינן ברוך אתה\u0004 וכו' אשר ג' המלות, \u0003אברם לאל עליון,\u0004 רומזים על חג\"ת דז\"א שמקבלים אתוון \u0003אל\"ה\u0004 מבריכה עליונה. כמו ג' המלות אתה ה' אלקינו. \u0003קונה שמים וארץ,\u0004 הוא כמו \u0003מלך העולם.\u0004 דהיינו בשעה שהבינה החזירה אתוון \u0003אל\"ה\u0004 אליה. שעלו עמהם גם הזו\"ן, והשלימו בה את המוחין, שאז נקראת הבינה \u0003קונה שמים וארץ,\u0004 כמו בשאר, ברכות שנקראת אז, \u0003מלך העולם.\u0004 ועד כאן, \u0003ויברכהי מתתא לעילא,\u0004 דהיינו שמעלים זו\"ן ממקום עצמם למעלה להשלים את הבינה. \u0003וברוך אל עליון, וגו' מעילא לתתא,\u0004 דהיינו שממשיכים המוחין מלמעלה מהבינה למטה אל הזו\"ן. דהיינו כמו חצי ברכה השניה כשאר הברכות. ויתן לו מעשר מכל. \u0003לאתדבקא באתר דקשורא אתקשר לתתא.\u0004 ויתן לו מעשר מכל, פירושו, שנתן להנוקבא מעשר. כדי להתדבק בהמקום שהקשר נקשר למטה, דהיינו בסוד מלכות המסיימת את הארת הנוקבא, שלא ליתן אחיזה לחיצונים, שסוד המעשר מסיימת הארתה."],[6,"עד דהוו אזלי וכו':","בעוד שהיו מהלכים פגע אותם ר' ייסא ויהודי אחד עמו, ואמר אותו היהודי. שכתוב לדוד, אליך ה' נפשי אשא. ושאל, נאמר לדוד, למה לא נאמר, מזמור לדוד, או לדוד מזמור."],[7,"אלא בגין דרגיה וכו':","ומשיב אלא בשביל מדרגתו עצמו אמר \u0003לדוד,\u0004 והשבח שאמר בשביל עצמו הוא. אליך ה' נפשי אשא, פירושו, \u0003אליך ה'\u0004 למעלה, נפשי, מי היא נפשי, זהו דוד, שהוא מדרגה הראשונה שאמרנו, דהיינו מלכות, שהיא הראשונה ממטה למעלה. \u0003אשא\u0004 פירושו \u0003אעלה,\u0004 כמש\"א אשא עיני אל ההרים. כי בכל ימיו של דוד היה משתדל להעלות מדרגתו לבינה, להעטירה למעלה בבינה ולקשרה שם בקשר שלם כראוי."],[8,"כגוונא דא וכו':","כעין זה, לדוד ברכי נפשי את ה', אמר גם כן בשביל מדרגתו עצמו. ומה אמר. ברכי נפשי \u0003את\u0004 ה'. \u0003את\u0004 פירושו, להתקשר בקשר למעלה, בבינה. \u0003וכל קרבי,\u0004 מה היא קרבי, אלו הם שאר חיות השדה היינו ספירות הנוקבא, הנקראים קרבים. כמש\"א ומעי המו עליו. ד\"א. ברכי נפשי בשביל מדרגתו עצמו אמר. \u0003את ה'.\u0004 זהו שלימות הכל. הכלל של הכל. כלומר \u0003א\"ת\u0004 ה\"ס המלכות \u0003ה'\u0004 ז\"ס ז\"א, \u0003את ה'\u0004 היא רומז על יחוד השלם של ז\"א ונוקביה."],[9,"א\"ל ר' אלעזר וכו':","אמר לו ר\"א לר' ייסא, אני רואה אותך, שעם השכינה באת ונתחברת. כי ראה שהשכינה שרתה על אותו היהודי שבא עמו. אמר לו כן הוא ודאי. וג' פרסאות, הוא שהלכתי עמו, ואמר לי כמה דברים טובים. ואני שכרתי אותו שישמשני יום הזה, ולא ידעתי שהוא נר המאיר כמו שאני רואה עתה."],[10,"א\"ל ר\"א לההוא וכו':","א\"ל ר\"א לאותו היהודי, מה שמך. א\"ל יועזר. א\"ל יועזר ואלעזר יושבים יחד. כלומר שמבטאם קרובים. ישבו אצל אבן אחד באותה השדה. פתח אותו היהודי ואמר, אנכי אנכי הוא מוחה פשעיך וגו' ושאלו מה הטעם שאומר ב' פעמים אנכי אנכי."]],[[0,"","אוֹתָהּ הַשַּׁלְהֶבֶת עָלְתָה וְהִתְעַטְּרָה בִּשְׂמֹאל, וְאוֹתָהּ הַטִּפָּה עָלְתָה וְהִתְעַטְּרָה בְּיָמִין. עָלוּ אֶחָד עִם אֶחָד, הֶחֱלִיפוּ מְקוֹמוֹת, זֶה לְצַד זֶה וְזֶה לְצַד זֶה. זֶה שֶׁיָּרַד עָלָה, וְזֶה שֶׁעָלָה יָרַד. נִ"],[1,"","קְשְׁרוּ זֶה עִם זֶה וְיָצְאָה מִבֵּינֵיהֶם רוּחַ שְׁלֵמָה, וְאָז אוֹתָם שְׁנֵי הַצְּדָדִים נַעֲשׂוּ אֶחָד, וְנִתְּנָה בֵינֵיהֶם (הרוח) וְהִתְעַטְּרוּ הָאֶחָד עִם הָאֶחָד. וְאָז נִמְצָא שָׁלוֹם לְמַעְלָה וְשָׁלוֹם לְמַטָּה, וְהַדַּרְגָּה הִתְקַיְּמָה."],[2,"","הִתְעַטְרָה הֵ\"א עִם וָא\"ו, וָא\"ו עִם הֵ\"א, וְאָז עָלְתָה הֵ\"א וְנִקְשְׁרָה בְּקֶשֶׁר שָׁלֵם. וְאָז וּמַלְכִּי צֶדֶק מֶלֶךְ שָׁלֵם. מֶלֶךְ שָׁלֵם הוּא וַדַּאי מֶלֶךְ שֶׁשּׁוֹלֵט בִּשְׁלֵמוּת. מָתַי הוּא מֶלֶךְ שָׁלֵם? בְּיוֹם הַכִּפּוּרִים, כְּשֶׁכָּל הַפָּנִים מְאִירוֹת. (דבר אחר מלכי צדק מלך שלם, אמר רבי שמעון, רצה הקדוש ברוך הוא להוציא כהנה משם, כמו שנאמר ברוך אברם לאל עליון, כיון שהקדים ברכת אברהם לברכת רבונו, אמר לו אברהם', וכי מקדימים ברכת העבד לברכת רבו? מיד נתנה הכהנה לאברהם, שכתוב (תהלים קי) נאם ה' לאדני שב לימיני, וכתוב אחריו, נשבע ה' ולא ינחם אתה כהן לעולם על דברתי מלכי צדק, שכתוב והוא כהן לאל עליון, ואין זרעו כהן)."],[3,"","דָּבָר אַחֵר וּמַלְכִּי צֶדֶק - זֶה הָעוֹלָם הָאַחֲרוֹן. מֶלֶךְ שָׁלֵם - זֶה הָעוֹלָם הָעֶלְיוֹן. שֶׁהִתְעַטֵּר אֶחָד עִם אֶחָד בְּלִי פֵרוּד שְׁנֵי עוֹלָמוֹת יַחַד, וַאֲפִלּוּ הָעוֹלָם הַתַּחְתּוֹן הוּא הַכֹּל, וְהוּא דָבָר אֶחָד. הוֹצִיא לֶחֶם וָיָיִן - שֶׁבּוֹ שְׁנֵי אֵלּוּ. וְהוּא כֹהֵן לְאֵל עֶלְיוֹן - מְשַׁמֵּשׁ עוֹלָם נֶגֶד עוֹלָם. וְהוּא כֹהֵן - זֶה הַיָּמִין. לְאֵל עֶלְיוֹן - הָעוֹלָם הָעֶלְיוֹן, וּמִשּׁוּם כָּךְ צָרִיךְ הַכֹּהֵן לְבָרֵךְ אֶת הָעוֹלָם."],[4,"","בֹּא רְאֵה, הַבְּרָכוֹת נוֹטֵל הָעוֹלָם הַתַּחְתּוֹן הַזֶּה, כְּשֶׁמִּתְחַבֵּר עִם הַכֹּהֵן הַגָּדוֹל, וְאָז וַיְבָרֲכֵהוּ וַיֹּאמַר בָּרוּךְ אַבְרָם לְאֵל עֶלְיוֹן. כָּךְ זֶה וַדַּאי. כְּמוֹ כֵן צָרִיךְ הַכֹּהֵן לְמַטָּה לִקְשֹׁר קְשָׁרִים וּלְבָרֵךְ אֶת הַמָּקוֹם הַזֶּה, כְּדֵי שֶׁיִּתְקַשֵּׁר הַיָּמִין לִקְשֹׁר שְׁנֵי עוֹלָמוֹת יַחַד. בָּרוּךְ אַבְרָם - סוֹד הַדָּבָר הוּא תִקּוּן הַבְּרָכוֹת."],[5,"","בָּרוּךָ אַבְרָם - כְּמוֹ שֶׁאָמַרְנוּ, בָּרוּךְ אַתָּה. לְאֵל עֶלְיוֹן - ה' אֱלֹהֵינוּ. קֹנֵה שָׁמַיִם וָאָרֶץ - מֶלֶךְ הָעוֹלָם. וְהַפָּסוּק הַזֶּה הוּא סוֹד הַבְּרָכוֹת. (ומשום כך) וַיְבָרֲכֵהוּ - מִמַּטָּה לְמַעְלָה. וּבָרוּךְ אֵל עֶלְיוֹן (אשר מגן צריך בידך), וּבָרוּךְ אֵל עֶלְיוֹן - מִמַּעְלָה לְמַטָּה. וַיִּתֶּן לוֹ מַעֲשֵׂר מִכֹּל - לְהִתְדַּבֵּק בַּמָּקוֹם שֶׁהַקֶּשֶׁר נִקְשָׁר לְמַטָּה."],[6,"","בְּעוֹדָם הוֹלְכִים פָּגַשׁ בָּהֶם רַבִּי יֵיסָא וִיהוּדִי אֶחָד עִמּוֹ. וְהָיָה אוֹתוֹ הַיְּהוּדִי אוֹמֵר, (שם כה) לְדָוִד אֵלֶיךְ ה' נַפְשִׁי אֶשָּׂא. לְדָוִד, וְכִי לָמָּה לֹא כָתוּב מִזְמוֹר לְדָוִד אוֹ לְדָוִד מִזְמוֹר?"],[7,"","אֶלָּא בִּשְׁבִיל דַּרְגָּתוֹ אָמַר דָּוִד אֶת הַתִּשְׁבַּחַת שֶׁאָמַר בִּשְׁבִילוֹ. אֵלֶיךְ ה' נַפְשִׁי אֶשָּׂא, אֵלֶיךְ ה' לְמַעְלָה. נַפְשִׁי, מִי זוֹ נַפְשִׁי? (אשא) זֶה דָוִד, (הוא) הַדַּרְגָּה הָרִאשׁוֹנָה שֶׁאָמַרְנוּ. אֶשָּׂא - אַעֲלֶה, כְּמוֹ שֶׁנֶּאֱמַר (שם קכא) אֶשָּׂא עֵינַי אֶל הֶהָרִים. מִשּׁוּם שֶׁדָּוִד הָיָה מִשְׁתַּדֵּל כָּל יָמָיו לְהַעֲלוֹת אֶת דַּרְגָּתוֹ לְהִתְעַטֵּר לְמַעְלָה וּלְהִתְקַשֵּׁר שָׁם בְּקֶשֶׁר שָׁלֵם כָּרָאוּי."],[8,"","כְּמוֹ כֵן (שם קג) לְדָוִד בָּרְכִי נַפְשִׁי אֶת ה'. מִשּׁוּם דַּרְגָּתוֹ אָמַר. וּמָה אָמַר בָּרְכִי נַפְשִׁי אֶת ה'? אֶת - לְהִתְקַשֵּׁר בְּקֶשֶׁר לְמַעְלָה. וְכָל קְרָבַי, מִי הֵם קְרָבַי? אֵלּוּ שְׁאָר חַיּוֹת הַשָּׂדֶה שֶׁנִּקְרָאוֹת קְרָבַיִם, כְּמוֹ שֶׁנֶּאֱמַר (שיר ה) וּמֵעַי הָמוּ עָלָיו. דָּבָר אַחֵר בָּרְכִי נַפְשִׁי - בִּשְׁבִילוֹ הוּא אָמַר. אֶת ה' - זוֹ שְׁלֵמוּת הַכֹּל. אֶת ה' - הַכְּלָל שֶׁל הַכֹּל."],[9,"","אָמַר רַבִּי אֶלְעָזָר לְרַבִּי יֵיסָא, רָאִיתִי אוֹתְךְ שֶׁבָּאתָ עִם הַשְּׁכִינָה וְהִתְחַבַּרְתָּ. אָמַר לוֹ, כָּךְ זֶה וַדַּאי. וְשָׁלֹשׁ פַּרְסָאוֹת שֶׁהָלַכְתִּי עִמָּהּ וְאָמְרָה לִי כַּמָּה דְבָרִים מְעֻלִּים, וַאֲנִי שָׁמַרְתִּי אוֹתָם לַיּוֹם הַזֶּה, וְלֹא יָדַעְתִּי שֶׁהוּא הַמָּאוֹר שֶׁמֵּאִיר כְּמוֹ שֶׁרָאִיתִי כָּעֵת."],[10,"","אָמַר רַבִּי אֶלְעָזָר לַיְּהוּדִי הַהוּא, מַה שְּׁמֶךְ? אָמַר לוֹ, יוֹעֵזֶר. אָמַר לוֹ, יוֹעֵזֶר וְאֶלְעָזָר (דבר אחד) יוֹשְׁבִים יַחַד. יָשְׁבוּ עַל סֶלַע אֶחָד בַּשָּׂדֶה הַהוּא. פָּתַח אוֹתוֹ הַיְּהוּדִי וְאָמַר, (ישעיה מג) אָנֹכִי אָנֹכִי הוּא מֹחֶה פְשָׁעֶיךְ לְמַעֲנִי וְחַטֹּאתֶיךְ לֹא אֶזְכֹּר. מָה הַטַּעַם פַּעֲמַיִם אָנֹכִי אָנֹכִי?."]]],[["אֶלָּא חַד בְּסִינַי וְחַד בְּשַׁעֲתָא דְּבָרָא עָלְמָא, דִּכְתִיב (שמות כ׳:ב׳) אָנֹכִי יְיָ אֱלֹהֶיךָ דָּא הוּא בְּסִינַי. וְחַד כַּד בְּרָא עָלְמָא דִּכְתִיב, (ישעיהו מ״ה:י״ב) אָנֹכִי עָשִׂיתִי אֶרֶץ וְאָדָם עָלֶיהָ בָּרָאתִי. הוּא, בְּגִין לְאַחֲזָאָה דְּלָא הֲוֵי פִּירוּדָא בֵּין עֵילָא וְתַתָּא.","מוֹחֶה פְשָׁעֶיךָ. מַעֲבִיר פְּשָׁעֶיךָ לָא כְּתִיב, אֶלָּא מוֹחֶה. בְּגִין דְּלָא יִתְחַזּוּן לְעָלְמִין. לְמַעֲנִי. מַאי לְמַעֲנִי, בְּגִין אִנּוּן רַחֲמִין דְּתַלְיָין בִּי דִּכְתִיב, (דברים ד׳:ל״א) כִּי אֵל רַחוּם יְיָ אֱלהֶיךָ וְגו'.","דָּבָר אַחֵר מוֹחֶה פְשָׁעֶיךָ לְמַעֲנִי. תָּא חֲזֵי (לעיל פד ב) חַיָּיבֵי עָלְמָא עָבְדִין פְּגִימוּתָא לְעֵילָא, דְכַד אִנּוּן חוֹבִין סָלְקִין רַחֲמִין וּנְהִירוּ עִלָּאָה וְיַנִּיקוּ דְּבִרְכָאן לָא נָחִית לְתַתָּא, וְהַאי דַרְגָּא לָא נָטִיל בִּרְכָאן דִּלְעֵילָא לְיַנָּקָא לְתַתָּא. וּבְגִין כָּךְ לְמַעֲנִי בְּגִין דְּלָא יִתְמָנְעוּן בִּרְכָאן לְיַנָּקָא (ליה) לְכֹלָּא.","כְּגַוְונָא דָא (דברים לכ) רְאוּ עַתָּה כִּי אֲנִי אֲנִי הוּא. לְאַחֲזָאָה דְּלָא הֲוֵי פִּירוּדָא בֵּין עֵילָא וְתַתָּא כְּמָה דְּאִתְּמָר.","תָּא חֲזֵי, כְּגַוְונָא דָא כַּד אִשְׁתַּכָּחוּ זַכָּאִין בְּעָלְמָא אִתְעָרוּ בִּרְכָאן לְעָלְמִין כֻּלְהוּ. כֵּיוָן דְּאָתָא אַבְרָהָם אִתְעַר בִּרְכָאן לְעָלְמָא דִּכְתִיב וַאֲבָרֶכְךָ וְהְיֵה בְּרָכָה. מַאי וֶהְיֵה בְּרָכָה. רֶמֶז דְיִשְׁתַּכְּחוּן בְּגִינֵיהּ בִּרְכָאן לְעֵילָא וְתַתָּא דִּכְתִיב וְנִבְרְכוּ בְךָ וְגו' וּכְתִיב וַאֲבָרְכָה מְבָרַכֶיךָ.","אֲתָא יִצְחָק אוֹדַע לְכֹלָּא דְּאִית דִּין וְאִית דַּיָּין לְעֵילָא לְאִתְפָּרְעָא מֵרַשִּׁיעַיָא, וְאִיהוּ אִתְעַר דִּינָא בְּעָלְמָא בְּגִין דְּיִדְחֲלוּן לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא כָּל בְּנֵי עָלְמָא. אֲתָא יַעֲקֹב וְאִתְעַר רַחֲמֵי בְּעָלְמָא וְאַשְׁלִים מְהֵימְנוּתָא בְּעָלְמָא כְּדְקָא חָזֵי.","בְּיוֹמֵי דְאַבְרָהָם מַה כְּתִיב וּמַלְכִּי צֶדֶק מֶלֶךְ שָׁלֵם, דְּאִתְעַטְּרַת כֻּרְסְיָיא בְּדוּכְתֵּיהּ, וּכְדֵין אִשְׁתְּכַח מֶלֶךְ שָׁלֵם בְּלָא פְּגִימוּ כְּלַל. הוֹצִיא לֶחֶם וָיָיִן דְּאַפִּיק מְזוֹנִין לְעָלְמִין כֻּלְהוּ כְּדְקָא חָזֵי. הוֹצִיא לֶחֶם וָיָיִן דְּלָא אִתְמְנָעוּ בִּרְכָאן מִכֻּלְהוּ עָלְמִין. הוֹצִיא כְּמָא דְאַתְּ אָמֵר, (בראשית א׳:כ״ד) תּוֹצֵא הָאָרֶץ מִדַרְגִּין דִּלְעֵילָא אַפִּיק מְזוֹנִין וּבִרְכָאן לְעָלְמִין כֻּלְהוּ.","וְהוּא כֹהֵן לְאֵל עֶלְיוֹן דְּאִשְׁתְּכַח כֹּלָּא בִּשְׁלִימוּ עִלָּאָה כְּדְקָא חָזֵי. לְאִתְחֲזָאָה כְּמָה דְחַיָּיבַיָא עָבְדֵי פְּגִימוּ בְּעָלְמָא וּמָנְעֵי בִּרְכָאן. הָכִי נָמֵי בְּגִין זַכָּאִין אַתְיָין (אתחזיאן) בִּרְכָאן לְעָלְמָא, וּבְגִינַיְיהוּ אִתְבָּרְכָאן כָּל בְּנֵי עָלְמָא:","וַיִּתֶּן לוֹ מַעֲשֵׂר מִכֹּל. מַאי מַעֲשֵׂר מִכֹּל מֵאִנּוּן בִּרְכָאן דְּנָפְקֵי מִכֹּל. בְּגִין דְּאִיהוּ אֲתַר דְּכָל בִּרְכָאן דְּנָחֲתֵי לְעָלְמָא מִתַּמָּן נָפְקֵי. דָּבָר אַחֵר וַיִּתֵּן לוֹ מַעֲשֵׂר מִכֹּל. קוּדְשָׁא בְּרִיךְ הוּא יַהַב לֵיהּ מַעַשְׂרָא. וּמַאן אִיהוּ, דָּא דַרְגָּא דְּכָל פִּתְחִין דִּמְהֵימְנוּתָא וּבִרְכָאן דְּעָלְמָא בֵּיהּ קָיְימֵי וְאִיהוּ מַעֲשֵׂר וְאִיהוּ חַד מֵעֲשָׂרָה וְאִיהוּ עֲשָׂרָה מִמֵּאָה. מִכָּאן וּלְהָלְאָה עָאל אַבְרָהָם בְּקִיּוּמָא דִלְעֵילָא כְּדְקָא חָזֵי.","אָמַר לֵיהּ רַבִּי אֶלְעָזָר שַׁפִּיר קָא אֲמַרְתְּ. אָמַר לֵיהּ רַבִּי אֶלְעָזָר מַאי עֲבִידְתָּךְ, אָמַר לֵיהּ קַרְיָנָא דַרְדְּקֵי בְּאַתְרִי, הַשְׁתָּא אֲתָא רַבִּי יוֹסֵי דִּכְפַר חָנִין לְמָתָא וּסְלִיקוּ לוֹן מִגַבָּאי וְאוֹתְבוּ לוֹן לְגַבֵּיהּ. וְהֲווּ יָהֲבִין לִי כָּל בְּנִי מָתָא אַגְרָא כְּהַהוּא זִמְנָא דְדַרְדְּקֵי הֲווּ גַּבָּאי. וְאִסְתַּכַּלְנָא בְּנַפְשָׁאי דְּלָא אִתְחֲזֵי לִי לְאִתְהַנֵּי מִנַּיְיהוּ לְמַגָּנָא, וַאֲגִירְנָא גַרְמָאי בַּהֲדֵי דְּהַאי חַכִּים. אָמַר רַבִּי אֶלְעָזָר בִּרְכָאן דְּאַבָּא אִצְטְרִיכוּ הָכָא.","קָמוּ. אָתוּ קַמֵּיהּ דְּרַבִּי שִׁמְעוֹן (לבתר), וְהֲוָה יָתִיב וְלָעֵי כָּל יוֹמָא קַמֵּיהּ דְּרַבִּי שִׁמְעוֹן. וְיוֹמָא חַד הֲוָה עָסִיק בִּנְטִילַת יָדַיִם קַמֵּיהּ. אָמַר כָּל מַאן דְּלָא נָטִיל יְדוֹי כְּדְקָא יְאוּת, אַף עַל גַּב דְּאִתְעַנַּשׁ לְעֵילָא אִתְעַנַּשׁ לְתַתָּא, וּמַאי עוֹנְשֵׁיהּ לְתַתָּא, דְּגָרִים לֵיהּ לְגַרְמֵיהּ מִסְכְּנוּתָא. כְּמָה דְּעוֹנְשֵׁיהּ כָּךְ, הָכִי הוּא זָכֵי מַאן דְּנָטִיל יְדוֹי כְּדְקָא יְאוּת דְּגָרִים לְגַרְמֵיהּ בִּרְכָאן דִּלְעֵילָא דְּשָׁרָאן בִּרְכָאן עַל יְדוֹי כְּדְקָא יְאוּת, וְאִתְבָּרַךְ בְּעוּתְרָא."],[[0,"אלא חד בסיני וכו':","והשיב אלא אנכי אחד הוא בסיני ואנכי אחד בשעה שנברא העולם. פירוש. אנכי הוא שם המלכות. וזהו בסיני. אבל בבריאת העולם הוא שם הבינה, כי בסוד עלית המלכות לבינה נקראה גם הבינה בשם אנכי כמו המלכות. \u0003אנכי ה' אלקיך\u0004 זה בסיני ואחד כשברא העולם, שכתוב \u0003אנכי עשיתי ארץ\u0004 וכו'. וכוללם כאן המלכות ובינה יחדיו, כדי להראות שלא היה פירוד, בין למעלה שהיא בינה, ובין למטה שהיא מלכות."],[1,"מוחה פשעיך:","שואל, מעביר פשעיך לא כתוב, אלא מוחה. ומשיב, שהוא כדי שלא יתראו עוד לעולם. \u0003למעני\u0004 מהו פירושו. היינו בשביל לגלות הרחמים התלוים בי. כמ\"ש כי אל רחום ה' אלקיך, וגו'."],[2,"ד\"א מוחה פשעיך למעני:","בוא וראה, רשעי העולם בחטאיהם עושים פגם למעלה. כי כשהחטאים עולים, הרחמים ואור העליון ויניקת הברכות אינם יורדים למטה. ומדרגה זו, דהיינו הנוקבא הנק' אנכי. אינה מקבלת משום זה ברכות מלמעלה להניק להתחתונים, וע\"כ נחשב זה אצלה לפגם ומשום זה אומרת \u0003למעני,\u0004 שלא ימנעו ממני, הברכות להניק לכל."],[3,"כגוונא דא ראו עתה וכו'.","כעין זה כתוב ראו עתה כי אני אני הוא. ששם ג\"כ אני א' יורה על בינה, ואני ב' על המלכות, כדי להראות שאין פירוד בין הבינה שלמעלה והמלכות שלמטה. כמו שאמרנו. בהכתוב אנכי אנכי וגו'."],[4,"ת\"ח כגוונא דא וכו':","בוא וראה, כעין זה, כאשר נמצאים צדיקים בעולם נמשכות הברכות לכל העולמות. כיון שבא אברהם, נמשכו הברכות לעולם, שכתוב ואברכך, והיה ברכה. ושואל, מהו והיה ברכה. ואומר, רמז, שבזכותו תמצאנה הברכות למעלה, בעולמות העליונים, ולמטה, בעולמות תחתונים, שכתוב ונברכו בך וגו', דהיינו התחתונים, וכתוב ואברכה מברכיך. דהיינו עולמות העליונים. שבשעה שמשפיעים ברכות למטה הם מתברכים תחילה, כנודע, שז\"ס ואברכה מברכיך."],[5,"אתא יצחק אודע וכו':","בא יצחק הודיע לכל, שיש דין ויש דיין למעלה להפרע מן הרשעים. והוא העיר הדין בעולם, כדי שכל בני עולם ייראו את הקב\"ה. בא יעקב, והעיר רחמים בעולם, והשלים האמונה בעולם כראוי. כי אברהם המשיך החסד, שה\"ס קו ימין של האמונה שה\"ס הנוקבא. ויצחק המשיך לה הדין והגבורה. שה\"ס קו שמאל שלה. ויעקב השלים אותה בהמשכת הרחמים שה\"ס קו האמצעי."],[6,"ביומי דאברהם וכו':","בימיו של אברהם מה כתוב. ומלכי צדק מלך שלם. שנתעטר הכסא, דהיינו הנוקבא, במקומה. בבינה. ואז נמצאת הנוקבא שהיא מלך שלם בלי פגם כלל. \u0003הוציא לחם ויין\u0004 שהנוקבא הוציאה מזונות לכל העולמות כראוי. \u0003הוציא לחם ויין,\u0004 יורה שלא נמנעו הברכות מכל העולמות. \u0003הוציא,\u0004 הוא כמש\"א, \u0003תוצא\u0004 הארץ, שהיא הנוקבא. שהוציאה ממדרגות העליונות מזונות וברכות לכל העולמות."],[7,"והוא כהן לאל עליון:","היינו שנמצא הכל בשלימות עליונה כראוי. דהיינו בשלימות הבינה הנקראת אל עליון. להורות כמו שהרשעים עושים פגם בעולם, ומונעים הברכות מן העולם, כן בשביל הצדיקים באים ברכות לעולם, ובשבילם מתברכים כל בני העולם."],[8,"ויתן לו מעשר מכל:","שואל מהו מעשר מכל. ואומר, שנתן לו מלכי צדק מאלו הברכות היוצאות \u0003מכל\u0004 שהוא יסוד. כלומר שמלכי צדק שהיא הנוקבא קבלה המעשר שה\"ס הברכות, מהיסוד, והשפיעה לאברהם. ולמה מהיסוד. משום שהוא המקום, אשר כל הברכות היורדות לעולם, משם הן יוצאות. דבר אחר, \u0003ויתן לו מעשר מכל,\u0004 שהקב\"ה נתן לאברהם מעשר, ומה הוא מעשר, הוא אחד מעשרה, והוא עשרה ממאה. דהיינו המלכות, אשר בקטנותה אין בה אלא ספירה אחת כתר, והוא אז אחת מעשר ספירות שבז\"א. ובגדלותה יש לה עשר ספירות שלמות, והיא אז עשר ממאה ספירות שבז\"א. והקב\"ה נתן לאברהם מדרגה הזאת. מכאן ואילך, נכנס אברהם בהקיום של מעלה כראוי. דהיינו שזכה להשגה שלמה לנצחיות. א\"ל ר' אלעזר יפה אמרת."],[9,"א\"ל ר' אלעזר וכו':","א\"ל ר' אלעזר מה מעשיך. אמר לו, מלמד תנוקות אני במקומי. ועתה בא לעיר, ר' יוסי דכפר חנין, ולקחו ממני את התנוקות והושיבו אותם אצלו. ומכל מקום נתנו לי כל בני עירי את שכרי כמו בעת שהתנוקות היו אצלי. אלא שהסתכלתי בנפשי שלא ראוי לי להנות מהם בחנם, השכרתי את עצמי אל חכם הזה. דהיינו לר' ייסא, כנ\"ל. אמר ר' אלעזר, צריכים כאן לברכותיו של אבי. הוא ר' שמעון בן יוחאי."],[10,"קמו אתו וכו':","קמו ובאו לפני ר\"ש. והיה אותו היהודי יושב ולומד כל היום לפני ר' שמעון. יום אחד היה עוסק לפניו בהלכות נטילת ידים. אמר ר' שמעון, כל מי שאינו נוטל ידיו כראוי, מלבד שנענש על זה למעלה, נענש גם כן למטה בעולם הזה. ומה ענשו למטה, הוא שגורם לעצמו עניות. וכמו שהוא ענשו, כן הוא שכרו ג\"כ למעלה ולמטה. ומי שנוטל ידיו כראוי, גורם לעצמו ברכות של מעלה, שהברכות העליונות שורות על ידיו כראוי, וכן מתברך למטה בעשירות."]],[[0,"","אֶלָּא אֶחָד בְּסִינַי, וְאֶחָד בְּשָׁעָה שֶׁבָּרָא אֶת הָעוֹלָם, שֶׁכָּתוּב (שמות כ) אָנֹכִי ה' אֱלֹהֶיךְ. זֶה הוּא בְּסִינַי. וְאֶחָד כְּשֶׁבָּרָא אֶת הָעוֹלָם, שֶׁכָּתוּב (ישעיה מה) אָנֹכִי עָשִׂיתִי אֶרֶץ וְאָדָם עָלֶיהָ בָרָאתִי. הוּא כְּדֵי לְהַרְאוֹת שֶׁאֵין פֵּרוּד בֵּין מַעְלָה וּמַטָּה."],[1,"","מֹחֶה פְשָׁעֶיךְ, לֹא כָתוּב מַעֲבִיר פְּשָׁעֶיךְ אֶלָּא מוֹחֶה, כְּדֵי שֶׁלֹּא יִתְרָאוּ לְעוֹלָמִים. לְמַעֲנִי, מַה זֶּה לְמַעֲנִי? מִשּׁוּם אוֹתָם הָרַחֲמִים שֶׁתְּלוּיִים בִּי, שֶׁכָּתוּב (דברים ד) כִּי אֵל רַחוּם ה' אֱלֹהֶיךְ וְגוֹ'."],[2,"","דָּבָר אַחֵר מֹחֶה פְשָׁעֶיךְ לְמַעֲנִי - בֹּא רְאֵה, הָרְשָׁעִים שֶׁל הָעוֹלָם עוֹשִׂים פְּגָם לְמַעְלָה, שֶׁכַּאֲשֶׁר אוֹתָם חֲטָאִים עוֹלִים, רַחֲמִים וְאוֹר עֶלְיוֹן וִינִיקַת הַבְּרָכוֹת לֹא יוֹרְדוֹת לְמַטָּה, וְהַדַּרְגָּה הַזּוֹ אֵינָהּ נוֹטֶלֶת בְּרָכוֹת שֶׁלְּמַעְלָה לְהָנִיק לְמַטָּה. וּמִשּׁוּם כָּךְ לְמַעֲנִי, כְּדֵי שֶׁלֹּא יִמָּנְעוּ בְרָכוֹת לְהָנִיק (לו) לַכֹּל."],[3,"","כְּמוֹ כֵן, (שם לב) רְאוּ עַתָּה כִּי אֲנִי אֲנִי הוּא. לְהַרְאוֹת שֶׁאֵין פֵּרוּד בֵּין מַעְלָה וּמַטָּה, כְּמוֹ שֶׁנִּתְבָּאֵר."],[4,"","בֹּא רְאֵה, כְּמוֹ זֶה כְּשֶׁנִּמְצָאִים צַדִּיקִים בָּעוֹלָם, מִתְעוֹרְרוֹת בְּרָכוֹת לְכָל הָעוֹלָמוֹת. כֵּיוָן שֶׁבָּא אַבְרָהָם, הִתְעוֹרְרוּ בְרָכוֹת לָעוֹלָם, שֶׁכָּתוּב וַאֲבָרֶכְךְ וֶהְיֵה בְּרָכָה. מַה זֶּה וֶהְיֵה בְּרָכָה? רֶמֶז שֶׁיִּמָּצְאוּ בִגְלָלוֹ בְּרָכוֹת לְמַעְלָה וּמַטָּה, שֶׁכָּתוּב וְנִבְרְכוּ בְךְ וְגוֹ', וְכָתוּב וַאֲבָרְכָה מְבָרֲכֶיךְ."],[5,"","בָּא יִצְחָק וְהוֹדִיעַ לַכֹּל שֶׁיֵּשׁ דִּין וְיֵשׁ דַּיָּן לְמַעְלָה לְהִפָּרַע מִן הָרְשָׁעִים, וְהוּא עוֹרֵר אֶת הַדִּין בָּעוֹלָם כְּדֵי שֶׁיִּירְאוּ מֵהַקָּדוֹשׁ בָּרוּךְ הוּא כָּל בְּנֵי הָעוֹלָם. בָּא יַעֲקֹב וְעוֹרֵר רַחֲמִים בָּעוֹלָם, וְהִשְׁלִים אֶת הָאֱמוּנָה בָּעוֹלָם כָּרָאוּי."],[6,"","בִּימֵי אַבְרָהָם מַה כָּתוּב? וּמַלְכִּי צֶדֶק מֶלֶךְ שָׁלֵם. שֶׁהִתְעַטֵּר הַכִּסֵּא בִּמְקוֹמוֹ, וְאָז נִמְצָא מֶלֶךְ שָׁלֵם לְלֹא פְגָם כְּלָל. הוֹצִיא לֶחֶם וָיָיִן - שֶׁהוֹצִיא מְזוֹנוֹת וּבְרָכוֹת לָעוֹלָמוֹת כֻּלָּם כָּרָאוּי. הוֹצִיא לֶחֶם וָיָיִן - שֶׁלֹּא יִמָּנְעוּ הַבְּרָכוֹת מִכָּל הָעוֹלָמוֹת. הוֹצִיא - כְּמוֹ שֶׁנֶּאֱמַר תּוֹצֵא הָאָרֶץ, מֵהַדְּרָגוֹת שֶׁלְּמַעְלָה מוֹצִיא מְזוֹנוֹת וּבְרָכוֹת לְכָל הָעוֹלָמוֹת."],[7,"","וְהוּא כֹהֵן לְאֵל עֶלְיוֹן - שֶׁהַכֹּל נִמְצָא בִּשְׁלֵמוּת עֶלְיוֹנָה כָּרָאוּי. לְהַרְאוֹת, כְּמוֹ שֶׁהָרְשָׁעִים עוֹשִׂים פְּגָם בָּעוֹלָם וּמוֹנְעִים בְּרָכוֹת, כָּךְ גַּם בִּשְׁבִיל הַצַּדִּיקִים בָּאוֹת בְּרָכוֹת לָעוֹלָם, וּבִגְלָלָם מִתְבָּרְכִים כָּל בְּנֵי הָעוֹלָם."],[8,"","וַיִּתֶּן לוֹ מַעֲשֵׂר מִכֹּל, מַה זֶּה מַעֲשֵׂר מִכֹּל? מֵאוֹתָם הַבְּרָכוֹת שֶׁיּוֹצְאוֹת מִכֹּל, מִשּׁוּם שֶׁהוּא הַמָּקוֹם שֶׁכָּל הַבְּרָכוֹת שֶׁיּוֹרְדוֹת לָעוֹלָם יוֹצְאוֹת מִשָּׁם. דָּבָר אַחֵר וַיִּתֶּן לוֹ מַעֲשֵׂר מִכֹּל - הַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לוֹ מַעֲשֵׂר, וּמַה הוּא? זוֹ הַדַּרְגָּה שֶׁכָּל פִּתְחֵי הָאֱמוּנָה וְהַבְּרָכוֹת שֶׁל הָעוֹלָם עוֹמְדוֹת בָּהּ, וְהִיא מַעֲשֵׂר, וְהִיא אַחַת מֵעֲשָׂרָה, וְהִיא עֲשָׂרָה מִמֵּאָה. מִכָּאן וָהָלְאָה נִכְנַס אַבְרָהָם בַּקִּיּוּם שֶׁלְּמַעְלָה כָּרָאוּי."],[9,"","אָמַר לוֹ רַבִּי אֶלְעָזָר, יָפֶה אָמַרְתָּ. אָמַר לוֹ רַבִּי אֶלְעָזָר, מַה מַּעֲשֶׂיךְ? אָמַר לוֹ, מְלַמֵּד תִּינוֹקוֹת בִּמְקוֹמִי. כָּעֵת בָּא רַבִּי יוֹסֵי מִכְּפָר חָנִין לָעִיר, וְסִלְּקוּ אוֹתָם מֵאֶצְלִי, וְהוֹשִׁיבוּ אוֹתָם אֶצְלוֹ. וְהָיוּ נוֹתְנִים לִי כָּל בְּנֵי הָעִיר שָׂכָר כְּמוֹ אוֹתוֹ הַזְּמַן שֶׁהַתִּינוֹקוֹת הָיוּ אֶצְלִי, וְהִסְתַּכַּלְתִּי בְעַצְמִי שֶׁלֹּא רָאוּי לִי לֵהָנוֹת מֵהֶם בְּחִנָּם, וְהִשְׂכַּרְתִּי עַצְמִי עִם הֶחָכָם (ההוא) הַזֶּה. אָמַר רַבִּי אֶלְעָזָר, כָּאן צָרִיךְ אֶת הַבְּרָכוֹת שֶׁל אַבָּא."],[10,"","קָמוּ, הָלְכוּ לִפְנֵי רַבִּי שִׁמְעוֹן (אחר כך), וְהָיָה יוֹשֵׁב וְלוֹמֵד כָּל יוֹם לִפְנֵי רַבִּי שִׁמְעוֹן. וְיוֹם אֶחָד הָיָה עָסוּק בִּנְטִילַת יָדַיִם לְפָנָיו. אָמַר, כָּל מִי שֶׁלֹּא נוֹטֵל יָדָיו כָּרָאוּי, אַף עַל גַּב שֶׁנֶּעֱנָשׁ לְמַעְלָה - נֶעֱנָשׁ לְמַטָּה. וּמָה עָנְשׁוֹ לְמַטָּה? שֶׁגּוֹרֵם לְעַצְמוֹ עֹנִי. כְּמוֹ שֶׁעָנְשׁוֹ כָּךְ - כָּךְ זוֹכֶה מִי שֶׁנּוֹטֵל יָדָיו כָּרָאוּי, שֶׁגּוֹרֵם לְעַצְמוֹ בְּרָכוֹת שֶׁלְּמַעְלָה, שֶׁשּׁוֹרוֹת הַבְּרָכוֹת עַל יָדוֹ כָּרָאוּי וּמִתְבָּרֵךְ בְּעֹשֶׁר."]]],[["לְבָתַר אַקְדִּים רַבִּי שִׁמְעוֹן חָמָא לֵיהּ דְּאַנְטַל יְדוֹי בְּמַיָא וְנָטִיל לוֹן בְּשִׁיעוּרָא סַגְיָיא דְמַיִין. אָמַר רַבִּי שִׁמְעוֹן מַלֵּא יָדָיו מִבִּרְכוֹתֶיךָ. וְכָךְ הֲוָה, מֵהַהוּא יוֹמָא וּלְהָלְאָה אִתְעַתַּר וְאַשְׁכַּח סִימָא וְהֲוָה לָעֵי בְּאוֹרַיְיתָא וְיָהִיב מְזוֹנָא לְמִסְכְּנֵי כָּל יוֹמָא, וְהֲוָה חָדֵי עִמְּהוֹן וּמַסְבַּר לוֹן אַנְפִּין נְהִירִין. קָרָא עֲלֵיהּ רַבִּי שִׁמְעוֹן (ישעיהו מ״א:ט״ז) וְאַתָּה תָּגִיל בַּיְיָ בִּקְדוֹשׁ וְגו', (חסר)","אַחַר הַדְּבָרִים הָאֵלֶּה הָיָה דְּבַר יְיָ אֶל אַבְרָם וְגו'. רַבִּי יְהוּדָה פַּתָח (שיר השירים ז׳:י״א) אֲנִי לְדוֹדִי וְעָלַי תְּשׁוּקָתוֹ. הָא אוּקְמוּהָ, אֲבָל בְּאִתְעֲרוּתָא דִלְתַתָּא אִשְׁתְּכַח אִתְעֲרוּתָא לְעֵילָא, דְּהָא לָא אִתְעַר לְעֵילָא עַד דְּאִתְעַר לְתַתָּא. וּבִרְכָאן דִּלְעֵילָא לָא מִשְׁתַּכְּחֵי אֶלָּא בַּמֶה דְּאִית בֵּיהּ מַמָּשָׁא וְלָאו אִיהוּ רֵיקַנְיָא.","מְנָלָן מֵאֵשֶׁת עוֹבַדְיָהוּ דְּאָמַר לָהּ אֱלִישָׁע (מלכים ב ד) הַגִּידִי לִי מַה יֵּשׁ לָךְ בַּבָּיִת. דְּהָא בִּרְכָאן דִּלְעֵילָא לָא שָׁרְיָין עַל פָּתוֹרָא רֵיקַנְיָא וְלָא בְּאֲתַר רֵיקַנְיָא. מַה כְּתִיב וַתֹּאמֶר אֵין לְשִׁפְחָתְךָ כֹּל בַּבָּיִת כִּי אִם אָסוּךְ שָׁמֶן. מַאי אָסוּךְ. אֶלָּא אֲמְרָה לֵיהּ שִׁיעוּרָא דְהַאי מִשְׁחָא לָאו אִיהִי אֶלָּא כְּדֵי מְשִׁיחַת אֶצְבְּעָא זְעִירָא.","אָמַר לָהּ נִחַמְתַּנִי. דְּהָא לָא יְדַעְנָא הֵיאַךְ יִשְׁרוּן בִּרְכָאן דִּלְעֵילָא בְּדוּכְתָּא רֵיקַנְיָא, אֲבָל הַשְׁתָּא דְּאִית לָךְ שֶׁמֶן, דָּא הוּא אֲתַר לְאִשְׁתַּכָּחָא בֵּיהּ בִּרְכָאן. מִנָּלָן דִּכְתִיב, (תהילים קל״ג:ב׳) כַּשֶּׁמֶן הַטּוֹב וְגו' וְסֵיפֵיהּ מַה כְּתִיב, (תהילים קל״ג:ג׳) כִּי שָׁם צִוָּה יְיָ אֶת הַבְּרָכָה חַיִּים עַד הָעוֹלָם. וּבְאַתְרָא דָּא שָׁרָאן בִּרְכָאן. (ואתמר).","וְאִי תֵימָא (תהילים קל״ג:ג׳) כְּטַל חֶרְמוֹן שֶׁיּוֹרֵד עַל הַרְרֵי צִיּוֹן וְלָא כְּתִיב שֶׁמֶן אֶלָא טַל. אֶלָּא אִיהוּ שֶׁמֶן וְאִיהוּ טַל. הַהוּא טַל אִיהוּ דְּאַטִּיל קוּדְשָׁא בְּרִיךְ הוּא מִמִּשְׁחָא עִלָּאָה. דְּהַהוּא שֶׁמֶן נָפַק לְסִטְרָא דְּיָמִינָא.","תְּרֵין אִנּוּן יַיִן וְשֶׁמֶן. וְאָזְלוּ לִתְרֵין סִטְרִין. יַיִן לִסְטַר שְׂמָאלָא שֶׁמֶן לִסְטַר יָמִינָא. וּמִסִּטְרָא דְיָמִינָא נָפְקֵי בִּרְכָאן לְעָלְמָא וּמִתַּמָּן אִתְמְשַׁח מַלְכוּתָא קַדִּישָׁא וּבְגִין דְּשֶׁמֶן הֲוָה אִתְתַּקַּן לְתַתָּא בְּקַדְמִיתָא, שֶׁמֶן אִזְדַמַּן לְעֵילָא אֲרִיקוּ דְּבִרְכָאן."],[[0,"לבתר אקדים וכו':","אחר כך הקדים ר\"ש עצמו לראות איך נוטל ידיו. ראה אותו נוטל ידיו במים, ונוטלם במדה גדולה של מים. אמר ר' שמעון \u0003מלא ידיו מברכותיך.\u0004 וכך היה, מאותו יום ואילך נתעשר ומצא מטמון, והיה לומד בתורה, ונותן בכל יום מזונות לעניים, והיה שמח עמהם, ומסביר פנים מאירות אליהם. קרא עליו ר\"ש, ואתה תגיל בה' בקדוש וגו'."],[1,"אחר הדברים האלה וגו':","ר' יהודה פתח. אני לדודי ועלי תשוקתו כבר בארוה, חבל על ידי התעוררות של מטה נמצא התעוררות של מעלה. כי לא נתעורר מלמעלה מטרם שנתעורר מלמטה. והברכות של מעלה אינן נמצאות, רק במה שיש בו ממש, ולא במקום ריקן, שאין בו ממש."],[2,"מנלן מאשת עובדיהו וכו':","מאין לנו זה, מאשת עובדיהו. שאלישע אמר לה, הגידי לי מה יש לך בבית. כי הברכות שלמעלה אינן שורות על שולחן ריקן כמ\"ש להלן בלחם הפנים, ולא במקום ריק. כמ\"ש באשת עובדיהו מה כתוב, ותאמר אין לשפחתך כל בבית כי אם אסוך שמן. ושואל מהו \u0003אסוך,\u0004 ואומר אלא, שהיה בו רק כדי משיחת אצבע קטנה. שה\"ס ו\"ק בלי ראש המכונה אצבע קטנה, בסוד ו' קטועה."],[3,"אמר לה וכו':","אמר אלישע, נחמתני כי לא ידעתי, איך תשרינה הברכות של מעלה במקום ריקן. אבל עתה שיש לך שמן, זה הוא מקום שתמצאנה בו הברכות. מאין לנו זה. כי כתוב כשמן הטוב וגו', ובסופו מה כתוב, כי שם צוה ה' את הברכה חיים עד העולם. הרי שבמקום הזה דהיינו בשמן שורות הברכות."],[4,"ואי תימא, כטל וכו':","ואם תאמר, הרי כתוב שם, כטל חרמון שיורד על הררי ציון. שהוא בסמוך להכתוב, כי שם צוה ה' את הברכה. ולא כתוב שמן אלא טל. נמצא שטל הוא מקום הברכה ולא שמן. ומשיב, אלא הוא שמן והוא טל. כלומר ששניהם בחינה אחת הם. כי טל הזה, הוא שהטיל אותו הקב\"ה משמן העליון, ששמן הזה יוצא לצד הימין."],[5,"תרין אנון וכו':","שנים הם, יין ושמן, והולכים לב' צדדים, יין לצד שמאל ושמן לצד ימין, ומצד הימין יוצאות ברכות לעולם. ומשם נמשח מלכות הקדושה. דהיינו למלכי ישראל. ומשום ששמן היה מתתקן למטה מתחילה, דהיינו שהיה לה \u0003אסוך שמן,\u0004 שה\"ס אתערותא דלתתא. נזדמן שמן מלמעלה, דהיינו הורקת הברכות מלמעלה, שה\"ס אתערותא דלעילא. כמ\"ש שם (מלכים ב' ד') הם מגישים אליה והיא מוצקת."]],[[0,"","אַחַר כָּךְ הִקְדִּים רַבִּי שִׁמְעוֹן, וְרָאָה אוֹתוֹ שֶׁנּוֹטֵל יָדָיו בְּמַיִם, וְנוֹטֵל יָדָיו בְּשִׁעוּר רַב שֶׁל מַיִם. אָמַר רַבִּי שִׁמְעוֹן, מַלֵּא יָדָיו מִבִּרְכוֹתֶיךְ. וְכָךְ הָיָה. מֵאוֹתוֹ הַיּוֹם וָהָלְאָה הִתְעַשֵּׁר וּמָצָא אוֹצָר, וְהָיָה עוֹסֵק בַּתּוֹרָה וְנוֹתֵן מָזוֹן לַעֲנִיִּים כָּל יוֹם, וְהָיָה שָׂמֵחַ עִמָּהֶם, וּמַסְבִּיר לָהֶם בְּפָנִים מְאִירוֹת. קָרָא עָלָיו רַבִּי שִׁמְעוֹן, (ישעיה מא) וְאַתָּה תָּגִיל בַּה' בִּקְדוֹשׁ וְגוֹ'."],[1,"","אַחַר הַדְּבָרִים הָאֵלֶּה הָיָה דְבַר ה' אֶל אַבְרָם וְגוֹ'. רַבִּי יְהוּדָה פָּתַח, (שיר ז) אֲנִי לְדוֹדִי וְעָלַי תְּשׁוּקָתוֹ. הֲרֵי פֵּרְשׁוּהָ, אֲבָל בַּהִתְעוֹרְרוּת שֶׁלְּמַטָּה תִּמְצָא הַהִתְעוֹרְרוּת שֶׁלְּמַעְלָה, שֶׁהֲרֵי אֵין מִתְעוֹרֵר לְמַעְלָה עַד שֶׁמִּתְעוֹרֵר לְמַטָּה, וְהַבְּרָכוֹת שֶׁלְּמַעְלָה לֹא נִמְצָאוֹת אֶלָּא בְּמַה שֶּׁיֵּשׁ בּוֹ מַמָּשׁ, וְאֵינוֹ רֵיקָן."],[2,"","מִנַּיִן לָנוּ? מֵאֵשֶׁת עוֹבַדְיָהוּ שֶׁאָמַר לָהּ אֱלִישָׁע (מלכים ב ד) הַגִּידִי לִי מַה יֶּשׁ לָךְ בַּבָּיִת. שֶׁהֲרֵי הַבְּרָכוֹת שֶׁלְּמַעְלָה אֵינָן שׁוֹרוֹת עַל שֻׁלְחָן רֵיק וְלֹא בְּמָקוֹם רֵיק. מַה כָּתוּב? וַתֹּאמֶר אֵין לְשִׁפְחָתְךְ כֹל בַּבַּיִת כִּי אִם אָסוּךְ שָׁמֶן. מַה זֶּה אָסוּךְ? אֶלָּא אָמְרָה לוֹ, הַשִּׁעוּר שֶׁל הַשֶּׁמֶן הַזֶּה אֵינוֹ אֶלָּא כְּדֵי מְשִׁיחַת אֶצְבַּע קְטַנָּה."],[3,"","אָמַר לָהּ, נִחַמְתַּנִי, שֶׁהֲרֵי לֹא יָדַעְתִּי אֵיךְ יִשְׁרוּ הַבְּרָכוֹת שֶׁלְּמַעְלָה בְּמָקוֹם רֵיק, אֲבָל עַכְשָׁו שֶׁיֵּשׁ לָךְ שֶׁמֶן, זֶהוּ מָקוֹם שֶׁיִּמָּצְאוּ בוֹ בְּרָכוֹת. מִנַּיִן לָנוּ? שֶׁכָּתוּב (תהלים קלג) כַּשֶּׁמֶן הַטּוֹב וְגוֹ'. וּבְסוֹפוֹ מַה כָּתוּב? (שם) כִּי שָׁם צִוָּה ה' אֶת הַבְּרָכָה חַיִּים עַד הָעוֹלָם. וּבַמָּקוֹם הַזֶּה שׁוֹרוֹת הַבְּרָכוֹת. (ונתבאר)."],[4,"","וְאִם תֹּאמַר, (שם) כְּטַל חֶרְמוֹן שֶׁיֹּרֵד עַל הַרְרֵי צִיּוֹן, וְלֹא כָתוּב שֶׁמֶן אֶלָּא טַל? אֶלָּא הוּא שֶׁמֶן וְהוּא טַל. אוֹתוֹ הַטַּל הוּא שֶׁהִטִּיל הַקָּדוֹשׁ בָּרוּךְ הוּא מֵהַשֶּׁמֶן הָעֶלְיוֹן. שֶׁאוֹתוֹ הַשֶּׁמֶן יוֹצֵא לְצַד הַיָּמִין."],[5,"","שְׁנַיִם הֵם - יַיִן וְשֶׁמֶן, וְהָלְכוּ לִשְׁנֵי צְדָדִים - הַיַּיִן לְצַד שְׂמֹאל, וְהַשֶּׁמֶן לְצַד יָמִין. וּמִצַּד הַיָּמִין יוֹצְאוֹת בְּרָכוֹת לָעוֹלָם, וּמִשָּׁם נִמְשַׁחַת הַמַּלְכוּת הַקְּדוֹשָׁה. וּמִשּׁוּם שֶׁהַשֶּׁמֶן הָיָה נִתְקָן לְמַטָּה בָּרִאשׁוֹנָה, הַשֶּׁמֶן מְזַמֵּן לְמַעְלָה הֲרָקַת הַבְּרָכוֹת."]]],[["תָּא חֲזֵי, מֵאִתְעֲרוּתָא דְּהַאי שֶׁמֶן דִּלְעֵילָא קָאי לְאֲרָקָא עַל דָּוִד וּשְׁלמֹה לְאִתְבָּרְכָא (על) בְּנוֹי. מְנָא לָן דִּכְתִיב וַיַּעֲמֹד הַשֶּׁמֶן. כְּתִיב הָכָא וַיַּעֲמֹד. וּכְתִיב הָתָם (ישעיהו י״א:י׳) שׁוִֹרְשׁ יִשַּׁי אֲשֶׁר עוֹמֵד לְנֵס עַמִּים.","תָּא חֲזֵי, מִשֻּׁלְחָן דְּלֶחֶם הַפָּנִים דְּבִרְכָאן נָפְקִין מִתַּמָּן וּמְזוֹנָא לְעָלְמָא, לָא בָעֵי לְאִשְׁתַּכָּחָא רֵיקַנְיָא אֲפִלּוּ רִגְעָא חָדָא, בְּגִין דְּלָא יִסְתַּלְּקוּן בִּרְכָאן מִתַּמָּן, אוּף הָכִי לָא מְבָרְכִין עַל שֻׁלְחָן רֵיקַנְיָא, דְּהָא בִּרְכָאן דִּלְעֵילָא לָא שָׁרְיָין עַל שֻׁלְחָן רֵיקַנְיָא.","תָּא חֲזֵי, מַה כְּתִיב אֲנִי לְדוֹדִי וְעָלַי תְּשׁוּקָתוֹ, אֲנִי לְדוֹדִי בְּקַדְמִיתָא וּלְבָתַר וְעָלַי תְּשׁוּקָתוֹ. אֲנִי לְדוֹדִי לְאַתְקָנָא לֵיהּ דּוּכְתָּא בְּקַדְמִיתָא. וּלְבָתַר וְעָלַי תְּשׁוּקָתוֹ.","דָּבָר אַחֵר אֲנִי לְדוֹדִי. דְּהָא תָּנִינָן שְׁכִינְתָּא לָא אִשְׁתַּכְּחַת עִמְהוֹן דְּחַיָּיבַיָא, כֵּיוָן דְּאָתֵי בַּר נָשׁ לְאִתְדַּכָּאָה וּלְמִקְרַב גַּבֵּי דְקוּדְשָׁא בְּרִיךְ הוּא כְּדֵין שְׁכִינְתָּא שַׁרְיָא עֲלֵיהּ. הֲדָא הוּא דִכְתִיב אֲנִי לְדוֹדִי בְּקַדְמִיתָא, וְעָלַי תְּשׁוּקָתוֹ לְבָתַר. אָתֵי בַּר נָשׁ לְאִתְדַּכָּאָה מְדַכְּאִין לֵיהּ.","תָּא חֲזֵי, אַחַר הַדְּבָרִים הָאֵלֶּה דְּרָדַף אַבְרָהָם בָּתַר אִלֵּין מַלְכִין וְקָטִיל לוֹן קוּדְשָׁא בְּרִיךְ הוּא, הֲוָה אַבְרָהָם תּוֹהֶא, אָמַר דִּילְמָא חַס וְשָׁלוֹם גָּרַעֲנָא הַהוּא אַגְרָא דַּהֲוֵינָא אַהֲדַר בְּנֵי נָשָׁא לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא וְאַחִידְנָא בְּהוּ לְקָרָבָא לוֹן לְגַבֵּיהּ וְהַשְׁתָּא אִתְקְטִילוּ בְּנֵי נְשָׁא עַל יָדִי. מִיָּד אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא אַל תִּירָא אַבְרָם אָנֹכִי מָגֵן לָךְ שְׂכָרְךָ הַרְבֵּה וְגו'. אַגְרָא קַבִּילַת עֲלַיְיהוּ, דְּהָא כֻּלְהוּ לָא יִזְכּוּן לְעָלְמִין.","הָיָה דְּבַר יְיָ אֶל אַבְרָם בַּמַּחֲזֶה לֵאמֹר, מַאי בַּמַּחֲזֶה, אֶלָּא בְּהַהוּא חֵיזוּ דַּרְגָּא דְכָל דִּיוּקְנִין אִתְחַזְּיָין בֵּיהּ. אָמַר רַבִּי שִׁמְעוֹן תָּא חֲזֵי, עַד לָא אִתְגְּזַר אַבְרָהָם הֲוָה חַד דַּרְגָּא מַלִּיל עִמֵּיהּ, וּמַאן אִיהוּ דָּא מַחֲזֶה דִּכְתִיב, (במדבר כ״ד:ד׳) מַחֲזֵה שַׁדַּי יֶחזֶה.","כֵּיוָן דְּאִתְגְּזַר הֲווּ כֻּלְהוּ דַּרְגִּין שָׁרָאן עַל הַאי דַרְגָּא, וּכְדֵין מַלִּיל עִמֵּיהּ הֲדָא הוּא דִכְתִיב, (שמות ו׳:ג׳) וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב בְּאֵל שַׁדַּי וְעַד לָא אִתְגְּזַר לָא הֲווּ אִנּוּן דַּרְגִּין שָׁרָאן עֲלוֹי לְמַלָּלָא."],[[0,"ת\"ח אתערותא וכו':","בוא וראה. מן אתערותא דלעילא של שמן הזה, כנ\"ל, עומד להריק על דוד ושלמה, שיתברכו בניהם. מאין לנו, שכתוב, ויעמוד השמן. וילפינן גזירה שוה, כתוב כאן ויעמוד, וכתוב שם, שורש ישי אשר עומד וגו'. מה שם דוד ושלמה ובניהם אחריהם, שהם משורש ישי. אף כאן לדוד ושלמה ובניהם אחריהם."],[1,"ת\"ח משלחן וכו':","בוא וראה, משלחן של לחם הפנים, שמשם יוצאות ברכות ומזונות לעולם, אשר אינו ראוי שימצא ריקן אפילו רגע אחד, כדי שלא יעברו הברכות משם. כן אין לברך על שלחן ריקן. כי הברכות של מעלה אינן שורות על שלחן ריקן."],[2,"ת\"ח מה כתוב וכו':","בוא וראה, מה כתיב, אני לדודי ועלי תשוקתו, שמתחילה אני לדודי, ואחר כך ועלי תשוקתו. \u0003אני לדודי\u0004 לתקן לו מקום מתחילה, באתערותא דלתתא כנ\"ל. ואחר כך ועלי תשוקתו."],[3,"ד\"א אני לדודי וכו':","פירוש אחר על אני לדודי. כי למדנו שהשכינה אינה נמצאת עם הרשעים. כיון שאדם בא לטהר, ולקרב את עצמו אל הקב\"ה, אז שורה עליו השכינה. וז\"ש אני לדודי מתחילה. ואחר כך, ועלי תשוקתו. כי כשבא האדם לטהר, מטהרין אותו."],[4,"ת\"ח אחר וכו':","בוא וראה, אחר הדברים האלה, שאברהם רדף אחר המלכים והקב\"ה הרג אותם. היה אברהם משתומם, אמר אולי ח\"ו הפסדתי כל אותו השכר, שהיתי מחזיר אנשים בתשובה להקב\"ה, ואחזתי בהם לקרבם אליו, כי עתה נהרגו אנשים על ידי. מיד א\"ל הקב\"ה, אל תירא אברם אנכי מגן לך שכרך הרבה וגו', שכר אתה מקבל עליהם, על שנהרגו, כי כולם, לעולם לא יזכו להטיב מעשיהם."],[5,"היה דבר ה' אל אברם במחזה לאמור.","שואל מהו במחזה. ואומר, אלא \u0003במראה\u0004 ההוא, שהיא מדרגה שכל הצורות נראות בה. אמר ר' שמעון בוא וראה. מטרם שנמול אברהם, היה רק מדרגה אחת מדבר עמו. ומי היא, זהו \u0003מחזה,\u0004 דהיינו הנוקבא, שכתוב בה, מחזה שדי יחזה."],[6,"כיון דאתגזר וכו':","כיון שנימול, היו כל המדרגות שורות על אותו מדרגה הנקראת מחזה, ואז דבר עמו, וז\"ש וארא אל אברהם שה\"ס חסד, אל יצחק ה\"ס גבורה, ואל יעקב ה\"ס ת\"ח, \u0003באל שדי\u0004 ה\"ס יסוד ומלכות שכל המדרגות מחסד ואילך מאירים בהנוקבא. ומטרם שנמול לא היו אלו המדרגות שורות עליו לדבר עמו, אלא הנוקבא בלבדה. שה\"ס \u0003מחזה שדי\u0004 בלבד."]],[[0,"","בֹּא רְאֵה, מֵהַהִתְעוֹרְרוּת שֶׁל הַשֶּׁמֶן הַזֶּה שֶׁלְּמַעְלָה בָּא לְהָרִיק עַל דָּוִד וּשְׁלֹמֹה לְהִתְבָּרֵךְ (על) בְּנוֹ. מִנַּיִן לָנוּ? שֶׁכָּתוּב וַיַּעֲמֹד הַשָּׁמֶן. כָּתוּב כָּאן וַיַּעֲמֹד, וְכָתוּב שָׁם (ישעיה יא) שֹׁרֶשׁ יִשַׁי אֲשֶׁר עֹמֵד לְנֵס עַמִּים."],[1,"","בֹּא רְאֵה, מִשֻּׁלְחָן שֶׁל לֶחֶם הַפָּנִים, שֶׁמִּשָּׁם יוֹצְאוֹת הַבְּרָכוֹת וּמָזוֹן לָעוֹלָם, לֹא צָרִיךְ שֶׁיִּמָּצֵא רֵיק אֲפִלּוּ רֶגַע אֶחָד, כְּדֵי שֶׁלֹּא יִסְתַּלְּקוּ מִשָּׁם הַבְּרָכוֹת. אַף כָּךְ לֹא מְבָרְכִים עַל שֻׁלְחָן רֵיק, שֶׁהֲרֵי הַבְּרָכוֹת שֶׁלְּמַעְלָה אֵין שׁוֹרוֹת עַל שֻׁלְחָן רֵיק."],[2,"","בֹּא רְאֵה מַה כָּתוּב, אֲנִי לְדוֹדִי וְעָלַי תְּשׁוּקָתוֹ. אֲנִי לְדוֹדִי בַּתְּחִלָּה, וְאַחַר כָּךְ וְעָלַי תְּשׁוּקָתוֹ. אֲנִי לְדוֹדִי לְתַקֵּן לוֹ מָקוֹם בַּתְּחִלָּה, וְאַחַר כָּךְ וְעָלַי תְּשׁוּקָתוֹ."],[3,"","דָּבָר אַחֵר אֲנִי לְדוֹדִי, שֶׁהֲרֵי שָׁנִינוּ שֶׁשְּׁכִינָה לֹא נִמְצֵאת עִם הָרְשָׁעִים. כֵּיוָן שֶׁבָּא הָאָדָם לְהִטָּהֵר וּלְהִתְקָרֵב לַקָּדוֹשׁ-בָּרוּךְ-הוּא, אָז הַשְּׁכִינָה שׁוֹרָה עָלָיו. זֶהוּ שֶׁכָּתוּב אֲנִי לְדוֹדִי - בַּהַתְחָלָה, וְעָלַי תְּשׁוּקָתוֹ - לְאַחַר מִכֵּן. בָּא הָאָדָם לְהִטָּהֵר - מְטַהֲרִים אוֹתוֹ."],[4,"","בֹּא רְאֵה, אַחַר הַדְּבָרִים הָאֵלֶּה שֶׁאַבְרָהָם רָדַף אַחַר הַמְּלָכִים הַלָּלוּ וְהָרַג אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא, הָיָה אַבְרָהָם תּוֹהֶה. אָמַר, אוּלַי חַס וְחָלִילָה גָּרַעְתִּי אוֹתוֹ הַשָּׂכָר שֶׁהָיִיתִי מַחֲזִיר בְּנֵי אָדָם אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאָחַזְתִּי בָהֶם לְקָרֵב אוֹתָם אֵלָיו, וְכָעֵת נֶהֶרְגוּ אֲנָשִׁים עַל יָדִי. מִיָּד אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, אַל תִּירָא אַבְרָם אָנֹכִי מָגֵן לָךְ שְׂכָרְךְ הַרְבֵּה מְאֹד וְגוֹ'. שָׂכָר קִבַּלְתָּ עֲלֵיהֶם, שֶׁהֲרֵי כֻּלָּם לֹא יִזְכּוּ לְעוֹלָמִים."],[5,"","הָיָה דְבַר ה' אֶל אַבְרָם בַּמַּחֲזֶה לֵאמֹר, מַה זֶּה בַּמַּחֲזֶה? אֶלָּא בְּאוֹתוֹ הַמַּרְאֶה, הַדַּרְגָּה שֶׁכָּל הַדְּמֻיּוֹת נִרְאוֹת בָּהּ. אָמַר רַבִּי שִׁמְעוֹן, בּא רְאֵה, טֶרֶם שֶׁנִּמּוֹל אַבְרָהָם, הָיְתָה דַרְגָּה אַחַת מְדַבֶּרֶת עִמּוֹ, וּמִי הַמַּחֲזֶה הַזֶּה? שֶׁכָּתוּב (במדבר כד) מַחֲזֵה שַׁדַּי יֶחֱזֶה."],[6,"","כֵּיוָן שֶׁנִּמּוֹל, הָיוּ כָּל הַדְּרָגוֹת שׁוֹרוֹת עַל הַדַּרְגָּה הַזּוֹ, וְאָז דִּבֵּר עִמּוֹ. זֶהוּ שֶׁכָּתוּב (שמות ו) וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב בְּאֵל שַׁדַּי. וְטֶרֶם שֶׁנִּמּוֹל, לֹא הָיוּ אוֹתָן הַדְּרָגוֹת שׁוֹרוֹת עָלָיו לְדַבֵּר."]]],[["וְאִי תֵימָא דְּהָא בְּקַדְמִיתָא כְּתִיב וַיֵּרָא יְיָ אֶל אַבְרָם וּכְתִיב וַיִּסַע אַבְרָם הָלוֹךְ וְנָסוֹעַ הַנֶּגְבָּה וּכְתִיב וַיִּבֶן שָׁם מִזְבֵּחַ הָא הָכָא אִנּוּן דַּרְגִּין עִלָּאִין. וְהַשְׁתָּא אֲמָרָן דְּעַד לָא אִתְגְּזַר לָא הֲווּ אִנּוּן דַּרְגִּין עִלָּאִין שָׁרָאן עַל הַאי דַּרְגָּא לְמַלָּלָא עִמֵּיהּ.","תָּא חֲזֵי, בְּקַדְמִיתָא יַהַב קוּדְשָׁא בְּרִיךְ הוּא חָכְמָה לְאַבְרָהָם לְמִנְדַע חָכְמָה לְאִתְדַּבְּקָא בֵּיהּ וְיָדַע רָזָא דִּמְהֵימְנוּתָא, אֲבָל לְמַלָּלָא עִמֵּיהּ לָא הֲוָה אֶלָּא הַאי דַרְגָּא תַּתָּאָה בִּלְחוֹדוֹי, כֵּיוָן דְּאִתְגְּזַר, כֻּלְהוּ דַּרְגִּין עִלָּאִין הֲווּ שָׁרָאן עַל הַאי דַּרְגָּא תַּתָּאָה בְּגִין לְמַלָּלָא עִמֵּיהּ, וּכְדֵין אִסְתַּלַּק אַבְרָהָם בְּכֹלָּא כְּמָה דְּאִתְּמָר.","תָּא חֲזֵי, עַד לָא אִתְגְּזַר בַּר נָשׁ לָא אִתְאַחִיד בִּשְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא, כֵּיוָן דְּאִתְגְּזַר עָאל בִּשְׁמֵיהּ וְאִתְאַחִיד בֵּיהּ. וְאִי תֵימָא אַבְרָהָם דְּאִתְאַחִיד בֵּיהּ עַד לָא אִתְגְּזַר. הָכִי הֲוָה דְּאִתְאַחִיד בֵּיהּ וְלָא כְּדְקָא יְאוּת, דְּהָא מִגּוֹ רְחִימוּתָא עִלָּאָה דְּרָחִים לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא קָרִיב לֵיהּ.","לְבָתַר פַּקִּיד לֵיהּ דְּיִתְגְּזַר וְאִתְיְיהִיב לֵיהּ בְּרִית. קִשּׁוּרָא, דְּכֻלְהוּ דַרְגִּין עִלָּאִין. בְּרִית קִשּׁוּרָא לְאִתְקַשְּׁרָא כֹּלָּא כְּחֲדָא לְאַכְלָלָא דָּא בְּדָא, בְּרִית קִשּׁוּרָא דְּכֹלָּא אִתְקְשַׁר בֵּיהּ. וּבְגִין כָּךְ אַבְרָהָם עַד לָא אִתְגְּזַר. מִלּוֹי לָא הֲוָה עִמֵּיהּ אֶלָּא בַּמַּחֲזֶה כְּמָה דְּאִתְּמָר.","תָּא חֲזֵי, בְּשַׁעֲתָא דְּבָרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא לָא אִתְבְּרִי אֶלָּא עַל בְּרִית כְּמָא דְאַתְּ אָמֵר בְּרֵ\"א שִׁי\"ת בָּרָא אֱלהִים, וְהַיְינוּ (ד\"א ל\"ג ברית) דְּעַל בְּרִית קִיֵּים קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא, וּכְתִיב, (ירמיהו ל״ג:כ״ה) אִם לא בְרִיתִי יוֹמָם וָלַיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לא שַׂמְתִּי. דְּהָא בְּרִית קִשּׁוּרָא אִיהוּ דְּיוֹמָא וְלֵילְיָא לָא מִתְפָּרְשָׁאן.","אָמַר רַבִּי אֶלְעָזָר כַּד בְּרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא עַל תְּנַאי הֲוָה, דְּכַד יֵיתוּן יִשְׂרָאֵל אִם יְקַבְּלוּן אוֹרַיְיתָא יָאוֹת. וְאִם לָאו הֲרִי אֲנָא אַהֲדַר לְכוּ לְתֹהוּ וָבֹהוּ. וְעָלְמָא לָא אִתְקְיַּים עַד דְּקָיְימוּ יִשְׂרָאֵל עַל טוּרָא דְסִינַי וְקַבִּילוּ אוֹרַיְיתָא וּכְדֵין אִתְקְיַּים עָלְמָא.","וּמֵהַהוּא יוֹמָא וּלְהָלְאָה קוּדְשָׁא בְּרִיךְ הוּא בָּרִי עָלְמִין. וּמָאן אִנּוּן, זִוּוּגִין דִּבְנֵי נָשָׁא. דְּהָא מֵהַהוּא זִמְנָא קוּדְשָׁא בְּרִיךְ הוּא מְזַוֵּוג זִוּוּגִין וְאוֹמֵר בַּת פְּלוֹנִי לִפְלוֹנִי. וְאִלֵּין אִנּוּן עָלְמִין דְּהוּא בָּרֵי. תָּא חֲזֵי, אָנֹכִי מָגֵן לָךְ. אָנֹכִי דָּא הוּא דַּרְגָא קַדְמָאָה דְּאִתְאֲחִיד בֵּיהּ בְּקַדְמִיתָא:","\u0003סִתְרֵי תּוֹרָה\u0004 אַחַר הַדְּבָרִים הָאֵלֶּה וְגו'. אִלֵּין פִּתְּגָּמֵי אוֹרַיְיתָּא, דִּכְתִּיב, (דברים ה׳:י״ט) אֶתּ הַדְּבָרִים הָאֵלֶּה דִּבֶּר יְיָ אֶל כָּל קְהַלְכֶם. מַה לְּהַלָּן פִּתְּגָּמֵי אוֹרַיְיתָּא, אוּף הָכָא פִּתְּגָּמֵי אוֹרַיְיתָּא. בָּתַּר דְּאִשְׁתַּדַּל בַּר נָשׁ בְּהַאי עָלְמָא בַּדְּבָרִים הָאֵלֶּה, קוּדְשָׁא בְּרִיךָ הוּא מְבַשֵׂר לֵיהּ וְאַקְדִּים לָהּ לְנִשְׁמָתָּא שְׁלָם (בשורות טובות), הֲדָא הוּא דִכְתִּיב אַל תִּירָא אַבְרָם אָנֹכִי מָגֵן לָךָ. מִכָּל זַיְינִין בִּישִׁין דְּגֵיהִנֹּם.","שְׂכָרְךָ הַרְבֵּה מְאֹד בְּגִין דְּכָל מַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָּא בְּהַאי עָלְמָא זָכֵי וְאַחְסִין יְרוּתָּא אַחְסַנְתָּא בְּעָלְמָא דְּאָתֵּי כְּמָה דִכְתִּיב (משלי ח׳:כ״א) לְהַנְחִיל אוֹהֲבַי יִשׁ. מאי יֵ\"שׁ (דא י\"ש מאין תלת עשר נהרי דאפרסמונא דכיא (מכילן) דיהבי ליה אחסנתא עלאה בעלמא דאתי) (נ\"א דא עלמא דאתי). וְאוֹצְּרוֹתֵּיהֶם אֲמַלֵּא, בְּהַאי עָלְמָא מֵעוּתְּרָא וּמִכָּל טִיבוּ דְעָלְמָא. מַאן דְּאָזִיל לְיָמִינָא זָכֵי לְעָלְמָא דְאָתֵּי, וּמַאן דְּאָזִיל לִשְׂמָאלָא הָא עוּתְּרָא בְּעָלְמָא דֵין, (דאית שמאלא קדישא ואית שמאלא מסאבא, ודא הוא דאמרינן מאן דמתעסק באורייתא יהבי ליה ארך ימים בעלמא דאתי, ויהבי ליה עשר וכבוד בעלמא דין שנאמר (משלי ג׳:ט״ז) ארך ימים בימינה וגו', ומאן דיתרעי דיתהני גופא בעלמא דין ולא אתעסק באורייתא ובעובדין טבין, יהבי ליה עותרא בעלמא דין מסטרא דשמאלא מסטרא דיצר הרע, ובעותרא דא עביד ביש ירית גיהנם. ואי תימא וכי לא אית בעלמא דין עותרא מסטרא דקדושה, אין, דכל המקיים את התורה מעוני סופו לקיימה מעשר, ודא הוא עותרא טבא דמסטרא דקדושה).","רַבִּי אַבָּא כַּד אֲתָּא מֵהָתָּם, הֲוָה מַכְרִיז מַאן בָּעֵי עוּתְּרָא וּמַאן בָּעֵי אוֹרְכָא דְּחַיֵּי בְּעָלְמָא דְאָתֵּי יֵיתֵּי וְיִשְׁתַּדַּל בְּאוֹרַיְיתָּא. הֲווּ מִתְּכַּנְשִׁין כּוּלֵי עַלְמָא לְגַבֵּיהּ. רַוָּוק חַד הֲוָה בְּשִׁיבְבוּתֵּיהּ. יוֹמָא חַד אֲתָּא לְגַבֵּיהּ, אָמַר לֵיהּ רַבִּי בָּעֵינָא לְמִלְעֵי בְּאוֹרַיְיתָּא כְּדֵי שֶׁיִּהְיֶה לִי עוּתְּרָא. אָמַר לֵיהּ הָא וַדַּאי. אָמַר לֵיהּ מַה שְׁמֶךָ. אָמַר לֵיהּ דְּאָזִיל לְיָמִינָא זָכֵי לְעָלְמָא דְאָתֵּי, וּמַאן דְּאָזִיל לִשְׂמָאלָא הָא עוּתְּרָא בְּעָלְמָא דֵין, (דאית שמאלא קדישא ואית שמאלא מסאבא, ודא הוא דאמרינן מאן דמתעסק באורייתא יהבי ליה ארך ימים בעלמא דאתי, ויהבי ליה עשר וכבוד בעלמא דין שנאמר (משלי ג׳:ט״ז) ארך ימים בימינה וגו', ומאן דיתרעי דיתהני גופא בעלמא דין ולא אתעסק באורייתא ובעובדין טבין, יהבי ליה עותרא בעלמא דין מסטרא דשמאלא מסטרא דיצר הרע, ובעותרא דא עביד ביש ירית גיהנם. ואי תימא וכי לא אית בעלמא דין עותרא מסטרא דקדושה, אין, דכל המקיים את התורה מעוני סופו לקיימה מעשר, ודא הוא עותרא טבא דמסטרא דקדושה). רַבִּי אַבָּא כַּד אֲתָּא מֵהָתָּם, הֲוָה מַכְרִיז מַאן בָּעֵי עוּתְּרָא וּמַאן בָּעֵי אוֹרְכָא דְּחַיֵּי בְּעָלְמָא דְאָתֵּי יֵיתֵּי וְיִשְׁתַּדַּל בְּאוֹרַיְיתָּא. הֲווּ מִתְּכַּנְשִׁין כּוּלֵי עַלְמָא לְגַבֵּיהּ. רַוָּוק חַד הֲוָה בְּשִׁיבְבוּתֵּיהּ. יוֹמָא חַד אֲתָּא לְגַבֵּיהּ, אָמַר לֵיהּ רַבִּי בָּעֵינָא לְמִלְעֵי בְּאוֹרַיְיתָּא כְּדֵי שֶׁיִּהְיֶה לִי עוּתְּרָא. אָמַר לֵיהּ הָא וַדַּאי. אָמַר לֵיהּ מַה שְׁמֶךָ. אָמַר לֵיהּ יוֹסֵי. אָמַר לוֹן לְתַּלְמִידוֹי דְּיִקְרוּן לֵיהּ רַבִּי יוֹסֵי מָארֵי דְּעוּתְּרָא ויקָרָא. יָתִּיב ואִתְּעַסַּק בְּאוֹרַיְיתָּא.","לְיוֹמִין הֲוָה קָאִים קַמֵּיהּ, אָמַר לֵיהּ רַבִּי אָן הוּא עוּתְּרָא. אָמַר שְׁמַע מִינָהּ דְּלָא לְשֵׁם שָׁמַיִם קָא עֲבִיד, וְעָאל לְאִדְרֵיהּ, שְׁמַע חַד קָלָא דְּהֲוָה אָמַר לָא תַּעַנְשֵׁיהּ (תוב לגביה) דְּגַבְרָא רַבָּא לִיהֱוִי. תָּב לְגַבֵּיהּ, אָמַר לֵיהּ תִּיב בְּרִי תִּיב וְאֲנָא יָהִיבְנָא לָךָ עוּתְּרָא.","אַדְהָכִי אֲתָּא גַּבְרָא חַד וּמָאנָא דְּפָּז בִּידֵיהּ, אַפְּקֵיהּ וּנְפַּל נְהוֹרָא בְּבֵיתָּא. אָמַר לֵיהּ רַבִּי בָּעֵינָא לְמִזְכֵּי בְּאוֹרַיְיתָּא וְאֲנָא לָא זָכִינָא, וּבָעֵינָא מָאן דְּיִשְׁתַּדַּל בְּאוֹרַיְיתָּא בְּגִינִי. דְּהָא אִיתּ לִי עוּתְּרָא סַגֵּי דְּקָא שְׁבַק לִי אַבָּא, דְּכַד יָתִּיב על פְּתּוֹרֵיהּ הֲוָה מְסַדַּר עֲלֵיהּ תְּלֵיסַר כַּסֵּי מֵאִלֵּין. וּבָעֵינָא לְמִזְכֵּי בְּאוֹרַיְיתָּא וְאֲנָא יָהִיבְנָא עוּתְּרָא.","אָמַר לֵיהּ לְהַהוּא רַוָּוק תִּשְׁתַּדַּל בְּאוֹרַיְיתָּא וְדָא יָהִיב לָךָ עוּתְּרָא, יָהַב לֵיהּ הַהוּא כַּסָּא דְּפָּז. קָרָא עֲלֵיהּ רַבִּי אַבָּא (איוב כ״ח:י״ז) לא יַעַרְכֶנָּה זָהָב וּזְכוּכִיתּ וּתְּמוּרָתָּהּ כְּלִי פָּז. יָתִּיב וְלָעָא בְּאוֹרַיְיתָּא וְהַהוּא בַּר נָשׁ הֲוָה יָהִיב לֵיהּ עוּתְּרָא.","לְיוֹמִין עָאל חֲמִידוּ דְאוֹרַיְיתָּא בִּמְעוֹי. יוֹמָא חַד הֲוָה יָתִּיב וְהֲוָה בָּכֵי. אַשְׁכְּחֵיהּ רַבֵּיהּ דְּהֲוָה בָּכֵי, אָמַר לֵיהּ עַל מָה קָא בָּכִיתּ. אָמַר לֵיהּ וּמָה מַנַּחְנא חַיֵּי דְעָלְמָא דְאָתֵּי בְּגִין הַאי, לָא בְּעֵינָא אֶלָּא לְמִזְכֵּי לְגַבָּאי. אָמַר הַשְׁתָּא שְׁמַע מִינָהּ דְּהָא לְשֵׁם שָׁמַיִם קָא עֲבִיד.","קָרָא לֵיהּ לְהַהוּא גַבְרָא, אָמַר לֵיהּ טוֹל עוּתְּרָךָ וְהַב לֵיהּ לְיַתְּמֵי וּלְמִסְכְּנִי, וְאֲנָא יָהִיבְנָא לָךָ חוּלַק יַתִּיר בְּאוֹרַיְיתָּא בְּכָל מַה דְּאֲנַן לָעָאן. אַהֲדַר לֵיהּ רַבִּי יוֹסֵי הַהוּא כַּסָּא דְּפָּז, וְעַד יוֹמָא לָא אַעֲדֵי שְׁמֵיהּ, וּמִן בְּנוֹי בֶּן פַּזִּי, וְהַיְינוּ רַבִּי יוֹסֵי בֶּן פַּזִי, וְזָכָה לְכַמָּה אוֹרַיְיתָּא הוּא וּבְנוֹי (בגין דלעא באורייתא). דְּלֵיתּ לָךָ אֲגַר טַב בְּעָלְמָא כְּמָאן דְּלָעֵי בְּאוֹרַיְיתָּא וּמְקַיְימָהּ:","אַחַר הַדְּבָרִים הָאֵלֶּה הָיָה דְּבַר יְיָ אֶל אַבְרָם בַּמַּחֲזֶה לֵאמֹר וְגו', בְּכָל אֲתַּר דִּכְתִּיב בְּאוֹרַיְיתָּא בַּמַּחֲזֶה דָּא שְׁמָא דְּאִתְּגְּלֵי לַאֲבָהָן, וּמָאן אִיהוּ, שַׁדַּ\"י, שֶׁנֶּאֱמַר (שמות ו׳:ג׳) וָאֵרָא אֶל אַבְרָהָם אֶל יִצְּחָק וְאֶל יַעֲקֹב בְּאֵל שַׁדַּי. כְּמָא דְאַתְּ אָמֵר, (במדבר כ״ד:ד׳) אֲשֶׁר מַחֲזֵה שַׁדַי יֶחזֶה. וְדָא אִיהוּ חֵיזוּ דְּכָל חֶזְוָון עִלָּאִין אִתְּחַזְּיָין מִגַּוִּיהּ, כְּהַאי מַרְאֶה דְּכָל דִּיוּקְנִין אִתְּחַזְּיָין בֵּיהּ וכֹלָּא חַד. מַרְאֶה מַחֲזֶה חַד הוּא, דָּא תַּרְגּוּם וְדָא לָשׁוֹן הַקֹּדֶשׁ.","אָמַר רַבִּי יוֹסֵי סַגִּיאִין אִנּוּן בְּאוֹרַיְיתָּא, וְעַל דָּא הֲוָה לֵיהּ רשוּ לְאוּנְקְלוּס לְתַּרְגֵּם בְּהַהוּא לִישְׁנָא דְּגָלֵי קוּדְשָׁא בְּרִיךָ הוּא בְּאוֹרַיְיתָּא. וְלִישְׁנָא דָא סָתִּים אִיהוּ מִגּוֹ מַלְאֲכֵי עִלָאָה, בַּמַּחֲזֶה (דהא) דְּהֲוָה סָתִּים מִמַּלְאֲכֵי עִלָּאֵי דְּלָא יָדְעֵי בְּדָא כַּד מְמַלֵּיל בֵּיהּ בְּאַבְרָהָם.","מַאי טַעְמָא, בְּגִין דְּאַבְרָהָם לָא הֲוָה מָהוּל וְהֲוָה עָרֵל סָתִּים בִּשְׂרָא. וּבְגִין כָּךָ הֲוָה סָתִּים מִנַּיְיהוּ בִּלְשׁוֹן תַּרְגּוּם. כְּגַוְונָא דָא בִּלְעָם דִּכְתִּיב אֲשֶׁר מַחֲזֵה שַׁדַּי יֶחזְהִ, יְחֱזֶה. סָתִּים הֲוָה מִלָּה מִגּוֹ מַלְאֲכֵי הַשָׁרֵתּ בְּגִין דּלא יְהֵא לוֹן פִּטְרָא דְּקוּדְשָׁא בְּרִיךָ הוּא מְמַלֵּל בְּהַהוּא עָרֵל מְסָאֳבָא (עד ב, עה ב) דְּהָא מַלְאֲכֵי קַדִּישֵׁי לָאו (יקרון) נִזְקָקִין בִּלְּשׁוֹן תַּרְגּוּם.","אִי תֵּימָא דלא יָדְעֵי, וְהָא גַּבְרִיאֵל אוֹלִיף לְיוֹסֵף ע' לָשׁוֹן, ותַּרְגּוּם חַד מֵע' לָשׁוֹן הוּא, אֶלָּא מִנְדַע יָדְעֵי אֲבָל לָא נִזְקָקִין תְּנַן, דְּלָא חַיְישֵׁי ולא מַשְׁגִּיחִין עֲלֵיהּ דְּהָא מָאִיס אִיהוּ קַמַּיְיהוּ מִכָּל שְׁאָר לָשׁוֹן.","וְאִי תֵּימָא הוֹאִיל וּמָאִיס אִיהוּ מִמַּלְאֲכֵי עִלָּאֵי, אַמַּאי תִּרְגֵּם אוּנְקְלוּס אוֹרַיְיתָּא בְּהַאי לָשׁוֹן, וְיוֹנָתָּן בֶּן עוּזִיאֵל הַמִּקְרָא. אֶלָּא מָאִיס הוּא קַמַּיְיהוּ והָכִי אִצְּטְרִיךָ, דְּלֵיתּ קִנְאָה לְמַלְאֲכֵי עִלָּאֵי בַּהֲדַיְיהוּ דְיִשְׂרָאֵל (אלא אורייתא, ואלמלא הוו ידעי שבחי דאורייתא הוה להו קנאה בהדייהו דישראל) יַתִּיר, וְעַל דָּא תַּרְגּוּם תּוֹרָה וּמִקְרָא כָּךָ, ולא מָאִיס אִיהוּ דְּהָא בְּכַמָּה דוּכְתֵּי כָּתַּב קוּדְשָׁא בְּרִיךָ הוּא בְּאוֹרַיְיתָּא הָכִי.","וּבְגִין כָּךָ סָתִּים אִיהוּ מִגּוֹ מַלְאֲכֵי עִלָּאֵי קַדִּישֵׁי. וְעַל דָּא אִתְּגְּלִי בֵּיהּ בְּאַבְרָהָם בְּאוֹרַח סָתִּים דְּלָא יִשְׁגְּחוּן בֵּיהּ מַלְאָכִין קַדִּישִׁין וְלָא יְהֵא לוֹן פִּטְרָא, דְּקוּדְשָׁא בְּרִיךָ הוּא אִתְּגְּלִי עַל בַּר נָשׁ עָרֵל.","אֵימָתַּי אִתְּגְּלִי לֵיהּ בְּאִתְּגַּלְּיָא דְּמַלְאֲכֵי עִלָּאֵי, כַּד יָהִיב לֵיהּ בְּרִיתּ קְיָימָא קַדִּישָׁא דִּכְתִּיב וַיְדַבֵּר אִתּוֹ אֱלהִים לֵאמֹר, אֱלהִים שְׁמָא דְקוּדְשָׁא ולא כְּתִּיב בַּמַּחֲזֶה. שְׁמָא בְּאִתְּגַּלְּיָיא.","לֵאמֹר מַאי לֵאמֹר, לֵאמֹר וּלְאַכְרָזָא בְּכָל לָשׁוֹן דְּלָא תְּהֵא בְּאִתְּכַּסְיָא, לָאו בְּלִישְׁנָא אָחֳרָא, אֶלָּא בְּלִישְׁנָא דְּכלָּא מִשְׁתָּעְיָין בָּהּ דְּיָכְלֵי לְמֵימַר דָּא לְדָא וְלָא יָכְלֵי לְקַטְרְגָא וּלְמֵימַר פִּטְרָא, וְעַל דָּא וַיְדַבֵּר אִתּוֹ אֱלהִים לֵאמֹר. אֱלהִים וְלא מַחֲזְה. בְּגִין דְּהֲוָה מְעֲיִּיל לֵיהּ בִּבְרִיתּ קְיָימָא קַדִּישָׁא וְקָרִיב לֵיהּ לְגַבֵּיהּ.","רַבִּי יְהוּדָה אָמַר בְגִין כָּךָ אָתּ ה' לָא אִתְּיְיהַב לֵיהּ עַד דְּאִתְּגַּזַּר, מַאי טַעְמָא דְּאִיהִי מַמָּשׁ בְּרִיתּ אִקְרֵי. וְעַל דָּא כֵּיוָן דְּעָאל בִּבְרִיתּ כְּדֵין אִתְּיְיהִיבַתּ לֵיהּ אָתּ ה\"א. דִּכְתִּיב אֲנִי הִנֵּה בְּרִיתִּי אִתָּךָ וְהָיִיתָּ לְאַב הֲמוֹן גּוֹיִם ולא יִקָרֵא עוֹד שִׁמְךָ אַבְרָם וְגו':","אַחַר הַדְּבָרִים הָאֵלֶּה. רַבִּי חִיָּיא הֲוָה אָזִיל לְמֶחֱמֵי לְרַבִּי אֶלְעָזָר, פְּגַע בֵּיהּ רַבִּי חַגַּאי, אָמַר לֵיהּ הַאי אָרְחָא דִּמְתַּקְנא קַמֵּיהּ דְּמַר לְאָן אִיהוּ אָזִיל, אָמַר לֵיהּ לְמֶחֱמֵי לְרַבִּי אֶלְעָזָר, אָמַר לֵיהּ וְאֲנָא נָמֵי אֵיזִיל בַּהֲדָךָ, אָמַר לֵיהּ אִי תֵּיכוּל לְמִסְבַּר סְבָרָא לְמַאי דְתִּשְׁמַע זִיל וְאִי לָאו תּוּב אֲבַתְּרָךָ, אָמַר לֵיהּ לא לִיחוּשׁ מַר לְהַאי, דְּהָא אֲנָא שְׁמַעְנא כַּמָּה רָזֵי דְאוֹרַיְיתָּא וְיָכִילְנָא לְמֵיקַם בְּהוּ.","פָּתַּח רַבִּי חַגַּאי וְאָמַר, מַאי דִכְתִּיב, (במדבר כ״ח:ב׳) אֶתּ קָרְבָּנִי לַחְמִי לְאִשַׁי וְגו'. אֶתּ קָרְבָּנִי דָּא קָרְבַּן בִּשְׂרָא דְּאִתְּקְרַב לְכַפָּרָא דָּמָא על דָּמָא בִּשְׂרָא עַל בִּשְׂרָא, בְּגִין דְּכָל קָרְבָּנִין לָאו מִתְּקָרְבִין אֶלָּא עַל בִּשְׂרָא לְכַפָּרָא על בִּשְׂרָא."],[[0,"ואי תימא דהא וכו':","ואם תאמר, הרי כבר כתוב וירא ה' אל אברם שהיא מדרגת הנפש. וכתוב ויסע אברם הלוך ונסוע הנגבה, שהוא רוח. וכתוב ויבן שם מזבח, שהוא נשמה (כנ\"ל דף ס\"א אות ק\"ס) הרי כאן מדרגות העליונות שהשיג, ואיך נאמר שמטרם שנמול, לא היו מדרגות העליונות שורות על אותה המדרגה לדבר עמו."],[1,"ת\"ח בקדמיתא וכו':","ומשיב. בוא וראה, מתחילה, מטרם שנמול, נתן הקב\"ה חכמה לאברהם, דהיינו המדרגות העליונות הנ\"ל. לדעת חכמה ולהתדבק בהקב\"ה, והשיג סוד האמונה. אבל לדבר עמו לא היה לו, אלא מדרגה התחתונה לבדה, דהיינו הנוקבא מבחינת מחזה שדי יחזה, כנ\"ל. כיון שנמול, כל מדרגות העליונות היו שורות על מדרגה זו התחתונה, כדי לדבר עמו. ואז נתעלה אברהם בכל המדרגות כמו שנתבאר."],[2,"ת\"ח עד לא וכו':","בוא וראה, כל עוד שלא נמול האדם, אינו נאחז בשם הקב\"ה. כיון שנמול, נכנס בשמו ונאחז בו. ואם תאמר, הרי אברהם, שנאחז בו מטרם שנמול. ומשיב כן הוא, שנאחז בו, אבל לא כראוי להיות. כי מתוך אהבה עליונה שאהב אותו הקב\"ה, קרבהו אליו. ועכ\"ז לא היה כראוי."],[3,"לבתר פקיד וכו':","אחר כך, צוה אותו הקב\"ה למול, וניתן לו \u0003הברית\u0004 שהוא יסוד הוא הקשר של כל מדרגות העליונות. \u0003ברית,\u0004 הוא קשר. שיהיו נקשרות כולן יחד, לכללם זו בזו. \u0003ברית\u0004 הוא קשר, שהכל נקשר בו. ומשום זה, מטרם שנמול אברהם, לא היו דיבוריו עמו אלא במחזה. כמו שאמרנו. שהיה חסר בה מדרגות העליונות, כי היה חסר הברית שהוא המקשר כל המדרגות יחד."],[4,"ת\"ח בשעתא וכו':","בוא וראה, בשעה שהקב\"ה ברא את העולם, לא ברא אותו אלא על ברית. כמו שאתה אומר ברא-שית ברא אלקים. \u0003ושית\u0004 היינו ברית. כי על ברית ברא הקב\"ה את העולם. וכתוב, אם לא בריתי יומם ולילה חוקות שמים וארץ לא שמתי, כי ברית קשר הוא, שיום ולילה, שהם ז\"א ונוקבא, לא יפרדו. (וביאור הענין עי' לעיל בראשית א' דף רפ\"ה ד\"ה וזה)."],[5,"אמר ר' אלעזר וכו':","אר\"א, כשברא הקב\"ה את העולם, היה על תנאי, שאם יבואו ישראל ויקבלו את התורה תתקיימו ואם לא, הריני מחזיר אתכם לתהו ובהו. והעולם לא נתקיים עד שעמדו ישראל על הר סיני, וקבלו התורה, ואז נתקיים העולם."],[6,"ומההוא יומא ולהלאה וכו':","ומיום ההוא ואילך, הקב\"ה בורא עולמות. ומי המה. הם הזווגים של בני אדם. כי מזמן ההוא, הקב\"ה מזווג זווגים, ואומר בת פלוני לפלוני ואלו הם העולמות שהוא בורא. כי כל זווג נבחן לעולם."],[7,"אחר הדברים האלה וגו':","הדברים האלה הם דברי תורה. שכתוב את הדברים האלה וגו' מה שם הם דברי תורה אף כאן הם דברי תורה. ושיעור הכתוב \u0003אחר,\u0004 שעסק האדם בעולם הזה \u0003בדברים האלה,\u0004 הקב\"ה מבשר את הנשמה ומקדים לה שלום. וזהו שכתוב, אל תירא אברם אנכי מגן לך, אגן עליך מכל בחינות הרעות שבגיהנם."],[8,"שברך הרבה מאד:","משום, שכל מי העוסק בתורה בעולם הזה. זוכה ויורש ירושה ונחלה בעולם הבא. כמ\"ש להנחיל אוהבי יש. ושואל מהו יש, ואומר זהו עולם הבא. \u0003ואוצרותיהם אמלא.\u0004 בעולם הזה מעושר ומכל טוב שבעולם. מי שהולך לימין זוכה לעולם הבא. ומי שהולך לשמאל זוכה לעשירות בעולם הזה."],[9,"ר' אבא כד אתא וכו':","ר\"א כאשר בא משם, מבבל, היה מכריז, מי רוצה עושר ומי רוצה אריכות ימים בעולם הבא, ילך ויעסוק בתורה, היו מתאספים אליו כל העולם לעסוק בתורה."],[9,"רווק חד וכו':","איש אחד פנוי מאשה, היה בשכונתו. יום אחד בא אליו, ואמר לו: רבי, אני רוצה ללמוד תורה, כדי שיהיה לי עשירות. אמר לו ר' אבא, הנה ודאי, שתזכה על ידי התורה לעשירות אמר לו מה שמך. אמר לו יוסי. אמר לתלמידיו שיקראו אותו, יוסי בעל העשירות והכבוד. והיה יושב ועוסק בתורה."],[10,"ליומין הוה קאים וכו':","לימים, כשהיה עומד לפניו, אמר לו: רבי, אנה הוא העושר. אמר, ר' אבא, משמע, שאינו עושה לשם שמים. ונכנס לחדרו, להתישב בדעתו מה לעשות עמו. שמע קול אחד שהיה אומר, אל תענישו, כי אדם גדול יהיה. חזר אליו, אמר לו שב בני שב, ואני אתן לך עשירות."],[11,"אדהכי אתא וכו':","בינתים, בא, איש אחד ובידו כלי פז. הוציאו לעינים והבריק אורו בבית. אמר לו רבי, אני רוצה לזכות בתורה. ואני בעצמי לא זכיתי להבין בתורה, ואני מבקש, מי שיעסוק בתורה בשבילי. כי יש לי עושר רב שהניח לי אבי שבעת שישב על שלחנו היה מסדר עליו שלשה עשר כוסות מאלו, דהיינו מפז. ואני רוצה לזכות במצות לימוד התורה, ואני נותן בעד זה עושר."],[12,"א\"ל לההוא רווק וכו':","אמר לאותו איש הפנוי מאשה, עסוק בתורה, ואיש הזה יתן לך עושר, נתן לו האיש אותו הכוס של פז. קרא עליו ר' אבא, לא יערכנה זהב וזכוכית ותמורתה כלי פז. ישב ועסק בתורה, ואותו האיש היה נותן לו עושר."],[13,"ליומין עאל חמידו וכו':","לימים, נכנסה חמדת התורה במעיו. יום אחד היה יושב ובוכה. מצאו רבו שהיה בוכה. אמר לו, על מה אתה בוכה. והשיב לו. ומה אני מניח בשביל זה העושר, את חיי עולם הבא. איני רוצה ללמוד עוד בשביל האיש, אלא לזכות בתורה בעד עצמי. אמר ר' אבא, עתה משמע, שכבר עושה לשם שמים."],[14,"קרא ליה וכו':","קרא לאותו האיש ואמר לו קח העושר שלך, ותן אותו ליתומים ועניים, ואני אתן לך חלק גדול יותר בתורה, בכל מה שאנו לומדים. החזיר לו ר' יוסי את הכוס של פז. ועד היום הזה לא ניטל השם בן פזי ממנו ומבניו. והיינו ר' יוסי בן פזי המפורסם. וזכה להרבה תורה הוא ובניו, כי אין לך שכר טוב יותר בעולם, כמי שעוסק בתורה. ואין צריכים לתמורה בעדה. כמ\"ש לא יערכנה זהב וזכוכית ותמורתה כלי פז."],[15,"אחר הדברים האלה וכו':","בכל מקום שכתוב \u0003במחזה,\u0004 בתורה, הוא השם שנגלה לאבות, ומי הוא, הוא \u0003שדי.\u0004 שנאמר וארא אל אברהם וגו' באל \u0003שדי.\u0004 וכמו שאתה אומר, אשר מחזה \u0003שדי\u0004 יחזה. וזה הוא מראה, אשר כל מראות העליונות נראות מתוכה. כמו מראה של זכוכית, שכל הצורות נראות בה. והכל אחד \u0003מראה ומחזה,\u0004 ואחד הם, אלא שזה תרגום וזה לשון הקודש."],[16,"א\"ר יוסי סגיאין וכו':","אר\"י הרבה מלות ארמיות הן בהתורה. ועל כן היה רשות לאונקלוס לתרגם התורה באותו לשון שגילה הקב\"ה בתורה. ולשון זה סתום הוא ממלאכי עליון, ולא הכירו בה כאשר דבר הקב\"ה עם אברהם."],[17,"מאי טעמא, בגין וכו':","ושואל, מהו הטעם, שהקב\"ה דבר עם אברהם בלשון שלא יכירו בו המלאכים. ומשיב, לפי שאברהם לא היה מהול, והיה ערל אטום בשר, ומשום זה היה הדיבור בלשון תרגום הסתום מהם מהמלאכים. כמו זה, בבלעם. שכתוב בו, אשר מחזה שדי יחזה. \u0003יחזה,\u0004 מלה זו היתה סתומה ממלאכי השרת, שהוא לשון ארמית, כדי שלא יהיה להם פתחון פה, שהקב\"ה מדבר עם אותו ערל הטמא, כי מלאכים הקדושים אינם נזקקים ללשון תרגום. ועל כן לא ידעו שהקב\"ה דבר עם בלעם."],[18,"אי תימא דלא ידעי וכו':","ושואל אם תאמר, שהמלאכים שאינם יודעים לשון תרגום. הרי גבריאל למד את יוסף ע' לשון, ותרגום הוא אחד מע' לשון. ומשיב, אלא שהם יודעים אבל לא \u0003נזקקין\u0004 תנן, שפירושו, שאינם חוששים לו ואינם משגיחים עליו, כי לשון זה נמאס להם מכל הלשונות."],[19,"ואי תימא הואיל וכו':","ואם תאמר, אם נמאס הוא ממלאכי עליון, למה תרגם אונקלוס את התורה באותו הלשון, ויונתן בן עוזיאל את המקרא. ומשיב, אלא רק להם הוא נמאס, וכן נצרך להיות, כדי שמלאכים העליונים לא יקנאו את ישראל. באמרם קדושה דסדרא וכדומה, (כמ\"ש בזהר תרומה דף כ' אות נ\"ב) אבל לנו אינו נמאס, ועל כן תרגמו התורה והמקרא בלשון זה, ואינו נמאס, שהרי בכמה מקומות כתב הקב\"ה בתורה מלשון הזה."],[20,"ובג\"כ סתים איהו וכו':","ומשום זה שהוא סתום ממלאכים העליונים הקדושים, על כן נגלה לאברהם בדרך זה הסתום, כדי שלא יסתכלו בו מלאכים הקדושים, ולא יהיה להם פתחון פה לקטרג, שהקב\"ה נגלה על אדם ערל."],[21,"אימתי אתגלי וכו':","שואל, מתי נגלה לו בגלוי לפני מלאכים העליונים. ואומר, הוא כאשר נתן לו אות ברית הקדוש. שכתוב אז, וידבר אתו אלקים לאמור, \u0003אלקים\u0004 שהוא שם קדוש, ולא כתוב \u0003במחזה,\u0004 אלא שם באתגליא שהוא אלקים."],[22,"לאמר מאי לאמר וכו':","ושואל, \u0003לאמר,\u0004 מהו לאמר, ומשיב \u0003לאמר\u0004 פירושו לומר ולהכריז בכל לשון, שהקב\"ה דבר עם אברהם, שלא יהיה עוד בהעלם מהמלאכים ולא בלשון אחר שהוא תרגום, אלא בלשון שהכל מדברים בה, שיוכלו לספר זה לזה, ולא יוכלו לקטרג ולומר ולפתוח פה. ועל כן וידבר אתו אלקים לאמור, \u0003אלקים\u0004 ולא \u0003מחזה,\u0004 משום שהיה מכניסו באות ברית קדש, וקרבהו אליו."],[23,"ר' יהודה אמר וכו':","רי\"א לפיכך לא ניתן לו אות \u0003ה'\u0004 שהיא השכינה, עד שנמול. מהו הטעם, משום שהיא נקראת ברית ממש. ועל כן כיון שנכנס בברית, ניתן לו אז אות ה' בשמו. שכתוב, אני הנה בריתי אתך, והיית לאב המון גוים ולא יקרא עוד שמך אברם וגו':"],[24,"אחר הדברים האלה וכו':","ר' חייא הלך לראות את ר' אלעזר. פגע בו ר' חגאי. אמר לו, דרך זה המתוקן לפני אדוני, לאן הוא הולך. אמר לו שהולך לראות את ר' אלעזר. אמר לו גם אני אלך אתך. אמר לו אם תוכל להבין השכל והטעם ממה שתשמע, לך, ואם לא, חזור לאחריך. אמר לו, אל ידאג אדוני לזה, כי שמעתי כמה סודות התורה ויכולתי לעמוד בהם."],[25,"פתח ר' חגאי וכו':","פתח ר\"ח ואמר. מה שכתוב, את קרבני לחמי לאשי וגו'. את קרבני, זהו קרבן בשר הנקרב לכפר דם הקרבן על דם האדם בשר הקרבן על בשר האדם. משום שכל הקרבנות אינם נקרבים אלא על בשר, דהיינו לכפר על בשר."]],[[0,"","וְאִם תֹּאמַר שֶׁהִנֵּה בַּתְּחִלָּה כָּתוּב וַיֵּרָא ה' אֶל אַבְרָם, וְכָתוּב וַיִּסַּע אַבְרָם הָלוֹךְ וְנָסוֹעַ הַנֶּגְבָּה, וְכָתוּב וַיִּבֶן שָׁם מִזְבֵּחַ. הִנֵּה כָּאן אוֹתָן הַדְּרָגוֹת הָעֶלְיוֹנוֹת. וְכָעֵת אוֹמְרִים, שֶׁטֶּרֶם שֶׁנִּמּוֹל לֹא הָיָה אוֹתָן הַדְּרָגוֹת הָעֶלְיוֹנוֹת שׁוֹרוֹת עַל הַדַּרְגָּה הַזּוֹ לְדַבֵּר עִמּוֹ?"],[1,"","בֹּא רְאֵה, בַּתְּחִלָּה נָתַן הַקָּדוֹשׁ בָּרוּךְ הוּא חָכְמָה לְאַבְרָהָם לָדַעַת אֶת הַחָכְמָה לְהִדָּבֵק בּוֹ, וְיָדַע אֶת סוֹד הָאֱמוּנָה, אֲבָל לְדַבֵּר עִמּוֹ לֹא הָיְתָה אֶלָּא הַדַּרְגָּה הַתַּחְתּוֹנָה הַזּוֹ לְבַדָּהּ. כֵּיוָן שֶׁנִּמּוֹל, כָּל הַדְּרָגוֹת הָעֶלְיוֹנוֹת הָיוּ שׁוֹרוֹת עַל הַדַּרְגָּה הַזּוֹ הַתַּחְתּוֹנָה כְּדֵי לְדַבֵּר עִמּוֹ, וְאָז הִתְעַלָּה אַבְרָהָם בַּכֹּל, כְּמוֹ שֶׁנִּתְבָּאֵר."],[2,"","בֹּא רְאֵה, טֶרֶם שֶׁנִּמּוֹל הָאָדָם, לֹא נֶאֱחַז בִּשְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. כֵּיוָן שֶׁנִּמּוֹל, נִכְנַס בִּשְׁמוֹ וְנֶאֱחַז בּוֹ. וְאִם תֹּאמַר, אַבְרָהָם שֶׁנֶּאֱחַז בּוֹ טֶרֶם שֶׁנִּמּוֹל? כָּךְ הָיָה, שֶׁנֶּאֱחַז בּוֹ וְלֹא כָּרָאוּי, שֶׁהֲרֵי מִתּוֹךְ הָאַהֲבָה הָעֶלְיוֹנָה שֶׁאָהַב אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא קֵרַב אוֹתוֹ,"],[3,"","אַחַר כָּךְ צִוָּה אוֹתוֹ שֶׁיִּמּוֹל וְנִתְּנָה לוֹ הַבְּרִית, הַקֶּשֶׁר שֶׁל כָּל הַדְּרָגוֹת הָעֶלְיוֹנוֹת. הַבְּרִית - הַקֶּשֶׁר לְקַשֵּׁר הַכֹּל יַחַד לְהַכְלִיל זֶה עִם זֶה. הַבְּרִית - הַקֶּשֶׁר שֶׁהַכֹּל נִקְשָׁר בּוֹ. וּמִשּׁוּם כָּךְ, טֶרֶם שֶׁנִּמּוֹל אַבְרָהָם, דִּבּוּרוֹ לֹא הָיָה עִמּוֹ אֶלָּא בְּמַחֲזֶה, כְּמוֹ שֶׁנִּתְבָּאֵר."],[4,"","בֹּא רְאֵה, בְּשָׁעָה שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, לֹא נִבְרָא אֶלָּא עַל הַבְּרִית, כְּמוֹ שֶׁנֶּאֱמַר בָּרָ\"א שִׁי\"ת, בָּרָא אֱלֹהִים. וְהַיְנוּ (ברית) שֶׁעַל הַבְּרִית קִיֵּם הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, וְכָתוּב (ירמיה לג) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי. שֶׁהֲרֵי הַבְּרִית הִיא הַקֶּשֶׁר שֶׁהַיּוֹם וְהַלַּיְלָה לֹא נִפְרָדִים."],[5,"","אָמַר רַבִּי אֶלְעָזָר, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, עַל תְּנַאי הָיָה: שֶׁכַּאֲשֶׁר יָבֹאוּ יִשְׂרָאֵל, אִם יְקַבְּלוּ אֶת הַתּוֹרָה - יָפֶה, וְאִם לֹא - הֲרֵינִי מַחֲזִירְכֶם לְתֹהוּ וָבהוּ. וְהָעוֹלָם לֹא הִתְקַיֵּם עַד שֶׁעָמְדוּ יִשְׂרָאֵל עַל הַר סִינַי וְקִבְּלוּ תוֹרָה, וְאָז הִתְקַיֵּם הָעוֹלָם."],[6,"","וּמֵאוֹתוֹ הַיּוֹם וָהָלְאָה, הַקָּדוֹשׁ בָּרוּךְ הוּא בּוֹרֵא עוֹלָמוֹת, וּמִי הֵם? זִוּוּגֵי בְּנֵי הָאָדָם. שֶׁהֲרֵי מֵאוֹתוֹ הַזְּמַן הַקָּדוֹשׁ בָּרוּךְ הוּא מְזַוֵּג זִוּוּגִים וְאוֹמֵר: בַּת פְּלוֹנִי לִפְלוֹנִי. וְאֵלּוּ הֵם הָעוֹלָמוֹת שֶׁהוּא בוֹרֵא. בּא רְאֵה, אָנֹכִי מָגֵן לָךְ, אָנֹכִי - זוֹ הִיא הַדַּרְגָּה הָרִאשׁוֹנָה שֶׁנֶּאֱחַז בָּהּ בַּתְּחִלָּה."],[7,"","אַחַר הַדְּבָרִים הָאֵלֶּה וְגוֹ' - אֵלּוּ דִּבְרֵי תוֹרָה, שֶׁכָּתוּב (דברים ה) אֶת הַדְּבָרִים הָאֵלֶּה דִּבֶּר ה' אֶל כָּל קְהַלְכֶם. מַה לְּהַלָּן דִּבְרֵי תוֹרָה - אַף כָּאן דִּבְרֵי תוֹרָה. אַחַר שֶׁהִשְׁתַּדֵּל אָדָם בָּעוֹלָם הַזֶּה בַּדְּבָרִים הָאֵלֶּה, הַקָּדוֹשׁ בָּרוּךְ הוּא מְבַשֵּׂר לוֹ וּמַקְדִּים לַנְּשָׁמָה שָׁלוֹם (בשורות טובות), זֶהוּ שֶׁכָּתוּב אַל תִּירָא אַבְרָם אָנֹכִי מָגֵן לָךְ, מִכָּל הַמִּינִים הָרָעִים שֶׁל הַגֵּיהִנֹּם."],[8,"","שְׂכָרְךָ הַרְבֵּה מְאֹד, מִשּׁוּם שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה בָּעוֹלָם הַזֶּה, זוֹכֶה וְנוֹחֵל יְרֻשַּׁת נַחֲלָה בָּעוֹלָם הַבָּא, כַּכָּתוּב (משלי ח) לְהַנְחִיל אֹהֲבַי יֵשׁ. מַה זֶּה יֵ\"שׁ? (זה י\"ש מאין שלש עשרה נהרות אפרסמון טהור (מדּות) שנותנים לו ירשה עליונה בעולם הבא (נ\"א: זה הָעולָם הבָּא). ואצרתיהם אמלא - בעולם הזה, מעשר וכל טוב של העולם.) מי שהולך לימין - זוכה לעולם הבא, ומי שהולך לשמאל - הנה עשר בעולם הזה (שיש שמאל קדוש ויש שמאל טמא, וזה הוא שאמרנו, מי שמתעסק בתורה, נותנים לו ארך ימים בעולם הבא ונותנים לו עשר וכבוד בעולם הזה, שנאמר (משלי ג) ארך ימים בימינה וגו', ומי שירצה שיהנה הגוף בעולם הזה ולא מתעסק בתורה ובמעשים טובים, נותנים לו עשר בעולם הזה מצד השמאל, מצד היצר הרע, ובעשר הזה עושה רע ויורש גיהנם, ואם תאמר, וכי אין בעולם הזה עשר מצד הקדשה? כן, שכל המקים את התורה מעני, סופו לקימה מעשר, וזהו עשר טוב שמצד הקדשה)."],[9,"","כשבא משם רבי אבא, היה מכריז: מי רוצה עשר ומי רוצה ארך חיים בעולם הבא, יבא וישתדל בתורה. היו מתכנסים אליו כל העולם. היה רוק אחד בשכונתו. יום אחד בא אליו. אמר לו: רבי, אני רוצה לעסק בתורה כדי שיהיה לי עשר. אמר לו: הנה ודאי. אמר לו: מה שמך? אמר לו: יוסי. אמר לתלמידיו שיקראו לו רבי יוסי בעל העשר והכבוד. ישב והתעסק בתורה."],[10,"","לימים היה עומד לפניו. אמר לו: רבי, איפה העשר? אמר: נשמע מזה שלא עשה לשם שמים. נכנס לחדרו, שמע קול אחד שהיה אומר: אל תעניש אותו (שוב אליו), שיהיה איש גדול. שב אליו. אמר לו: שב, בני, שב, ואני נותן לך עשר."],[11,"","בינתים בא איש אחד וכלי של פז בידו. הוציא אותו ונפל אור בבית. אמר לו: רבי, אני רוצה לזכות בתורה ואני לא זכיתי, ורוצה מי שישתדל בתורה בשבילי, שהרי יש לי עשר רב שהשאיר לי אבי, שכאשר ישב על שלחנו היה מסדר עליו שלשה עשר כוסות מאלו, ואני רוצה לזכות בתורה ואני נותן עשר."],[12,"","אמר לאותו הרוק: תשתדל בתורה, וזה נותן לך עשר. נתן לו אותו הכוס של הפז. קרא עליו רבי אבא: (איוב כח) לא יערכנה זהב וזכוכית ותמורתה כלי פז. ישב ולמד בתורה, והאדם ההוא היה נותן לו עשר."],[13,"","לימים נכנסה חמדת התורה למעיו. יום אחד היה יושב והיה בוכה. מצא אותו רבו שהיה בוכה. אמר לו: על מה אתה בוכה? אמר לו: ומה אני מניח את חיי העולם הבא בשביל זה? איני רוצה אלא לזכות אצלי. אמר: עכשו מזה נשמע שהנה עשה לשם שמים."],[14,"","קָרָא לְאוֹתוֹ הָאִישׁ, אָמַר לוֹ: טֹל אֶת עָשְׁרְךְ וְתֵן אוֹתוֹ לִיתוֹמִים וַעֲנִיִּים, וַאֲנִי נוֹתֵן לְךְ חֵלֶק יָתֵר בַּתּוֹרָה בְּכָל מַה שֶּׁאֲנִי לוֹמֵד. הֶחֱזִיר לוֹ רַבִּי יוֹסֵי אוֹתוֹ הַכּוֹס שֶׁל פָּז, וְעַד הַיּוֹם לֹא סָר שְׁמוֹ, וּמִבָּנָיו בֶּן פָּזִי, וְהַיְנוּ רַבִּי יוֹסֵי בֶּן פָּזִי, וְזָכָה לְכַמָּה תוֹרָה הוּא וּבָנָיו (משום שלמד תורה). שֶׁאֵין לְךְ שָׂכָר טוֹב בָּעוֹלָם כְּמִי שֶׁלּוֹמֵד תּוֹרָה וּמְקַיֵּם אוֹתָהּ."],[15,"","אַחַר הַדְּבָרִים הָאֵלֶּה הָיָה דְבַר ה' אֶל אַבְרָם בַּמַּחֲזֶה לֵאמֹר וְגוֹ'. בְּכָל מָקוֹם שֶׁכָּתוּב בַּתּוֹרָה בַּמַּחֲזֶה, זֶה הַשֵּׁם שֶׁהִתְגַּלָּה לָאָבוֹת, וּמִי הוּא? שַׁדַּ\"י, שֶׁנֶּאֱמַר (שמות ו) וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב בְּאֵל שַׁדַּי, כְּמוֹ שֶׁנֶּאֱמַר (במדבר כד) אֲשֶׁר מַחֲזֵה שַׁדַּי יֶחֱזֶה. וְזֶה הַמַּרְאֶה שֶׁכָּל הַמַּרְאוֹת הָעֶלְיוֹנוֹת נִרְאִים מִתּוֹכוֹ. כְּמוֹ הַמַּרְאֶה הַזֶּה שֶׁכָּל הַדְּמֻיּוֹת נִרְאוֹת בּוֹ וְהַכֹּל אֶחָד. מַרְאֶה וּמַחֲזֶה הוּא אֶחָד. זֶה תַרְגּוּם וְזֶה לְשׁוֹן הַקֹּדֶשׁ."],[16,"","אָמַר רַבִּי יוֹסֵי, רַבִּים הֵם בַּתּוֹרָה, וְעַל כֵּן הָיְתָה רְשׁוּת לְאוּנְקְלוּס לְתַרְגֵּם בְּאוֹתָהּ הַלָּשׁוֹן שֶׁגִּלָּה הַקָּדוֹשׁ בָּרוּךְ הוּא בַּתּוֹרָה, וְהַלָּשׁוֹן הַזּוֹ הִיא נִסְתֶּרֶת מֵהַמַּלְאָכִים הָעֶלְיוֹנִים. בַּמַּחֲזֶה, (שהנה) שֶׁהָיָה נִסְתָּר מֵהַמַּלְאָכִים הָעֶלְיוֹנִים שֶׁאֵינָם יוֹדְעִים בָּזֶה כְּשֶׁמְּדַבֵּר עִם אַבְרָהָם."],[17,"","מָה הַטַּעַם? מִשּׁוּם שֶׁאַבְרָהָם לֹא הָיָה מָהוּל, וְהָיָה עָרֵל סְתוּם בָּשָׂר, וּמִשּׁוּם כָּךְ הָיָה מַסְתִּיר מֵהֶם בִּלְשׁוֹן תַּרְגּוּם. כְּמוֹ כֵן בְּבִלְעָם, שֶׁכָּתוּב אֲשֶׁר מַחֲזֵה שַׁדַּי יֶחֱזֶה. יֶחֱזֶה, נִסְתָּר הָיָה הַדָּבָר מִתּוֹךְ מַלְאֲכֵי הַשָּׁרֵת כְּדֵי שֶׁלֹּא יִהְיֶה לָהֶם פִּתְחוֹן פֶּה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְדַבֵּר עִם אוֹתוֹ הֶעָרֵל הַטָּמֵא, שֶׁהֲרֵי הַמַּלְאָכִים הַקְּדוֹשִׁים אֵינָם (קוראים) נִזְקָקִים לִלְשׁוֹן תַּרְגּוּם."],[18,"","אִם תֹּאמַר שֶׁלֹּא יוֹדְעִים - וַהֲרֵי גַבְרִיאֵל לִמֵּד אֶת יוֹסֵף שִׁבְעִים לָשׁוֹן, וְהַתַּרְגּוּם הוּא אֶחָד מִשִּׁבְעִים לָשׁוֹן? אֶלָּא יָדוֹעַ יוֹדְעִים, אֲבָל שָׁנִינוּ שֶׁלֹּא נִזְקָקִים, שֶׁאֵין חוֹשְׁשִׁים וְאֵין מִתְבּוֹנְנִים עָלָיו, שֶׁהֲרֵי הוּא מָאוּס לִפְנֵיהֶם מִכָּל שְׁאָר הַלְּשׁוֹנוֹת."],[19,"","וְאִם תֹּאמַר, שֶׁהוֹאִיל וְהוּא מָאוּס מִן הַמַּלְאָכִים הָעֶלְיוֹנִים, לָמָּה תִרְגֵּם אוּנְקְלוּס אֶת הַתּוֹרָה בַּלָּשׁוֹן הַזּוֹ, וְיוֹנָתָן בֶּן עֻזִּיאֵל אֶת הַמִּקְרָא? אֶלָּא מָאוּס הוּא לִפְנֵיהֶם, וְכָךְ צָרִיךְ! שֶׁאֵין קִנְאָה לַמַּלְאָכִים הָעֶלְיוֹנִים עִם יִשְׂרָאֵל יוֹתֵר, וְעַל כֵּן תַּרְגּוּם תּוֹרָה וּמִקְרָא כָּךְ, וְאֵינוֹ מָאוּס, שֶׁהֲרֵי בְּכַמָּה מְקוֹמוֹת כָּתַב הַקָּדוֹשׁ בָּרוּךְ הוּא בַּתּוֹרָה כָּךְ."],[20,"","וּמִשּׁוּם כָּךְ הוּא נִסְתָּר מִתּוֹךְ הַמַּלְאָכִים הָעֶלְיוֹנִים הַקְּדוֹשִׁים. וְעַל כֵּן הִתְגַּלָּה לְאַבְרָהָם בְּדֶרֶךְ נִסְתָּר, שֶׁלֹּא יַשְׁגִּיחוּ בוֹ הַמַּלְאָכִים הַקְּדוֹשִׁים, וְלֹא יִהְיֶה לָהֶם פִּתְחוֹן פֶּה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְגַּלָּה עַל אִישׁ עָרֵל."],[21,"","מָתַי הִתְגַּלָּה לוֹ בְּהִתְגַּלּוּת שֶׁל מַלְאָכִים עֶלְיוֹנִים? כַּאֲשֶׁר נָתַן לוֹ בְּרִית קִיּוּם הַקֹּדֶשׁ, שֶׁכָּתוּב וַיְדַבֵּר אִתּוֹ אֱלֹהִים לֵאמֹר. אֱלֹהִים - הַשֵּׁם שֶׁל הַקֹּדֶשׁ, וְלֹא כָתוּב בְּמַחֲזֵה הַשֵּׁם בַּהִתְגַּלּוּת."],[22,"","לֵאמֹר, מַה זֶּה לֵאמֹר? לֵאמֹר וּלְהַכְרִיז בְּכָל לָשׁוֹן שֶׁלֹּא תִהְיֶה בִּמְכֻסֶּה, לֹא בְּלָשׁוֹן אַחֶרֶת, אֶלָּא בְּלָשׁוֹן שֶׁכֻּלָּם מְדַבְּרִים בָּהּ, שֶׁיְּכוֹלִים לוֹמַר זֶה לָזֶה וְלֹא יְכוֹלִים לְקַטְרֵג וְלוֹמַר פִּתְחוֹן פֶּה, וְעַל כֵּן וַיְדַבֵּר אִתּוֹ אֱלֹהִים לֵאמֹר. אֱלֹהִים וְלֹא מַחֲזֶה, מִשּׁוּם שֶׁהָיָה מַכְנִיס אוֹתוֹ לִבְרִית קִיּוּם הַקֹּדֶשׁ וְקֵרַב אוֹתוֹ אֵלָיו."],[23,"","רַבִּי יְהוּדָה אָמַר, מִשּׁוּם כָּךְ הַהֵ\"א לֹא נִתְּנָה לוֹ עַד שֶׁנִּמּוֹל. מָה הַטַּעַם? שֶׁהִיא מַמָּשׁ נִקְרֵאת בְּרִית. וְעַל כֵּן, כֵּיוָן שֶׁנִּכְנַס בַּבְּרִית, אָז נִתְּנָה לוֹ הָאוֹת הֵ\"א, שֶׁכָּתוּב אֲנִי הִנֵּה בְּרִיתִי אִתָּךְ וְהָיִיתָ לְאַב הֲמוֹן גּוֹיִם וְלֹא יִקָּרֵא עוֹד שִׁמְךְ אַבְרָם וְגוֹ'."],[24,"","אַחַר הַדְּבָרִים הָאֵלֶּה. רַבִּי חִיָּיא הָיָה הוֹלֵךְ לִרְאוֹת אֶת רַבִּי אֶלְעָזָר. פָּגַשׁ אוֹתוֹ רַבִּי חַגַּאי. אָמַר לוֹ, הַדֶּרֶךְ הַזּוֹ שֶׁמְּתֻקֶּנֶת לִפְנֵי מַר, לְאָן הוֹלֶכֶת הִיא? אָמַר לוֹ, לִרְאוֹת אֶת רַבִּי אֶלְעָזָר. אָמַר לוֹ, וְגַם אֲנִי אֵלֵךְ עִמְּךְ? אָמַר לוֹ, אִם תּוּכַל לְהָבִין לְהַשְׂכִּיל לְמַה שֶּׁתִּשְׁמַע - לֵךְ, וְאִם לֹא - שׁוּב לַאֲחוֹרֶיךְ. אָמַר לוֹ, שֶׁלֹּא יַחְשֹׁשׁ מוֹר לָזֶה, שֶׁהֲרֵי אֲנִי שָׁמַעְתִּי כַּמָּה סוֹדוֹת שֶׁל תּוֹרָה וְיָכֹלְתִּי לַעֲמֹד בָּהֶן."],[25,"","פָּתַח רַבִּי חַגַּאי וְאָמַר, מַה שֶּׁכָּתוּב (במדבר כח) אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי וְגוֹ', אֶת קָרְבָּנִי - זֶה קָרְבַּן הַבָּשָׂר שֶׁנִּקְרָב לְכַפֵּר דָּם עַל דָּם, בָּשָׂר עַל בָּשָׂר, מִשּׁוּם שֶׁכָּל הַקָּרְבָּנוֹת לֹא נִקְרָבִים אֶלָּא הַבָּשָׂר לְכַפֵּר עַל הַבָּשָׂר."]]],[["וְהָכִי שְׁמַעְנָא אִי בַּר נָשׁ חָטָא בְּהֵמָה מַה חָטָאתּ, דְקוּדְשָׁא בְּרִיךָ הוּא אָמַר (ויקרא א׳:ב׳) אָדָם כִּי יַקְרִיב מִכֶּם קָרְבָּן וְגו'. אַמַּאי, אֶלָּא קוּדְשָׁא בְּרִיךָ הוּא עֲבִיד רוּחַ בְּנֵי נָשָׁא וְרוּחַ הַבְּהֵמָה, וְאַפְּרִישׁ דָּא מִן דָּא. וּבְגִין כָּךָ (קהלת ג׳:כ״א) רוּחַ בְּנֵי הָאָדָם הָעוֹלָה הִיא לְמַעְלָה וְרוּחַ הַבְּהֵמָה וְגו' ודַּאי מִתְּפְּרַשׁ דָּא מִן דָּא.","עַד לָא חָטָא אָדָם מַה כְּתִּיב, (בראשית א׳:כ״ט) וַיֹּאמֶר אֱלהִים הִנִּה נָתַּתִּי לָכֶם אֶתּ כָּל עֵשֶׂב זוֹרֵעַ זָרַע וְגו' וּכְתִּיב לָכֶם יִהְיֶה לְאָכְלָה ולא יַתִּיר. כֵּיוָן דְּחָטָא וְיֵצֶּר הָרָע אִשְׁתָּאִיב בְּגוּפָּא דִילֵיהּ, וּבְכָל אִנּוּן תּוֹלָדִין עֲבַד בְּהוּ דִּינָא.","וּלְבָתַּר אֲתָּא נֹחַ וחָמָא דְּהָא גוּפָּא אִתְּבְּנֵי מֵאַתְּרָא דְּיֵצֶּר הָרָע, אַקְרִיב קָרְבָּן כְּמָה דְּאַקְרִיב אָדָם, מַה כְּתִּיב, (בראשית ח׳:כ״א) וַיָּרַח יְיָ אֶתּ רֵיחַ הַנִּיחֹחַ וגו'. (וכתיב) כִּי יֵצֶּר לֵב הָאָדָם רַע מִנְּעוּרָיו. אָמַר קוּדְשָׁא בְּרִיךָ הוּא מִכָּאן וּלְהָלְאָה הוֹאִיל וְגוּפָּא אִשְׁתָּאִיב מֵהַהוּא יֵצֶּר הָרָע, יִתְּעַנַּג גּוּפָּא כְּמָה דְאִתְּחֲזֵי לֵיהּ יֵיכוּל בִּשְׂרָא. כְּיְרֶק עֵשֶׂב נָתַּתִּי לָכֶם אֶתּ כֹּל.","כַּד אָכִיל בִּשְׂרָא. מֵהַהוּא בִּשְׂרָא אִתְּעַנַּג בִּשְׂרָא דִּילֵיהּ וְאִתְּעָרַב דָּא בְּדָא וְאִתְּרַבֵּי גוּפָּא מִנֵּיהּ, וּמֵהַהוּא עֹנֶג גּוּפָּא חָטָא בְּכַמָּה חֶטְאִין. אָמַר קוּדְשָׁא בְּרִיךָ הוּא כַּפָּרָה על גּוּפָּא בִּשְׂרָא. בִּשְׂרָא אָכִיל וּבִשְׂרָא אִתְּרַבֵּי מִינֵיהּ וּבֵיהּ חָטָא. בְגִין כָּךָ לְכַפָּרָא על גּוּפֵּיהּ בִּשְׂרָא. וּבִשְׂרָא דְּאָכִיל בִּשְׂרָא עֲבִיד דָּמָא לְגוּפָּא (בגין כך דמא דאשתאר מההוא בשרא דאכיל בשרא עבד דמא לגופא) בְגִין כָּךָ דָּמָא דְּאִשְׁתָּאַר מֵהַהוּא בִּשְׂרָא לְבַר אִתְּעַתַּד לְכַפָּרָא עַל דָּמָא דְּאִתְּעֲבִיד מֵהַהוּא בִּשְׂרָא דִילֵיהּ דִּכְתִּיב, (ויקרא י״ז:י״א) כִּי הַדָּם הוּא בַּנְּפֶּשׁ יְכַפֵּר.","כְּתִּיב קָרְבָּנִי, וּכְתִּיב קָרְבַּנְכֶם דִּכְתִּיב, (ויקרא א׳:ב׳) תַּקְרִיבוּ אֶתּ קָרְבַּנְכֶם, מַה בֵּין הַאי לְהַאי, אֶלָּא קָרְבָּנִי. כְּגוֹן שְׁלָמִים דְּאַתְּיָין עַל שָׁלוֹם. קָרְבַּנְכֶם, כְּגוֹן חַטָאוֹתּ וַאֲשָׁמוֹתּ דְּאַתְּיָין עַל חֵטְא ואָשָׁם, בְגִין כָּךָ אֶתּ קָרְבָּנִי בִּשְׂרָא. לַחְמִי נַהֲמָא וְחַמְרָא. רֵיחַ דָּא קְטוֹרֶתּ. נִיחֹחִי דָּא נַחַתּ רוּחַ דְּעֲבִיד כַּהֲנָא בִּרְעוּתָּא דִּשְׁמָא קַדִּישָׁא, וְלֵיוָאֵי בִּרְעוּתָּא דְּשִׁיר וּשְׁבָחָה.","תִּשְׁמְרוּ לְהַקְרִיב לִי בְּמוֹעֲדוֹ. בְּמוֹעֲדוֹ מַאי הֲוִי, אִי תֵּימָא בְּכָל יוֹמָא בַּבֹּקֶר וּבָעֶרֶב, מאי אִיהוּ בְּמוֹעֲדוֹ (נ\"א מאי אריא דאיהו מועדו), אֶלָּא מוֹעֲדוֹ דְּשָׁלְטָא בְּהַהוּא זִמְנָא רַעֲוָא. רְעוּ דְּאִשְׁתְּכַח לְעֵילָא בְּדַרְגָּא יְדִיעָא. ועל דָּא כְּתִּיב בְּמוֹעֲדוֹ.","כַּד קָרְבָּן אִתְּקְרִיב. כּלָּא נָטְלִין חוּלָקָא, וְאִתְּבַּדְּרָן קְלִיפִּין לְכָל סִטְרָא, וְיִיחוּדָא אִתְּקְרִיב וְאִתְּיַיחַד וּבוֹצִּינִין אִתְּנַהֲרִין וְאִשְׁתְּכַח רַעֲוָא וּרְעוּ בְּכָל עָלְמִין וְקוּדְשָׁא בְּרִיךָ הוּא אִשְׁתְּכַח בְּרָזָא דְיִחוּדָא חָדָא כְּדְקָא חָזֵי. אֲתָּא רַבִּי חִיָּיא וּנְשָׁקֵיהּ, אָמַר לֵיהּ יָאוֹתּ אַנְתְּ בְּרִי מִינִּי לְמֵיהַךָ לְמֶחֱמֵי לֵיהּ לִסְבָר אַנְפִּין דְּיוֹמִין. (תו פתח ואמר דוד מלכא דאיהו רביעאה ואיהו אבן מאסו הבונים) (נ\"א אמאי דוד מלכא אחסין מלכותא דאיהו רביעאה דאיהו אבן מאסו הבונים).","אֲזְלוּ, כַּד מָטוּן לְגַבֵּיהּ, חָמָא לוֹן יַתְּבֵי עַל תַּרְעָא, אָמַר לֵיהּ לְשַׁמּשא זִיל וְאֵימָא לוֹן הַאי כֻּרְסְיָיא דִּתְּלַתּ קָיְימִין מַהוּ כָּל אֶחָד (ס\"א כלא חד). אָמְרוּ לֵיהּ זִיל וְאֵימָא לֵיהּ לְמַר דְּלָאו לְמַגָּנָא אָמַר דָּוִד מַלְכָּא דְּאִיהוּ רְבִיעָאָה אֶבֶן מָאֲסוּ הַבּוֹנִים. אָמַר לֵיהּ זִיל וְאֵימָא לוֹן דְּאָן גָּעֲלוּ בֵּיהּ בְּדָוד דְּאִיהוּ אָמַר אֶבֶן מָאֲסוּ הַבּוֹנִים.","אַהֲדַר רַבִּי חִיָּיא רֵישֵׁיהּ לְגַבֵּי רַבִּי חַגַּאי וְאָמַר לֵיהּ שַׁמְעַתּ בְּהַאי מִידִי. אָמַר שְׁמַעְנא בְּהַאי קְרָא דִּכְתִּיב, (שיר השירים א׳:ו׳) \"בְּנֵי \"אִמִּי \"נִחֲרוּ בִי שָׂמוּנִי וְגו'. דְּהַאי קְרָא שְׁלֹמֹה מַלְכָּא אֲמָרוֹ, וְעַל דָּוִד מַלְכָּא אִתְּמָר כַּד דָּחוּ לֵיהּ אֲחוּהִי מִנַּיְיהוּ.","וְתּוּ שְׁמַעְנָא מַאי חָמָא קוּדְשָׁא בְּרִיךָ הוּא לְמֵיהַב מַלְכוּתָּא לִיהוּדָה מִכָּל אֲחוּהִי, אֶלָּא אַתְּוָון דִּשְׁמֵיהּ חֲקִיקָן בֵּיהּ, וְקוּדְשָׁא בְּרִיךָ הוּא יָהַב יְקָרָא לִשְׁמֵיהּ וּבְגִין כָּךָ אַחְסִין מַלְכוּתָּא. וְתּוּ שְׁמַעְנָא יְהוּדָה הָא אַתְּוָון דִּשְׁמֵיהּ וַדַּאי, ד' לֵיתֵּיהּ אַמַּאי. אֶלָּא דָּא דָּוִד מַלְכָּא דְּאִתְּקַשַׁר בִּשְׁמֵיהּ מִכָּל בְּנֵי עָלְמָא דִּכְתִּיב, (הושע ג׳:ה׳) וּבִקְּשׁוּ אֶתּ יְיָ אֱלהֵיהֶם וְאֶתּ דָּוד מַלְכָּם וְגו' הָא דָּוִד קָשִׁיר בִּשְׁמֵיהּ, תּוּ דְּאִיהוּ קֶשֶׁר שֶׁל תְּפִּלִּין ודַּאי ד' דָּוד מַלְכָּא (ד\"א קשר של תפלין ודאי), וּבְגִין כָּךָ דָּוִד אִתְּקַשַׁר בִּשְׁמֵיהּ.","עָאלוּ, כֵּיוָן דְּעָאלוּ יְתִּיבוּ קַמֵּיהּ, אִשְׁתִּיק רַבִּי אֶלְעָזָר וְאִנּוּן אִשְׁתִּיקוּ. עָאל רַבִּי אֶלְעָזָר לְאִדְרֵיהּ שְׁמַע חַד קָלָא דְּהֲוָה אָמַר זִיל וְאֵימָא לוֹן מַה דְּאִנּוּן בָּעְיָין דִּכְשֵׁרִין אִנּוּן. אַהֲדַר לְגַבַּיְיהוּ. אָמַר לוֹן אִיתּ מַאן דִּשְׁמַע מִלָּה לֵימָא לִי. אָמְרוּ לֵיהּ אֲנַן מְחַכָּאן לְאַנְהָרָא מִגּוֹ צַּחוּתָּא דְּבוּצִּינָא עִלָּאָה וּסְבָרָא נִסְבַּר."],[[0,"והכי שמענא וכו':","וכך שמעתי. אם האדם חטא, בהמה מה חטאת, שהקב\"ה אמר אדם כי יקריב מכם קרבן לה, מן הבהמה וגו'. ומשיב, אלא הקב\"ה עשה את רוח האדם ורוח הבהמה, והפרידם זה מזה, ולפיכך, רוח בני האדם העולה היא למעלה, ורוח הבהמה היורדת היא למטה וגו' ודאי נפרדים הם זה מזה."],[1,"עד לא חטא וכו':","מטרם שחטא אדם מה כתוב. ויאמר אלקים הנה נתתי לכם את כל עשב זורע זרע וגו'. וכתיב לכם יהיה לאכלה, ולא יותר מזה. ו לא הותר לו לאכול בעלי חיים. כיון שחטא ויצר הרע נבלע בגוף שלו, ובכל תולדותיו, עשה בהם דין. דהיינו שהביא עליהם המבול."],[2,"ולבתר אתא נח וכו':","ואחר כך בא נח, וראה שהגוף נבנה ממקום יצר הרע, הקריב קרבן כמו שהקריב אדם. מה כתוב וירח ה' את ריח הניחח וגו' כי יצר לב האדם רע מנעוריו, אמר הקב\"ה מכאן ואילך, הואיל והגוף כבר נבלע מאותו יצר הרע, יתענג הגוף כמה שירצה, ויאכל בשר, ואמר, כירק עשב נתתי לכם את כל."],[3,"כד אכיל וכו':","כאשר האדם אוכל בשר, מתענג בשר האדם מאותו בשר ומתערבים זה בזה, בשר אדם ובשר בהמה. והגוף מתגדל ממנו. ומאותו העונג שנתענג באכילת הבשר, חוטא הגוף בכמה חטאים. אמר הקב\"ה, בשר, יהיה כפרה על הגוף, דהיינו בשר הקרבן. כי בשר אכל, ובשר נתגדל ממנו בהגוף, ובו חטא. לפיכך, יהיה הבשר של הקרבן, לכפרה על גופו. ובשר, דהיינו הגוף, האוכל בשר, עושה דם בהגוף, ומשום זה, דם הנשאר מבחוץ שנשאר מהכשר של הקרבן, מזומן לכפר על הדם של האדם שנעשה מאותו הבשר של הבהמה. שכתוב כי הדם הוא בנפש יכפר."],[3,"","פנימיות הדברים. וצריך שתזכור כל המתבאר לעיל פרשת נח דף מ\"ח אות ק\"ל בהסולם עש\"ה ואין להכפיל דברים. היוצא משם שהכלי דבשר שבכל פרצוף הוא מחוסר שלמות, משום שהמאציל לא תקן רק בחינת ו\"ק של הכלי דבשר, להמשכת ו\"ק דאור החיה, דהיינו לבחינת הארה שממטה למעלה, והג\"ר דכלי דבשר שהוא המשכת האור ממעלה למטה, נמצאים עוד בשבירה, שהם הקליפות וס\"א שלא יתוקנו מטרם גמר התקון, וה\"ס האיסור של עץ הדעת, שהמשיך האורות ממעלה למטה, דהיינו להשלים הג\"ר דכלי דבשר. כמ\"ש שם עש\"ה. גם נתבאר שם סוד הקרבנות לכפרת עונות, שע\"י המ\"ן העולה מהקרבן נעשה זווג עליון, שבתחילת הזווג נמשך מג\"ר הללו דחיה, ותכף הם מתבטלים אשר מרגע זו מטרם שנתבטלו מקבלים הקליפות, ועי\"ז נפרדים מהקדושה עש\"ה."],[3,"","וזה אמרו כאן, \u0003קב\"ה עביד רוח בני נשא וכו' רוח בני האדם העולה היא למעלה, ורוח הבהמה היא למטה.\u0004 כי רק בחינת האדם נעשה מתוקן לקדושה, וניתן לו הרוח חיה, שיאיר ממטה למעלה. כנ\"ל. אבל רוח הבהמה יורדת למטה, שהיא נוטה לקבל רק ממעלה למטה, מבחינת ג\"ר דבשר כנ\"ל. וז\"ש \u0003עד לא חטא וכו' לכם יהיה לאכלה ולא יתיר.\u0004 שלא הותר לו אלא עשב ולא בשר. והוא מטעם, שרוח הבהמה יורדת למטה, ויכול בשר בהמה להזיק לו ולהחטיאו שימשיך גם הוא ממעלה למטה כמעשה עצה\"ד. \u0003כיון דחטא ויצה\"ר אשתאיב בגופא וכו' אתא נח וכו' אקריב קרבן.\u0004 כי מאחר שהקליפות נאחזו בהגוף ע\"י אכילות עצה\"ד דהיינו שיש להם כח להחטיאו תמיד כנ\"ל, עתה אין תקון אחר אלא להקריב קרבן. כי ע\"י הקרבן נמשך לס\"א השפע שממעלה למטה המיוחס להם, ואז תכף מתפרדים מגוף האדם. (כנ\"ל בפרשת נח אות ק\"ל עש\"ה.) ואחר שהקריב קרבן, יכול להעלות מ\"ן ולתקן אותו התקון של הקרבן גם באכילתו עצמו את בשר בהמה, וע\"י הזווג שגורם למעלה באכילתו מפריד הקליפות כמו הקרבן, בסו\"ה זה השלחן אשר לפני ה'. וז\"ש \u0003אמר קב\"ה מכאן ולהלאה הואיל וגופא אשתאיב מההוא יצה\"ר יתענג גופא כמה דאתחזי ליה,\u0004 שהקב\"ה אמר, כיון שהיצה\"ר להמשיך ממעלה למטה כבר נבלע בגוף, ע\"כ אכילת בשר בהמה לא יקלקלו יותר, אלא אדרבה אם יתענג הגוף כמו שראוי, דהיינו שיעלה מ\"ן באכילתו כמו בקרבן, הרי או יפריד את יצה\"ר הזה מהגוף, וע\"כ אמר \u0003יתענג גופא כמה דאתחזי ליה.\u0004 וז\"ש \u0003ואתערב דא בדא ואתרבי גופא מניה,\u0004 כי ע\"י התערבות בשר בהמה בבשר האדם הוא מעלה מ\"ן לזווג עליון, אשר בתחילתו יורד בחינת ג\"ר החסרות לגוף, ומטרם שנפסק מקבל אותו גם גוף האדם, והוא נגדל ממנו, כלומר שמקבל תקון לבחי' ג\"ר החסדים לבשר הגוף, כנ\"ל אצל קרבן. וז\"ש \u0003ואתרבי גופא,\u0004 דהיינו שקונה בחינת גדלות. אמנם אם אינו אוכל בקדושה וטהרה ואכילתו אינו כמו קרבן, נמצא הבשר בהמה שאוכל, שמקלקלו עוד יותר, וז\"ש \u0003ומההוא ענג גופא חטא בכמה חטאין.\u0004 ומ\"מ הותר לו לאכול, כי אמר הקב\"ה \u0003כפרה על גופא בשרא,\u0004 שאין כפרה אחרת על עון דעצה\"ד אלא בשר שאוכל בטהרה כנ\"ל. לפיכך \u0003בשרא אכיל ובשרא אתרבי מניה,\u0004 שאם אוכל בטהרה הרי בשר הגוף מתגדל משפע הזווג בתחילתו כנ\"ל. \u0003וביה חטא,\u0004 ואם אינו אוכל בטהרה, נמצא שמתקלקל עוד יותר וחוטא בו. \u0003ובג\"כ לכפרא על גופיה בשרא,\u0004 כלומר, גם אחר שחטא מכח אכילת הבשר, אין תקנה אחרת לכפר על הגוף רק ע\"י שיחזור ויאכל בשר בטהרה. כנ\"ל."],[3,"","אמנם בשר בהמה עצמו, אינו מתערב בגוף האדם להגדילו, שהוא מטעם, רוח הבהמה היורדת היא למטה, שהיה מתערב על ידי זה ברוח האדם. וע\"כ נעשה תקון, שהבשר בהמה מתהפך ונעשה \u0003דם\u0004 בגוף האדם, ומדם הזה מתגדל גוף האדם, ולא מבשר. ויש עוד תקון נוסף, שהיא התקון שלא לאכול דם, וכן תקון הזריקה על גבי מזבח, שזה מכפר על הדם שנעשה מבשר בהמה שבא בפנימיות הגוף. וז\"ש \u0003ובג\"כ דמא דאשתאר מההוא בשרא לבר,\u0004 דהיינו דם הבהמה שאסור לאכלו, ונאמר עליו על הארץ תשפכנו כמים, ונשאר מחוץ לגוף האדם, \u0003אתעתד לכפרא על דמא דאתעביד מההוא בשרא דיליה,\u0004 שהוא מכפר על הדם שנעשה מבשר הבהמה, שנשאר בגוף האדם. כמבואר."],[4,"כתיב קרבני וכו':","כתוב קרבני, וכתוב קרבנכם, שכתוב תקריבו את קרבנכם, מה בין זה לזה. ומשיב, אלא \u0003קרבני,\u0004 דהיינו כעין שלמים. הבאים על שלום. \u0003קרבנכם\u0004 היינו כעין חטאות ואשמות הבאים על חטא ואשם. \u0003ולפיכך את קרבני,\u0004 הוא בשר. \u0003לחמי,\u0004 הוא לחם ויין. \u0003ריח\u0004 הוא קטרת. \u0003ניחחי,\u0004 זה נחת רוח שעושה הכהן בכונת השם הקדוש. שמזכיר בעת הקרבה. ולוים בכונה שבשיר ושבחה, שמשוררים בעת הקרבה."],[5,"תשמרו להקריב לי במועדו:","ושואל. מה הוא \u0003במועדו,\u0004 אם תאמר, שהפירוש הוא להקריב בכל יום בבוקר ובערב, למה נקרא זה במועדו. ומשיב, אלא מועדו, פירושו, הרצון, השולט באותה שעה, היינו בשעת הקרבה, הרצון, הנמצא אז למעלה במדרגה ידועה היינו בהנוקבא ועל כן כתוב \u0003במועדו.\u0004"],[6,"כד קרבן וכו':","כאשר הקרבן נקרב. כל העולמות מקבלים חלק ממנו, ומתפזרים הקליפות לכל עבר, והיחוד של זו\"נ מתקרב ונתיחד, והנרות מאירים שה\"ס מדרגות העליונות, ונקרא רצון ורעות בכל העולמות, והקב\"ה נמצא בסוד היחוד \u0003דאחד\u0004 כראוי. בא ר' חייא ונשקו. א\"ל ראוי אתה יותר ממני ללכת לראות אותו. היינו לר' אלעזר."],[7,"אזלו, כד מטון וכו':","הלכו. כאשר הגיעו אצלו, אצל ר' אלעזר, ראה אותם יושבים על יד השער. אמר להמשמש שלו, לך ואמור להם, כסא הזה של שלשה עמודים, מה הם כל אחד ואחד מהם. אמרו לו לך ואמור לאדוננו, שלא בחנם, אמר דוד המלך, שהוא עמוד הרביעי של הכסא, אבן מאסו הבונים, ובזה רמזו לו גם את ג' העמודים הקודמים לדוד, שהם חג\"ת. אמר לו להמשמש שלו, לך ואמור להם, איפה מאסו הבונים בדוד, שהוא אמר, אבן מאסו הבונים."],[8,"אהדר ר' חייא וכו':","החזיר ר' חייא ראשו אל ר' חגאי, ואמר לו שמעת דבר כזה. אמר שמעתי במקרא הזה שכתוב בני אמי נחרו בי שמוני וגו'. שכתוב הזה שלמה המלך אמרו, ונאמר על דוד המלך כאשר דחו אותו אחיו. ורמז לו התשובה בזה, שהכתוב, אבן מאסו הבונים אמר דוד, בעת שהיה לו מוחין דאחורים, אשר אז אחיו דחו אותו."],[9,"ותו שמענא וכו':","ועוד שמענו. מה ראה הקב\"ה ליתן המלכות ליהודה יותר מלכל אחיו. ומשיב, אלא אותיות שמו הקדוש היו חקוקות בו. כי יש שם הוי\"ה בהשם יהודה. והקב\"ה נתן כבוד לשמו, ומשום זה ירש המלכות. ועוד שמעתי. יהודה, הם ודאי אותיות שמו הקדוש, אבל \u0003ד'\u0004 אין בו, בשם הויה. ושואל, למה. ומשיב, אלא \u0003ד'\u0004 זו דיהודה, הוא דוד המלך, שנקשר בשמו יותר מכל בני העולם, שכתוב ובקשו את ה' אלקיהם, ואת דוד מלכם וגו'. הרי שדוד קשור בשמו הקדוש. ועוד, שהוא קשר של תפילין. שדוד ה\"ס קשר של תפילין של הקב\"ה, שה\"ס הנוקבא דז\"א. ודאי הוא שה \u0003ד'\u0004 דיהודה הוא דוד המלך, ומשום זה דוד נקשר בשמו הקדוש. כי בשם \u0003יהודה\u0004 יש הוי\"ה שהוא ז\"א, ויש \u0003ד'\u0004 שהיא דוד המלך שה\"ס הנוקבא דז\"א."],[10,"עאלו כיון וכו':","נכנסו, כיון שנכנסו ישבו לפניו. שתק ר' אלעזר, וגם הם שתקו. נכנס ר' אלעזר לחדרו. שמע שם קול אחד שהיה אומר, לך ואמור להם מה שהם רוצים כי צדיקים המה. חזר אצלם, אמר להם, יש מי ביניכם ששמע דבר, יאמר לי. אמרו לו, אנחנו מחכים להאיר על ידי צחות נר העליון, ודעת נבין."]],[[0,"","וְכָךָ שָׁמַעְתִּי, אִם אָדָם חָטָא - בְּהֵמָה מֶה חָטְאָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר (ויקרא א) אָדָם כִּי יַקְרִיב מִכֶּם קָרְבָּן וְגוֹ'? לָמָּה? אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה אֶת רוּחַ בְּנֵי אָדָם וְאֶת רוּחַ הַבְּהֵמָה, וְהִפְרִיד זוֹ מִזּוֹ, וּמִשּׁוּם כָּךְ (קהלת ג) רוּחַ בְּנֵי הָאָדָם הָעֹלָה הִיא לְמָעְלָה וְרוּחַ הַבְּהֵמָה וְגוֹ'. וַדַּאי נִפְרָדִים זֶה מִזֶּה."],[1,"","בְּטֶרֶם שֶׁחָטָא אָדָם מַה כָּתוּב? (בראשית א) וַיֹּאמֶר אֱלֹהִים הִנֵּה נָתַתִּי לָכֶם אֶת כָּל עֵשֶׂב זרֵעַ זֶרַע וְגוֹ', וְכָתוּב לָכֶם יִהְיֶה לְאָכְלָה, וְלֹא יוֹתֵר! כֵּיוָן שֶׁחָטָא וְהַיֵּצֶר נִשְׁאַב לְגוּפוֹ, וּבְכָל אוֹתָם הַתּוֹלָדוֹת עָשָׂה דִין,"],[2,"","וְאַחַר בָּא נֹחַ וְרָאָה שֶׁהִנֵּה הַגּוּף נִבְנָה מֵהַמָּקוֹם שֶׁל הַיֵּצֶר הָרָע, הִקְרִיב קָרְבָּן כְּמוֹ שֶׁהִקְרִיב אָדָם, מַה כָּתוּב? (שם ח) וַיָּרַח ה' אֶת רֵיחַ הַנִּיחֹחַ וְגוֹ', וְכָתוּב כִּי יֵצֶר לֵב הָאָדָם רַע מִנְּעֻרָיו. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, מִכָּאן וָהָלְאָה, הוֹאִיל וְהַגּוּף נִשְׁאָב מֵאוֹתוֹ הַיֵּצֶר הָרָע, יִתְעַנֵּג הַגּוּף כְּמוֹ שֶׁרָאוּי לוֹ, יֹאכַל בָּשָׂר. כְּיֶרֶק עֵשֶׂב נָתַתִּי לָכֶם אֶת כֹּל."],[3,"","כְּשֶׁאוֹכֵל בָּשָׂר, מֵאוֹתוֹ הַבָּשָׂר מִתְעַנֵּג הַבָּשָׂר שֶׁלּוֹ, וּמִתְעָרְבִים זֶה עִם זֶה וּמִתְגַּדֵּל מִמֶּנּוּ הַגּוּף, וּמֵאוֹתוֹ הָעֹנֶג הַגּוּף חוֹטֵא בְּכַמָּה חֲטָאִים. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, הַבָּשָׂר כַּפָּרָה עַל הַגּוּף. בָּשָׂר אוֹכֵל, וּבָשָׂר מִתְרַבֶּה מִמֶּנּוּ, וּבוֹ חָטָא. מִשּׁוּם כָּךְ בָּשָׂר לְכַפֵּר עַל גּוּפוֹ, וְהַבָּשָׂר שֶׁאוֹכֵל עוֹשֶׂה דָּם לַגּוּף (משום כך הדם שנשאר מאותו הבשר שאוכל, הבשר עושה לגוף דם). מִשּׁוּם כָּךְ, הַדָּם שֶׁנִּשְׁאָר מֵאוֹתוֹ הַבָּשָׂר בַּחוּץ, מִתְעַתֵּד לְכַפֵּר עַל הַדָּם שֶׁנַּעֲשָׂה מֵאוֹתוֹ הַבָּשָׂר שֶׁלּוֹ, שֶׁכָּתוּב (ויקרא יז) כִּי הַדָּם הוּא בַּנֶּפֶשׁ יְכַפֵּר."],[4,"","כָּתוּב קָרְבָּנִי, וְכָתוּב קָרְבַּנְכֶם, שֶׁכָּתוּב (שם א) תַּקְרִיבוּ אֶת קָרְבַּנְכֶם. מַה בֵּין זֶה לָזֶה? אֶלָּא קָרְבָּנִי - כְּמוֹ שְׁלָמִים שֶׁבָּאִים עַל שָׁלוֹם. קָרְבַּנְכֶם - כְּמוֹ חַטָּאוֹת וַאֲשָׁמוֹת שֶׁבָּאִים עַל חֵטְא וְאָשָׁם. מִשּׁוּם כָּךְ, (במדבר כח) אֶת קָרְבָּנִי - בָּשָׂר. לַחְמִי - לֶחֶם וְיַיִן. רֵיחַ - זוֹ הַקְּטֹרֶת. נִיחֹחִי - זוֹ נַחַת רוּחַ שֶׁעוֹשֶׂה הַכֹּהֵן בָּרָצוֹן שֶׁל הַשֵּׁם הַקָּדוֹשׁ, וְהַלְוִיִּם בְּרָצוֹן שֶׁל שִׁיר וּשְׁבָחָה."],[5,"","תִּשְׁמְרוּ לְהַקְרִיב לִי בְּמוֹעֲדוֹ, מַה זֶּה בְּמוֹעֲדוֹ? אִם תֹּאמַר בְּכָל יוֹם בַּבֹּקֶר וּבָעֶרֶב, מַה זֶּה בְּמוֹעֲדוֹ? (נ\"א: מה אומר שהוא מו דו)? אֶלָּא הַמּוֹעֲדוֹ שֶׁשּׁוֹלֵט בְּאוֹתָהּ עֵת רָצוֹן, הָרָצוֹן שֶׁנִּמְצָא לְמַעְלָה בְּדַרְגָּה יְדוּעָה. וְעַל כֵּן כָּתוּב בְּמוֹעֲדוֹ."],[6,"","כְּשֶׁנִּקְרָב הַקָּרְבָּן. הַכֹּל נוֹטְלִים חֵלֶק, וּמִתְפַּזְּרוֹת הַקְּלִפּוֹת לְכָל צַד, וְהַיִּחוּד נִקְרָב וּמִתְיַחֵד, וְהַמְּאוֹרוֹת מְאִירִים, וְנִמְצָא רָצוֹן בְּכָל הָעוֹלָמוֹת, וְהַקָּדוֹשׁ בָּרוּךְ הוּא נִמְצָא בְּסוֹד שֶׁל יִחוּד אֶחָד כָּרָאוּי. בָּא רַבִּי חִיָּיא וְנָשַׁק אוֹתוֹ. אָמַר לוֹ, נָאֶה אַתָּה, בְּנִי, מִמֶּנִּי לָלֶכֶת וְלִרְאוֹת אֶת סֵבֶר פְּנֵי הַיָּמִים. (עוד פתח ואמר דוד המלך, שהוא רביעי, שהוא אבן מאסו הבונים) (נ\"א: למה דוד המלך ירש המלכות? שהוא הרביעי, שהוא אבן מאסו הבונים)."],[7,"","הָלְכוּ, כְּשֶׁהִגִּיעוּ אֵלָיו, רָאָה אוֹתָם יוֹשְׁבִים עַל הַשַּׁעַר. אָמַר לוֹ לַשַּׁמָּשׁ, לֵךְ וֶאֱמֹר לָהֶם, הַכִּסֵּא הַזֶּה שֶׁל שְׁלֹשָׁה עַמּוּדִים מַה הוּא כָּל אֶחָד (הכל אחד)? אָמְרוּ לוֹ, לֵךְ וֶאֱמֹר לוֹ לְמַר, שֶׁלֹּא לְחִנָּם אָמַר דָּוִד הַמֶּלֶךְ, שֶׁהוּא הָרְבִיעִי, אֶבֶן מָאֲסוּ הַבּוֹנִים. אָמַר לוֹ, לֵךְ וֶאֱמֹר לָהֶם, שֶׁאֵיפֹה מָאֲסוּ בוֹ בְּדָוִד שֶׁהוּא אָמַר אֶבֶן מָאֲסוּ הַבּוֹנִים."],[8,"","הֶחֱזִיר רַבִּי חִיָּיא אֶת רֹאשׁוֹ לְרַבִּי חַגַּאי, וְאָמַר לוֹ, הֲשָׁמַעְתָּ בָּזֶה דָּבָר? אָמַר, שָׁמַעְתִּי בַּפָּסוּק הַזֶּה שֶׁכָּתוּב (שיר א) \"בְּנֵי \"אִמִּי \"נִחֲרוּ בִי שָׂמוּנִי וְגוֹ', שֶׁהַפָּסוּק הַזֶּה אָמַר אוֹתוֹ שְׁלֹמֹה, וְעַל דָּוִד הַמֶּלֶךְ הוּא נֶאֱמַר, כְּשֶׁדָּחוּ אוֹתוֹ הָאַחִים שֶׁלּוֹ מֵהֶם."],[9,"","וְעוֹד שָׁמַעְתִּי, מָה רָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא לָתֵת מַלְכוּת לִיהוּדָה מִכָּל אֶחָיו? אֶלָּא אוֹתִיּוֹת שְׁמוֹ חֲקוּקוֹת בּוֹ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן כָּבוֹד לִשְׁמוֹ, וּמִשּׁוּם כָּךְ יָרַשׁ אֶת הַמַּלְכוּת. וְעוֹד שָׁמַעְתִּי, יְהוּדָה - הִנֵּה אוֹתִיּוֹת שְׁמוֹ וַדַּאי. ד' אֵינֶנָּה לָמָּה? אֶלָּא זֶה דָּוִד הַמֶּלֶךְ שֶׁנִּקְשַׁר בִּשְׁמוֹ מִכָּל בְּנֵי הָעוֹלָם, שֶׁכָּתוּב (הושע ג) וּבִקְשׁוּ אֶת ה' אֱלֹהֵיהֶם וְאֵת דָּוִיד מַלְכָּם וְגוֹ'. הִנֵּה דָּוִד קָשׁוּר בִּשְׁמוֹ. וְעוֹד, שֶׁהוּא קֶשֶׁר שֶׁל תְּפִלִּין וַדַּאי, ד' דָּוִד הַמֶּלֶךְ (ד\"א קשר של תפלין ודאי), וּמִשּׁוּם כָּךְ דָּוִד נִקְשַׁר בִּשְׁמוֹ."],[10,"","נִכְנְסוּ, כֵּיוָן שֶׁנִּכְנְסוּ, יָשְׁבוּ לְפָנָיו. שָׁתַק רַבִּי אֶלְעָזָר וְהֵם שָׁתְקוּ. נִכְנַס רַבִּי אֶלְעָזָר לְחַדְרוֹ, וְשָׁמַע קוֹל אֶחָד שֶׁהָיָה אוֹמֵר: לֵךְ וֶאֱמֹר לָהֶם מַה שֶּׁהֵם רוֹצִים, שֶׁהֲרֵי הֵם כְּשֵׁרִים. חָזַר אֲלֵיהֶם. אָמַר לָהֶם, אִם יֵשׁ מִי שֶׁשָּׁמַע דָּבָר - שֶׁיֹּאמַר לִי. אָמְרוּ לוֹ, אָנוּ מְחַכִּים לִהְיוֹת מוּאָרִים מִתּוֹךְ הַצַּחוּת שֶׁל הַמָּאוֹר הָעֶלְיוֹן, וּלְהָבִין וּלְהַשְׂכִּיל."]]],[["פָּתַּח וְאָמַר, (חבקוק ב׳:כ׳) וַיְיָ בְּהֵיכַל קָדְשׁוֹ הַס מִפָּנָיו כָּל הָאָרֶץ. כַּד בָּעֵי קוּדְשָׁא בְּרִיךָ הוּא לְמִבְרֵי עָלְמָא, אִסְתַּכַּל גּוֹ מַחֲשָׁבָה רָזָא דְאוֹרַיְיתָּא וְרָשִׁים רִשׁוּמִין ולא הֲוָה יָכִיל לְמֵיקַם, עַד דְּבָרָא תְּשׁוּבָה דְּאִיהִי הֵיכָלָא פְּנִימָאָה עִלָּאָה וְרָזָא סְתִּימָא וְתַּמָּן אִתְּרְשִׁימוּ וְאִתְּצַּיְירוּ אַתְּוָון בְּגִלּוּפַּיְיהוּ.","כֵּיוָן דְּאִתְּבְּרֵי דָא הֲוָה מִסְתַּכַּל בְּהַאי הֵיכָלָא וְרָשִׁים קַמֵּיהּ צִּיּוּרִין דְּכָל עָלְמָא דִּכְתִּיב הַס מִפָּנָיו כָּל הָאָרֶץ רְשִׁים קַמֵּיהּ רְשׁוּמִין וְצִּיּוּרִין דְּכָל עָלְמָא. בָּעֵי לְמִבְרֵי שָׁמַיִם מָה עֲבַד אִסְתַּכַּל בְּאוֹר קַדְמָאָה וְאִתְּעַטַף בֵּיהּ וּבְרָא שָׁמַיִם. דִּכְתִּיב, (תהילים ק״ד:ב׳) עוֹטֶה אוֹר כַּשַׁלְמָה וְאַחַר כָּךָ נוֹטֶה שָׁמַיִם כַּיְרִיעָה.","אִסְתַּכַּל לְמֶעְבַּד עָלְמָא תַּתָּאָה עֲבַד הֵיכָלָא אוֹחֲרָא וְעָאל בֵּיהּ וּמִנֵּיהּ אִסְתַּכַּל וּרְשִׁים קַמֵּיהּ כָּל עָלְמִין לְתַּתָּא וּבְרָא לוֹ. הֲדָא הוּא דִכְתִּיב וַיְיָ בְּהֵיכַל קָדְשׁוֹ הַס מִפָּנָיו כָּל הָאָרֶץ. הַ\"ס מִפָּנָיו, ה\"ס רָשִׁים קַמֵּיהּ כָּל נְקוּדִין דְּכָל עָלְמָא דְּאִנּוּן שִׁתִּין וְחָמֵשׁ, כְּחוּשְׁבַּן ה\"ס, שִׁתִּין אִנּוּן וְחָמֵשׁ אִנּוּן, וְכֻלְהוּ רָשִׁים קַמֵּיהּ כַּד בְּרָא עָלְמָא. בְגִין כָּךָ יְקָרָא דְּקוּדְשָׁא בְּרִיךָ הוּא לָאו אִיהוּ אֶלָּא לְאִנּוּן דְּיָדְעִין אָרְחוֹי וּמְהֲכִין בָּהּ בְּאוֹרַח קְשׁוֹט כְּדְקָא יְאוּתּ.","אַדְהָכִי דְּהֲוָה מִשְׁתָּעֵי בַּהֲדַיְיהוּ, אֲתָּא נוּרָא וְאַסְחַר לֵיהּ, וְאִנּוּן יָתְּבוּ לְבַר. שְׁמָעוּ חַד קָלָא דְּהֲוָה אָמַר אִי קַדִּישָׁא הֱבִיאֲנִי הַמֶּלֶךָ חֲדָרָיו בְּכָל אִנּוּן אִידְרִין דְּסָבָא דְּאַנְפִּין עוּלֵימָא קַדִּישָׁא (נ\"א עולימתא קדישתא) דְאִתְּמְסָרוּ מַפְּתְּחָן דִּלְהוֹן בִּידֵיהּ, וְכֻלְהוּ מְתַּקְנָן לָךָ וּלְאִנּוּן דִּבְגִינָךָ. וּבְחַיָּיךָ קַדִּישָׁא כָּל חֵילָא דִשְׁמַיָא נָגִילָה ונִשְׂמְחָה בָךָ.","כַּד חָמוּ אִלֵּין הָכִי, אִזְדַּעְזעְוּ, וּדְחִילוּ סָגִּי נָפַּל עֲלַיְיהוּ, אֲמְרֵי, לֵיתּ אֲנַן חַזְיָין לְהַאי, נִפּוּק מִכָּאן וְנֵהַךָ לְאוֹרְחִין, (אזלו) יַתְּבוּ תַּמָּן כּל הַהוּא יוֹמָא וְלָא יָכִילוּ לְמֶחֱמֵי לֵיהּ, וְאָמְרוּ לֵיתּ רְעוּתָּא דְקוּדְשָׁא בְּרִיךָ הוּא דְּנֵיתִּיב הָכָא נָפְּקוּ מִתַּמָּן וְאַזְלֵי.","עַד דְּהֲווּ אָזְלֵי פָּתַח רַבִּי חִיָּיא וְאָמַר (תהילים ק״ג:כ׳) בָּרְכוּ יְיָ מַלְאָכָיו גִּבּוֹרֵי כֹחַ עוֹשֵׂי דְבָרוֹ וְגו'. זַכָּאִין אִנּוּן יִשְׂרָאֵל מִכָּל שְׁאָר עַמִּין דְּעָלְמָא דְּקוּדְשָׁא בְּרִיךָ הוּא אִתְּרָעֵי בְּהוּ מִכָּל שְׁאָר עַמִּין וְעֲבַד לוֹן חוּלְקֵיהּ וְאַחְסַנְתֵּיהּ, וְעַל דָּא יָהִיב לוֹן אוֹרַיְיתָּא קַדִּישָׁא, בְּגִין דְּכֻלְהוּ הֲווּ בִּרְעוּתָּא חֲדָא עַל טוּרָא דְסִינַי ואַקְדִּימוּ עֲשִׂיָּה לִשְׁמִיעָה.","כֵּיוָן דְּאַקְדִּימוּ עשיָּה לִשְׁמִיעָה קְרָא קוּדְשָׁא בְּרִיךָ הוּא לְפַּמַּלְיָא דִילֵיהּ אָמַר לוֹן עַד הָכָא אַתּוּן הֲוִיתּוּן יְחִידָאִין קַמָּאי בְּעָלְמָא, מִכָּאן וּלְהָלְאָה הָא בָּנַי בְּאַרְעָא חֲבֵרִים בַּהֲדַיְיהוּ בְּכלָּא. לֵיתּ לְכוּ רשוּ לְקַדְשָׁא שְׁמִי עַד דְּיִשְׂרָאֵל יִתְּחַבְּרוּן בַּהֲדַיְיכוּ בְּאַרְעָא, וְכֻלְהוּ תֶּהֱווֹן כְּחֲדָא חֲבֵרִים לְקַדְּשָׁא שְׁמִי, בְּגִין דְּאַקְדִּימוּ עֲשִׂיָּה לִשְׁמִיעָה כְּגַוְונא דְּמַלְאֲכֵי עִלָּאֵי עָבְדֵי בִּרְקִיעָא דִּכְתִּיב בָּרְכוּ יְיָ מַלְאָכָיו גִּבּוֹרֵי כֹחַ עוֹשֵׂי דְּבָרוֹ לִשְׁמוֹעַ בְּקוֹל דְּבָרוֹ. עוֹשֵׂי דְּבָרוֹ בְּקַדְמִיתָּא וּלְבָתַּר לִשְׁמֹע.","דָּבָר אַחֵר בָּרְכוּ יְיָ מַלְאָכָיו. אִלֵּין אִנּוּן צַּדִּיקַיָא בְּאַרְעָא דְּאִנּוּן חֲשׁוּבִין קַמֵּי קוּדְשָׁא בְּרִיךָ הוּא כְּמַלְאֲכֵי עִלָּאֵי בִּרְקִיעָא, בְּגִין דְּאִנּוּן גִּבּוֹרֵי כֹחַ דְּמִתְּגַּבְּרֵי עַל יִצְּרֵיהוֹן כְּגִבָּר טַב דְּמִתְּגַּבֵּר עַל שַׂנְאֵיהּ. לִשְׁמֹעַ בְּקוֹל דְּבָרוֹ. דְּזָכָאן בְּכָל יוֹמָא לְמִשְׁמַע קָלָא מִלְּעֵילָא בְּשַׁעֲתָּא דְּאִצְּטְרִיכוּ.","הַשְׁתָּא מָאן יָכִיל לְמֵיקַם בַּהֲדַיְיהוּ דְּאִנּוּן קַדִּישִׁין עֶלְיוֹנִין, זַכָּאִין אִנּוּן דְּיָכְלֵי לְמֵיקַם קַמַּיְיהוּ, זַכָּאִין אִנּוּן דְּיָכְלֵי (ד\"א ל\"ג למאן דייכול) לְאִשְׁתְּזָבָא מִקַּמַּיְיהוּ, אַשְׁגָּחוּתָּא דְּקוּדְשָׁא בְּרִיךָ הוּא עֲלַיְיהוּ בְּכָל יוֹמָא, הֵיךָ אֲנַן יְכִילָן לְמֵיעַל קַמַּיְיהוּ. וְעַל דָּא כְּתִּיב, (תהילים ס״ה:ה׳) אַשְׁרֵי תִּבְחַר וּתְּקָרֵב יִשְׁכֹּן חֲצֵּרֶיךָ וּכְתִּיב (תהילים פ״ד:ו׳) אַשְׁרֵי אָדָם עוֹז לוֹ בָךָ וְגו', (עד כאן סתרי תורה):","וַיֹּאמֶר אַבְרָם אֲדֹנָי יהִֹוִ\"ה מַה תִּתֶּן לִי. אדנ\"י אל\"ף דל\"ת נו\"ן יו\"ד. אֱלהִים יו\"ד ה\"א וי\"ו ה\"א. (נ\"א אלהים יהוה בניקוד אלהים) אֶלָּא רָזָא דְמִלָּה, חִבּוּרָא דִּתְרֵין עָלְמִין כְּחֲדָא עַלְמָא תַּתָּאָה וְעַלְמָא עִלָּאָה.","מַה תִּתֶּן לִי וְאָנֹכִי הוֹלֵךְ עֲרִירִי. דְּלֵית לִי בַּר, וְאוֹלִיפְנָא דְּכָל מָאן דְּלֵית לֵיהּ בְּרָא בְּהַאי עָלְמָא אִקְרֵי עֲרִירִי כְּמָא דְאַתְּ אָמֵר, (ויקרא כ׳:כ״א) עֲרִירִים יִהְיוּ. וְאַבְרָהָם עַל מָה אָמַר מִלָּה דָא דְּאָמַר מַה תִּתֶּן לִי. כִּבְיָכוֹל כְּאִילוּ לא הֶאֱמִין בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא.","אֶלָּא אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא אָנֹכִי מָגֵן לָךְ בְּהַאי עָלְמָא. שְׂכָרְךָ הַרְבֵּה מְאֹד בְּעָלְמָא דְאָתֵי. מִיָּד אִתְעַר אַבְרָהָם בְּרָזָא דְּחָכְמְתָא וְאָמַר מַה תִּתֶּן לִי, דְּהָא יְדַעְנָא דְּלָא קַבִּיל אֲגַר לְמֵיעַל בֵּיהּ בְּהַהוּא עָלְמָא בַּר נָשׁ דְּלָא אוֹלִיד בַּר, וְעַל דָּא אָמַר מַה תִּתֶּן לִי וְאָנֹכִי הוֹלֵךְ עֲרִירִי, דְּהָא לָא תִּתֶּן לִי דְּלָא זָכִינָא בֵּיהּ. מִכָּאן דְּבַּר נָשׁ דְּלָא זָכֵי בִּבְנִין בְּהַאי עָלְמָא לָא זָכֵי בְּהַהוּא עָלְמָא לְאֲעָלָא גּוֹ פַּרְגּוֹדָא."],[[0,"פתח ואמר וכו':","פתח ואמר וה' בהיכל קדשו הס מפניו כל הארץ. כאשר רצה הקב\"ה. שה\"ס הבינה, לברוא העולם, שה\"ס זו\"ן, הנקראים שמים וארץ הסתכל תוך המחשבה שה\"ס חכמה, סוד התורה, ורשם רשומות דהיינו שרשם רשומות והמשיך אור החכמה אל זו\"ן, שה\"ס שמים וארץ, והעולם לא היה יכול לעמוד, כלומר, שלא יכלו לקבל האור מחמת כח הצמצום והדין שהיה בהמלכות. עד שברא תשובה, שהיא היכל פנימי ועליון, וסוד סתום. \u0003עד שברא תשובה,\u0004 פירושו עד שהעלה המלכות לבינה, שאז נקראת הבינה בשם תשובה, שנתמעטה הבינה, בסוד \u0003נקודה בהיכליה,\u0004 שבזה נתמתקה מדת הדין שבמלכות בהבינה, ונעשית ראויה לקבל אור החכמה. כמ\"ש לעיל. (בראשית א' דף י\"ב ד\"ה וכד אתתקן ע\"ש כל ההמשך) וזהו שאומר \u0003והוא היכל פנימי ועליון וסוד סתום.\u0004 כי ההיכל נסתם בסוד ה \u0003י'\u0004 שנכנסה ב \u0003אור\u0004 ההיכל, וה \u0003אור\u0004 נעשה ל \u0003אויר,\u0004 כמ\"ש שם בארוכה."],[0,"ותמן אתרשימו וכו':","ושם, בהיכל הנזכר, נתרשמו ונצטיירו האותיות שהם זו\"ן, בחקיקותיהם. כלומר שנעשו ראוים לקבל המוחין משם."],[1,"כיון דאתברי דא וכו':","כיון שנברא היכל הזה, בסוד נקודה בהיכליה. כנ\"ל, היה מסתכל בהיכל הזה, ורשם לפניו ציורים, דהיינו מוחין, של כל העולם. שכל מדות המוחין הם מכאן, כי כשרוצה להשפיע מוחין דקטנות לזו\"ן מעלה הי' לאור ההיכל ונעשה אויר, שפירושו מוחין דו\"ק ורוח. וכשרוצה להשפיע ג\"ר מוציא ה \u0003י'\u0004 מן \u0003אויר\u0004 ההיכל וחזר להיות \u0003אור.\u0004 וזסו\"ה ו \u0003ה' בהיכל קדשו,\u0004 ו \u0003ה'\u0004 ה\"ס הבינה, בהיכל קדשו, היינו היכל הנזכר, \u0003נקודה בהיכליה.\u0004 וז\"ש, \u0003דכתיב הם מפניו כל הארץ\u0004 שפירושו \u0003רשים קמיה רשימין וציורין דכל עלמא.\u0004 רשימין, הם מוחין דו\"ק. וציורין, הם מוחין דג\"ר. דכל עלמא, היינו דזו\"ן, הנקראים עולם, דהיינו כמבואר שבהיכל זה תלוים, מדידות כל המוחין."],[1,"בעי למברי שמים וכו':","רצה לברוא השמים, שהם ז\"א, מה עשה, הסתכל באור הראשון, דהיינו בהיכל הראשון, שה\"ס או\"א (כנ\"ל ב\"א דף ז' אות ג') ונתעטף בו וברא שמים. שכתוב עוטה אור כשלמה ואח\"כ נוטה שמים כיריעה. פירוש. ה \u0003י',\u0004 שה\"ס המלכות, שנכנסה לאור ההיכל ונעשה אויר, הוא נקרא אז, \u0003אור מעוטף,\u0004 כנ\"ל (בראשית א' דף ט' ד\"ה ועביד.) ונעשה אז בבינה ב' היכלות. היכל א' בג\"ר דבינה, ונק' או\"א עלאין. והוא נשאר תמיד \u0003אור מעוטף,\u0004 כי ה \u0003י'\u0004 אינה יוצאת מן האויר של היכל הזה. והיכל ב' נעשה בז\"ת דבינה, ונק' ישסו\"ת. ובעת שרוצה להשפיע חכמה מוציא ה \u0003י'\u0004 מאויר היכל הזה, הב', וחוזר להיות \u0003אור\u0004 ואז משפיע אור החכמה. ונודע שז\"א הוא תמיד בבחינת חסדים מכוסים כמו או\"א. שה\"ס היכל א'. וז\"ש \u0003עוטה אור כשלמה,\u0004 שמתחילה מתעטף בסוד אור מעוטף מן או\"א עלאין, ואח\"כ נוטה שמים כיריעה, שהוא ז\"א. כי ז\"א תמיד \u0003באור מעוטף\u0004 כמבואר."],[2,"אסתכל למעבד וכו':","נסתכל לעשות עולם התחתון, שהיא נוקבא דז\"א, הצריכה לאור החכמה שאינו מקובל מהיכל הא' הנ\"ל עשה היכל אחר, הוא היכל ישסו\"ת (כנ\"ל בדבור הסמוך) שבו יוצא ה \u0003י' מאויר,\u0004 ונכנס בו, וממנו הסתכל ורשם לפניו כל העולמות שלמטה דהיינו כל מדות המוחין שהם צריכים וברא אותם. וזהו שכתוב ו \u0003ה' בהיכל קדשו,\u0004 דהיינו בהיכל הב', \u0003הס מפניו כל הארץ: ה\"ס\u0004 מקובלים \u0003מפניו.\u0004 כלומר, מספר ה\"ס רשם לפניו, שהוא מספר כל הנקודות שהן הספירות, שבכל העולם שהיא הנוקבא. שהם ששים וחמש נקודות כמספר \u0003ה\"ס\u0004. ששים המה הם ששה ספירות חג\"ת נה\"י, שכל אחד כלול מעשר. וחמש אינין, היינו חצי המלכות, שחמש האחרונות שמחזה ולמטה חסרים לה (כנ\"ל בראשית ב' דף קנ\"ח ד\"ה ולא יקשה ע\"ש), וכל אלו ס\"ה נקודות של הנוקבא רשם לפניו להשפיע לה בעת שברא העולם. שהיא הנוקבא. ומה שחושב לעיל. (ב\"ב דף קנ\"ח), מ\"ה זיני נהורין בהנוקבא, וכאן חושב ס\"ה נקודות. הוא כי שם מדבר בערך קבלתה של הנוקבא מחמשים שערי בינה. וכאן מדבר בערך קבלתה מבחינת ז\"ס תחתוניות חג\"ת נהי\"מ. וכתר נתבאר כל הענין לעיל ואין להאריך בו כאן. \u0003בג\"כ יקרא וכו':\u0004 לפיכך כבודו של הקב\"ה דהיינו השכינה, אינה אלא לאותם היודעים דרכיו ומהלכים בהם בדרך האמת כראוי. כלומר, שלא יעוררו זווג במקום שמחזה ולמטה של המלכות, כי מטעם חסרון ה' נקודות הנזכרים אין שם מקום זווג."],[3,"אדהכי דהוה וכו':","עוד שהיה מדבר עמהם, באה אש והקיפה אותו, והם נשארו יושבים מבחוץ. שמעו קול אחד שהיה אומר: אהה קדוש, הביאני המלך חדריו, בכל אותם החדרים, שמפתחותיהם נמסרו בידו של נשוא הפנים העלם הקדוש, דהיינו מטטרון הנק' נער. וכולם מתוקנים לך. ולאלו הזוכים בשבילך. ובחייך קדוש, כל צבאות השמים, נגילה ונשמחה בך. וקול הזה היה של השכינה. בספרים ישנים הגירסא, דסבא דאנפין עולימא קדישא, והוא ט\"ס וצריך לומר דסבר דאנפין וכו'. שפירושו נשוא פנים."],[4,"כד חמו אלין וכו':","כאשר אלו ראו את זה, נזדעזעו ופחד גדול נפל עליהם. אמרו אין אנו ראוים לזה. נצא מכאן ונלך לדרכנו. ישבו שם כל אותו היום, ולא יכלו לראות אותו. ואמרו, אין רצונו של הקב\"ה שנשב כאן. יצאו משם, והלכו."],[5,"עד דהוו אולי וכו':","עוד שהיו מהלכים, פתח ר' חייא ואמר. ברכו ה' מלאכיו וגו' עושי דברו לשמוע בקול דברו. אשרי הם ישראל מכל שאר אומות העולם, שהקב\"ה בחר בהם מכל שאר העמים. ועשה אותם לחלקו ונחלתו. ועל כן נתן להם התורה הקדושה, משום שכולם היו ברצון אחד על הר סיני, והקדימו עשיה לשמיעה. שאמרו נעשה קודם לנשמע. (שמות כ\"ד ז')."],[6,"כיון דאקדימו וכו':","כיון שהקדימו עשיה לשמיעה, קרא הקב\"ה לפמליא שלו דהיינו למלאכים, אמר להם: עד כאן הייתם לפני יחידים בעולם, מכאן ואילך, הנה בני בארץ חברים עמכם לכל דבר, אין לכם רשות לקדש את שמי עד שישראל יתחברו עמכם בארץ, וכלכם יחד תהיו חברים לקדש את שמי. משום שהקדימו עשיה לשמיעה כמו מלאכים העליונים עושים ברקיע, שכתוב ברכו ה' מלאכיו וגו' עושי דברו מתחילה, ואחר כך לשמוע. (ופנימיות הדברים עי' בהקדמת הזהר דף ט' ד\"ה נשמע)."],[7,"דבר אחר, ברכו וכו':","פירוש אחר על ברכו ה' מלאכיו, אלו הם הצדיקים בארץ, שהם חשובים לפני הקב\"ה כמו מלאכים העליונים ברקיע, משום שהם גבורי כח, שמתגברים על יצרם כגבור המתגבר על שונאיו \u0003לשמוע בקול דברו,\u0004 היינו, שזוכים בכל יום לשמוע קול ממרום ובכל שעה שצריכים."],[8,"השתא מאן וכו':","עתה, מי יוכל לעמוד עמהם, עם אלו הקדושים העליונים. אשריהם היכולים לעמוד לפניהם. אשריהם היכולים להנצל מהם. השגחתו של הקב\"ה עליהם בכל יום. איך אנו יכולים לבא לפניהם כל זה אמר ר' חייא בהפלגת מעלת ר' אלעזר, ועל שלא יכלו להיות עמו. ועל כן כתוב, אשרי תבחר ותקרב ישכון חצריך. וכתוב אשרי אדם עוז לו בך."],[9,"ת\"ח אנכי מגן לך: אנכי,","זה הוא מדרגה הראשונה, שנאחז בה מתחילה. ויאמר אברם אדני הוי\"ה מה תתן לי, וכתוב הוי\"ה בניקוד אלקים. \u0003אדני\u0004 במילואו הוא אלף דלת נון יוד, שה\"ס הנוקבא. הוי\"ה בניקוד אלקים, הוא הויה במילוא כזה, \u0003יוד הי ואו הי.\u0004 (כצ\"ל) שה\"ס בינה. והוקשה לו, מה הטעם שכתוב ב' השמות הללו במאמר אחד. ועל זה אומר, אלא סוד הדבר, הוא חיבור של שני העולמות ביחד, עולם העליון ועולם התחתון. כי אדני הוא עולם התחתון שהוא הנוקבא. הוי\"ה בניקוד אלקים הוא עולם העליון שהוא בינה. ובמאמר הזה נתיחדו שתיהם יחד."],[10,"מה תתן לי ואנכי הולך ערירי:","היינו שאין לי בן, ולמדנו שכל מי שאין לו בן בעולם הזה נקרא ערירי. כמו שאתה אומר ערירים יהיו. ומקשה ואברהם למה אמר דבר זה, שאמר מה תתן לי, כביכול כמו שלא היה מאמין בו בהקב\"ה."],[11,"אלא אמר וכו':","אלא אמר לו הקב\"ה אנכי מגן לך בעולם הזה, שכרך הרבה מאד בעולם הבא, מיד נתעורר אברהם בסוד החכמה ואמר, מה תתן לי, כי אני יודע שאיש שלא הוליד בן אינו מקבל שכר שיבוא בו לעולם הבא. ועל כן אמר, מה תתן לי ואנכי הולך ערירי: כי לא תתן לי, שלא זכיתי בו. מכאן שאדם שלא זכה לבנים בעולם הזה, אינו זוכה בעולם הבא לכנוס למחיצתו של הקב\"ה."]],[[0,"","פָּתַח וְאָמַר, (חבקוק ב) וַה' בְּהֵיכַל קָדְשׁוֹ הַס מִפָּנָיו כָּל הָאָרֶץ. כְּשֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְרֹא אֶת הָעוֹלָם, הִסְתַּכֵּל בְּתוֹךְ הַמַּחֲשָׁבָה סוֹד הַתּוֹרָה וְרָשַׁם רִשּׁוּמִים, וְלֹא הָיָה יָכוֹל לַעֲמֹד, עַד שֶׁבָּרָא הַתְּשׁוּבָה, שֶׁהִיא הֵיכָל פְּנִימִי עֶלְיוֹן וְסוֹד נִסְתָּר, וְשָׁם נִרְשְׁמוּ וְהִצְטַיְּרוּ הָאוֹתִיּוֹת בַּחֲקִיקוֹתֵיהֶן."],[1,"","כֵּיוָן שֶׁזֶּה נִבְרָא, הָיָה מִסְתַּכֵּל בַּהֵיכָל הַזֶּה, וְרוֹשֵׁם לְפָנָיו צִיּוּרִים שֶׁל כָּל הָעוֹלָם, שֶׁכָּתוּב הַס מִפָּנָיו כָּל הָאָרֶץ. רָשַׁם לְפָנָיו רִשּׁוּמִים וְצִיּוּרִים שֶׁל כָּל הָעוֹלָם. רָצָה לִבְרֹא שָׁמַיִם, מֶה עָשָׂה? הִסְתַּכֵּל בָּאוֹר הָרִאשׁוֹן וְהִתְעַטֵּף בּוֹ וּבָרָא שָׁמַיִם, שֶׁכָּתוּב (תהלים קד) עֹטֶה אוֹר כַּשַּׂלְמָה, וְאַחַר כָּךְ נוֹטֶה שָׁמַיִם כַּיְרִיעָה."],[2,"","הִסְתַּכֵּל לַעֲשׂוֹת הָעוֹלָם הַתַּחְתּוֹן, עָשָׂה הֵיכָל אַחֵר וְנִכְנַס בּוֹ, וּמִמֶּנּוּ הִסְתַּכֵּל וְרָשַׁם לְפָנָיו אֶת כָּל הָעוֹלָמוֹת לְמַטָּה וּבָרָא אוֹתוֹ. זֶהוּ שֶׁכָּתוּב וַה' בְּהֵיכַל קָדְשׁוֹ הַס מִפָּנָיו כָּל הָאָרֶץ. הַ\"ס מִפָּנָיו - ה\"ס רָשַׁם לְפָנָיו כָּל הַנְּקֻדּוֹת שֶׁל כָּל הָעוֹלָם, שֶׁהֵם שִׁשִּׁים וְחָמֵשׁ כְּחֶשְׁבּוֹן ה\"ס. שִׁשִּׁים וְחָמֵשׁ הֵן. וְכֻלָּן רָשַׁם לְפָנָיו כְּשֶׁבָּרָא אֶת הָעוֹלָם. מִשּׁוּם כָּךְ כְּבוֹדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא אֵינוֹ אֶלָּא לְאוֹתָם שֶׁיּוֹדְעִים דְּרָכָיו וְהוֹלְכִים בָּהֶם בְּדֶרֶךְ אֱמֶת כָּרָאוּי."],[3,"","בֵּינְתַיִם שֶׁהָיָה מְדַבֵּר עִמָּם, בָּאָה אֵשׁ וְהִקִּיפָה אוֹתוֹ, וְהֵם יָשְׁבוּ בַּחוּץ. שָׁמְעוּ קוֹל אֶחָד שֶׁהָיָה אוֹמֵר: אֵי קָדוֹשׁ, הֱבִיאַנִי הַמֶּלֶךְ חֲדָרָיו, בְּכָל אוֹתָם הַחֲדָרִים שֶׁל פְּנֵי הַזָּקֵן, הָעֵלֶם הַקָּדוֹשׁ (העלמה הקדושה) שֶׁנִּמְסְרוּ הַמַּפְתְּחוֹת שֶׁלָּהֶם בְּיָדוֹ, וְכֻלָּם מְתֻקָּנִים לְךְ וּלְאוֹתָם שֶׁבִּשְׁבִילְךְ. וּבְחַיֶּיךְ הַקְּדוֹשִׁים, כָּל צְבָא הַשָּׁמַיִם נָגִילָה וְנִשְׂמְחָה בָךְ."],[4,"","כְּשֶׁאֵלֶּה רָאוּ כָּךְ, הִזְדַּעְזְעוּ, וּפַחַד רַב נָפַל עֲלֵיהֶם. אָמְרוּ, אֵינֶנּוּ רְאוּיִים לָזֶה, נֵצֵא מִכָּאן וְנֵלֵךְ לְדַרְכֵּנוּ. (הלכו). יָשְׁבוּ שָׁם כָּל אוֹתוֹ יוֹם וְלֹא יָכְלוּ לִרְאוֹת אוֹתוֹ, וְאָמְרוּ, אֵין רְצוֹנוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁנֵּשֵׁב כָּאן. יָצְאוּ מִשָּׁם וְהָלְכוּ."],[5,"","בְּעוֹדָם הוֹלְכִים, פָּתַח רַבִּי חִיָּיא וְאָמַר, (שם קג) בָּרְכוּ ה' מַלְאָכָיו גִּבֹּרֵי כֹחַ עֹשֵׂי דְבָרוֹ וְגוֹ'. אַשְׁרֵיהֶם יִשְׂרָאֵל מִכָּל שְׁאָר הָעַמִּים שֶׁל הָעוֹלָם, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָהֶם מִכָּל שְׁאָר הָעַמִּים וְעָשָׂה אוֹתָם חֶלְקוֹ וְנַחֲלָתוֹ, וְעַל כֵּן נָתַן לָהֶם תּוֹרָה קְדוֹשָׁה, מִשּׁוּם שֶׁכֻּלָּם הָיוּ בְּרָצוֹן אֶחָד עַל הַר סִינַי וְהִקְדִּימוּ עֲשִׂיָּה לִשְׁמִיעָה."],[6,"","כֵּיוָן שֶׁהִקְדִּימוּ עֲשִׂיָּה לִשְׁמִיעָה, קָרָא הַקָּדוֹשׁ בָּרוּךְ הוּא לַפַּמַלְיָה שֶׁלּוֹ. אָמַר לָהֶם, עַד כָּאן אַתֶּם הֱיִיתֶם יְחִידִים לְפָנַי בָּעוֹלָם, מִכָּאן וָהָלְאָה הִנֵּה בָּנַי בָּאָרֶץ חֲבֵרִים עִמָּהֶם בַּכֹּל. אֵין לָכֶם רְשׁוּת לְקַדֵּשׁ אֶת שְׁמִי עַד שֶׁיִּשְׂרָאֵל יִתְחַבְּרוּ עִמָּכֶם בָּאָרֶץ, וְכֻלְּכֶם תִּהְיוּ יַחַד חֲבֵרִים לְקַדֵּשׁ אֶת שְׁמִי, מִשּׁוּם שֶׁהִקְדִּימוּ עֲשִׂיָּה לִשְׁמִיעָה כְּמוֹ שֶׁעוֹשִׂים הַמַּלְאָכִים הָעֶלְיוֹנִים בָּרָקִיעַ, שֶׁכָּתוּב בָּרְכוּ ה' מַלְאָכָיו גִּבֹּרֵי כֹחַ עֹשֵׂ\"י דְבָרוֹ לִשְׁמֹ\"עַ בְּקוֹל דְּבָרוֹ. עֹשֵׂי דְבָרוֹ בַּהַתְחָלָה, וְאַחַר כָּךְ לִשְׁמֹעַ."],[7,"","דָּבָר אַחֵר בָּרְכוּ ה' מַלְאָכָיו - אֵלּוּ אוֹתָם הַצַּדִּיקִים בָּאָרֶץ שֶׁהֵם חֲשׁוּבִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כַּמַּלְאָכִים הָעֶלְיוֹנִים בָּרָקִיעַ, מִשּׁוּם שֶׁהֵם גִּבּוֹרֵי כֹחַ שֶׁמִּתְגַּבְּרִים עַל יִצְרָם כְּגִבּוֹר טוֹב שֶׁמִּתְגַּבֵּר עַל שׂוֹנְאוֹ. לִשְׁמֹעַ בְּקוֹל דְּבָרוֹ - שֶׁזּוֹכִים בְּכָל יוֹם לִשְׁמֹעַ קוֹל מִלְמַעְלָה בְּשָׁעָה שֶׁמִּצְטָרְכִים."],[8,"","כָּעֵת מִי יָכוֹל לַעֲמֹד עִם אוֹתָם שֶׁהֵם קְדוֹשִׁים עֶלְיוֹנִים? אַשְׁרֵי אוֹתָם שֶׁיְּכוֹלִים לַעֲמֹד לִפְנֵיהֶם. אַשְׁרֵי אוֹתָם שֶׁיְּכוֹלִים (למי שיוכל) לְהִנָּצֵל מִלִּפְנֵיהֶם. הַשְׁגָּחָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא עֲלֵיהֶם בְּכָל יוֹם. אֵיךְ אָנוּ יְכוֹלִים לְהִכָּנֵס לִפְנֵיהֶם? וְעַל זֶה כָּתוּב (שם סה) אַשְׁרֵי תִּבְחַר וּתְקָרֵב, וְכָתוּב (שם פד) אַשְׁרֵי אָדָם עוֹז לוֹ בָךְ וְגוֹ'. (עד כאן סתרי תורה)."],[9,"","וַיֹּאמֶר אַבְרָם אֲדנָי יֱהִֹוִ\"ה מַה תִּתֶּן לִי. אֲדנָ\"י - אָלֶ\"ף דָּלֶ\"ת נוּ\"ן יוֹ\"ד. אֱלֹהִים - יוֹ\"ד הֵ\"א וָי\"ו הֵ\"א (אלהים יהוה בנקוד אלהים). אֶלָּא סוֹד הַדָּבָר - חִבּוּר שֶׁל שְׁנֵי עוֹלָמוֹת יַחַד, הָעוֹלָם הַתַּחְתּוֹן וְהָעוֹלָם הָעֶלְיוֹן."],[10,"","מַה תִּתֶּן לִי וְאָנֹכִי הוֹלֵךְ עֲרִירִי, שֶׁאֵין לִי בֵּן. וְלָמַדְנוּ, שֶׁכָּל מִי שֶׁאֵין לוֹ בֵּן בָּעוֹלָם הַזֶּה נִקְרָא עֲרִירִי, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא כ) עֲרִירִים יִהְיוּ. וְאַבְרָהָם, עַל מָה אָמַר הַדָּבָר הַזֶּה שֶׁאָמַר מַה תִּתֶּן לִי? כִּבְיָכוֹל לֹא הֶאֱמִין בַּקָּדוֹשׁ- בָּרוּךְ-הוּא?"],[11,"","אֶלָּא אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, אָנֹכִי מָגֵן לָךְ - בָּעוֹלָם הַזֶּה, שְׂכָרְךְ הַרְבֵּה מְאֹד - בָּעוֹלָם הַבָּא. מִיָּד הִתְעוֹרֵר אַבְרָהָם בְּסוֹד הַחָכְמָה וְאָמַר מַה תִּתֶּן לִי, שֶׁהֲרֵי יָדַעְתִּי שֶׁלֹּא מְקַבֵּל שָׂכָר לְהִכָּנֵס לָעוֹלָם הַהוּא אָדָם שֶׁלֹּא מוֹלִיד בֵּן. וְעַל זֶה אָמַר מַה תִּתֶּן לִי וְאָנֹכִי הֹלֵךְ עֲרִירִי. שֶׁהֲרֵי לֹא תִתֵּן לִי, שֶׁלֹּא זָכִיתִי בוֹ. מִכָּאן שֶׁאָדָם שֶׁלֹּא זוֹכֶה בְּבָנִים בָּעוֹלָם הַזֶּה, לֹא זוֹכֶה בָּעוֹלָם הַהוּא לְהִכָּנֵס לְתוֹךְ הַפַּרְגּוֹד."]]],[["וְאַבְרָהָם הֲוָה חָמֵי בְּאִצְטַגְנִינוּת דִּילֵיהּ דְּלָא יוֹלִיד. מַה כְּתִיב וַיּוֹצֵא אוֹתוֹ הַחוּצָה וְגו'. (אמר ליה קודשא בריך הוא צא מאצטגנינות דילך אברם אינו מוליד אברהם מוליד). אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לָא תִסְתַּכַּל בְּהַאי אֶלָּא בְּרָזָא דִשְׁמִי יְהֵא לָךְ בַּר. הֲדָא הוּא דִכְתִיב כֹּה יִהְיֶה זַרְעֶךָ. רָזָא דִשְׁמָא קַדִּישָׁא דְּמִתַּמָּן אִתְקַשַּׁר לֵיהּ בְּדָא (ברא) וְלָא מִסִּטְרָא אָחֳרָא.","כֹּה דְּהוּא תַּרְעָא לִצְלוֹתָא, בָּהּ יִשְׁכַּח בְּרָכָה, בָּהּ יִשְׁכַּח בַּר נָשׁ שְׁאִלְתֵּיהּ. כֹּה הַהוּא סִטְרָא דְאַתְיָיא מִסִּטְרָא דִגְבוּרָה, דְּהָא מִסִּטְרָא דִגְבוּרָה קָא אֲתָא יִצְחָק. וְהַהוּא סִטְרָא דִגְבוּרָה כֹּה אִקְרֵי דְּמִתַּמָּן אַתְיָין אִיבִּין וּפֵירֵי לְעָלְמָא, וְלָא מִסִּטְרָא דִּלְתַתָּא דְּכֹכְבַיָא וּמַזָּלוֹת.","כְּדֵין וְהֶאֱמִין בַּיְיָ. אִתְדָּבַּק לְעֵילָא וְלָא אִתְדָּבַּק לְתַתָּא. וְהֶאֱמִין בַּיְיָ וְלָא בְּכֹכְבַיָא וּמַזָּלֵי. וְהֶאֱמִין בַּיְיָ, דְּאַבְטַח לֵיהּ דְּיַסְגֵּי אַגְרֵיהּ לְעָלְמָא דְּאָתֵי. וְהֶאֱמִין בַּיְיָ, בְּהַהוּא דַרְגָּא דְּאִתְיְיהִיב לֵיהּ דְּמִתַּמָּן יֵיתֵי לֵיהּ זַרְעָא לְאוֹלָדָא בְּעָלְמָא. וַיַּחְשְׁבֶהָ לוֹ צְדָקָה.","וַיַּחְשְׁבֶהָ לוֹ דְּאַף עַל גַּב דְּאִיהִי דִינָא כְּאִילוּ הִיא רַחֲמֵי הַאי כֹּה. דָּבָר אַחֵר וַיַּחְשְׁבֶהָ לוֹ צְדָקָה, דְּקָשִׁיר קִשְׁרָא עִלָּאָה בְּתַתָּאָה לְחַבְּרָא לוֹן כְּחֲדָא.","תָּא חֲזֵי, הָא אִתְעָרוּ אַבְרָהָם מוֹלִיד אַבְרָם אֵינוֹ מוֹלִיד, וְכִי תֵימָא דְּהָא אוֹלִיד יִשְׁמָעֵאל בְּעוֹד דְּאִיהוּ אַבְרָם. אֶלָּא הַהוּא בְּרָא דְּאַבְטַח לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לָא אוֹלִיד בְּעוֹד דְּאִיהוּ אַבְרָם, דְּהָא בְּעוֹד דְּאִיהוּ אַבְרָם אוֹלִיד לְתַתָּא, כֵּיוָן דְּאִתְקְרֵי אַבְרָהָם וְעָאל בַּבְּרִית כְּדֵין אוֹלִיד לְעֵילָא, וּבְגִין כָּךְ אַבְרָם אֵינוֹ מוֹלִיד בְּקִשּׁוּרָא עִלָּאָה, אַבְרָהָם מוֹלִיד כְּמָה דְאֲמָרָן, וְאִתְקַשַּׁר לְעֵילָא בְּיִצְחָק:","וַיְהִי אַבְרָם בֶּן תִּשְׁעִים שָׁנָה וְתֵשַׁע שָׁנִים וְגו'. רַבִּי אַבָּא פָּתַח (שמואל ב כ״ב:ל״ב) כִּי מִי אֵל מִבַּלְעֲדֵי יְיָ וּמִי צוּר וְגו'. דָּוִד מַלְכָּא אָמַר הַאי קְרָא (תהילים י״ח:ל״ב) כִּי מִי אֵל מִבַּלְעֲדֵי יְיָ. מָאן הוּא שַׁלִּיטָא אוֹ מְמַנָּא דְּיְכוּל לְמֶעְבַּד מִדִּי מִבַּלְעֲדֵי יְיָ, אֶלָּא מַה דְּאִתְפַּקַּד מֵעִם קוּדְשָׁא בְּרִיךְ הוּא, בְּגִין דְּכֻלְהוּ לָא בִּרְשׁוּתַיְיהוּ קָיְימֵי וְלָא יָכְלֵי לְמֶעְבַּד מִדִּי. וּמִי צוּר, וּמַאן אִיהוּ תַּקִּיף דְּיָכוֹל לְמֶעְבַּד תּוּקְפָא וּגְבוּרָה מִגַּרְמֵיהּ מִבַּלְעֲדֵי אֱלהֵינוּ. אֶלָּא כֻּלְהוּ בִּידָא דְּקוּדְשָׁא בְּרִיךְ הוּא וְלָא יָכִיל לְמֶעְבַּד מִדִּי בַּר בִּרְשׁוּתֵיהּ.","דָּבָר אַחֵר כִּי מִי אֵל מִבַּלְעֲדֵי יְיָ. דְּקוּדְשָׁא בְּרִיךְ הוּא כֹּלָּא בִּרְשׁוּתֵיהּ וְלָא כְּמַאן דְּאִתְחֲזֵי בְּחֵיזוּ דְּכֹכְבַיָא וּמַזָּלֵי, דְּכֻלְהוּ אַחְזְיָין מִלָּה, וְקוּדְשָׁא בְּרִיךְ הוּא אַחְלַף לֵיהּ לְגַוְונָא אָחֳרָא. וּמִי צוּר זוּלָתִי אֱלהֵינוּ. הָא אוּקְמוּהָ דְּלֵית צַיָּיר כְּמָה דְּקוּדְשָׁא בְּרִיךְ הוּא דְּאִיהוּ צַיָּיר שְׁלִים עָבִיד וְצִיֵּיר דִּיוּקְנָא גּוֹ דִיוּקְנָא וְאַשְׁלִים לְהַהוּא דִּיוּקְנָא בְּכָל תִּקּוּנֵיהּ, וְאָעִיל בָּהּ נֶפֶשׁ עִלָּאָה דְּדָמֵי לְתִקּוּנָא עִלָּאָה, בְגִין כָּךְ לֵית צַיָּיר כְּקוּדְשָׁא בְּרִיךְ הוּא.","תָּא חֲזֵי, מֵהַהוּא זַרְעָא דְּבַּר נָשׁ כַּד אִתְעַר תִּיאוּבְתֵּיהּ לְגַבֵּי נוּקְבֵיהּ וְנוּקְבֵיהּ אִתְעָרַת לְגַבֵּיהּ כְּדֵין מִתְחַבְּרָן תַּרְוַויְיהוּ כְּחֲדָא וְנָפַק מִנַּיְיהוּ בַּר חַד דְּכָלִיל מִתְּרֵין דִּיוּקְנִין כְּחַד. בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא צִיֵיר לֵיהּ בְּצִיּוּרָא דְּאִתְכְּלִיל מִתַּרְוַויְיהוּ. וְעַל דָּא בָּעֵי בַּר נָשׁ לְקַדְשָׁא גַרְמֵיהּ בְּהַהוּא זִמְנָא בְּגִין דְּיִשְׁתְּכַח הַהוּא דִּיוּקְנָא בְּצִיּוּרָא שְׁלִים כְּדְקָא חָזֵי.","אָמַר רַבִּי חִיָּיא תָּא חֲזֵי, כַּמָּה אִנּוּן רַבְרְבִין עוֹבָדוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּהָא אוּמְנוּתָא וְצִיּוּרָא דְּבַּר נָשׁ אִיהוּ כְּגַוְונָא דְעָלְמָא, וּבְכָל יוֹמָא וְיוֹמָא קוּדְשָׁא בְּרִיךְ הוּא בָּרֵי עָלְמָא מְזַוִּוג זִוּוּגִין כָּל חַד וְחַד כְּדְקָא חָזֵי לֵיהּ, וְהוּא צִיֵּיר דִּיוּקְנֵיהוֹן עַד לָא יֵיתוּן לְעָלְמָא.","תָּא חֲזֵי, דְּאָמַר רַבִּי שִׁמְעוֹן, כְּתִיב זֶה סֵפֶר תּוֹלְדוֹת אָדָם. וְכִי סֵפֶר הֲוָה לֵיהּ. אֶלָּא אוּקְמוּהָ דְּקוּדְשָׁא בְּרִיךְ הוּא אַחְמֵי לֵיהּ לְאָדָם הָרִאשׁוֹן דּוֹר דּוֹר וְדוֹרְשָׁיו וְכוּ'. הֵיאַךְ אַחְמֵי לֵיהּ, אִי תֵימָא דְּחָמָא בְּרוּחַ קוּדְשָׁא דְּאִנּוּן זְמִינִין לְמֵיתֵי לְעָלְמָא. כְּמַאן דְּחָמָא בְּחָכְמְתָא מַה דְּיֵיתֵי לְעָלְמָא. לָאו הָכִי, אֶלָּא חָמָא בְּעֵינָא כֻּלְהוּ. וְהַהוּא דִּיוּקְנָא דְּזַמִּינִין לְמֵיקַם בֵּיהּ בְּעָלְמָא כֻּלְהוּ חָמָא בְּעֵינָא, מַאי טַעְמָא בְּגִין דְּמִיּוֹמָא דְּאִתְבְּרֵי עָלְמָא כֻּלְהוּ נַפְשָׁאן דְּזַמִּינִין לְמֵיקַם בִּבְנֵי נָשָׁא כֻּלְהוּ קָיְימִין קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא בְּהַהוּא דִּיוּקְנָא מַמָּשׁ דְּזַמִּינִין לְמֵיקַם בֵּיהּ בְּעָלְמָא."],[[0,"ואברהם הוה חמי וכו':","ואברהם היה רואה בחכמת הכוכבים, שלא יוליד. מה כתוב. ויוצא אותו החוצה וגו'. אמר לו הקב\"ה, לא תסתכל בזה, בחכמת הככבים, אלא בסוד השם שלי, שהיא הנוקבא, יהיה לך בן. זהו שכתוב \u0003כה\u0004 יהיה זרעך. כה, הוא סוד השם הקדוש שמשם נקשר לו בן. ולא מסטרא אחרא, שהוא הככבים והמזלות."],[1,"כה. דהוא תרעא וכו': כה,","שהוא שער לקבלת התפלה, שהיא הנוקבא, בה ימצא ברכה, בה יקבל האדם בקשתו. \u0003כה,\u0004 הוא אותו צד הבא מצד הגבורה, דהיינו הנוקבא הנבנית משמאל, שהוא גבורה, כי מצד הגבורה נולד יצחק, ואותו צד הגבורה נקרא \u0003כה,\u0004 שמשם באים איבים ופירות לעולם, ולא מהצד שלמטה שהוא הככבים והמזלות."],[2,"כדין והאמין וכו':","אז, \u0003והאמין בה',\u0004 היינו שנתדבק למעלה בהקדושה בהשם \u0003כה,\u0004 ולא נתדבק למטה, בסטרא אחרא. \u0003והאמין בה',\u0004 ולא בככבים ומזלות. \u0003והאמין בה',\u0004 שהבטיח לו ששכרו הרבה מאד לעולם הבא. \u0003והאמין בה',\u0004 באותו המדרגה שניתן לו, דהיינו השם \u0003כה,\u0004 האמין שמשם ימשך לו להוליד בנים בעולם."],[3,"ויחשבה לו צדקה:","היינו, \u0003ויחשבה לו\u0004 להשם \u0003כה\u0004 הזה אע\"פ שהוא דין, חשבה כאלו הוא רחמים. פירוש אחר, על ויחשבה לו צדקה, שקשר קשר ליחד העליונה, שהיא בינה, בתחתונה, שהיא הנוקבא, לחבר אות יחד. פירוש. הנוקבא נקראת \u0003צדק\u0004 ובעת שנתיחדה לאחת עם בינה, ממשכת ממנה \u0003ה'\u0004 שה\"ס ה' ראשונה שבשם הויה, ואז נקראת הנוקבא \u0003צדקה,\u0004 שהוא \u0003צדק\u0004 עם \u0003ה'\u0004 מבינה. וזהו שלמד מהכתוב ויחשבה לו צדקה, \u0003דקשיר קשרא עלאה בתתאה,\u0004 כי ע\"כ חשבה עתה בהשם, \u0003צדקה,\u0004 כמבואר."],[4,"ת\"ח הא אתערו וכו':","בוא וראה. הנה אמרו, אברהם עם \u0003ה'\u0004 מוליד אברם אינו מוליד. ואם תאמר, הרי הוליד את ישמעאל בעוד שהוא אברם. ומשיב, אלא אותו הבן שהבטיח לו הקב\"ה לא הוליד בעוד שהוא אברם, כי בעוד שהוא אברם הוליד רק למטה, שהוא ישמעאל, כיון שנקרא אברהם, ונכנס בברית, אז הוליד למעלה בהקדושה. ומשום זה, אברם אינו מוליד בקשר העליון, אלא למטה, אברהם מוליד, כמו שאמרנו, שנתקשר למעלה ביצחק."],[5,"ויהי אברם בן תשעים שנים וגו':","ר' אבא פתח. כי מי אל מבלעדי ה' ומי צור וגו'. דוד המלך אמר את הכתוב הזה. כי מי אל מבלעדי ה'. היינו, מי הוא המושל או הממונה שיכול לעשות דבר, מבלעדי ה', אלא שעושים מה שנצטוו מאת הקב\"ה, כי כולם אינם ברשותם עצמם, ואינם יכולם לעשות משהו \u0003ומי צור,\u0004 ומי הוא תקיף, שיוכל לעשות תוקף וגבורה מעצמו, \u0003מבלעדי אלקינו,\u0004 אלא כולם הם ביד הקב\"ה, ואינם יכולים לעשות משהו רק ברשותו."],[6,"ד\"א כי מי אל וכו':","פירוש אחר על מי אל מבלעדי ה'. כי הקב\"ה הכל הוא ברשותו, ולא כמו הנראה במראה הככבים ומזלות, שהם מראים דבר, והקב\"ה מחליפו לאופן אחר. \u0003ומי צור זולתי אלקינו,\u0004 הרי בארוה, שאין צייר כמו הקב\"ה, שהוא צייר השלם, שעושה ומצייר צורה תוך צורה, דהיינו עובר במעי אמו, ומשלים אותה הצורה בכל תקוניה, ומכניס בתוכה נפש עליונה הדומה לתקון העליון. ומשום זה, אין צייר כמו הקב\"ה."],[7,"ת\"ח מההוא זרעא וכו':","בוא וראה מאותו זרע של האדם. בעת שנתעורר חשקו אל הנוקבא, והנקבה נתעוררת אליו, אז מתחברים שניהם יחד, ויוצא מהם בן אחד, הכלול מב' הצורות כאחד. ועל כן צריך האדם לקדש את עצמו באותו זמן, כדי שתהיה אותה הצורה בציור שלם כראוי."],[8,"א\"ר חייא וכו'","אר\"ח בוא וראה, כמה גדולים הם מעשיו של הקב\"ה. כי האומנות והציור של האדם הוא כמו אומנות וציור של העולם. כלומר, שהאדם כולל בתוכו כל מעשה העולם, ונקרא עולם קטן. ובכל יום ויום הקב\"ה בורא עולם, דהיינו שמזווג זווגים לכל אחד כראוי לו, שזהו נבחן לבורא עולמות. והוא צייר צורתם של כל אחד מטרם שבאו לעולם."],[9,"ת\"ח דאמר ר\"ש וכו':","בוא וראה, מה שאמר ר' שמעון. כתוב זה ספר תולדות אדם. ושואל וכי ספר היה לו. ומשיב אלא בארוה, שהקב\"ה הראה לו לאדם הראשון דור דור ודורשיו וכו'. ואיך הראה לו כל הצורות. אם תאמר, שראה ברוח הקדש שהן עתידות לבא בעולם, כמו המסתכל בחכמה לדעת מה שעתיד לבא בעולם. אינו כך, אלא ראה אותן כולן בעין, ובאותו הצורה שהן עתידות לעמוד בה בעולם, הכל ראה בעין."],[9,"מה טעמא בגין וכו':","ושואל, מה הטעם שהיה יכול לראותם כולם בעינו. ואומר, משום שמיום שנברא העולם, כל הנפשות העתידות לקום בבני אדם, כולם עומדים לפני הקב\"ה, באותה הצורה ממש, שעתידים להיות בעולם."]],[[0,"","וְאַבְרָהָם הָיָה רוֹאֶה בָּאִצְטַגְנִינוּת שֶׁלּוֹ שֶׁלֹּא יוֹלִיד. מַה כָּתוּב? וַיּוֹצֵא אֹתוֹ הַחוּצָה וְגוֹ'. (אמר לו הקדוש ברוך הוא, צא מאצטגנינות שלך, אברם אינו מוליד, אברהם מוליד) אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, אַל תִּסְתַּכֵּל בָּזֶה, אֶלָּא בַּסּוֹד שֶׁל שְׁמִי יִהְיֶה לְךְ בֵּן. זֶהוּ שֶׁכָּתוּב כֹּה יִהְיֶה זַרְעֶךְ. הַסּוֹד שֶׁל הַשֵּׁם הַקָּדוֹשׁ שֶׁמִּשָּׁם נִקְשַׁר לוֹ עִם זֶה (בן) וְלֹא מֵהַצַּד הָאַחֵר."],[1,"","כֹּה - שֶׁהוּא הַשַּׁעַר לַתְּפִלָּה, בָּהּ יִמְצָא בְרָכָה, בָּהּ יִמְצָא אָדָם אֶת בַּקָּשָׁתוֹ. כֹּה - אוֹתוֹ הַצַּד שֶׁבָּא מִצַּד הַגְּבוּרָה, שֶׁהֲרֵי מִצַּד הַגְּבוּרָה בָּא יִצְחָק. וְאוֹתוֹ צַד הַגְּבוּרָה נִקְרָא כֹּ\"ה, שֶׁמִּשָּׁם בָּאִים פֵּרוֹת וּפֵרוֹת לָעוֹלָם, וְלֹא מֵהַצַּד שֶׁלְּמַטָּה שֶׁל כּוֹכָבִים וּמַזָּלוֹת."],[2,"","אָז והִאִמן בַּה'. נִדְבַּק לְמַעְלָה וְלֹא נִדְבַּק לְמַטָּה. וְהֶאֱמִן בַּה', וְלֹא בְכוֹכָבִים וּמַזָּלוֹת. וְהֶאֱמִן בַּה' - שֶׁהִבְטִיחַ לוֹ שֶׁיַּרְבֶּה אֶת שְׂכָרוֹ לָעוֹלָם הַבָּא. וְהֶאֱמִן בַּה' - בְּאוֹתָהּ הַדַּרְגָּה שֶׁנִּתְּנָה לוֹ, שֶׁמִּשָּׁם יָבא לוֹ זֶרַע לְהוֹלִיד בָּעוֹלָם."],[3,"","וַיַּחְשְׁבֶהָ לּוֹ צְדָקָה. וַיַּחְשְׁבֶהָ לּוֹ - שֶׁאַף עַל גַּב שֶׁהִיא דִין, כְּאִלּוּ הִיא רַחֲמִים הַ\"כֹּה\" הַזֹּאת. דָּבָר אַחֵר וַיַּחְשְׁבֶהָ לּוֹ צְדָקָה - שֶׁקָּשַׁר קֶשֶׁר עֶלְיוֹן בַּתַּחְתּוֹן לְחַבְּרָם יַחַד."],[4,"","בֹּא רְאֵה, הִנֵּה הֵעִירוּ, אַבְרָהָם מוֹלִיד - אַבְרָם אֵינוֹ מוֹלִיד. וְכִי תֹאמַר שֶׁהִנֵּה הוֹלִיד אֶת יִשְׁמָעֵאל בְּעוֹדוֹ אַבְרָם? אֶלָּא הַבֵּן הַהוּא שֶׁהִבְטִיחַ לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, לֹא הוֹלִיד אוֹתוֹ בְּעוֹדוֹ אַבְרָם, שֶׁהֲרֵי בְּעוֹדוֹ אַבְרָם הוֹלִיד לְמַטָּה. כֵּיוָן שֶׁנִּקְרָא אַבְרָהָם וְנִכְנַס בַּבְּרִית, אָז הוֹלִיד לְמַעְלָה. וּמִשּׁוּם כָּךְ אַבְרָם אֵינוֹ מוֹלִיד בְּקֶשֶׁר עֶלְיוֹן, אַבְרָהָם מוֹלִיד כְּמוֹ שֶׁאָמַרְנוּ, וְנִקְשָׁר לְמַעְלָה בְּיִצְחָק."],[5,"","וַיְהִי אַבְרָם בֶּן תִּשְׁעִים שָׁנָה וְתֵשַׁע שָׁנִים וְגוֹ'. רַבִּי אַבָּא פָּתַח, (שמואל ב כב) כִּי מִי אֵל מִבַּלְעֲדֵי ה' וּמִי צוּר וְגוֹ'. דָּוִד הַמֶּלֶךְ אָמַר אֶת הַפָּסוּק הַזֶּה, כִּי מִי אֵל מִבַּלְעֲדֵי ה' - מִי הוּא הַשַּׁלִּיט אוֹ הַמְמֻנֶּה שֶׁיָּכוֹל לַעֲשׂוֹת דָּבָר מִבַּלְעֲדֵי ה'? אֶלָּא מִי שֶׁהִצְטַוָּה מֵעִם הַקָּדוֹשׁ בָּרוּךְ הוּא, מִשּׁוּם שֶׁכֻּלָּם אֵין עוֹמְדִים בִּרְשׁוּתָם וְלֹא יְכוֹלִים לַעֲשׂוֹת דָּבָר. וּמִי צוּר - וּמִי הוּא הַתַּקִּיף שֶׁיָּכוֹל לַעֲשׂוֹת תֹּקֶף וּגְבוּרָה מֵעַצְמוֹ מִבַּלְעֲדֵי אֱלֹהֵינוּ? אֶלָּא כֻּלָּם בְּיַד הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלֹא יָכוֹל לַעֲשׂוֹת דָּבָר, רַק מֵרְשׁוּתוֹ."],[6,"","דָּבָר אַחֵר כִּי מִי אֵל מִבַּלְעֲדֵי ה' - שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הַכֹּל בִּרְשׁוּתוֹ, וְלֹא כְּמִי שֶׁנִּרְאֶה בְּמַרְאֵה הַכּוֹכָבִים וְהַמַּזָּלוֹת, שֶׁכֻּלָּם מַרְאִים דָּבָר, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מַחֲלִיפוֹ לְגָוֶן אַחֵר. וּמִי צוּר זוּלָתִי אֱלֹהֵינוּ, הֲרֵי פֵּרְשׁוּהָ שֶׁאֵין צַיָּר כְּמוֹ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא צַיָּר שָׁלֵם, עוֹשֶׂה וּמְצַיֵּר דְּמוּת בְּתוֹךְ דְּמוּת, וּמַשְׁלִים אֶת אוֹתָהּ הַדְּמוּת בְּכָל תִּקּוּנָהּ, וּמַכְנִיס בּוֹ נֶפֶשׁ עֶלְיוֹנָה, שֶׁדּוֹמֶה לַתִּקּוּן הָעֶלְיוֹן, מִשּׁוּם כָּךְ אֵין צַיָּר כְּמוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא."],[7,"","בֹּא רְאֵה, מֵאוֹתוֹ הַזֶּרַע שֶׁל אָדָם, כְּשֶׁמִּתְעוֹרֶרֶת תְּשׁוּקָתוֹ לִנְקֵבָתוֹ, וּנְקֵבָתוֹ מִתְעוֹרֶרֶת אֵלָיו, אָז מִתְחַבְּרִים שְׁנֵיהֶם יַחַד, וְיוֹצֵא מֵהֶם בֵּן אֶחָד שֶׁכָּלוּל מִשְּׁתֵּי דְמֻיּוֹת כְּאֶחָד, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא צִיֵּר אוֹתוֹ בְּצִיּוּר שֶׁנִּכְלָל מִשְּׁנֵיהֶם. וְעַל כֵּן צָרִיךְ אָדָם לְקַדֵּשׁ אֶת עַצְמוֹ בַּזְּמַן הַהוּא, כְּדֵי שֶׁיִּמָּצֵא הַדְּמוּת הַהִיא בְּצִיּוּר שָׁלֵם כָּרָאוּי."],[8,"","אָמַר רַבִּי חִיָּיא, בּא רְאֵה, כַּמָּה גְּדוֹלִים הֵם מַעֲשָׂיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהֲרֵי הָאֻמָּנוּת וְהַצִּיּוּר שֶׁל הָאָדָם הִיא כְּמוֹ הָעוֹלָם, וּבְכָל יוֹם וָיוֹם הַקָּדוֹשׁ בָּרוּךְ הוּא בּוֹרֵא עוֹלָמוֹת, וּמְזַוֵּג זִוּוּגִים כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ, וְהוּא צִיֵּר אֶת דְּמוּתָם טֶרֶם בּוֹאָם לָעוֹלָם."],[9,"","בֹּא רְאֵה, שֶׁאָמַר רַבִּי שִׁמְעוֹן, כָּתוּב זֶה סֵפֶר תּוֹלְדת אָדָם, וְכִי סֵפֶר הָיָה לוֹ? אֶלָּא פֵּרְשׁוּהָ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הֶרְאָה לְאָדָם הָרִאשׁוֹן דּוֹר דּוֹר וְדוֹרְשָׁיו וְכוּ'. אֵיךְ הֶרְאָה לוֹ? אִם תֹּאמַר שֶׁרָאָה בְּרוּחַ הַקֹּדֶשׁ שֶׁהֵם עֲתִידִים לָבֹא לָעוֹלָם כְּמִי שֶׁרוֹאֶה בְּחָכְמָה מַה יָּבֹא לָעוֹלָם - לֹא כָּךְ, אֶלָּא רָאָה בְּעַיִן אֶת כֻּלָּם, וְאוֹתָהּ הַדְּמוּת שֶׁעֲתִידִים לַעֲמֹד בָּהּ בָּעוֹלָם, אֶת כֻּלָּם הוּא רָאָה בְּעַיִן. מָה הַטַּעַם? מִשּׁוּם שֶׁמִּיּוֹם שֶׁנִּבְרָא הָעוֹלָם, כָּל הַנְּפָשׁוֹת הָעֲתִידוֹת לַעֲמֹד בִּבְנֵי הָאָדָם, כֻּלָּן עוֹמְדוֹת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתָהּ הַדְּמוּת מַמָּשׁ שֶׁעֲתִידוֹת לַעֲמֹד בָּהּ בָּעוֹלָם."]]],[["כְּגַוְונָא דָא כָּל אִנּוּן צַדִּיקַיָּיא בָּתַר דְּנָפְקִין מֵהַאי עָלְמָא כֻּלְהוּ נַפְשָׁאן סָלְקָן, וְקוּדְשָׁא בְּרִיךְ הוּא אַזְמִין לוֹן דִּיוּקְנָא אָחֳרָא לְאִתְלַבְּשָׁא בְּהוּ כְּגַוְונָא דְּהֲווּ בְּהַאי עָלְמָא, בְגִין כָּךְ כֻּלְהוּ קָיְימִין קַמֵּיהּ וְחָמָא לוֹן אָדָם הָרִאשׁוֹן בְּעֵינָא.","וְאִי תֵימָא בָּתַר דְּחָמָא לוֹן לָא קָיְימֵי בְּקִיּוּמַיְיהוּ. תָּא חֲזֵי כָּל מִלּוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא בְּקִיּוּמָא אִנּוּן וְקָיְימוּ קַמֵּיהּ עַד דְּנָחֲתוּ לְעָלְמָא. כְּגַוְונָא דָא כְּתִיב, (דברים כ״ט:י״ד) כִּי אֵת אֲשֶׁר יֶשְׁנוֹ פֹה וְגו' הָא אוּקְמוּהָ דְּכֻלְהוּ בְּנֵי נָשָׁא דְּזַמִּינִין לְמֶהֱוֵי בְּעָלְמָא כֻּלְהוּ אִשְׁתְּכָחוּ תַּמָּן.","הָכָא אִית לְאִסְתַּכָּלָא דְּהָא כְּתִיב אֵת אֲשֶׁר אֵינֶנּוּ פֹה וְגו' וּמַשְׁמַע הַנְהוּ (כלהו) דְּיִפְקוּן מֵאִנּוּן דְּקָיְימוּ תַּמָּן, בְּגִין דִּכְתִיב עִמָּנוּ הַיּוֹם וְלָא כְּתִיב עִמָּנוּ עוֹמֵד הַיּוֹם. אֶלָּא וַדַּאי (הכא) כֻּלְהוּ קָיְימוּ תַּמָּן אֶלָּא דְּלָא אִתְחֲזוּ לְעֵינָא, בְגִין כָּךְ כְּתִיב עִמָּנוּ הַיּוֹם אַף עַל גַּב דְּלָא אִתְחֲזוּן.","וְאִי תֵימָא מַאי טַעְמָא לָא אִתְחֲזוּן הָכָא כְּמָה דְּאִתְחֲזוּן לְאָדָם הָרִאשׁוֹן דְּחָמָא לוֹן עֵינָא בְּעֵינָא, וְהָא הָכָא אִתְחֲזֵי יַתִּיר. אֶלָּא הָכָא כַּד אִתְיְיהִיבַת אוֹרַיְיתָא לְיִשְׂרָאֵל חֵיזוּ אָחֳרָא וְדַרְגִּין עִלָּאִין הֲווּ חָמָאן וּמִסְתַּכְּלָאן עֵינָא בְּעֵינָא וְהֲווּ תְּאִיבִין לְאִסְתַּכָּלָא וּלְמֶחמֵי בִּיקָרָא דְּמָרֵיהוֹן, וּבְגִין כָּךְ חָמוּ יְקָרָא עִלָּאָה דְּקוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי וְלָא מֵאָחֳרָא.","וְעַל דָּא כֻּלְהוּ בְּנֵי נָשָׁא דְּזַמִּינִין לְקָיְימָא בְּעָלְמָא כֻּלְהוּ קָיְימֵי קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא בְּאִנּוּן דִּיוּקְנִין מַמָּשׁ דְּזַמִּינִין לְקָיְימָא בֵּיהּ הֲדָא הוּא דִכְתִיב, (תהילים קל״ט:ט״ז) גָּלְמִי רָאוּ עֵינֶיךָ וְעַל סִפְרְךָ וְגו'. גָּלְמִי רָאוּ עֵינֶיךָ. מַאי טַעְמָא בְּגִין דְּדִיוּקְנָא אָחֳרָא עִלָּאָה הֲוִי כְּהַאי וּבְגִין כָּךְ כְּתִיב, (תהילים י״ח:ל״ב) וּמִי צוּר זוּלָתִי אֱלֹהֵינוּ. מַאן צַיָּיר טַב דְּצַיָּיר (דכליל) כֹּלָּא (דא בדא) כְּקוּדְשָׁא בְּרִיךְ הוּא.","דָּבָר אַחֵר כִּי מִי אֱלוֹהַּ, דָּא רָזָא דְמִלָּה דְּהָא אֵל כְּלָלָא הוּא דְּאִתְכְּלִיל מִכֻּלְהוּ דַּרְגִּין, וְאִי תֵימָא דְּהָא אֵל אִיהוּ דַּרְגָּא אָחֳרָא בְּגִין דִּכְתִיב (תהלים ז) אֵל זוֹעֵם בְּכָל יוֹם. תָּא חֲזֵי, דְּהָא לֵית אֵל מִבַּלְעֲדֵי יְיָ דְּלָאו אִיהוּ בִּלְחוֹדוֹי וְלָא אִתְפְּרַשׁ לְעָלְמִין. וְעַל דָּא כְּתִיב, (שמואל ב כ״ב:ל״ב) כִּי מִי אֵל מִבַּלְעֲדֵי יְיָ וְגו', וּמִי צוּר וְגו' דְּהָא צוּר לָאו אִיהוּ בִּלְחוֹדוֹי אֶלָּא כֹּלָּא חַד כְּדִכְתִיב, (דברים ד׳:ל״ט) וְיָדַעְתָּ הַיּוֹם וַהֲשֵׁבוֹתָ אֶל לְבָבֶךָ כִּי יְיָ הוּא הָאֱלהִים וְגו'.","תָּא חֲזֵי, עַד לָא אִתְגְּזַר אַבְרָהָם הֲוָה מְמַלֵּיל עִמֵּיהּ מִגּוֹ מַחֲזֶה בִּלְחוֹדוֹי כְּמָה דְּאִתְּמָר דִּכְתִיב הָיָה דְּבַר יְיָ אֶל אַבְרָם בַּמַּחֲזֶה וְגו'. בַּמַּחֲזֶה. בְּהַהוּא חֵיזוּ דַּרְגָּא דְּכָל דִּיוּקְנִין אִתְחַזְיָין בֵּיהּ, כְּמָה דְּאִתְּמָר. וְהַאי מַחֲזֶה אִיהוּ רָזָא דִּבְרִית.","וְאִי תֵימָא דִּבְגִין כָּךְ אִקְרֵי מַחֲזֶה בְּגִין דְּאִיהוּ דַּרְגָּא חֵיזוּ דְּכָל דִּיוּקְנִין אִתְחַזְיָין בֵּיהּ וּכְדֵין אִקְרֵי מַחֲזֶה, הָא אֲמַרְתְּ (פח ב) בְּקַדְמִיתָא דְּעַד לָא אִתְגְּזַר אַבְרָהָם לָא הֲוָה מְמַלֵּיל עִמֵּיהּ בַּר הַאי דַּרְגָּא דְּלָא שָׁרָאן עֲלוֹי דַּרְגִּין אָחֳרָנִין, וְהַשְׁתָּא אֲמַרְתְּ בַּמַּחֲזֶה חֵיזוּ דְּכָל דַּרְגִּין עִלָּאִין (איהו). וְהָא עַד לָא אִתְגְּזַר כְּתִיב הָיָה דְּבַר יְיָ אֶל אַבְרָם בַּמַּחֲזֶה.","אֶלָּא הַאי דַרְגָּא חֵיזוּ דְּכָל דַּרְגִּין עִלָּאִין אִיהוּ וּבְחֵיזוּ דְּדַרְגִּין עִלָּאִין אִתְתַּקַּן. וְאַף עַל גַּב דִּבְהַהוּא זִמְנָא דְּאַבְרָהָם לָא הֲוָה גָּזִיר הַאי דַּרְגָּא בְּחֵיזוּ דְּדַרְגִּין עִלָּאִין אִיהוּ וּבְכָל אִנּוּן גְּוָונִין אִיהוּ קָאִים. וְחֵיזוּ דְּאִנּוּן (קא א, וצז ב) גְּוָונִין קָיְימֵי תְּחוֹתֵיהּ חַד מִיָּמִינָא גַּוָּון חִוַּור. חַד מִשְּׂמָאלָא גַּוָּון סוּמָק. חַד דְּכָלִיל מִכָּל גְּוָונִין, וְאִיהוּ חֵיזוּ דְּכָל גְּוָונִין עִלָּאִין דְּקָיְימֵי עֲלֵיהּ. וְעַל דָּא בְּהַאי חֵיזוּ קָאִים עֲלֵיהּ דְּאַבְרָהָם וּמַלִּיל עִמֵּיהּ וְאַף עַל גַּב דְּלָא אִתְגְּזַר. כֵּיוָן דְּאִתְגְּזַר מַה כְּתִיב וַיֵּרָא יְיָ אֶל אַבְרָם.","תָּא חֲזֵי, מַחֲזֵה שַׁדַּי (אמר) כְּתִיב בְּבִלְעָם. וּבְאַבְרָהָם כְּתִיב מַחֲזֶה סְתָם, מַה בֵּין הַאי לְהַאי. אֶלָּא מַחֲזֵה שַׁדַּי אִלֵּין דִּלְתַתָּא (דנפקו) מִנֵּיהּ וְאִנּוּן חֵיזוּ דִּילֵיהּ. מַחֲזֶה סְתָם מַחֲזֶה דָּא הוּא ה' (דכל חיזו) דְּכָל דִּיוּקְנִין עִלָּאִין אִתְחַזְיָין בֵּיהּ, וּבְגִין כָּךְ כְּתִיב בְּאַבְרָהָם מַחֲזֶה סְתָם וּבְבִלְעָם מַחֲזֵה שַׁדַּי.","וְעַל דָּא עַד לָא אִתְגְּזַר אַבְרָהָם הֲוָה לֵיהּ הַאי דַרְגָא כִּדְאֲמָרָן. כֵּיוָן דְּאִתְגְּזַר מִיָּד וַיֵּרָא יְיָ אֶל אַבְרָם וְגו' אִתְחֲזוּן כֻּלְהוּ (שאר) דַּרְגִּין עַל הַאי דַּרְגָּא, וְהַאי דַּרְגָּא מַלִּיל עִמֵּיהּ כְּדְקָא חָזֵי בִּשְׁלִימוּ. וְאַבְרָהָם אִתְקַטַּר מִדַּרְגָּא לְדַרְגָּא וְעָאל בִּבְרִית קְיָימָא קַדִּישָׁא כְּדְקָא חָזֵי בִּשְׁלִימוּ"],[[0,"כגוונא דא כל וכו':","כעין זה, כל אלו הצדיקים אחר שנפטרים מעולם הזה, כל הנפשות שלהם עולות. והקב\"ה מזמין לכל אחד שם, צורה אחרת להתלבש בה, כעין שהיו מלובשות בעולם הזה. משום זה, כל הנשמות נמצאות לפניו. וראה אותן אדם הראשון, בעין."],[1,"ואי תימא וכו':","ואם תאמר, אחר שראה אותן לא נשארו בקיום אלא שנתבטלו אחר כך. בוא וראה, כל דברי הקב\"ה הם בקיום, ועומדים לפניו עד שהגיע זמנן לירד לעולם. כעין זה כתוב, כי את אשר ישנו פה וגו'. ובארוהו, שכל בני אדם העתידים להיות בעולם היו כולם נמצאים שם."],[2,"הכא אות לאסתכלא וכו':","הכא יש להסתכל שהרי כתוב, את אשר איננו פה וגו'. ומשמע, רק אותם שיולדו מאלו העומדים שם, כי על כן לא כתוב \u0003עמנו עומד היום,\u0004 שהיה משמע שעומדים שם עמהם, אלא כתוב. \u0003עמנו היום,\u0004 שמשמע שאינם נמצאים עמהם. ומשיב, אלא ודאי שהיו עומדים שם כולם, אלא משום שלא היו נראים לעין, על כן אומר הכתוב \u0003עמנו היום,\u0004 כלומר, אע\"פ שאינם נראים. ולא היה יכול לומר, משום זה, עמנו עומד היום."],[3,"ואי תימא מאי וכו':","ואם תאמר, מה הטעם שלא נראו כאן על הר סיני, כמו שהיו נראים לאדם הראשון, שהוא ראה אותם עין בעין. והרי כאן, במתן תורה, היה ראוי יותר שיתראו כל הדורות עין בעין."],[3,"אלא הכא וכו':","ומשיב, אלא כאן, כשניתן התורה לישראל, מראה אחרת, ומדרגות עליונות היו רואים ומסתכלים עין בעין, והיו משתוקקים להסתכל ולראות בכבוד רבונם, ומשום זה ראו את כבוד העליון של הקב\"ה בלבדו, ולא ממה שהוא אחר חוץ ממנו."],[4,"ועל דא כלהו וכו':","ועל כן, כל בני אדם העתידים להמצא בעולם, כולם עומדים לפני הקב\"ה באלו הצורות ממש העתידים להיות בהן. וז\"ש גלמי ראו עיניך ועל ספרך כולם יכתבו. \u0003גלמי ראו עיניך,\u0004 מהו הטעם, שראה הקב\"ה את גלמו. ואומר, משום שצורה אחרת העליונה, העומדת לפניו מקודם בריאת העולם כנ\"ל, היתה כמוה. וע\"כ ראה אותה, ומי צור זולתי אלקינו, היינו, מי היה צייר טוב שיוכל לצייר הכל כמו הקב\"ה."],[5,"ד\"א כי מי אלוה:","זהו סוד הדבר. כי הנוקבא שנקראת \u0003אל\u0004 היא כלל, כי היא כלולה מכל המדרגות. הן ממדרגות הימין שהן חסדים, והן ממדרגות השמאל שהן גבורות. פירוש שהכתוב מדבר בעת שהויה אלקים מיוחדים, כמו שמסיק הזהר לפנינו בסו\"ה הוי\"ה הוא האלקים, ואז הנוקבא כלולה מכל המדרגות מימין ומשמאל, הימין שבה מקבלת מ \u0003הויה,\u0004 והשמאל שבה היא בחינתה עצמה, שהיא השם \u0003אלקים.\u0004 וזהו שכתוב. \u0003מי אל,\u0004 היינו הנוקבא בסוד ימין שבה, \u0003מבלעדי ה'\u0004 היינו שמקבלת מהשם הויה שהוא ז\"א. \u0003ומי צור,\u0004 היינו הנוקבא בסוד השמאל שבה, \u0003מבלעדי אלקינו,\u0004 כלומר שהיא בחינתה עצמה של הנוקבא הנקראת אלקינו."],[5,"ואי תימא וכו':","ושואל, ואם תאמר שהשם אל הוא מדרגה אחרת ואינו בחינת ימין, משום שכתוב, ואל זועם בכל יום, שמשמע, שמדת השם \u0003אל,\u0004 הוא זעם וגבורות. ומשיב, בוא וראה כי מי \u0003אל\u0004 מבלעדי הויה, פירושו, שהנוקבא אינה בלבדה, אלא מיוחדת עם הויה, שהוא ז\"א, בזווג שאינו נפסק לעולם, כי הכתוב מדבר, בעת שזו\"ן עלו והלבישו לאו\"א עלאין, שאז נבחנים בזווג דלא פסיק לעלמין, כמו או\"א. כי התחתון שעלה לעליון נעשה כמוהו. ועל זה כתוב, כי מי אל מבלעדי הויה, ומי צור מבלעדי אלקינו, כי \u0003צור,\u0004 שה\"ס השמאל שבנוקבא אינו בלבדו, אלא הכל אחד, כמ\"ש וידעת היום והשבות אל לבבך כי הוי\"ה הוא האלקים. דהיינו כשזו\"ן עולים ומלבישים לאו\"א, אז נעשה היחוד הזה של הויה הוא האלקים. ואז כל המדרגות כלולות בנוקבא, ובחינת הימין ה\"ס השם \u0003אל,\u0004 ובחינת השמאל ה\"ס השם צור. ומיוחדים כאחד. אבל הכתוב \u0003אל זועם בכל יום,\u0004 מדבר בהנוקבא במקומה, מטרם שעלתה לאו\"א, ואז יש בה גבורות תמיד. ועי' לעיל בהק' הזהר דף קכ\"ט אות קכ\"ט, ששם פירש הזהר הכתוב הזה באופן אחר. וע\"ש בהסולם."],[6,"ת\"ח עד לא אתגזר וכו':","בוא וראה, כל עוד שלא נמול אברהם, היה הקב\"ה מדבר עמו מתוך \u0003מחזה\u0004 בלבד, שה\"ס הנוקבא במקומה, שעליה נאמר, ואל זועם בכל יום, כנ\"ל. כמו שלמדנו, שכתוב, היה דבר ה' אל אברם \u0003במחזה,\u0004 במחזה, פירושו, באותה המראה. דהיינו הנוקבא, שהיא מדרגה שכל הצורות נראות בה, דהיינו כל ג' הקוין ימין שמאל אמצע. כמו שלמדנו. ומחזה הזה, הוא סוד הברית, דהיינו הנוקבא, שהברית מאיר בה."],[7,"ואי תימא דבגין וכו':","ושואל, ואיך תאמר שמשום זה נקראת הנוקבא, בשם מחזה, משום שהוא מדרגת מראה שכל הצורות נראות בה. הרי מקודם לכן אמרת, שכל עוד שלא נמול אברהם, לא היה מדבר עמו רק מדרגת \u0003המחזה\u0004 בלבדה, שמדרגות אחרות אינן שורות עליה. ועתה תאמר, \u0003שמחזה,\u0004 הוא מראה שכוללת בה כל מדרגות העליונות, והרי מטרם שנמול, נאמר, היה דבר ה' אל אברם במחזה."],[8,"אלא האי דרגא וכו':","ומשיב. אלא מדרגה זו, היא ודאי המראה של כל מדרגות העליונות, ובמראה של מדרגות העליונות היא נתתקנה. וגם באותו זמן, שאברהם לא היה נמול, היתה מדרגה זו במראה של מדרגות העליונות, ובכל אלו גוונין שבמדרגות העליונות היתה עומדת. וכן המראה של אלו הגוונין עומדים תחתיה דהיינו מתחת הנוקבא, גוון אחד. מימין, שהוא גוון לבן, חסד. גוון אחד משמאל. שהוא גוון אדום, גבורה. גוון אחד הכלול מכל הגוונים, שהוא גוון ירוק, תפארת. והיא, דהיינו הנוקבא הנקראת מחזה, המראה של כל גוונין העליונים, לבן אדום וירוק, העומדים עליה. ועל זה במראה ההוא, עמד על אברהם ודיבר עמו, אף על פי שלא נמול. כיון שנמול מה כתוב וירא אליו הוי\"ה. כי נתחבר בה השם הויה, דהיינו עצם מדרגות העליונות נכללו בה, משא\"כ מטרם שנמול שרק הגוונין לבדם נכללו בה."],[9,"ת\"ח מחזה וכו':","בוא וראה. \u0003מחזה שדי\u0004 כתוב בבלעם. ובאברהם כתוב \u0003מחזה\u0004 סתם. ושואל. מה ההפרש בין זה לזה, ומשיב, אלא \u0003מחזה שדי,\u0004 הוא אלו הגוונין שמתחת הנוקבא, והם המראה שלה. \u0003מחזה\u0004 סתם. זה הוא \u0003ה'\u0004 של השם הויה, דהיינו הנוקבא, שכל הצורות העליונות, שהם ג' הגוונין, נראות בה. ומשום זה כתוב באברהם \u0003מחזה\u0004 סתם. ובבלעם \u0003מחזה שדי.\u0004 דהיינו כנ\"ל בדבור הסמוך, שנכללת בעצמה מג' הגוונין לבן אדום ירוק, וכן \u0003וחיזו דאינון גוונין קיימי תחותיה,\u0004 ע\"ש. ובזה מחלק בין נבואת אברהם שהיה מג' גוונין שבעצם הנוקבא, וזהו \u0003מחזה\u0004 סתם. לבין נבואת בלעם שהיה ממראה ג' הגוונים שמתחת הנוקבא שנקראת \u0003מחזה שדי.\u0004"],[10,"ועל דא עד לא וכו':","ועל כן, מטרם שנמול אברהם, היה לו אותה המדרגה, כמו שאמרנו, דהיינו הנקראת \u0003מחזה\u0004 סתם. כיון שנמול, מיד וירא הויה אליו וגו'. שכל המדרגות של הויה נראות על מדרגה זו, שהיא הנוקבא דהיינו עצם המדרגות כנ\"ל. ומדרגה זו דיברה עמו כראוי, בשלמות, כי הנוקבא היא סוד הדיבור. ואברהם נתקשר ממדרגה למדרגה ונכנס באות ברית הקדוש כראוי, בשלמות."]],[[0,"","כְּמוֹ כֵן כָּל אוֹתָם הַצַּדִּיקִים, אַחַר שֶׁיּוֹצְאִים מִן הָעוֹלָם הַזֶּה, כָּל הַנְּפָשׁוֹת עוֹלוֹת, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְזַמֵּן לָהֶם דְּמוּת אַחֶרֶת לְהִתְלַבֵּשׁ בָּהּ כְּמוֹ שֶׁהָיוּ בָּעוֹלָם הַזֶּה. מִשּׁוּם כָּךְ כֻּלָּם עוֹמְדִים לְפָנָיו, וְרָאָה אוֹתָם אָדָם הָרִאשׁוֹן בְּעַיִן."],[1,"","וְאִם תֹּאמַר, שֶׁאַחַר שֶׁרָאָה אוֹתָם לֹא עָמְדוּ בְקִיּוּמָם - בֹּא וְתִרְאֶה, כָּל דִּבְרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא הֵם בְּקִיּוּם וְעוֹמְדִים לְפָנָיו עַד שֶׁיּוֹרְדִים לָעוֹלָם. כְּמוֹ זֶה כָּתוּב (דברים כט) כִּי אֶת אֲשֶׁר יֶשְׁנוֹ פֹּה וְגוֹ'. הֲרֵי פֵּרְשׁוּהָ, שֶׁכָּל בְּנֵי הָאָדָם שֶׁעֲתִידִים לִהְיוֹת בָּעוֹלָם, כֻּלָּם נִמְצְאוּ שָׁם."],[2,"","כָּאן יֵשׁ לְהִסְתַּכֵּל, שֶׁהֲרֵי כָּתוּב אֶת אֲשֶׁר אֵינֶנּוּ פֹּה וְגוֹ', וּמַשְׁמָע אֵלּוּ (כלם) שֶׁיָּצְאוּ מֵאוֹתָם שֶׁעָמְדוּ שָׁם, מִשּׁוּם שֶׁכָּתוּב עִמָּנוּ הַיּוֹם, וְלֹא כָתוּב עִמָּנוּ עוֹמֵד הַיּוֹם. אֶלָּא וַדַּאי (כאן) כֻּלָּם עָמְדוּ שָׁם, אֶלָּא שֶׁלֹּא נִרְאוּ לָעַיִן, מִשּׁוּם כָּךְ כָּתוּב עִמָּנוּ הַיּוֹם אַף עַל גַּב שֶׁלֹּא נִרְאוּ."],[3,"","וְאִם תֹּאמַר, מָה הַטַּעַם לֹא נִרְאוּ כָּאן כְּמוֹ שֶׁנִּרְאוּ לְאָדָם הָרִאשׁוֹן שֶׁרָאָה אוֹתָם עַיִן בְּעַיִן, וַהֲרֵי כָּאן רָאוּ יוֹתֵר? אֶלָּא כָּאן, כְּשֶׁנִּתְּנָה תוֹרָה לְיִשְׂרָאֵל, מַרְאֶה אַחֵר וּדְרָגוֹת עֶלְיוֹנוֹת. הָיוּ רוֹאִים וּמִסְתַּכְּלִים עַיִן בְּעַיִן, וְהָיוּ מִשְׁתּוֹקְקִים לְהִסְתַּכֵּל וְלִרְאוֹת בִּכְבוֹד רִבּוֹנָם, וּמִשּׁוּם כָּךְ רָאוּ אֶת הַכָּבוֹד הָעֶלְיוֹן שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ וְלֹא מֵאַחֵר."],[4,"","וְעַל כֵּן, כָּל בְּנֵי הָאָדָם שֶׁעֲתִידִים לַעֲמֹד בָּעוֹלָם, כֻּלָּם עוֹמְדִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתָן הַדְּמֻיּוֹת מַמָּשׁ שֶׁעֲתִידִים לַעֲמֹד בָּהֶן. זֶהוּ שֶׁכָּתוּב (תהלים קלט) גָּלְמִי רָאוּ עֵינֶיךְ וְעַל סִפְרְךְ וְגוֹ'. גָּלְמִי רָאוּ עֵינֶיךְ, מָה הַטַּעַם? מִשּׁוּם שֶׁדְּמוּת אַחֶרֶת עֶלְיוֹנָה הָיְתָה כָּזֶה, וּמִשּׁוּם כָּךְ כָּתוּב (שם יח) וּמִי צוּר זוּלָתִי אֱלֹהֵינוּ, מִי הַצַּיָּר הַטּוֹב שֶׁצִּיֵּר (שכולל) הַכֹּל (זה עם זה) כְּמוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא?"],[5,"","דָּבָר אַחֵר כִּי מִי אֱלוֹהַּ - זֶה סוֹד הַדָּבָר, שֶׁהֲרֵי אֵל הוּא כְּלָל שֶׁנִּכְלָל מִכָּל הַדְּרָגוֹת. וְאִם תֹּאמַר שֶׁאֵל הַזֶּה הִיא דַּרְגָּה אַחֶרֶת, מִשּׁוּם שֶׁכָּתוּב (שם ז) וְאֵל זעֵם בְּכָל יוֹם? בֹּא רְאֵה, שֶׁהֲרֵי אֵין אֵל מִבַּלְעֲדֵי ה' שֶׁאֵינוֹ לְבַדּוֹ, וְלֹא נִפְרָד לְעוֹלָמִים, וְעַל כֵּן כָּתוּב (שמואל ב כב) כִּי מִי אֵל מִבַּלְעֲדֵי ה' וְגוֹ'. וּמִי צוּר וְגוֹ', שֶׁהֲרֵי צוּר אֵינוֹ לְבַדּוֹ, אֶלָּא הַכֹּל אֶחָד, כַּכָּתוּב (דברים ד) וְיָדַעְתָּ הַיּוֹם וַהֲשֵׁבתָ אֶל לְבָבֶךְ כִּי ה' הוּא הָאֱלֹהִים וְגוֹ'."],[6,"","בֹּא רְאֵה, שֶׁטֶּרֶם שֶׁנִּמּוֹל אַבְרָהָם, הָיָה מְדַבֵּר עִמּוֹ מִתּוֹךְ מַחֲזֶה לְבַדּוֹ, כְּמוֹ שֶׁנֶּאֱמַר, שֶׁכָּתוּב הָיָה דְבַר ה' אֶל אַבְרָם בַּמַּחֲזֶה וְגוֹ'. בַּמַּחֲזֶה - בְּאוֹתוֹ הַמַּרְאֶה, הַדַּרְגָּה שֶׁכָּל הַדְּמֻיּוֹת נִרְאוֹת בָּהּ, כְּמוֹ שֶׁנֶּאֱמַר. וְהַמַּחֲזֶה הַזֶּה הוּא סוֹד הַבְּרִית."],[7,"","וְאִם תֹּאמַר שֶׁמִּשּׁוּם כָּךְ נִקְרָא מַחֲזֶה, מִשּׁוּם שֶׁהִיא הַדַּרְגָּה הַמַּרְאֶה שֶׁכָּל הַדְּמֻיּוֹת נִרְאוֹת בָּהּ וְאָז נִקְרֵאת מַחֲזֶה - הֲרֵי אָמַרְתָּ בָּרִאשׁוֹנָה, שֶׁטֶּרֶם שֶׁנִּמּוֹל אַבְרָהָם, לֹא הָיָה מְדַבֵּר עִמּוֹ, רַק הַדַּרְגָּה הַזּוֹ שֶׁאֵין שׁוֹרִים עָלֶיהָ הַדְּרָגוֹת הָאֲחֵרוֹת, וְעַכְשָׁו אָמַרְתָּ בַּמַּחֲזֶה - הַמַּרְאֶה שֶׁל כָּל הַדְּרָגוֹת הָעֶלְיוֹנוֹת הוּא, וַהֲרֵי טֶרֶם שֶׁנִּמּוֹל כָּתוּב הָיָה דְבַר ה' אֶל אַבְרָם בַּמַּחֲזֶה?"],[8,"","אֶלָּא הַדַּרְגָּה הַזּוֹ הִיא הַמַּרְאֶה שֶׁל כָּל הַדְּרָגוֹת הָעֶלְיוֹנוֹת, וּבַמַּרְאֶה שֶׁל הַדְּרָגוֹת הָעֶלְיוֹנוֹת נִתְקְנָה. וְאַף עַל גַּב שֶׁבְּאוֹתוֹ הַזְּמַן אַבְרָהָם לֹא הָיָה מָהוּל - הַדַּרְגָּה הַזּוֹ בַּמַּרְאֶה שֶׁל הַדְּרָגוֹת הָעֶלְיוֹנוֹת הִיא, וּבְכָל אוֹתָם הַגְּוָנִים עוֹמֶדֶת, וְהַמַּרְאֶה שֶׁל אוֹתָם הַגְּוָנִים עוֹמֵד תַּחְתֶּיהָ. אֶחָד מִיָּמִין - גָּוֶן לָבָן, וְאֶחָד מִשְּׂמֹאל - גָּוֶן אָדם, אֶחָד שֶׁכָּלוּל מִכָּל הַגְּוָנִים. וְהוּא הַמַּרְאֶה שֶׁכָּל הַגְּוָנִים הָעֶלְיוֹנִים עוֹמְדִים עָלָיו. וְעַל זֶה בַּמַּרְאֶה הַזֶּה עָמַד עַל אַבְרָהָם וְדִבֵּר עִמּוֹ, וְאַף עַל גַּב שֶׁלֹּא נִמּוֹל. כֵּיוָן שֶׁנִּמּוֹל מַה כָּתוּב? וַיֵּרָא ה' אֶל אַבְרָם."],[9,"","בֹּא רְאֵה, בְּבִלְעָם (אמר) כָּתוּב מַחֲזֵה שַׁדַּי, וּבְאַבְרָהָם כָּתוּב מַחֲזֶה סְתָם. מַה בֵּין זֶה לָזֶה? אֶלָּא מַחֲזֵה שַׁדַּי אֵלּוּ שֶׁלְּמַטָּה (שיצאו) מִמֶּנּוּ, וְהֵם הַמַּרְאֶה שֶׁלּוֹ. מַחֲזֶה סְתָם, מַחֲזֶה זֶה הוּא ה' (של כל מראה) שֶׁכָּל הַדְּמֻיּוֹת הָעֶלְיוֹנוֹת נִרְאוֹת בּוֹ. וּמִשּׁוּם כָּךְ כָּתוּב בְּאַבְרָהָם מַחֲזֶה סְתָם, וּבְבִלְעָם מַחֲזֵה שַׁדַּי."],[10,"","וְעַל כֵּן, טֶרֶם שֶׁנִּמּוֹל אַבְרָהָם, הָיְתָה לוֹ הַדַּרְגָּה הַזּוֹ כְּפִי שֶׁאָמַרְנוּ. כֵּיוָן שֶׁנִּמּוֹל, מִיָּד וַיֵּרָא אֵלָיו ה' וְגוֹ'. נִרְאוּ כָּל (שאר) הַדְּרָגוֹת עַל הַדַּרְגָּה הַזּוֹ, וְהַדַּרְגָּה הַזּוֹ דִּבְּרָה עִמּוֹ כָּרָאוּי בִּשְׁלֵמוּת. וְאַבְרָהָם נִקְשַׁר מִדַּרְגָּה לְדַרְגָּה, וְנִכְנַס לִבְרִית הַקֹּדֶשׁ כָּרָאוּי בִּשְׁלֵמוּת."]]],[["תָּא חֲזֵי, כֵּיוָן דְּאִתְגְּזַר אַבְרָהָם, נָפַק מֵעָרְלָה וְעָאל בִּקְיָימָא קַדִּישָׁא וְאִתְעַטַּר בְּעִטְּרָא קַדִּישָׁא וְעָאל בְּקִיּוּמָא דְּעָלְמָא קָאִים עֲלֵיהּ, וּכְדֵין אִתְקְיַּים עָלְמָא בְּגִינֵיהּ. בְּגִין דִּכְתִיב (ירמיהו ל״ג:כ״ה) אִם לֹא בְרִיתִי יוֹמָם וָלַיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לא שָׂמְתִּי. וּכְתִיב (בראשית ב׳:ד׳) אֵלֶּה תּוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם. בְּה\"א בָּרְאָם, בְּאַבְרָהָם. וְכֹלָּא בְּרָזָא חָדָא קָאִים. וּבְשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא אַחֲמֵי לֵיהּ לְאָדָם כָּל אִנּוּן דָּרִין דְּעָלְמָא, וְחָמָא לוֹן כָּל חַד וְחַד כָּל דָּרָא וְדָרָא כֻּלְהוּ קָיְמֵי בְּגִנְתָּא דְעֵדֶן בְּהַהוּא דִּיוּקְנָא דְּזַמִּינִין לְקָיְימָא בְּהַאי עָלְמָא.","וְתָּא חֲזֵי, הָא אִתְּמָר כֵּיוָן דְּחָמָא לֵיהּ לְדָוִד דְּלָאו בֵּיהּ חַיִּים כְּלַל, תָּוָהּ, וְאִיהוּ יְהִיב לֵיהּ מִדִּילֵיהּ ע' שְׁנִין, בְגִין כָּךְ הֲווּ לֵיהּ לְאָדָם תְּשַׁע מֵאוֹת וּתְלָתִין שְׁנִין. וְאִנּוּן שִׁבְעִין אִסְתַּלָּקוּ לֵיהּ לְדָוִד.","וּמִלָּה דָּא רָזָא דְּחָכְמְתָא אִיהוּ, דְּדָוִד לֵית לֵיהּ (יומין) בַּר שִׁבְעִין שְׁנִין מֵאָדָם קַדְמָאָה, וְכֹלָּא רָזָא דְּחָכְמְתָא אִיהוּ. וְכָל מַה דִּלְתַתָּא כֹּלָּא אִיהוּ בְּרָזָא דִּלְעֵילָא.","וְתָּא חֲזֵי, בְּכָל אִנּוּן דִּיוּקְנִין דְּנִשְׁמָתִין דְּעָלְמָא כֻּלְהוּ זִוּוּגִין זִוּוּגִין קַמֵּיהּ. לְבָתַר כַּד אַתְיָין לְהַאי עָלְמָא קוּדְשָׁא בְּרִיךְ הוּא מְזַוִּוג זִוּוּגִין. אָמַר רַבִּי (יהודה) יִצְחָק קוּדְשָׁא בְּרִיךְ הוּא (מזווג זווגין ואמר) אָמַר בַּת פְּלוֹנִי לִפְלוֹנִי. אָמַר רַבִּי יוֹסֵי מַאי קָא מַיְירֵי וְהָא כְּתִיב, (קהלת א׳:ט׳) אֵין כָּל חָדָשׁ תַּחַת הַשֶּׁמֶשׁ. אָמַר רַבִּי יְהוּדָה תַּחַת הַשֶּׁמֶשׁ כְּתִיב, שָׁאנֵי לְעֵילָא.","אָמַר רַבִּי יוֹסֵי מַאי כָּרוֹזָא הָכָא. וְהָא אָמַר רַבִּי חִזְקִיָּה אָמַר רַבִּי חִיָּיא בְּהַהִיא שַׁעֲתָא מַמָּשׁ דְּנָפִיק בַּר נָשׁ לְעָלְמָא בַּת זוּגוֹ אִזְדַמְּנַת לוֹ.","אָמַר רַבִּי אַבָּא זַכָּאִין אִנּוּן צַדִּיקַיָּיא דְּנִשְׁמַתְהוֹן מִתְעַטְּרִין קַמֵּי מַלְכָּא קַדִּישָׁא עַד לָא יֵיתוּן לְעָלְמָא, דְּהָכִי תָּנִינָן בְּהַהִיא שַׁעֲתָא דְּאַפִּיק קוּדְשָׁא בְּרִיךְ הוּא נִשְׁמָתִין לְעָלְמָא, כָּל אִנּוּן רוּחִין וְנִשְׁמָתִין כֻּלְהוּ כְּלִילָן דְּכַר וְנוּקְבָא דְּמִתְחַבְּרָן כְּחֲדָא.","וְאִתְמַסְּרָן בִּידָא דְּהַהוּא מְמַנָּא שְׁלִיחָא דְּאִתְפַּקַּד עַל עִדּוּאֵיהוֹן דִּבְנֵי נָשָׁא. וְלַיְלָה שְׁמֵיהּ, וּבְשַׁעֲתָא דְּנָחֲתִין וְאִתְמַסְרָן בִּידוֹי מִתְפָּרְשִׁין, וּלְזִמְנִין דָּא אַקְדִּים מִן דָּא וְאָחִית לְהוּ בִּבְנֵי נָשָׁא.","וְכַד (מחא) מָטָא עִידָן דְּזִוּוּגָא דִלְהוֹן. קוּדְשָׁא בְּרִיךְ הוּא דְּיָדַע אִנּוּן רוּחִין וְנִשְׁמָתִין מְחַבַּר לוֹן כִּדְבְּקַדְמִיתָא וּמַכְרְזָא עֲלַיְיהוּ. וְכַד אִתְחַבְּרָן אִתְעֲבִידוּ חַד גּוּפָא חַד נִשְׁמָתָא יָמִינָא וּשְׂמָאלָא כְּדְקָא חָזֵי, וּבְגִין כָּךְ אֵין כָּל חָדָשׁ תַּחַת הַשָּׁמֶשׁ.","וְאִי תֵימָא הָא תָּנִינָן לֵית זִוּוּגָא אֶלָּא לְפוּם עוֹבָדוֹי וְאָרְחוֹי דְּבַר נָשׁ. הָכִי הוּא וַדַּאי. דְּאִי זָכֵי וְעוֹבָדוֹי אִתְכַּשְׁרָן, זָכֵי לְהַהוּא דִּילֵיהּ לְאִתְחַבָּרָא בֵּיהּ כְּמָה דְּנָפִיק.","אָמַר רַבִי חִיָּיא מַאן דְּאִתְכַּשְׁרָן עוֹבָדוֹי בְּאָן אֲתַר יִתְבַּע (ס\"א יתבא) הַהוּא זִוּוּגָא דִּילֵיהּ. אָמַר לֵיהּ הָא תָּנִינָן לְעוֹלָם יִמְכֹּר אָדָם כו' וְיִשָּׂא בַּת תַּלְמִיד חָכָם (ד\"א ל\"ג תא חזי). דְּתַלְמִיד חָכָם פִּקְדוֹנָא דְמָארֵיהּ אִתְפַּקְדָן בִּידֵיהּ.","תָּאנָא בְּרָזָא דְּמַתְנִיתָּא כָּל אִנּוּן דְּאָתוּ בְּגִלְגּוּלָא דְּנִשְׁמָתִין יָכְלִין לְאַקְדָּמָא בְּרַחֲמֵי זִוּוּגָא דִּלְהוֹן. וְעַל הַאי אִתְעָרוּ חַבְרַיָיא. (אין נושאין נשים במועד אבל מקדשין) שֶׁמָּא יְקַדְּמֶנּוּ אַחֵר בְּרַחֲמִים. וְשַׁפִּיר קָאֲמְרוּ אַחֵר דַּיְיקָא, וְעַל כֵּן קָשִׁין זִוּוּגִין קַמֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא. וְעַל כֹּלָּא (פנים) וַדַּאי כִּי יְשָׁרִים דַּרְכֵי יְיָ כְּתִיב.","רַבִּי יְהוּדָה שָׁלַח לֵיהּ לְרַבִּי אֶלְעָזָר אָמַר הָא רָזָא דְמִלָּה יְדַעְנָא, אִנּוּן דְּאָתוּ בְּגִלְגּוּלָא דְּנִשְׁמָתִין מֵאָן אֲתַר לְהוּ זִוּוּגָא. שְׁלַח לֵיהּ כְּתִיב, (שופטים כ״א:ז׳) מַה נַּעֲשֶׂה לָהֶם לַנּוֹתָרִים לְנָשִׁים וְגו'. וּכְתִיב לְכוּ וַחֲטַפְתֶּם לָכֶם וְגו'. פַּרְשָׁתָא דִּבְנִי בִנְיָמִין אוֹכַח וְעַל הַאי תָּנִינָן שֶׁמָּא יְקַדְמֶנּוּ אַחֵר בְּרַחֲמִים. (כי אותו אחר אין לו בת זוגו, אבל תשכח דא כגון בר נש דנסיב בת זוגיה ולא הוו ליה מנה בנין ומת, ייתי אחוהי וייבם אתתיה ויתיליד ליה מנה בר. האי בר הוא מיתא דאהדרת נשמתיה לעלמא. דא הוא אחר דאין לו בת זוג אלא אמיה, ודא הוא שמא יקדמנו אחר ברחמים דיכיל לאקדמא אחרא למיסב אתתיה דדא ברחמי ובצלותא ואף על גב דאמינא לך דיכיל לאקדמא ברחמי לא יכיל אלא אם (הוא) בעלה חייבא איהו ואיהו זכאה)"],[[0,"ת\"ח כיון דאתגזר וכו':","כיון שנמול אברהם, יצא מקליפת הערלה, ונכנס בברית הקדוש, ונתעטר בעטרה הקדושה, ונכנס בברית שהעולם עומד עליו, ואז נתקיים העולם בשבילו. משום שכתוב, אם לא בריתי יומם ולילה חוקות שמים וארץ לא שמתי, הרי שבזכות הברית מילה מתקיים העולם. וכתוב, אלה תולדות השמים והארץ בהבראם, שהוא אותיות \u0003בה' בראם,\u0004 וכן \u0003באברהם,\u0004 להורות, שבשביל אברהם נברא העולם. והכל בסוד אחד עומד. כלומר, שהוא ענין אחד עם קיום הברית מילה. כי ע\"כ נברא העולם \u0003באברהם,\u0004 משום שנכנס בברית מילה, שעליה כתוב אם לא בריתי יומם, וגו' כנ\"ל."],[1,"ובשעתא דקב\"ה אחמי וכו':","ובעת שהקב\"ה הראה לו לאדם הראשון כל אלו דורות שבעולם, וראה אותם כל אחד ואחד, כל דור ודור, כולם עומדים בגן עדן, באותה הצורה שעתידים לעמוד בה בעולם, ובוא וראה הרי למדנו, כיון שראה את דוד, שאין לו שנות חיים כלל, היה תוהה, והוא נתן לו משלו ע' שנים, משום זה היה לאדם רק תשע מאות ושלשים שנה. ואלו ע' שנים החסרים עד אלף שנה, ניתנו לדוד."],[2,"ומלה דא וכו':","ודבר זה סוד החכמה הוא. שדוד אין לו רק שבעים השנים שנתן לו אדם הראשון, והכל בסוד החכמה הוא, כי כל מה שלמטה הכל הוא בסוד הנעשה מלמעלה, בעולם העליון."],[3,"ת\"ח בכל וכו':","בא וראה. בכל אלו הנשמות העתידות לבא בעולם, כולן הן זווגים זווגים לפניו. כלומר, שכל אחת מחולקת לזכר ונקבה. אחר כך כשבאים לעולם הזה, הקב\"ה מזווג זווגים. אמר ר' יצחק, הקב\"ה אמר, בת פלוני לפלוני."],[4,"א\"ר יוסי מאי קא מיירי וכו':","אר\"י. מה הוא הכונה, במה שאומר שהקב\"ה אמר בת פלוני לפלוני. הרי כתוב אין כל חדש תחת השמש. אלא הכל כבר נעשה במעשה בראשית ולדברך יהיו ענין הזווגים דבר חדש בכל זווג, שצריך להכריז בת פלוני לפלוני. אמר ר' יהודה תחת השמש כתוב, מה שאין כן למעלה מהשמש יש חדש. אמר ר' יוסי למה הכריז כאן, לומר בת פלוני לפלוני, והרי אמר ר' חזקיה אמר ר' חייא, באותה שעה ממש שהאדם נולד ויוצא לעולם, מזדמנת לו בת זוגו."],[5,"אמר ר' אבא וכו':","ומשיב ר' אבא. אשריהם הצדיקים, שנשמותיהם מתעטרות לפני המלך הקדוש מטרם שבאות לעולם להתלבש בגוף. כי כן למדנו. באותה שעה, שהקב\"ה מוציא הנשמות לעולם, כל אלו הרוחות והנשמות כולם כלולים מזכר ונקבה שמתחברים יחד."],[6,"ואתמסרן בידא וכו':","ונמסרים בידי אותו הממונה, השליח, שהפקד על עיבור בני אדם, ושמו לילה. ובשעה שיורדים לעולם ונמסרים בידיו של אותו הממונה הם מתפרדים זה מזה ולפעמים אחד מקדים את חבירו לירד להתלבש בבני אדם."],[7,"וכד מטא עידן וכו':","וכשמגיע עת הזווג שלהם הקב\"ה המכיר את הזכרים והנקבות של אלו הרוחות והנשמות, הוא מחבר אותם כמו שהיו בתחילה, מטרם שבאו לעולם, ומכריז עליהם בת פלוני לפלוני וכשמתחברים נעשו שניהם, גוף אחד ונשמה אחת, והם ימין ושמאל כראוי. שהזכר הוא חלק הימין של הגוף והנשמה והנקבה חלק השמאל מהם. ומשום זה אין כל חדש תחת השמש. כלומר אע\"פ שהקב\"ה מכריז בת פלוני לפלוני, עם כל זה אין זה חידוש, אלא החזרה למה שהיו מקודם שבאו לעולם. וכיון שאין זה ידוע אלא להקב\"ה, ע\"כ מכריז עליהם."],[8,"ואי תימא הא","וכו': ואם תאמר, הרי למדנו אין מזווגין לאדם אלא לפי מעשיו ודרכיו. כן הוא ודאי, אם הוא זוכה ומעשיו ישרים, הוא זוכה את בת זוג שלו להתחבר בה כמו שהיו מחוברים לעת צאתם מהקב\"ה, מטרם שנתלבשו בגוף."],[9,"אמר ר' חייא","וכו': מי שמעשיו ישרים באיזה מקום יבקש את בת זוגו. אמר לו הרי למדנו. לעולם ימכור אדם וכו' וישא בת תלמיד חכם. כי התלמיד חכם, הפקדון של רבונו נפקד בידו. וודאי ימצא אצלו בת זוגו."],[10,"תאנא ברזא דמתניתא וכו':","למדנו בסוד ברייתא. כל אלו הנשמות הבאות בגלגול הנשמות, ואין להם בת זוג (כמ\"ש בפרשת משפטים אות קל\"ג) יכולים להקדים ברחמים את הזווג שלהם, דהיינו שיקדימו ויטלו בת זוגו של אדם אחר. ועל זה העירו החברים ואמרו אין נושאים נשים במועד אבל מקדשין, שמא יקדמנו אחר ברחמים. ויפה אמרו. \u0003אחר דייקא.\u0004 פירוש. כי אותו המגולגל שאין לו בת זוג, הוא משום שירד ונעשה לבחינת אחורים, הנבחן בעצמו לבחינת נוקבא, וע\"כ אין לו בת זוג, ועל כן נקרא המגולגל הזה בשם, \u0003אחר\u0004 להורות שהוא בא מאחורים. וזהו שאומר \u0003אחר\u0004 דייקא, דהיינו שבא מאחורים, ואין לו בת זוג, וע\"כ נוהג בו שיטול בת זוגו של חבירו."],[10,"ועל כן קשין:","ועל כן קשים זווגים לפני הקב\"ה. פירוש. כי לפי הנ\"ל שזכר ונקבה המזדווגים הם ב' חלקים של נשמה אחת. והיו מתחלקים כן עוד מטרם שבאו לעולם, א\"כ למה אמרו שקשה זווגו של אדם לפני הקב\"ה. הרי אין כאן אלא חזרה על הנעשה מכבר. אבל לפי מה שנתבאר שיש נשמות מגולגלות שאין להם בת זוג, אשר מקדימים ונוטלים בת זוג של חבירו על ידי רחמים. ואח\"כ אם חבירו זוכה במעשיו שיחזירו לו, בת זוגי, צריך הקב\"ה ליטול מזה וליתן לזה, וזהו קשה לפניו לדחות אחד מפני חבירו. ועל הכל, ודאי, כי ישרים דרכי ה' כתוב. וכל מה שעושה הקב\"ה, הוא טוב וישר."],[11,"ר' יהודה וכו':","ר\"י שלח שאלה לר' אלעזר, אמר, הרי סוד הדבר ידעתי, על כן אני שואל, אלו הבאים בגלגול הנשמות ואין להם בת זווג מאיזה מקום לוקחים את בת זוגם. שלח לו. כתוב, מה נעשה לנותרים לנשים וגו', וכתוב לכו וחטפתם לכם וגו'. פרשה זו דבני בנימין מוכיח, על הנשמות המגולגלות, שצריכים להקדים ברחמים וליטול מאחר את בת זוגם. ועל זה למדנו שמא יקדמנו אחר ברחמים."]],[[0,"","בֹּא רְאֵה, כֵּיוָן שֶׁנִּמּוֹל אַבְרָהָם, יָצָא מֵהָעָרְלָה, וְנִכְנַס לַבְּרִית הַקְּדוֹשָׁה, וְהִתְעַטֵּר בַּעֲטָרָה קְדוֹשָׁה, וְנִכְנַס בַּבְּרִית שֶׁהָעוֹלָם עוֹמֵד עָלֶיהָ, וְאָז הִתְקַיֵּם הָעוֹלָם בִּגְלָלוֹ, מִשּׁוּם שֶׁכָּתוּב (ירמיה לג) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי, וְכָתוּב (בראשית ב) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, בְּהֵ\"א בְּרָאָם, בְּאַבְרָהָם, וְהַכֹּל עוֹמֵד בְּסוֹד אֶחָד. וּבְשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הֶרְאָה לָאָדָם אֶת כָּל אוֹתָם הַדּוֹרוֹת שֶׁל הָעוֹלָם, וְרָאָה אוֹתָם כָּל אֶחָד וְאֶחָד, כָּל דּוֹר וָדוֹר, כֻּלָּם עוֹמְדִים בְּגַן הָעֵדֶן בְּאוֹתָהּ הַדְּמוּת שֶׁעֲתִידִים לַעֲמֹד בָּהּ בָּעוֹלָם הַזֶּה."],[1,"","וּבֹא וּרְאֵה, הֲרֵי נִתְבָּאֵר, כֵּיוָן שֶׁרָאָה אֶת דָּוִד שֶׁאֵין בּוֹ חַיִּים כְּלָל, תָּמַהּ, וְהוּא נָתַן לוֹ מִשֶּׁלּוֹ שִׁבְעִים שָׁנִים. מִשּׁוּם כָּךְ הָיוּ לוֹ לְאָדָם תְּשַׁע מֵאוֹת וּשְׁלֹשִׁים שָׁנִים, וְאוֹתָם הַשִּׁבְעִים עָלוּ לוֹ לְדָוִד."],[2,"","וְהַדָּבָר הַזֶּה הוּא סוֹד שֶׁל חָכְמָה, שֶׁלְּדָוִד אֵין (ימים) פְּרָט לְשִׁבְעִים הַשָּׁנִים מֵאָדָם הָרִאשׁוֹן. וְהַכֹּל הוּא סוֹד שֶׁל חָכְמָה. וְכָל מַה שֶּׁלְּמַטָּה, הַכֹּל הוּא בַּסּוֹד שֶׁל מַעְלָה."],[3,"","וּבֹא וּרְאֵה, בְּכָל אוֹתָן הַדְּמֻיּוֹת שֶׁל הַנְּשָׁמוֹת שֶׁל הָעוֹלָם, כֻּלָּם לְפָנָיו זוּגוֹת זוּגוֹת. לְאַחַר מִכֵּן, כְּשֶׁבָּאִים לָעוֹלָם הַזֶּה, הַקָּדוֹשׁ בָּרוּךְ הוּא מְזַוֵּג זִוּוּגִים. אָמַר רַבִּי (יהודה) יִצְחָק, הַקָּדוֹשׁ בָּרוּךְ הוּא (מזוג זווגים ואומר) אוֹמֵר בַּת פְּלוֹנִי לִפְלוֹנִי. אָמַר רַבִּי יוֹסֵי, מַה זֶּה אוֹמֵר, וַהֲרֵי כָּתוּב (קהלת א) אֵין כָּל חָדָשׁ תַּחַת הַשָּׁמֶשׁ? אָמַר רַבִּי יְהוּדָה, תַּחַת הַשָּׁמֶשׁ כָּתוּב, שׁוֹנֶה לְמַעְלָה."],[4,"","אָמַר רַבִּי יוֹסֵי, מַה כָּאן הַכְּרוּז, וַהֲרֵי אָמַר רַבִּי חִזְקִיָּה אָמַר רַבִּי חִיָּיא, בְּאוֹתָהּ שָׁעָה מַמָּשׁ שֶׁיּוֹצֵא אָדָם לָעוֹלָם, בַּת זוּגוֹ מְזֻמֶּנֶת לוֹ?"],[5,"","אָמַר רַבִּי אַבָּא, אַשְׁרֵי הַצַּדִּיקִים שֶׁנִּשְׁמוֹתֵיהֶם מִתְעַטְּרוֹת לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ טֶרֶם יָבֹאוּ לָעוֹלָם. שֶׁכָּךְ שָׁנִינוּ, בַּשָּׁעָה הַהִיא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מוֹצִיא נְשָׁמוֹת לָעוֹלָם, כָּל אוֹתָן הָרוּחוֹת וְהַנְּשָׁמוֹת, כֻּלָּן כְּלוּלוֹת זָכָר וּנְקֵבָה שֶׁמְּחֻבָּרוֹת יַחַד."],[6,"","וְנִמְסָרוֹת בִּידֵי אוֹתוֹ הַמְמֻנֶּה הַשָּׁלִיחַ שֶׁנִּתְמַנָּה עַל הֶרְיוֹנוֹת בְּנֵי הָאָדָם, וּשְׁמוֹ לַיְלָה. וּבְשָׁעָה שֶׁיּוֹרְדוֹת וְנִמְסָרוֹת בְּיָדָיו, נִפְרָדוֹת, וְלִפְעָמִים זֶה מַקְדִּים לִפְנֵי זֶה, וּמוֹרִיד אוֹתָם בִּבְנֵי הָאָדָם."],[7,"","וּכְשֶׁמַּגִּיעַ (מכה) זְמַן זִוּוּגָם, הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁמַּכִּיר אוֹתָן הָרוּחוֹת וְהַנְּשָׁמוֹת מְחַבֵּר אוֹתָן כְּבָרִאשׁוֹנָה וּמַכְרִיז עֲלֵיהֶם. וּכְשֶׁמִּתְחַבְּרִים, נַעֲשִׂים גּוּף אֶחָד וּנְשָׁמָה אַחַת, יָמִין וּשְׂמֹאל כָּרָאוּי, וּמִשּׁוּם כָּךְ אֵין כָּל חָדָשׁ תַּחַת הַשָּׁמֶשׁ."],[8,"","וְאִם תֹּאמַר, הֲרֵי שָׁנִינוּ שֶׁאֵין זִוּוּג אֶלָּא לְפִי מַעֲשֵׂי וְדַרְכֵי הָאָדָם - כָּךְ זֶה וַדַּאי! שֶׁאִם זוֹכֶה וּמַעֲשָׂיו כְּשֵׁרִים, הוּא זוֹכֶה לְהִתְחַבֵּר עִם אוֹתוֹ שֶׁלּוֹ כְּמוֹ שֶׁיָּצָא."],[9,"","אָמַר רַבִּי חִיָּיא, מִי שֶׁמַּעֲשָׂיו כְּשֵׁרִים, בְּאֵיזֶה מָקוֹם יְבַקֵּשׁ (יושב) אֶת זִוּוּגוֹ? אָמַר לוֹ, הֲרֵי שָׁנִינוּ, לְעוֹלָם יִמְכֹּר אָדָם וְכוּ' וְיִשָּׂא בַּת תַּלְמִיד חָכָם, (ד\"א ובא ראה) שֶׁתַּלְמִיד חָכָם פִּקְדוֹן רִבּוֹנוֹ נִפְקָד בְּיָדוֹ."],[10,"","שָׁנִינוּ בְּסוֹד הַמִּשְׁנָה, כָּל אוֹתָם שֶׁבָּאוּ בְּגִלְגּוּל שֶׁל נְשָׁמוֹת, יְכוֹלִים לְהַקְדִּים בְּרַחֲמִים אֶת זִוּוּגָם. וְעַל זֶה הֵעִירוּ הַחֲכָמִים, אֵין נוֹשְׂאִים נָשִׁים בַּמּוֹעֵד, אֲבָל מְקַדְּשִׁים, שֶׁמָּא יְקַדְּמֶנּוּ אַחֵר בְּרַחֲמִים. וְיָפֶה אָמְרוּ אַחֵר בְּדִיּוּק. וְעַל כֵּן קָשִׁים הַזִּוּוּגִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. וְעַל כָּל פָּנִים וַדַּאי כָּתוּב כִּי יְשָׁרִים דַּרְכֵי ה'."],[11,"","רַבִּי יְהוּדָה שָׁלַח לְרַבִּי אֶלְעָזָר. אָמַר, הֲרֵי סוֹד הַדָּבָר יָדַעְתִּי, אוֹתָם שֶׁבָּאוּ בְּגִלְגּוּל נְשָׁמוֹת - מֵאֵיזֶה מָקוֹם לָהֶם יֵשׁ זִוּוּג? שָׁלַח לוֹ, כָּתוּב (שופטים כא) מַה נַּעֲשֶׂה לָהֶם לַנּוֹתָרִים לְנָשִׁים וְגוֹ'. וְכָתוּב וַחֲטַפְתֶּם לָכֶם וְגוֹ'. פָּרָשַׁת בְּנֵי בִנְיָמִין מוֹכִיחָה, וְעַל זֶה שָׁנִינוּ שֶׁמָּא יְקַדְּמֶנּוּ אַחֵר בְּרַחֲמִים. (וכי אותו אחר אין לו בת זוגו? אבל תמצא זה כמו אדם שנשא בת זוגו ולא היו לו ממנה בנים ומת, יבא אחיו וייבם את אשתו ויולד לו ממנה בן, הבן הזה הוא המת שנשמתו חזרה לעולם, זה הוא האחר שאין לו בת זוג אלא אמו, וזה הוא שמא יקדמנו אחר ברחמים, שיכול להקדים אחר לשא את אשתו של זה ברחמים ובתפלה, ואף על גב שאמרתי לך שיכולים להקדים אחר ברחמים, לא יכול אלא אם (הוא) בעלה הוא רשע והוא צדיק)."]]],[["אָמַר רַבִּי יְהוּדָה (השתא) הַאי הוּא וַדַּאי דְּקָשִׁין זִוּוּגִין קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא. זַכָּאָה חוּלַקְהוֹן דְּיִשְׂרָאֵל דְּאוֹרַיְיתָא אוֹלִיף לְהוּ אָרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, וְכָל טְמִירִין וּגְנִיזָא דִּגְנִיזִין קַמֵּיהּ.","וַדַּאי כְּתִיב, (תהילים י״ט:ח׳) תּוֹרַת יְיָ תְּמִימָה וְגו'. זַכָּאָה חוּלָקֵיהּ מַאן דְּיִשְׁתָּדַל בְּאוֹרַיְיתָא וְלָא יִתְפְּרַשׁ מִינָהּ, דְּכָל מַאן דְּיִתְפְּרַשׁ מֵאוֹרַיְיתָא אֲפִלּוּ שַׁעֲתָא חָדָא כְּמָה דְּאִתְפְּרַשׁ מֵחַיֵּי דְּעָלְמָא דִּכְתִיב, (דברים ל׳:כ׳) כִּי הִיא חַיֶּיךָ וְאֹרֶךְ יָמֶיךָ. וּכְתִיב, (משלי ג׳:ב׳) אֹרֶךְ יָמִים וּשְׁנוֹת חַיִּים וְשָׁלוֹם יוֹסִיפוּ לָךְ:","וַיְהִי אַבְרָם בֶּן תִּשְׁעִים שָׁנָה וְגו'. רַבִּי יוֹסֵי פָּתַח (ישעיהו ס׳:כ״א) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ וְגו'. זַכָּאִין אִנּוּן יִשְׂרָאֵל מִכָּל שְׁאָר עַמִּין, דְּקוּדְשָׁא בְּרִיךְ הוּא קָרָא לוֹן צַדִּיקִים. דְּתַנְיָא מֵאָה וְעֶשְׂרִים (ד\"א ל\"ג וחמש) וּתְמַנְיָא אַלְפֵי מָארֵי דְגַדְּפִין דְּאָזְלִין וְטָאסִין כָּל עָלְמָא וְשָׁמְעִין קָלָא וְאַחֲדִין לֵיהּ לְהַהוּא קָלָא.","כְּמָה דְּתָנִינָן לֵית לָךְ מִלָּה בְּעָלְמָא דְּלֵית לָהּ קָלָא, וְאָזְלָא וְטָאסָא בָּרְקִיעָא, וְאַחֲדִין לָהּ מָארֵי דְגַדְפִין וְסָלְקִין הַהוּא קָלָא (ד\"א למאריהון) דְּאָמְרִין (נ\"א דמדין) וְדַיְינִין לָהּ הֵן לְטַב הֵן לְבִישׁ דִּכְתִיב, (קהלת י׳:כ׳) כִּי עוֹף הַשָּׁמַיִם יוֹלִיךְ אֶת הַקּוֹל וְגו'.","אֵימָתַי דָּיְינִין לְהַהוּא קָלָא. רַבִּי חִיָּיא אָמַר בְּשַׁעֲתָא דְּבַּר נָשׁ שָׁכִיב וְנָאִים, וְנִשְׁמְתֵיהּ נָפְקַת מִנֵּיהּ, וְהִיא אַסְהִידַת בֵּיהּ בְּבַּר נָשׁ, וּכְדֵין דָּיְינִין לְהַהוּא קָלָא הֲדָא הוּא דִכְתִיב, (מיכה ז׳:ה׳) מִשֹּׁכֶבֶת חֵיקֶךָ שְׁמֹר פִּתְחֵי פִיךָ. מַאי טַעְמָא, מִשּׁוּם דְּהִיא אַסְהִידַת בְּבַר נָשׁ. רַבִּי יְהוּדָה אָמַר כָּל מַה דְּבַּר נָשׁ עֲבִיד בְּכָל יוֹמָא נִשְׁמָתֵיהּ אַסְהִידַת בֵּיהּ בְּבַר נָשׁ בְּלֵילְיָא.","תָּאנָא אָמַר רַבִּי אֶלְעָזָר בִּתְחִלַת שַׁעֲתָא קַמַּיְיתָא בְּלֵילְיָא כַּד נָשַׁף יְמָמָא וְעָאל שִׁמְשָׁא מָארֵי דְּמַפְתְּחָן דִּמְמַנָּן עַל שִׁמְשָׁא עָאל בִּתְרֵיסַר תַּרְעִין דִּפְתִיחִין בִּימָמָא, בָּתַר דְּעָל בְּכֻלְהוּ, כָּל אִנּוּן תַּרְעִין סְתִימִין (נ\"א פתחין),","כָּרוֹזָא קָאִים וְשָׁרֵי לְאַכְרָזָא, קָאִים מָאן דְּקָאִים וְאָחִיד לְאִנּוּן מַפְתְּחָן, בָּתַר דְּסִיֵּים כָּרוֹזָא, כָּל אִנּוּן נְטוּרֵי עָלְמָא מִתְכַּנְשִׁין וְסָלְקִין, לֵית מָאן דְּפָתַח (פומא) פִּטְרָא כֹּלָּא מִשְׁתַּכְּכִין. כְּדֵין דִּינִין דִּלְתַתָּא מִתְעָרִין וְאָזְלִין וְשָׁאטִין בְּעָלְמָא, וְסִיהֲרָא שָׁארֵי לְאַנְהָרָא.","וּמָארֵי דִיבָבָא תָּקְעִין וּמְיַלְּלִין. תָּקְעִין תִּנְיָינוּת כְּדֵין מִתְעָרֵי שִׁירָתָא וּמְזַמְּרִין קַמֵּי מָארֵיהוֹן, כַּמָּה מָארֵי תְּרֵיסִין קָיְימוּ בְּקִיּוּמַיְיהוּ וְאִתְעָרִין דִּינִין בְּעָלְמָא, כְּדֵין בְּנֵי נָשָׁא נָיְימִין וְנִשְׁמָתָא נָפְקַת וְאַסְהִידַת סַהֲדוּתָא וְאִתְחַיְיבַת בְּדִינָא, וְקוּדְשָׁא בְּרִיךְ הוּא עָבִיד חֶסֶד בְּבַר נָשׁ וְנִשְׁמְתָא תָּבַת לְאַתְרָהּ.","בְּפַלְגוּת לֵילְיָא כַּד צִפֳּרִין מִתְעָרִין, סִטְרָא דְּצָפוֹן אִתְעַר בְּרוּחָא, קָם בְּקִיּוּמֵיהּ שַׁרְבִיטָא דְּבִסְטַר דָּרוֹם וּבָטַשׁ בְּהַהוּא רוּחָא וְשָׁכִיךְ וְאִתְבַּסָּם, כְּדֵין אִתְעַר קוּדְשָׁא בְּרִיךְ הוּא בְּנִימוּסוֹי לְאִשְׁתַּעְשְׁעָא עִם צַדִּיקַיָּא בְּגִנְתָא דְעֵדֶן.","בְּהַהוּא שַׁעֲתָא זַכָּאָה חוּלָקֵיהּ דְּבַּר נָשׁ דְּקָאִים לְאִשְׁתַּעֲשַׁע בְּאוֹרַיְיתָא, דְּהָא קוּדְשָׁא בְּרִיךְ הוּא וְכָל צַדִּיקַיָא דִּבְגִנְתָּא דְעֵדֶן כֻּלְהוּ צָיְיתִין לְקָלֵיהּ הֲדָא הוּא דִכְתִיב, (שיר השירים ח׳:י״ג) הַיּוֹשֶׁבֶת בַּגַּנִּים חֲבֵרִים מַקְשִׁיבִים לְקוֹלֵךְ הַשְׁמִיעִנִי.","וְלֹא עוֹד אֶלָּא דְּקוּדְשָׁא בְּרִיךְ הוּא מָשִׁיךְ עֲלֵיהּ חַד חוּטָא דְּחֶסֶ\"ד לְמֶהֱוֵי (ד\"א ל\"ג תדיר) נְטִיר בְּעָלְמָא, דְּהָא עִלָּאִין וְתַתָּאִין נָטְרִין לֵיהּ הֲדָא הוּא דִכְתִיב, (תהילים מ״ב:ט׳) יוֹמָם יְצַוֶּה יְיָ חַסְדּוֹ וּבַלַּיְלָה שִׁירֹה עִמִּי.","אָמַר רַבִּי חִזְקִיָּה כָּל מַאן דְּאִשְׁתַּדַּל בְּהַאי שַׁעֲתָא בְּאוֹרַיְיתָא וַדַּאי אִית לֵיהּ חוּלָקָא תָּדִיר בְּעָלְמָא דְּאָתֵי. אָמַר רַבִּי יוֹסֵי מַאי טַעְמָא תָּדִּיר. אָמַר לֵיהּ הָכִי אוֹלִיפְנָא דְּכָל פַּלְגוּת לֵילְיָא כַּד קוּדְשָׁא בְּרִיךְ הוּא אִתְעַר בְּגִנְתָא דְעֵדֶן כָּל אִנּוּן נְטִיעָן דְּגִינְתָא אִשְׁתַּקְיָין יַתִּיר מֵהַהוּא נַחֲלָא דְּאִקְרֵי נַחַל קְדוּמִים נַחַל עֲדָנִים דְּלָא פָּסְקוּ מֵימוֹי לְעָלְמִין, כִּבְיָכוֹל הַהוּא דְּקָאִים וְאִשְׁתְּדָּל בְּאוֹרַיְיתָא כְּאִילוּ הַהוּא נַחֲלָא אִתְרַק עַל רֵישֵׁיהּ וְאַשְׁקֵי לֵיהּ בְּגוֹ אִנּוּן נְטִיעָן דִּבְגִנְתָּא דְעֵדֶן."],[[0,"אמר ר\"י האי","וכו': אמר ר' יהודה, זה הוא ודאי, שקשים זווגים לפני הקב\"ה, כי צריך לקחת מזה ולתת לזה. אשרי חלקם של ישראל, שהתורה מלמדת אותם דרכיו של הקב\"ה, וכל הנסתרות והגנוזות הצפונות לפניו."],[1,"ודאי כתיב","תורת ה' תמימה, וגו', משום שהכל בה. אשרי חלקו מי שעוסק בתורה ואינו נפרד ממנה, כי כל מי שנפרד מתורה אפילו שעה אחת, הוא כמו שנפרד מחיי העולם, וכתוב, כי הוא חייך ואורך ימיך וכתיב אורך ימים וגו'."],[2,"ויהי אברם וגו':","ר' יוסי פתח ועמך כלם צדיקים וגו'. אשריהם ישראל מכל העמים, שהקב\"ה קראם צדיקים. שלמדנו, מאה ועשרים וחמש אלפי מארי דגדפין, הולכים ומשוטטים כל העולם, ושומעים קול ומקבלים את הקול."],[3,"כמה דתנינן וכו':","כמו שלמדנו, אין לך דבר בעולם שאין לו קול, והוא הולך ומשוטט ברקיע, ותופשים בו בעלי הכנפים ומעלים אותו הקול, למ\"ן לזו\"ן, ודנים אותו הן לטוב והן לרע. שכתוב כי עוף השמים יוליך את הקול וגו'."],[3,"","פירוש. כי הצדיקים מעלים מ\"ן, שה\"ס מסך דחירק, לקו אמצעי המיחד לקב\"ה ושכינתיה. (כנ\"ל דף ג' ד\"ה וז\"ש בשעתא, עש\"ה) והוא על ידי מעשים הטובים שהצדיקים עושים ביום. כמ\"ש בזהר (בשלח דף צ\"ב אות ש\"כ) \u0003בשעתא דעובדין מתכשרן לתתא, ובר נש אשתדל בפולחנא דמלכא קדישא, וכו', הבל אתעביד ממנו לעילא, ולית לך הבל דלית ליה קלא וכו' ואתעביד סניגורא קמי קב\"ה.\u0004 בשעה שהמעשים למטה ישרים, והאדם משתדל בעבודת המלך הקדוש, נעשה מהם הבל, העולה למעלה בסוד מ\"ן, ואין לך הבל שאין לו קול. כלומר שנעשה לבחינת קו אמצעי הנק' קול, (כנ\"ל פרשת נח דף כ\"ג ד\"ה תוספתא) ונעשה סניגור לפני הקב\"ה וכו'. כלומר, שמיחד קב\"ה ושכינתיה, \u0003כל מלין דמתעבדין דלאו אינון פולחנא דקב\"ה, הבל יתעביד מנייהו איהו תבירא דרוחא\u0004 וכו'. וכל המעשים שאינם עבודת הקב\"ה, נעשה מהם הבל, שהוא שבירת הרוח. \u0003הה\"ד הבל ורעות רוח.\u0004 עש\"ה כל ההמשך."],[3,"","הרי שמכל מעשה עולה הבל, וההבל נעשה קול, ואם טוב הוא עולה למ\"ן ליחוד ז\"א ונוקביה. והמלאכים המשמשים ליחוד זו\"ן, לקבל המ\"ן מהצדיקים ולהוריד להם מקומת הזווג, נקראים עוף, או בעלי כנפים. מכונים \u0003עוף,\u0004 משום שאין להם אלא קומת ו\"ק שה\"ס אור הרוח המכונה אויר דהיינו הרמז, שפורחים באויר כמו עוף השמים, וזהו בשעה שמקבלים המ\"ן הנק' קול. וזסו\"ה, \u0003כי עוף השמים יוליך את הקול,\u0004 ואחר הזווג שמשפיעים קומת הזווג, המכונה \u0003דיבור,\u0004 אל הצדיקים שאז יש להם ג\"ר, אלא שממעטים בכנפיהם את הג\"ר דחכמה שבקומת הזווג, שלא ימשכו ממעלה למטה. נקראים \u0003בעלי כנפים.\u0004 וזסו\"ה \u0003ובעל כנפים יגיד דבר. יגיד,\u0004 הוא לשון המשכה והשפעה, \u0003דבר,\u0004 הוא קומת הזווג המכונה דיבור."],[3,"","והמספר קכ\"ה אלף בעלי כנפים, שאומר, היינו על שם קומת הזווג שהם ממשיכים בכח המ\"ן שמעלים, כי הזווג נמשך מג' הקוין, ובב' הקוין ימין ושמאל יש נרנח\"י שלמים המלובשים בה' ספירות כח\"ב תו\"מ. אבל קו אמצעי שלהם אינו אלא נפש רוח המלובש בב' ספירות כתר חכמה. ולפי שהם מבחינת ז\"א שכל ספירה שלו בסוד עשר, ע\"כ יש להם נ' ספירות מקו ימין ונ' ספירות מקו שמאל. דהיינו כח\"ב תו\"מ שכל אחת מהן כלולה מעשר. ויש להם עשרים מב' הספירות כו\"ח שבקו אמצעי. הרי מאה ועשרים. ומבחינת המלכות הדבוקה בקו אמצעי. אין להם אלא חצי המלכות. דהיינו מבחינת מחזה ולמעלה, וחסרים את חצי המלכות שמחזה ולמטה, וע\"כ אין להם ממנה אלא חמש ספירות ולא עשר. ועם הק\"כ מג' הקוין יש להם מאה ועשרים וחמש ספירות. ונתבאר לעיל שעיקר השם בעלי כנפים הוא על שם שמתקנים את אור החכמה. ומכסים בכנפיהם על הג\"ר. ולפי שהם משמשים על החכמה. שספירותיה בסוד אלפים. ע\"כ נבחנים למספר מאה ועשרים וחמשה אלף."],[4,"אימתי דיינין וכו':","מתי דנים את קול הזה. כלומר, מתי עולה הקול, למ\"ן לזו\"ן. ר' חייא אומר בשעה שאדם שוכב וישן, והנשמה יוצאת ממנו, והיא מעידה על האדם, אז דנים את הקול. דהיינו, שעולה למ\"ן, אם הנשמה מעידה לטובה. וז\"ש, משוכבת חיקך שמור פתחי פיך. מה הטעם משום שהיא מעידה על האדם. משוכבת חיקך, פירושו הנשמה. ר' יהודה אומר, כל מה שאדם עושה בכל היום, הנשמה מעידה עליו בלילה."],[5,"תאנא א\"ר אלעזר וכו':","למדנו אר\"א, בתחילת שעה ראשונה, שבלילה, כשנושף היום, והשמש באה, בעל המפתחות, שהוא מטטרון שר העולם, הממונה על השמש, להמשיך אורה לעולם, נכנס בי\"ב שערים של השמש הפתוחים ביום, שה\"ס י\"ב שעות היום, אחר שכבר נכנס בכולם דהיינו בסיום שעה הי\"ב, אז כל אלו השערים נסתמים. דהיינו שנגמר ממשלת היום, והגיע הזמן של ממשלת הלילה."],[6,"כרוזא קאים וכו':","ואז כרוז עומד ומתחיל להכריז. כי כל שינוי נעשה עם כרוז, קם מי שקם, היינו המלאך גבריאל שהוא המכריז, ותופס באלו המפתחות, שהם הכחות הנמשכות ממלכות הממותקת, המכונה מפתחא, כנ\"ל (בהקדמת הזהר דף נ\"ו אות מ\"ב ע\"ש) שביום הם ברשותו של מטטרון כנ\"ל, שבכח המפתחות הוא ממשיך החשך, שה\"ס הכרוז. ואחר שמר את הכרוז, כל אלו שומרי העולם מתאספים ועולים מהעולם, ואין מי שיפתח פתיחה, שימשיך הארה מועטת, כי כולם משתתקים. אז מתעוררים הדינים של מטה, של המלכות הבלתי ממותקת, והולכים ומשוטטים בעולם. והלבנה מתחלת להאיר."],[7,"ומארי דיבבא וכו':","ובעלי היבבא, שהם כחות הדין המעוררים יבבא ויללה בעולם, תוקעים, ומיללים, דהיינו תרועה, ותוקעים שנית. אז מתעוררת השירה, והמלאכים מזמרים לפני רבונם. פירוש. יש י\"ב שעות ביום, וכן י\"ב בלילה. (וסוד י\"ב כבר נתבאר לעיל דף ח' ד\"ה וזה) שה\"ס חו\"ב תו\"מ שאין בכל אחד מהם חו\"ב תו\"מ, אלא חו\"ב ות\"ת בלבד, כי המלכות חסרה בכל אחד מהם, שמצד אחד יש מלכות, שהרי יש ד' פנים חו\"ב תו\"מ, והיא מלכות הממותקת בבינה. ומצד אחד חסר המלכות, שאין בכל אחד מהם ד' אלא ג', וה\"ס מלכות מבחינת עצמה שנגנזה."],[7,"","ונתבאר (לעיל ב\"א דף ז' ד\"ה כבר) שלולא התיקון הזה לא היו זו\"ן ראוים לקבל אורות עליונים. ולפיכך יש תיקון י\"ב שעות ביום ותיקון י\"ב שעות בלילה. אלא שביום הן מתוקנות ע\"י כחות החסד. ובלילה הן מתוקנות ע\"י כחות הדין, הנקראים מארי דיבבא. וז\"ש \u0003ומארי דיבבא תקעין ומיללין תקעין תניינות,\u0004 דהיינו שממשיכים ג' קוין, כי תקיעה ראשונה ה\"ס קו ימין, ויללה, ה\"ס שברים תרועה, דהיינו קו שמאל, ותקיעה שניה, ה\"ס קו אמצעי, ובזה נתקנת הלילה בסוד י\"ב שעות, כי בכל קו יש חו\"ב תו\"מ, והם י\"ב. וכיון שהלילה נתקנה בזה, \u0003כדין מתערי שירתא ומזמרין קמי מאריהון,\u0004 כלומר הגיע הזמן לומר שירה שז\"ס ג' משמורות הוי הלילה, שבהם המלאכים אומרים שירה. (כנ\"ל ב\"א דף שט\"ו אות תי\"א.) \u0003כמה מארי תריסין וכו':\u0004 כמה בעלי מגינים עומדים בקיומם להגן על הדינים, ומתערים דינים בעולם, ואז בני אדם ישנים, והנשמה יוצאת מהגוף ומעידת עדות, ומתחייבת בדין, כי אין צדיק בארץ אשר לא יחטא. והקב\"ה עושה חסד עם האדם, והנשמה חוזרת בבוקר למקומה."],[8,"בפלגות ליליא וכו':","בחצות הלילה כשהצפורים נעורים, דהיינו התרנגולים, נתעורר צד צפון ברוח, דהיינו קו שמאל בבחינת הארת השורק, שה\"ס הארת חכמה בחוסר חסדים שה\"ס ג\"ר דרוח. קם בקיומו השרביט של צד דרום דהיינו קו הימין שה\"ס חסדים, ונזדווג באותו הרוח דקו שמאל, ונכללו זה בזה, ואז שככו דיניו של קו שמאל, ונמתק בחסדים. אז נתעורר הקב\"ה במנהגו להשתעשע עם הצדיקים בגן עדן. (וביאור הדברים עי' לעיל דף נ\"ג ד\"ה פירוש."],[9,"בההוא שעתא וכו':","בשעה ההיא, אשרי חלקו של האדם הקם להשתעשע בתורה, כי הקב\"ה וכל הצדיקים שבגן עדן מקשיבים לקולו. זהו שכתוב, היושבת בגנים חברים מקשיבים לקולך השמיעני."],[10,"ולא עוד וכו':","ולא עוד, אלא הקב\"ה מושך עליו חוט של חסד, שיהיה נשמר בעולם, כדי שהעליונים והתחתונים ישמרו אותו. זהו שכתוב, יומם יצוה ה' חסדו ובלילה שירה עמי."],[11,"א\"ר חזקיה","וכו': אר\"ח, כל מי שעוסק באותה שעה בתורה, ודאי שיש לו חלק תמידי בעולם הבא. אמר ר' יוסי, מהו הטעם של תמידי. הוקשה לו, כי המוחין הללו נמשכים מישסו\"ת שזווגם פסיק ואינו תמידי. אמר לו כך למדתי, שבכל חצות לילה כאשר הקב\"ה נתעורר בגן עדן, כל אלו הנטיעות, דהיינו הספירות, שבגן עדן, שהיא הנוקבא, יושקו ביותר מאותו הנחל, הנקרא נחל קדומים נחל עדנים, שהוא או\"א עלאין, שמימיו אינם נפסקים לעולם שזווג או\"א לא נפסק לעלמין, וכביכול, מי שקם ועוסק בתורה, נחל ההוא כאלו הורק על ראשו ומשקה אותו בתוך הנטיעות שבגן עדן. וע\"כ יש לו חלק תמידי גם במוחין דעלמא דאתי, שהוא ישסו\"ת, כי המוחין דאו\"א כלולים בתוכם גם המוחין דישסו\"ת."]],[[0,"","אָמַר רַבִּי יְהוּדָה, (כעת) זֶה הוּא וַדַּאי שֶׁקָּשִׁים הַזִּוּוּגִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁהַתּוֹרָה מְלַמֶּדֶת אוֹתָם אֶת דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכָל הַנִּסְתָּרוֹת וְהַגְּנָזִים שֶׁגְּנוּזִים לְפָנָיו."],[1,"","וַדַּאי כָּתוּב (תהלים יט) תּוֹרַת ה' תְּמִימָה וְגוֹ'. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה וְלֹא נִפְרָד מִמֶּנָּה, שֶׁכָּל מִי שֶׁנִּפְרָד מִן הַתּוֹרָה אֲפִלּוּ שָׁעָה אַחַת, כְּמִי שֶׁנִּפְרָד מֵחַיֵּי הָעוֹלָם, שֶׁכָּתוּב (דברים ל) כִּי הִיא חַיֶּיךְ וְאֹרֶךְ יָמֶיךְ, וְכָתוּב (משלי ג) אֹרֶךְ יָמִים וּשְׁנוֹת חַיִּים וְשָׁלוֹם יוֹסִיפוּ לָךְ."],[2,"","וַיְהִי אַבְרָם בֶּן תִּשְׁעִים שָׁנָה וְגוֹ'. רַבִּי יוֹסֵי פָּתַח, (ישעיה ס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ וְגוֹ'. אַשְׁרֵיהֶם יִשְׂרָאֵל מִכָּל שְׁאָר הָעַמִּים, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא קָרָא לָהֶם צַדִּיקִים. שֶׁלָּמַדְנוּ, מֵאָה וְעֶשְׂרִים (וחמש) וּשְׁמוֹנָה אֲלָפִים בַּעֲלֵי כְנָפַיִם שֶׁהוֹלְכִים וְטָסִים אֶת כָּל הָעוֹלָם, וְשׁוֹמְעִים קוֹל וְאוֹחֲזִים אֶת אוֹתוֹ הַקּוֹל."],[3,"","כְּמוֹ שֶׁשָּׁנִינוּ שֶׁאֵין לְךְ דָּבָר בָּעוֹלָם שֶׁאֵין לוֹ קוֹל וְהוֹלֵךְ וְטָס בָּרָקִיעַ. וְאוֹחֲזִים בּוֹ בַּעֲלֵי כְנָפַיִם, וּמַעֲלִים אֶת אוֹתוֹ הַקּוֹל (לרבונם) שֶׁאוֹמְרִים (בעלי הדין) וְדָנִים אוֹתוֹ הֵן לְטוֹב הֵן לְרַע, שֶׁכָּתוּב (קהלת י) כִּי עוֹף הַשָּׁמַיִם יֹלִיךְ אֶת הַקּוֹל וְגוֹ'."],[4,"","מָתַי דָּנִים אֶת אוֹתוֹ הַקּוֹל? רַבִּי חִיָּיא אָמַר, בְּשָׁעָה שֶׁבֶּן אָדָם שׁוֹכֵב וְיָשֵׁן וְנִשְׁמָתוֹ יָצְאָה מִמֶּנּוּ, וְהִיא מְעִידָה בְּבֶן הָאָדָם, וְאָז דָּנִים אֶת אוֹתוֹ הַקּוֹל. זֶהוּ שֶׁכָּתוּב (מיכה ז) מִשֹּׁכֶבֶת חֵיקֶךְ שְׁמֹר פִּתְחֵי פִיךְ. מָה הַטַּעַם? מִשּׁוּם שֶׁהִיא מְעִידָה בָּאָדָם. רַבִּי יְהוּדָה אוֹמֵר, כָּל מַה שֶּׁאָדָם עוֹשֶׂה בְּכָל יוֹם, נִשְׁמָתוֹ מְעִידָה בּוֹ בָּאָדָם בַּלַּיְלָה."],[5,"","לָמַדְנוּ, אָמַר רַבִּי אֶלְעָזָר, בִּתְחִלַּת הַשָּׁעָה הָרִאשׁוֹנָה בַּלַּיְלָה, כְּשֶׁנּוֹשֵׁף (שיוצא) הַיּוֹם וְנִכְנָס הַשֶּׁמֶשׁ, בַּעַל הַמַּפְתְּחוֹת שֶׁמְּמֻנֶּה עַל הַשֶּׁמֶשׁ נִכְנָס בִּתְרֵיסַר שְׁעָרִים שֶׁפְּתוּחִים בַּיּוֹם. אַחַר שֶׁנִּכְנַס בְּכֻלָּם, כָּל אוֹתָם הַשְּׁעָרִים הַסְּתוּמִים (הפתוחים),"],[6,"","הַכָּרוֹז עוֹמֵד וּמַתְחִיל לְהַכְרִיז. עוֹמֵד מִי שֶׁעוֹמֵד וְאוֹחֵז אֶת אוֹתָם הַמַּפְתְּחוֹת. אַחַר שֶׁסִּיֵּם הַכָּרוֹז, כָּל אוֹתָם שׁוֹמְרֵי הָעוֹלָם מִתְכַּנְּסִים וְעוֹלִים, וְאֵין מִי שֶׁפּוֹתֵחַ (פה) פִּתְחוֹן פֶּה וְהַכֹּל שׁוֹקְטִים. אָז מִתְעוֹרְרִים הַדִּינִים שֶׁלְּמַטָּה, וְהוֹלְכִים וּמְשׁוֹטְטִים בָּעוֹלָם, וְהַלְּבָנָה מַתְחִילָה לְהָאִיר."],[7,"","וּבַעָלֵי הַיְבָבָה תּוֹקְעִים וּמְיַלְּלִים. תּוֹקְעִים שֵׁנִית. אָז מִתְעוֹרֶרֶת שִׁירָה וּמְזַמְּרִים לִפְנֵי רִבּוֹנָם. כַּמָּה בַּעֲלֵי מָגִנִּים עוֹמְדִים בִּמְקוֹמָם וּמְעוֹרְרִים דִּינִים בָּעוֹלָם. אָז בְּנֵי הָאָדָם יְשֵׁנִים, וְהַנְּשָׁמָה יוֹצֵאת וּמְעִידָה עֵדוּת וּמִתְחַיֶּבֶת בַּדִּין. וְהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה חֶסֶד עִם אָדָם, וְהַנְּשָׁמָה שָׁבָה לִמְקוֹמָהּ."],[8,"","בַּחֲצוֹת הַלַּיְלָה, כְּשֶׁהַצִּפֳּרִים מִתְעוֹרְרוֹת, צַד הַצָּפוֹן מִתְעוֹרֵר בָּרוּחַ, עוֹמֵד בִּמְקוֹמוֹ הַשַּׁרְבִיט שֶׁבְּצַד הַדָּרוֹם, וּמַכֶּה בְּאוֹתָהּ הָרוּחַ וְשׁוֹקֵט וּמִתְבַּסֵּם. אָז מִתְעוֹרֵר הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמִנְהָגָיו לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים בְּגַן עֵדֶן."],[9,"","בְּאוֹתָהּ שָׁעָה. אַשְׁרֵי חֶלְקוֹ שֶׁל אָדָם שֶׁעוֹמֵד לְהִשְׁתַּעֲשֵׁעַ בַּתּוֹרָה, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְכָל הַצַּדִּיקִים שֶׁבְּגַן עֵדֶן, כֻּלָּם מַקְשִׁיבִים לְקוֹלוֹ. זֶהוּ שֶׁכָּתוּב (שיר ח) הַיּוֹשֶׁבֶת בַּגַּנִּים חֲבֵרִים מַקְשִׁיבִים לְקוֹלֵךְ הַשְׁמִיעִנִי."],[10,"","וְלֹא עוֹד, אֶלָּא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מוֹשֵׁךְ עָלָיו חוּט אֶחָד שֶׁל חֶסֶ\"ד שֶׁיִּהְיֶה (תמיד) שָׁמוּר בָּעוֹלָם, שֶׁהֲרֵי עֶלְיוֹנִים וְתַחְתּוֹנִים שׁוֹמְרִים אוֹתוֹ. זֶהוּ שֶׁכָּתוּב (תהלים מב) יוֹמָם יְצַוֶּה ה' חַסְדּוֹ וּבַלַּיְלָה שִׁירֹה עִמִּי."],[11,"","אָמַר רַבִּי חִזְקִיָּה, כָּל מִי שֶׁמִּשְׁתַּדֵּל בַּשָּׁעָה הַזּוֹ בַּתּוֹרָה, וַדַּאי יֵשׁ לוֹ חֵלֶק תָּמִיד בָּעוֹלָם הַבָּא. אָמַר רַבִּי יוֹסֵי, מָה הַטַּעַם תָּמִיד? אָמַר לוֹ, כָּךְ לָמַדְנוּ, שֶׁכָּל חֲצוֹת לַיְלָה, כְּשֶׁמִּתְעוֹרֵר הַקָּדוֹשׁ בָּרוּךְ הוּא בְּגַן עֵדֶן, כָּל הַנְּטִיעוֹת שֶׁל הַגָּן מֻשְׁקִים יוֹתֵר מֵאוֹתוֹ הַנַּחַל שֶׁנִּקְרָא נַחַל קְדוּמִים, נַחַל עֲדָנִים, שֶׁאֵין פּוֹסְקִים מֵימָיו לְעוֹלָמִים. כִּבְיָכוֹל אוֹתוֹ שֶׁעוֹמֵד וּמִשְׁתַּדֵּל בַּתּוֹרָה, כְּאִלּוּ אוֹתוֹ הַנַּחַל מוֹרִיק עַל רֹאשׁוֹ וּמַשְׁקֶה אוֹתוֹ בְּתוֹךְ אוֹתָם הַנְּטִיעוֹת שֶׁבְּגַן עֵדֶן."]]],[["(אמר רבי יוסי) וְלֹא עוֹד אֶלָּא הוֹאִיל וְכֻלְהוּ צַדִּיקַיָּיא דִּבְגוֹ גִנְתָא דְעֵדֶן צַיְיתִין לֵיהּ, חוּלְקָא שַׁוְיָין לֵיהּ בְּהַהוּא שַׁקְיוּ דְּנַחֲלָא. אִשְׁתְּכַח דְּאִית לֵיהּ חוּלָקָא תָּדִיר בְּעָלְמָא דְאָתֵי.","רַבִּי אַבָּא הֲוָה אָתֵי מִטְבֶרְיָה לְבֵי טְרוֹנְיָא דְּחָמוּי, וְרַבִּי יַעֲקֹב בְּרֵיהּ הֲוָה עִמֵּיהּ, אִעָרְעוּ בִּכְפַר טַרְשָׁא. כַּד בָּעוּ לְמִשְׁכַּב, אָמַר רַבִּי אַבָּא לְמָרֵיהּ דְּבֵיתָא אִית הָכָא תַּרְנְגוֹלָא. אָמַר לֵיהּ מָארָא דְבֵיתָא, אַמַּאי. אָמַר לֵיהּ בְּגִין דְּקָאִימְנָא בְּפַלְגוּת לֵילְיָא מַמָּשׁ.","אָמַר לֵיהּ לָא אִצְטְרִיךְ, דְּהָא סִימָנָא לִי בְּבֵיתָא דְּהָדֵין טִקְלָא דְּקַמֵּי עַרְסָאי מָלִינָא לֵיהּ מַיָא וְנָטִיף טִיף טִיף, בְּפַלְגוּת לֵילְיָא מַמָּשׁ אִתְרָקוּ כֻּלְהוּ מַיָא, וְאִתְגַּלְגָּל הָאי קִיטְפָא וְנָהִים, וְאִשְׁתְּמַע קָלֵיהּ בְּכָל בֵּיתָא, וּכְדֵין הוּא פַלְגּוּת לֵילְיָא מַמָּשׁ, וְחָד סָבָא הֲוָה לִי דַּהֲוָה קָם בְּכָל פַּלְגּוּת לֵילְיָא וְאִשְׁתַּדַּל בְּאוֹרַיְיתָא, וּבְגִינֵי כָּךְ עָבַד הָאי,","אָמַר רִבִּי אַבָּא בְּרִיךְ רַחֲמָנָא דְשָׁדַרְנִי הָכָא, בְּפַלְגּוּת לֵילְיָא נָהִים הַהוּא גַּלְגָּלָא דְקִיטְפָא, קָמוּ רִבִּי אַבָּא וְרִבִּי יַעֲקֹב. שָׁמְעוּ לְהַהוּא גַבְרָא דַּהֲוָה יָתִיב בְשִׁפּוּלֵי בֵיתָא וּתְרִין בְּנוֹי עִמֵּיהּ, וַהֲוָה אָמַר כְּתִיב (תהלים קיט סב) חֲצוֹת לַיְלָה אָקוּם לְהוֹדוֹת לְךָ עַל מִשְׁפְּטֵי צִדְקֶךָ, מַאי קָא חָמָא דָוִד דְּאִיהוּ אָמַר חֲצוֹת לַיְלָה וְלָא בַּחֲצוֹת לַיְלָה. אֶלָּא חֲצוֹת לַיְלָה וַדַּאי, לְקוּדְשָׁא בְּרִיךְ הוּא אָמַר הָכִי.","וְכִי קוּדְשָׁא בְּרִיךְ הוּא הָכִי אִקְרֵי. אִין, דְּהָא חֲצוֹת לַיְלָה מַמָּשׁ קוּדְשָׁא בְּרִיךְ הוּא אִשְׁתְּכַח וְסִיעָתָא דִילֵיהּ וּכְדֵין הִיא שַׁעֲתָא דְּעָיִיל בְּגִנְתָא דְעֵדֶן לְאִשְׁתַּעְשְׁעָא עִם צַדִיקַיָא.","אָמַר רַבִּי אַבָּא לְרַבִּי יַעֲקֹב וַדַּאי נִשְׁתַּתֵּף בִּשְׁכִינְתָּא וְנִתְחַבַּר כְּחֲדָא, קָרִיבוּ וְיָתִיבוּ עִמֵּיהּ, אָמְרוּ לֵיהּ אֵימָא מִלָּה דְפוּמָךְ דְּשַׁפִּיר קָאֲמַרְתְּ. מְנָא לָךְ הַאי. אָמַר לוֹן מִלָּה דָא אוֹלִיפְנָא מִסָּבָאי.","וְתוּ הֲוָה אָמַר דִּתְלַת (נ\"א דתחלת) שַׁעֲתֵי קָמַיְיתָא דְּלֵילְיָא כָּל דִּינִין דִּלְתַתָּא מִתְעָרִין וְאָזְלִין וְשָׁאטִין בְּעָלְמָא. בְּפַלְגוּת לֵילְיָא מַמָּשׁ קוּדְשָׁא בְּרִיךְ הוּא אִתְעַר בְּגִנְתָא דְעֵדֶן וְדִינִין דִּלְתַתָּא לָא מִשְׁתַּכְּחָן.","וְכָל נִימוּסִין דִּלְעֵילָא בְּלֵילְיָא לָא אִשְׁתְּכָחוּ אֶלָּא בְּפַלְגוּת לֵילְיָא מַמָּשׁ. מְנָלָן מֵאַבְרָהָם דִּכְתִיב וַיֵּחָלֵק עֲלֵיהֶם לַיְלָה. בְּמִצְרַיִם (שמות י״ב:כ״ט) וַיְהִי בַּחֲצִי הַלַּיְלָה, וּבְאַתְרִין סַגִּיאִין בְּאוֹרַיְיתָא הָכִי אִשְׁתְּכַח. וְדָוִד הֲוָה יָדַע.","(ומה) וּמְנָא הֲוָה יָדַע. אֶלָּא הָכִי אָמַר סָבָא. דְּמַלְכוּתָא דִילֵיהּ בְּהַאי (ליליא) תַּלְיָא. וְעַל דָּא קָאִים בְּהַהִיא שַׁעֲתָא וְאָמַר שִׁירָתָא, וּלְהָכִי קַרְיֵיה לְקוּדְשָׁא בְּרִיךְ הוּא חֲצוֹת לַיְלָה מַמָּשׁ, אָקוּם לְהוֹדוֹת לְךָ וְגו' דְּהָא כָּל דִּינִין תַּלְיָין מֵהָכָא, וְדִינִין דְּמַלְכוּתָא מֵהָכָא מִשְׁתַּכְּחִין, וְהַהִיא שַׁעֲתָא אִתְקְטִיר בָּהּ דָּוִד וְקָם וְאָמַר שִׁירָתָא. אֲתָא רַבִּי אַבָּא וּנְשָׁקֵיהּ, אָמַר לֵיהּ וַדַּאי הָכִי הוּא בְּרִיךְ רַחֲמָנָא דְּשַׁדְּרַנִי הָכָא.","תָּא חֲזֵי, לַיְלָה דִינָא בְּכָל אֲתַר וְהָא אוֹקִימְנָא מִילֵּי, וְהָכִי הוּא וַדַּאי, וְהָא אִתְעַר קַמֵי דְרַבִּי שִׁמְעוֹן. אָמַר הַהוּא יְנוּקָא בְּרֵיהּ דְּהַהוּא גַבְרָא אִי הָכִי אַמַּאי כְּתִיב חֲצוֹת לַיְלָה. אָמַר לֵיהּ הָא אִתְּמָר בְּפַלְגוּת לֵילְיָא מַלְכוּתָא דִּשְׁמַיָא אִתְעָרַת. אָמַר אֲנָא שְׁמַעְנָא מִלָּה. אָמַר לֵיהּ רַבִּי אַבָּא, אֵימָא בְּרִי טַב דְּהָא מִלָּה דְּפוּמָךְ קָלָא דְבוּצִינָא לֶהוֵי.","אָמַר אֲנָא שְׁמַעְנָא דְּהָא לַיְלָה דִינָא דְמַלְכוּתָא אִיהוּ וּבְכָל אֲתַר דִּינָא הוּא, וְהַאי דְּקָאֲמַר חֲצוֹת, בְּגִין דְּיַנְקָא בִּתְרֵי גַוְונִי (חצות) בְּדִינָא וְחֶסֶד, וַדַּאי פַּלְגוּתָא קַדְמִיתָא דִּינָא הוּא, דְּהָא פַּלְגוּתָא אָחֳרָא נְהִירוּ אַנְפָּהָא בְּסִטְרָא דְּחֶסֶד. וְעַל דָּא חֲצוֹת לַיְלָה כְּתִיב וַדַּאי.","קָם רַבִּי אַבָּא וְשַׁוֵּי יְדוֹי בְּרֵישֵׁיהּ וּבָרְכֵיהּ, אָמַר וַדַּאי חֲשִׁיבְנָא דְּחָכְמְתָא לָא אִשְׁתְּכַח בַּר בְּאִנּוּן זַכָּאֵי דְּזָכוּ בָּה. הַשְׁתָּא חָמֵינָא דְּאֲפִילּוּ יְנוּקֵי בְּדָרָא דְרַבִּי שִׁמְעוֹן זָכוּ לְחָכְמְתָא עִלָאָה. זַכָּאָה אַנְתְּ רַבִּי שִׁמְעוֹן. וַוי לְדָרָא דְּאַנְתְּ תִּסְתַּלַּק מִנֵּיהּ. יָתְבוּ עַד צַפְרָא וְאִשְׁתַּדְּלוּ בְּאוֹרַיְיתָא."],[[0,"ולא עוד וכו':","ולא עוד אלא הואיל וכל הצדיקים שבתוך גן העדן מקשיבים לו, משימים לו חלק באותו שיקוי הנחל, שהם המוחין דאו\"א עילאין, ונמצא שיש לו חלק תמידי לעולם הבא, שהם כלולים במוחין דאו\"א, כנ\"ל."],[1,"ר' אבא הוה אתי וכו':","ר\"א היה הולך מטבריה לבי טרוניא ששם דר חמיו, ור' יעקב בנו היה עמו, פגעו בכפר טרשא. כשרצו לשכב, אמר ר' אבא לבעל הבית יש כאן תרנגול, אמר לו בעל הבית למה לך תרנגול. אמר לו משום שאני קם בחצות לילה ממש. ואני צריך לתרנגול שיעיר אותי."],[2,"א\"ל לא אצטריך וכו':","אמר לו בעל הבית אינך צריך לתרנגול. כי יש לי סימן ערוך בבית. כי משקל זה שלפני מטתי, אני ממלא כלי מים, ונותן אותו על כף אחת מהמשקל, ודרך חור שבכלי, נוטפים המים טפה אחר טפה, עד שבחצות לילה ממש כבר התרוקנו כל המים, ועולה הכף למעלה וכף השניה שבמשקל נשמטת ומתגלגלת למטה, ונוהם, שעושה רעש בנפילתו, והקול נשמע בכל הבית ואז הוא חצות לילה ממש. וזקן אחד היה עמי, שהיה קם בכל לילה ועסק בתורה, ובשביל זה עשה את סימן הזה."],[3,"אמר ר' אבא בריך וכו'","אר\"א, ברוך השם הרחמן ששלח אותי לכאן. בחצות לילה, נהם אותו גלגל של המשקל בנפילתו, וקמו ר' אבא ורבי יעקב. שמעו אותו האיש, שהיה יושב בירכתי הבית ושני בניו עמו, והיה אומר, כתוב חצות לילה אקום וכו' ושואל מה ראה דוד שאמר חצות לילה וגו' ולא אמר בחצות לילה. ומשיב, אלא חצות לילה, ודאי להקב\"ה אמר כן שקרא אותו חצות לילה."],[4,"וכי קב\"ה וכו':","ושואל וכי הקב\"ה נקרא כן. ואומר, כן. כי חצות לילה ממש, נמצא הקב\"ה ופמליא שלו, ואז הוא הזמן שנכנס בגן עדן להשתעשע עם הצדיקים. פירוש כל שם יורה השגה, שאנו משיגים אותו ית' דרך השם ההוא. וכיון שדרכו של הקב\"ה להתגלות בגן עדן בחצות לילה, ע\"כ מכנהו דוד בשם חצות לילה."],[5,"אמר ר' אבא וכו':","אר\"א לר' יעקב. ודאי נשתתף בהשכינה, ונתחבר יחד עם אותו האיש ובניו. קרבו אליו וישבו עמו. אמרו לו, אמור אמרי פיך, כי יפה אמרת, שאלוהו, מאין לך זה. אמר להם דבר זה שמעתי מזקני."],[6,"ותו הוה אמר וכו':","ועוד היה אומר, שבתחילת שעה ראשונה של הלילה כל הדינין של מטה מתעוררים, דהיינו הדינין של המלכות הבלתי ממותקת בבינה, והולכים ומשוטטים בעולם. בחצות לילה ממש, הקב\"ה נתעורר ובא לגן עדן, שהיא הנוקבא, והדינים שלמטה הנ\"ל, נעלמים ואינם נמצאים."],[7,"וכל נימוסין וכו':","וכל הדרכים של מעלה דהיינו דרכי הבינה הממתקת את הנוקבא, אינם נמצאים בלילה רק בחצות לילה ממש. מאין לנו זה. מאברהם, שכתוב ויחלק עליהם לילה. במצרים כתוב, ויהי בחצי הלילה. כי אז נמתקה הנוקבא בהבינה ונתגלו אורותיה. ודוד היה יודע זה וע\"כ אמר חצות לילה וגו'."],[8,"ומנא הוה ידע וכו':","ושואל, מאין היה יודע דוד את זה. ואומר, אלא כך אמר זקני. כי מלכותו של דוד היתה תלויה בזה דהיינו בהארת המוחין של חצות לילה. וע\"כ קם בשעה ההיא ואמר שירה. ועל כן קרא את הקב\"ה, חצות לילה ממש אקום להודות לך וגו'. כי אז כל הדינים תלוים מכאן, דהיינו רק מנוקבא הממותקת שבחצות לילה, כי הדינים של מטה כבר נעלמו כנ\"ל בסמוך. ודינים של המלכות רק מכאן נמצאים, ולא מבחינת עצמה הבלתי ממותקת, וע\"כ בשעה ההיא נתקשר בה דוד, וקם ואמר שירה. בא ונשק אותו. אמר לו ודאי כך הוא. ברוך הרחמן ששלח אותי לכאן."],[9,"ת\"ח לילה וכו':","בוא וראה, לילה היא דין בכל מקום. וכבר בארנו הדברים וכן הוא ודאי. וכן העירו זה לפני ר\"ש. אמר אותו תנוק בנו של האיש, בעל הבית, אם כן למה כתוב חצות לילה. אמרו לו הרי כבר אמרנו, משום שבחצות לילה מלכות שמים מתעוררת. דהיינו כנ\"ל. אמר התנוק, אני שמעתי הדבר, אמר לו ר' אבא, טוב, אמור בני. כי האומר שבפיך יהיה קול של הנר. דהיינו בקול של ר\"ש. הנקרא בוצינא דנהורא. כמו שמסיים לפנינו."],[10,"אמר אנא שמענא וכו':","אמר התנוק אני שמעתי, כי לילה, היא זמן שליטת הדין של המלכות. ובכל מקום סתם לילה היא דין. ומה שאומר חצות לילה הוא משום שהמלכות יונקת אז בשתי בחינות, בדין ובחסד, וודאי הוא שחצי לילה הראשון הוא דין. כי מחצה האחרת מאיר הפנים מצד החסד. וע\"כ כתוב חצות לילה. ודאי. דהיינו המחצה של חסד."],[11,"קם ר' אבא וכו':","קם ר\"א ושם ידיו על ראשו וברכו. אמר חשבתי שהחכמה ודאי אינה נמצאת אלא באלו הצדיקים שזכו בה על ידי מעשיהם הטובים, ועתה אני רואה, שבדורו של ר' שמעון, אפילו תנוקות זכו בחכמה עלאה בזכותו. אשרי לך רבי שמעון. ווי להדור שאתה תסתלק ממנו. ישבו עד הבוקר ועסקו בתורה."]],[[0,"","(אמר רבי יוסי) וְלֹא עוֹד, אֶלָּא הוֹאִיל וְכָל הַצַּדִּיקִים שֶׁבְּתוֹךְ גַּן הָעֵדֶן מַקְשִׁיבִים לוֹ, שָׂמִים לוֹ חֵלֶק בְּאוֹתָהּ הַשְׁקָאַת הַנַּחַל. נִמְצָא שֶׁיֵּשׁ לוֹ חֵלֶק תָּמִיד בָּעוֹלָם הַבָּא."],[1,"","רַבִּי אַבָּא הָיָה בָּא מִטְּבֶרְיָה לְבֵית טְרוֹנְיָא שֶׁלְּחָמִיו, וְרַבִּי יַעֲקֹב בְּנוֹ הָיָה עִמּוֹ. נִפְגְּשׁוּ בִּכְפַר טְרָשָׁא. כְּשֶׁרָצוּ לִשְׁכַּב, אָמַר רַבִּי אַבָּא לְבַעַל הַבַּיִת: יֵשׁ כָּאן תַּרְנְגוֹל? אָמַר לוֹ בַּעַל הַבַּיִת: לָמָּה? אָמַר לוֹ: מִשּׁוּם שֶׁאֲנִי קָם בַּחֲצוֹת הַלַּיְלָה מַמָּשׁ."],[2,"","אָמַר לוֹ: לֹא צָרִיךְ, שֶׁהֲרֵי סִימָן יֵשׁ לִי בַּבַּיִת - שֶׁהַמִּשְׁקָל הַזֶּה שֶׁלִּפְנֵי מִטָּתִי, אֲנִי מְמַלֵּא אוֹתוֹ בְּמַיִם, וּמְטַפְטֵף טִפָּה טִפָּה. וּבַחֲצוֹת הַלַּיְלָה מַמָּשׁ מִתְרוֹקְנִים כָּל הַמַּיִם, וּמִתְגַּלְגֵּל הַגַּלְגַּל (הדבוק) הַזֶּה וְנוֹהֵם, וְנִשְׁמָע קוֹלוֹ בְּכָל הַבַּיִת. וְאָז הוּא חֲצוֹת הַלַּיְלָה מַמָּשׁ. וְזָקֵן אֶחָד הָיָה לִי שֶׁהָיָה קָם בְּכָל חֲצוֹת לַיְלָה וּמִשְׁתַּדֵּל בַּתּוֹרָה, וּמִשּׁוּם כָּךְ עָשָׂה אֶת זֶה."],[3,"","אָמַר רַבִּי אַבָּא: בָּרוּךְ הָרַחֲמָן שֶׁשְּׁלָחַנִי לְכָאן. בַּחֲצוֹת הַלַּיְלָה נָהַם אוֹתוֹ הַגַּלְגַּל (הדבוק). קָמוּ רַבִּי אַבָּא וְרַבִּי יַעֲקֹב, וְשָׁמְעוּ אֶת אוֹתוֹ הָאִישׁ שֶׁהָיָה יוֹשֵׁב בְּיַרְכְּתֵי הַבַּיִת וּשְׁנֵי בָנָיו עִמּוֹ, וְהָיָה אוֹמֵר, כָּתוּב (תהלים קיט) חֲצוֹת לַיְלָה אָקוּם לְהוֹדוֹת לָךְ עַל מִשְׁפְּטֵי צִדְקֶךְ. מָה רָאָה דָוִד שֶׁהוּא אָמַר חֲצוֹת לַיְלָה וְלֹא בַּחֲצוֹת הַלַּיְלָה? אֶלָּא חֲצוֹת לַיְלָה - וַדַּאי לַקָּדוֹשׁ- בָּרוּךְ-הוּא אָמַר כָּךְ."],[4,"","וְכִי כָּךְ נִקְרָא הַקָּדוֹשׁ בָּרוּךְ הוּא? כֵּן, שֶׁהֲרֵי חֲצוֹת לַיְלָה מַמָּשׁ הַקָּדוֹשׁ בָּרוּךְ הוּא נִמְצָא וְסִיעָתוֹ, וְאָז הִיא הַשָּׁעָה שֶׁנִּכְנָס לְגַן הָעֵדֶן לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים."],[5,"","אָמַר רַבִּי אַבָּא לְרַבִּי יַעֲקֹב, וַדַּאי נִשְׁתַּתֵּף עִם הַשְּׁכִינָה וְנִתְחַבֵּר יַחַד. קָרְבוּ וְיָשְׁבוּ עִמּוֹ. אָמְרוּ לוֹ, אֱמֹר דְּבַר פִּיךְ, שֶׁיָּפֶה אָמַרְתָּ, מִנַּיִן לְךְ זֶה? אָמַר לָהֶם, דָּבָר זֶה לָמַדְתִּי מִסָּבִי."],[6,"","וְעוֹד הָיָה אוֹמֵר, שֶׁשְּׁלֹשׁ (שתחלת) הַשָּׁעוֹת הָרִאשׁוֹנוֹת שֶׁל הַלַּיְלָה, כָּל הַדִּינִים שֶׁלְּמַטָּה מִתְעוֹרְרִים וְהוֹלְכִים וּמְשׁוֹטְטִים בָּעוֹלָם. וּבַחֲצוֹת הַלַּיְלָה מַמָּשׁ הַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעוֹרֵר בְּגַן עֵדֶן, וְהַדִּינִים שֶׁלְּמַטָּה אֵין נִמְצָאִים."],[7,"","וְכָל הַמִּנְהָגִים שֶׁלְּמַעְלָה בַּלַּיְלָה, אֵין נִמְצָאִים אֶלָּא בַּחֲצוֹת הַלַּיְלָה מַמָּשׁ. מִנַּיִן לָנוּ? מֵאַבְרָהָם, שֶׁכָּתוּב (בראשית יד) וַיֵּחָלֵק עֲלֵיהֶם לַיְלָה. בְּמִצְרַיִם - (שמות יב) וַיְהִי בַּחֲצִי הַלַּיְלָה. וּבִמְקוֹמוֹת רַבִּים בַּתּוֹרָה כָּךְ נִמְצָא. וְדָוִד הָיָה יוֹדֵעַ."],[8,"","(ומה) וּמִנַּיִן הָיָה יוֹדֵעַ? אֶלָּא כָּךְ אָמַר הַזָּקֵן, שֶׁמַּלְכוּתוֹ תְּלוּיָה בָּזֶה (הלילה), וְעַל זֶה עוֹמֵד בַּשָּׁעָה הַזּוֹ וְאוֹמֵר שִׁירָה, וְלָכֵן קָרָא לַקָּדוֹשׁ- בָּרוּךְ-הוּא חֲצוֹת לַיְלָה (ממש) אָקוּם לְהוֹדוֹת לָךְ וְגוֹ', שֶׁהֲרֵי כָּל הַדִּינִים תְּלוּיִים מִכָּאן, וְדִינֵי הַמַּלְכוּת נִמְצָאִים מִכָּאן. וּבְאוֹתָהּ הַשָּׁעָה נִקְשַׁר דָּוִד בָּהּ, וְקָם וְאָמַר שִׁירָה. בָּא רַבִּי אַבָּא וּנְשָׁקוֹ. אָמַר לוֹ, וַדַּאי כָּךְ הוּא. בָּרוּךְ הָרַחֲמָן שֶׁשְּׁלָחַנִי לְכָאן."],[9,"","בֹּא רְאֵה, הַלַּיְלָה הוּא דִין בְּכָל מָקוֹם, וַהֲרֵי הֵקַמְנוּ אֶת הַדְּבָרִים, וְכָךְ הוּא וַדַּאי, וַהֲרֵי הֵעַרְתִּי לִפְנֵי רַבִּי שִׁמְעוֹן. אָמַר אוֹתוֹ הַיֶּלֶד בְּנוֹ שֶׁל אוֹתוֹ הָאִישׁ, אִם כָּךְ, לָמָּה כָּתוּב חֲצוֹת לַיְלָה? אָמַר לוֹ, הֲרֵי נֶאֱמַר שֶׁבַּחֲצוֹת הַלַּיְלָה מִתְעוֹרֶרֶת מַלְכוּת הַשָּׁמַיִם. אָמַר, אֲנִי שָׁמַעְתִּי דָבָר. אָמַר לוֹ רַבִּי אַבָּא, אֱמֹר בְּנִי טוֹב, שֶׁהֲרֵי דְּבַר פִּיךְ יִהְיֶה קוֹל הַמָּאוֹר."],[10,"","אָמַר, אֲנִי שָׁמַעְתִּי, שֶׁהֲרֵי הַלַּיְלָה הוּא דִּין הַמַּלְכוּת, וּבְכָל מָקוֹם הוּא דִין. וְזֶה שֶׁאָמַר חֲצוֹת, מִשּׁוּם שֶׁיּוֹנֶקֶת בִּשְׁנֵי גְוָנִים (חצות) - בְּדִין וְחֶסֶד. וּוַדַּאי שֶׁהַמַּחֲצִית הָרִאשׁוֹנָה הִיא דִין, שֶׁהֲרֵי בַּמַּחֲצִית הָאַחֶרֶת הִיא מְאִירָה פָנֶיהָ בְּצַד הַחֶסֶד, וְעַל כֵּן חֲצוֹת לַיְלָה כָּתוּב וַדַּאי."],[11,"","קָם רַבִּי אַבָּא וְשָׂם יָדוֹ בְּרֹאשׁוֹ וּבֵרַךְ אוֹתוֹ. אָמַר, וַדַּאי חָשַׁבְתִּי שֶׁאֵין נִמְצֵאת חָכְמָה, רַק בְּאוֹתָם הַצַּדִּיקִים שֶׁזָּכוּ בָהּ. כָּעֵת רָאִיתִי שֶׁאֲפִלּוּ יְלָדִים בַּדּוֹר שֶׁל רַבִּי שִׁמְעוֹן זָכוּ לְחָכְמָה עֶלְיוֹנָה. אַשְׁרֶיךְ רַבִּי שִׁמְעוֹן! אוֹי לַדּוֹר שֶׁאַתָּה תִסְתַּלֵּק מִמֶּנּוּ! יָשְׁבוּ עַד הַבֹּקֶר וְהִתְעַסְּקוּ בַתּוֹרָה."]]],[["פָּתַח רַבִּי אַבָּא וְאָמַר (ישעיהו ס׳:כ״א) וְעַמֵּךְ כֻּלָּם צַדִּיקִים וְגו'. מִלָּה דָא הָא אוּקְמוּהָ חַבְרַיָיא מַאי טַעְמָא כְּתִיב וְעַמֵּךְ כֻּלָּם צַדִּיקִים, וְכִי כֻּלְהוּ יִשְׂרָאֵל צַדִּיקֵי נִינְהוּ. וְהָא כַּמָּה חַיָּיבִין אִית בְּהוּ בְּיִשְׂרָאֵל כַּמָּה חַטָּאִין וְכַמָּה רַשִּׁיעִין דְּעָבְרִין עַל פִּקּוּדֵי אוֹרַיְיתָא.","אֶלָּא הָכִי תָנָא בְּרָזָא דְמַתְנִיתִין. זַכָּאִין אִנּוּן יִשְׂרָאֵל דְּעָבְדִין קָרְבָּנָא דְרַעֲוָא לְקוּדְשָׁא בְּרִיךְ הוּא דְּמַקְרִיבִין בְּנַיְיהוּ לִתְמַנְיָא יוֹמִין לְקָרְבָּנָא, וְכַד אִתְגְּזָרוּ עָאלוּ בְּהַאי חוּלָקָא טָבָא דְּקוּדְשָׁא בְּרִיךְ הוּא דִּכְתִיב, (משלי י׳:כ״ה) וְצַדִּיק יְסוֹד עוֹלָם. כֵּיוָן דְּעָאלוּ בְּהַאי חוּלָקָא דְצַדִּיק אִקְרוּן צַדִּיקִים, וַדַּאי כֻּלָּם צַדִּיקִים.","וְעַל כֵּן לְעוֹלָם יִירְשׁוּ אָרֶץ. כְּדִכְתִיב, (תהילים קי״ח:כ׳) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק אָבֹא בָם. וּכְתִיב זֶה הַשַּׁעַר לַיְיָ צַדִּיקִים יָבֹאוּ בוֹ. אִנּוּן דְּאִתְגְּזָרוּ וְאִקְרוּן צַדִּיקִים. נֵצֶר מַטָּעַי. נִצֶר מֵאִנּוּן נְטִיעִין דְּנָטַע קוּדְשָׁא בְּרִיךְ הוּא בְּגִנְתָא דְעֵדֶן הַאי אֶרֶץ חַד מִנַיְיהוּ, וְעַל כֵּן אִית לְהוּ לְיִשְׂרָאֵל חוּלָקָא טָבָא בְּעָלְמָא דְּאָתֵי וּכְתִיב, (תהילים ל״ז:כ״ט) צַדִּיקִים יִירְשׁוּ אָרֶץ. (ישעיהו ס׳:כ״א) לְעוֹלָם יִירְשׁוּ אָרֶץ. מַהוּ לְעוֹלָם. כְּמָה דְּאוֹקִימְנָא בְּמַתְנִיתָּא דִילָן, וְהָא אִתְּמָר הַאי מִלָּה בֵּין חַבְרַיָיא.","(ותאנא מאי קא חמא קרא דלא אקרי אברהם עד השתא). (נ\"א תא חזי, קודשא בריך הוא לא קרא לאברהם אברהם עד השתא מאי טעמא. אלא הכי אוקימנא דעד השתא לא אתגזר, וכד אתגזר אתחבר ביה האי ה\"א ושריא ביה), אֶלָּא הָכִי אוֹקִימְנָא דְּעַד הַשְׁתָּא לָא אִתְגְּזַר, וְכַד אִתְגְּזַר אִתְחַבַּר בְּהַאי ה' וּשְׁכִינְתָּא שַׁרְיָא בֵּיהּ וּכְדֵין אִקְרֵי אַבְרָהָם.","וְהַיְנוּ דִּכְתִיב, (בראשית ב׳:ד׳) אֵלֶּה תּוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם. וְתָאנָא בְּה' בְּרָאָם. וְתָאנָא בְּאַבְרָהָם. מַאי קָאַמְרֵי אֶלָּא דָּא חֶסֶד וְדָא שְׁכִינְתָּא וְכֹלָּא נָחִית כְּחֲדָא, וְלָא קַשְׁיָא מִלָּה וְהַאי וְהַאי הֲוֵי.","אָמַר רַבִּי יַעֲקֹב לְרַבִּי אַבָּא הַאי ה' דְּהִבָּרְאָם זְעִירָא, וְה' (דברים ל\"ב ו) דְּהַלַּיְיָ רַבְרְבָא, מַה בֵּין הַאי לְהַאי, אָמַר לֵיהּ דָּא (שכינתא) שְׁמִיטָה, וְדָא יוֹבְלָא (ואית דמתני דכלא חד, דכד מנהרא מצדיק כדין קיימא באשלמותא וה' רברבא, דהא מתנהרא כדקא יאות, ולזמנין דלא קיימא באשלמותא וינקא מסטרא אחרא כדין ה\"א זעירא) וּבְגִין כָּךְ זִמְנִין דְּסִיהֲרָא קָיְימָא בְּאַשְׁלָמוּתָא וְזִמְנִין בִּפְגִימוּתָא, וּבְאַנְפָּהָא אִשְׁתְּכַח וְאִשְׁתְּמוֹדַע וְכֹלָּא שַׁפִּיר. וְהַאי אִיהוּ בְּרִירָא דְּמִלָּה.","אָמַר רַבִּי אַבָּא זַכָּאִין אִנּוּן יִשְׂרָאֵל דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בְּהוֹן מִכָּל שְׁאָר עַמִין, וְיָהִיב לוֹן אָת קְיָימָא דָא, דְּכָל מַאן דְּאִית בֵּיהּ הַאי אָת, לָא נָחִית לַגֵּיהִנֹּם אִי אִיהוּ נָטִיר לֵיהּ כְּדְקָא יָאוּת דְּלָא עָיִיל לֵיהּ בִּרְשׁוּתָא אָחֳרָא וְלָא מְשַׁקֵּר בִּשְׁמֵיהּ דְּמַלְכָּא, דְּכָל מַאן דִּמְשַׁקֵּר בְּהַאי, כְּמַאן דִּמְשַׁקֵּר בִּשְׁמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא דִּכְתִיב, (הושע ה׳:ז׳) בַּיְיָ בָּגָדוּ כִּי בָּנִים זָרִים יָלָדוּ.","תוּ אָמַר רַבִּי אַבָּא בְּזִמְנָא דְּבַר נָשׁ אַסִּיק בְּרֵיהּ לְאָעֳלֵיהּ לְהַאי בְּרִית, קְרֵי קוּדְשָׁא בְּרִיךְ הוּא לְפַמַּלְיָא דִילֵיהּ וְאָמַר חָמוּ מַאי בְּרִיָּה עֲבָדִית בְּעָלְמָא. בֵּיהּ שַׁעֲתָא אִזְדַּמַּן (ליה) אֵלִיָהוּ וְטָאס (מו ב) עָלְמָא בְּד' טָאסִין וְאִזְדַּמַּן תַּמָּן.","וְעַל דָּא תָּנִינָן דְּבָעֵי בַּר נָשׁ לְתַקָּנָא כֻּרְסְיָיא אָחֳרָא לִיקָרָא דִּילֵיהּ, וְיֵימָא (יג א) דָּא כֻּרְסְיָיא דְּאֵלִיָּהוּ, וְאִי לָאו לָא שָׁרֵי תַמָּן. וְהוּא סָלִיק וְאַסְהִיד קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא.","תָּא חֲזֵי, בְּקַדְמִיתָא כְּתִיב, (מלכים א י״ט:ט׳-י׳) מַה לְּךָ פֹה אֵלִיָּהוּ וְגו'. וּכְתִיב קַנֹּא קִנֵאתִי לַיְיָ (אלהי צבאות) כִּי עָזְבוּ בְּרִיתְךָ בְּנֵי יִשְׂרָאֵל וְגו'. אָמַר לֵיהּ חַיֶּיךָ בְּכָל אֲתַר דְּהַאי רְשִׁימָא קַדִּישָׁא יִרְשְׁמוּן לֵיהּ בָּנַי בִּבְשַׂרְהוֹן אַנְתְּ תִּזְדַּמַּן תַּמָּן, וּפוּמָא דְּאַסְהִיד דְּיִשְׂרָאֵל עָזְבוּ, הוּא יַסְהִיד דְּיִשְׂרָאֵל מְקַיְימִין הַאי קְיָימָא. וְהָא תָּנִינָן עַל מָה אִתְעַנַּשׁ אֵלִיָּהוּ קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא עַל דְּאָמַר דִּלְטוֹרָא עַל בְּנוֹי.","אַדְהָכִי הֲוָה אָתֵי נְהוֹרָא דְיוֹמָא וְהֲווּ אֲמָרֵי מִלֵּי דְאוֹרַיְיתָא. קָמוּ לְמֵיזַל. אָמַר לֵיהּ הַהוּא גַבְרָא בַּמֶּה דְּעַסְקִיתוּ בְּהַאי לֵילְיָא אַשְׁלִימוּ. אֲמָרֵי מַאי הוּא. אָמַר לֶהוּ דְּתֶחמוּן לִמְחָר אַנְפּוֹי דְּמָרֵיהּ דְּקַיָימָא, דְּהָא דְּבִיתָאי בָּעָאת בָּעוּתָא דָא מִנַּיְיכוּ. וּגְזַר קְיָימָא דִּבְרֵי דְּאִתְיְילִיד לִי, לְמָחָר לֵיהֱוֵי הִלּוּלָא דִילֵיהּ. אָמַר רַבִּי אַבָּא הַאי בְּעוּתָא דְּמִצְוָה אִיהוּ וּלְמֶחמֵי אַפֵּי שְׁכִינְתָּא נֵיתִיב."],[[0,"פתח ר' אבא וכו':","פתח ר\"א ואמר. ועמך כלם צדיקים, וגו'. דבר זה כבר בארוהו החברים. מה הטעם שכתוב ועמך כלם צדיקים, וכי כל ישראל הם צדיקים, והרי כמה רשעים יש בישראל כמה חוטאים וכמהפושעים שעוברים על מצות התורה."],[1,"אלא הכי תנא וכו':","אלא כך למדנו בסוד המשנה. אשריהם ישראל שמקריבים קרבן רצון לפני הקב\"ה, שמקריבים בניהם לקרבן לשמונה ימים. וכשנמולו נכנסים באותו חלק הטוב של הקב\"ה, שכתוב וצדיק יסוד עולם. כיון שנכנסו בחלק הזה של הצדיק בזכות המילה, הטה נקראים צדיקים. וודאי כלם צדיקים. כי כלם נמולו, ואפילו הרשעים שבישראל. וע\"כ אמר הכתוב, ועמך כלם צדיקים."],[2,"וע\"כ לעולם ירשו ארץ:","שהוא השכינה הנקראת ארץ. כמו שכתוב פתחו לי שערי צדק אבא בם. וכתוב זה השער לה' צדיקים יבואו בו, דהיינו אלו שנמולו ונקראים צדיקים. פירוש ארץ הוא מלכות, וכיון שנמולו הם נקראים צדיקים, שפותחים להם שערי צדק, דהיינו שערי המלכות. הרי שכל ישראל \u0003ירשו ארץ,\u0004 שבשביל שנמולו פותחים להם השערים. \u0003נצר מטעי,\u0004 נצר מאלו הנטיעות שנטע הקב\"ה בגן עדן, אשר ארץ הזו הוא אחת מאלו הנטיעות, הנטיעות, הן עשר ספירות שבגן עדן והמלכות שבהן נקראת ארץ. ועל כן יש לישראל חלק טוב בעולם הבא, שכתוב וצדיקים ירשו ארץ. לעולם ירשו ארץ. ושואל מהו לעולם ואומר כמו שבארוהו במשנה שלנו וכבר נתבאר דבר זה בין החברים. והישוב על זה נמצא להלן פרשת ויחי אות קצ\"ד ע\"ש."],[3,"ותאנא מאי וכו':","ולמדנו מה ראה הכתוב, שלא נקרא אברהם עד עתה. אלא כך בארנוהו, כי עד עתה לא נמול ועתה נמול, וכשנמול נתחבר בה' זו שהוא השכינה, והשכינה שרתה בו, ועל כן נקרא אז אברהם עם \u0003ה'.\u0004"],[4,"והיינו דכתיב אלה וגו':","והיינו שכתוב אלה תולדות השמים וארץ בהבראם ולמדנו ב \u0003ה'\u0004 בראם. ולמדנו באברהם. כלומר שבהבראם אותיות באברהם, ללמדנו שבשביל אברהם נברא העולם. ושואל מה הם אומרים. כלומר, למה חולקים זה על זה בפירוש \u0003בהבראם.\u0004 ומשיב, \u0003אלא דא חסד.\u0004 זה שאומר שבהבראם רומז לאברהם. היינו חסד, שבשביל חסד נברא העולם. \u0003ודא שכינתא.\u0004 וזה שאומר ב \u0003ה'\u0004 בראם היינו השכינה. כי \u0003ה'\u0004 רומזת להשכינה. ואין קושיא מאחד על חבירו, כי הכל יורד ביחד, כלומר אם החסד בעולם גם השכינה בעולם וכן להיפך, וע\"כ ב' המשמעות חסד ושכינה ענין אחד הוא \u0003והאי והאי הוי,\u0004 והעולם נברא בשביל החסד ובשביל השכינה."],[5,"אמר ר' יעקב לר' אבא","וכו': אר\"י לר\"א, ה' זו דהבראם, קטנה, וה' דהלה' תגמלו זאת, גדולה. מהו ההפרש בין ה' זו לזו. אמר לו, זו, ה' קטנה, שמיטה, דהיינו מלכות, וזו, ה' גדולה, יובל דהיינו בינה, ומשום זה, לפעמים עומדת הלבנה במילואה, ולפעמים היא פגומה. כשמלבשת הבינה, שהיא אז ה' גדולה, היא במילואה. ומטרם שהיא מלבשת הבינה היא ה' קטנה והיא פגומה. ובפניה של הלבנה נמצא וניכר ההפרש מה' קטנה לגדולה. והכל יפה. וזהו בירורו של הדבר."],[6,"אמר ר' אבא וכו':","אר\"א אשריהם ישראל, שהקב\"ה בחר בהם מכל שאר העמים, ונתן להם אות ברית הזה. כי כל מי שיש בו אות הזה, אינו יורד לגיהנם, אם שמר אותו כראוי, שלא הכניסו לרשות אחר דהיינו, לנדה שפחה גויה זונה, ולא שקר בשמו של המלך. כי כל מי שמשקר בשמו באות ברית, הוא כמו שמשקר בשמו של הקב\"ה, שכתוב, בה' בגדו כי בנים זרים ילדו."],[7,"תו אמר ר' אבא:","עוד אמר ר\"א, בשעה שהאדם מעלה את בנו להכניסו בברית הזה קורא הקב\"ה אל פמליא שלו, דהיינו למלאכי מרום, ואומר, ראו טיבה של הבריה שעשיתי בעולם, בה בשעה מזדמן אליהו, ומעופף העולם בד' עפיפות. ונזדמן שם. (וביאור הדברים תמצא לעיל בהקדמת הזהר דף ר\"י אות רכ\"ה."],[8,"ועל דא תנינן וכו':","ועל כן למדנו, שאדם צריך לתקן כסא מיוחד לכבודו של אליהו, ויאמר, זהו כסא של אליהו. ואם אינו אומר, אינו שורה שם. והוא עולה ומעיד לפני הקב\"ה. (והביאור תמצא שם דף קע\"ג ד\"ה ולאדכרא)."],[9,"תא חזי בקדמיתא","וכו': בוא וראה בתחילה כתוב מה לך פה אליהו וגו', וכתוב קנא קנאתי לה' וגו' כי עזבו בריתך וגו'. אמר לו, הקב\"ה לאליהו חייך, בכל מקום שירשמו בני רשימה קדושה הזו בבשרם, אתה תזדמן שם. והפה שהעיד שישראל עזבו ברית, הוא יעיד שישראל מקיימים הברית. והנה למדנו על מה נענש אליהו לפני הקב\"ה, משום שאמר דברי האשמה על בניו. כי אמר, כי עזבו בריתך בני ישראל. (וביאור הדברים תמצא שם דף ר\"י אות רכ\"ה)."],[10,"אדהכי הוה אתי","וכו': בינתים האיר אור היום, ועוד היו אומרים דברי תורה, קמו ללכת, אמר להם אותו האדם, בעל הבית, מה שעסקתם, בלילה הזה, השלימו. אמרו מה הוא. אמר להם, שתראו למחר פניו של בעל הברית, דהיינו אליהו, כי אשתי מבקשת בקשה זו מכם. כי מילת הברית של בני הנולד לי, למחר יהי' השמחה שלו. אמר ר' אבא, זו היא בקשה של מצוה, נשב."]],[[0,"","פָּתַח רַבִּי אַבָּא וְאָמַר, וְעַמֵּךְ כֻּלָּם צַדִּיקִים וְגוֹ'. הַדָּבָר הַזֶּה הֲרֵי בֵּאֲרוּהוּ הַחֲבֵרִים, מָה הַטַּעַם כָּתוּב (ישעיה ס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים, וְכִי כָּל יִשְׂרָאֵל הֵם צַדִּיקִים? וַהֲרֵי כַּמָּה רְשָׁעִים יֵשׁ בְּיִשְׂרָאֵל, כַּמָּה חוֹטְאִים וְכַמָּה רְשָׁעִים שֶׁעוֹבְרִים עַל מִצְווֹת הַתּוֹרָה."],[1,"","אֶלָּא כָּךְ שָׁנָה בְּסוֹד הַמִּשְׁנָיוֹת: אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁעוֹשִׂים קָרְבָּן שֶׁל רָצוֹן לַקָּדוֹשׁ-בָּרוּךְ-הוּא, שֶׁמַּקְרִיבִים אֶת בְּנֵיהֶם לִשְׁמוֹנָה יָמִים לְקָרְבָּן, וּכְשֶׁנִּמּוֹלִים, נִכְנָסִים לַחֵלֶק הַטּוֹב שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (משלי י) וְצַדִּיק יְסוֹד עוֹלָם. וְכֵיוָן שֶׁנִּכְנְסוּ בַּחֵלֶק הַזֶּה שֶׁל הַצַּדִּיק, הֵם נִקְרָאִים צַדִּיקִים. וַדַּאי כֻּלָּם צַדִּיקִים."],[2,"","וְעַל כֵּן לְעוֹלָם יִירְשׁוּ אָרֶץ, כַּכָּתוּב (תהלים קיח) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק אָבֹא בָם, וְכָתוּב זֶה הַשַּׁעַר לַה' צַדִּיקִים יָבאוּ בוֹ, אוֹתָם שֶׁנִּמּוֹלוּ וְנִקְרָאִים צַדִּיקִים. נֵצֶר מַטָּעַי - נֵצֶר מֵאוֹתָם הַנְּטִיעוֹת שֶׁנָּטַע הַקָּדוֹשׁ בָּרוּךְ הוּא בְּגַן עֵדֶן. הָאָרֶץ הַזּוֹ הִיא אַחַת מֵהֶן, וְעַל כֵּן יֵשׁ לְיִשְׂרָאֵל חֵלֶק טוֹב לָעוֹלָם הַבָּא, וְכָתוּב (שם לז) צַדִּיקִים יִירְשׁוּ אָרֶץ. (יסעיה ס) לְעוֹלָם יִירְשׁוּ אָרֶץ, מַה זֶּה לְעוֹלָם? כְּמוֹ שֶׁבֵּאַרְנוּ בְּמִשְׁנָתֵנוּ, וַהֲרֵי הַדָּבָר הַזֶּה נִתְבָּאֵר בֵּין הַחֲבֵרִים."],[3,"","(ולמדנו, מה ראה הכתוב שלא נקרא אברהם עד עתה)? (נ\"א: בא ראה, הקדוש ברוך הוא לא קרא לאברהם אברהם עד עתה, מה הטעם? אלא כך בארנו, שעד עתה לא נמול, וכשנמול, התחברה בו הה\"א הזו ושרתה בו). אֶלָּא כָּךְ בֵּאַרְנוּ, שֶׁעַד עַכְשָׁו לֹא נִמּוֹל, וּכְשֶׁנִּמּוֹל, הִתְחַבֵּר לַהֵ\"א הַזּוֹ וְהַשְּׁכִינָה שָׁרְתָה בּוֹ, וְאָז נִקְרָא אַבְרָהָם."],[4,"","וְהַיְנוּ מַה שֶּׁכָּתוּב (בראשית ב) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם. וְשָׁנָה בְּה' בְּרָאָם, וְשָׁנָה בְּאַבְרָהָם. מָה אוֹמְרִים? אֶלָּא זֶה חֶסֶד וְזוֹ הַשְּׁכִינָה, וְהַכֹּל יוֹרֵד יַחַד, וְהַדָּבָר לֹא קָשֶׁה, וְזֶה וְזֶה הָיָה."],[5,"","אָמַר רַבִּי יַעֲקֹב לְרַבִּי אַבָּא, הַה' הַזּוֹ שֶׁל הִבָּרְאָם הִיא קְטַנָּה, וְה' שֶׁל הַלְה' (דברים לב) - גְּדוֹלָה. מַה בֵּין זֶה לָזֶה? אָמַר לוֹ, זוֹ שְׁמִטָּה, וְזֶה יוֹבֵל, (ויש ששונים שהכל אחד, שכאשר מאירה מהצדיק, אז עומדת בשלמות וה\"א גדולה, שהרי מוארת כראוי, ופעמים שלא עומדת בשלמות ויונקת מצד האחר, אז ה\"א קטנה). וּמִשּׁוּם כָּךְ לִפְעָמִים שֶׁהַלְּבָנָה עוֹמֶדֶת בִּשְׁלֵמוּתָהּ, וְלִפְעָמִים בְּחֶסְרוֹנָהּ, וּבְפָנֶיהָ נִמְצָא וְנוֹדָע, וְהַכֹּל יָפֶה, וְזֶה הוּא בֵּרוּר הַדָּבָר."],[6,"","אָמַר רַבִּי אַבָּא, אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָהֶם מִכָּל שְׁאָר הָעַמִּים וְנָתַן לָהֶם אוֹת הַבְּרִית הַזּוֹ, שֶׁכָּל מִי שֶׁיֵּשׁ בּוֹ אוֹת הַבְּרִית הַזּוֹ, אֵין יוֹרֵד לַגֵּיהִנֹּם אִם הוּא שׁוֹמֵר אוֹתוֹ כָּרָאוּי, שֶׁאֵין מַכְנִיס אוֹתוֹ לְרָשׁוּת אַחֶרֶת וְלֹא מְשַׁקֵּר בְּשֵׁם הַמֶּלֶךְ. שֶׁכָּל מִי שֶׁמְּשַׁקֵּר בָּזֶה, כְּמִי שֶׁמְּשַׁקֵּר בִּשְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (הושע ה) בַּה' בָּגָדוּ כִּי בָנִים זָרִים יָלָדוּ."],[7,"","עוֹד אָמַר רַבִּי אַבָּא, בִּזְמַן שֶׁהָאָדָם מַעֲלֶה אֶת בְּנוֹ לְהַכְנִיסוֹ לַבְּרִית הַזּוֹ, קוֹרֵא הַקָּדוֹשׁ בָּרוּךְ הוּא לַפָּמַלְיָא שֶׁלּוֹ וְאוֹמֵר, רְאוּ אֵיזוֹ בְּרִיָּה עָשִׂיתִי בָּעוֹלָם! בְּאוֹתָהּ הַשָּׁעָה מִזְדַּמֵּן (לו) אֵלִיָּהוּ, וְטָס אֶת הָעוֹלָם בְּאַרְבַּע טִיסוֹת וּמִזְדַּמֵּן לְשָׁם,"],[8,"","וְעַל זֶה שָׁנִינוּ שֶׁצָּרִיךְ אָדָם לְתַקֵּן כִּסֵּא אַחֵר לִכְבוֹדוֹ, וְיֹאמַר: זֶה הַכִּסֵּא שֶׁל אֵלִיָּהוּ. וְאִם לֹא, אֵינוֹ שׁוֹרֶה שָׁם. וְהוּא עוֹלֶה וּמֵעִיד לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא."],[9,"","בֹּא רְאֵה, בָּרִאשׁוֹנָה כָּתוּב (מלכים א יט) מַה לְּךְ פֹּה אֵלִיָּהוּ וְגוֹ', וְכָתוּב קַנֹּא קִנֵּאתִי לַה' אֱלֹהֵי צְבָאוֹת כִּי עָזְבוּ בְרִיתְךְ בְּנֵי יִשְׂרָאֵל וְגוֹ'. אָמַר לוֹ, חַיֶּיךְ, שֶׁבְּכָל מָקוֹם שֶׁהָרֹשֶׁם הַקָּדוֹשׁ הַזֶּה יִרְשְׁמוּ אוֹתוֹ בָּנַי בִּבְשָׂרָם, אַתָּה תִזְדַּמֵּן לְשָׁם. וְהַפֶּה שֶׁהֵעִיד שֶׁיִּשְׂרָאֵל עָזְבוּ, הוּא יָעִיד שֶׁיִּשְׂרָאֵל מְקַיְּמִים אֶת הַבְּרִית הַזּוֹ. וַהֲרֵי שָׁנִינוּ, עַל מָה נֶעֱנַשׁ אֵלִיָּהוּ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא? עַל שֶׁאָמַר לָשׁוֹן הָרָע עַל בָּנָיו."],[10,"","בֵּינְתַיִם בָּא אוֹר הַיּוֹם, וְהָיוּ אוֹמְרִים דִּבְרֵי תוֹרָה. קָמוּ לָלֶכֶת, אָמַר לוֹ אוֹתוֹ הָאִישׁ, בְּמַה שֶּׁעֲסַקְתֶּם בַּלַּיְלָה הַזֶּה הַשְׁלִימוּ. אָמְרוּ, מַה הוּא? אָמַר לוֹ, שֶׁתִּרְאוּ לְמָחָר אֶת פָּנָיו שֶׁל בַּעַל הַבְּרִית, שֶׁהֲרֵי אִשְׁתִּי בִּקְשָׁה אֶת הַבַּקָּשָׁה הַזּוֹ מִכֶּם, וּמִילַת הַבְּרִית שֶׁל בְּנִי שֶׁנּוֹלַד לִי - לְמָחָר תִּהְיֶה הַהִלּוּלָא שֶׁלּוֹ. אָמַר רַבִּי אַבָּא, זוֹ הִיא בַּקָּשָׁה שֶׁל מִצְוָה, וְנֵשֵׁב לִרְאוֹת אֶת פְּנֵי הַשְּׁכִינָה."]]],[["אוֹרִיכוּ כָּל הַהוּא יוֹמָא, בְּהַהוּא לֵילְיָא כָּנַשׁ הַהוּא גַבְרָא כָּל אִנּוּן רְחִימוֹי, וְכָל הַהוּא לֵילְיָא אִשְׁתַּדָּלוּ בְּאוֹרַיְיתָא וְלָא הֲוָה מַאן דְּנָאִים, אָמַר לֶהוּ הַהוּא גַבְרָא בְּמָטוּ מִנַּיְיכוּ כָּל חַד וְחַד לֵימָא מִלָּה חַדְתָּא דְאוֹרַיְיתָא:","פָּתַח חַד (רבי אבא) וְאָמַר (שופטים ה׳:ב׳) בִּפְרוֹעַ פְּרָעוֹת בְּיִשְׂרָאֵל בְּהִתְנַדֵב עָם בָּרְכוּ יְיָ. מַאי קָא חָמוּ דְּבוֹרָה וּבָרָק דְּפָתְחוּ בְּהַאי קְרָא. אֶלָּא הָכִי תָּנִינָן לֵית עָלְמָא מִתְקָיְימָא אֶלָּא עַל הַאי בְּרִית דִּכְתִיב, (ירמיהו ל״ג:כ׳) אִם לֹא בְרִיתִי יוֹמָם וָלַיְלָה וְגו' דְּהָא שְׁמַיָא וְאַרְעָא עַל דָּא קָיְימִין.","בְּגִין כָּךְ כָּל זִמְנָא דְיִשְׂרָאֵל מְקַיְימִין הַאי בְּרִית, נִמּוּסֵי שְׁמַיָא וְאַרְעָא קָיְימִין בְּקִיּוּמַיְיהוּ, וְכָל זִמְנָא דְּחַס וְשָׁלוֹם יִשְׂרָאֵל מְבַטְּלִין הַאי בְּרִית, שְׁמַיָא וְאַרְעָא לָא מִתְקָיְימִין, וּבִרְכָאן לָא מִשְׁתַּכְּחִין בְּעָלְמָא.","תָּא חֲזֵי, לָא שַׁלִּיטוּ שְׁאָר עַמִּין עַל יִשְׂרָאֵל אֶלָּא כַּדּ בְּטִילוּ מִנַּיְיהוּ קְיָימָא דָּא. וּמַה בְּטִילוּ מִנַיְיהוּ. דְּלָא אִתְפָּרְעָן וְלָא אִתְגַּלְיָין. וְעַל דָּא כְּתִיב וַיַּעַזְבוּ בְּנִי יִשְׂרָאֵל אֶת יְיָ וְגו' וַיִּמְכֹּר אוֹתָם בְּיַד סִיסְרָא, וַיַּעַזְבוּ אֶת יְיָ מַמָּשׁ. עַד דְּאֲתַת דְּבוֹרָה וְאִתְנַדְּבַת לְכָל יִשְׂרָאֵל בְּמִלָּה דָא, כְּדֵין אִתְכְּנָעוּ שַׂנְאֵיהוֹן תְּחוֹתַיְיהוּ.","וְהַיְינוּ דְּתָנִינָן דְּאָמַר קוּדְשָׁא בְּרִיךְ הוּא לִיהוֹשֻׁעַ וְכִי יִשְׂרָאֵל אֲטִימִין אִנּוּן וְלָא (בא מ' א') (ע) אִתְפְּרָעוּ וְלָא אִתְגַּלְיָיא וְלָא קָיְימִין קְיָימָא דִילִי, וְאַתְּ בָּעֵי לְאָעֳלָא לְהוּ לְאַרְעָא וּלְאַכְנָעָא שַׂנְאֵיהוֹן. (יהושע ה׳:ב׳) שׁוּב מוֹל אֶת בְּנִי יִשְׂרָאֵל שֵׁנִית. וְעַד דְּאִתְפְּרָעוּ וְאִתְגַּלְּיָיא הַאי בְּרִית לָא עָאלוּ לְאַרְעָא וְלָא אִתְכְּנָעוּ שַׂנְאֵיהוֹן. אוּף הָכָא כֵּיוָן דְּאִתְנַדְּבִין יִשְׂרָאֵל בְּהַאי אָת אִתְכְּנָעוּ שַׂנְאֵיהוֹן תְּחוֹתַיְיהוּ וּבִרְכָאן אִתְחֲזָרוּ לְעָלְמָא הֲדָא הוּא דִכְתִיב בִּפְרוֹעַ פְּרָעוֹת בְּיִשְׂרָאֵל בְּהִתְנַדֵּב עָם בָּרְכוּ יְיָ.","קָם אָחֳרָא פָּתַח וְאָמַר, (שמות ד׳:כ״ד) וַיְהִי בַדֶּרֶךְ בַּמָּלוֹן וַיִּפְגְּשֵׁהוּ יְיָ וַיְבַקֵּשׁ הֲמִיתוֹ לְמַאן לְמשֶׁה. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא וְכִי אַתְּ אָזִיל לְאַפָּקָא יַת יִשְׂרָאֵל מִמִּצְרָיִם וּלְאַכְנְעָא מַלְכָּא רַב וְשַׁלִּיטָא, וְאַתְּ אַנְשְׁיֵית מִנָךְ קְיָימָא. דִּבְרָךְ לָא אִתְגְּזַר, מִיָּד וַיְבַקֵּשׁ הֲמִיתוֹ.","תָּאנָא נָחַת גַּבְרִיאֵל בְּשַׁלְהוֹבָא דְּאֶשָׁא לְאוֹקְדֵיהּ, וְאִתְרְמִיז חַד חִיוְיָא מִתּוֹקְדָא לְשָׁאפָא לֵיהּ בְּגַוֵּיהּ. אַמַּאי חִיוְיָא, אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא אַתְּ אָזִיל לְקַטְלָא חִיוְיָא רַבְרְבָא וְתַקִּיפָא וּבְרָךְ לָא אִתְגְּזַר. מִיָּד אִתְרְמִיז לְחַד חִיוְיָא לְקַטְלָא לֵיהּ,","עַד דְּחָמַת צִפּוֹרָה וְגַזְרַת לִבְרָהּ וְאִשְׁתְּזִיב הֲדָא הוּא דִכְתִיב וַתִּקַּח צִפּוֹרָה צוֹר. מַהוּ צוֹר, אֶלָּא אַסְוָותָא. וּמַאי אַסְוָותָא דִּכְתִיב וַתִּכְרוֹת אֶת עָרְלַת בְּנָהּ. דְּנִצְנְצָא בָּהּ רוּחַ קוּדְשָׁא.","קָם אָחֳרָא וְאָמַר (בראשית מ״ה:ד׳) וַיֹּאמֶר יוֹסֵף אֶל אֶחָיו גְּשׁוּ נָא אֵלַי וַיִּגָּשׁוּ וַיֹּאמֶר וְגו'. וְכִי אַמַּאי קָרֵי לְהוּ וְהָא קְרִיבִין הֲווּ גַבֵּיהּ. אֶלָּא בְּשַׁעֲתָא דְּאָמַר לוֹן אֲנִי יוֹסֵף אֲחִיכֶם. תְּוָוהוּ דְּחָמוּ לֵיהּ בְּמַלְכוּ עִלָּאָה. אָמַר יוֹסֵף מַלְכוּ דָּא בְּגִין דָּא רַוַוחְנָא לֵיהּ, גְּשׁוּ נָא אֵלַי וַיִּגָּשׁוּ, דְּאַחֲזֵי לְהוּ הַאי קְיָימָא דְמִילָה, אָמַר דָּא גָרְמַת לִי מַלְכוּ דָא בְּגִין דְּנָטְרִית לָהּ.","מִכָּאן אוֹלִיפְנָא מַאן דְּנָטִיר לְהַאי אָת קְיָימָא מַלְכוּ אִתְנַטְרַת לֵיהּ. מְנָלָן מִבֹּעַז דִּכְתִיב, (רות ג׳:י״ג) חַי יְיָ שִׁכְבִי עַד הַבֹּקֶר דְּהֲוָה מְקַטְרֵג לֵיהּ יִצְרֵיהּ עַד דְּאוֹמֵי אוֹמָאָה וּנְטִיר לְהַאי בְּרִית, בְּגִין כָךְ זָכָה דְּנָפְקוּ מִנֵּיהּ מַלְכִין שַׁלִּיטִין עַל כָּל שְׁאָר מַלְכִין, וּמַלְכָּא מְשִׁיחָא דְּאִתְקְרֵי בִּשְׁמָא דְקוּדְשָׁא בְּרִיךְ הוּא:","פָּתַח אִידָךְ וְאָמַר כְּתִיב, (תהילים כ״ז:ג׳) אִם תַּחֲנֶה עָלַי מַחֲנְה וְגו'. הָכִי תָאנָא בְּזֹאת אֲנִי בוֹטֵחַ, מַהוּ בְּזֹאת, דָּא אָת קְיָימָא דִּזְמִינָא תָּדִיר גַּבֵּי בַּר נָשׁ וְאִתְרְמִיזָא לְעֵילָא, וּבְגִינֵי כָךְ אִתְּמָר בְּזֹאת כְּמָה דִכְתִיב זֹאת אוֹת הַבְּרִית. זֹאת בְּרִיתִי. וְכֹלָּא בְּחַד דַּרְגָּא. וְתָאנָא זֶה וְזֹאת בְּחַד דַּרְגָּא אִנּוּן וְלָא מִתְפָּרְשָׁן.","וְאִי תֵימָא אִי הָכִי הָא שְׁאָר בְּנֵי עָלְמָא הָכִי. אַמַּאי דָּוִד בִּלְחוֹדוֹי וְלָא אָחֳרָא. אֶלָּא בְּגִין דְּאֲחִידָא בֵּיהּ וְאִתְרְמִיזָא בֵּיהּ וְהוּא כִתְרָא דְּמַלְכוּתָא.","תָּא חֲזֵי, בְּגִין דְּהַאי זֹאת לָא נָטַר לֵיהּ דָּוִד מַלְכָּא כְּדְקָא חָזֵי, מַלְכוּתָא אִתְעַדֵּי מִנֵּיהּ כָּל הַהוּא זִמְנָא. וְהָכִי אוֹלִיפְנָא הַאי זֹאת אִתְרְמִיזָא בְּמַלְכוּתָא דִלְעֵילָא, וְאִתְרְמִיזָא בִּיְרוּשָׁלַ ם קַרְתָּא קַדִּישָׁא."],[[0,"אוריכו כל","וכו': המתינו כל אותו היום, ובלילה אסף אותו האיש כל אוהביו. וכל אותו הלילה עסקו בתורה, ולא היה מי שישן, אמר להם אותו האיש, בבקשה מכם, כל אחד ואחד יאמר דבר חידוש בתורה."],[1,"פתח חד","וכו': פתח אחד ואמר, כתוב בפרוע פרעות בישראל וגו'. ושואל, מה ראו דבורה וברק שפתחו את שירתם בכתוב הזה. אלא כך למדנו, אין העולם מתקיים אלא על ברית הזה, שכתוב אם לא בריתי יומם ולילה חוקות שמים וארץ לא שמתי."],[2,"בגין כך וכו':","משום זה כל זמן שישראל מקיימים ברית הזה, חוקות שמים וארץ נמצאים בקיומם. וכל זמן שישראל מבטלים ברית הזה, ברית שמים וארץ אינו מתקיים, וברכות אינם נמצאות בעולם."],[3,"ת\"ח לא שליטו וכו':","בוא וראה, לא שלטו עמים אחרים על ישראל אלא כאשר בטלו מהם ברית הזה. ומה בטלו מהם, שמלו, ולא פרעו, ולא נגלה בשר קדש. ועל כן כתוב ויעזבו בני ישראל את ה' וגו', וימכור אותם ביד סיסרא. הרי שהעמים לא שלטו בהם אלא אחר שבטלו הברית. ויעזבו את ה', ממש. פירוש, כי על ידי הפריעה מתגלים אותיות השם י\"ה שה\"ס המוחין העליונים וע\"כ \u0003פריעה\u0004 אותיות \u0003פרע י\"ה\u0004 וכיון שלא פרעו, לא נגלה עליהם השם \u0003י\"ה,\u0004 וז\"ש ויעזבו את ה' ממש, שעזבו השם י\"ה."],[3,"עד דאתת דבורה","וכו':עד שבאה דבורה והתנדבה עצמה לכל ישראל בדבר הזה, דהיינו לגלות המוחין די\"ה שה\"ס פריעה, אז נכנעו שונאיהם תחתיהם."],[4,"והיינו דתנינן וכו':","והיינו שלמדנו, שאמר הקב\"ה ליהושע הרי ישראל ערלים הם, שלא פרעו ולא נגלה בשר קדש, ואינם מקימים הברית שלי, ואתה רוצה להביאם לארץ, ולהכניע את שונאיהם, שוב מול את בני ישראל שנית. ומטרם שפרעו ונתגלה ברית הזה לא נכנסו לארץ, ולא נכנעו שונאיהם. אף כאן, כיון שהתנדבו ישראל באות ברית הזה. נכנעו שונאיהם תחתיהם, והברכות חזרו לעולם. וזהו שכתוב \u0003בפרוע פרעות בישראל,\u0004 שה\"ס \u0003פריעה, בהתנדב עם,\u0004 שהתנדבו לשמור את זה, \u0003ברכו ה'.\u0004 ומטעם זה התחילה שירת דבורה וברק בפסוק הזה."],[5,"קם אחרא ופתח וכו':","קם אחר ופתח ואמר, ויהי בדרך במלון ויפגשהו ה' ויבקש המיתו. למי ביקש להמית. למשה, אמר לו הקב\"ה וכי אתה הולך להוציא את ישראל ממצרים, ולהכניע מלך רב ושליט, ואתה מבטל מצוה ממך, כי בנך לא נמול. מיד ויבקש המיתו."],[6,"תאנא נחת וכו':","למדנו, ירד גבריאל בלהב אש לשרפו, ונרמז נחש שרף אחד שיבלע אותו לתוכו. ושואל למה דוקא נחש, ומשיב, אמר לו הקב\"ה אתה הולך להרוג נחש גדול ותקיף, דהיינו התנין הגדול הרובץ תוך יאוריו, שהוא מלך מצרים. ובנך לא נמול. מיד נרמז לנחש אחד שיהרוג את משה."],[7,"עד דחמת וכו':","עד שראתה צפורה, ומלה את בנה. זהו שכתוב ותקח צפורה צור, מהו צור. אלא צור פירושו רפואה ומהו הרפואה. ותכרות ערלת בנה. כי נצנץ בה רוח הקדש, שעל ידי זה ינצל משה ממות."],[8,"קם אחרא ואמר וכו':","קם אחר ואמר. ויאמר יוסף אל אחיו גשו נא אלי ויגשו ויאמר וגו'. ושואל למה קרא אותם, הרי קרובים היו אליו. ומשיב, אלא בשעה שאמר להם, אני יוסף אחיכם. תמהו, כי ראוהו במלוכה עליונה. אמר להם יוסף, מלוכה זו משום זה, הרוחתי, היינו משום מצות המילה, גשו נא אלי, ויגשו, והראה אותם אות ברית המילה. אמר, זה גרם לי מלוכה הזו, משום ששמרתי אותה."],[9,"מכאן אוליפנא וכו':","מכאן למדנו, מי ששומר אות ברית הזה, מלוכה נשמרת לו. מאין לנו זה, מבועז. שכתוב חי ה' שכבי עד הבקר. כי היצר היה מסיתו עד שנשבע שבועה זו, חי ה' וגו', ושמר את הברית. משום זה זכה שיצאו ממנו מלכים ושליטים על המלכים, ומלך המשיח הנקרא בשם הקב\"ה. הרי ששומר בריתו מלטמא אותו, נשמרת לו מלוכה."],[10,"פתח אידך וכו':","פתח אחר ואמר. כתוב אם תחנה עלי מחנה וגו'. כך למדנו, בזאת אני בוטח. מהו \u0003בזאת,\u0004 ואומר שהוא אות הברית, המזומן תמיד באדם, ונרמז למעלה, דהיינו במלכות הנקראת זאת, ומשום זה נאמר \u0003בזאת,\u0004 כמו שכתוב זאת אות הברית, זאת בריתי, והכל במדרגה אחת. ולמדנו, זה וזאת במדרגה אחת הם ואינם נפרדים. פירוש, \u0003ברית,\u0004 הוא יסוד, הנקרא \u0003זה,\u0004 ואין המלכות נקראת \u0003זאת\u0004, אלא בשעה שמחוברת עם הברית במדרגה אחת, שהסו\"ה, זאת בריתי. ועליה אמר דוד \u0003בזאת\u0004 אני בוטח."],[11,"ואי תימא","וכו': ואם תאמר אם כן, גם שאר בני העולם כן כמו דוד, שיכולים לומר, בזאת אני בוטח. ולמה דוקא דוד לבדו אמר כן, ולא אחר. ומשיב, אלא משום שמדרגת \u0003זאת\u0004 נאחזת בדוד ונרמזת בו כלומר שהשם דוד מרמז על מלכות והיא כתר מלכות שלו."],[12,"ת\"ח בגין","וכו': בוא וראה. משום שדוד לא שמר כראוי \u0003זאת\u0004 זו, הוסרה ממנו המלכות כל אותו הזמן שלחם עם אבשלום בנו. וכך למדנו \u0003זאת\u0004 זו נרמזת במלכות שלמעלה, ונרמזה בירושלים עיר הקדש."]],[[0,"","חִכּוּ כָּל אוֹתוֹ הַיּוֹם. בְּאוֹתוֹ הַלַּיְלָה כִּנֵּס אוֹתוֹ הָאִישׁ אֶת כָּל אוֹהֲבָיו, וְכָל אוֹתוֹ הַלַּיְלָה הִתְעַסְּקוּ בַתּוֹרָה, וְלֹא הָיָה מִי שֶׁיָּשַׁן. אָמַר לָהֶם אוֹתוֹ הָאִישׁ, בְּבַקָּשָׁה מִכֶּם, כָּל אֶחָד וְאֶחָד יֹאמַר דָּבָר חָדָשׁ בַּתּוֹרָה."],[1,"","פָּתַח אֶחָד (רבי אבא) וְאָמַר, (שופטים ה) בִּפְרֹעַ פְּרָעוֹת בְּיִשְׂרָאֵל בְּהִתְנַדֵּב עָם בָּרְכוּ ה'. מָה רָאוּ דְבוֹרָה וּבָרָק שֶׁפָּתְחוּ בַּפָּסוּק הַזֶּה? אֶלָּא כָּךְ שָׁנִינוּ, אֵין הָעוֹלָם מִתְקַיֵּם אֶלָּא עַל הַבְּרִית הַזּוֹ, שֶׁכָּתוּב (ירמיה לג) אִם לֹא בְרִיתִי יוֹמָם וָלַיְלָה וְגוֹ'. שֶׁהֲרֵי שָׁמַיִם וָאָרֶץ עַל זֶה קַיָּמִים."],[2,"","מִשּׁוּם כָּךְ, כָּל זְמַן שֶׁיִּשְׂרָאֵל מְקַיְּמִים אֶת הַבְּרִית הַזּוֹ, חֻקּוֹת שָׁמַיִם וָאָרֶץ עוֹמְדִים בְּקִיּוּמָם. וְכָל זְמַן שֶׁחַס וְשָׁלוֹם מְבַטְּלִים אֶת הַבְּרִית הַזּוֹ, אֵין שָׁמַיִם וָאָרֶץ מִתְקַיְּמִים, וְאֵין נִמְצָאוֹת בְּרָכוֹת בָּעוֹלָם."],[3,"","בֹּא רְאֵה, לֹא שָׁלְטוּ שְׁאָר הָעַמִּים עַל יִשְׂרָאֵל אֶלָּא כְּשֶׁבִּטְּלוּ מֵהֶם אֶת הַבְּרִית הַזּוֹ. וּמַה בִּטְּלוּ מֵהֶם? שֶׁלֹּא נִפְרְעוּ וְלֹא נִתְגַּלּוּ. וְעַל זֶה כָּתוּב (שמואל א יב) וַיַּעַזְבוּ בְּנֵי יִשְׂרָאֵל אֶת ה' וְגוֹ' וַיִּמְכֹּר אֹתָם בְּיַד סִיסְרָא. וַיַּעַזְבוּ אֶת ה' מַמָּשׁ. עַד שֶׁבָּאָה דְבוֹרָה וְנִדְּבָה אֶת כָּל יִשְׂרָאֵל לַדָּבָר הַזֶּה, אָז נִכְנְעוּ שׂוֹנְאֵיהֶם תַּחְתֵּיהֶם."],[4,"","וְהַיְנוּ מַה שֶּׁשָּׁנִינוּ, שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לִיהוֹשֻׁעַ, וְכִי יִשְׂרָאֵל הֵם אֲטוּמִים וְלֹא נִפְרְעוּ וְלֹא הִתְגַּלּוּ וְלֹא מְקַיְּמִים אֶת בְּרִיתִי, וְאַתָּה רוֹצֶה לְהַכְנִיסָם לָאָרֶץ וּלְהַכְנִיעַ אֶת שׂוֹנְאֵיהֶם? (יהושע ה) שׁוּב מֹל אֶת בְּנֵי יִשְׂרָאֵל שֵׁנִית. וְעַד שֶׁנִּפְרְעוּ וְנִתְגַּלְּתָה הַבְּרִית הַזּוֹ, לֹא נִכְנְסוּ לָאָרֶץ וְלֹא נִכְנְעוּ שׂוֹנְאֵיהֶם. אַף כָּאן, כֵּיוָן שֶׁהִתְנַדְּבוּ יִשְׂרָאֵל בָּאוֹת הַזּוֹ, נִכְנְעוּ שׂוֹנְאֵיהֶם תַּחְתֵּיהֶם וְחָזְרוּ הַבְּרָכוֹת לָעוֹלָם. זֶהוּ שֶׁכָּתוּב בִּפְרֹעַ פְּרָעוֹת בְּיִשְׂרָאֵל בְּהִתְנַדֵּב עָם בָּרְכוּ ה'."],[5,"","קָם אַחֵר, פָּתַח וְאָמַר, (שמות ד) וַיְהִי בַדֶּרֶךְ בַּמָּלוֹן וַיִּפְגְּשֵׁהוּ ה' וַיְבַקֵּשׁ הֲמִיתוֹ. אֶת מִי? אֶת מֹשֶׁה. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכִי אַתָּה הוֹלֵךְ לְהוֹצִיא אֶת יִשְׂרָאֵל מִמִּצְרַיִם וּלְהַכְנִיעַ מֶלֶךְ גָּדוֹל וְשַׁלִּיט, וְאַתָּה שָׁכַחְתָּ מִמְּךְ אֶת הַבְּרִית, שֶׁבִּנְךְ לֹא נִמּוֹל? מִיָּד - וַיְבַקֵּשׁ הֲמִיתוֹ."],[6,"","לָמַדְנוּ, יָרַד גַּבְרִיאֵל בְּשַׁלְהֶבֶת שֶׁל אֵשׁ לִשְׂרֹף אוֹתוֹ, וְנִרְמַז לְנָחָשׁ אֶחָד שׂוֹרֵף לִשְׁאֹף אוֹתוֹ לְתוֹכוֹ. לָמָּה נָחָשׁ? אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, אַתָּה הוֹלֵךְ לַהֲרֹג אֶת הַנָּחָשׁ הַגָּדוֹל וְהֶחָזָק, וּבִנְךְ לֹא נִמּוֹל!? מִיָּד נִרְמַז לְנָחָשׁ אֶחָד לַהֲרֹג אוֹתוֹ,"],[7,"","עַד שֶׁרָאֲתָה צִפּוֹרָה וּמָלָה אֶת בְּנָהּ וְנִצּוֹל. זֶהוּ שֶׁכָּתוּב וַתִּקַּח צִפּוֹרָה צֹר. מַה זֶּה צֹר? אֶלָּא רְפוּאָה. וּמָה הָרְפוּאָה? שֶׁכָּתוּב וַתִּכְרֹת אֶת עָרְלַת בְּנָהּ. שֶׁנִּצְנְצָה בָּהּ רוּחַ הַקֹּדֶשׁ."],[8,"","קָם אַחֵר וְאָמַר, (בראשית מה) וַיֹּאמֶר יוֹסֵף אֶל אֶחָיו גְּשׁוּ נָא אֵלַי וַיִּגָּשׁוּ וַיֹּאמֶר וְגוֹ'. וְכִי לָמָּה קָרָא לָהֶם, וַהֲרֵי הֵם הָיוּ קְרוֹבִים אֵלָיו? אֶלָּא בְּשָׁעָה שֶׁאָמַר לָהֶם אֲנִי יוֹסֵף אֲחִיכֶם, תָּמְהוּ שֶׁרָאוּ אוֹתוֹ בְּמַלְכוּת עֶלְיוֹנָה. אָמַר יוֹסֵף, הַמַּלְכוּת הַזּוֹ, מִשּׁוּם זֶה הִרְוַחְתִּי אוֹתָהּ. גְּשׁוּ נָא אֵלַי וַיִּגָּשׁוּ, שֶׁהֶרְאָה לָהֶם אֶת בְּרִית הַמִּילָה. אָמַר, זוֹ גָרְמָה לִי אֶת הַמַּלְכוּת הַזּוֹ, מִשּׁוּם שֶׁשָּׁמַרְתִּי אוֹתָהּ."],[9,"","מִכָּאן לָמַדְנוּ, שֶׁמִּי שֶׁשּׁוֹמֵר אֶת אוֹת הַבְּרִית הַזּוֹ, הַמַּלְכוּת שְׁמוּרָה לוֹ. מִנַּיִן לָנוּ? מִבֹּעַז, שֶׁכָּתוּב (רות ג) חַי ה' שִׁכְבִי עַד הַבֹּקֶר. שֶׁיִּצְרוֹ הָיָה מִתְגָּרֶה בּוֹ, עַד שֶׁנִּשְׁבַּע שְׁבוּעָה וְשָׁמַר אֶת הַבְּרִית הַזּוֹ, מִשּׁוּם כָּךְ זָכָה שֶׁיָּצְאוּ מִמֶּנּוּ מְלָכִים שַׁלִּיטִים עַל כָּל שְׁאָר הַמְּלָכִים, וְהַמֶּלֶךְ הַמָּשִׁיחַ שֶׁנִּקְרָא בִּשְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא."],[10,"","פָּתַח אַחֵר וְאָמַר, כָּתוּב (תהלים כז) אִם תַּחֲנֶה עָלַי מַחֲנֶה וְגוֹ'. כָּךְ שָׁנִינוּ, בְּזאת אֲנִי בוֹטֵחַ, מַה זֶּה בְּזאת? זוֹ אוֹת הַבְּרִית הַמְזֻמֶּנֶת תָּמִיד אֵצֶל אָדָם, וְנִרְמְזָה לְמַעְלָה. וּמִשּׁוּם כָּךְ נֶאֱמַר בְּזֹאת, כְּמוֹ שֶׁכָּתוּב זֹאת אוֹת הַבְּרִית, זאת בְּרִיתִי, וְהַכֹּל בְּדַרְגָּה אַחַת. וְשָׁנִינוּ, זֶה וְזאת הֵם בְּדַרְגָּה אַחַת וְלֹא נִפְרָדִים."],[11,"","וְאִם תֹּאמַר, אִם כָּךְ, הֲרֵי שְׁאָר בְּנֵי הָאָדָם כָּךְ, לָמָּה דָוִד בִּלְבַדּוֹ וְלֹא אַחֵר? אֶלָּא מִשּׁוּם שֶׁהִיא אֲחוּזָה בּוֹ וְנִרְמְזָה בּוֹ, וְהִיא כֶּתֶר הַמַּלְכוּת."],[12,"","בֹּא רְאֵה, מִשּׁוּם שֶׁאֶת הַ את הַזּוֹ לֹא שָׁמַר אוֹתָהּ דָּוִד הַמֶּלֶךְ כָּרָאוּי, הַמַּלְכוּת הָעָבְרָה מִמֶּנּוּ כָּל אוֹתוֹ הַזְּמַן. וְכָךְ לָמַדְנוּ, הַ את הַזּוֹ נִרְמְזָה בַּמַּלְכוּת שֶׁלְּמַעְלָה, וְנִרְמְזָה בִּירוּשָׁלַיִם, הַקִּרְיָה הַקְּדוֹשָׁה."]]],[["בְּהַהוּא שַׁעֲתָא דְּדָוִד עֲבַר עֲלֵיהּ, נָפַק קָלָא וְאָמַר דָּוִד בַּמֶּה דְּאִתְקַטְרַת תִּשְׁתְּרֵי. לָךְ טַרְדִּין מִיְרוּשָׁלַ ם וּמַלְכוּתָא אִתְעֲדֵי מִינָךְ. מְנָא לָן דִּכְתִיב, (שמואל ב י״ב:י״א) הִנְנִי מֵקִים עָלֶיךָ רָעָה מִבֵּיתְךָ. מִבֵּיתְךָ דַּיְיקָא וְהָכִי הֲוָה בְּמָּה דְּעֲבַר בֵּיהּ אִתְעַנַּשׁ, וּמַה דָּוִד מַלְכָּא הָכִי שְׁאָר בְּנֵי עָלְמָא עַל אַחַת כַּמָּה וְכַמָּה.","פָּתַח אִידָךְ וְאָמַר (תהילים צ״ד:י״ז) לוּלֵי יְיָ עֶזְרָתָה לִי כִּמְעַט שָׁכְנָה דּוּמָה נַפְשִׁי. תָּאנָא בַּמֶּה זָכָאן יִשְׂרָאֵל דְּלָא נָחֲתֵי לַגֵּיהִנֹּם כִּשְׁאָר עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת וְלָא אִתְמַסְרָן בִּידוֹי דְּדוּמָה, (אלא) בְּהַאי אָת.","דְּהָכִי תָאנָא בְּשַׁעֲתָא דְּבַּר נָשׁ נָפִיק מֵעָלְמָא כַּמָּה חֲבִילֵי (מלאכי חבלה) טְהִירִין אִתְפַּקְדָּן עֲלֵיהּ. זְקִפִין עֵינָא וְחָמָאן הַאי אָת דְּהוּא קְיָימָא דְּקוּדְשָׁא, אִתְפָּרְשָׁן מִנֵּיהּ, וְלָא אִתְיְיהִיב בִּידוֹי דְּדוּמָה לְנַחֲתָא לַגֵּיהִנֹּם, דְּכָל מַאן דְּאִתְמָסַר בִּידוֹי נָחִית לַגֵּיהִנֹּם וַדַּאי,","וּמֵהַאי אָת דָּחֲלִין עִלָּאִין וְתַתָּאִין, וְדִינִין בִּישִׁין לָא שָׁלְטִין בֵּיהּ בַּבַּר נָשׁ אִי אִיהוּ זָכִי לִנְטוּרֵי לֵיהּ לְהַאי אָת, בְּגִין דְּהוּא אִתְאַחִיד בִּשְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא.","כֵּיוָן דְּדָוִד מַלְכָּא לָא נָטַר אָת קְיָימָא דָא כְּדְקָא חָזֵי, אִתְעַדֵּי מִנֵּיהּ מַלְכוּתָא וְאִתְטְרִיד מִיְרוּשָׁלַם. מִיָּד דָּחִיל דְסָבַר דְּיֵיחֲתוּן לֵיהּ מִיָּד וְיִמְסְרוּן לֵיהּ בִּידוֹי דְדוּמָה וְיָמוּת בְּהַהוּא עָלְמָא, עַד דְּאִתְבַּשַּׂר בֵּיהּ דִּכְתִיב, (שמואל ב י״ב:י״ג) גַּם יְיָ הֶעֱבִיר חַטָּאתְךָ לֹא תָמוּת. בֵּיהּ שַׁעֲתָא פָּתַח וְאָמַר לוּלֵי יְיָ עֶזְרָתָה לִי כִּמְעַט שָׁכְנָה דוּמָ\"ה נַפְשִׁי.","פָּתַח אִידָךְ וְאָמַר מַאי הַאי (דכתיב) דְּאָמַר דָּוִד וְהַרְאֵנִי אוֹתוֹ וְאֶת נָוִהוּ. (מאי והראני אותו ואחר כך ואת נוהו), מַאן יָכִיל לְמֶחמֵי לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא. אֶלָּא הָכִי תָּנִינָן בְּהַהִיא שַׁעֲתָא דְּאִתְגְּזַר עֲלֵיהּ הַהוּא עוֹנָשָׁא, וְדָוִד יָדַע דְּעַל דְּלָא נָטַר הַאי אָת כְּדְקָא יְאוּת אִתְעַנַּשׁ בְּהַאי, דְּכֹלָּא כְּחֲדָא אֲחִידָא, וְכֹלָּא מִתְרְמִיז בְּהַאי אָת, וְלָא אִקְרֵי צַדִּיק מַאן דְּלָא נָטַר לֵיהּ כְּדְקָא יְאוּת, הֲוָה בָּעֵי בְּעוּתֵיהּ וְאָמַר (שמואל ב ט״ו:כ״ה) וְהַרְאֵנִי אוֹתוֹ וְאֶת נָוִהוּ.","מַאי אוֹתוֹ, (אות דיליה אות הברית דהא אותו דקודשא בריך הוא, את דיליה) דָּא אָת קְיָימָא (דיליה) קַדִּישָׁא דְּהָא דָּחִילְנָא דְּאִתְאֲבִיד מִנָּאי. מַאי טַעְמָא בְּגִין דִּתְרֵין אִלֵּין מַלְכוּתָא וִיְרוּשָׁלַ ם בְּהַאי אֲחִידָן, וּבְגִין כָּךְ תָּלֵי בְּבָעוּתֵיהּ אוֹתוֹ וְאֶת נָוֵהוּ דְּיִתְהַדַּר מַלְכוּתָא דְּהַאי אָת לְאַתְרֵיהּ. וְכֹלָּא חַד מִלָּה.","פָּתַח אִידָךְ וְאָמַר (איוב י״ט:כ״ו) וּמִבְּשָׂרִי אֶחזֶה אֱלוֹהַּ, מַאי וּמִבְּשָׂרִי, וּמֵעַצְמִי מִבָּעֵי לֵיהּ. אֶלָּא מִבְּשָׂרִי מַמָּשׁ. וּמַאי הִיא. דִּכְתִיב, (ירמיהו י״א:ט״ו) וּבְשַׂר קֹדֶשׁ יַעַבְרוּ מֵעָלָיִךְ. וּכְתִיב (בראשית י״ז:י״ג) וְהָיְתָה בְּרִיתִי בִּבְשַׂרְכֶם. דְּתַנְיָא בְּכָל זִמְנָא דְּאִתְרְשִׁים בַּר נָשׁ בְּהַאי רְשִׁימָא קַדִּישָׁא דְּהַאי אָת, מִנֵּיהּ חָמֵי לְקוּדְשָׁא בְּרִיךְ הוּא. מִנֵּיהּ מַמָּשׁ. וְנִשְׁמְתָא קַדִּישָׁא אִתְאֲחִידַת בֵּיהּ.","וְאִי לָא זָכֵי. דְּלָא נָטִיר הַאי אָת. מַה כְּתִיב, (איוב ד׳:ט׳) מִנִּשְׁמַת אֱלוֹהַּ יֹאבֵדוּ. דְּהָא רְשִׁימוּ דְּקוּדְשָׁא בְּרִיךְ הוּא לָא אִתְנְטִיר. וְאִי זָכֵי וְנָטִיר לֵיהּ, שְׁכִינְתָּא לָא אִתְפְּרַשׁ מִנֵּיהּ.","אֵימָתַי מִתְקָיְימָא בֵּיהּ כַּד אִתְנְסִיב וְהַאי אָת עָיִיל בְּאַתְרֵיהּ, (מצוין דתניא מאי טעמא וא\"ו ה\"א אזלין כחדא, אלא חד דכר וחד נוקבא) אִשְׁתַּתָּפוּ כַּחֲדָא וְאִקְרֵי חַד שְׁמָא, כְּדֵין חֶסֶד עִלָּאָה שַׁרְיָיא עֲלַיְיהוּ. בְּאָן אֲתַר שַׁרְיָא בְּסִטְרָא דִּדְכוּרָא. וּמַאן חֶסֶ\"ד חֶסֶ\"ד אֵ\"ל דְּאָתֵי וְנָפַק מֵחָכְמָה עִלָּאָה וְאִתְעַטַּר בִּדְכוּרָא וּבְגִין כָּךְ אִתְבַּסְמַת נוּקְבָא. (נ\"א דתנן רזא דוי\"ו ה\"א אזלין כחדא כגוונא דדכר ונוקבא אשתתפו כחדא ואנון חד, כדין חסד עלאה שרייא עלייהו ואתעטר בדכורא ואתבסמת נוקבא).","תוּ תָּנִינָן אֱלוֹהַ הָכִי הוּא אָמַר לֵיהּ נְהִירוּ דְּחָכְמְתָא. ו' דְּכַר ה' נוּקְבָא. אִשְׁתַּתָּפוּ כְּחֲדָא אֱלוֹהַּ אִקְרֵי. וְנִשְׁמְתָא קַדִּישָׁא מֵהַאי אֲתַר אִתְאַחְדַת, וְכֹלָּא תַּלְיָא בְּהַאי אָת.","וְעַל דָּא כְּתִיב וּמִבְּשָׂרִי אֶחֱזֶה אֱלוֹהַּ. דָּא שְׁלֵימוּתָא דְּכֹלָּא, מִבְּשָׂרִי מַמָּשׁ, מֵהַאי אָת מַמָּשׁ, וְעַל דָּא זַכָּאִין אִנּוּן יִשְׂרָאֵל קַדִּישִׁין דְּאֲחִידָן בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, זַכָּאִין אִנּוּן בְּעָלְמָא דֵּין וּבְעָלְמָא דְאָתֵי, עֲלַיְיהוּ כְּתִיב, (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּיְיָ וְגו', וּבְגִין כָּךְ חַיִּים כֻּלְּכֶם הַיּוֹם.","אָמַר רַבִּי אַבָּא וּמַה בְּכָל כָּךְ אַתּוּן חַכִּימִין וְאַתּוּן יָתְבִין הָכָא, אָמְרוּ לֵיהּ אִי צִפּוֹרָאָה יִתְעַקְרוּ מֵאַתְרַיְיהוּ לָא יָדְעִין לְאָן טָאסָן הֲדָא הוּא דִכְתִיב, (משלי כ״ז:ח׳) כְּצִפּוֹר נוֹדֶדֶת מִן קִנָּהּ כֵּן אִישׁ נוֹדֵד מִמְקוֹמוֹ."],[[0,"בההוא שעתא","וכו': בשעה זו שדוד עבר עליה דהיינו במעשה דבת שבע, יצא קול ואמר: דוד במה שנקשרת, דהיינו \u0003בזאת\u0004 הנרמזת במלכות ונרמזת בירושלים, הותרת, שיגרשו אותך מירושלים והמלכות תסיר ממך. מאין לנו זה, שכתוב, הנני מקים עליך רעה מביתך, מביתך הוא בדיוק, דהיינו בית שלו ממש, שה\"ס הנוקבא הנקראת \u0003זאת.\u0004 והרעה שאומה\"כ הוא שיפרד ממנה. וכן היה, במה שעבר, בו נענש, כנ\"ל משום שלא שמר מדרגת \u0003זאת\u0004 שה\"ס הברית ע\"כ נפרד ממנה. ומה דוד המלך כך, שאר בני העולם על אחת כמה וכמה."],[1,"פתח אידך ואמר וכו':","פתח אחר ואמר לולי ה' עזרתה לי כמעט שכנה דומה נפשי. תאנא, במה זכו ישראל שאינם יורדים לגיהנם כמו שאר האומות, עובדי ע\"ז. ולא נמסרו בידיו של דומה, שהוא שרו של גיהנם. ואומר, באות ברית זה, זכו כל כך."],[2,"דהכי תאנא וכו':","כי כך למדנו, בשעה שהאדם נפטר מן העולם, כמה חבילות קליפות נפקדים עליו להזיקו, כשנושאים עיניהם ורואים אות זה, שהוא ברית קדש. נפרדים ממנו. ואינו ניתן בידיו של המלאך דומה, לירד לגיהנם כי כל מי שנמסר בידיו הוא יורד ודאי לגיהנם."],[3,"ומהאי את","וכו': ומאות הזה, יראים העליונים ותחתונים. ודינים רעים אינם שולטים על האדם, אם הוא זוכה לשמור אות הזה. משום שנתאחד על ידי זה, בשמו של הקב\"ה."],[4,"כיון דדוד וכו':","אחר שדוד המלך לא שמר אות ברית הזה, וניטל ממנו המלכות ונגרש מירושלים, היה מפחד, שחשב שיורידו אותו מיד וימסרו אותו ביד דומה, וימות בעולם האמת. כלומר שלא יזכה לחיים הרוחנים עד שנתבשר, שכתוב, גם ה' העביר חטאתך לא תמות, בה בשעה פתח ואמר, לולי ה' עזרתה לי כמעט שכנה \u0003דומה\u0004 נפשי, דהיינו שהיה נמסר בידיו של המלאך דומה כנ\"ל."],[5,"פתח אידך ואמר וכו':","פתח אחר ואמר, מה זה שאמר דוד, והראני אותו ואת נוהו, מי יכול לראות את הקב\"ה. ומשיב, אלא כך למדנו. באותה שעה שנגזר עליו אותו העונש מאבשלום, ודוד ידע, שמשום שלא שמר אות הזה כראוי, דהיינו במעשה דבת שבע, נענש בזה, שהוסר ממלכותו כי הכל מיוחד כאחד, והכל נרמז ב \u0003אות\u0004 הזה. דהיינו מלכות שלמעלה וירושלים (כנ\"ל באות ת\"ג) ואינו נקרא צדיק מי שלא שמר \u0003אות\u0004 הזה כראוי, לכן היה מתפלל תפלתו, ואמר והראני אותו ואת נוהו."],[6,"מאי וכו':","מהו \u0003אותו.\u0004 זה הוא \u0003אות\u0004 ברית קודש, שהרי אני מתירא שנאבד ממני. מהו הטעם, שחשב שנאבד ממנו אות ברית, הוא משום ששנים אלו, המלכות וירושלים, נאחזים באות ברית וכיון שאבד המלכות ונגרש מירושלים, חשב שגם אות הברית נאבד ממנו. ומשום זה קשר בתפילתו, \u0003אותו ואת נוהו,\u0004 יחד, שאותו הוא אות ברית, ונוהו הוא המלכות. שהתפלל שתחזור המלכות, הקשורה ב \u0003אות\u0004 הזה, למקומו והכל ענין אחד."],[7,"פתח אידך וכו':","פתח אחר ואמר. ומבשרי אחזה אלוה. ושואל, מהו מבשרי, ומעצמי היה צריך לומר. ומשיב, אלא מבשרי ממש, דהיינו יסוד הנקרא בשר, אמר \u0003אחזה אלוה,\u0004 ומה הוא שכתוב ובשר קדש יעברו מעליך שה\"ס ברית קדש. וכתוב והיתה בריתי בבשרכם שפירושו יסוד. כי למדנו. בכל זמן שהאדם נרשם ברשימה הקדושה הזו של אות הזה, כלומר, שאות הברית נרשם בו עד כדי לשמרו תמיד, רואה מתוכו את הקב\"ה ממנו ממש, והנשמה הקדושה נאחזת בו, באות ברית."],[8,"ואי לא זכי וכו':","ואם לא זכה, שלא שמר אות הזה, מה כתוב עליו, מנשמת אלוה יאבדו. כי רשימו של הקב\"ה לא נשמר. ואם זוכה ושומר אותו, השכינה אינה נפרדת ממנו לעולם."],[9,"אימתי מתקיימא וכו':","ושואל, מתי מתקיימת בו השכינה, ואומר, כשהוא נושא אשה. ואות הזה נכנס במקומו, בהשכינה, הם משתתפים יחד, הזכר והנקבה שהם אות ברית והשכינה, ונקראים בשם אחד, כמו שיתבאר להלן, ואז חסד עליון שורה עליהם. באיזה מקום שורה החסד. הוא שורה בצד הזכר. ומי הוא החסד, הוא חסד שבשם \u0003אל,\u0004 הבא ויוצא מחכמה עליונה, ומתעטר בזכר, ועל ידי אלו החסדים נמתקת הנוקבא."],[10,"תו תנינן וכו':","עוד למדנו הוא הפירוש על דיבור הקודם, השם \u0003אלוה\u0004 כך הוא פירושו. \u0003אל\u0004 שבו, הוא הארת החכמה. \u0003ו'\u0004 הוא זכר, \u0003ה'\u0004 נקבה נשתתפו זכר ונקבה יחד, כנ\"ל בדיבור הסמוך, נקראים שם אחד \u0003אלוה.\u0004 אשר \u0003אל\u0004 הוא הארת החכמה. \u0003ו'\u0004 הוא זכר. \u0003ה'\u0004 היא הנקבה. והנשמה הקדושה ממקום זה נאחזת, והכל תלוי באות ברית הזה."],[11,"ועל דא כתיב וכו':","וע\"כ כתוב ומבשרי אחזה אלוה, דהיינו השם \u0003אלוה,\u0004 כנ\"ל בדבור הסמוך, זהו שלמות כל, מבשרי ממש, דהיינו היסוד הנקרא בשר, מאות ברית ממש, ועל כן אשריהם ישראל הקדושים, שמתאחדים בהקב\"ה אשריהם בעולם הזה ובעולם הבא. עליהם כתוב ואתם הדבקים בה' וגו' ומשום זה חיים כלכם היום."],[12,"א\"ר אבא וכו':","אר\"א ומה אתם כל כך חכמים, ואתם יושבים כאן. אמרו לו אם צפורים יתעקרו ממקומם לא ידעו אנה יעופו. ז\"ש כצפור נודדת מן קנה כן איש נודד ממקומו."]],[[0,"","בְּאוֹתָהּ הַשָּׁעָה שֶׁדָּוִד עָבַר עָלֶיהָ, יָצָא קוֹל וְאָמַר: דָּוִד, בְּמַה שֶּׁנִּקְשַׁרְתָּ תִּוָּתֵר. אוֹתְךְ טוֹרְדִים מִירוּשָׁלַיִם, וְהַמַּלְכוּת תּוּסַר מִמְּךְ. מִנַּיִן לָנוּ? שֶׁכָּתוּב (שמואל ב יב) הִנְנִי מֵקִים עָלֶיךְ רָעָה מִבֵּיתְךְ. מִבֵּיתְךְ בִּמְדֻיָּק. וְכָךְ הָיָה. בְּמַה שֶּׁעָבַר עָלָיו נֶעֱנַשׁ. וּמַה דָּוִד הַמֶּלֶךְ כָּךְ - שְׁאָר בְּנֵי הָעוֹלָם עַל אַחַת כַּמָּה וְכַמָּה."],[1,"","פָּתַח אַחֵר וְאָמַר, (תהים צד) לוּלֵי ה' עֶזְרָתָה לִּי כִּמְעַט שָׁכְנָה דוּמָה נַפְשִׁי. לָמַדְנוּ, בַּמֶּה זוֹכִים יִשְׂרָאֵל שֶׁאֵינָם יוֹרְדִים לַגֵּיהִנֹּם כְּמוֹ שְׁאָר הָעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה, וְאֵין נִמְסָרִים בִּידֵי דוּמָה? (אלא) בָּאוֹת הַזּוֹ."],[2,"","שֶׁכָּךָ לָמַדְנוּ, בְּשָׁעָה שֶׁאָדָם יוֹצֵא מִן הָעוֹלָם הַזֶּה, כַּמָּה קְבוּצוֹת שֶׁל (מלאכי חבלה) מְחַבְּלִים נִפְקָדִים עָלָיו. מְרִימִים עֵינַיִם וְרוֹאִים אֶת הָאוֹת הַזּוֹ, שֶׁהִיא בְּרִית הַקֹּדֶשׁ, וְנִפְרָדִים מִמֶּנּוּ, וְאֵינוֹ נִתָּן בִּידֵי דוּמָה לָרֶדֶת לַגֵּיהִנֹּם. שֶׁכָּל מִי שֶׁנִּמְסָר בְּיָדוֹ, וַדַּאי יוֹרֵד לַגֵּיהִנֹּם."],[3,"","וּמֵהָאוֹת הַזּוֹ פּוֹחֲדִים עֶלְיוֹנִים וְתַחְתּוֹנִים, וְהַדִּינִים הָרָעִים אֵין שׁוֹלְטִים בּוֹ בָּאָדָם אִם הוּא זוֹכֶה לִשְׁמֹר אֶת הַבְּרִית הַזּוֹ, מִשּׁוּם שֶׁהוּא נֶאֱחָז בִּשְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא."],[4,"","כֵּיוָן שֶׁדָּוִד הַמֶּלֶךְ לֹא שָׁמַר אֶת אוֹת הַבְּרִית הַזּוֹ כָּרָאוּי, הָעָבְרָה מִמֶּנּוּ הַמַּלְכוּת, וְנִטְרַד מִירוּשָׁלַיִם. מִיָּד פָּחַד, כִּי סָבַר שֶׁיּוֹרִידוּ אוֹתוֹ מִיָּד, וְיִמְסְרוּ אוֹתוֹ בְּיַד דּוּמָה וְיָמוּת בָּעוֹלָם הַהוּא, עַד שֶׁהִתְבַּשֵּׂר עָלָיו, שֶׁכָּתוּב (שמואל ב ב) גַּם ה' הֶעֱבִיר חַטָּאתְךְ לֹא תָמוּת. בְּאוֹתָהּ הַשָּׁעָה פָּתַח וְאָמַר, לוּלֵי ה' עֶזְרָתָה לִּי כִּמְעַט שָׁכְנָה דוּמָה נַפְשִׁי."],[5,"","פָּתַח אַחֵר וְאָמַר, מַה זֶּה (שכתוב) שֶׁאָמַר דָּוִד (שם טו) וְהִרְאַנִי אֹתוֹ וְאֶת נָוֵהוּ? (מהו והראני אתו ואחר כך ואת נוהו)? מִי יָכוֹל לִרְאוֹת אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא? אֶלָּא כָּךְ שָׁנִינוּ, בַּשָּׁעָה הַהִיא שֶׁגָּזַר עָלָיו אוֹתוֹ הָעֹנֶשׁ, וְדָוִד יָדַע שֶׁעַל שֶׁלֹּא שָׁמַר הָאוֹת הַזּוֹ כָּרָאוּי נֶעֱנָשׁ בָּזֶה, שֶׁהַכֹּל יַחַד אָחוּז, וְהַכֹּל נִרְמָז בָּאוֹת הַזּוֹ, וְלֹא נִקְרָא צַדִּיק מִי שֶׁאֵינוֹ שׁוֹמֵר אוֹתוֹ כָּרָאוּי - הָיָה מְבַקֵּשׁ בַּקָּשָׁתוֹ וְאוֹמֵר, וְהִרְאַנִי אֹתוֹ וְאֶת נָוֵהוּ."],[6,"","מַה זֶּה אֹתוֹ? (האות שלו, אות הברית, שהרי אותו של הקב\"ה האות שלו) זוֹ אוֹת הַבְּרִית (שלו) הַקְּדוֹשָׁה, שֶׁהֲרֵי אֲנִי פּוֹחֵד שֶׁאָבְדָה מִמֶּנִּי. מָה הַטַּעַם? מִשּׁוּם שֶׁשְּׁנֵי אֵלּוּ - הַמַּלְכוּת וִירוּשָׁלַיִם - אֲחוּזוֹת בָּזֶה. וּמִשּׁוּם כָּךְ תָּלָה בְּבַקָּשָׁתוֹ אֹתוֹ וְאֶת נָוֵהוּ, שֶׁתַּחֲזֹר הַמַּלְכוּת שֶׁל הָאוֹת הַזּוֹ לִמְקוֹמָהּ, וְהַכֹּל דָּבָר אֶחָד."],[7,"","פָּתַח אַחֵר וְאָמַר, (איוב יט) וּמִבְּשָׂרִי אֶחֱזֶה אֱלוֹהַּ. מַה זֶּה וּמִבְּשָׂרִי? הָיָה צָרִיךְ לִהְיוֹת וּמֵעַצְמִי! אֶלָּא מִבְּשָׂרִי מַמָּשׁ, וּמַה הִיא? שֶׁכָּתוּב (ירמיה יא) וּבְשַׂר קֹדֶשׁ יַעַבְרוּ מֵעָלָיִךְ, וְכָתוּב (בראשית יז) וְהָיְתָה בְרִיתִי בִּבְשַׂרְכֶם. שֶׁשָּׁנִינוּ, בְּכָל זְמַן שֶׁנִּרְשָׁם אָדָם בָּרֹשֶׁם הַקָּדוֹשׁ שֶׁל הָאוֹת הַזּוֹ, מִמֶּנָּה רוֹאֶה אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, מִמֶּנּוּ מַמָּשׁ, וְהַנְּשָׁמָה הַקְּדוֹשָׁה נֶאֱחֶזֶת בּוֹ."],[8,"","וְאִם לֹא זוֹכֶה, שֶׁאֵינוֹ שׁוֹמֵר אֶת הָאוֹת הַזּוֹ, מַה כָּתוּב? (איוב ד) מִנִּשְׁמַת אֱלוֹהַּ יֹאבֵדוּ, שֶׁהֲרֵי הָרֹשֶׁם שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא נִשְׁמָר. וְאִם זוֹכֶה וְשׁוֹמֵר אוֹתוֹ, אֵין הַשְּׁכִינָה נִפְרֶדֶת מִמֶּנּוּ."],[9,"","מָתַי מִתְקַיֵּם בּוֹ? כַּאֲשֶׁר הוּא נִשָּׂא, וְהָאוֹת הַזּוֹ נִכְנֶסֶת לִמְקוֹמָהּ (ששנינו, מה הטעם וא\"ו ה\"א הולכות יחד? אלא אחת זכר ואחת נקבה). מִשְׁתַּתְּפִים יַחַד, וְנִקְרָא שֵׁם אֶחָד, אָז שׁוֹרֶה עֲלֵיהֶם הַחֶסֶד הָעֶלְיוֹן. בְּאֵיזֶה מָקוֹם שׁוֹרֶה? בְּצַד הַזָּכָר. וּמִי הַחֶסֶד? חֶסֶ\"ד אֵ\"ל שֶׁבָּא וְיוֹצֵא מֵהַחָכְמָה הָעֶלְיוֹנָה וּמִתְעַטֵּר בַּזָּכָר. וּמִשּׁוּם כָּךְ נִתְבַּשֶּׂמֶת הַנְּקֵבָה. (נ\"א: ששנינו, הסוד של וי\"ו ה\"א הולכים יחד כמו שזכר ונקבה משתתפים יחד והם אחד, אז שורה עליהם החסד העליון, ומתעטר בזכר ונתבשמת הנקבה)."],[10,"","עוֹד שָׁנִינוּ, אֱלוֹהַּ כָּךְ הוּא. א\"ל, אוֹר הַחָכְמָה. ו' זָכָר, ה' נְקֵבָה. כְּשֶׁמִּשְׁתַּתְּפִים יַחַד נִקְרָא אֱלוֹהַּ. וְהַנְּשָׁמָה הַקְּדוֹשָׁה מֵהַמָּקוֹם הַזֶּה נֶאֱחֶזֶת, וְהַכֹּל תָּלוּי בָּאוֹת הַזּוֹ,"],[11,"","וְעַל כֵּן כָּתוּב וּמִבְּשָׂרִי אֶחֱזֶה אֱלוֹהַּ. זוֹ הִיא שְׁלֵמוּת הַכֹּל, מִבְּשָׂרִי מַמָּשׁ, מֵהָאוֹת הַזּוֹ מַמָּשׁ. וְעַל כֵּן אַשְׁרֵיהֶם יִשְׂרָאֵל קְדוֹשִׁים שֶׁאֲחוּזִים בַּקָּדוֹשׁ בָּרוּךְ הוּא, אַשְׁרֵיהֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, עֲלֵיהֶם כָּתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' וְגוֹ', וּמִשּׁוּם כָּךְ חַיִּים כֻּלְּכֶם הַיּוֹם."],[12,"","אָמַר רַבִּי אַבָּא, וּמַה בְּכָל כָּךְ אַתֶּם חֲכָמִים, וְאַתֶּם יוֹשְׁבִים כָּאן? אָמְרוּ לוֹ, אִם הַצִּפֳּרִים יַעַקְרוּ מִמְּקוֹמָם, לֹא יוֹדְעִים לְאָן טָסוֹת. זֶהוּ שֶׁכָּתוּב (משלי כז) כְּצִפּוֹר נוֹדֶדֶת מִן קִנָּהּ כֵּן אִישׁ נוֹדֵד מִמְּקוֹמוֹ."]]],[["וְאַתְרָא דָא זָכֵי לָן לְאוֹרַיְיתָא, וְהַאי אוֹרְחָא דִילָן. בְּכָל לֵילְיָא פַּלְגוּתָא אֲנַן נָיְימִין, וּפַלְגוּתָא אֲנַן עָסְקִין בְּאוֹרַיְיתָא. וְכַד אֲנַן קָיְימִין בְּצַפְרָא רֵיחֵי חַקְלָא וְנַהֲרֵי מַיָא, נְהָרִין לָן אוֹרַיְיתָא, וְאִתְיַישַּׁבְתָּ בְּלִבָּן.","הָא דַּיְינוּהָ לְעֵילָא זִמְנָא חָדָא. וְכַמָּה סָרְכֵי תְּרִיסִין אִסְתַּלָּקוּ בְּהַהוּא דִינָא עַל עוֹנְשָׁא (עה, קא ב) דְאוֹרַיְיתָא, וּכְדֵין אִשְׁתַּדְּלוּתָא דִילָן יְמָמָא וְלֵילְיָא בְּאוֹרַיְיתָא הוּא, וְאַתְרָא דָא קָא מְסַיְיעָא לָן, וּמַאן דְּאִתְפְּרַשׁ מִכָּאן, כְּמַאן דְּאִתְפְּרַשׁ מֵחַיֵּי עָלְמָא.","זָקִיף יְדוֹי רַבִּי אַבָּא וּבָרִיךְ לוֹן. יָתְבוּ עַד דְּנָהַר יְמָמָא. בָּתַר דְּנָהַר יְמָמָא אָמְרוּ לְאִנּוּן דַּרְדְּקֵי דְּקָמַיְיהוּ פּוּקוּ וְחֲמוּ אִי נָהַר יְמָמָא, וְכָל חַד לֵימָא מִלָּה חַדְתָּא דְאוֹרַיְיתָא לְהַאי גַּבְרָא רַבָּא.","נָפְקוּ וְחָמוּ דְּנָהַר יְמָמָא. אָמַר חַד מִנַּיְיהוּ זַמִּין הַאי יוֹמָא אֶשָׁא מִלְּעֵילָא. אָמַר אָחֳרָא וּבְהַךְ בֵּיתָא. אָמַר אָחֳרָא חַד סָבָא הָכָא דְּזַמִּין הַאי יוֹמָא לְאִתּוֹקְדָא בְּנוּרָא דָא, אָמַר רַבִּי אַבָּא רַחֲמָנָא לִישֵׁזְבָן.","תָּוָוה וְלָא יָכִיל לְמַלָּלָא, אָמַר קוּטְרָא דְהוּרְמָנָא בְּאַרְעָא אִתַּפְסַת. וְכָךְ הֲוָה, דְּהַהוּא יוֹמָא חָמוּ חַבְרַיָיא אַפֵּי שְׁכִינְתָּא וְאִסְתַּחֲרוּ בְּאֶשָׁא. וְרַבִּי אַבָּא אִתְלַהִיטוּ אַנְפּוֹי כְּנוּרָא מֵחֶדְוָותָא דְאוֹרַיְיתָא.","תָּאנָא כָּל הַהוּא יוֹמָא לָא נָפְקוּ כֻּלְהוּ מִבֵּיתָא וּבֵיתָא אִתְקַטַּר בְּקִיטְרָא, וְהֲווּ חַדְתָאן מִלֵּי בְּגַוַויְיהוּ, כְּאִלּוּ קִבְּלוּ הַהוּא יוֹמָא אוֹרַיְיתָא מִטּוּרָא דְסִינַי. בָּתַר דְּאִסְתַּלָּקוּ לָא הֲווּ יָדְעֵי אִי הוּא יְמָמָא וְאִי לֵילְיָא. אָמַר רַבִּי אַבָּא בְּעוֹד דְּאֲנַן קָיְימִין לֵימָא כָּל חַד מִינָן מִלָּה חַדְתָּא דְחָכְמְתָא לְאַקְשְׁרָא טִיבוּ לְמָארֵיהּ דְּבֵיתָא מָרֵיהּ דְּהִלּוּלָא:","פָּתַח חַד וְאָמַר (תהילים ס״ה:ה׳) אַשְׁרֵי תִּבְחַר וּתְקָרֵב יִשְׁכֹּן חֲצֵרֶיךָ וְגו'. בְּקַדְמִיתָא חֲצֵרֶיךָ לְבָתַר בֵּיתֶךָ וּלְבָתַר הֵיכָלֶךָ. דָּא פְּנִימָאָה מִן דָּא, וְדָא לְעֵילָא (נ\"א לגו) מִן דָּא. יִשְׁכֹּן חֲצֵרֶיךָ בְּקַדְמִיתָא, כְּמָא דְאַתְּ אָמֵר (ישעיהו ד׳:ג׳) וְהָיָה הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּיְרוּשָׁלַ ם קָדוֹשׁ יֵאָמֶר לוֹ.","נִשְׂבְּעָה בְּטוּב בֵּיתֶךָ לְבָתַר כְּמָא דְאַתְּ אָמֵר, (משלי כ״ד:ג׳) בְּחָכְמָה יִבְנֶה בַיִת. הַחָכְמָה יִבְנֶה בַיִת לָא כְּתִיב, דְּאִי כְּתִיב הָכִי, הֲוָה מַשְׁמַע דְּחָכְמָה בַּיִת אִקְרֵי, אֶלָּא כְּתִיב בְּחָכְמָה יִבְנֶה בַיִת, הַיְינוּ דִּכְתִיב, (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן וְגו'.","קְדוֹשׁ הֵיכָלֶךָ לְבָתַר דָּא הוּא שְׁלִימוּ דְּכֹלָּא, דְּהָכִי תָּנִינָן מַהוּ הֵיכָל. כְּלוֹמַר ה\"י כ\"ל, הַאי וְהַאי. וְכֹלָּא אִשְׁתְּלִים כְּחֲדָא.","רֵישָׁא דְקְרָא מַה מּוֹכַח דִּכְתִיב אַשְׁרֵי תִּבְחַר וּתְקָרֵב יִשְׁכֹּן חֲצֵרֶיךָ. הַאי מַאן דְּאַקְרִיב בְּרֵיהּ קָרְבָּנָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, רַעֲוָא דְּקוּדְשָׁא בְּרִיךְ הוּא בְּהַהוּא קָרְבָּנָא וְאִתְרְעֵי בֵּיהּ וְקָרִיב לֵיהּ וְשַׁוֵּי מְדוֹרֵיהּ בִּתְרֵין אִדְרִין וְאָחִיד לְהַאי וּלְהַאי דְּאִנּוּן תְּרֵין אִתְקַשְּׁרוּ כְּחֲדָא. דִּכְתִיב יִשְׁכֹּן חֲצֵרֶיךָ. חֲצֵרֶיךָ וַדַּאי תְּרֵי.","בְּגִינֵי כָךְ חֲסִידֵי קַדְמָאֵי סָבָאן דְּהָכָא כַּד מַקְרִיבִין בְּנַיְיהוּ לְקָרְבָּנָא דָא. פָּתְחֵי וְאָמְרֵי אַשְׁרֵי תִבְחַר וּתְקָרֵב יִשְׁכֹּן חֲצֵרֶיךָ. אִנּוּן דְּקָיְימֵי עֲלַיְיהוּ אָמְרֵי נִשְׂבְּעָה בְּטוּב בֵּיתֶךָ קְדוֹשׁ הֵיכָלֶךָ. לְבָתַר מְבָרֵךְ אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ לְהַכְנִיסוֹ בִּבְרִיתוֹ שֶׁל אַבְרָהָם אָבִינוּ. וְאִנּוּן דְּקָיְימֵי עֲלַיְיהוּ אָמְרֵי כְּשֵׁם שֶׁהִכְנַסְתּוֹ לַבְּרִית וְכוּ'.","וְתָנִינָן בְּקַדְמִיתָא לִבָּעֵי בַּר נָשׁ רַחֲמִין עֲלֵיהּ וּלְבָתַר עַל אָחֳרָא דִּכְתִיב, (ויקרא ט״ז:י״ז) וְכִפֶּר בַּעֲדוֹ בְּקַדְמִיתָא וּלְבָתַר וּבְעַד כָּל קְהַל יִשְׂרָאֵל. וְאֲנַן אוֹרְחָא דָא נַקְטִינָן וְהָכִי שַׁפִּיר וְחָזֵי לְקַמָּאן.","אָמַר רַבִּי אַבָּא וַדַּאי כָּךְ הוּא וְיָאוֹת מִלָּה, וּמַאן דְּלָא אָמַר הָכִי אַפִּיק גַּרְמֵיהּ מֵעֲשָׂרָה חֻפּוֹת דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְמֶעְבַּד לְצַדִּיקַיָּא בְּעָלְמָא דְאָתֵי, וְכֻלְהוּ מִתְקַשְׁרָן בְּהַאי. וּבְגִינֵי כָךְ עֲשָׂרָה מִילֵּי דִּמְהֵימְנוּתָא אִית בְּהַאי קְרָא אַשְׁרֵי תִּבְחַר וּתְקָרֵב וְגו'. וְכָל מִלָּה וּמִלָּה חַד חֻפָּה אִתְעֲבִיד מִנָּהּ.","זַכָּאָה חוּלָקֵיכוֹן בְּעָלְמָא דָא וּבְעָלְמָא דְאָתֵי, דְּהָא אוֹרַיְיתָא מִתְקַשְּׁרָא בְּלִבַּיְיכוּ כְּאִלּוּ קָיְימִיתוּ בְּגוּפַיְיכוּ בְּטוּרָא דְסִינַי בְּשַׁעֲתָא דְּאִתְיְהִיבַת אוֹרַיְיתָא לְיִשְׂרָאֵל:"],[[0,"ואתרא דא וכו':","ומקום זה שאנו בו, זיכה אותנו לתורה, ולדרך הזה שלנו. בכל לילה, חציה אנו ישנים, וחציה אנו עוסקים בתורה. וכשאנו קמים בבוקר, ריח השדה ונהרות מים מאירים לנו התורה, ומתישבת בלבנו."],[1,"ואתר דא וכו':","ומקום זה, פעם אחת כבר דנוהו למעלה, וכמה גדולי תורה נסתלקו באותו הדין בעונש ביטול התורה. ומאז, העסק שלנו הוא יום ולילה בתורה, ומקום זה עוזר לנו. וכל הפורש מכאן, הוא כמו שנפרש מחיי העולם."],[2,"זקיף ידוי וכו':","נשא ידיו ר' אבא, וברך אותם. ישבו עד שהאיר היום. אחר שהאיר היום, אמרו לילדים שישבו לפניהם, צאו וראו אם האיר היום, וכל אחד מכם יאמר דבר חידוש בתורה לאדם גדול הזה. דהיינו לר' אבא."],[3,"נפקו וחמו וכו':","יצאו וראו שהאיר היום, אמר אחד מהם. עתיד לבא ביום הזה אש מלמעלה. אמר אחר, ובבית הזה אמר אחר, זקן אחד כאן, עתיד ביום הזה להשרף באש הזה, אמר ר' אבא הרחמן יצילנו."],[4,"תווה ולא יכיל וכו':","תמה ר' אבא, ולא יכול לדבר. אמר סוד ממשלה העליונה נתפס בארץ. כי גם ילדים יודעים לנבא עתידות, \u0003קוטרא\u0004 פירושו דבר מסובך וסוד. \u0003דהורמנא\u0004 פירושו ממשלה כמ\"ש (ערובין י\"ט) כיון דשכיחי גבי הרמנא. \u0003וכך הוה\u0004 וכו' וכך היה, שבאותו יום ראו החברים פני השכינה והוקפו באש, ור' אבא, נתלהטו פניו כאש, משמחת התורה."],[5,"תאנא כל וכו':","למדנו. כל אותו היום, כולם, לא יצאו מן הבית, והבית נתקשר באש ועשן, והדברים היו שמחים ביניהם, כאלו קבלו התורה באותו יום מהר סיני. ואחר שנסתלקו משם, לא היו יודעים אם הוא יום או לילה. אמר ר' אבא, כל עוד שאנו נמצאים כאן, יאמר כל אחד מאתנו, דבר חדש בחכמה, להחזיק טובה לבעל הבית בעל השמחה."],[6,"פתח חד וכו':","פתח אחד ואמר אשרי תבחר ותקרב וגו'. מתחילה אומר הכתוב חצריך, אח\"כ ביתך, ואח\"כ היכלך. זה פנימי מזה וזה למעלה מזה. כלומר, שהם ג' מדרגות המלכות ממטה למעלה, זו גבוהה מזו. \u0003ישכון חצריך\u0004 בתחילה, שפירושו בחי' נה\"י שהם לבר מגופא, ונק' חצרות. כמו שאתה אומר, והיה הנשאר בציון, והנותר בירושלים קדוש יאמר לו. כי עיקר נה\"י הוא יסוד, וציון היא פנימיות היסוד, וירושלים חיצוניותו. ושניהם נקראים חצרות."],[7,"נשבעה וכו':","נשבעה בטוב ביתך הוא לאח\"כ, כלומר לאחר שנשלם במדרגת \u0003חצר,\u0004 זוכה למדרגת \u0003בית.\u0004 כמש\"א בחכמה יבנה בית. \u0003החכמה יבנה בית,\u0004 לא כתוב, שאם היה כתוב כן היה משמע שהחכמה נקרא בית, אלא שכתוב \u0003בחכמה יבנה בית,\u0004 שהמשמעות שהמלכות מקבלת חכמה, ואז נקראת בית. והיינו שכתוב ונהר יוצא מעדן להשקות את הגן. \u0003שנהר יוצא מעדן\u0004 ה\"ס בינה החוזרת לחכמה. \u0003הגן\u0004 זהו מלכות. ואז נקראת בית."],[8,"קדוש היכלך וכו':","קדוש היכלך, הוא לאחר כך, דהיינו אחר שנשלם במדרגת בית. הוא שלימות הכל. כי כך למדנו. מהו \u0003היכל.\u0004 כלומר, \u0003הי כל\u0004 זה וזה. דהיינו שהזוכה למדרגה זו מתפלא ואומר, איך נגלה כל זה. והכל נשלם כאן ביחד. כלומר כל דבר מוצא כאן תכלית שלמותו."],[9,"רישא דקרא וכו':","תחילת הכתוב מה מוכיח לנו, שכתוב, אשרי תבחר ותקרב ישכון חצריך, הוא, שכל מי שמקריב את בנו קרבן לפני הקב\"ה, דהיינו שמל אותו, רצונו של הקב\"ה בקרבן הזה, ורוצה בו, ומקרבו, ושם משכנו, בשני חדרים של היסוד, שהם ציון וירושלים כנ\"ל, ותופש בזה ובזה, כי אלו השנים מתקשרים כאחד. שכתוב ישכון חצריך, חצריך ודאי שני חצרות."],[10,"בגיני כך חסידי וכו':","משום זה, חסידים הראשונים, זקניהם של אלו שבכאן, כשהקריבו בניהם לקרבן זה לברית מילה, פתחו ואמרו אשרי תבחר ותקרב ישכון חצריך. אלו העומדים אצלם אמרו, נשבעה בטוב ביתך קדוש היכלך. אחר כך מברך, אשר קדשנו במצותיו וצונו להכניסו בבריתו של אברהם אבינו. והעומדים עליהם, אמרו כשם שהכנסתו לברית וכו'."],[11,"ותנינן בקדמיתא:","ולמדנו, שתחלה יבקש אדם רחמים על עצמו, ואחר כך על חבירו. שכתוב, \u0003וכפר בעדו\u0004 מתחילה, ואחר כך ובעד כל קהל ישראל. אנו לקחנו דרך הזה וכן טוב ויפה לנו. לכן צריך תחילה בעל הברית עצמו לומר פסוקי דרחמי, ואח\"כ יאמרו העומדים עליו."],[12,"אמר ר' אבא וכו':","אר\"א, ודאי כך הוא ויפה הדבר, דהיינו לומר הכתוב אשרי תבחר ותקרב הנ\"ל, ומי שאינו אומר כן, מוציא את עצמו מעשרה חופות שעתיד הקב\"ה לעשות לצדיקים בעולם הבא. וכולם מתקשרים בזה הכתוב, ומשום כך עשר מלות של האמונה יש בכתוב הזה, אשרי תבחר ותקרב וגו', וכל מלה ומלה נעשה ממנה חופה אחת."],[13,"אשרי חלקכם","בעולם הזה ובעולם הבא, כי התורה מתקשרת בלבותיכם, כאלו עמדתם בעצמכם בהר סיני בשעה שניתנה תורה לישראל."]],[[0,"","וְהַמָּקוֹם הַזֶּה זִכָּה אוֹתָנוּ לַתּוֹרָה, וְהַדֶּרֶךְ הַזּוֹ שֶׁלָּנוּ. בְּכָל לַיְלָה, חֲצִי אָנוּ יְשֵׁנִים, וַחֲצִי אָנוּ עוֹסְקִים בַּתּוֹרָה. וּכְשֶׁאָנוּ עוֹמְדִים בַּבֹּקֶר, רֵיחוֹת הַשָּׂדֶה וְנַהֲרוֹת מַיִם מְאִירִים לָנוּ אֶת הַתּוֹרָה, וְהִיא מִתְיַשֶּׁבֶת בְּלִבֵּנוּ."],[1,"","וְאֶת הַמָּקוֹם הַזֶּה הֲרֵי דָּנוּ אוֹתוֹ לְמַעְלָה פַּעַם אַחַת, וְכַמָּה שָׂרֵי מָגִנִּים הִסְתַּלְּקוּ בְּאוֹתוֹ הַדִּין עַל עֹנֶשׁ הַתּוֹרָה, וְאָז הַהִשְׁתַּדְּלוּת שֶׁלָּנוּ יוֹמָם וָלַיְלָה הִיא בַּתּוֹרָה, וְהַמָּקוֹם הַזֶּה מְסַיֵּעַ לָנוּ, וּמִי שֶׁנִּפְרָד מִכָּאן, כְּמִי שֶׁנִּפְרָד מֵחַיֵּי הָעוֹלָם."],[2,"","הֵרִים יָדוֹ רַבִּי אַבָּא וּבֵרַךְ אוֹתָם. יָשְׁבוּ עַד שֶׁהֵאִיר הַיּוֹם. אַחַר שֶׁהֵאִיר הַיּוֹם, אָמְרוּ לְאוֹתָם הַתִּינוֹקוֹת שֶׁלִּפְנֵיהֶם: צְאוּ וּרְאוּ אִם הֵאִיר הַיּוֹם, וְכָל אֶחָד יֹאמַר דָּבָר חָדָשׁ בַּתּוֹרָה לָאִישׁ הַגָּדוֹל הַזֶּה."],[3,"","יָצְאוּ וְרָאוּ שֶׁהֵאִיר הַיּוֹם. אָמַר אֶחָד מֵהֶם, מְזֻמֶּנֶת בַּיּוֹם הַזֶּה אֵשׁ מִלְמַעְלָה. אָמַר אַחֵר, וּבַבַּיִת הַזֶּה. אָמַר אַחֵר, זָקֵן אֶחָד כָּאן שֶׁעָתִיד בַּיּוֹם הַזֶּה לְהִשָּׂרֵף בָּאֵשׁ הַזּוֹ. אָמַר רַבִּי אַבָּא, הָרַחֲמָן יַצִּילֵנוּ."],[4,"","תָּמַהּ וְלֹא יָכֹל לְדַבֵּר. אָמַר, עֲשַׁן הַמַּלְכוּת נִתְפָּס בָּאָרֶץ. וְכָךְ הָיָה, שֶׁהַיּוֹם הַהוּא רָאוּ הַחֲבֵרִים אֶת פְּנֵי הַשְּׁכִינָה וְהֻקְּפוּ בְאֵשׁ, וְרַבִּי אַבָּא לָהֲטוּ פָנָיו כָּאֵשׁ מִשִּׂמְחַת הַתּוֹרָה."],[5,"","שָׁנִינוּ, כָּל אוֹתוֹ הַיּוֹם לֹא יָצְאוּ כֻלָּם מִן הַבַּיִת, וְהַבַּיִת נִקְשַׁר בְּעָשָׁן, וְהָיוּ מְחַדְּשִׁים דְּבָרִים בְּתוֹכָם כְּאִלּוּ קִבְּלוּ הַיּוֹם הַהוּא תּוֹרָה מֵהַר סִינַי. אַחַר שֶׁהִסְתַּלְּקוּ, לֹא הָיוּ יוֹדְעִים אִם הוּא יוֹם וְאִם לַיְלָה. אָמַר רַבִּי אַבָּא, בְּעוֹדֵנוּ עוֹמְדִים, יֹאמַר כָּל אֶחָד מֵעִמָּנוּ דָּבָר חָדָשׁ שֶׁל חָכְמָה לִקְשֹׁר חֶסֶד לְבַעַל הַבַּיִת, בַּעַל הַהִלּוּלָא."],[6,"","פָּתַח אֶחָד וְאָמַר, (תהלים סה) אַשְׁרֵי תִּבְחַר וּתְקָרֵב יִשְׁכֹּן חֲצֵרֶיךְ וְגוֹ'. בַּתְּחִלָּה חֲצֵרֶיךְ, לְאַחַר מִכֵּן בֵּיתֶךְ, וּלְאַחַר מִכֵּן הֵיכָלֶךְ. זֶה פְּנִימִי מִזֶּה, וְזֶה (נ\"א: לתוך) לְמַעְלָה מִזֶּה. יִשְׁכֹּן חֲצֵרֶיךְ בַּתְּחִלָּה, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה ד) וְהָיָה הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּירוּשָׁלַיִם קָדוֹשׁ יֵאָמֶר לוֹ."],[7,"","נִשְׂבְּעָה בְּטוּב בֵּיתֶךְ לְאַחַר מִכֵּן, כְּמוֹ שֶׁנֶּאֱמַר (משלי כד) בְּחָכְמָה יִבָּנֶה בָּיִת. לֹא כָתוּב הַחָכְמָה יִבְנֶה בַיִת. שֶׁאִם הָיָה כָּתוּב כָּךְ, מַשְׁמָע שֶׁחָכְמָה נִקְרֵאת בַּיִת. אֶלָּא כָּתוּב בְּחָכְמָה יִבָּנֶה בָּיִת, הַיְנוּ מַה שֶּׁכָּתוּב (בראשית ב) וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן וְגוֹ'."],[8,"","קְדוֹשׁ הֵיכָלֶךְ לְאַחַר זֶה הוּא שְׁלֵמוּת הַכֹּל. שֶׁכָּךְ שָׁנִינוּ, מַה זֶּה הֵיכָל? כְּלוֹמַר ה\"י כ\"ל, זֶה וָזֶה, וְהַכֹּל נִשְׁלָם יַחַד."],[9,"","מַה מּוֹכִיחַ רֹאשׁ הַכָּתוּב שֶׁכָּתוּב אַשְׁרֵי תִּבְחַר וּתְקָרֵב יִשְׁכֹּן חֲצֵרֶיךְ? זֶה מִי שֶׁמַּקְרִיב אֶת בְּנוֹ קָרְבָּן לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, רְצוֹנוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בַּקָּרְבָּן הַהוּא, וּמִתְרַצֶּה בּוֹ וּמְקָרֵב אוֹתוֹ, וְשָׂם אֶת מְדוֹרוֹ בִּשְׁנֵי חֲדָרִים, וְאוֹחֵז אֶת זֶה וְאֶת זֶה, שֶׁאוֹתָם הַשְּׁנַיִם נִקְשְׁרוּ יַחַד, שֶׁכָּתוּב יִשְׁכֹּן חֲצֵרֶיךְ, וַדַּאי שְׁנֵי חֲצֵרֶיךְ.\\"],[10,"","מִשּׁוּם כָּךְ הַחֲסִידִים הָרִאשׁוֹנִים, זְקֵנֵינוּ שֶׁל כָּאן, כְּשֶׁמַּקְרִיבִים אֶת בְּנֵיהֶם לַקָּרְבָּן הַזֶּה, פּוֹתְחִים וְאוֹמְרִים: אַשְׁרֵי תִּבְחַר וּתְקָרֵב יִשְׁכֹּן חֲצֵרֶיךְ. אוֹתָם שֶׁעוֹמְדִים עֲלֵיהֶם אוֹמְרִים: נִשְׂבְּעָה בְּטוּב בֵּיתֶךְ קְדוֹשׁ הֵיכָלֶךְ. אַחַר כָּךְ מְבָרֵךְ אֲשֶׁר קִדְּשָׁנוּ בְּמִצְווֹתָיו וְצִוָּנוּ לְהַכְנִיסוֹ בִּבְרִיתוֹ שֶׁל אַבְרָהָם אָבִינוּ. וְאוֹתָם שֶׁעוֹמְדִים עֲלֵיהֶם אוֹמְרִים: כְּשֵׁם שֶׁהִכְנַסְתּוֹ לַבְּרִית וְכוּ'."],[11,"","וְשָׁנִינוּ, בַּתְּחִלָּה יְבַקֵּשׁ אָדָם רַחֲמִים עָלָיו, וְאַחַר כָּךְ עַל הָאַחֵר, שֶׁכָּתוּב (ויקרא טז) וְכִפֶּר בַּעֲדוֹ - בַּתְּחִלָּה, וְאַחַר כָּךְ - וּבְעַד כָּל קְהַל יִשְׂרָאֵל. וְאָנוּ לָקַחְנוּ אֶת הַדֶּרֶךְ הַזּוֹ, וְכָךְ יָפֶה וְרָאוּי לְפָנֵינוּ."],[12,"","אָמַר רַבִּי אַבָּא, וַדַּאי כָּךְ הוּא וְנָאֶה הַדָּבָר. וּמִי שֶׁלֹּא אוֹמֵר כָּךְ, הוּא מוֹצִיא אֶת עַצְמוֹ מֵעֲשָׂרָה חֻפּוֹת שֶׁעָתִיד לַעֲשׂוֹת הַקָּדוֹשׁ בָּרוּךְ הוּא לַצַּדִּיקִים בָּעוֹלָם הַבָּא. וְכֻלָּם נִקְשָׁרִים בָּזֶה. וּמִשּׁוּם כָּךְ עֲשָׂרָה דְבָרִים שֶׁל הָאֱמוּנָה יֵשׁ בַּפָּסוּק הַזֶּה אַשְׁרֵי תִּבְחַר וּתְקָרֵב וְגוֹ', וּמִכָּל דָּבָר וְדָבָר נַעֲשֵׂית חֻפָּה אַחַת מִמֶּנָּה."],[13,"","אַשְׁרֵי חֶלְקְכֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁהֲרֵי הַתּוֹרָה נִקְשֶׁרֶת בִּלְבַבְכֶם כְּאִלּוּ עֲמַדְתֶּם בְּגוּפְכֶם בְּהַר סִינַי בְּשָׁעָה שֶׁנִּתְּנָה תוֹרָה לְיִשְׂרָאֵל."]]],[["פָּתַח אִידָךְ וְאָמַר (שמות כ׳:כ״א) מִזְבַּח אֲדָמָה תַּעֲשֶׂה לִי וְזָבַחְתָּ עָלָיו אֶת עֹלֹתֶיךָ וְאֶת שְׁלָמֶיךָ וְגו'. תָּאנָא כָּל מַאן דְּקָרִיב בְּרֵיהּ לְקָרְבָּנָא דָא, כְּאִלּוּ אַקְרִיב כָּל קָרְבָּנִין דְּעָלְמָא לְקַמֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, וּכְאִילּוּ בָּנֵי מַדְבְּחָא שְׁלֵימָתָא קַמֵּיהּ.","בְּגִינֵי כָךְ בָּעֵי לְסַדְּרָא מַדְבְּחָא בְּמָאנָא חַד מַלְיָיא אַרְעָא לְמִגְזַר עֲלֵיהּ הַאי קְיָימָא קַדִּישָׁא, וְאִתְחַשִּׁיב קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא כְּאִלּוּ אַדְבַּח עֲלֵיהּ עִלַוָּון וְקָרְבָּנִין עָאנָא וְתוֹרֵי.","וְנִיחָא לֵיהּ יַתִּיר מִכֻּלְהוּ דִּכְתִיב וְזָבַחְתָּ עָלָיו אֶת עֹלֹתֶיךָ וְאֶת שְׁלָמֶיךָ וְגו'. בְּכָל הַמָּקוֹם אֲשֶׁר אַזְכִּיר אֶת שְׁמִי. מַהוּ אַזְכִּיר אֶת שְׁמִי (את) דָּא מִילָה דִּכְתִיב בָּהּ (תהילים כ״ה:י״ד) סוֹד יְיָ לִירֵאָיו וּבְרִיתוֹ לְהוֹדִיעָם.","הַאי מִזְבַּח אֲדָמָה וַדַּאי כְּמָא דְּאָמִינָא. בַּתְרֵיהּ מַה כְּתִיב וְאִם מִזְבַּח אֲבָנִים תַּעֲשֶׂה לִי. רֶמֶז לְגִיּוֹרָא כַּד אִתְגַיַּיר דְּאִיהוּ מֵעַם קְשֵׁי קְדַל וּקְשֵׁי לִבָּא, הַאי אִקְרֵי מִזְבַּח אֲבָנִים.","לֹא תִבְנֶה אֶתְהֶן גָּזִית. מָה הוּא, דְּבָעֵי לְאֲעָלָא לֵיהּ בְּפוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא (בגין) וְלָא יִגְזַר יָתֵיהּ עַד דְּיִנְשֵׁי פּוּלְחָנָא אָחֳרָא דְּעֲבַד עַד הָכָא וְיַעֲדֵי מִנֵּיהּ הַהוּא קַשְׁיוּ דְלִבָּא.","וְאִי אִתְגְּזַר וְלָא אַעֲדֵי מִנֵּיהּ הַהוּא קַשְׁיָא דְלִבָּא לְמֵיעַל בְּפוּלְחָנָא קַדִּישָׁא דְּקוּדְשָׁא בְּרִיךְ הוּא, הֲרֵי הוּא כְּהַאי פְּסִילָא דְאַבְנָא דְּגַזְרֵי לֵיהּ מֵהַאי גִיסָא וּמֵהַאי גִיסָא וְאִשְׁתָּאַר אַבְנָא כִּדְבְּקַדְמִיתָא. בְגִין כָּךְ לא תִבְנֶה אֶתְהֶן גָּזִית. דְּאִי אִשְׁתָּאַר בְּקַשְׁיוּתֵיהּ, כִּי חַרְבְּךָ הֵנַפְתָּ עָלֶיהָ וַתְּחַלֲּלֶיהָ, כְּלוֹמַר הַהוּא גְּזִירוּ דְּאִתְגְּזַר לָא מְהַנְיָא לֵיהּ.","בְּגִינֵי כָךְ זַכָּאָה חוּלָקֵיהּ דְּמַאן דְּאַקְרִיב הַאי קָרְבָּנָא בְּחֶדְוָותָא בְּרַעֲוָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וּבָעֵי לְמֶחדֵי בְּהַאי חוּלָקָא כָּל (ד\"א ל\"ג ההוא) יוֹמָא דִּכְתִיב, (תהילים ה׳:י״ב) וְיִשְׂמְחוּ כָל חוֹסֵי בָךְ לְעוֹלָם יְרַנֵּנוּ וְתָסֵךְ עָלֵימוֹ וְיַעְלְצוּ בְךָ אֹהֲבֵי שְׁמֶךָ:","פָּתַח אִידָךְ וְאָמַר וַיְהִי אַבְרָם בֶּן תִּשְׁעִים שָׁנָה וְתֵשַׁע שָׁנִים וַיֵּרָא יְיָ וְגו' אֲנִי אֵל שַׁדַּי הִתְהַלֶּךְ לְפָנַי וְגו'. הַאי קְרָא אִית לְעַיְינָא בֵּיהּ וְקַשְׁיָא בְּכַמָּה אוֹרְחִין, וְכִי עַד הַשְׁתָּא לָא אִתְגְּלִי לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְאַבְרָהָם אֶלָּא (עד) הָאִידְנָא כַּד מָטָא לְהַנֵּי יוֹמִין וַיֵּרָא יְיָ אֶל אַבְרָם וְלָא קֹדֶם. וְהָכְתִיב וַיֹּאמֶר יְיָ אֶל אַבְרָם. וַיְיָ אָמַר אֶל אַבְרָם. וַיֹּאמֶר לְאַבְרָם יָדוֹעַ תֵדַע וְגו'. וְהָאִידְנָא מָנֵי חוּשְׁבַּן יוֹמִין, וְכַד מָנִי לְהוּ כְּתִיב וַיֵּרָא יְיָ אֶל אַבְרָם, אִשְׁתְּמַע דְּעַד הַשְׁתָּא לָא אִתְגְּלִי עֲלוֹי. וְעוֹד דִּכְתִיב בֶּן תִּשְׁעִים שָׁנָה וְתֵשַׁע שָׁנִים, בְּקַדְמִיתָא שָׁנָה וּלְבַסוֹף שָׁנִים.","אֶלָּא הָכִי תָאנָא, כָּל אִנּוּן יוֹמִין לָא כְּתִיב וַיֵּרָא, מַאי טַעְמָא, אֶלָּא כָּל כַּמָּה דְהֲוָה אָטִים וְסָתִים (כך) קוּדְשָׁא בְּרִיךְ הוּא לָא אִתְגְּלִי עֲלֵיהּ כִּדְקָחָזֵי. הָאִידְנָא אִתְגְּלִי עֲלֵיהּ דִּכְתִיב וַיֵּרָא. מַאי טַעְמָא. מִשּׁוּם דְּבָעָא לְגַלֵּי בֵּיהּ הַאי אָת כִּתְרָא קַדִּישָׁא.","וְעוֹד דְּבָעָא קוּדְשָׁא בְּרִיךְ הוּא לְאֲפָקָא מִנֵּיהּ זַרְעָא קַדִּישָׁא, וְקַדִּישָׁא לָא לֶהֱוֵי בְּעוֹד דְּאִיהוּ אָטִים בִּשְׂרָא, אֶלָּא אָמַר הַשְׁתָּא דְהוּא בֶּן תִּשְׁעִים שָׁנָה וְתֵשַׁע שָׁנִים וּזְמַן קָרִיב הוּא דְּיִנְפּוֹק מִנֵּיהּ זַרְעָא קַדִּישָׁא, לֶהוֵי הוּא קַדִּישָׁא בְּקַדְמִיתָא וּלְבָתַר יִנְפּוֹק מִנֵּיהּ זַרְעָא קַדִּישָׁא. בְגִין כָּךְ מָנֵי יוֹמוֹי בְּהַאי וְלָא בְּכָל הַנֵּי זִמְנִי קַדְמִיתָא.","תוּ תִּשְׁעִים שָׁנָה, דְּכָל יוֹמוֹי קַדְמָאֵי לָא הֲווּ שָׁנִים אֶלָּא כְּחַד שָׁנָה דְּלָא הֲווּ יוֹמוֹי יוֹמִין, הַשְׁתָּא דְּמָטָא לְהַאי שָׁנִים, אִנּוּן וְלָא שָׁנָה:","וַיֹּאמֶר אֵלָיו אֲנִי אֵל שַׁדַּי. מַאי מַשְׁמַע דְּעַד הַשְׁתָּא לָא קָאֲמַר אֲנִי אֵל שַׁדַּי. אֶלָּא הָכִי תָאנָא, עֲבַד קוּדְשָׁא בְּרִיךְ הוּא כִּתְרִין תַּתָּאִין דְּלָא קַדִּישִׁין לְתַתָּא. וְכָל אִנּוּן דְּלָא אִתְגְזָּרוּ יִסְתָּאֲבוּן בְּהוֹן.","וּרְשִׁימִין בְּהוֹן, וּמַאי רִשּׁוּמָא אִית בְּהוֹן, דְּאִתְחֲזֵי בְּהוּ שי\"ן דל\"ת וְלָא יַתִּיר, וּבְגִין כָּךְ אִסְתַּאֲבוּן בְּהוּ וְאִתְדַּבְּקוּן בְּהוּ. בָּתַר דְּאִתְגְּזָרוּ נָפְקִין מֵאִלֵּין וְעָאלִין בְּגַדְפוֹי דִּשְׁכִינְתָּא וְאִתְגַּלְּיָא בְּהוּ יו\"ד רְשִׁימָא קַדִּישָׁא אָת קְיָימָא שְׁלִים וְאִתְרְשִׁים בְּהוּ שד\"י וְאִשְׁתְּלִים בְּקִיּוּמָא שְׁלִים, וְעַל דָּא כְּתִיב בְּהַאי אֲנִי אֵל שַׁדַּי."],[[0,"פתח אידך וכו':","פתח אחר ואמר. מזבח אדמה תעשה לי וגו'. למדנו, כל מי שמקריב את בנו לקרבן הזה של ברית מילה, הוא כאלו היה מקריב כל קרבנות שבעולם לפני הקב\"ה, וכאלו בנה מזבח שלם לפניו."],[1,"בגיני כך בעי וכו':","משום זה, צריך לסדר מזבח בכלי אחד מלא עפר, למול עליו ברית קדוש הזה. ונחשב לפני הקב\"ה כאלו שחט עליו עולות וקרבנות צאן ובקר."],[2,") וניחא ליה יתיר וכו':","ונוח לו להקב\"ה מעשה המילה, יותר מכל הקרבנות, שכתוב וזבחת עליו את עולותיך ואת שלמיך וגו' בכל המקום אשר \u0003אזכיר את שמי.\u0004 מהו אזכיר את שמי, הוא מילה, שכתוב, סוד ה' ליראיו ובריתו להודיעם. הרי שברית הוא שם, שאומר בו ובריתו להודיעם."],[3,"האי מזבח אדמה וכו':","מזבח אדמה הזה, הוא ודאי כמו שאמרתי, (לעיל באות ת\"ל) ואחריו מה כתוב, ואם מזבח אבנים תעשה לי. זהו רמז לגר כשהוא מתגייר. שהוא מעם קשה עורף וקשה לב, זהו נקרא מזבח אבנים."],[4,"לא תבנה אתהן גזית:","מהו פירושו. ואומר, שצריך להכניס את הגר בעבודת הקב\"ה, ולא ימול אותו, עד שישכח העבודה זרה שעבד עד כאן, דהיינו שתצא מלבו. ועד שתסור ממנו ערלת לבו."],[5,"ואי אתגזר וכו':","ואם נמול ולא הסיר ממנו אותו קשיות לב כדי שיכנס בעבודתו הקדושה של הקב\"ה, הרי הוא כמו פסל של אבן. שמסתתים אותו מצד זה ומצד זה, והאבן נשאר אבן כבתחילה. משום זה לא תבנה אתהן גזית, שאם נשאר בקשיותו, נמצא, כי חרבך הנפת עליה ותחלליה, כלומר, מילה זו שנמול אינה מועלת לו."],[6,"בגיני כך זכאה וכו':","משום זה, אשרי חלקו של המקריב קרבן זה בשמחה וברצון לפני הקב\"ה, וצריכים לשמוח בחלק הזה כל היום. שכתוב וישמחו כל חוסי בך. לעולם ירננו וגו'."],[7,"פתח אידך וכו':","פתח אחר ואמר. ויהי אברם בן תשעים שנה ותשע שנים וירא ה' וגו'. במקרא הזה יש לעיין בו. והוא קשה בכמה דרכים. וכי עד עתה לא נגלה הקב\"ה לאברהם, אלא רק עתה כשהגיע לימים האלו, וירא ה' אל אברם ולא מקודם לכן, והרי כתוב ויאמר ה' אל אברם. וה' אמר אל אברם. ויאמר לאברם ידוע תדע וגו'. ועתה כשמחשב מספר ימים, וכאשר מחשב אותם, כתוב, וירא ה' אל אברם, משמע כי עד עתה עוד לא נגלה עליו אלקים ועוד שכתוב, בן תשעים \u0003שנה\u0004 ותשע \u0003שנים,\u0004 מתחילה אומר שנה, ולבסוף אומר שנים."],[8,"אלא הכי תאנא וכו':","אלא כך למדנו כל אלו הימים עד עתה לא כתוב וירא ה' אל אברם. מה הטעם. אלא כל זמן שהיה ערל וסתים הקב\"ה לא נגלה עליו כראוי. עתה נגלה עליו כראוי, שכתוב וירא. מה הטעם. משום שרצה לגלות בו אות ברית הזה שהוא כתר הקדוש."],[9,"ועוד דבעא וכו':","ועוד, כי רצה הקב\"ה להוציא ממנו זרע קדוש, וקדוש לא יוכל היות בעוד שהוא ערל בשר. אלא אמר הקב\"ה, עתה, כשהוא בן צ\"ט שנה, והזמן קרוב שיצא ממנו זרע קדוש, דהיינו שקרוב להיות מאה שנה, יהיה הוא קדוש מתחילה, דהיינו שימול עצמו, ואח\"כ יצא ממנו זרע קדוש. משום זה מנה ימיו בזה, דהיינו \u0003בתשע שנים,\u0004 משום שנתקרב לזמן הראוי להוליד בשלמות, ולא בכל הזמנים שקדמו. דהיינו בתשעים שנים שקדמו, שעוד לא היה ראוי להוליד זרע קדוש, ולפיכך לא כתוב בהם \u0003שנים\u0004 אלא \u0003תשעים שנה.\u0004"],[10,"תו תשעים שנה וכו':","ועוד יש לומר על מה שכתוב תשעים שנה ולא שנים. כי כל הימים הקודמים, מטרם שנמול, לא היו שנים. אלא היו נחשבים כשנה אחת, כי ימיו לא היו ימים. עתה שהגיע לשנים האלו, דהיינו לצ\"ט שנה שימול עצמו, נחשבו לו שנים ולא כתוב בהם שנה. אלא שכתוב, ותשע שנים."],[11,"ויאמר אליו אני אל שדי:","ושואל, מה הטעם שעד עתה, לא אמר אליו הקב\"ה אני אל שדי. ומשיב, אלא כך למדנו. עשה הקב\"ה למטה, כתרים תחתונים שאינם קדושים. וכל אלו שלא נמולו יטמאו בהם."],[12,"ורשימין בהון וכו':","ויש בהם, בכתרים תחתונים, רשימות. ומה הוא הרשימה שיש בהם, הוא כי נראה בהם \u0003שין דלת\u0004 ולא יותר. דהיינו שחסר שם ה \u0003י'\u0004 מהשם \u0003שדי.\u0004 ומשום זה מטמאים בהם, ומתדבקים בהם כתרים תחתונים. פירושו. הלעומת של עשרה כתרים דקדושה, בסו\"ה זה לעומת זה עשה אלקים. והמכשפים והשדים יונקים חיותם וכל כחם מעשרה כתרים תחתונים הללו."],[12,"בתר דאתגזרו וכו':","אחר שנמולו יוצאים מאלו, כתרים תחתונים, ונכנסים בכנפי השכינה, ומתגלה בהם ה \u0003י'\u0004 רשימה הקדושה, אות ברית השלם, ונרשם בהם השם \u0003שדי,\u0004 ונשלם בקיום שלם. ועל כן כתוב בזה באברהם, \u0003אני אל שדי.\u0004 מה שלא כתוב כן מטרם שנצטוה על המילה."]],[[0,"","פָּתַח אַחֵר וְאָמַר, (שמות כ) מִזְבַּח אֲדָמָה תַּעֲשֶׂה לִּי וְזָבַחְתָּ עָלָיו אֶת עֹלֹתֶיךְ וְאֶת שְׁלָמֶיךְ וְגוֹ'. שָׁנִינוּ, כָּל מִי שֶׁמַּקְרִיב אֶת בְּנוֹ לַקָּרְבָּן הַזֶּה, כְּאִלּוּ הִקְרִיב אֶת כָּל הַקָּרְבָּנוֹת שֶׁל הָעוֹלָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וּכְאִלּוּ בָּנָה מִזְבֵּחַ שָׁלֵם לְפָנָיו."],[1,"","מִשּׁוּם כָּךְ צָרִיךְ לְסַדֵּר מִזְבֵּחַ עִם כְּלִי אֶחָד מָלֵא עָפָר לָמוּל עָלָיו אֶת הַבְּרִית הַקָּדוֹשׁ הַזֶּה, וְנֶחְשָׁב לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּאִלּוּ זָבַח עָלָיו עוֹלוֹת וְקָרְבָּנוֹת, צֹאן וּבָקָר."],[2,"","וְנוֹחַ לוֹ יוֹתֵר מִכֻּלָּם, שֶׁכָּתוּב וְזָבַחְתָּ עָלָיו אֶת עֹלֹתֶיךְ וְאֶת שְׁלָמֶיךְ וְגוֹ'. בְּכָל הַמָּקוֹם אֲשֶׁר אַזְכִּיר אֶת שְׁמִי. מַהוּ אַזְכִּיר אֶת שְׁמִי? (את) זוֹ הַמִּילָה, שֶׁכָּתוּב בָּהּ (תהלים כה) סוֹד ה' לִירֵאָיו וּבְרִיתוֹ לְהוֹדִיעָם. מִזְבַּח הָאֲדָמָה הַזֶּה וַדַּאי כְּמוֹ שֶׁאָמַרְנוּ, מַה כָּתוּב אַחֲרָיו?"],[3,"","וְאִם מִזְבַּח אֲדָמָה תַּעֲשֶׂה לִּי. רֶמֶז לַגֵּר כַּאֲשֶׁר מִתְגַּיֵּר, שֶׁהֵם מֵעַם קְשֵׁה עֹרֶף וּקְשֵׁה לֵב. זֶה נִקְרָא מִזְבַּח אֲבָנִים."],[4,"","לֹא תִבְנֶה אֶתְהֶן גָּזִית, מַה זֶּה? שֶׁצָּרִיךְ לְהַכְנִיסוֹ לַעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא, (כדי) וְלֹא יָמוּל אוֹתוֹ, עַד שֶׁיִּשְׁכַּח עֲבוֹדָה הָאַחֶרֶת שֶׁעָבַד עַד עַתָּה, וְיָסִיר מִמֶּנּוּ אוֹתוֹ קְשִׁי הַלֵּב."],[5,"","וְאִם נִמּוֹל וְלֹא הוּסַר מִמֶּנּוּ אוֹתוֹ קְשִׁי הַלֵּב לְהִכָּנֵס לַעֲבוֹדַת הַקֹּדֶשׁ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, הֲרֵי הוּא כְּפֶסֶל הָאֶבֶן הַזֶּה שֶׁגּוֹזְרִים אוֹתוֹ מֵהַצַּד הַזֶּה וּמִן הַצַּד הַזֶּה, וְנִשְׁאָר אֶבֶן כְּבָרִאשׁוֹנָה. מִשּׁוּם כָּךְ לֹא תִבְנֶה אֶתְהֶן גָּזִית. שֶׁאִם הוּא נִשְׁאָר בְּקַשְׁיוּתוֹ - כִּי חַרְבְּךְ הֵנַפְתָּ עָלֶיהָ וַתְּחַלֲלֶהָ. כְּלוֹמַר, אוֹתָהּ הַמִּילָה שֶׁנִּמּוֹל אֵינָהּ מוֹעִילָה לוֹ."],[6,"","מִשּׁוּם כָּךְ, אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁמַּקְרִיב אֶת הַקָּרְבָּן הַזֶּה בְּשִׂמְחָה וּבְרָצוֹן לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. וְצָרִיךְ לִשְׂמֹחַ בַּחֵלֶק הַזֶּה כָּל הַיּוֹם (ההוא), שֶׁכָּתוּב (שם ה) וְיִשְׂמְחוּ כָל חוֹסֵי בָךְ לְעוֹלָם יְרַנֵּנוּ וְתָסֵךְ עָלֵימוֹ וְיַעְלְצוּ בְךְ אֹהֲבֵי שְׁמֶךְ."],[7,"","פָּתַח אַחֵר וְאָמַר, (בראשית יז) וַיְהִי אַבְרָם בֶּן תִּשְׁעִים שָׁנָה וְתֵשַׁע שָׁנִים וַיֵּרָא ה' וְגוֹ', אֲנִי אֵל שַׁדַּי הִתְהַלֵּךְ לְפָנַי וְגוֹ'. בַּפָּסוּק הַזֶּה יֵשׁ לְעַיֵּן בּוֹ, וְקָשֶׁה בְּכַמָּה דְרָכִים. וְכִי עַד עַתָּה לֹא הִתְגַּלָּה הַקָּדוֹשׁ בָּרוּךְ הוּא לְאַבְרָהָם אֶלָּא (עד) כָּעֵת, כְּשֶׁהִגִּיעַ לַיָּמִים הָאֵלֶּה, וַיֵּרָא ה' אֵלָיו וְלֹא קֹדֶם? וַהֲרֵי כָּתוּב וַיֹּאמֶר ה' אֶל אַבְרָם. וַה' אָמַר אֶל אַבְרָם. וַיֹּאמֶר לְאַבְרָם יָדוֹעַ תֵּדַע וְגוֹ', וְכָעֵת מוֹנֶה אֶת חֶשְׁבּוֹן הַיָּמִים, וּכְשֶׁמּוֹנֶה אוֹתָם, כָּתוּב וַיֵּרָא ה' אֶל אַבְרָם, נִשְׁמָע שֶׁעַד עַתָּה לֹא הִתְגַּלָּה עָלָיו! וְעוֹד, שֶׁכָּתוּב בֶּן תִּשְׁעִים שָׁנָה וְתֵשַׁע שָׁנִים. בַּתְּחִלָּה שָׁנָה, וְאַחַר כָּךְ שָׁנִים !:"],[8,"","אֶלָּא כָּךְ שָׁנִינוּ, כָּל אוֹתָם הַיָּמִים לֹא כָתוּב וַיֵּרָא. מָה הַטַּעַם? אֶלָּא כָּל מַה שֶּׁהָיָה אָטוּם וְסָתוּם, (כך) לֹא הִתְגַּלָּה עָלָיו הַקָּדוֹשׁ בָּרוּךְ הוּא כָּרָאוּי. כָּעֵת הִתְגַּלָּה אֵלָיו, שֶׁכָּתוּב וַיֵּרָא. מָה הַטַּעַם? מִשּׁוּם שֶׁרָצָה לְגַלּוֹת בּוֹ הָאוֹת הַזּוֹ, הַכֶּתֶר הַקָּדוֹשׁ."],[9,"","וְעוֹד, כְּשֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהוֹצִיא מִמֶּנּוּ זֶרַע קָדוֹשׁ, וְקָדוֹשׁ לֹא יִהְיֶה כְּשֶׁעֲדַיִן הוּא בְּבָשָׂר אָטוּם, אֶלָּא אָמַר, כָּעֵת שֶׁהוּא בֶּן תִּשְׁעִים וְתֵשַׁע שָׁנִים וְלִזְמַן קָרוֹב הוּא שֶׁיֵּצֵא מִמֶּנּוּ זֶרַע קָדוֹשׁ, שֶׁיִּהְיֶה הוּא קָדוֹשׁ בַּהַתְחָלָה, וְאַחַר כָּךְ יֵצֵא מִמֶּנּוּ זֶרַע קָדוֹשׁ. מִשּׁוּם כָּךְ מָנָה אֶת יָמָיו בָּזֶה, וְלֹא בְּכָל הַזְּמַנִּים הַלָּלוּ שֶׁבַּהַתְחָלָה."],[10,"","עוֹד, תִּשְׁעִים שָׁנָה - שֶׁכָּל יָמָיו הָרִאשׁוֹנִים לֹא הָיוּ שָׁנִים, אֶלָּא כְּשָׁנָה אַחַת, שֶׁלֹּא הָיוּ יָמָיו יָמִים. עַכְשָׁו שֶׁהִגִּיעַ לָזֶה, הֵם שָׁנִים וְלֹא שָׁנָה."],[11,"","וַיֹּאמֶר אֵלָיו אֲנִי אֵל שַׁדַּי. מַה מַּשְׁמִיעַ שֶׁעַד עַכְשָׁו לֹא אָמַר אֲנִי אֵל שַׁדַּי? אֶלָּא כָּךְ שָׁנִינוּ, עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא כְּתָרִים תַּחְתּוֹנִים שֶׁאֵינָם קְדוֹשִׁים לְמַטָּה, וְכָל אוֹתָם שֶׁלֹּא נִמּוֹלִים, נִטְמָאִים בָּהֶם."],[12,"","וּרְשׁוּמִים בָּהֶם. וּמָה הָרִשּׁוּם שֶׁיֵּשׁ בָּהֶם? שֶׁנִּרְאֶה בָהֶם שִׁי\"ן דָּלֶ\"ת וְלֹא יוֹתֵר, וּמִשּׁוּם כָּךְ נִטְמָאִים בָּהֶם וְנִדְבָּקִים בָּהֶם. אַחַר שֶׁנִּמּוֹלִים יוֹצְאִים מֵאֵלּוּ, וְנִכְנָסִים לְכַנְפֵי הַשְּׁכִינָה, וּמִתְגַּלֶּה בָהֶם יוֹ\"ד, הָרֹשֶׁם הַקָּדוֹשׁ, אוֹת הַבְּרִית הַשָּׁלֵם, וְנִרְשָׁם בָּהֶם שַׁדַּ\"י, וְנִשְׁלָמִים בְּקִיּוּם שָׁלֵם, וְעַל כֵּן כָּתוּב בָּזֶה אֲנִי אֵל שַׁדַּי."]]],[["הִתְהַלֶּךָ לְפָנַי וֶהְיֵה תָמִים, שְׁלִים, דְּהַשְׁתָּא אָת חָסֵר בִּרְשִׁימָא דְּשי\"ן וְדל\"ת, גְּזַר גַּרְמָךְ וֶהֱוֵי שְׁלִים בִּרְשִׁימָא דְּיוּ\"ד. וּמַאן דְּאִיהוּ בְּרִשּׁוּמָא דָא אִתְחֲזֵי לְאִתְבָּרְכָא בִּשְׁמָא דָא דִּכְתִיב, (בראשית כ״ח:ג׳) וְאֵל שַׁדַּי יְבָרֵךְ אוֹתְךָ.","מַהוּ אֵל שַׁדַּי. הַהוּא דְּבִרְכָאן נָפְקָן מִנֵּיהּ, הוּא דְּשַׁלִּיט עַל כִּתְרִין תַּתָּאִין, וְכֹלָּא מִדַּחַלְתֵּיהּ דָּחֲלִין וּמִזְדַּעְזְעִין, בְגִין כָּךְ מַאן דְּאִתְגְּזַר, כָּל אִנּוּן דְּלָא קַדִּישִׁין אִתְרַחֲקָן מִנֵּיהּ וְלָא שָׁלְטִין בֵּיהּ. וְלָא עוֹד אֶלָּא דְּלָא נָחִית לַגֵּיהִנֹּם דִּכְתִיב, (ישעיהו ס׳:כ״א) וְעַמֵּךְ כֻּלָּם צַדִּיקִים וְגו'. (כל אנון (צג א) דאתגזרו אקרון צדיקים, ובגין כך לעולם ירשו ארץ, דלא ירית האי ארץ אלא ההוא דאקרי צדיק, אוף הכי ועמך כלם צדיקים לעולם ירשו ארץ וגו)","אָמַר רַבִּי אַבָּא זַכָּאִין אַתּוּן בְּעָלְמָא דֵין וּבְעָלְמָא דְאָתֵי, זַכָּאָה חוּלָקִי דְּאָתֵינָא לְמִשְׁמַע מִלִּין אִלֵּין מִפּוּמֵיכוֹן, כֻּלְכוּ קַדִּישִׁין, כֻּלְכוּ בְּנֵי אֱלָהָא קַדִּישָׁא, עֲלַיְיכוּ כְּתִיב, (ישעיה מה) זֶה יֹאמַר לַיְיָ אָנִי וְזֶה יִקְרָא בְּשֵׁם יַעֲקֹב וְזֶה יִכְתֹּב יָדוֹ לַיְיָ וּבְשֵׁם יִשְׂרָאֵל יְכַנֶּה. כָּל חַד מִנְּכוֹן אָחִיד וְאִתְקַשַּׁר בְּמַלְכָּא קַדִּישָׁא עִלָּאָה, וְאַתּוּן רַבְרְבָן מְמַנָּן תְּרֵיסִין מֵהַהִיא אֶרֶץ דְּאִקְרֵי אֶרֶץ הַחַיִּים דְּרַבְרְבָנוֹהִי אָכְלִין מִמַּנָּא דְטַלָּא קַדִּישָׁא:","פָּתַח אִידָךְ וְאָמַר (קהלת י׳:י״ז) אַשְׁרֵיךָ אֶרֶץ שֶׁמַּלְכֵּךְ בֶּן חוֹרִין וְשָׂרַיִךְ בָּעֵת יֹאכֵלוּ. וּכְתִיב אִי לָךְ אֶרֶץ שֶׁמַּלְכֵּךְ נַעַר וְשָׂרַיִךְ בַּבֹּקֶר יֹאכֵלוּ. הַנֵּי קְרָאֵי קַשְׁיָין אַהֲדָדֵי. וְלָא קַשְׁיָין, הַאי דִּכְתִיב אַשְׁרֵיךְ אֶרֶץ, דָּא אֶרֶץ דִּלְעֵילָא דְּשָׁלְטָא עַל כָּל אִנּוּן חַיִּין דִּלְעֵילָא. וּבְגִין כָּךְ אִקְרֵי אֶרֶץ הַחַיִּים, וְעֲלָהּ כְּתִיב, (דברים י״א:י״ב) אֶרֶץ אֲשֶׁר יְיָ אֱלהֶיךָ דּוֹרֵשׁ אוֹתָהּ תָּמִיד. וּכְתִיב אֶרֶץ אֲשֶׁר לא בְמִסְכֵּנוּת תֹּאכַל בָּהּ לֶחֶם לא תֶחְסַר כֹּל בָּהּ. לא תֶחְסַר כֹּל בָּהּ דַּיְיקָא. וְכָל כָּךְ לָמָּה, מִשּׁוּם דִּכְתִיב שֶׁמַּלְכֵּךְ בֶּן חוֹרִין דָּא קוּדְשָׁא בְּרִיךְ הוּא. כְּמָא דְאַתְּ אָמֵר, (שמות ד) בְּנִי בְּכוֹרִי יִשְׂרָאֵל.","בֶּן חוֹרִין, מַהוּ בֶּן חוֹרִין כְּמָא דְאַתְּ אָמֵר, (ויקרא כ״ה:י׳) יוֹבֵל הִיא קֹדֶשׁ תִּהְיֶה לָכֶם. וּכְתִיב וּקְרָאתֶם דְּרוֹר בָּאָרֶץ דְּהָא כָּל חֵירוּ מִיּוֹבְלָא קָא אָתֵי. בְגִין כָּךְ בֶּן חוֹרִין. וְאִי תֵימָא בֶּן חוֹרִין וְלָא כְּתִיב בֶּן חֵירוּת. הָכִי הוּא וַדַּאי בֶּן חֵירוּת מִבָּעֵי לֵיהּ.","אֶלָּא בְּמַתְנִיתָּא סְתִימָאָה דִילָן תָּנִינָא. כַּד מִתְחַבְּרָן יוּ\"ד בְּה' כְּדֵין כְּתִיב, (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן. וְלָא תֵימָא כַּד מִתְחַבְּרָן, אֶלָּא מִתְחַבְּרָן וַדַּאי. וּבְגִין כָּךְ בֶּן חוֹרִין כְּתִיב, וְעַל דָּא אַשְׁרֵיךְ אֶרֶץ שֶׁמַּלְכֵּךְ בֶּן חוֹרִין, וְשָׂרַיִךְ בָּעֵת יֹאכֵלוּ בְּחֶדְוָותָא בִּשְׁלִימוּ בְּרַעֲוָא.","אִי לָךְ אֶרֶץ שֶׁמַּלְכָּךְ נַעַר, הַאי אֶרֶץ דִּלְתַתָּא, דְּתַנְיָא כָּל שְׁאָר אַרְעֵי דִּשְׁאָר עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת אִתְיְהִיבוּ לְרַבְרְבִין תְּרֵיסִין דִּמְמַנָּן עֲלַיְיהוּ, וְעֵילָא מִכֻּלְהוּ הַהוּא דִּכְתִיב בֵּיהּ (תהילים ל״ז:כ״ה) נַעַר הָיִיתִי גַּם זָקַנְתִּי. וְתָאנָא הַאי קְרָא שָׂרוֹ שֶׁל עוֹלָם אֲמָרוֹ. וְעַל דָּא כְּתִיב אִי לָךְ אֶרֶץ שֶׁמַּלְכֵּךְ נַעַר. וַוי לְעָלְמָא דְּמִסִּטְרָא דָא יָנְקָא, וְכַד יִשְׂרָאֵל בְּגָלוּתָא יַנְקִין כְּמַאן דְּיַנִּיק מֵרְשׁוּתָא אָחֳרָא.","וְשָׂרַיִךָ בַּבֹּקֶר יֹאכֵלוּ וְלָא בְּכוּלֵי יוֹמָא. בַּבֹּקֶר וְלָא בְּזִמְנָא אָחֳרָא דְיוֹמָא. דְּתַנְיָא בְּשַׁעֲתָא דְּחַמָּה זוֹרַחַת וְאַתְיָין וְסָגְדִין לֵיהּ לְשִׁמְשָׁא רוּגְזָא תָּלֵי בְּעָלְמָא, בְּשַׁעֲתָא דְּמִנְחָה רוּגְזָא תַּלְיָיא בְּעָלְמָא. מַאן גָּרִים הַאי, מִשּׁוּם דְּמַלְכֵּךְ נַעַר הַהוּא דְּאִקְרֵי נַעַר.","וְאַתּוּן זַכָּאֵי קְשׁוֹט קַדִּישֵׁי עֶלְיוֹנִין בְּנֵי מַלְכָּא קַדִּישָׁא לָא יָנְקִין מֵהַאי סִטְרָא, אֶלָּא מֵהַהוּא אֲתַר קַדִּישָׁא דִּלְעֵילָא. עֲלַיְיכוּ כְּתִיב, (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּיְיָ אֱלהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם:","פָּתַח רַבִּי אַבָּא וְאָמַר (ישעיהו ה׳:א׳) אָשִׁירָה נָא לִידִידִי שִׁירַת דּוֹדִי לְכַרְמוֹ וְגו'. וַיְעַזְּקֵהוּ וַיְסַקְּלֵהוּ וְגו'. הַנִּי קְרָאֵי אִית לְאִסְתַּכְּלָא בְּהוּ. אַמַּאי כְּתִיב שִׁירָה, תּוֹכָחָה מִבָּעֵי לֵיהּ. לִידִידִי, לְדוֹדִי מִבָּעֵי לֵיהּ. כְּמָה דִּכְתִיב שִׁירַת דּוֹדִי. כֶּרְם הָיָה לִידִידִי בְּקֶרֶן בֶּן שָׁמֶן. אִסְתַּכַּלְנָא בְּכָל אוֹרַיְיתָא וְלָא אַשְׁכַּחְנָא אַתְרָא דְאִקְרֵי קֶרֶן שָׁמֶן."],[[0,"התהלך לפני והיה תמים:","תמים, פירוש שלם. כי עד עתה היה חסר \u0003י'\u0004 ברשימה של \u0003שין דלת,\u0004 לפיכך אמר לו הקב\"ה, מול את עצמך, והיה שלם ברשימה של ה \u0003י'.\u0004 והשם \u0003שדי\u0004 יהיה שלם בך. ומי שהוא שלם ברשימה זאת הוא ראוי להתברך בשם הזה, שכתוב ואל שדי יברך אותך וגו'."],[1,"מהו אל שדי וכו':","ושואל מהו השם אל שדי. ואומר, הוא השם שהברכות יוצאות ממנו. הוא השולט על כל כתרים התחתונים. וכולם יראים ומזדעזעים מפחדו. משום זה, כל מי שנמול כל אלו שאינם קדושים מתרחקים ממנו ואינם שולטים עליו. ולא עוד אלא שאינו יורד לגיהנם, שכתוב, ועמך כלם צדיקים וגו'."],[2,"א\"ר אבא זכאין וכו':","אר\"א, אשריכם בעולם הזה ובעולם הבא. אשרי חלקי שבאתי לשמוע דברים הללו מפיכם. כלכם קדושים. כלכם בני אלקים הקדוש. עליכם כתוב, זה יאמר לה' אני וזה יקרא בשם יעקב וגו'. כל אחד מכם אחוז ונתקשר במלך הקדוש העליון. ואתם שרים ממונים בעלי מגן מאותו ארץ שנקרא ארץ החיים, שה\"ס הנוקבא המלבשת לאמא עלאה, ששריו אוכלים מן המן של הטל הקדוש."],[3,"פתח אידך וכו':","פתח אחר ואמר. אשריך ארץ שמלכך בן חורין וגו'. וכתוב אי לך ארץ שמלכך נער וגו'. מקראות אלו קשים זה על זה. כי ארץ פירושו הנוקבא, וכאן אומר שמלכך בן חורין וכאן אומר שמלכך נער. ומשיב, ולא קשים. זה שכתוב אשריך ארץ וגו'. זהו ארץ שלמעלה, דהיינו הנוקבא שעלה למעלה והלבישה הבינה. השולטת על כל החיים שלמעלה, שבבינה, שמשום זה נקראת ארץ החיים. ועליה כתוב, ארץ אשר ה' אלקיך דורש אותה תמיד. וכתוב ארץ אשר לא במסכנות וגו' לא תחסר כל בה. לא תחסר כל בה הוא בדיוק דהיינו שמקבלת מזווג דלא פסיק. וכל כך למה, הוא משום שכתוב שמלכך בן חורין. זה הקב\"ה, שה\"ס ז\"א כמו שאתה אומר, בני בכורי ישראל. פירוש. בעת שז\"א עולה ומלביש לאו\"א עלאין והנוקבא עולה ומלביש לישסו\"ת. והם פב\"פ, אז נקרא ז\"א ישראל בסו\"ה בני בכורי ישראל. ונקרא בן חורין. והנוקבא נקראת ארץ החיים, ואז נאמר עליה אשר לא תחסר כל בה, כי ז\"א משפיע לה מזווג או\"א דלא פסיק."],[4,"בן חורין, מהו בן חורין וכו':","ושואל, מהו פירושו של בן חורין. ואומר כמש\"א, יובל היא קדש תהיה לכם. ויובל פירושו בינה וכתוב, וקראתם דרור בארץ, הרי שכל חירות באה מיובל, שהיא בינה, משום זה בעת שז\"א יש לו המוחין דבינה נקרא, בן חורין. ומקשה, ואם תאמר, למה כתוב בן חורין ולא בן חרות."],[4,"הכי הוא ודאי וכו':","ומשיב. כן הוא ודאי שהיה צריך לומר בן חירות. פירוש. המוחין דהארת חכמה נקראים חירות, כי על ידי המוחין הללו מכניעים כל הקליפות והס\"א. ומוחין הללו דחכמה מאירים רק ממטה למעלה, (כנ\"ל דף ה' ד\"ה חד) שהוא בחינת ו\"ק דג\"ר, ונבחן לאור נקבה, כי כל אור שאינו מאיר ממעלה למטה, אינו אור זכר. וע\"כ מכונים המוחין \u0003חירות\u0004 מלשון נקבה, ולא \u0003חורין\u0004 שהוא לשון זכר. וז\"ש \u0003הכי הוא ודאי בן חירות מיבעי ליה,\u0004 בי אינם מושפעים ממעלה למטה."],[5,"אלא כמתניתא סתימאה וכו':","אלא למה כתוב בן חורין, במשנה סתומה שלנו למדנו, כאשר \u0003יוד\u0004 עם \u0003ה'\u0004 מתחברים, אז כתוב נהר יוצא מעדן שהוא ז\"א להשקות את הגן. ואל תאמר, כאשר מתחברים, אלא, מתחברים ודאי ומשום זה כתוב בן חורין. פירוש. כי \u0003כאשר מתחברים,\u0004 יורה שזווגם פסיק ולפעמים מתחברים. וכיון שהמדובר הוא באו\"א עלאין שזווגם לא פסיק, לא יתכן לומר \u0003כאשר מתחברים\u0004 אלא \u0003מתחברים ודאי תמיד.\u0004 ואז כשז\"א מקבל מוחין אלו דאו\"א עלאין, שהם מאירים ממעלה למטה הוא נקרא \u0003בן חורין.\u0004 כי או\"א עלאין בעת שהם בזווג עם ישסו\"ת שהם משפיעים אז מוחין דהארת חכמה אליהם, נבחנים אז גם או\"א למוחין דחרות. אע\"פ שהם לפי עצמם, אינם רק חסדים מכוסים והוא מטעם היותם כוללים למוחין דישסו\"ת. ועוד נוסף אליהם שהם משפיעים ממעלה למטה ע\"כ הם נקראים \u0003חורין\u0004 לשון זכר. וע\"כ אומר הכתוב על ז\"א אז, אשריך ארץ שמלכך בן חורין, ושריך בעת יאכלו, דהיינו בשמחה בשלמות וברצון."],[6,"אי לך ארץ שמלכך נער:","היינו ארץ הזו שלמטה, היינו הנוקבא שבבריאה אשת מטטרו\"ן (כנ\"ל בראשית א' דף רכ\"ט ד\"ה ובג\"ד ע\"ש) כי למדנו, כל שאר ארצות של שאר העמים עובדי כוכבים ומזלות, ניתנו לשרים ממונים עליהם, ועליון על כולם הוא אותו שכתוב בו, נער הייתי גם זקנתי, ולמדנו שפסוק זה שרו של עולם אמרו, דהיינו מטטרו\"ן, הנקרא נער. ועליו כתוב, אי לך ארץ שמלכך \u0003נער.\u0004 ווי אל העולם שיונקים מצד זה, דהיינו מצד מטטרו\"ן. וכאשר ישראל בגלות הם יונקים ממנו, כמי שיונק מרשות זר. כי ישראל צריכים לינק מן הקב\"ה ולא ממנו."],[7,"ושריך בבקר יאכלו:","ולא בשאר שעות היום. כי בבוקר, משמע ולא בזמן אחר שביום. כי למדנו, בשעה שהחמה זורחת ובני העולם משתחוים אל השמש, הנה כעס תלוי אז בעולם. וכן בשעת המנחה תלוי כעס בעולם, שאז זמן הדין, (כנ\"ל ב\"א דף ק\"ל ד\"ה תנינא ע\"ש) מי גרם זה, משום דמלכך נער, אותו שנקרא נער, דהיינו מטטרון. כנ\"ל."],[8,"ואתון זכאי וכו':","ואתם צדיקי אמת קדושים עליונים בני המלך הקדוש, אינכם יונקים מאותו הצד של מטטרון, אלא מאותו מקום קדוש שלמעלה, דהיינו הנוקבא דז\"א הנקראת ארץ החיים כנ\"ל, עליכם כתוב, ואתם הדבקים בה' אלקיכם חיים כלכם היום."],[9,"פתח ר' אבא וכו':","פתח ר\"א ואמר. אשירה נא לידידי שירת דודי לכרמו וגו'. מקראות אלו יש להסתכל בהם. למה כתוב שירה, תוכחה היה צריך לכתוב כי דברי תוכחה הם לישראל. ועוד, כתוב \u0003לידידי לדודי היה\u0004 צריך לכתוב כמו שכתוב שירת דודי לכרמו ועוד, כתוב, כרם היה לידידי, \u0003בקרן בן שמן,\u0004 הסתכלתי בכל התורה, ולא מצאתי מקום, שיהיה נקרא קרן בן שמן."]],[[0,"","הִתְהַלֵּךָ לְפָנַי וֶהְיֵה תָמִים. שָׁלֵם. שֶׁכָּעֵת אוֹת חֲסֵרָה בָּרֹשֶׁם שֶׁל שִׁי\"ן וְדָלֶ\"ת. מוֹל אֶת עַצְמְךְ, וֶהְיֵה שָׁלֵם בָּרֹשֶׁם שֶׁל יוֹ\"ד. וּמִי שֶׁהוּא בָּרֹשֶׁם הַזֶּה, רָאוּי לְהִתְבָּרֵךְ בַּשֵּׁם הַזֶּה, שֶׁכָּתוּב (בראשית כח) וְאֵל שַׁדַּי יְבָרֵךְ אוֹתְךְ."],[1,"","מַה זֶּה אֵל שַׁדַּי? הַהוּא שֶׁמִּמֶּנּוּ יוֹצְאוֹת הַבְּרָכוֹת, הוּא שֶׁשּׁוֹלֵט עַל כָּל הַכְּתָרִים הַתַּחְתּוֹנִים, וְהַכֹּל פּוֹחֲדִים מִיִּרְאָתוֹ וּמִזְדַּעְזְעִים. מִשּׁוּם כָּךְ, מִי שֶׁנִּמּוֹל, כָּל אוֹתָם שֶׁאֵינָם קְדוֹשִׁים מִתְרַחֲקִים מִמֶּנּוּ וְלֹא שׁוֹלְטִים בּוֹ, וְלֹא עוֹד, אֶלָּא שֶׁלֹּא יוֹרֵד לַגֵּיהִנֹּם, שֶׁכָּתוּב (ישעיה ס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים וְגוֹ'. (כל אותם שנמולו נקראים צדיקים, ומשום כך לעולם יירשו ארץ, שאין יורש את הארץ הזו אלא ההוא שנקרא צדיק, אף כך, ועמך כלם צדיקים לעולם יירשו ארץ וגו')"],[2,"","אָמַר רַבִּי אַבָּא, אַשְׁרֵיכֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, אַשְׁרֵי חֶלְקִי שֶׁבָּאתִי לִשְׁמֹעַ אֶת הַדְּבָרִים הַלָּלוּ מִפִּיכֶם. כֻּלְּכֶם קְדוֹשִׁים, כֻּלְּכֶם בְּנֵי הָאֱלוֹהַּ הַקָּדוֹשׁ. עֲלֵיכֶם כָּתוּב (שם מד) זֶה יֹאמַר לַה' אָנִי וְזֶה יִקְרָא בְשֵׁם יַעֲקֹב וְזֶה יִכְתֹּב יָדוֹ לַה' וּבְשֵׁם יִשְׂרָאֵל יְכַנֶּה. כָּל אֶחָד מִכֶּם אָחוּז וְקָשׁוּר בַּמֶּלֶךְ הַקָּדוֹשׁ הָעֶלְיוֹן, וְאַתֶּם גְּדוֹלִים מְמֻנִּים מָגִנִּים מֵאוֹתָהּ הָאָרֶץ שֶׁנִּקְרֵאת אֶרֶץ הַחַיִּים, שֶׁגְּדוֹלֶיהָ אוֹכְלִים מִן הַמָּן שֶׁל הַטַּל הַקָּדוֹשׁ."],[3,"","פָּתַח אַחֵר וְאָמַר, (קהלת י) אַשְׁרֵיךְ אֶרֶץ שֶׁמַּלְכֵּךְ בֶּן חוֹרִים וְשָׂרַיִךְ בָּעֵת יֹאכֵלוּ. וְכָתוּב (שם) אֵי לָךְ אֶרֶץ שֶׁמַּלְכֵּךְ נָעַר וְשָׂרַיִךְ בַּבֹּקֶר יֹאכֵלוּ. הַפְּסוּקִים הַלָּלוּ קָשִׁים הֲדָדִית, וְלֹא קָשִׁים. זֶהוּ שֶׁכָּתוּב אַשְׁרֵיךְ אֶרֶץ - זוֹ הָאָרֶץ שֶׁלְּמַעְלָה שֶׁשּׁוֹלֶטֶת עַל כָּל אוֹתָם הַחַיִּים שֶׁלְּמַעְלָה, וּמִשּׁוּם כָּךְ נִקְרֵאת אֶרֶץ הַחַיִּים, וְעָלֶיהָ כָּתוּב (דברים יא) אֶרֶץ אֲשֶׁר ה' אֱלֹהֶיךְ דֹּרֵשׁ אֹתָהּ תָּמִיד. וְכָתוּב אֶרֶץ אֲשֶׁר לֹא בְמִסְכֵּנֻת תֹּאכַל בָּהּ לֶחֶם לֹא תֶחְסַר כֹּל בָּהּ. לֹא תֶחְסַר כֹּל בָּהּ, בִּמְדֻיָּק. וְכָל כָּךְ לָמָּה? מִשּׁוּם שֶׁכָּתוּב שֶׁמַּלְכֵּךְ בֶּן חוֹרִים, זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנֶּאֱמַר (שמות ד) בְּנִי בְכֹרִי יִשְׂרָאֵל."],[4,"","בֶּן חוֹרִים, מַה זֶּה בֶּן חוֹרִים? כְּמוֹ שֶׁנֶּאֱמַר (ויקרא כה) יוֹבֵל הִיא קֹדֶשׁ תִּהְיֶה לָכֶם, וְכָתוּב וּקְרָאתֶם דְּרוֹר בָּאָרֶץ, שֶׁהֲרֵי כָּל הַחֵרוּת בָּאָה מִן הַיּוֹבֵל, וּמִשּׁוּם כָּךְ בֶּן חוֹרִין. וְאִם תֹּאמַר, בֶּן חוֹרִין, וְלֹא כָתוּב בֶּן חֵרוּת - כָּךְ זֶה בְּוַדַּאי. בֶּן חֵרוּת הָיָה צָרִיךְ לִהְיוֹת!"],[5,"","אֶלָּא בְּמִשְׁנָתֵנוּ הַסְּתוּמָה לָמַדְנוּ, כְּשֶׁמִּתְחַבְּרוֹת יוֹ\"ד בְּה', אָז כָּתוּב וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן. וְאַל תֹּאמַר כְּשֶׁמִּתְחַבְּרִים, אֶלָּא וַדַּאי מִתְחַבְּרִים, וּמִשּׁוּם כָּךְ כָּתוּב בֶּן חוֹרִים. וְעַל כֵּן אַשְׁרֵיךְ אֶרֶץ שֶׁמַּלְכֵּךְ בֶּן חוֹרִים, וְשָׂרַיִךְ בָּעֵת יֹאכֵלוּ - בְּשִׂמְחָה, בִּשְׁלֵמוּת וּבְרָצוֹן."],[6,"","אֵי לָךְ אֶרֶץ שֶׁמַּלְכֵּךְ נָעַר - זוֹ הָאָרֶץ שֶׁלְּמַטָּה. שֶׁלָּמַדְנוּ, כָּל שְׁאָר אַרְצוֹת שְׁאָר הָעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה, נִתְּנוּ לִגְדוֹלִים מָגִנִּים שֶׁמְּמֻנִּים עֲלֵיהֶם. וּמֵעַל לְכֻלָּם הַהוּא שֶׁכָּתוּב בּוֹ (תהלים לז) נַעַר הָיִיתִי גַּם זָקַנְתִּי. וְלָמַדְנוּ, הַפָּסוּק הַזֶּה אָמַר אוֹתוֹ שָׂרוֹ שֶׁל עוֹלָם, וְעַל כֵּן כָּתוּב אֵי לָךְ אֶרֶץ שֶׁמַּלְכֵּךְ נָעַר. אוֹי לָעוֹלָם שֶׁיּוֹנֵק מֵהַצַּד הַזֶּה. וּכְשֶׁיִּשְׂרָאֵל בַּגָּלוּת, יוֹנְקִים כְּמִי שֶׁיּוֹנֵק מֵרָשׁוּת אַחֶרֶת."],[7,"","וְשָׂרַיִךָ בַּבֹּקֶר יֹאכֵלוּ - וְלֹא בְּכָל הַיּוֹם. בַּבֹּקֶר - וְלֹא בִּזְמַן אַחֵר שֶׁל הַיּוֹם. שֶׁשָּׁנִינוּ, בְּשָׁעָה שֶׁהַחַמָּה זוֹרַחַת וּבָאִים וְסוֹגְדִים לַשֶּׁמֶשׁ, הָרֹגֶז תָּלוּי בָּעוֹלָם. בִּשְׁעַת הַמִּנְחָה הָרֹגֶז תָּלוּי בָּעוֹלָם. מִי גָרַם אֶת זֶה? מִשּׁוּם שֶׁמַּלְכֵּךְ נָעַר, הַהוּא שֶׁנִּקְרָא נַעַר."],[8,"","וְאַתֶּם צַדִּיקֵי הָאֱמֶת, קְדוֹשִׁים עֶלְיוֹנִים, בְּנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, אֵין יוֹנְקִים מִן הַצַּד הַזֶּה, אֶלָּא מֵאוֹתוֹ הַמָּקוֹם הַקָּדוֹשׁ שֶׁלְּמַעְלָה. עֲלֵיכֶם כָּתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם."],[9,"","פָּתַח רַבִּי אַבָּא וְאָמַר, (ישעיה ה) אָשִׁירָה נָּא לִידִידִי שִׁירַת דּוֹדִי לְכַרְמוֹ וְגוֹ', וַיְעַזְּקֵהוּ וַיְסַקְּלֵהוּ וְגוֹ'. בַּפְּסוּקִים הַלָּלוּ יֵשׁ לְהִתְבּוֹנֵן, לָמָּה כָּתוּב שִׁירָה? הָיָה צָרִיךְ לִהְיוֹת תּוֹכָחָה! לִידִידִי? הָיָה צָרִיךְ לִהְיוֹת לְדוֹדִי, כְּמוֹ שֶׁכָּתוּב שִׁירַת דּוֹדִי. כֶּרֶם הָיָה לִידִידִי בְּקֶרֶן בֶּן שָׁמֶן?"]]],[["אֶלָּא הַנִּי קְרָאֵי הָא אוּקְמוּהָ חַבְרַיָיא בְּכַמָּה גְוָונִין וְכֻלְהוּ שַׁפִּיר וְהָכִי הוּא, אֲבָל אָשִׁירָה נָא לִידִידִי, דָּא יִצְחָק דְּהֲוָה יְדִיד, וְאִקְרֵי יְדִיד עַד לָא יִפּוּק לְעָלְמָא.","אַמַּאי יְדִיד, דְּתָנִינָן רְחִימוּ סַגֵּי הֲוָה לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא בֵּיהּ דְּלָא אִתְעֲבִיד עַד דְּלָא אִתְגְּזַר אַבְרָהָם אֲבוּהָ וְאִקְרֵי שְׁלִים וְאִתּוֹסַף לֵיהּ ה\"א לְאַשְׁלָמוּתָא. וְכֵן לְשָׂרָה הַאי ה\"א אִתְיְהִיבַת לָהּ.","הָכָא אִית לְאִסְתַּכָּלָא, ה' לְשָׂרָה שַׁפִּיר, אֲבָל לְאַבְרָהָם אַמַּאי ה\"א וְלָא יו\"ד, י' מִבָּעֵי לֵיהּ דְּהָא הוּא דְּכַר הֲוָה. אֶלָּא רָזָא עִלָּאָה הֲוָה (ד\"א הוא) סָתִים בְּגַוָּון אַבְרָהָם סָלִיק לְעֵילָא וְנָטִיל רָזָא (קי א) מֵה\"א עִלָּאָה דְּאִיהוּ עָלְמָא דִדְכוּרָא. ה\"א עִלָּאָה וְה\"א תַּתָּאָה, הַאי תַּלְיָא בִּדְכוּרָא, וְהַאי בְּנוּקְבָא וַדַּאי. וּבְגִין כָךְ אַבְרָהָם סָלִיק בְה\"א דְעֵילָא, וְשָׂרָה נָחֲתָא בְה\"א דְּלְתַתָּא.","תוּ דִּכְתִיב כֹּה יִהְיֶה זַרְעֶךָ. וְתָנָא זַרְעֶךָ, זַרְעֶךָ מַמָּשׁ, דְּהֲוָה שָׁארֵי לְמֵיעַל בְּהַאי קְיָים, וּמָאן דְּשָׁארֵי לְמֵיעַל בְּהַאי קְיָים עָאל. וּבְגִינֵי כָךְ גִּיּוֹרָא דְּאִתְגְּזַר (שלח לך קסה) גֵּר צֶדֶק אִקְרֵי בְּגִין דְּלָא אֲתָא מִגִּזְעָא קַדִּישָׁא דְּאִתְגְּזָרוּ, וְעַל דָּא מַאן דְּעָאל בְּהַאי שְׁמֵיהּ כְּהַאי","אַבְרָהָם, בְגִין כָּךְ כְּתִיב בֵּיהּ כֹּה יִהְיֶה זַרְעֶךָ, זַרְעֶךָ מַמָּשׁ. וְאִתְמָסַר לֵיהּ ה\"א. וְאִי לָאו דִּאִתְמָסַר ה\"א לְשָׂרָה הֲוָה לֵיהּ לְאַבְרָהָם לְאוֹלִיד לְתַתָּא כְּמָה דְּהַאי כ\"ה אוֹלִידַת לְתַתָּא. בָּתַר דְּאִתְמַסְרַת ה\"א לְשָׂרָה אִתְחַבָּרוּ תְּרֵין ההי\"ן כְּחֲדָא וְאוֹלִידוּ לְעֵילָא, וּמַאי דְּנָפַק מִנַּיְיהוּ הוּא יו\"ד, בְּגִינִי כָךְ יו\"ד אָת רֵישָׁא דְּיִצְחָק דְּכַר. מִכָּאן שָׁארֵי דְכוּרָא לְאִתְפַּשְּׁטָא, וְעַל דָּא כְּתִיב, (בראשית כ״א:י״ב) כִּי בְיִצְחָק יִקָּרֵא לְךָ זָרַע. בְּיִצְחָק וְלָא בְּךָ. יִצְחָק אוֹלִיד לְעֵילָא דִּכְתִיב, (מיכה ז׳:כ׳) תִּתֵּן אֱמֶת לְיַעֲקֹב. יַעֲקֹב אַשְׁלִים כֹּלָּא.","וְאִי תֵימָא וְכִי אַבְרָהָם בְּהַאי אִתְאַחִיד וְלָא יַתִּיר, וְהָא כְּתִיב חֶסֶד לְאַבְרָהָם. אֶלָּא חוּלָקָא דִילֵיהּ כָּךְ הוּא בְּגִין דְּעֲבִיד חֶסֶד עִם בְּנֵי עָלְמָא. אֲבָל לְאוֹלָדָא הָכָא אָחִיד וּמֵהָכָא שָׁארֵי. וְעַל דָּא לָא אִתְגְּזַר אַבְרָהָם אֶלָּא בֶּן תִּשְׁעִים וְתֵשַׁע שָׁנָה. וְרָזָא דְמִלָּה הָא אִתְיְידַע וְאוֹקִימְנָא בְּמַתְנִיתָּא דִילָן.","וּבְגִין כָּךְ יִצְחָק דִּינָא קַשְׁיָא נָפַק לְאַחֲדָא לְחוּלָקֵיהּ, וּלְאוֹלָדָא וְחֶסֶד אִקְרֵי, וְעַל דָּא יַעֲקֹב אַשְׁלִים כֹּלָּא מֵהַאי סִטְרָא וּמֵהַאי סִטְרָא, מִסִּטְרָא דְּאֲחִידוּ אַבְרָהָם וְיִצְחָק לְחוּלָקֵיהוֹן לְעֵילָא הוּא שְׁלֵימוּתָא. מִסִּטְרָא דְּאִתְיְהִיב לְהוּ לְאוֹלָדָא מִתַּתָּא לְעֵילָא הוּא שְׁלֵמוּתָא. וְעַל דָּא כְּתִיב, (ישעיהו מ״ט:ג׳) יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאַר. בֵּיהּ אִתְאֲחִידוּ גְּוָונִין מֵעֵילָא וּמִתַּתָּא.","וְעַל דָּא כְּתִיב הָכָא שִׁירָה דִּכְתִיב, (ישעיהו ה׳:א׳) אָשִׁירָה נָא לִידִידִי. שִׁירָה וַדַּאי, דְּהָא אִקְרֵי לְאוֹלָדָא דְּכַר, דְּהָא אִקְרֵי יְדִיד עַד לָא יִפּוּק לְעָלְמָא.","וְאִית דְּאָמְרֵי (דא) אָשִׁירָה נָא לִידִידִי דָּא אַבְרָהָם כְּמָא דְאַתְּ אָמֵר, (ירמיהו י״א:ט״ו) מַה לִּידִידִי בְּבֵיתִי. וְאַבְרָהָם יָרִית יְרוּתָא דְּאַחְסָנַת חוּלָקָא דָא, אֲבָל (על) מַה דְּאֲמִינָא דְּדָא יִצְחָק הָכִי הוּא.","שִׁירַת דּוֹדִי לְכַרְמוֹ. דָּא קוּדְשָׁא בְּרִיךְ הוּא דְּאִקְרֵי דּוֹדִי דִּכְתִיב, (שיר השירים ה׳:י׳) דּוֹדִי צַח וְאָדוֹם. יְדִידִי, אָחִיד בְּדוֹדִי דְּכַר וּמִנֵּיהּ אִתְנְטַע כֶּרֶם, דִּכְתִיב כֶּרְם הָיָה לִידִידִי.","בְּקֶרֶן בֶּן שָׁמֶן. מַאי בְּקֶרֶן בֶּן שָׁמֶן. אֶלָּא בְּמָּה נָפִיק הַאי כֶּרְם וּבְמָּה אִתְנְטַע, חָזַר וְאָמַר בְּקֶרֶן. מַאי קֶרֶן דִּכְתִיב, (יהושע ו׳:ה׳) בְּקֶרֶן הַיּוֹבֵל. בְּקֶרֶן הַיּוֹבֵל. שָׁארֵי. וְהַאי קֶרֶן אִתְאַחִיד בְּהַהוּא דְּכַר דְּאִקְרֵי בֶּן שָׁמֶן.","מַהוּ בֶּן שָׁמֶן כְּמָא דְאַתְּ אָמֵר בֶּן חוֹרִין. וְתַרְוַויְיהוּ חַד מִלָּה, שֶׁמֶן דְּמִתַּמָּן נְגִיד מִשְׁחָא וּרְבוּ לְאַדְלָקָא בּוֹצִינִין, וּבְגִין כָּךְ בֶּן שָׁמֶן. וְדָא שֶׁמֶן וּרְבוּ נְגִיד וּנְפִיק וְאַדְלִיק בּוֹצִינִין עַד דְּנָטִיל לֵיהּ וְכָנִישׁ לֵיהּ הַאי קֶרֶן, וְדָא אִקְרֵי קֶרֶן הַיּוֹבֵל. בְּגִינֵי כָךְ לֵית מְשִׁיחוּתָא דְמַלְכוּתָא אֶלָּא בְּקֶרֶן, וְעַל דָּא אִתְמְשַׁךְ מַלְכוּתָא דְּדָוִד דְּאִתְמְשַׁח בְּקֶרֶן וְאִתְאַחִיד בֵּיהּ."],[[0,"אלא הני וכו':","ומשיב. אלא מקראות אלו בארו אותם החברים באופנים שונים וכולם יפים, וכן הוא. אבל אשירה נא לידידי, זה יצחק, שהיה ידיד ונקרא ידיד מטרם שיצא לעולם. דהיינו שאנו אומרים עליו, אשר קדש ידיד מבטן."],[1,"אמאי ידיד וכו':","ושואל, למה נקרא יצחק ידיד. ואומר, כי למדנו אהבה גדולה היה להקב\"ה אל יצחק, שלא נעשה, עד שנמול אברהם אבינו, ונקרא תמים, כי אז נאמר לו, והיה תמים, ונתוסף \u0003ה'\u0004 לשמו להשלמה, וכן לשרה ניתן ה' זו. שהוא נקרא אברהם, והיא שרה."],[2,"הכא אית וכו':","כאן יש להסתכל. \u0003ה'\u0004 שניתנה לשרה, נכון הוא, אבל לאברהם, למה ניתנה לו \u0003ה'\u0004 ולא \u0003י', י'\u0004 היה צריך להתוסף בשמו, כי הוא זכר, ובחינת \u0003י'\u0004 שייכת לזכר, ובחינת \u0003ה'\u0004 שייכת לנקבה. ומשיב אלא סוד עליון הוא סתום גוון. אברהם עלה למעלה ילקח סוד מה\"א עליונה, בינה, שהיא עולם זכר. כי ה\"א עליונה וה\"א תחתונה, שבשם הויה, זו תלויה בזכר, דהיינו ה' ראשונה, וזו תלויה בנקבה, דהיינו \u0003ה'\u0004 אחרונה. ו \u0003ה'\u0004 שלקח אברהם, היא \u0003ה'\u0004 ראשונה שהיא זכר דהיינו בינה."],[2,"","פנימיות הדברים. נודע שאברהם יצחק ויעקב, ה\"ס ג' קוין הנמשכים מג' הנקודות, חולם שורק וחירק. (כנ\"ל ב\"א דף ק\"ל ד\"ה וזהו) וזו\"ן ה\"ס קו אמצעי, שה\"ס נקודת החירק. ובב' הקוין ימין ושמאל שה\"ס חולם שורק, אין לזו\"ן בהם כלום, כי ה\"ס \u0003מ\"י אל\"ה\u0004 שבשם אלקים שבבינה. אלא מתוך ד \u0003תלת נפקי מחד,\u0004 שג' קוין דבינה יצאו ע\"י מסך דחירק של זו\"ן, על כן, \u0003חד בתלת קיימא,\u0004 זכו זו\"ן גם הם בב' הקוין ימין ושמאל דבינה שעם קו אמצעי שבהם עצמם הם ג' קוין. כי כל השיעור שהתחתון גורם שיאיר בהעליון זוכה בו גם הוא. (כנ\"ל ב\"א דף רפ\"ז ד\"ה תלת) וז\"ש, \u0003ואקרי ידיד עד לא יפוק בעלמא,\u0004 (באות תנ\"ג) כי \u0003ידיד,\u0004 ה\"ס קו שמאל, ששם אהבת דודים, וכל הנשמות נמשכות מזו\"ן שנקראים \u0003עלמא,\u0004 וא\"כ קשה, הרי מציאות קו השמאל אינו \u0003בעלמא,\u0004 שהוא זו\"ן, אלא בבינה. לפיכך אומר, שיצחק נמשך מבינה \u0003עד לא יפוק לעלמא,\u0004 מטרם שבא לזו\"ן, כלומר. שאע\"פ שיוצא מזו\"ן, מ\"מ אין לידתו אלא מבחינת בינה, ששם מציאות קו השמאל, אלא שיוצא דרך זו\"ן בבחינת העברה. כי להיות הנשמות מדרגה תחתונה מזו\"ן, הן מחויבות לעבור דרך זו\"ן, אע\"פ ששורשם מבינה."],[2,"","וזה ששואל \u0003אמאי ידיד\u0004 (באות תנ\"ד) כלומר, כיון שיוצא מזו\"ן, ונולד מאברהם, איך אפשר שיצחק יהיה נמשך מקו שמאל שנקרא \u0003ידיד,\u0004 אחר שהוא תולדה מזו\"ן ומאברהם, שכבר הם מבחינת מסך דחירק, שהוא קו אמצעי. וזהו שמשיב, \u0003רחימי סגי וכו', ואתוסף ליה ה' לאשלמותא וכן לשרה וכו', אברהם סליק לעילא ונטיל רזא מה\"א עלאה וכו'.\u0004 כי סוד \u0003ה'\u0004 שנתוסף לו על שמו, הוא בינה, ויורה, שאברהם עלה למעלה אל הבינה ולקח סוד הבינה עצמה, ושם בעודו בבינה הוליד את יצחק, כי הוא הלביש שם את קו ימין דבינה, שה\"ס חולם, והוליד את יצחק בסוד קו שמאל דבינה, שה\"ס שורק. וע\"כ יצא יצחק בבחינת ידיד, שהוא קו שמאל דבינה שלמעלה מזו\"ן. ואיך נעשה זה, מבאר בסמוך באות תנ\"ז."],[3,"דכתיב כה יהיה זרעך:","ולמדנו זרעך, זרעך ממש. כלומר, כה, שהיא המלכות, תהיה זרע ממש שלו. כי היה מתחיל להכנס בברית הזה, וכל המתחיל להכנס, נכנס בברית הזה, שהיא המלכות, הנקראת \u0003כה,\u0004 ומשום זה גר שנמול נקרא \u0003גר צדק,\u0004 שהוא משום, שאינו בא מגזע קדוש שנמולו, והוא המתחיל להכנס בברית, וכל מתחיל נכנס במלכות, ועל כן מי שנכנס בזו דהיינו במלכות הנקראת \u0003צדק,\u0004 שמו כזו, נקרא שמו \u0003גר צדק.\u0004"],[4,"אברהם, בגין כך וכו':","אברהם, משום זה כתוב בו, כה יהיה זרעך, שפירושו, זרעך ממש. כי \u0003כה,\u0004 שהיא ה' תתאה, דהיינו המלכות, תהיה לך זרע ממש. ומבאר איך נעשה לו המלכות לזרע, ואומר, \u0003אתחברו תרין ההין כחדא,\u0004 ב' ההין, שהן בינה ומלכות, נתחברו יחד, כלומר לאחר שאברהם עלה ל \u0003ה'\u0004 ראשונה כנ\"ל עלתה אליו \u0003ה'\u0004 תחתונה שהיא מלכות ונתחברו שתיהן יחדיו. ואז \u0003ואולידו לעילא\u0004 והולידו למעלה בבינה, ב' קוין מ\"י אל\"ה. כי תחלה על ידי עלית המלכות לבינה, נפלו אתוון \u0003אל\"ה\u0004 דבינה, ונשארה בב' אותיות \u0003מ\"י\u0004 דאלקים. שזה נבחן לכניסת י' באור הבינה ונעשה \u0003אור לאויר.\u0004 וה\"ס נקודת החולם. ואח\"כ ירדה המלכות מהבינה למקומה וחזרו אתוון אל\"ה להבינה ונעשו קו שמאל, שהוא סוד נקודת השורק, (כנ\"ל ב\"א דף מ\"ה ד\"ה כיון ע\"ש) \u0003ומאי דנפק מנייהו,\u0004 ומה שיוצא מהם, בעת לידת קו שמאל, \u0003הוא יוד,\u0004 דהיינו ה \u0003י'\u0004 שיוצאת מ \u0003אויר\u0004 הבינה וחזרה הבינה להיות \u0003אור\u0004 ג\"ר. (כנ\"ל ב\"א דף מ\"ה ד\"ה כיון ע\"ש) \u0003בגיני כך י' אות רישא דיצחק, דכר.\u0004 משום זה אות ראשונה של השם יצחק הוא \u0003י'\u0004 שהוא בחינת זכר, כי \u0003מכאן שרי דכורא לאתפשטא.\u0004 כי מסוד ה \u0003י'\u0004 מתחיל הזכר להתפשט, זכר, פירושו מוחין דג\"ר. שמתפשט ע\"י יציאת הי' מ \u0003אויר. ועל דא כתיב כי ביצחק יקרא לך זרע ביצחק ולא בך.\u0004 ועל כן כתוב ביצחק יקרא לך זרע, דהיינו דוקא ביצחק שה\"ס קו שמאל ואתוון \u0003אל\"ה\u0004 שחזרו אל הבינה, וכן \u0003י'\u0004 שיצאה מ \u0003אויר\u0004 והבינה חזרה להיות אור ג\"ר. אבל לא בך, כי באברהם עצמו לבדו אין שלמות, שה\"ס \u0003מ\"י\u0004 דאלקים שנתמעט מחמת עלית ה\"ת לה' ראשונה, ונעשה לבחינת ו\"ק כנ\"ל. אלא בעת לידת קו שמאל שהוא יצחק חזר גם אברהם לבחינת ג\"ר. וזהו שמדייק הכתוב ביצחק דוקא יקרא לך זרע, ותשיג על ידו השלמות, ולא בך, כי בך עצמך אין ג\"ר בלי יצחק."],[4,"יצחק אוליד לעילא וכו'","יצחק הוליד למעלה שכתוב, תתן אמת ליעקב. יעקב השלים הכל, פירוש. אע\"פ שיעקב הוא בחינת קו אמצעי דהיינו ז\"א, ולפי\"ז לא היה צריך להולד למעלה במקום בינה, כמו יצחק. אמנם לפי שיעקב השלים הכל, כי לולא קו אמצעי, לא היו ב' הקוין שבבינה יכולים להאיר. (כנ\"ל ב\"א דף ק\"ל ד\"ה תליתאה) לפיכך הוליד יצחק את יעקב למעלה במקום בינה, ויעקב נעשה שם דעת המכריע בין חכמה ובינה שהם אברהם יצחק."],[5,"ואי תימא וכו':","ואם תאמר, וכי אברהם נתאחד בזה, דהיינו שנכלל בבחינת קו שמאל דיצחק, ולא יותר, והרי כתוב, חסד לאברהם, הרי שנאחז בימין. ומשיב אלא חלק שלו כך הוא, דהיינו חסד, משום שעשה חסד עם בני העולם. אבל להוליד נאחז כאן דהיינו שנכלל בקו שמאל, ומכאן מתחיל כי אין הולדה אלא מבחינת הארת חכמה, שהוא מושג על ידי התכללות ימין בשמאל. שז\"ס ביצחק יקרא לך זרע, ולא בך. (כנ\"ל בסמוך בד\"ה אברהם.) ועל כן לא נמול אברהם אלא בן צ\"ט שנים. וסוד הדבר נודע, ונתבאר במשנה שלנו. והסוד הוא כי מאה שנה ה\"ס עשר ספירות שבכל אחת עשר. ובהכלים דע\"ס, העליונים נגדלים תחילה, דהיינו שמתחיל בכתר ומסיים במלכות. ונמצא שנת המאה שה\"ס מלכות דמלכות, שתקונה קשה מאד, וע\"כ נמול אברהם בשנת הצ\"ט, כדי שיוכל לתקן את שנת המאה."],[6,"ובגין כך יצחק וכו':","ומשום זה יצחק שהוא דין קשה, שהוא קו שמאל שנסתם מחמת חסרון הלבוש של חסדים (כנ\"ל ב\"א דף ק\"ל ד\"ה תנינא) יצא להשלים את חלקו ולהוליד את קו האמצעי שהוא יעקב, ונקרא חסד, דהיינו שתמשיך קומת חסדים על מסך דחירק, שה\"ס קו אמצעי הנקרא יעקב, שהרבה החסדים, ואז נכללו ימין ושמאל זב\"ז, כנודע. ועל כן יעקב השלים הכל מצד הימין ומצד השמאל: מצד שנכללו אברהם ויצחק בחלקיהם למעלה ע\"י יעקב שהוא קו אמצעי, שבזה נשלמו החסדים שבימין הוא שלימות אחד של יעקב. ומצד שניתן להם להוליד ממטה למעלה הוא שלמות ב' ליעקב. כלומר מצד, שנשלם החכמה שבשמאל, על ידי התלבשות בחסדים שבימין, שאז החכמה מאירה ממטה למעלה, ונעשה ראוי להוליד כנ\"ל. שכל זה נשלם ע\"י יעקב, הריהו שלימות ב' של יעקב. הרי שיעקב השלים \u0003מהאי סטרא ומהאי סטרא,\u0004 מצד הימין ומצד השמאל. כמבואר. ועל כן כתוב, \u0003ישראל אשר בך אתפאר.\u0004 כי בו בישראל נשלמו הגוונים, דהיינו האורות מלמעלה ומלמטה."],[7,"ועל דא כתיב וכו':","ועל כן כתוב כאן שירה, שכתוב אשירה נא לידידי. ולא תוכחה, כנ\"ל (באות תנ\"ב) הוא שירה ודאי, כי נקרא להוליד זכר. כלומר, בשביל שהזכיר \u0003לידידי,\u0004 יורה על הולדת זכר, שהוא יצחק, שהוא מוחין דקו שמאל מבינה, שהוא \u0003עלמא דדכורא,\u0004 (כנ\"ל באות תנ\"ה) \u0003דהא אקרי ידיד עד לא יפוק לעלמא.\u0004 כי יצחק נקרא ידיד, מטרם שיוצא דרך זו\"ן הנקראים עולם, דהיינו בעודו בחינת קו שמאל בבינה (כנ\"ל באות תנ\"ג) וע\"כ הוא דכר כמו בינה. ולפיכך כתיב כאן אשירה כי בדכר שהוא ג\"ר, נוהג שירה."],[8,"ואית דאמרי וכו':","ויש אומרים, אשר אשירה נא לידידי, זה אברהם. כמו שאתה אומר, מה לידידי בביתי, שהוא אברהם, כן ידידי שבכאן הוא אברהם. ואברהם ירש ירושה של נחלת שדה זו, שהיא המלכות, המכונה כאן כרם, שאומר עליה שירת דודי לכרמו אבל, אומר ר' אבא, מה שאמרתי שהוא יצחק כן הוא. דאחסנת חולקא, פירושו, נחלת שדה, כי, ובשדי יתומים, מתרגמינן ובחלקא דיתמי. (משלי כ\"ג י')."],[9,"שירת דודי לכרמו:","דודי, זה הקב\"ה שנקרא דודי, שכתוב, דודי צח ואדום. כשידידי נאחז בדודי, הוא דכר. פירוש דודי הוא ז\"א, והוא נאחז בידידי שהוא קו שמאל דבינה, בעת שז\"א משמש שם לקו אמצעי, ואז יש לז\"א מוחין הללו דבינה שהוא דכר. ואז \u0003ומניה אתנטע כרם,\u0004 וממנו, בהארת השמאל דבינה, נטע כרם, שהיא המלכות ונוקבא דז\"א. שכתוב, כרם היה לידידי. כי היא נבנית משמאל דבינה."],[10,"בקרן בן שמן:","ושואל, מהו בקרן בן שמן. ואומר, אלא ללמדינו במה יצא ונולד כרם הזה ובמה נטע, חוזר ואומר \u0003בקרן.\u0004 מהו קרן. הוא שכתוב, בקרן היובל, שפירושו מלכות ממותקת בבינה. כי קרן היא מלכות, ויובל היא בינה. \u0003וקרן הזה\u0004 שבכאן, נתאחד בדכר הזה הנקרא בן שמן, שהיא גם כן בינה. ומשמיענו הכתוב בזה, שכל יציאתו ונטיעתו של הכרם שהיא מלכות, נעשה בסבת עליתה אל הבינה, שהיא דכר, כמו שמפרש לפנינו בסדר הכתובים ויעזקהו ויסקלהו."],[11,"מהו בן שמן וכו':","ושואל, מה פירושו של בן שמן. ואומר שהוא כמו שאתה אומר בן חורין. שפירושו בינה. ושניהם, בן שמן ויובל דבר אחד הוא, דהיינו בינה, ונקרא שמן כי משם, מבינה, נמשך שמן וגדלות להדליק הנרות, עד שקרן הזה, שהיא מלכות, לוקחת ומאספת אותם. וזה נקרא גם כן, קרן היובל. ומשום זה, נמשכה מלכות בית דוד משום שנמשח בקרן, ונתאחד בו. (כמ\"ש במסכת מגילה יד. ע\"ש.)"]],[[0,"","הִסְתַּכַּלְתִּי בְּכָל הַתּוֹרָה וְלֹא מָצָאתִי מָקוֹם שֶׁנִּקְרָא בֶּן שָׁמֶן. אֶלָּא אֶת הַפְּסוּקִים הַלָּלוּ בֵּאֲרוּ הַחֲבֵרִים בְּכַמָּה צוּרוֹת, וְהַכֹּל יָפֶה וְכָךְ זֶה. אֲבָל אָשִׁירָה נָּא לִידִידִי - זֶה יִצְחָק, שֶׁהָיָה יָדִיד, וְנִקְרָא יָדִיד טֶרֶם שֶׁיָּצָא לָעוֹלָם."],[1,"","לָמָּה יָדִיד? שֶׁשָּׁנִינוּ, אַהֲבָה רַבָּה הָיְתָה לַקָּדוֹשׁ-בָּרוּךְ-הוּא בּוֹ שֶׁלֹּא נַעֲשָׂה טֶרֶם שֶׁנִּמּוֹל אַבְרָהָם אָבִיו, וְנִקְרָא שָׁלֵם, וְנוֹסְפָה לוֹ הֵ\"א לְהַשְׁלִימוֹ, וְכֵן לְשָׂרָה הֲרֵי נִתְּנָה לָהּ הֵ\"א הַ את."],[2,"","כָּאן יֵשׁ לְהִתְבּוֹנֵן, ה' לְשָׂרָה זֶה יָפֶה, אֲבָל לְאַבְרָהָם לָמָּה הֵ\"א וְלֹא יוֹ\"ד? יוֹ\"ד הָיָה צָרִיךְ לִכְתֹּב, שֶׁהֲרֵי הוּא הָיָה זָכָר. אֶלָּא סוֹד עֶלְיוֹן הָיָה (הוא) סָתוּם אֶצְלֵנוּ אַבְרָהָם עָלָה לְמַעְלָה, וְנָטַל סוֹד מֵהֵ\"א הָעֶלְיוֹנָה שֶׁהִיא הָעוֹלָם שֶׁל הַזָּכָר. הֵ\"א הָעֶלְיוֹנָה וְהֵ\"א הַתַּחְתּוֹנָה, זוֹ תְּלוּיָה בַּזָּכָר וְזוֹ וַדַּאי בַּנְּקֵבָה. וּמִשּׁוּם כָּךְ אַבְרָהָם עָלָה בַּהֵ\"א שֶׁלְּמַעְלָה, וְשָׂרָה יָרְדָה בַּהֵ\"א שֶׁלְּמַטָּה."],[3,"","עוֹד, שֶׁכָּתוּב כֹּה יִהְיֶה זַרְעֶךְ, וְלָמַדְנוּ זַרְעֶךְ - זַרְעֲךְ מַמָּשׁ, שֶׁהָיָה מַתְחִיל לְהִכָּנֵס בַּבְּרִית הַזּוֹ. וּמִי שֶׁמַּתְחִיל לְהִכָּנֵס בַּבְּרִית הַזּוֹ - נִכְנָס. וּמִשּׁוּם כָּךְ הַגֵּר שֶׁמִּתְגַּיֵּר נִקְרָא גֵר צֶדֶק, מִשּׁוּם שֶׁלֹּא בָא מִגֶּזַע קָדוֹשׁ שֶׁנִּמּוֹלוּ. וְעַל כֵּן, מִי שֶׁנִּכְנָס בָּזֶה - שְׁמוֹ כָּזֶה:"],[4,"","אַבְרָהָם. מִשּׁוּם כָּךְ כָּתוּב בּוֹ כֹּה יִהְיֶה זַרְעֶךְ, זַרְעֲךְ מַמָּשׁ, וְנִמְסַר לוֹ הֵ\"א. וְאִם לֹא נִמְסְרָה הֵ\"א לְשָׂרָה, הָיָה לוֹ לְאַבְרָהָם לְהוֹלִיד לְמַטָּה, כְּמוֹ שֶׁהַכֹּה הַזּוֹ מוֹלִידָה לְמַטָּה. אַחַר שֶׁנִּמְסְרָה לְשָׂרָה הֵ\"א, הִתְחַבְּרוּ שְׁתֵּי הֵהִי\"ן יַחַד וְהוֹלִידוּ לְמַעְלָה, וּמַה שֶּׁיָּצָא מֵהֶם הוּא יוֹ\"ד. מִשּׁוּם כָּךְ יוֹ\"ד אוֹת הָרֹאשׁ שֶׁל יִצְחָק, זָכָר. מִכָּאן מַתְחִיל הַזָּכָר לְהִתְפַּשֵּׁט, וְעַל כֵּן כָּתוּב (בראשית כא) כִּי בְיִצְחָק יִקָּרֵא לְךְ זָרַע. בְּיִצְחָק וְלֹא בְּךְ. יִצְחָק הוֹלִיד לְמַעְלָה, שֶׁכָּתוּב (מיכה ז) תִּתֵּן אֱמֶת לְיַעֲקֹב, וְיַעֲקֹב הִשְׁלִים הַכֹּל."],[5,"","וְאִם תֹּאמַר, וְכִי אַבְרָהָם בָּזֶה נֶאֱחַז וְלֹא יוֹתֵר, וַהֲרֵי כָּתוּב חֶסֶד לְאַבְרָהָם? אֶלָּא חֶלְקוֹ כָּךְ הוּא, מִשּׁוּם שֶׁעָשָׂה חֶסֶד עִם בְּנֵי הָעוֹלָם. אֲבָל לְהוֹלִיד - כָּאן הוּא אָחוּז וּמִכָּאן מַתְחִיל, וְעַל כֵּן לֹא נִמּוֹל אַבְרָהָם אֶלָּא בֶּן תִּשְׁעִים וְתֵשַׁע שָׁנָה, וְסוֹד הַדָּבָר הֲרֵי יָדוּעַ, וּבֵאַרְנוּהוּ בְמִשְׁנָתֵנוּ."],[6,"","וּמִשּׁוּם כָּךְ יִצְחָק, הַדִּין הַקָּשֶׁה, יָצָא לֶאֱחֹז לְחֶלְקוֹ וּלְהוֹלִיד, וְנִקְרָא חֶסֶד, וְעַל כֵּן יַעֲקֹב הִשְׁלִים הַכֹּל מֵהַצַּד הַזֶּה וּמֵהַצַּד הַזֶּה. מִצַּד הָאֲחִיזָה אַבְרָהָם וְיִצְחָק לְחֶלְקָם לְמַעְלָה הִיא הַשְּׁלֵמוּת. מֵהַצַּד שֶׁנִּתַּן לָהֶם לְהוֹלִיד מִלְּמַטָּה לְמַעְלָה הִיא שְׁלֵמוּת. וְעַל כֵּן כָּתוּב (ישעיה מט) יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר. בּוֹ נֶאֶחְזוּ הַגְּוָנִים מִמַּעְלָה וּמִמַּטָּה."],[7,"","וְעַל כֵּן כָּתוּב כָּאן שִׁירָה, שֶׁכָּתוּב (שם ה) אָשִׁירָה נָּא לִידִידִי. שִׁירָה וַדַּאי. שֶׁזֶּה נִקְרָא לְהוֹלִיד זָכָר, שֶׁהֲרֵי נִקְרָא יָדִיד טֶרֶם שֶׁיָּבֹא לָעוֹלָם."],[8,"","וְיֵשׁ אוֹמְרִים, (זה) אָשִׁירָה נָּא לִידִידִי - זֶה אַבְרָהָם, שֶׁנֶּאֱמַר (ירמיה יא) מַה לִּידִידִי בְּבֵיתִי. וְאַבְרָהָם יָרַשׁ יְרֻשָּׁה שֶׁל נַחֲלַת הַחֵלֶק הַזֶּה. אֲבָל (על) מַה שֶּׁאָמַרְנוּ שֶׁזֶּה יִצְחָק - כָּךְ זֶה."],[9,"","שִׁירַת דּוֹדִי לְכַרְמוֹ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁנִּקְרָא דוֹדִי, שֶׁכָּתוּב (שיר ה) דּוֹדִי צַח וְאָדוֹם. יְדִידִי - אוֹחֵז בְּדוֹדִי, זָכָר, וּמִמֶּנּוּ נִטַּע כֶּרֵם, שֶׁכָּתוּב כֶּרֶם הָיָה לִידִידִי."],[10,"","בְּקֶֹרֶן בֶּן שָׁמֶן, מַה זֶּה בְּקֶרֶן בֶּן שָׁמֶן? אֶלָּא בַּמֶּה יָצָא הַכֶּרֶם הַזֶּה וּבַמֶּה נִטַּע? חָזַר וְאָמַר בְּקֶרֶן, מַה זֶּה קֶרֶן? שֶׁכָּתוּב (יהושע ו) בְּקֶרֶן הַיּוֹבֵל. בְּקֶרֶן הַיּוֹבֵל מַתְחִיל. וְהַקֶּרֶן הַזּוֹ אֲחוּזָה בְּאוֹתוֹ הַזָּכָר שֶׁנִּקְרָא בֶּן שָׁמֶן."],[11,"","מַה זֶּה בֶּן שָׁמֶן? כְּמוֹ שֶׁנֶּאֱמַר בֶּן חוֹרִים, וּשְׁנֵיהֶם דָּבָר אֶחָד. שֶׁמֶן, שֶׁמִּשָּׁם שׁוֹפֵעַ שֶׁמֶן וּגְדֻלָּה לְהַדְלִיק הַמְּאוֹרוֹת, וּמִשּׁוּם כָּךְ בֶּן שָׁמֶן. וְהַשֶּׁמֶן וְהַמִּשְׁחָה הַלָּלוּ שׁוֹפְעִים וְיוֹצְאִים וּמַדְלִיקִים מְאוֹרוֹת, עַד שֶׁנּוֹטֵל אוֹתוֹ וְכוֹנֵס אוֹתוֹ הַקֶּרֶן הַזֶּה. וְזֶה נִקְרָא קֶרֶן הַיּוֹבֵל. מִשּׁוּם כָּךְ אֵין מְשִׁיחַת הַמַּלְכוּת אֶלָּא בְּקֶרֶן, וְעַל כֵּן נִמְשְׁכָה מַלְכוּת דָּוִד, שֶׁנִּמְשַׁח בְּקֶרֶן וְנֶאֱחַז בּוֹ."]]],[["וַיְעַזְקֵהוּ, (ויסקלהו) כְּהַאי עִזְקָא דְּאִסְתַּחַר לְכָל סִטְרִין. וַיְסַקְלֵהוּ, דְּאַעֲדֵי מִנֵּיהּ וּמֵחוּלָקֵיהּ כָּל אִנּוּן רַבְרְבִין כָּל אִנּוּן תְּרֵיסִין כָּל אִנּוּן כִּתְרִין תַּתָּאִין, וְהוּא נָסִיב לֵיהּ לְהַאי (קרן) כֶּרְם לְחוּלָקֵיהּ, דִּכְתִיב, (דברים ל״ב:ט׳) כִּי חֵלֶק יְיָ עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ.","וַיִּטָּעֵהוּ שׂוֹרֵק, כְּמָא דְאַתְּ אָמֵר, (ירמיהו ב׳:כ״א) וְאָנֹכִי נְטַעְתִּיךְ שׂוֹרֵק, כֹּלֹּה זֶרַע אֱמֶת. כל\"ה כְּתִיב בְּה\"א. מִכָּאן שָׁארֵי אַבְרָהָם לְאוֹלָדָא לְעֵילָא, וּמֵהַאי נָפַק זֶרַע אֱמֶת. כֹּלֹּה זֶרַע אֱמֶת וַדַּאי, הַיְינוּ דִכְתִיב כֹּה יִהְיֶה זַרְעֶךָ, וְכֹלָּא חַד מִלָּה. זַכָּאָה חוּלַקְהוֹן דְּיִשְׂרָאֵל דְּיָרְתוֹי רוּתָא קַדִּישָׁא דָּא.","סוֹפֵיהּ דִּקְרָא (ישעיהו ה׳:ב׳) וַיִּבֶן מִגְדָּל בְּתוֹכוֹ. מַהוּ מִגְדָּל כְּמָא דְאַתְּ אָמֵר, (משלי י״ח:י׳) מִגְדַּל עֹז שֵׁם יְיָ, וְנִשְׂגָּב. בּוֹ יָרוּץ צַדִּיק וַדַּאי.","וְגַם יֶקֶב חָצֵב בּוֹ דָּא תַּרְעָא דְּצֶדֶק כְּמָא דְאַתְּ אָמֵר, (תהילים קי״ח:י״ט) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק. מַאי מַשְׁמַע, דְּכָל בַּר יִשְׂרָאֵל דְּאִתְגְּזַר, עֲיִּיל בְּתַרְוַויְיהוּ וְזָכֵי לְתַרְוַויְיהוּ.","וּמַאן דְּקָרִיב בְּרֵיהּ לְקָרְבָּנָא דָּא עֲיִּיל לֵיהּ בִּשְׁמָא קַדִּישָׁא, וְעַל אָת דָּא מִתְקַיְימִין שְׁמַיָא וְאַרְעָא דִּכְתִיב, (ירמיהו ל״ג:כ״ה) אִם לא בְרִיתִי יוֹמָם וָלַיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי. וְהַאי מָארֵיהּ דְּהִלּוּלָא דָא זָכָה לְכֹלָּא לְמֶחזֵי קוּדְשָׁא בְּרִיךְ הוּא אַנְפִּין בְּאַנְפִּין בְּהַאי יוֹמָא.","זַכָּאָה חוּלָקָנָא דְּזָכִינָא לְהַאי יוֹמָא וְזַכָּאָה חוּלָקָךְ עִמָּנָא, וְהַאי בְּרָא דְּאִתְיְילִיד לָךְ קָרֵינָא עֲלֵיהּ כָּל הַנִּקְרָא בִּשְׁמִי וְגו' יְצַרְתִּיו אַף עֲשִׂיתִיו. וּכְתִיב, (ישעיהו נ״ד:י״ג) וְכָל בָּנַיִךְ לִמּוּדֵי יְיָ וְגו'. אוֹזְפוּהָ לְרַבִּי אַבָּא תְּלַת מִילִין.","אָמְרוּ לֵיהּ הַאי מָרֵיהּ דְּהִלּוּלָא, אוּשְׁפִּיזָךְ, זָכָה לְכוּלֵי הַאי בְּגִין דְּקִיֵּים קִיּוּמָא דְמִצְוָה. אָמַר מַאי הִיא. אָמַר הַהוּא גַבְרָא, דְּבִיתָאי אִתַּת אָחִי הֲוַות, וּמִית בְּלָא בְּנִין, וְנָסִיבְנָא לָהּ, וְדָא הוּא בְּרָא קַדְמָאָה דְּהֲוָה לִי מִנָּהּ וְקָרֵינָא לֵיהּ בִּשְׁמָא דְּאָחִי דְּאִתְפַּטַּר. אָמַר לֵיהּ מִכָּאן וּלְהָלְאָה קְרֵי לֵיהּ אִידִי, וְהַיְינוּ אִידִי בַּר יַעֲקֹב. בָּרִיךְ לוֹן רַבִּי אַבָּא וְאָזִיל לְאָרְחֵיהּ.","כַּד אֲתָא סִדֵּר מִלִּין קַמֵּיהּ דְּרַבִּי אֶלְעָזָר, וְדָחִיל לְמֵימַר לְרַבִּי שִׁמְעוֹן. יוֹמָא חַד הֲוָה (קאים) קַמֵּיהּ דְּרַבִּי שִׁמְעוֹן. וְאָמַר רַבִּי שִׁמְעוֹן מַאי דִכְתִיב וַיִּפֹּל אַבְרָם עַל פָּנָיו וַיְדַבֵּר אִתּוֹ אֱלֹהִים לֵאמֹר אֲנִי הִנֵּה בְרִיתִי אִתָּךְ. מַשְׁמַע דְּעַד דְּלָא אִתְגְּזַר הֲוָה נְפִיל עַל אַנְפּוֹי וּמַלִּיל עִמֵּיהּ. בָּתַר דְּאִתְגְּזַר קָאִים בְּקִיּוּמֵיהּ וְלָא דָּחִיל. אֲנִי הִנֵּה בְרִיתִי אִתָּךְ דְּאַשְׁכַּח גַּרְמֵיהּ גָּזִיר.","אָמַר לֵיהּ רַבִּי אַבָּא אִי נִיחָא קַמֵּיהּ דְּמַר דְּלֵימָא קַמֵּיהּ מֵאִנּוּן מִלֵּי מַעֲלַיְיתָא דְּשְׁמַעְנָא בְהַאי, אָמַר לֵיהּ אֵימָא. אָמַר לֵיהּ דָּחִילְנָא דְּלָא יִתְעַנְשׁוּ עַל יְדָאי. אָמַר לֵיהּ חַס וְשָׁלוֹם (תהילים קי״ב:ז׳) מִשְׁמוּעָה רָעָה לא יִירָא נָכוֹן לִבּוֹ בָּטוּחַ בַּיְיָ. סָח לֵיהּ עוֹבָדָא וְסִדֵּר קַמֵיהּ כָּל אִנּוּן מִלִּין.","אָמַר לֵיהּ וְכִי כָּל הַנֵּי מִלֵּי מַעַלְיָיתָא הֲווּ טְמִירִין גַּבָּךְ וְלָא אֲמַרְתְּ לְהוּ. גּוֹזַרְנָא עֲלָךְ דְּכָל תְּלָתִין יוֹמִין אִלֵּין תִּלְעֵי וְתִנְשֵׁי. וְלָא כְּתִיב, (משלי ג׳:כ״ז) אַל תִּמְנַע טוֹב מִבְּעָלָיו בִּהְיוֹת לְאֵל יָדְךָ לַעֲשׂוֹת. וְכָךְ הֲוָה. אָמַר גּוֹזַרְנָא דִּבְאוֹרַיְיתָא דָּא יִגְלוּן לְבָבֶל (ויגלון בבבל) בֵּינֵי חַבְרַיָיא.","חָלַשׁ דַּעְתֵּיהּ דְּרַבִּי אַבָּא, יוֹמָא חַד חָמָא לֵיהּ רַבִּי שִׁמְעוֹן אָמַר לֵיהּ טוּפְסְרָא דְּלִבָּךְ בְּאַנְפָּךְ שְׁכִיחַ. אָמַר לֵיהּ לָא עַל דִּידִי הוּא אֶלָּא עַל דִּידְהוּ. אָמַר לֵיהּ חַס וְשָׁלוֹם דְּאִתְעַנָּשׁוּ, אֶלָּא בְּגִין דְּמִלִּין אִתְגַלְּיָין בֵּינַיְיהוּ כָּל כָּךְ. יִגְלוּן בֵּינֵי חַבְרַיְיא יִלְּפוּן אִנּוּן אָרְחִין (ואתבסמן) וְאִתְכַּסְיָין מִלִּין בְּגַוַויְיהוּ. דְהָא מִלִּין לָא אִתְגַּלְיָין אֶלָּא בֵּינָנָא דְּהָא קוּדְשָׁא בְּרִיךְ הוּא אִסְתְּכִים עִמָּנָא וְעַל יְדָנָא אִתְגַּלְּיָין מִלִּין.","אָמַר רַבִּי יוֹסֵי כְּתִיב, (ישעיהו נ״ח:ח׳) אָז יִבָּקַע כַּשַּׁחַר אוֹרֶךָ וְגו'. זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאַכְרְזָא עַל בְּנוֹי וְיֵימָא, אָז יִבָּקַע כַּשַּׁחַר אוֹרֶךָ וַאֲרֻכָתְךָ מְהֵרָה תִצְמָח וְהָלַךְ לְפָנְיךָ צִדְקֶךָ וּכְבוֹד יְיָ יַאַסְפֶךָ,"],[[0,"ויעזקהו, כהאי עזקא וכו':","ועתה מבאר הכתוב, איך יצא ונולד הכרם מקרן בן שמן, דהיינו על ידי עליתה אל הבינה. ואומר \u0003ויעזקהו\u0004 פירושו, שצמצם והגדיר אותו סביב סביב, כמו טבעת המקפת מכל הצדדים. ודורש, ויעזקהו, מלשון עזקא, שפירושו טבעת. פירוש הכתוב הולך ומביא תקונה של הכרם מקטנותה עד גדלותה שנעשה מפאת עליתה אל הבינה. והנה בתחילה, כשעלתה המלכות אל הבינה, נבחן, ש \u0003י'\u0004 נכנסה באור הבינה ונעשה אויר. ונתמעטה הבינה לו\"ק, כי אז נפלו ממנה ג' אתוון \u0003אל\"ה\u0004 לזו\"ן, והיא נשארה באתוון \u0003מ\"י.\u0004 ואז גם זו\"ן נתמעטו לו\"ק, (כנ\"ל ב\"א דף מ\"ג ד\"ה יהי) ועל מצב הזה אומר הכתוב, \u0003ויעזקהו,\u0004 שהקיפו מכל צד, דהיינו שצמצם אותה לו\"ק, מחמת ה \u0003י'\u0004 שנכנסה לאור הבינה ונעשה אויר. שפירושו קומת רוח, שהוא ו\"ק."],[0,"ויסקלהו, דאעדי וכו':","ויסקלהו, פירושו שהסיר מהכרם ומחלקו, כל אלו הגדולים וכל אלו השרים וכל הכתרים התחתונים. פירוש, ע\"י עלית המלכות לבינה, שנתמעטה אז לו\"ק בלי ראש, הסיר המאציל מן המלכות כל כחות הגדולים של הס\"א שהיו דבוקים במלכות. כי אחר שנתמעטה לו\"ק אין להם מה לינק ממנה, \u0003והוא נסיב ליה להאי כרם לחולקיה,\u0004 ואז הוא, דהיינו הבינה, לקח את הכרם לחלקו, דהיינו שנתדבקה בהבינה ונעשתה לחלק מן הבינה. שכתוב כי חלק ה' עמו יעקב חבל נחלתו. כי לפי שהמלכות נעשתה לחלק מן הבינה, נעשו גם ישראל לחלק מן הבינה. להיותם דבוקים בה."],[1,"ויטעהו שורק, כד\"א וכו':","הוא כמו שאתה אומר. ואנכי נטעתיך שורק, כלה זרע אמת \u0003כל\"ה\u0004 כתיב ב \u0003ה'\u0004 והוא כמו שהיה כתוב \u0003כל ה',\u0004 שהיא המלכות, \u0003זרע אמת.\u0004 פירוש. כי \u0003ויטעהו שורק,\u0004 היינו על ידי שהבינה חזרה והורידה ה \u0003י'\u0004 מאויר והחזירה אליה אתוון \u0003אל\"ה,\u0004 שאז יצא קו שמאל הנקרא \u0003שורק,\u0004 (כנ\"ל דף קמ\"ח ד\"ה אברהם) שה\"ס אור החכמה בלי חסדים כמ\"ש שם. והשפיעה הבינה מוחין הללו אל המלכות. ואז אומר הכתוב כל \u0003ה'\u0004 זרע אמת. כי אור החכמה שמאירה הבינה אל הכרם, נקרא אמת. וז\"ש מכאן \u0003שארי אברהם לאולדא לעילא,\u0004 ממצב הזה, דהיינו אור השורק, התחיל אברהם להוליד למעלה \u0003את יצחק,\u0004 (כנ\"ל באות תנ\"ז) כי הוא בחינת שורק הזה כנ\"ל. וז\"ש \u0003ומהאי נפק זרע אמת כל\"ה זרע אמת ודאי,\u0004 כי הארת החכמה נקרא אמת כנ\"ל. וז\"ש \u0003היינו דכתיב כ\"ה יהיה זרעך,\u0004 זה שכתוב \u0003כ\"ה\u0004 יהיה זרעך, כי קו שמאל הזה בעת שמאיר במלכות נקראת המלכות \u0003כ\"ה,\u0004 (כנ\"ל דף קמ\"ח ד\"ה אברהם) \u0003וכלא חד מלה,\u0004 והכל דבר אחד הוא, דהיינו, שורק, זרע אמת, לידת יצחק, כה יהיה זרעך, הם כולם דבר אחד, שהוא הארת קו שמאל מהבינה, כמבואר. \u0003זכאה חולקהון\u0004 וכו', אשרי חלקם של ישראל שיורשים ירושה גדולה הזו. כי מוחין אלו נקראים ירושה, להיותם מלמעלה מזו\"ן, וזו\"ן מקבלם מאו\"א בדרך ירושה. וכן ישראל. בדומה לבן היורש את אביו, שזוכה בו אע\"פ שאינו מעשה ידיו, כן זוכה זו\"ן במוחין דבינה, אע\"פ שמצד עצמו אין לו בהם כלום. וכן ישראל מזו\"ן."],[2,"סופיה דקרא ויבן מגדל בתוכו:","ושואל מהו מגדל. ואומר, כמש\"א. מגדל עז שם ה' בו ירוץ צדיק ונשגב, בו ירוץ צדיק ודאי. פירוש. כי מבחינת הארת השורק אין המלכות יכולה להתקיים, להיותה חכמה בלי חסדים. ובנין המגדל פירושו התלבשות החכמה בחסדים, שאז \u0003ירוץ צדיק ונשגב.\u0004 ולא מקודם לכן."],[3,"וגם יקב חצב בו:","זהו שער צדק כמש\"א, פתחו לי שערי צדק. שז\"ס המסך דחירק שעליו נמשך קומת החסדים וקו אמצעי. שלולא זה לא היה החכמה מאירה. ומשום זה יש בחסדים הללו גם התכללות החכמה. \u0003מאי משמע,\u0004 ושואל, מהו המשמעות של הכתוב פתחו לי שערי צדק. ואומר, שכל אחד מישראל שנמול נכנס בשניהם, וזוכה בשניהם. דהיינו במגדל ויקב. שמגדל פירושו התכללות חכמה בחסדים. ויקב פירושו התכללות חסדים בחכמה. לכן בקש דוד פתחו לי שערי צדק, לזכות בשניהם."],[4,"ומאן דקריב בריה וכו':","ומי שהקריב את בנו לקרבן הזה. של ברית מילה הוא מכניסו בשם הקדוש. ועל אות הזה מתקיימים שמים וארץ. שכתוב אם לא בריתי וגו'. ובעל שמחה הזה זכה לכל, וזכה לראות את הקב\"ה פנים בפנים ביום הזה."],[5,"זכאה חולקנא וכו':","אשרי חלקנו שזכינו ליום הזה. ואשרי חלקך עמנו. ובן הזה הנולד לך קורא אני עליו כל הנקרא בשמי וגו' יצרתיו אף עשיתיו. וכתוב וכל בניך למודי ה'. וליוה את ר' אבא שלשה מילים."],[6,"אמרו ליה האי:","אמרו לו, לר' אבא, בעל השמחה הזה, בעל המלון שלך, זכה לכל זהו משום שעשה עשיה של מצוה. אמר, מה הוא המצוה. אמר אותו האיש, בעל המלון, אשתי, אשת אחי היתה, שמת בלא בנים, ונשאתי אותה, וזה הוא בן הראשון שהיה לי ממנה, וקראתי שמו על שם אחי שנפטר. אמר לו, מכאן והלאה תקרא אותו \u0003אידי.\u0004 והוא, אידי בן יעקב. ברך אותם ר' אבא והלך לדרכו."],[7,"כד אתא וכו':","כשבא למקומו, סידר הדברים לפני ר' אלעזר. והיה מתירא לומר אותם לפני ר\"ש. שלא יענישם על גילוי הסודות, יום אחד היה לפני ר\"ש, ואר\"ש, מה זה שכתוב, ויפול אברהם על פניו וידבר וגו', משמע, שכל עוד שלא נמול היה נופל על פניו ואז דבר עמו. ואחר שנמול עמד על עמדו, ולא היה מפחד. אני הנה בריתי אתך, היינו שמצא את עצמו נמול, כי דבר ה' פעל עליו ונמול."],[8,"אמר ליה ר' אבא:","אמר לו ר\"א, אם טוב בעיני אדוני, לומר לפניו מאלו דברים הטובים ששמעתי בענין זה. אמר לו אמור. אמר לו אני מפחד שלא יענשו על ידי. אמר לו משמועה רעה לא יירא וגו' ספר לו המעשה, וסידר לפניו כל הדברים."],[9,"אמר ליה, וכי כל וכו':","אמר לו ר\"ש, וכי כל אלו דברים הטובים היו נסתרים אצלך ולא אמרת אותם, אני גוזר עליך, שבכל שלשים יום הללו, תלמוד ותכף תשכח, וכי לא כתוב, אל תמנע טוב מבעליו וגו'. וכן היה, שלמד ושכח. אמר, אני גוזר, שעם תורתם זו, יגלו, היינו בעל האכסנא שלו וחביריו, לבבל בין החברים אשר שם."],[10,"חלש דעתיה וכו':","נחלש דעתו של ר' אבא. יום אחד ראה אותו ר' שמעון. אמר לו, העתקה מלבך נמצא בפניך. אמר לו ר' אבא, לא על עצמי אני מצטער אלא עליהם, שהענישם לגלות לבבל."],[10,"אמר ליה ח\"ו וכו':","אמר לו ר\"ש, חס ושלום שנענשו, אלא משום שהסודות נתגלו ביניהם כל כך, גזרתי עליהם, שיגלו בין החברים שבבבל, וילמדו הדרכים שלהם והסודות יתכסו ביניהם. כי הסודות לא יתגלו אלא ביננו, כי הקב\"ה הסכים עמנו, ועל ידינו יתגלו הדברים."],[11,"אמר ר' יוסי וכו':","אר\"י, כתוב אז יבקע משחר אורך וגו' עתיד הקב\"ה להכריז על בניו, ויאמר, אז יבקע כשחר אורך וארוכתך מהרה תצמח וגו'."]],[[0,"","וַיְעַזְּקֵהוּ וַיְסַלְּקֵהוּ - כַּטַּבַּעַת הַזּוֹ שֶׁמַּקִּיפָה אֶת כָּל הַצְּדָדִים. וַיְסַקְּלֵהוּ - שֶׁהֵסִיר מִמֶּנּוּ וּמֵחֶלְקוֹ אֶת כָּל אוֹתָם שָׂרִים גְּדוֹלִים, כָּל אוֹתָם הַמָּגִנִּים, כָּל אוֹתָם הַכְּתָרִים הַתַּחְתּוֹנִים. וְהוּא לָקַח לוֹ אֶת (הקרן) הַכֶּרֶם הַזֶּה לְחֶלְקוֹ, שֶׁכָּתוּב (דברים לב) כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ."],[1,"","וַיִּטָעֵהוּ שּׁרֵק - כְּמוֹ שֶׁנֶּאֱמַר (ירמיה ב) וְאָנֹכִי נְטַעְתִּיךְ שׂוֹרֵק כֻּלֹּה זֶרַע אֱמֶת. כֻּלֹּ\"ה כָּתוּב בְּהֵ\"א. מִכָּאן הִתְחִיל אַבְרָהָם לְהוֹלִיד לְמַעְלָה, וּמִזֶּה יָצָא זֶרַע אֱמֶת. כֻּלֹּה זֶרַע אֱמֶת וַדַּאי. הַיְנוּ שֶׁכָּתוּב כֹּה יִהְיֶה זַרְעֶךְ, וְהַכֹּל דָּבָר אֶחָד. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁיָּרְשׁוּ אֶת הַיְרֻשָּׁה הַקְּדוֹשָׁה הַזּוֹ."],[2,"","סוֹף הַפָּסוּק (ישעיה ה) - וַיִּבֶן מִגְדָּל בְּתוֹכוֹ. מַה זֶּה מִגְדָּל? כְּמוֹ שֶׁנֶּאֱמַר (משלי יח) מִגְדַּל עֹז שֵׁם ה' בּוֹ יָרוּץ צַדִּיק וְנִשְׂגָּב. בּוֹ יָרוּץ צַדִּיק וַדַּאי."],[3,"","וְגַם יֶקֶב חָצֵב בּוֹ - זֶה הַשַּׁעַר שֶׁל הַצֶּדֶק, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קיח) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק. מַה מַּשְׁמִיעֵנוּ? שֶׁכָּל בֶּן יִשְׂרָאֵל שֶׁנִּמּוֹל, נִכְנָס בִּשְׁנֵיהֶם וְזוֹכֶה לִשְׁנֵיהֶם."],[4,"","וּמִי שֶׁמַּקְרִיב אֶת בְּנוֹ לַקָּרְבָּן הַזֶּה, מַכְנִיס אוֹתוֹ לַשֵּׁם הַקָּדוֹשׁ. וְעַל הָאוֹת הַזּוֹ מִתְקַיְּמִים שָׁמַיִם וָאָרֶץ, שֶׁכָּתוּב (ירמיה לג) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי. וּבַעַל הַהִלּוּלָא הַזֶּה זָכָה לַכֹּל, לִרְאוֹת אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא פָּנִים בְּפָנִים בַּיּוֹם הַזֶּה."],[5,"","אַשְׁרֵי חֶלְקֵנוּ שֶׁזָּכִינוּ לַיּוֹם הַזֶּה, וְאַשְׁרֵי חֶלְקְךְ עִמָּנוּ. וְהַבֵּן הַזֶּה שֶׁנּוֹלַד לְךְ, קָרָאנוּ עָלָיו (ישעיה מג) כֹּל הַנִּקְרָא בִשְׁמִי וְגוֹ', יְצַרְתִּיו אַף עֲשִׂיתִיו. וְכָתוּב (שם נד) וְכָל בָּנַיִךְ לִמּוּדֵי ה' וְגוֹ'. לִוּוּ אֶת רַבִּי אַבָּא שְׁלֹשָׁה מִילִין."],[6,"","אָמְרוּ לוֹ, בַּעַל הַהִלּוּלָא הַזֶּה הַמְאָרֵחַ שֶׁלְּךְ זָכָה לְכָל זֶה מִשּׁוּם שֶׁקִּיֵּם אֶת קִיּוּם הַמִּצְוָה. אָמַר, מַה הִיא? אָמַר אוֹתוֹ הָאִישׁ, אִשְׁתִּי, אֵשֶׁת אָחִי הָיְתָה, וְהוּא מֵת בְּלִי בָנִים, וְנָשָׂאתִי אוֹתָהּ, וְזֶה הַבֵּן הָרִאשׁוֹן שֶׁהָיָה לִי מִמֶּנָּה, וְקָרָאתִי לוֹ בְּשֵׁם אָחִי שֶׁנִּפְטַר. אָמַר לוֹ, מִכָּאן וָהָלְאָה קְרָא לוֹ אִידִי, וְזֶה הוּא אִידִי בַּר יַעֲקֹב. בֵּרַךְ אוֹתָם רַבִּי אַבָּא וְהָלַךְ לְדַרְכּוֹ."],[7,"","כַּאֲשֶׁר בָּא, סִדֵּר הַדְּבָרִים לִפְנֵי רַבִּי אֶלְעָזָר, וּפָחַד לוֹמַר לְרַבִּי שִׁמְעוֹן. יוֹם אֶחָד הָיָה לִפְנֵי רַבִּי שִׁמְעוֹן, וְאָמַר רַבִּי שִׁמְעוֹן, מַהוּ שֶׁכָּתוּב וַיִּפֹּל אַבְרָם עַל פָּנָיו וַיְדַבֵּר אִתּוֹ אֱלֹהִים לֵאמֹר אֲנִי הִנֵּה בְרִיתִי אִתָּךְ? מַשְׁמָע שֶׁעַד שֶׁלֹּא נִמּוֹל, הָיָה נוֹפֵל עַל פָּנָיו וּמְדַבֵּר עִמּוֹ. אַחַר שֶׁנִּמּוֹל, עָמַד בְּקִיּוּמוֹ וְלֹא פָחַד. אֲנִי הִנֵּה בְרִיתִי אִתָּךְ, שֶׁמָּצָא אֶת עַצְמוֹ מָהוּל."],[8,"","אָמַר לוֹ רַבִּי אַבָּא, אִם נוֹחַ לִפְנֵי מַר שֶׁאֹמַר לְפָנָיו מֵאוֹתָם הַדְּבָרִים הַמְעֻלִּים שֶׁשָּׁמַעְתִּי בָּזֶה? אָמַר לוֹ, אֱמֹר. אָמַר לוֹ, אֲנִי פוֹחֵד שֶׁלֹּא יֵעָנְשׁוּ עַל יָדִי. אָמַר לוֹ, חַס וְשָׁלוֹם, (תהלים קיב) מִשְּׁמוּעָה רָעָה לֹא יִירָא נָכוֹן לִבִּי בָּטוּחַ בַּה'. סִפֵּר לוֹ הַמַּעֲשֶׂה, וְסִדֵּר לְפָנָיו אֶת כָּל אוֹתָם הַדְּבָרִים."],[9,"","אָמַר לוֹ, וְכִי כָּל הַדְּבָרִים הַמְעֻלִּים הַלָּלוּ הָיוּ טְמוּנִים אֶצְלְךְ וְלֹא אָמַרְתָּ אוֹתָם? גּוֹזְרַנִי עָלֶיךְ שֶׁכָּל שְׁלֹשִׁים הַיָּמִים הַלָּלוּ תִּלְמַד וְתִשְׁכַּח, וְלֹא כָתוּב (משלי ג) אַל תִּמְנַע טוֹב מִבְּעָלָיו בִּהְיוֹת לְאֵל יָדְךְ לַעֲשׂוֹת? וְכָךְ הָיָה. אָמַר, גּוֹזְרַנִי שֶׁבַּתּוֹרָה הַזּוֹ יִגְלוּ לְבָּבֶל (ויגלו בבבל) בֵּין הַחֲבֵרִים."],[10,"","חָלְשָׁה דַעְתּוֹ שֶׁל רַבִּי אַבָּא. יוֹם אֶחָד רָאָה אוֹתוֹ רַבִּי שִׁמְעוֹן, אָמַר לוֹ, דְּפוּס לִבְּךְ מָצוּי בְּפָנֶיךְ. אָמַר לוֹ, לֹא עַל שֶׁלִּי הוּא, אֶלָּא עַל שֶׁלָּהֶם! אָמַר לוֹ, חַס וְשָׁלוֹם שֶׁנֶּעֶנְשׁוּ, אֶלָּא מִשּׁוּם שֶׁדְּבָרִים הִתְגַּלּוּ בֵינֵיהֶם כָּל כָּךְ. יִגְלוּ לְבֵין הַחֲבֵרִים, וְיִלְמְדוּ אוֹתָם הַדְּרָכִים, (ומתמתקים) וְיִתְכַּסּוּ הַדְּבָרִים בְּתוֹכָם, שֶׁהֲרֵי אֵין הַדְּבָרִים מִתְגַּלִּים אֶלָּא בֵּינֵינוּ, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא הִסְכִּים עִמָּנוּ, וְעַל יָדֵינוּ מִתְגַּלִּים הַדְּבָרִים."],[11,"","אָמַר רַבִּי יוֹסֵי, כָּתוּב (ישעיה נח) אָז יִבָּקַע כַּשַּׁחַר אוֹרֶךְ וְגוֹ'. עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַכְרִיז עַל בָּנָיו וְיֹאמַר, אָז יִבָּקַע כַּשַּׁחַר אוֹרֶךְ וַאֲרֻכָתְךְ מְהֵרָה תִצְמָח וְהָלַךְ לְפָנֶיךְ צִדְקֶךְ כְּבוֹד ה' יַאַסְפֶךְ."]]]]};
